import { createPersistenceManager } from './persistenceManager';
import { STORAGE_KEYS } from '../constants/storageKeys';

export const POLICY_ACK_VERSION = 1;

export const POLICY_ACK_CHANGE_EVENT = 'sportwizard:policy-ack-changed';

export const POLICY_ACK_DEFAULTS = Object.freeze({
  acknowledgedDate: null,
  version: POLICY_ACK_VERSION,
});

export const policyAckPersistence = createPersistenceManager(
  STORAGE_KEYS.POLICY_ACKNOWLEDGMENT,
  { ...POLICY_ACK_DEFAULTS }
);

export function loadPolicyAck() {
  const stored = policyAckPersistence.loadState();
  if (!stored || stored.version !== POLICY_ACK_VERSION) {
    return { ...POLICY_ACK_DEFAULTS };
  }
  return stored;
}

// True when the user has already acknowledged the current policy date.
export function isPolicyAcknowledged(currentDate) {
  return loadPolicyAck().acknowledgedDate === currentDate;
}

function notifyPolicyAckChanged() {
  // The `storage` event only fires in OTHER tabs, so same-tab hook instances
  // need a separate signal to stay in sync after a write.
  if (typeof window === 'undefined') return;
  window.dispatchEvent(new Event(POLICY_ACK_CHANGE_EVENT));
}

export function savePolicyAck(acknowledgedDate) {
  const result = policyAckPersistence.saveState({
    acknowledgedDate,
    version: POLICY_ACK_VERSION,
  });
  notifyPolicyAckChanged();
  return result;
}

export function clearPolicyAck() {
  const result = policyAckPersistence.clearState();
  notifyPolicyAckChanged();
  return result;
}
