import { useState, useCallback, useRef } from 'react';
import { useTranslation } from 'react-i18next';
import { useAuth } from '../contexts/AuthContext';
import { useTeam } from '../contexts/TeamContext';
import { useTeamSwitchAction } from './useTeamSwitchAction';
import { useToast } from '../contexts/ToastContext';
import { VIEWS } from '../constants/viewConstants';
import { shouldProcessInvitation, retrievePendingInvitation, hasPendingInvitation } from '../utils/invitationUtils';

/**
 * Custom hook for processing invitation acceptance workflow
 * 
 * Handles:
 * - Invitation acceptance API calls
 * - Processing state management
 * - Navigation after successful acceptance
 * - Pending invitation processing after sign-in
 * - Success/error handling
 * 
 * @param {Object} options Configuration options
 * @param {Function} options.onSuccess Callback when invitation is successfully processed
 * @param {Function} options.onNavigate Function to navigate to views
 * @param {Function} options.clearInvitationParams Function to clear invitation parameters
 * @returns {Object} Invitation processing state and handlers
 */
export function useInvitationProcessing({
  onSuccess = () => {},
  onNavigate = () => {},
  clearInvitationParams = () => {}
}) {
  const { t } = useTranslation('team');
  const { user } = useAuth();
  const {
    currentTeam,
    acceptTeamInvitation,
    getUserTeams,
    getClubMemberships,
    switchCurrentTeam,
    clearTeamSelectionPrompt,
  } = useTeam();
  const { confirming: isSwitchingTeam, runSwitch } = useTeamSwitchAction();
  const { showWarning } = useToast();
  const isProcessingRef = useRef(false);
  const [isProcessing, setIsProcessing] = useState(false);
  // When set, the user already had an active team and must choose to switch or stay.
  const [pendingTeamChoice, setPendingTeamChoice] = useState(null);

  // Handle invitation acceptance
  const handleInvitationAcceptance = useCallback(async (params) => {
    if (!params.invitationId) {
      console.error('No invitation ID provided');
      return;
    }

    if (isProcessingRef.current) {
      console.log('Invitation already being processed, skipping');
      return;
    }

    // Capture whether the user already has an active team before refreshing.
    const hadActiveTeam = Boolean(currentTeam);
    const previousTeam = currentTeam;

    try {
      isProcessingRef.current = true;
      setIsProcessing(true);

      const result = await acceptTeamInvitation(params.invitationId);

      if (result.success) {
        // Clear URL parameters
        clearInvitationParams();

        // Trigger success callback with result
        onSuccess(result.message || 'Welcome to the team!');

        const newTeamId = result.data?.team_id;
        if (!newTeamId) {
          console.error('acceptTeamInvitation returned success without data.team_id; team switch will be skipped');
          showWarning(t('teamSelection.noTeamIdWarning'));
          // Continue: getUserTeams still runs to refresh the member list even without a switch target.
        }
        try {
          const refreshedTeams = await getUserTeams();
          const newTeam = refreshedTeams?.find(team => team.id === newTeamId) ?? null;
          if (newTeam) {
            try {
              await getClubMemberships();
            } catch (e) {
              console.error('Error refreshing club memberships:', e);
            }
            if (hadActiveTeam) {
              // Already have an active team: offer a switch-or-stay choice, no auto-switch.
              setPendingTeamChoice({ newTeam, previousTeam });
            } else {
              // No prior active team: explicitly switch so multi-team users aren't
              // shown the generic TeamSelectionModal instead.
              try {
                await switchCurrentTeam(newTeam.id, refreshedTeams);
              } catch (switchError) {
                console.error('Error switching to newly joined team:', switchError);
                showWarning(t('teamSelection.error'));
              }
            }
          } else if (newTeamId) {
            console.error('Could not find newly joined team in refreshed list; skipping team switch', { newTeamId });
          }
        } catch (refreshError) {
          console.error('Error refreshing team data:', refreshError);
        }

        // Navigate to team management immediately, even when hadActiveTeam=true and
        // the switch-or-stay modal is still open. The modal renders on top of whatever
        // view is active; the user lands on Team Management regardless of their choice
        // (switch or stay). Deferring navigation would require threading onNavigate
        // through confirmTeamSwitch/dismissTeamChoice with no UX benefit.
        onNavigate(VIEWS.TEAM_MANAGEMENT);

        return result;
      } else {
        console.error('Failed to accept invitation:', result.error);
        return result;
      }
    } catch (error) {
      console.error('Error processing invitation:', error);
      return { success: false, error: error.message };
    } finally {
      isProcessingRef.current = false;
      setIsProcessing(false);
    }
  }, [t, currentTeam, acceptTeamInvitation, getUserTeams, getClubMemberships, switchCurrentTeam, showWarning, onSuccess, onNavigate, clearInvitationParams]);

  // Resolve the switch-or-stay choice from the URL invite flow via the shared action.
  const confirmTeamSwitch = useCallback(() => {
    if (!pendingTeamChoice) return undefined;
    return runSwitch(pendingTeamChoice.newTeam.id, () => setPendingTeamChoice(null));
  }, [pendingTeamChoice, runSwitch]);

  const dismissTeamChoice = useCallback(() => {
    setPendingTeamChoice(null);
    // User chose to stay: mark the prompt dismissed so the post-invite userTeams
    // refresh doesn't re-fire the generic TeamSelectionModal.
    clearTeamSelectionPrompt();
  }, [clearTeamSelectionPrompt]);

  // Handle invitation processed callback from InvitationWelcome component
  const handleInvitationProcessed = useCallback((result) => {
    if (result?.success) {
      // Clear URL parameters
      clearInvitationParams();

      // Trigger success callback
      onSuccess(result.message || 'Welcome to the team!');

      // Navigate to team management view
      onNavigate(VIEWS.TEAM_MANAGEMENT);
    }
  }, [onSuccess, onNavigate, clearInvitationParams]);

  // Process invitation when user becomes authenticated (but only if they don't need password setup)
  const processInvitationForUser = useCallback((invitationParams) => {
    if (user && invitationParams && shouldProcessInvitation(user, invitationParams)) {
      console.log('User is ready to process invitation');
      handleInvitationAcceptance(invitationParams);
    }
  }, [user, handleInvitationAcceptance]);

  // Check for pending invitation after user signs in (for users who completed password setup)
  const processPendingInvitationForUser = useCallback((invitationParams) => {
    if (user && !invitationParams && hasPendingInvitation()) {
      console.log('User signed in, checking for pending invitation...');
      const pendingInvitation = retrievePendingInvitation();

      if (pendingInvitation && pendingInvitation.invitationId) {
        console.log('Processing pending invitation:', pendingInvitation);

        // Process the stored invitation
        handleInvitationAcceptance({ invitationId: pendingInvitation.invitationId });

        // Show success message with team context
        const teamContext = pendingInvitation.teamName ?
          ` Welcome to ${pendingInvitation.teamName}!` :
          ' Welcome to the team!';
        const message = `Successfully joined as ${pendingInvitation.role || 'member'}.${teamContext}`;
        
        onSuccess(message);
      }
    }
  }, [user, handleInvitationAcceptance, onSuccess]);

  return {
    isProcessing,
    pendingTeamChoice,
    isSwitchingTeam,
    confirmTeamSwitch,
    dismissTeamChoice,
    handleInvitationAcceptance,
    handleInvitationProcessed,
    processInvitationForUser,
    processPendingInvitationForUser
  };
}
