import { useCallback, useEffect, useRef } from 'react';

/**
 * Custom hook to intercept the browser back button for navigation handling.
 *
 * Supports both modal management and view navigation interception. When the
 * back button is pressed, the most recently registered navigation handler is
 * executed instead of allowing the browser to navigate.
 *
 * Single source of truth
 * ----------------------
 * The browser exposes exactly one history and one `popstate` stream, so this
 * hook is backed by a SINGLE shared handler stack and a SINGLE `popstate`
 * listener, regardless of how many components call it. Every caller pushes onto
 * the same stack, so back navigation is true LIFO across the whole app: the
 * innermost / most recently opened thing (a match detail, a modal, …) is closed
 * first, and only one handler fires per back press.
 *
 * Each call site only ever removes the handlers IT registered: `pushNavigationState`
 * records the id it created on a per-instance list, and `removeFromNavigationStack`
 * / `popNavigationState` remove that instance's most recent still-registered id.
 *
 * Usage Examples:
 *
 * // For modals:
 * const { pushNavigationState } = useBrowserBackIntercept();
 * pushNavigationState(() => setModalOpen(false));
 *
 * // For view navigation:
 * const { pushNavigationState } = useBrowserBackIntercept();
 * pushNavigationState(() => navigateToParentView());
 *
 * // Global navigation handling (fallback when the stack is empty):
 * const { pushNavigationState } = useBrowserBackIntercept(globalHandler);
 */

// ---------------------------------------------------------------------------
// Shared singleton state (one per app, not one per hook instance)
// ---------------------------------------------------------------------------
let sharedStack = []; // [{ id, navigationHandler, handlerName, registeredAt }]
let nextHandlerId = 1;
let globalNavigationHandlerRef = null; // current fallback handler (App-level)
let baseStateInitialized = false;
let listenerInstalled = false;

function ensureInterceptInstalled() {
  if (typeof window === 'undefined') {
    return;
  }

  // Initialize a base history state exactly once.
  if (!baseStateInitialized) {
    window.history.replaceState({ navigationLevel: 0 }, '', window.location.href);
    baseStateInitialized = true;
  }

  // Install the single popstate listener exactly once. It lives for the app
  // lifetime, so it is intentionally never removed on a consumer unmount.
  if (!listenerInstalled) {
    window.addEventListener('popstate', handleSharedPopState);
    listenerInstalled = true;
  }
}

function handleSharedPopState(event) {
  // If we have navigation handlers registered, execute the topmost handler
  // instead of navigating.
  if (sharedStack.length > 0) {
    if (event && typeof event.preventDefault === 'function') {
      event.preventDefault();
    }

    const topHandler = sharedStack.pop();

    if (topHandler && typeof topHandler.navigationHandler === 'function') {
      topHandler.navigationHandler();
    }

    // If handlers remain, push a new state so the next back press is intercepted.
    if (sharedStack.length > 0) {
      window.history.pushState(
        { navigationLevel: sharedStack.length },
        '',
        window.location.href
      );
    }
  } else if (typeof globalNavigationHandlerRef === 'function') {
    // No handlers registered: defer to the global navigation handler.
    globalNavigationHandlerRef();
  }
  // Otherwise let the browser handle the back navigation normally.
}

function removeEntriesByIds(ids) {
  if (!ids || ids.length === 0 || sharedStack.length === 0) {
    return;
  }
  const idSet = new Set(ids);
  sharedStack = sharedStack.filter((entry) => !idSet.has(entry.id));
}

// Return (and forget) this instance's most recent id that is still on the shared
// stack. Trailing ids already consumed by a popstate are pruned and skipped.
function takeLatestLiveOwnId(ownIds) {
  while (ownIds.length > 0) {
    const id = ownIds.pop();
    if (sharedStack.some((entry) => entry.id === id)) {
      return id;
    }
  }
  return null;
}

/**
 * Test-only hook to reset the shared singleton state between test cases.
 * Never call this from production code.
 */
export function __resetBrowserBackInterceptForTests() {
  sharedStack = [];
  nextHandlerId = 1;
  globalNavigationHandlerRef = null;
  baseStateInitialized = false;
  listenerInstalled = false;
}

export function useBrowserBackIntercept(globalNavigationHandler) {
  // Ids this particular consumer has pushed onto the shared stack.
  const ownIdsRef = useRef([]);

  // Register/refresh the global fallback handler. Only callers that pass one
  // (the App shell) participate; the latest registrant wins and clears itself
  // on unmount/change.
  useEffect(() => {
    if (typeof globalNavigationHandler !== 'function') {
      return undefined;
    }

    globalNavigationHandlerRef = globalNavigationHandler;

    return () => {
      if (globalNavigationHandlerRef === globalNavigationHandler) {
        globalNavigationHandlerRef = null;
      }
    };
  }, [globalNavigationHandler]);

  // Install the shared base state + listener, and clean up this consumer's
  // remaining handlers on unmount (the shared listener itself persists).
  useEffect(() => {
    ensureInterceptInstalled();

    const ownIds = ownIdsRef.current;
    return () => {
      if (ownIds.length > 0) {
        removeEntriesByIds(ownIds);
        ownIds.length = 0;
      }
    };
  }, []);

  const pushNavigationState = useCallback((navigationCallback, handlerName = 'unnamed') => {
    if (typeof navigationCallback !== 'function') {
      console.warn('pushNavigationState requires a function to handle navigation');
      return;
    }

    ensureInterceptInstalled();

    const id = nextHandlerId++;
    sharedStack.push({
      id,
      navigationHandler: navigationCallback,
      handlerName,
      registeredAt: Date.now()
    });
    ownIdsRef.current.push(id);

    // Push a new browser history state so the back button is intercepted.
    window.history.pushState(
      { navigationLevel: sharedStack.length },
      '',
      window.location.href
    );
  }, []);

  const popNavigationState = useCallback(() => {
    const id = takeLatestLiveOwnId(ownIdsRef.current);
    if (id == null) {
      return;
    }

    removeEntriesByIds([id]);

    // Only go back if we're not already at the base level.
    // Support both new navigationLevel and old modalLevel for compatibility.
    const currentLevel = window.history.state?.navigationLevel || window.history.state?.modalLevel || 0;
    if (currentLevel > 0) {
      window.history.back();
    }
  }, []);

  const removeFromNavigationStack = useCallback(() => {
    // Remove this consumer's most recent handler without triggering browser navigation.
    const id = takeLatestLiveOwnId(ownIdsRef.current);
    if (id != null) {
      removeEntriesByIds([id]);
    }
  }, []);

  const clearNavigationStack = useCallback(() => {
    sharedStack = [];
    ownIdsRef.current.length = 0;
    // Go back to base state if we're in a navigation state.
    // Support both new navigationLevel and old modalLevel for compatibility.
    const currentLevel = window.history.state?.navigationLevel || window.history.state?.modalLevel || 0;
    if (currentLevel > 0) {
      window.history.go(-currentLevel);
    }
  }, []);

  const hasActiveNavigationHandlers = useCallback(() => sharedStack.length > 0, []);

  return {
    // Navigation-generic methods
    pushNavigationState,
    popNavigationState,
    removeFromNavigationStack,
    clearNavigationStack,
    hasActiveNavigationHandlers
  };
}
