import React from 'react';
import PropTypes from 'prop-types';
import { useTranslation } from 'react-i18next';
import { getInitials } from '../../utils/formatUtils';
import { Tooltip } from './Tooltip';

const SIZE_CLASSES = {
  sm: 'w-5 h-5 text-[9px]',
  md: 'w-7 h-7 text-xs'
};

export function CoachChip({ name, size = 'md' }) {
  const { t } = useTranslation('common');
  const label = name || t('roles.coach');

  return (
    <Tooltip
      content={<span className="text-xs text-slate-100 font-medium">{label}</span>}
      trigger="hover"
      position="top"
      contentClassName="!min-w-0 !p-2 whitespace-nowrap"
    >
      <span
        className={`inline-flex items-center justify-center rounded-full bg-sky-600/20 text-sky-300 font-medium ${SIZE_CLASSES[size] || SIZE_CLASSES.md}`}
        aria-label={label}
      >
        {getInitials(name)}
      </span>
    </Tooltip>
  );
}

CoachChip.propTypes = {
  name: PropTypes.string,
  size: PropTypes.oneOf(['sm', 'md']),
};
