/**
 * Pure game state logic functions
 * These functions take current state as input and return new state as output
 * They have no side effects and can be used for previews, undo calculations, etc.
 */

import { createSubstitutionManager } from './substitutionManager';
import { findPlayerById } from '../../utils/playerUtils';
import { getCurrentTimestamp } from '../../utils/timeUtils';
import { PLAYER_ROLES, PLAYER_STATUS } from '../../constants/playerConstants';
import { normalizeRole } from '../../constants/roleConstants';
import { POSITION_KEYS } from '../../constants/positionConstants';
import { handleRoleChange } from './substitutionManager';
import { updatePlayerTimeStats, resetPlayerStintTimer } from '../time/stintManager';
import { createRotationQueue } from '../queue/rotationQueue';
import { createPlayerLookupFunction } from '../../utils/playerUtils';
import { getPositionRole } from './positionUtils';
import { getValidPositions, supportsInactiveUsers, hasMultipleSubstitutes, getBottomSubstitutePosition } from '../../constants/gameModes';
import { getFormationDefinition } from '../../utils/formationConfigUtils';
import { handleError, ERROR_CATEGORIES } from '../../utils/errorHandler';
import { isSameRoleMode, getFixedGroupFieldPositions } from '../../constants/teamConfiguration';

/**
 * Helper to get mode definition from team config object
 * Uses centralized formation configuration utilities
 */
const getDefinitionForGameLogic = (teamConfig, selectedFormation = null) => {
  if (!teamConfig || typeof teamConfig !== 'object') {
    return null;
  }
  
  // For team config objects, use formation definition utility
  return getFormationDefinition(teamConfig, selectedFormation);
};

/**
 * Calculate nextToSubOutIds from roleGroups.
 * Each role group with >= 2 players contributes its queue[0] (the field player next off).
 * IDs are sorted by substitutePosition to ensure stable ordering.
 */
export const calculateNextToSubOutIds = (roleGroups) => {
  if (!roleGroups) return { nextToSubOutIds: null, nextPlayerIdToSubOut: null };
  const ids = Object.values(roleGroups)
    .filter(g => g.queue && g.queue.length >= 2 && g.substitutePosition && g.isScheduled !== false && g.hasInactiveSub !== true)
    .map(g => g.queue[0]);
  const subPosForPlayer = {};
  for (const group of Object.values(roleGroups)) {
    if (group.queue?.[0] && group.substitutePosition) {
      subPosForPlayer[group.queue[0]] = group.substitutePosition;
    }
  }
  ids.sort((a, b) => (subPosForPlayer[a] || '').localeCompare(subPosForPlayer[b] || ''));
  return { nextToSubOutIds: ids, nextPlayerIdToSubOut: ids[0] || null };
};

/**
 * Reorder substitute positions so scheduled groups occupy top slots.
 * Called after cross-group scheduling changes to keep visual indicators correct:
 * getIndicatorProps highlights substitutePositions.slice(0, substitutionCount),
 * so scheduled groups must be at the top positions.
 *
 * @param {Object} roleGroups - Role groups with isScheduled flags and substitutePosition
 * @param {Object} formation - Current formation mapping
 * @param {Array} allPlayers - All player objects
 * @returns {{ newFormation: Object, newAllPlayers: Array } | null} Updated formation and players, or null if no change needed
 */
export const reorderSubstitutePositionsForSchedule = (roleGroups, formation, allPlayers) => {
  if (!roleGroups) return null;

  // Gather role groups that have a substitutePosition
  const groupsWithSubPos = Object.entries(roleGroups)
    .filter(([, g]) => g.substitutePosition)
    .sort(([, a], [, b]) => (a.substitutePosition || '').localeCompare(b.substitutePosition || ''));

  if (groupsWithSubPos.length === 0) return null;

  // Collect sorted substitute position keys
  const allSubPositions = groupsWithSubPos.map(([, g]) => g.substitutePosition).sort();

  // Sort: scheduled groups first, then by current substitutePosition for stability
  const reordered = [...groupsWithSubPos].sort(([, a], [, b]) => {
    const aScheduled = a.isScheduled !== false ? 0 : 1;
    const bScheduled = b.isScheduled !== false ? 0 : 1;
    if (aScheduled !== bScheduled) return aScheduled - bScheduled;
    return (a.substitutePosition || '').localeCompare(b.substitutePosition || '');
  });

  // Early return if positions are already correctly ordered
  const alreadyCorrect = reordered.every(([role], index) =>
    roleGroups[role].substitutePosition === allSubPositions[index]
  );
  if (alreadyCorrect) return null;

  // Collect player IDs at current positions before reassignment
  const subPlayerIds = reordered.map(([role]) => {
    const oldSubPos = roleGroups[role].substitutePosition;
    return formation[oldSubPos];
  });

  // Build new roleGroups with reassigned substitutePositions (no mutation of input)
  const newRoleGroups = { ...roleGroups };
  const newFormation = { ...formation };
  reordered.forEach(([role], index) => {
    const newSubPos = allSubPositions[index];
    newRoleGroups[role] = {
      ...roleGroups[role],
      substitutePosition: newSubPos
    };
    newFormation[newSubPos] = subPlayerIds[index];
  });

  // Update affected substitute players' currentPositionKey
  const subPlayerIdSet = new Set(subPlayerIds.filter(Boolean));
  const newAllPlayers = allPlayers.map(p => {
    if (!subPlayerIdSet.has(p.id)) return p;
    // Find this player's new position from updated formation
    const newPos = allSubPositions.find(pos => newFormation[pos] === p.id);
    if (newPos && newPos !== p.stats.currentPositionKey) {
      return { ...p, stats: { ...p.stats, currentPositionKey: newPos } };
    }
    return p;
  });

  return { newRoleGroups, newFormation, newAllPlayers };
};

/**
 * Find which role group a player belongs to
 * @returns {{ role: string, index: number } | null}
 */
export const findPlayerRoleGroup = (roleGroups, playerId) => {
  if (!roleGroups) return null;
  for (const role of Object.keys(roleGroups)) {
    const group = roleGroups[role];
    if (!group?.queue) continue;
    const index = group.queue.indexOf(playerId);
    if (index >= 0) return { role, index };
  }
  return null;
};

/**
 * Lazy initializer for isScheduled flags on role groups.
 * Marks the first `substitutionCount` groups (by substitutePosition order) as scheduled,
 * the rest as unscheduled. Returns a new roleGroups object with flags applied,
 * or null if no flags are needed (substitutionCount >= totalGroups or flags already exist).
 */
const ensureScheduledFlags = (roleGroups, substitutionCount) => {
  if (!roleGroups) return null;

  const groups = Object.entries(roleGroups);
  const eligibleGroups = groups.filter(([, g]) => g.queue && g.queue.length >= 2 && g.substitutePosition);

  // If substitutionCount covers all groups, no flags needed
  if (substitutionCount >= eligibleGroups.length) return null;

  // Check if flags already exist on any group
  const hasFlags = eligibleGroups.some(([, g]) => g.isScheduled !== undefined);
  if (hasFlags) return null;

  // Sort by substitutePosition to determine which groups are scheduled
  const sorted = [...eligibleGroups].sort(
    ([, a], [, b]) => (a.substitutePosition || '').localeCompare(b.substitutePosition || '')
  );

  const result = { ...roleGroups };
  for (let i = 0; i < sorted.length; i++) {
    const [role] = sorted[i];
    result[role] = { ...roleGroups[role], isScheduled: i < substitutionCount };
  }
  return result;
};

/**
 * Recalculate isScheduled flags on role groups when substitutionCount changes.
 * If substitutionCount >= eligible groups, all groups become scheduled (isScheduled flags removed).
 * If substitutionCount < eligible groups, exactly substitutionCount groups are scheduled (by substitutePosition order).
 * Returns null when no change is needed (idempotent — prevents infinite effect loops).
 */
export const recalculateScheduledGroupsForSubstitutionCount = (roleGroups, substitutionCount) => {
  if (!roleGroups) return null;

  const entries = Object.entries(roleGroups);
  const eligibleEntries = entries.filter(([, g]) => g.queue && g.queue.length >= 2 && g.substitutePosition);

  if (substitutionCount >= eligibleEntries.length) {
    // All groups should be scheduled — check if any are currently unscheduled
    const hasUnscheduled = eligibleEntries.some(([, g]) => g.isScheduled === false);
    if (!hasUnscheduled) return null;

    // Remove isScheduled flags (all groups scheduled)
    const newRoleGroups = {};
    for (const [role, group] of entries) {
      const { isScheduled, ...rest } = group;
      newRoleGroups[role] = { ...rest, queue: [...(group.queue || [])] };
    }
    const result = calculateNextToSubOutIds(newRoleGroups);
    return { roleGroups: newRoleGroups, ...result };
  }

  // substitutionCount < eligibleGroups: ensure exactly substitutionCount groups are scheduled
  const sorted = [...eligibleEntries].sort(
    ([, a], [, b]) => (a.substitutePosition || '').localeCompare(b.substitutePosition || '')
  );

  // Check if current scheduled state already matches
  const currentScheduledCount = eligibleEntries.filter(([, g]) => g.isScheduled !== false).length;
  if (currentScheduledCount === substitutionCount) return null;

  const newRoleGroups = {};
  for (const [role, group] of entries) {
    newRoleGroups[role] = { ...group, queue: [...(group.queue || [])] };
  }
  for (let i = 0; i < sorted.length; i++) {
    const [role] = sorted[i];
    newRoleGroups[role] = { ...newRoleGroups[role], isScheduled: i < substitutionCount };
  }

  const result = calculateNextToSubOutIds(newRoleGroups);
  return { roleGroups: newRoleGroups, ...result };
};

/**
 * Update role groups after two players swap positions.
 * If players are in different groups, they swap group membership.
 * Returns new roleGroups or null if not applicable.
 */
const updateRoleGroupsForPositionSwap = (roleGroups, player1Id, player2Id) => {
  if (!roleGroups) return null;

  const group1 = findPlayerRoleGroup(roleGroups, player1Id);
  const group2 = findPlayerRoleGroup(roleGroups, player2Id);

  if (!group1 && !group2) return roleGroups;
  if (group1 && group2 && group1.role === group2.role) return roleGroups;

  // Deep copy all role groups dynamically
  const newGroups = Object.fromEntries(
    Object.entries(roleGroups).map(([role, g]) => [role, { ...g, queue: [...(g.queue || [])] }])
  );

  if (group1 && group2) {
    // Both in groups but different ones — remove then insert to preserve queue priority.
    // Each player keeps their own queue index when moving to the other group.
    const queue1 = newGroups[group1.role].queue;
    const queue2 = newGroups[group2.role].queue;
    queue1.splice(group1.index, 1);
    queue2.splice(group2.index, 1);
    queue2.splice(group1.index, 0, player1Id);
    queue1.splice(group2.index, 0, player2Id);

    // Swap isScheduled only when the "next off" player (queue[0]) leaves a scheduled group.
    // Use !== false to match codebase convention (undefined is treated as scheduled).
    const group1Scheduled = newGroups[group1.role].isScheduled !== false;
    const group2Scheduled = newGroups[group2.role].isScheduled !== false;

    if (group1Scheduled !== group2Scheduled) {
      const scheduledGroupLosesNextOff =
        (group1Scheduled && group1.index === 0) ||
        (group2Scheduled && group2.index === 0);

      if (scheduledGroupLosesNextOff) {
        newGroups[group1.role].isScheduled = group2Scheduled;
        newGroups[group2.role].isScheduled = group1Scheduled;
      }
    }
  } else if (group1 && !group2) {
    newGroups[group1.role].queue[group1.index] = player2Id;
  } else if (!group1 && group2) {
    newGroups[group2.role].queue[group2.index] = player1Id;
  }

  return newGroups;
};

/**
 * Update role groups after a goalie switch.
 * The new goalie leaves their role group and the former goalie takes their place.
 */
const updateRoleGroupsForGoalieSwitch = (roleGroups, formerGoalieId, newGoalieId) => {
  if (!roleGroups) return null;

  const newGoalieGroup = findPlayerRoleGroup(roleGroups, newGoalieId);
  if (!newGoalieGroup) return roleGroups;

  const newGroups = Object.fromEntries(
    Object.entries(roleGroups).map(([groupKey, group]) => [groupKey, {
      ...group,
      queue: [...(group?.queue || [])]
    }])
  );

  // Former goalie replaces new goalie in their group
  newGroups[newGoalieGroup.role].queue[newGoalieGroup.index] = formerGoalieId;

  return newGroups;
};

/**
 * Calculate the result of a substitution without modifying any state
 */
export const calculateSubstitution = (gameState) => {
  const {
    formation,
    nextPlayerIdToSubOut,
    allPlayers,
    rotationQueue,
    teamConfig,
    selectedFormation,
    isSubTimerPaused = false,
    substitutionCount = 1,
    substitutionLogic = null,
    roleGroups = null,
    targetRole = null
  } = gameState;


  const currentTimeEpoch = getCurrentTimestamp();
  const substitutionManager = createSubstitutionManager(teamConfig, selectedFormation);


  const context = {
    formation,
    nextPlayerIdToSubOut,
    allPlayers,
    rotationQueue,
    currentTimeEpoch,
    isSubTimerPaused,
    substitutionCount,
    substitutionLogic,
    roleGroups,
    targetRole
  };

  try {
    const result = substitutionManager.executeSubstitution(context);

    const newGameState = {
      ...gameState,
      formation: result.newFormation,
      allPlayers: result.updatedPlayers,
      rotationQueue: result.newRotationQueue || gameState.rotationQueue,
      nextPlayerIdToSubOut: result.newNextPlayerIdToSubOut !== undefined ? result.newNextPlayerIdToSubOut : gameState.nextPlayerIdToSubOut,
      nextPlayerToSubOut: result.newNextPlayerToSubOut || gameState.nextPlayerToSubOut,
      playersToHighlight: result.playersComingOnIds || [],
      lastSubstitutionTimestamp: currentTimeEpoch,
      substitutionResult: result
    };

    // Propagate updated roleGroups from same-role substitution
    if (result.newRoleGroups) {
      newGameState.roleGroups = result.newRoleGroups;
    }
    if (result.nextToSubOutIds) {
      newGameState.nextToSubOutIds = result.nextToSubOutIds;
    }

    return newGameState;
  } catch (error) {
    handleError(error, {
      category: ERROR_CATEGORIES.GAME_LOGIC,
      operation: 'calculateSubstitution',
      teamConfig,
      selectedFormation,
      nextPlayerIdToSubOut
    });
    return gameState; // Return unchanged state on error
  }
};

/**
 * Calculate the result of switching positions between two players
 */
export const calculatePositionSwitch = (gameState, player1Id, player2Id) => {
  const { allPlayers, formation, teamConfig, isSubTimerPaused = false } = gameState;

  if (!player1Id || !player2Id || player1Id === player2Id) {
    return gameState;
  }

  const player1 = findPlayerById(allPlayers, player1Id);
  const player2 = findPlayerById(allPlayers, player2Id);
  
  if (!player1 || !player2) {
    return gameState;
  }

  // Don't allow switching with goalie
  if (player1.id === formation.goalie || player2.id === formation.goalie) {
    return gameState;
  }

  const player1Position = player1.stats.currentPositionKey;
  const player2Position = player2.stats.currentPositionKey;

  // Validate positions
  const currentValidPositions = getValidPositions(teamConfig);
  if (!currentValidPositions.includes(player1Position) || !currentValidPositions.includes(player2Position)) {
    return gameState;
  }

  // Create new formation with swapped positions - individual formations only
  const newFormation = { ...formation };
  newFormation[player1Position] = player2Id;
  newFormation[player2Position] = player1Id;

  // Update player stats with new positions and roles
  const currentTimeEpoch = getCurrentTimestamp();
  const newAllPlayers = allPlayers.map(p => {
    if (p.id === player1Id) {
      // Determine the new role for player1 based on their new position
      const newRole = getPositionRole(player2Position) || p.stats.currentRole;

      const playerWithRoleChange = handleRoleChange(p, newRole, currentTimeEpoch, isSubTimerPaused);
      return {
        ...playerWithRoleChange,
        stats: {
          ...playerWithRoleChange.stats,
          currentPositionKey: player2Position
        }
      };
    }
    if (p.id === player2Id) {
      // Determine the new role for player2 based on their new position
      const newRole = getPositionRole(player1Position) || p.stats.currentRole;

      const playerWithRoleChange = handleRoleChange(p, newRole, currentTimeEpoch, isSubTimerPaused);
      return {
        ...playerWithRoleChange,
        stats: {
          ...playerWithRoleChange.stats,
          currentPositionKey: player1Position
        }
      };
    }
    return p;
  });

  // Ensure isScheduled flags are initialized before position swap
  const { substitutionCount = 1 } = gameState;
  const flaggedRoleGroups = ensureScheduledFlags(gameState.roleGroups, substitutionCount);
  const effectiveRoleGroups = flaggedRoleGroups || gameState.roleGroups;

  const newRoleGroups = updateRoleGroupsForPositionSwap(effectiveRoleGroups, player1Id, player2Id);

  // Recalculate nextToSubOutIds when players swapped between different role groups
  // Also persist newly-initialized flags even for same-group swaps
  const roleGroupsChanged = newRoleGroups && (newRoleGroups !== effectiveRoleGroups || flaggedRoleGroups);

  // After isScheduled swap, reorder substitute positions so scheduled groups occupy top slots
  let finalFormation = newFormation;
  let finalAllPlayers = newAllPlayers;
  let finalRoleGroups = newRoleGroups;
  if (roleGroupsChanged) {
    const reorderResult = reorderSubstitutePositionsForSchedule(newRoleGroups, newFormation, newAllPlayers);
    if (reorderResult) {
      finalFormation = reorderResult.newFormation;
      finalAllPlayers = reorderResult.newAllPlayers;
      finalRoleGroups = reorderResult.newRoleGroups;
    }
  }

  const nextSubOutUpdate = roleGroupsChanged ? calculateNextToSubOutIds(finalRoleGroups) : {};

  // Handle rotation queue updates for rotate-roles mode with fixed role group boundary crossings
  const { fixedRoleGroup, substitutionLogic, rotationQueue = [] } = gameState;
  const isRotateRoles = !isSameRoleMode(substitutionLogic);
  let finalRotationQueue = rotationQueue;
  let finalNextPlayerIdToSubOut = gameState.nextPlayerIdToSubOut;

  if (isRotateRoles && fixedRoleGroup) {
    const fixedPositions = getFixedGroupFieldPositions(gameState.teamConfig, fixedRoleGroup);
    const player1WasFixed = fixedPositions.includes(player1Position);
    const player2WasFixed = fixedPositions.includes(player2Position);

    if (player1WasFixed !== player2WasFixed) {
      // One player crossed the fixed-group boundary
      const playerEnteringFixed = player1WasFixed ? player2Id : player1Id;
      const playerLeavingFixed = player1WasFixed ? player1Id : player2Id;

      const enteringIdx = rotationQueue.indexOf(playerEnteringFixed);
      const newQueue = rotationQueue.filter(id => id !== playerEnteringFixed && id !== playerLeavingFixed);
      if (enteringIdx >= 0 && enteringIdx <= newQueue.length) {
        newQueue.splice(enteringIdx, 0, playerLeavingFixed);
      } else {
        newQueue.push(playerLeavingFixed);
      }
      finalRotationQueue = newQueue;
      finalNextPlayerIdToSubOut = newQueue[0] || null;
    }
  }

  return {
    ...gameState,
    formation: finalFormation,
    allPlayers: finalAllPlayers,
    playersToHighlight: [player1Id, player2Id],
    rotationQueue: finalRotationQueue,
    nextPlayerIdToSubOut: finalNextPlayerIdToSubOut,
    ...(finalRoleGroups ? { roleGroups: finalRoleGroups } : {}),
    ...(nextSubOutUpdate.nextToSubOutIds ? {
      nextToSubOutIds: nextSubOutUpdate.nextToSubOutIds,
      nextPlayerIdToSubOut: nextSubOutUpdate.nextPlayerIdToSubOut
    } : {})
  };
};

/**
 * Calculate the result of a "Substitute Now" from a fixed (non-rotating) role group.
 *
 * In same-role mode with an odd squad size, one role group has only 2 field players
 * and no substitute (substitutePosition: null). When a field player from this fixed
 * group requests an immediate substitution with a substitute from another group, the
 * two players swap groups: the field player goes to the bench in the active group and
 * the selected substitute joins the fixed group on the field.
 *
 * @param {Object} gameState - Current game state
 * @param {string} fieldPlayerId - ID of the field player in the fixed group
 * @param {string} selectedSubstituteId - ID of the substitute from another group
 * @returns {Object} New game state with the group switch applied
 */
export const calculateFixedGroupSubNow = (gameState, fieldPlayerId, selectedSubstituteId) => {
  const { allPlayers, formation, roleGroups, isSubTimerPaused = false } = gameState;

  if (!fieldPlayerId || !selectedSubstituteId || fieldPlayerId === selectedSubstituteId) {
    return gameState;
  }

  const fieldPlayer = findPlayerById(allPlayers, fieldPlayerId);
  const selectedSub = findPlayerById(allPlayers, selectedSubstituteId);

  if (!fieldPlayer || !selectedSub) {
    return gameState;
  }

  const fieldPlayerGroupInfo = findPlayerRoleGroup(roleGroups, fieldPlayerId);
  const subGroupInfo = findPlayerRoleGroup(roleGroups, selectedSubstituteId);

  if (!fieldPlayerGroupInfo || !subGroupInfo || fieldPlayerGroupInfo.role === subGroupInfo.role) {
    return gameState;
  }

  const fixedGroup = roleGroups[fieldPlayerGroupInfo.role];
  if (!fixedGroup || fixedGroup.substitutePosition !== null) {
    return gameState;
  }

  const currentTimeEpoch = getCurrentTimestamp();
  const fieldPlayerOldPosition = fieldPlayer.stats.currentPositionKey;
  const subOldPosition = selectedSub.stats.currentPositionKey;

  // Swap formation positions
  const newFormation = { ...formation };
  newFormation[fieldPlayerOldPosition] = selectedSubstituteId;
  newFormation[subOldPosition] = fieldPlayerId;

  // Update player stats
  const newAllPlayers = allPlayers.map(p => {
    if (p.id === fieldPlayerId) {
      const timeResult = isSubTimerPaused
        ? resetPlayerStintTimer(p, currentTimeEpoch)
        : { ...p, stats: updatePlayerTimeStats(p, currentTimeEpoch, false) };
      return {
        ...timeResult,
        stats: {
          ...timeResult.stats,
          currentStatus: 'substitute',
          currentRole: PLAYER_ROLES.SUBSTITUTE,
          currentPositionKey: subOldPosition
        }
      };
    }
    if (p.id === selectedSubstituteId) {
      const newRole = getPositionRole(fieldPlayerOldPosition) || PLAYER_ROLES.FIELD_PLAYER;
      const timeResult = isSubTimerPaused
        ? resetPlayerStintTimer(p, currentTimeEpoch)
        : { ...p, stats: updatePlayerTimeStats(p, currentTimeEpoch, false) };
      return {
        ...timeResult,
        stats: {
          ...timeResult.stats,
          currentStatus: 'on_field',
          currentRole: newRole,
          currentPositionKey: fieldPlayerOldPosition
        }
      };
    }
    return p;
  });

  // Update role groups: swap the two players between groups, keep substitutePosition unchanged
  const newRoleGroups = Object.fromEntries(
    Object.entries(roleGroups).map(([role, g]) => [role, { ...g, queue: [...g.queue] }])
  );
  newRoleGroups[fieldPlayerGroupInfo.role].queue[fieldPlayerGroupInfo.index] = selectedSubstituteId;
  newRoleGroups[subGroupInfo.role].queue[subGroupInfo.index] = fieldPlayerId;

  const { nextToSubOutIds, nextPlayerIdToSubOut } = calculateNextToSubOutIds(newRoleGroups);

  return {
    ...gameState,
    formation: newFormation,
    allPlayers: newAllPlayers,
    roleGroups: newRoleGroups,
    nextToSubOutIds,
    nextPlayerIdToSubOut,
    playersToHighlight: [fieldPlayerId, selectedSubstituteId],
    substitutionResult: {
      playersGoingOffIds: [fieldPlayerId],
      playersComingOnIds: [selectedSubstituteId],
      newFormation,
      updatedPlayers: newAllPlayers
    }
  };
};

/**
 * Calculate the result of a "Substitute Now" from a fixed group in rotate-roles mode.
 *
 * The fixed group is defined by field positions, not by the original players occupying
 * them. When a fixed-group player goes off manually, the incoming substitute takes that
 * fixed-group field position and is removed from rotation, while the outgoing player
 * joins the rotation queue in the incoming substitute's former queue slot.
 *
 * @param {Object} gameState - Current game state
 * @param {string} fieldPlayerId - ID of the outgoing fixed-group field player
 * @param {string} selectedSubstituteId - ID of the incoming substitute
 * @returns {Object} New game state with formation, players, and queue updated
 */
export const calculateRotateRolesFixedGroupSubNow = (gameState, fieldPlayerId, selectedSubstituteId) => {
  const {
    allPlayers,
    formation,
    rotationQueue = [],
    teamConfig,
    selectedFormation,
    isSubTimerPaused = false
  } = gameState;

  if (!fieldPlayerId || !selectedSubstituteId || fieldPlayerId === selectedSubstituteId) {
    return gameState;
  }

  const fieldPlayer = findPlayerById(allPlayers, fieldPlayerId);
  const selectedSub = findPlayerById(allPlayers, selectedSubstituteId);

  if (!fieldPlayer || !selectedSub) {
    return gameState;
  }

  const fieldPlayerOldPosition = fieldPlayer.stats.currentPositionKey;
  const subOldPosition = selectedSub.stats.currentPositionKey;

  if (!fieldPlayerOldPosition || !subOldPosition) {
    return gameState;
  }

  const definition = getDefinitionForGameLogic(teamConfig, selectedFormation);
  if (!definition?.substitutePositions?.includes(subOldPosition)) {
    return gameState;
  }

  const currentTimeEpoch = getCurrentTimestamp();

  const newFormation = { ...formation };
  newFormation[fieldPlayerOldPosition] = selectedSubstituteId;
  newFormation[subOldPosition] = fieldPlayerId;

  const incomingRole = getPositionRole(fieldPlayerOldPosition) || PLAYER_ROLES.FIELD_PLAYER;
  const newAllPlayers = allPlayers.map((player) => {
    if (player.id === fieldPlayerId) {
      const timeResult = isSubTimerPaused
        ? resetPlayerStintTimer(player, currentTimeEpoch)
        : { ...player, stats: updatePlayerTimeStats(player, currentTimeEpoch, false) };

      return {
        ...timeResult,
        stats: {
          ...timeResult.stats,
          currentStatus: PLAYER_STATUS.SUBSTITUTE,
          currentRole: PLAYER_ROLES.SUBSTITUTE,
          currentPositionKey: subOldPosition
        }
      };
    }

    if (player.id === selectedSubstituteId) {
      const timeResult = isSubTimerPaused
        ? resetPlayerStintTimer(player, currentTimeEpoch)
        : { ...player, stats: updatePlayerTimeStats(player, currentTimeEpoch, false) };

      return {
        ...timeResult,
        stats: {
          ...timeResult.stats,
          currentStatus: PLAYER_STATUS.ON_FIELD,
          currentRole: incomingRole,
          currentPositionKey: fieldPlayerOldPosition
        }
      };
    }

    return player;
  });

  const selectedSubQueueIndex = rotationQueue.indexOf(selectedSubstituteId);
  const filteredQueue = rotationQueue.filter(
    (playerId) => playerId !== selectedSubstituteId && playerId !== fieldPlayerId
  );
  const newRotationQueue = [...filteredQueue];

  if (selectedSubQueueIndex >= 0 && selectedSubQueueIndex <= newRotationQueue.length) {
    newRotationQueue.splice(selectedSubQueueIndex, 0, fieldPlayerId);
  } else {
    newRotationQueue.push(fieldPlayerId);
  }

  const newNextPlayerIdToSubOut = newRotationQueue[0] || null;
  const newNextPlayerToSubOut = newNextPlayerIdToSubOut
    ? definition.fieldPositions.find((position) => newFormation[position] === newNextPlayerIdToSubOut) || gameState.nextPlayerToSubOut
    : null;

  return {
    ...gameState,
    formation: newFormation,
    allPlayers: newAllPlayers,
    rotationQueue: newRotationQueue,
    nextPlayerIdToSubOut: newNextPlayerIdToSubOut,
    nextPlayerToSubOut: newNextPlayerToSubOut,
    playersToHighlight: [fieldPlayerId, selectedSubstituteId],
    substitutionResult: {
      playersGoingOffIds: [fieldPlayerId],
      playersComingOnIds: [selectedSubstituteId]
    }
  };
};

/**
 * Calculate the result of switching goalies
 */
export const calculateGoalieSwitch = (gameState, newGoalieId) => {
  const { allPlayers, formation, isSubTimerPaused = false } = gameState;

  if (!newGoalieId || newGoalieId === formation.goalie) {
    return gameState;
  }

  const currentGoalie = findPlayerById(allPlayers, formation.goalie);
  const newGoalie = findPlayerById(allPlayers, newGoalieId);
  
  if (!currentGoalie || !newGoalie) {
    return gameState;
  }

  // Don't allow switching with inactive player
  if (newGoalie.stats.isInactive) {
    return gameState;
  }

  const newGoaliePosition = newGoalie.stats.currentPositionKey;

  const isRotateRolesGoalie = !isSameRoleMode(gameState.substitutionLogic);
  const fixedPositionsGoalie = isRotateRolesGoalie && gameState.fixedRoleGroup
    ? getFixedGroupFieldPositions(gameState.teamConfig, gameState.fixedRoleGroup)
    : [];
  const newGoalieWasInFixedGroup = fixedPositionsGoalie.includes(newGoaliePosition);

  // Create new formation
  const newFormation = { ...formation };
  
  // Set new goalie
  newFormation.goalie = newGoalieId;

  // Place current goalie in the position of the new goalie
  // Handle individual formations (6-player and 7-player)
  newFormation[newGoaliePosition] = formation.goalie;

  // Update player stats and handle role changes
  const currentTimeEpoch = getCurrentTimestamp();
  const newAllPlayers = allPlayers.map(p => {
    if (p.id === formation.goalie) {
      // Current goalie becomes a field player
      const updatedStats = updatePlayerTimeStats(p, currentTimeEpoch, isSubTimerPaused);
      
      // Determine new role and status based on position they're moving to
      // Individual formations - use centralized role determination
      const newRole = getPositionRole(newGoaliePosition) || PLAYER_ROLES.DEFENDER; // Default to defender
      const newStatus = (newGoaliePosition && newGoaliePosition.includes('substitute_1')) ? PLAYER_STATUS.SUBSTITUTE : PLAYER_STATUS.ON_FIELD;
      
      // Handle role change from goalie to new position
      const playerWithNewRole = handleRoleChange(
        { ...p, stats: updatedStats },
        newRole,
        currentTimeEpoch,
        isSubTimerPaused
      );
      
      // Update status and position while preserving the properly initialized stats from handleRoleChange
      const finalStats = {
        ...playerWithNewRole.stats,
        currentStatus: newStatus,
        currentPositionKey: newGoaliePosition
      };
      
      return { ...p, stats: finalStats };
    } else if (p.id === newGoalieId) {
      // New goalie - calculate accumulated time for their field stint
      const updatedStats = updatePlayerTimeStats(p, currentTimeEpoch, isSubTimerPaused);
      
      // Handle role change from field player to goalie
      const playerWithNewRole = handleRoleChange(
        { ...p, stats: updatedStats },
        PLAYER_ROLES.GOALIE,
        currentTimeEpoch,
        isSubTimerPaused
      );
      
      // Update status and position while preserving the properly initialized stats from handleRoleChange
      const finalStats = {
        ...playerWithNewRole.stats,
        currentStatus: PLAYER_STATUS.GOALIE,
        currentPositionKey: POSITION_KEYS.GOALIE
      };
      
      return { ...p, stats: finalStats };
    }
    return p;
  });

  // Update rotation queue - remove new goalie from queue and add old goalie
  const queueManager = createRotationQueue(gameState.rotationQueue, createPlayerLookupFunction(allPlayers));
  queueManager.initialize();
  
  // Get new goalie's position BEFORE removing them
  const newGoalieQueuePosition = queueManager.getPosition(newGoalieId);

  // Remove new goalie from queue (they're now goalie, not in rotation)
  queueManager.removePlayer(newGoalieId);
  
  // Former goalie takes new goalie's exact queue position (maintains fair rotation)
  if (newGoalieQueuePosition >= 0) {
    queueManager.addPlayer(formation.goalie, newGoalieQueuePosition);
  } else if (!newGoalieWasInFixedGroup) {
    // Fallback: if new goalie wasn't in queue and wasn't in fixed group, add former goalie to end
    queueManager.addPlayer(formation.goalie, 'end');
  }
  // If new goalie was in fixed group, former goalie is now in fixed group — don't add to queue

  // Recalculate next player tracking if the new goalie was next to come off
  let newNextPlayerIdToSubOut = gameState.nextPlayerIdToSubOut;

  if (newGoalieId === gameState.nextPlayerIdToSubOut) {
    // New goalie was next to come off, so update tracking to next player in queue
    const updatedQueue = queueManager.toArray();
    newNextPlayerIdToSubOut = updatedQueue[0] || null;
  }

  const newRoleGroups = updateRoleGroupsForGoalieSwitch(gameState.roleGroups, formation.goalie, newGoalieId);

  // Recalculate nextToSubOutIds when role groups changed (new goalie left a group)
  const roleGroupsChanged = newRoleGroups && newRoleGroups !== gameState.roleGroups;
  const nextSubOutUpdate = roleGroupsChanged ? calculateNextToSubOutIds(newRoleGroups) : {};

  return {
    ...gameState,
    formation: newFormation,
    allPlayers: newAllPlayers,
    rotationQueue: queueManager.toArray(),
    nextPlayerIdToSubOut: newNextPlayerIdToSubOut,
    playersToHighlight: [formation.goalie, newGoalieId],
    ...(newRoleGroups ? { roleGroups: newRoleGroups } : {}),
    ...(nextSubOutUpdate.nextToSubOutIds ? {
      nextToSubOutIds: nextSubOutUpdate.nextToSubOutIds,
      nextPlayerIdToSubOut: nextSubOutUpdate.nextPlayerIdToSubOut
    } : {})
  };
};

/**
 * Calculate the result of undoing a substitution
 */
export const calculateUndo = (gameState, lastSubstitution) => {
  if (!lastSubstitution) {
    return gameState;
  }

  const currentTime = getCurrentTimestamp();
  const timeSinceSubstitution = Math.round((currentTime - lastSubstitution.timestamp) / 1000); // seconds

  // Restore formation and next player tracking
  const newFormation = lastSubstitution.beforeFormation;
  const newNextPlayerToSubOut = lastSubstitution.beforeNextPlayer;
  const newNextPlayerIdToSubOut = lastSubstitution.beforeNextPlayerId;
  const newRotationQueue = lastSubstitution.beforeRotationQueue || gameState.rotationQueue;

  // Calculate and restore player stats with time adjustments
  const newAllPlayers = gameState.allPlayers.map(player => {
    const wasComingOn = lastSubstitution.playersComingOnIds.includes(player.id);
    const wasGoingOff = lastSubstitution.playersGoingOffIds.includes(player.id);
    
    if (wasComingOn) {
      // Player came on during substitution - restore their original stats (before they came on)
      const originalStats = lastSubstitution.playersComingOnOriginalStats.find(p => p.id === player.id);
      if (originalStats) {
        return { ...player, stats: originalStats.stats };
      }
      return player;
    } else if (wasGoingOff) {
      // Player went off during substitution - they should get credit for the time they spent on bench
      const currentStats = { ...player.stats };
      
      // Add the bench time to their total field time
      currentStats.timeOnFieldSeconds += timeSinceSubstitution;
      
      // Add bench time to their role-specific counter based on what role they had when substituted
      const normalizedRole = normalizeRole(currentStats.currentRole);
      if (normalizedRole === PLAYER_ROLES.ATTACKER) {
        currentStats.timeAsAttackerSeconds += timeSinceSubstitution;
      } else if (normalizedRole === PLAYER_ROLES.DEFENDER) {
        currentStats.timeAsDefenderSeconds += timeSinceSubstitution;
      }

      // Update their status back to 'on_field' and reset stint timer
      currentStats.currentStatus = PLAYER_STATUS.ON_FIELD;
      currentStats.lastStintStartTimeEpoch = currentTime;
      
      // Restore their field position from the before-substitution formation
      const beforeFormation = lastSubstitution.beforeFormation;
      const validPositions = getValidPositions(lastSubstitution.teamConfig);
      const restoredPosition = validPositions.find(pos => beforeFormation[pos] === player.id);

      if (restoredPosition) {
        currentStats.currentPositionKey = restoredPosition;
      }

      return { ...player, stats: currentStats };
    } else {
      // Player wasn't involved in substitution - no changes needed
      return player;
    }
  });

  return {
    ...gameState,
    formation: newFormation,
    nextPlayerToSubOut: newNextPlayerToSubOut,
    nextPlayerIdToSubOut: newNextPlayerIdToSubOut,
    rotationQueue: newRotationQueue,
    allPlayers: newAllPlayers,
    playersToHighlight: lastSubstitution.playersGoingOffIds, // Highlight players going back on field
    lastSubstitutionTimestamp: null, // Clear the undo data
    // Restore roleGroups and nextToSubOutIds for same-role mode undo
    ...(lastSubstitution.beforeRoleGroups ? { roleGroups: lastSubstitution.beforeRoleGroups } : {}),
    ...(lastSubstitution.beforeNextToSubOutIds ? { nextToSubOutIds: lastSubstitution.beforeNextToSubOutIds } : {})
  };
};

/**
 * Creates a reactivation cascade mapping for moving a reactivated player to substitute_1
 * and shifting all other active substitutes down one position
 * 
 * @param {string} reactivatedPlayerId - Player being reactivated 
 * @param {Array<string>} substitutePositions - Array of substitute position keys
 * @param {Object} formation - Current formation
 * @param {Array} allPlayers - Array of all player objects
 * @returns {Object} Mapping of player moves and formation updates
 */
const createReactivationCascade = (reactivatedPlayerId, substitutePositions, formation, allPlayers) => {
  const cascade = { formation: {}, players: {} };
  
  // Collect all players currently in substitute positions with their status
  const substitutePlayersInfo = [];
  substitutePositions.forEach(position => {
    const playerId = formation[position];
    if (playerId) {
      const player = allPlayers.find(p => p.id === playerId);
      substitutePlayersInfo.push({
        playerId,
        position,
        isActive: player && !player.stats.isInactive,
        isReactivatedPlayer: playerId === reactivatedPlayerId
      });
    }
  });
  
  // Separate active players (excluding reactivated) and inactive players
  const activeSubstitutes = substitutePlayersInfo.filter(p => p.isActive && !p.isReactivatedPlayer);
  const inactiveSubstitutes = substitutePlayersInfo.filter(p => !p.isActive && !p.isReactivatedPlayer);
  
  // Reactivated player goes to substitute_1
  cascade.formation[substitutePositions[0]] = reactivatedPlayerId;
  cascade.players[reactivatedPlayerId] = {
    currentPositionKey: substitutePositions[0],
    isInactive: false
  };
  
  // All active substitutes shift down one position
  for (let i = 0; i < activeSubstitutes.length; i++) {
    const { playerId } = activeSubstitutes[i];
    const newPosition = substitutePositions[i + 1];
    
    if (newPosition) {
      cascade.formation[newPosition] = playerId;
      cascade.players[playerId] = {
        currentPositionKey: newPosition,
        isInactive: false  // Explicitly preserve active status
      };
    }
  }
  
  // Fill remaining positions with inactive players (they stay inactive but may move positions)
  const remainingPositionIndex = activeSubstitutes.length + 1; // +1 because reactivated player took substitute_1
  for (let i = 0; i < inactiveSubstitutes.length; i++) {
    const { playerId } = inactiveSubstitutes[i];
    const newPosition = substitutePositions[remainingPositionIndex + i];
    
    if (newPosition) {
      cascade.formation[newPosition] = playerId;
      cascade.players[playerId] = {
        currentPositionKey: newPosition,
        isInactive: true  // Explicitly preserve inactive status
      };
    }
  }
  
  return cascade;
};

/**
 * Calculate the result of toggling a player's inactive status in same-role mode.
 * Sets hasInactiveSub on the affected role group, cascades the player to the
 * bottom substitute position (or top on reactivation), and recalculates nextToSubOutIds.
 */
const calculatePlayerToggleInactiveSameRole = (gameState, playerId) => {
  const { allPlayers, formation, roleGroups, teamConfig, selectedFormation } = gameState;

  const player = findPlayerById(allPlayers, playerId);
  if (!player) return gameState;

  const definition = getDefinitionForGameLogic(teamConfig, selectedFormation);
  if (!definition) return gameState;

  const currentlyInactive = player.stats.isInactive;

  // Deep-copy roleGroups
  const newRoleGroups = {};
  for (const [role, group] of Object.entries(roleGroups)) {
    newRoleGroups[role] = { ...group, queue: [...group.queue] };
  }

  let newFormation = { ...formation };
  let newAllPlayers;

  // Find which role group this player belongs to
  const playerGroupInfo = findPlayerRoleGroup(roleGroups, playerId);

  if (currentlyInactive) {
    // --- REACTIVATION ---
    // Mark player as active
    newAllPlayers = allPlayers.map(p => {
      if (p.id === playerId) {
        return { ...p, stats: { ...p.stats, isInactive: false } };
      }
      return p;
    });

    // Remove hasInactiveSub from the player's group
    if (playerGroupInfo) {
      delete newRoleGroups[playerGroupInfo.role].hasInactiveSub;
    }

    // Apply reactivation cascade: player moves to substitute_1, others shift down
    const cascade = createReactivationCascade(playerId, definition.substitutePositions, formation, newAllPlayers);

    // Update formation with cascade results
    Object.entries(cascade.formation).forEach(([position, playerIdForPosition]) => {
      newFormation[position] = playerIdForPosition;
    });

    // Update player positions with cascade results
    newAllPlayers = newAllPlayers.map(p => {
      if (cascade.players[p.id]) {
        return {
          ...p,
          stats: {
            ...p.stats,
            ...cascade.players[p.id]
          }
        };
      }
      return p;
    });

    // Update roleGroups substitutePosition mappings based on new formation
    for (const [role, group] of Object.entries(newRoleGroups)) {
      const subPlayerId = group.queue[group.queue.length - 1]; // Last in queue = substitute
      const newSubPosition = Object.keys(newFormation).find(
        pos => definition.substitutePositions.includes(pos) && newFormation[pos] === subPlayerId
      );
      if (newSubPosition) {
        newRoleGroups[role] = { ...newRoleGroups[role], substitutePosition: newSubPosition };
      }
    }
  } else {
    // --- INACTIVATION ---
    // Mark player as inactive
    newAllPlayers = allPlayers.map(p => {
      if (p.id === playerId) {
        return { ...p, stats: { ...p.stats, isInactive: true } };
      }
      return p;
    });

    // Set hasInactiveSub on the player's group
    if (playerGroupInfo) {
      newRoleGroups[playerGroupInfo.role].hasInactiveSub = true;
    }

    // Cascade: move inactive player to bottom substitute position
    const bottomSubPosition = getBottomSubstitutePosition(teamConfig);
    const currentPosition = player.stats.currentPositionKey;

    if (bottomSubPosition && currentPosition !== bottomSubPosition) {
      const substitutePositions = definition.substitutePositions;
      const currentIndex = substitutePositions.indexOf(currentPosition);
      const bottomIndex = substitutePositions.indexOf(bottomSubPosition);

      // All players from current position to bottom need to shift up one position
      for (let i = currentIndex + 1; i <= bottomIndex; i++) {
        const position = substitutePositions[i];
        const playerIdToMove = formation[position];
        if (playerIdToMove) {
          const targetPosition = substitutePositions[i - 1];
          newFormation[targetPosition] = playerIdToMove;

          // Update player's position key
          newAllPlayers = newAllPlayers.map(p => {
            if (p.id === playerIdToMove) {
              return { ...p, stats: { ...p.stats, currentPositionKey: targetPosition } };
            }
            return p;
          });
        }
      }

      // Move inactive player to bottom position
      newFormation[bottomSubPosition] = playerId;
      newAllPlayers = newAllPlayers.map(p => {
        if (p.id === playerId) {
          return { ...p, stats: { ...p.stats, currentPositionKey: bottomSubPosition } };
        }
        return p;
      });
    }

    // Update roleGroups substitutePosition mappings based on new formation
    for (const [role, group] of Object.entries(newRoleGroups)) {
      const subPlayerId = group.queue[group.queue.length - 1]; // Last in queue = substitute
      const newSubPosition = Object.keys(newFormation).find(
        pos => definition.substitutePositions.includes(pos) && newFormation[pos] === subPlayerId
      );
      if (newSubPosition) {
        newRoleGroups[role] = { ...newRoleGroups[role], substitutePosition: newSubPosition };
      }
    }
  }

  // Recalculate nextToSubOutIds
  const { nextToSubOutIds, nextPlayerIdToSubOut } = calculateNextToSubOutIds(newRoleGroups);

  return {
    ...gameState,
    formation: newFormation,
    allPlayers: newAllPlayers,
    roleGroups: newRoleGroups,
    nextToSubOutIds,
    nextPlayerIdToSubOut,
    playersToHighlight: []
  };
};

/**
 * Calculate the result of toggling a player's inactive status (all individual modes)
 */
export const calculatePlayerToggleInactive = (gameState, playerId) => {
  const { allPlayers, formation, rotationQueue, nextPlayerIdToSubOut, teamConfig, selectedFormation } = gameState;

  if (!supportsInactiveUsers(teamConfig)) {
    return gameState;
  }

  const player = findPlayerById(allPlayers, playerId);
  if (!player) {
    return gameState;
  }

  const definition = getDefinitionForGameLogic(teamConfig, selectedFormation);
  if (!definition) {
    return gameState;
  }

  const currentlyInactive = player.stats.isInactive;

  // Check if player is a substitute using configuration-driven approach
  const isSubstitute = definition.substitutePositions.includes(player.stats.currentPositionKey);

  // Only allow inactivating/activating substitute players
  if (!isSubstitute) {
    return gameState;
  }

  // Delegate to same-role specific logic when in same-role mode
  if (isSameRoleMode(gameState.substitutionLogic) && gameState.roleGroups) {
    return calculatePlayerToggleInactiveSameRole(gameState, playerId);
  }

  // No additional validation needed - SUB NOW button handles "all inactive" scenario

  let newFormation = { ...formation };
  let newRotationQueue = [...rotationQueue];
  let newNextPlayerIdToSubOut = nextPlayerIdToSubOut;

  // Update player stats and manage positions
  let newAllPlayers = allPlayers.map(p => {
    if (p.id === playerId) {
      return { ...p, stats: { ...p.stats, isInactive: !currentlyInactive } };
    }
    return p;
  });

  // Update rotation queue and positions
  if (currentlyInactive) {
    // DEBUG: Log initial state before reactivation
    
    // Player is being reactivated - they become substitute_1 and all others cascade down
    const queueManager = createRotationQueue(rotationQueue, createPlayerLookupFunction(allPlayers));
    queueManager.initialize();
    queueManager.reactivatePlayer(playerId);
    newRotationQueue = queueManager.toArray();
    
    
    // Apply reactivation cascade to formation and player positions
    const cascade = createReactivationCascade(playerId, definition.substitutePositions, formation, newAllPlayers);
    
    // Update formation with cascade results
    Object.entries(cascade.formation).forEach(([position, playerIdForPosition]) => {
      newFormation[position] = playerIdForPosition;
    });
    
    // Update player positions with cascade results
    newAllPlayers = newAllPlayers.map(p => {
      if (cascade.players[p.id]) {
        return {
          ...p,
          stats: {
            ...p.stats,
            ...cascade.players[p.id]
          }
        };
      }
      return p;
    });
    
    // DEBUG: Log reactivation state changes
    
    // ✅ FIXED: Reactivated player should be "next to go ON", not "next to come OFF"
    // The nextPlayerIdToSubOut should point to the first field player in the rotation queue
    // The reactivated player is now substitute_1 (next to go on) via the cascade logic
    
    // Set nextPlayerIdToSubOut to the first player in the rotation queue (should be a field player)
    const nextActivePlayers = queueManager.getNextActivePlayer(2);
    if (nextActivePlayers.length > 0) {
      newNextPlayerIdToSubOut = nextActivePlayers[0];
    } else {
      // Keep the original value if queue is empty (shouldn't happen)
      newNextPlayerIdToSubOut = nextPlayerIdToSubOut;
    }
  } else {
    // Player is being inactivated - move to bottom substitute position if possible
    const queueManager = createRotationQueue(rotationQueue, createPlayerLookupFunction(allPlayers));
    queueManager.initialize();
    queueManager.deactivatePlayer(playerId);
    newRotationQueue = queueManager.toArray();
    
    // Update next player tracking if the inactivated player was next
    if (playerId === nextPlayerIdToSubOut && queueManager.activeSize() > 0) {
      const nextActivePlayers = queueManager.getNextActivePlayer(2);
      if (nextActivePlayers.length > 0) {
        newNextPlayerIdToSubOut = nextActivePlayers[0];
      }
    }
    
    // Cascading inactivation: Move inactive player to bottom and shift others up
    const bottomSubPosition = getBottomSubstitutePosition(teamConfig);
    const currentPosition = player.stats.currentPositionKey;
    
    if (bottomSubPosition && currentPosition !== bottomSubPosition) {
      const substitutePositions = definition.substitutePositions;
      const currentIndex = substitutePositions.indexOf(currentPosition);
      const bottomIndex = substitutePositions.indexOf(bottomSubPosition);
      
      // All players from current position to bottom need to shift up one position
      for (let i = currentIndex + 1; i <= bottomIndex; i++) {
        const position = substitutePositions[i];
        const playerIdToMove = formation[position];
        if (playerIdToMove) {
          const targetPosition = substitutePositions[i - 1];
          newFormation[targetPosition] = playerIdToMove;
          
          // Update player's position key
          newAllPlayers = newAllPlayers.map(p => {
            if (p.id === playerIdToMove) {
              return { ...p, stats: { ...p.stats, currentPositionKey: targetPosition } };
            }
            return p;
          });
        }
      }
      
      // Move inactive player to bottom position
      newFormation[bottomSubPosition] = playerId;
      newAllPlayers = newAllPlayers.map(p => {
        if (p.id === playerId) {
          return { ...p, stats: { ...p.stats, currentPositionKey: bottomSubPosition } };
        }
        return p;
      });
    }
  }

  return {
    ...gameState,
    formation: newFormation,
    allPlayers: newAllPlayers,
    rotationQueue: newRotationQueue,
    nextPlayerIdToSubOut: newNextPlayerIdToSubOut,
    playersToHighlight: [] // No special highlighting for activation/deactivation
  };
};

/**
 * Calculate the result of reordering substitutes when setting a player as next to go in
 * The target player moves to substitute_1, all players ahead of them move down one position
 */
export const calculateSubstituteReorder = (gameState, targetPosition, substitutionCount = 1) => {
  const { allPlayers, formation, teamConfig, selectedFormation } = gameState;

  if (!hasMultipleSubstitutes(teamConfig)) {
    return gameState;
  }

  const definition = getDefinitionForGameLogic(teamConfig, selectedFormation);
  if (!definition || !definition.substitutePositions.includes(targetPosition)) {
    return gameState;
  }

  const substitutePositions = definition.substitutePositions;

  // Determine the last "next to go in" position based on substitutionCount
  // If substitutionCount is 3, the last "next" position is substitute_3
  const lastNextPosition = substitutePositions[Math.min(substitutionCount - 1, substitutePositions.length - 1)];

  // Cannot reorder if already in a "next to go in" position
  const targetIndex = substitutePositions.indexOf(targetPosition);
  if (targetIndex < substitutionCount) {
    return gameState;
  }

  const targetPlayerId = formation[targetPosition];
  if (!targetPlayerId) {
    return gameState;
  }

  if (targetIndex === -1) {
    return gameState;
  }

  // Create new formation with reordered positions
  const newFormation = { ...formation };

  // Store the players who need to be shifted (those from lastNextPosition up to but not including targetPosition)
  const playersToShift = [];
  const lastNextIndex = substitutePositions.indexOf(lastNextPosition);
  for (let i = lastNextIndex; i < targetIndex; i++) {
    const position = substitutePositions[i];
    const playerId = formation[position];
    if (playerId) {
      playersToShift.push({ playerId, currentPosition: position });
    }
  }

  // Move target player to the last "next to go in" position
  newFormation[lastNextPosition] = targetPlayerId;

  // Shift all players who were at or after lastNextPosition down one position
  for (let i = 0; i < playersToShift.length; i++) {
    const nextPosition = substitutePositions[lastNextIndex + i + 1];
    newFormation[nextPosition] = playersToShift[i].playerId;
  }
  
  // Update player stats with new positions
  const newAllPlayers = allPlayers.map(p => {
    // Target player moves to lastNextPosition
    if (p.id === targetPlayerId) {
      return { ...p, stats: { ...p.stats, currentPositionKey: lastNextPosition } };
    }

    // Update shifted players
    const shiftedPlayer = playersToShift.find(shifted => shifted.playerId === p.id);
    if (shiftedPlayer) {
      const currentIndex = substitutePositions.indexOf(shiftedPlayer.currentPosition);
      const newPosition = substitutePositions[currentIndex + 1];
      return { ...p, stats: { ...p.stats, currentPositionKey: newPosition } };
    }

    return p;
  });
  
  // Create list of all affected players for highlighting
  const affectedPlayers = [targetPlayerId, ...playersToShift.map(p => p.playerId)];

  // Update roleGroups substitutePosition assignments when in same-role mode
  let updatedRoleGroups = null;
  let nextToSubOutIds = null;
  let newNextPlayerIdToSubOut = null;

  if (gameState.roleGroups) {
    updatedRoleGroups = {};
    for (const [role, group] of Object.entries(gameState.roleGroups)) {
      // Find which substitute position this group's sub player now occupies
      const subPlayerId = group.queue[group.queue.length - 1]; // Last in queue = substitute
      const newSubPosition = Object.keys(newFormation).find(
        pos => substitutePositions.includes(pos) && newFormation[pos] === subPlayerId
      );
      updatedRoleGroups[role] = {
        ...group,
        substitutePosition: newSubPosition || group.substitutePosition
      };
    }

    // Recalculate nextToSubOutIds sorted by new substitutePosition
    const nextSubOut = calculateNextToSubOutIds(updatedRoleGroups);
    nextToSubOutIds = nextSubOut.nextToSubOutIds;
    newNextPlayerIdToSubOut = nextSubOut.nextPlayerIdToSubOut;
  }

  return {
    ...gameState,
    formation: newFormation,
    allPlayers: newAllPlayers,
    playersToHighlight: affectedPlayers,
    ...(updatedRoleGroups ? {
      roleGroups: updatedRoleGroups,
      nextToSubOutIds,
      nextPlayerIdToSubOut: newNextPlayerIdToSubOut
    } : {})
  };
};

/**
 * Calculate the result of setting a field player as "next to go off" in same-role mode.
 * Manipulates roleGroups queues instead of rotationQueue.
 *
 * When substitutionCount >= totalGroups (all groups active): swap queue[0] and queue[1] in the player's group.
 * When substitutionCount < totalGroups:
 *   - Player's group IS active, player at queue[1]: within-group swap
 *   - Player's group is NOT active: cross-group activation (activate this group, deactivate another)
 */
export const calculateSetPlayerAsNextToGoOffSameRole = (gameState, playerId, substitutionCount) => {
  const { roleGroups } = gameState;
  if (!roleGroups) return gameState;

  const playerGroup = findPlayerRoleGroup(roleGroups, playerId);
  if (!playerGroup) return gameState;

  // Player must be at queue[0] or queue[1] (field player, not substitute)
  if (playerGroup.index > 1) return gameState;

  // Deep-copy roleGroups
  const newRoleGroups = {};
  for (const [role, group] of Object.entries(roleGroups)) {
    newRoleGroups[role] = { ...group, queue: [...group.queue] };
  }

  const totalGroups = Object.values(roleGroups).filter(g => g.queue && g.queue.length >= 2 && g.substitutePosition).length;

  if (substitutionCount >= totalGroups) {
    // All groups active: player must be at queue[1] to swap
    if (playerGroup.index !== 1) return gameState;
    const q = newRoleGroups[playerGroup.role].queue;
    [q[0], q[1]] = [q[1], q[0]];
  } else {
    // Initialize isScheduled flags if needed
    const flagged = ensureScheduledFlags(newRoleGroups, substitutionCount);
    if (flagged) Object.assign(newRoleGroups, flagged);

    const playerGroupIsScheduled = newRoleGroups[playerGroup.role].isScheduled !== false;

    if (playerGroupIsScheduled && playerGroup.index === 1) {
      // Within-group swap: change who's next off in this scheduled group
      const q = newRoleGroups[playerGroup.role].queue;
      [q[0], q[1]] = [q[1], q[0]];
    } else if (!playerGroupIsScheduled) {
      // Cross-group activation: schedule this group, unschedule another
      // Move player to queue[0] if at queue[1]
      if (playerGroup.index === 1) {
        const q = newRoleGroups[playerGroup.role].queue;
        [q[0], q[1]] = [q[1], q[0]];
      }
      // Player is now at queue[0] (or was already)

      // Schedule this group
      newRoleGroups[playerGroup.role].isScheduled = true;

      // Unschedule one currently-scheduled group (last in substitutePosition order)
      const scheduledGroups = Object.entries(newRoleGroups)
        .filter(([role, g]) => role !== playerGroup.role && g.isScheduled !== false && g.queue?.length >= 2 && g.substitutePosition)
        .sort(([, a], [, b]) => (a.substitutePosition || '').localeCompare(b.substitutePosition || ''));

      if (scheduledGroups.length > 0) {
        const [roleToUnschedule] = scheduledGroups[scheduledGroups.length - 1];
        newRoleGroups[roleToUnschedule].isScheduled = false;
      }
    } else {
      // Player is at queue[0] in an active group — already next off, nothing to do
      return gameState;
    }
  }

  const nextToSubOutResult = calculateNextToSubOutIds(newRoleGroups);

  // Reorder substitute positions so scheduled groups occupy top slots
  const reorderResult = reorderSubstitutePositionsForSchedule(
    newRoleGroups, gameState.formation, gameState.allPlayers
  );

  return {
    ...gameState,
    roleGroups: reorderResult ? reorderResult.newRoleGroups : newRoleGroups,
    ...nextToSubOutResult,
    ...(reorderResult ? { formation: reorderResult.newFormation, allPlayers: reorderResult.newAllPlayers } : {}),
    playersToHighlight: [playerId]
  };
};

/**
 * Calculate the result of removing a field player from "next to go off" in same-role mode.
 * Manipulates roleGroups queues instead of rotationQueue.
 *
 * When substitutionCount >= totalGroups (all groups scheduled): swap queue[0] and queue[1] in the player's group.
 * When substitutionCount < totalGroups: unschedule this group and schedule a currently-unscheduled group.
 */
export const calculateRemovePlayerFromNextToGoOffSameRole = (gameState, playerId, substitutionCount) => {
  const { roleGroups } = gameState;
  if (!roleGroups) return gameState;

  const playerGroup = findPlayerRoleGroup(roleGroups, playerId);
  if (!playerGroup || playerGroup.index !== 0) {
    // Player must be at queue[0] (currently next off) to be removed
    return gameState;
  }

  // Deep-copy roleGroups
  const newRoleGroups = {};
  for (const [role, group] of Object.entries(roleGroups)) {
    newRoleGroups[role] = { ...group, queue: [...group.queue] };
  }

  const totalGroups = Object.values(roleGroups).filter(g => g.queue && g.queue.length >= 2 && g.substitutePosition).length;

  if (substitutionCount >= totalGroups) {
    // All groups active: just swap within this player's group
    const q = newRoleGroups[playerGroup.role].queue;
    [q[0], q[1]] = [q[1], q[0]];
  } else {
    // Initialize isScheduled flags if needed
    const flagged = ensureScheduledFlags(newRoleGroups, substitutionCount);
    if (flagged) Object.assign(newRoleGroups, flagged);

    // Check there are unscheduled groups to schedule
    const unscheduledGroups = Object.entries(newRoleGroups)
      .filter(([role, g]) => role !== playerGroup.role && g.isScheduled === false && g.queue?.length >= 2 && g.substitutePosition)
      .sort(([, a], [, b]) => (a.substitutePosition || '').localeCompare(b.substitutePosition || ''));

    if (unscheduledGroups.length === 0) {
      // No unscheduled groups available — fall back to within-group swap
      const q = newRoleGroups[playerGroup.role].queue;
      [q[0], q[1]] = [q[1], q[0]];
    } else {
      // Cross-group unscheduling
      // Swap queue[0]/queue[1] in player's group (for future rescheduling order)
      const q = newRoleGroups[playerGroup.role].queue;
      [q[0], q[1]] = [q[1], q[0]];

      // Unschedule this group
      newRoleGroups[playerGroup.role].isScheduled = false;

      // Schedule the first unscheduled group (by substitutePosition order)
      const [roleToSchedule] = unscheduledGroups[0];
      newRoleGroups[roleToSchedule].isScheduled = true;
    }
  }

  const nextToSubOutResult = calculateNextToSubOutIds(newRoleGroups);

  // Reorder substitute positions so scheduled groups occupy top slots
  const reorderResult = reorderSubstitutePositionsForSchedule(
    newRoleGroups, gameState.formation, gameState.allPlayers
  );

  return {
    ...gameState,
    roleGroups: reorderResult ? reorderResult.newRoleGroups : newRoleGroups,
    ...nextToSubOutResult,
    ...(reorderResult ? { formation: reorderResult.newFormation, allPlayers: reorderResult.newAllPlayers } : {}),
    playersToHighlight: [playerId]
  };
};

/**
 * Calculate the result of setting next substitution target
 */
export const calculateNextSubstitutionTarget = (gameState, target, targetType) => {
  // This is a simple state update with no complex logic
  if (targetType === 'player') {
    const newNextPlayerIdToSubOut = gameState.formation[target];
    return {
      ...gameState,
      nextPlayerToSubOut: target,
      nextPlayerIdToSubOut: newNextPlayerIdToSubOut
    };
  }

  return gameState;
};

/**
 * Calculate the result of removing a player from the "next to go off" group
 * The player is moved to just after the last player in the "next to go off" group
 * The next player in the queue who is not already in the group takes their place
 */
export const calculateRemovePlayerFromNextToGoOff = (gameState, playerId, substitutionCount = 1) => {
  const { rotationQueue } = gameState;

  if (!rotationQueue || rotationQueue.length === 0) {
    return gameState;
  }

  // Get players in the "next to go off" group
  const nextNToSubOut = rotationQueue.slice(0, substitutionCount);

  if (!nextNToSubOut.includes(playerId)) {
    return gameState;
  }

  const queueWithoutPlayer = rotationQueue.filter(id => id !== playerId);
  const insertPosition = Math.min(substitutionCount, queueWithoutPlayer.length);

  const newQueue = [
    ...queueWithoutPlayer.slice(0, insertPosition),
    playerId,
    ...queueWithoutPlayer.slice(insertPosition)
  ];

  return {
    ...gameState,
    rotationQueue: newQueue,
    playersToHighlight: [playerId]
  };
};

/**
 * Calculate the result of setting a player as next to go off
 * The player is moved to the front of the rotation queue
 * The player previously last in the "next to go off" group is moved to just after the group
 */
export const calculateSetPlayerAsNextToGoOff = (gameState, playerId, substitutionCount = 1) => {
  const { rotationQueue } = gameState;

  if (!rotationQueue || rotationQueue.length === 0) {
    return gameState;
  }

  const nextNToSubOut = rotationQueue.slice(0, substitutionCount);

  if (nextNToSubOut.includes(playerId)) {
    return gameState;
  }

  const queueManager = createRotationQueue(rotationQueue, createPlayerLookupFunction(gameState.allPlayers));
  queueManager.initialize();
  queueManager.removePlayer(playerId);
  queueManager.addPlayer(playerId, 0);

  return {
    ...gameState,
    rotationQueue: queueManager.toArray(),
    playersToHighlight: [playerId]
  };
};
