import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import { ModalShell } from '../shared/ModalShell';
import { InstallAppCTA } from '../shared/InstallAppCTA';
import { LegalLinks } from '../legal/LegalLinks';
import { LoginForm } from './LoginForm';
import { SignupForm } from './SignupForm';
import { PasswordReset } from './PasswordReset';
import { EmailVerificationForm } from './EmailVerificationForm';

// Auth modes
export const AUTH_MODES = {
  LOGIN: 'login',
  SIGNUP: 'signup',
  RESET: 'reset',
  VERIFY: 'verify'
};

export function AuthModal({ isOpen, onClose, initialMode = AUTH_MODES.LOGIN, initialEmail = '' }) {
  const { t } = useTranslation('auth');
  const [currentMode, setCurrentMode] = useState(initialMode);
  const [emailContext, setEmailContext] = useState(initialEmail); // Email to carry between modes
  const [verificationEmail, setVerificationEmail] = useState(''); // Email for verification mode

  // Reset to initial mode when modal opens
  useEffect(() => {
    if (isOpen) {
      setCurrentMode(initialMode);
    }
  }, [isOpen, initialMode]);

  // Update email context when initialEmail changes
  useEffect(() => {
    if (initialEmail) {
      setEmailContext(initialEmail);
    }
  }, [initialEmail]);

  // Clear email context when modal closes
  useEffect(() => {
    if (!isOpen) {
      setEmailContext('');
    }
  }, [isOpen]);

  if (!isOpen) return null;

  const handleSwitchToReset = (email = '') => {
    setEmailContext(email);
    setCurrentMode(AUTH_MODES.RESET);
  };

  const handleSwitchToLogin = () => {
    setEmailContext(''); // Clear email when going back to login
    setCurrentMode(AUTH_MODES.LOGIN);
  };

  const handleSwitchToSignup = () => {
    setEmailContext(''); // Clear email when switching to signup
    setCurrentMode(AUTH_MODES.SIGNUP);
  };

  const handleSwitchToVerify = (email = '') => {
    setVerificationEmail(email);
    setCurrentMode(AUTH_MODES.VERIFY);
  };

  const renderForm = () => {
    switch (currentMode) {
      case AUTH_MODES.LOGIN:
        return (
          <LoginForm
            onSwitchToSignup={handleSwitchToSignup}
            onSwitchToReset={handleSwitchToReset}
            onSwitchToVerify={handleSwitchToVerify}
            onClose={onClose}
            initialEmail={emailContext}
          />
        );
      case AUTH_MODES.SIGNUP:
        return (
          <SignupForm
            onSwitchToLogin={handleSwitchToLogin}
            onClose={onClose}
            initialEmail={emailContext}
          />
        );
      case AUTH_MODES.RESET:
        return (
          <PasswordReset
            onSwitchToLogin={handleSwitchToLogin}
            onClose={onClose}
            initialEmail={emailContext}
          />
        );
      case AUTH_MODES.VERIFY:
        return (
          <EmailVerificationForm
            email={verificationEmail}
            onSuccess={onClose}
            onSwitchToLogin={handleSwitchToLogin}
            onClose={onClose}
          />
        );
      default:
        return null;
    }
  };

  const modalTitle = currentMode === AUTH_MODES.LOGIN ? t('authModal.titles.login')
    : currentMode === AUTH_MODES.SIGNUP ? t('authModal.titles.signup')
    : currentMode === AUTH_MODES.RESET ? t('authModal.titles.reset')
    : t('authModal.titles.verify');

  return (
    <ModalShell
      title={modalTitle}
      onClose={onClose}
      className="max-h-[90vh] overflow-y-auto"
    >
        {renderForm()}
        <InstallAppCTA />
        <LegalLinks className="justify-center mt-4 text-xs" />
    </ModalShell>
  );
}

// Hook for managing auth modal state.
//
// All returned methods are wrapped in useCallback and the returned object is
// memoized so that consumers' useEffect dependencies stay stable across
// renders. Without this, App.js effects depending on `authModal` re-fire every
// render and can pop the password-reset modal in unrelated flows.
export function useAuthModal(initialMode = AUTH_MODES.LOGIN) {
  const [isOpen, setIsOpen] = useState(false);
  const [mode, setMode] = useState(initialMode);
  const [initialEmail, setInitialEmail] = useState('');

  const openModal = useCallback((authMode = initialMode, email = '') => {
    setMode(authMode);
    setInitialEmail(email);
    setIsOpen(true);
  }, [initialMode]);

  const closeModal = useCallback(() => {
    setIsOpen(false);
    setInitialEmail('');
  }, []);

  const switchMode = useCallback((newMode) => {
    setMode(newMode);
  }, []);

  const openLogin = useCallback((email = '') => openModal(AUTH_MODES.LOGIN, email), [openModal]);
  const openSignup = useCallback((email = '') => openModal(AUTH_MODES.SIGNUP, email), [openModal]);
  const openReset = useCallback(() => openModal(AUTH_MODES.RESET), [openModal]);

  return useMemo(() => ({
    isOpen,
    mode,
    initialEmail,
    openModal,
    closeModal,
    switchMode,
    openLogin,
    openSignup,
    openReset
  }), [isOpen, mode, initialEmail, openModal, closeModal, switchMode, openLogin, openSignup, openReset]);
}