import { useState, useEffect } from 'react';
import { PREFERENCE_KEYS, DEFAULT_PREFERENCES } from '../types/preferences';

/**
 * Hook to load the trackGoalScorer and trackAssists team preferences.
 *
 * @param {Object} options
 * @param {string|null} options.teamId - Current team ID
 * @param {Function} options.loadTeamPreferences - Function to load team preferences
 * @param {Object} [options.prefResult] - Already-loaded preferences object (skips fetching)
 * @returns {{ trackGoalScorer: boolean, trackAssists: boolean }}
 */
export function useTrackingPreferences({ teamId, loadTeamPreferences, prefResult }) {
  const [trackGoalScorer, setTrackGoalScorer] = useState(
    DEFAULT_PREFERENCES[PREFERENCE_KEYS.TRACK_GOAL_SCORER]
  );
  const [trackAssists, setTrackAssists] = useState(
    DEFAULT_PREFERENCES[PREFERENCE_KEYS.TRACK_ASSISTS]
  );

  useEffect(() => {
    const apply = (prefs) => {
      const rawScorer = prefs?.[PREFERENCE_KEYS.TRACK_GOAL_SCORER];
      const rawAssists = prefs?.[PREFERENCE_KEYS.TRACK_ASSISTS];
      setTrackGoalScorer(
        rawScorer === undefined ? DEFAULT_PREFERENCES[PREFERENCE_KEYS.TRACK_GOAL_SCORER] : rawScorer
      );
      setTrackAssists(
        rawAssists === undefined ? DEFAULT_PREFERENCES[PREFERENCE_KEYS.TRACK_ASSISTS] : rawAssists
      );
    };

    if (prefResult !== undefined && prefResult !== null) {
      apply(prefResult);
      return;
    }

    async function fetchPreferences() {
      if (!teamId || !loadTeamPreferences) return;
      try {
        apply(await loadTeamPreferences(teamId));
      } catch (err) {
        console.warn('[useTrackingPreferences] Failed to load preferences, using defaults', err);
      }
    }
    fetchPreferences();
  }, [teamId, loadTeamPreferences, prefResult]);

  // trackAssists is a sub-option of trackGoalScorer: never report assists as
  // tracked when goal-scorer tracking is off, even if the stored prefs disagree.
  return { trackGoalScorer, trackAssists: trackGoalScorer && trackAssists };
}
