import { useCallback, useEffect, useState } from 'react';
import {
  POLICY_ACK_CHANGE_EVENT,
  isPolicyAcknowledged,
  savePolicyAck,
} from '../utils/policyAcknowledgment';
import { POLICY_LAST_UPDATED } from '../constants/legalUrls';
import { STORAGE_KEYS } from '../constants/storageKeys';

export function usePolicyAcknowledgment() {
  const [acknowledged, setAcknowledged] = useState(() => isPolicyAcknowledged(POLICY_LAST_UPDATED));

  useEffect(() => {
    if (typeof window === 'undefined') return undefined;
    const sync = () => setAcknowledged(isPolicyAcknowledged(POLICY_LAST_UPDATED));
    const handleStorage = (event) => {
      if (event.key !== STORAGE_KEYS.POLICY_ACKNOWLEDGMENT) return;
      sync();
    };
    window.addEventListener('storage', handleStorage);
    window.addEventListener(POLICY_ACK_CHANGE_EVENT, sync);
    return () => {
      window.removeEventListener('storage', handleStorage);
      window.removeEventListener(POLICY_ACK_CHANGE_EVENT, sync);
    };
  }, []);

  const acknowledge = useCallback(() => {
    savePolicyAck(POLICY_LAST_UPDATED);
    setAcknowledged(true);
  }, []);

  return {
    needsAcknowledgment: !acknowledged,
    acknowledge,
  };
}
