/**
 * Team management tab identifiers
 */
export const TAB_VIEWS = {
  OVERVIEW: 'overview',
  ROSTER: 'roster',
  LOANS: 'loans',
  ACCESS: 'access',
  CONNECTORS: 'connectors',
  PREFERENCES: 'preferences'
};

export const TEAM_MANAGEMENT_BASE_PATH = '/team';

const TEAM_MANAGEMENT_TAB_VALUES = new Set(Object.values(TAB_VIEWS));

export const isValidTeamManagementTab = (tab) => TEAM_MANAGEMENT_TAB_VALUES.has(tab);

export const normalizeTeamManagementPath = (path) => {
  const basePath = typeof path === 'string' ? path.split(/[?#]/, 1)[0] : '';
  return basePath.replace(/\/+$/, '') || '/';
};

export const isTeamManagementPath = (path) => {
  const normalizedPath = normalizeTeamManagementPath(path);

  return (
    normalizedPath === TEAM_MANAGEMENT_BASE_PATH ||
    /^\/team\/[^/]+$/i.test(normalizedPath)
  );
};

export const getTeamManagementTabFromPath = (path) => {
  const normalizedPath = normalizeTeamManagementPath(path);

  if (!normalizedPath.startsWith(`${TEAM_MANAGEMENT_BASE_PATH}/`)) {
    return null;
  }

  const tab = normalizedPath.slice(TEAM_MANAGEMENT_BASE_PATH.length + 1);
  return isValidTeamManagementTab(tab) ? tab : null;
};

export const getTeamManagementPath = (tab = TAB_VIEWS.OVERVIEW) => {
  const safeTab = isValidTeamManagementTab(tab) ? tab : TAB_VIEWS.OVERVIEW;
  return `${TEAM_MANAGEMENT_BASE_PATH}/${safeTab}`;
};
