import { getModeDefinition } from '../../constants/gameModes';

/**
 * Merge a saved pre-plan formation onto a fresh recommendation formation,
 * preserving uniqueness by *swapping* players rather than overwriting cells.
 *
 * Why a swap and not an overwrite? Saved pre-plans can encode positions for
 * players who are no longer eligible (inactive, removed from the squad,
 * dropped by the recommendation). A naive per-position overwrite can leave
 * the same player at two positions while another player goes missing —
 * because saved-position X falls back to the recommendation's pick A, but
 * saved-position Y still claims A. Swapping permutes the player multiset, so
 * uniqueness is invariant by construction.
 *
 * Saved positions are processed in a deterministic order (goalie → field
 * positions in mode order → substitute positions) so two runs with the same
 * input produce the same output.
 *
 * @param {Object} params
 * @param {Object} params.savedFormation — the persisted pre-plan formation
 *   ({ position → playerId }).
 * @param {Object} params.recommendationFormation — the unique baseline
 *   formation produced by the period recommendation engine.
 * @param {Array}  params.allPlayers — current player roster, used for
 *   active/inactive checks.
 * @param {Array<string>} params.selectedSquadIds — player IDs currently
 *   selected for the match.
 * @param {Object} params.teamConfig — formation/format/squadSize.
 * @returns {{ formation: Object, notices: Array<{ position: string,
 *   reason: 'unavailable'|'displaced'|'corrupt', playerId: string|null }> }}
 *   The merged formation and a list of notices describing saved positions
 *   that could not be honoured. When the saved formation itself is malformed
 *   (duplicate assignments), the recommendation is returned unchanged with a
 *   single `corrupt` notice.
 */
export const mergePrePlanFormation = ({
  savedFormation,
  recommendationFormation,
  allPlayers,
  selectedSquadIds,
  teamConfig
}) => {
  if (!savedFormation || !recommendationFormation) {
    return { formation: recommendationFormation || {}, notices: [] };
  }

  // Reject malformed saved data up front: if the persisted formation already
  // contains a duplicate, we cannot safely permute it onto the recommendation.
  const savedAssignedIds = Object.values(savedFormation).filter(Boolean);
  if (new Set(savedAssignedIds).size !== savedAssignedIds.length) {
    return {
      formation: { ...recommendationFormation },
      notices: [{ position: null, reason: 'corrupt', playerId: null }]
    };
  }

  const playerById = new Map((allPlayers || []).map(p => [p.id, p]));
  const squadSet = new Set(selectedSquadIds || []);
  const isAvailable = (playerId) => {
    if (!playerId) return false;
    if (squadSet.size > 0 && !squadSet.has(playerId)) return false;
    const player = playerById.get(playerId);
    return Boolean(player) && player.stats?.isInactive !== true;
  };

  // Deterministic processing order: goalie → field positions in
  // mode-defined order → substitute positions.
  const modeDefinition = getModeDefinition(teamConfig);
  const fieldPositions = modeDefinition?.fieldPositions || [];
  const substitutePositions = modeDefinition?.substitutePositions || [];
  const orderedPositions = ['goalie', ...fieldPositions, ...substitutePositions];
  const isFieldPosition = (pos) => fieldPositions.includes(pos);

  const merged = { ...recommendationFormation };
  const notices = [];

  for (const position of orderedPositions) {
    if (!Object.prototype.hasOwnProperty.call(savedFormation, position)) {
      continue;
    }
    const savedPlayerId = savedFormation[position];
    if (!savedPlayerId) {
      // The saved plan didn't assign this slot (e.g. user left a sub blank).
      // Leave the recommendation's pick in place.
      continue;
    }

    if (!isAvailable(savedPlayerId)) {
      notices.push({ position, reason: 'unavailable', playerId: savedPlayerId });
      continue;
    }

    if (merged[position] === savedPlayerId) {
      continue;
    }

    // Locate the player in the merged formation. They must be somewhere if
    // they're in the squad and the recommendation is well-formed.
    const currentPos = orderedPositions.find(p => merged[p] === savedPlayerId);
    if (!currentPos) {
      // Player is available but the recommendation didn't include them
      // anywhere (e.g. a goalie change pushed them off, or the squad shape
      // changed). Refuse the override; surfacing this is up to the caller.
      notices.push({ position, reason: 'displaced', playerId: savedPlayerId });
      continue;
    }

    // Guardrail: refuse swaps that would shove an inactive player from a
    // substitute slot onto the field. This protects against the case where
    // the recommendation engine carefully routed an inactive player to the
    // substitute slot, and the saved plan asks us to pull a different
    // player into that same substitute slot — a naive swap would push the
    // inactive player into whatever field position the saved player came
    // from. Swapping field↔field positions of two active players is fine.
    const displacedPlayerId = merged[position];
    if (
      !isAvailable(displacedPlayerId) &&
      !isFieldPosition(position) &&
      isFieldPosition(currentPos)
    ) {
      notices.push({ position, reason: 'displaced', playerId: savedPlayerId });
      continue;
    }

    // Swap: permutes the player multiset, so uniqueness is invariant.
    merged[position] = savedPlayerId;
    merged[currentPos] = displacedPlayerId;
  }

  return { formation: merged, notices };
};
