import { createClient } from '@supabase/supabase-js';
import { NavigatorLockAcquireTimeoutError } from '@supabase/auth-js';
import { Preferences } from '@capacitor/preferences';
import { isNativePlatform } from '../utils/platform';
import { storageBackend } from '../utils/storageBackend';

// Supabase client configuration
const supabaseUrl = process.env.REACT_APP_SUPABASE_URL;
const supabaseAnonKey = process.env.REACT_APP_SUPABASE_ANON_KEY;

// Check if we're in a test environment
const isTestEnvironment = process.env.NODE_ENV === 'test';

// Use dummy values for testing to prevent test failures
const testUrl = 'https://test.supabase.co';
const testKey = 'test-anon-key';


// Only throw error in non-test environments
if (!supabaseUrl || !supabaseAnonKey) {
  if (!isTestEnvironment) {
    throw new Error(
      'Missing Supabase environment variables. Please check that REACT_APP_SUPABASE_URL and REACT_APP_SUPABASE_ANON_KEY are set in your .env.local file.'
    );
  }
}

// Serialize auth operations within this tab without touching navigator.locks,
// which has documented orphaned-lock hangs after tab idle that stall getSession/
// refreshSession for 10+ seconds (supabase-js#2013, #2111, #1517). We keep intra-
// tab ordering by chaining on a promise; cross-tab coordination is handled by
// auth-js's BroadcastChannel sync and isn't relied on elsewhere in the app.
//
// acquireTimeout semantics:
//   - 0: fail-fast — throw NavigatorLockAcquireTimeoutError if another op is in
//        flight. Auth-js uses this to avoid double-refresh, which would trip
//        Supabase's refresh-token-reuse protection (10s window).
//   - -1 or positive: queue behind any in-flight op. We don't honor positive
//        timeouts precisely — the queue is cheap and in-memory, and auth-js's
//        common paths use -1. Queuing a positive-timeout caller is strictly
//        safer than failing it.
let authLockInFlight = 0;
let authLockChain = Promise.resolve();
const inMemoryAuthLock = async (name, acquireTimeout, fn) => {
  if (acquireTimeout === 0 && authLockInFlight > 0) {
    // auth-js checks for `isAcquireTimeout` in its catch blocks (see
    // LockAcquireTimeoutError in @supabase/auth-js/lib/locks.ts) to silently
    // swallow fail-fast lock misses; mirror that contract so the 30s auto-
    // refresh ticker doesn't surface as an uncaught error.
    throw new NavigatorLockAcquireTimeoutError(`Acquiring an exclusive lock '${name}' immediately failed`);
  }

  authLockInFlight++;
  const run = authLockChain.then(fn, fn);
  authLockChain = run.catch(() => {});
  try {
    return await run;
  } finally {
    authLockInFlight--;
  }
};

// On native, route auth session storage through @capacitor/preferences so
// it survives Android low-memory eviction of the WebView's localStorage.
// Reads come straight from Preferences (always durable truth); writes go
// through storageBackend's awaited variants, which update the in-memory cache
// AND return a single Preferences write promise — Supabase awaits that, giving
// us token durability without double-writing.
const nativeAuthStorage = isNativePlatform()
  ? {
      // Reads bypass storageBackend's in-memory cache on purpose. Auth tokens
      // can be mutated from contexts the cache doesn't observe (Realtime worker,
      // BroadcastChannel sync, future cold-start handlers); going straight to
      // Preferences guarantees Supabase always sees persisted truth. Supabase
      // already holds the resolved session in memory after the first read, so
      // the bridge cost is not on a hot path. Don't "optimise" this to use
      // storageBackend.getItem.
      getItem: async (key) => {
        const { value } = await Preferences.get({ key });
        return value;
      },
      setItem: (key, value) => storageBackend.setItemAwaitable(key, value),
      removeItem: (key) => storageBackend.removeItemAwaitable(key),
    }
  : undefined;

// Create and export the Supabase client
export const supabase = createClient(
  supabaseUrl || testUrl,
  supabaseAnonKey || testKey,
  {
  auth: {
    // Configure auth settings
    autoRefreshToken: true,
    persistSession: true,
    detectSessionInUrl: true,
    flowType: 'pkce', // Use PKCE flow for enhanced security
    debug: false, // Disable Supabase auth debug logging
    lock: inMemoryAuthLock,
    ...(nativeAuthStorage ? { storage: nativeAuthStorage } : {}),
  },
  // Configure database settings
  db: {
    schema: 'public',
  },
  // Configure global headers
  global: {
    headers: {
      'X-Client-Info': 'dif-f16-6-coach-app',
    },
  },
  // Use a Web Worker for Realtime heartbeats so browser tab throttling
  // (which suspends JS timers in inactive tabs) cannot kill the WebSocket
  // connection. Without this, Realtime subscriptions silently disconnect
  // after the tab has been idle for an extended period.
  realtime: {
    worker: typeof Worker !== 'undefined',
  },
});

// Helper function to get the current user session
export const getCurrentSession = async () => {
  const { data: { session }, error } = await supabase.auth.getSession();
  if (error) {
    console.error('Error getting session:', error.message);
    return null;
  }
  return session;
};

// Helper function to get the current user
export const getCurrentUser = async () => {
  const { data: { user }, error } = await supabase.auth.getUser();
  if (error) {
    console.error('Error getting user:', error.message);
    return null;
  }
  return user;
};

// Export default for easier imports
export default supabase;
