/**
 * View Constants
 * Centralizes view routing strings for the application
 */

export const VIEWS = {
  CONFIG: 'config',
  PERIOD_SETUP: 'periodSetup',
  GAME: 'game',
  STATS: 'stats',
  STATISTICS: 'statistics',
  PROFILE: 'profile',
  TACTICAL_BOARD: 'tacticalBoard',
  TEAM_MANAGEMENT: 'teamManagement',
  TEAM_MATCHES: 'teamMatches',
  PLAN_MATCHES: 'planMatches',
  LIVE_MATCH: 'liveMatch',
  PLAYER_RANKING: 'playerRanking'
};

// Coaching-flow views gated at the routing level. LIVE_MATCH and TACTICAL_BOARD
// are intentionally excluded so they stay publicly viewable (the live link for
// /live/{matchId}, and the tactical board for anonymous users). Views that
// self-gate with their own auth guard (STATISTICS, TEAM_MANAGEMENT) are
// intentionally omitted here.
// Contract: every new coaching view MUST either be added here OR implement its
// own auth guard — omitting both silently makes the view public.
export const COACHING_VIEWS = new Set([
  VIEWS.CONFIG,
  VIEWS.PERIOD_SETUP,
  VIEWS.GAME,
  VIEWS.STATS,
  VIEWS.TEAM_MATCHES,
  VIEWS.PLAN_MATCHES,
  VIEWS.PLAYER_RANKING,
  VIEWS.PROFILE,
]);
