import React, { useEffect, useRef, useState } from 'react';
import PropTypes from 'prop-types';
import { useTranslation } from 'react-i18next';
import { Button } from './UI';
import { useCookieConsent } from '../../hooks/useCookieConsent';
import { useBrowserBackIntercept } from '../../hooks/useBrowserBackIntercept';
import { CONSENT_STATUS } from '../../utils/consentPersistence';

export function CookieConsentBanner({ isReady = true }) {
  const { t } = useTranslation('common');
  const { status, accept, reject } = useCookieConsent();
  const { pushNavigationState, removeFromNavigationStack } = useBrowserBackIntercept();

  const shouldShow = isReady && status === CONSENT_STATUS.UNSET;
  const [dismissed, setDismissed] = useState(false);
  const [visible, setVisible] = useState(false);
  const backWiredRef = useRef(false);
  const dialogRef = useRef(null);

  useEffect(() => {
    if (!shouldShow || dismissed) return undefined;
    const id = requestAnimationFrame(() => setVisible(true));
    return () => cancelAnimationFrame(id);
  }, [shouldShow, dismissed]);

  useEffect(() => {
    if (visible && dialogRef.current) {
      dialogRef.current.focus();
    }
  }, [visible]);

  useEffect(() => {
    if (!shouldShow || dismissed) return undefined;
    if (backWiredRef.current) return undefined;
    pushNavigationState(() => setDismissed(true), 'cookie-consent');
    backWiredRef.current = true;
    return () => {
      if (backWiredRef.current) {
        removeFromNavigationStack();
        backWiredRef.current = false;
      }
    };
  }, [shouldShow, dismissed, pushNavigationState, removeFromNavigationStack]);

  if (!shouldShow || dismissed) return null;

  const clearBackWire = () => {
    if (backWiredRef.current) {
      removeFromNavigationStack();
      backWiredRef.current = false;
    }
  };

  const handleAccept = () => {
    clearBackWire();
    accept();
  };

  const handleReject = () => {
    clearBackWire();
    reject();
  };

  return (
    <div
      ref={dialogRef}
      role="dialog"
      aria-modal="true"
      aria-label={t('cookieConsent.title')}
      aria-describedby="cookie-consent-body"
      tabIndex={-1}
      data-testid="cookie-consent-banner"
      className={`fixed bottom-0 inset-x-0 sm:bottom-4 sm:right-4 sm:left-auto sm:max-w-md z-50 pb-[env(safe-area-inset-bottom)] transition-transform duration-300 ease-out outline-none ${visible ? 'translate-y-0' : 'translate-y-full'}`}
    >
      <div className="bg-slate-800 border border-slate-600 rounded-t-lg sm:rounded-lg shadow-2xl p-5 m-0 sm:m-2">
        <h3 className="text-sky-300 font-semibold text-base mb-2">
          {t('cookieConsent.title')}
        </h3>
        <p id="cookie-consent-body" className="text-slate-200 text-sm mb-4">
          {t('cookieConsent.body')}
        </p>
        <div className="flex flex-col sm:flex-row gap-2 sm:justify-end">
          <Button
            onClick={handleReject}
            variant="secondary"
            className="w-full sm:w-auto sm:order-1"
          >
            {t('cookieConsent.reject')}
          </Button>
          <Button
            onClick={handleAccept}
            variant="primary"
            className="w-full sm:w-auto sm:order-2"
          >
            {t('cookieConsent.accept')}
          </Button>
        </div>
      </div>
    </div>
  );
}

CookieConsentBanner.propTypes = {
  isReady: PropTypes.bool,
};
