// Public legal document routes and URLs. Imported by the app UI and by M8
// store-submission metadata. Both routes are reachable without sign-in.

export const PUBLIC_BASE = (process.env.PUBLIC_URL || '').replace(/\/$/, '');

// Contact address shown in the app; keep in sync with docs/legal/*.md.
export const SUPPORT_EMAIL = 'niclas.berggren.ab@gmail.com';

// The "Last updated" date in docs/legal/privacy-policy.md and terms-of-service.md
// (ISO YYYY-MM-DD). Bump this whenever either policy materially changes so the
// in-app update notice resurfaces. Keep both docs and this constant in sync.
export const POLICY_LAST_UPDATED = '2026-05-29';

export const LEGAL_DOCS = Object.freeze({
  privacy: {
    slug: 'privacy',
    path: '/legal/privacy',
    markdownFile: 'privacy-policy.md',
    titleKey: 'common:legal.privacyTitle',
  },
  terms: {
    slug: 'terms',
    path: '/legal/terms',
    markdownFile: 'terms-of-service.md',
    titleKey: 'common:legal.termsTitle',
  },
});

export const PRIVACY_PATH = LEGAL_DOCS.privacy.path;
export const TERMS_PATH = LEGAL_DOCS.terms.path;

export function getLegalUrl(docPath) {
  if (PUBLIC_BASE) return `${PUBLIC_BASE}${docPath}`;
  return docPath;
}

// Resolve a pathname (e.g. '/legal/privacy') to its doc definition, or null.
export function getLegalDocByPath(pathname) {
  if (!pathname) return null;
  const clean = pathname.replace(/\/$/, '');
  return Object.values(LEGAL_DOCS).find((doc) => doc.path === clean) || null;
}
