import React, { useEffect, useMemo, useRef, useState } from 'react';
import PropTypes from 'prop-types';
import { useTranslation } from 'react-i18next';
import { Button } from './UI';
import { LegalLinks } from '../legal/LegalLinks';
import { usePolicyAcknowledgment } from '../../hooks/usePolicyAcknowledgment';
import { useBrowserBackIntercept } from '../../hooks/useBrowserBackIntercept';
import { POLICY_LAST_UPDATED } from '../../constants/legalUrls';

// Top-anchored so it never overlaps the bottom-anchored CookieConsentBanner.
// Dismissing (button or browser back) counts as acknowledging the current
// policy version, so it won't reappear until the "Last updated" date changes.
export function PolicyUpdateBanner({ isReady = true }) {
  const { t, i18n } = useTranslation('common');
  const { needsAcknowledgment, acknowledge } = usePolicyAcknowledgment();
  const { pushNavigationState, removeFromNavigationStack } = useBrowserBackIntercept();

  const shouldShow = isReady && needsAcknowledgment;
  const [mounted, setMounted] = useState(shouldShow);
  const [visible, setVisible] = useState(false);
  const backWiredRef = useRef(false);
  const dialogRef = useRef(null);
  const formattedPolicyDate = useMemo(() => {
    const date = new Date(`${POLICY_LAST_UPDATED}T00:00:00`);
    return new Intl.DateTimeFormat(i18n.language, {
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    }).format(date);
  }, [i18n.language]);

  useEffect(() => {
    if (shouldShow) {
      setMounted(true);
      const id = requestAnimationFrame(() => setVisible(true));
      return () => cancelAnimationFrame(id);
    }

    setVisible(false);
    const id = setTimeout(() => setMounted(false), 300);
    return () => clearTimeout(id);
  }, [shouldShow]);

  useEffect(() => {
    if (visible && dialogRef.current) {
      dialogRef.current.focus();
    }
  }, [visible]);

  useEffect(() => {
    if (!shouldShow) return undefined;
    if (backWiredRef.current) return undefined;
    pushNavigationState(() => acknowledge(), 'policy-update');
    backWiredRef.current = true;
    return () => {
      if (backWiredRef.current) {
        removeFromNavigationStack();
        backWiredRef.current = false;
      }
    };
  }, [shouldShow, acknowledge, pushNavigationState, removeFromNavigationStack]);

  if (!mounted) return null;

  const handleAcknowledge = () => {
    if (backWiredRef.current) {
      removeFromNavigationStack();
      backWiredRef.current = false;
    }
    acknowledge();
  };

  return (
    <div
      ref={dialogRef}
      role="region"
      aria-label={t('policyUpdate.title')}
      aria-describedby="policy-update-body"
      tabIndex={-1}
      data-testid="policy-update-banner"
      className={`fixed top-0 inset-x-0 sm:top-4 sm:right-4 sm:left-auto sm:max-w-md z-50 pt-[env(safe-area-inset-top)] transition-transform duration-300 ease-out outline-none ${visible ? 'translate-y-0' : '-translate-y-full'}`}
    >
      <div className="bg-slate-800 border border-slate-600 rounded-b-lg sm:rounded-lg shadow-2xl p-5 m-0 sm:m-2">
        <h3 className="text-sky-300 font-semibold text-base mb-2">
          {t('policyUpdate.title')}
        </h3>
        <p id="policy-update-body" className="text-slate-200 text-sm mb-3">
          {t('policyUpdate.body', { date: formattedPolicyDate })}
        </p>
        <LegalLinks className="mb-4" />
        <div className="flex flex-col sm:flex-row gap-2 sm:justify-end">
          <Button
            onClick={handleAcknowledge}
            variant="primary"
            className="w-full sm:w-auto"
          >
            {t('policyUpdate.acknowledge')}
          </Button>
        </div>
      </div>
    </div>
  );
}

PolicyUpdateBanner.propTypes = {
  isReady: PropTypes.bool,
};
