/**
 * Match Configuration Service
 * 
 * Consolidates match configuration save/update operations to eliminate code duplication.
 * Provides a unified interface for handling match configuration across different flows:
 * - Period setup navigation
 * - Configuration saving
 * - Match configuration updates
 */

import {
  createMatch,
  formatMatchDataFromGameState,
  updateExistingMatch,
  saveInitialMatchConfig,
  logMatchCreatedEvent
} from './matchStateManager';
import { DEFAULT_VENUE_TYPE } from '../constants/matchVenues';
import { DEFAULT_MATCH_DIFFICULTY } from '../constants/matchDifficulties';
import { FORMATS, getMinimumPlayersForFormat, getMaximumPlayersForFormat } from '../constants/teamConfiguration';

const pendingMatchConfigurationCreates = new Map();

function buildMatchConfigurationIdempotencyKey({ matchData, initialConfig, selectedSquadIds }) {
  return JSON.stringify({ matchData, initialConfig, selectedSquadIds }, (_, v) =>
    v && typeof v === 'object' && !Array.isArray(v)
      ? Object.fromEntries(Object.entries(v).sort())
      : v
  );
}

/**
 * Transforms team configuration to the database format using flat structure
 * @param {Object} teamConfig - The team configuration object
 * @returns {Object} Team config for database storage (same as runtime format)
 */
export function formatTeamConfigForDatabase(teamConfig) {
  return {
    format: teamConfig.format,
    formation: teamConfig.formation,
    squadSize: teamConfig.squadSize
  };
}

/**
 * Creates the initial configuration object for database storage
 * @param {Object} params - Configuration parameters
 * @param {Object} params.formation - Formation object
 * @param {Object} params.teamConfig - Team configuration
 * @param {Object} params.matchData - Match data
 * @param {string} params.matchType - Match type
 * @param {string} params.venueType - Venue type (home, away, neutral)
 * @param {string} params.opponentTeam - Opponent team name
 * @param {number} params.numPeriods - Number of periods
 * @param {number} params.periodDurationMinutes - Period duration
 * @param {string} params.captainId - Captain player ID
 * @param {string|null} params.fixedRoleGroup - Fixed role group selection for supported substitution modes
 * @param {string|null} params.substitutionLogic - Selected substitution mode (rotate_roles, same_role_period, same_role_match)
 * @param {Object} params.periodGoalieIds - Period goalie assignments
 * @param {Array} params.selectedSquadIds - Selected squad player IDs
 * @returns {Object} Initial configuration object
 */
export function createInitialConfiguration(params) {
  const {
    formation,
    teamConfig,
    matchData,
    matchType,
    venueType = DEFAULT_VENUE_TYPE,
    difficulty = DEFAULT_MATCH_DIFFICULTY,
    opponentTeam,
    numPeriods,
    periodDurationMinutes,
    captainId,
    fixedRoleGroup = null,
    substitutionLogic = null,
    periodGoalieIds,
    selectedSquadIds
  } = params;

  const transformedTeamConfig = formatTeamConfigForDatabase(teamConfig);

  return {
    formation: formation,
    teamConfig: transformedTeamConfig,
    matchConfig: {
      format: matchData.format,
      matchType: matchType,
      venueType: venueType,
      difficulty: difficulty,
      opponentTeam: opponentTeam,
      periods: numPeriods,
      periodDurationMinutes: periodDurationMinutes,
      captainId: captainId,
      fixedRoleGroup,
      substitutionLogic
    },
    periodGoalies: periodGoalieIds,
    squadSelection: selectedSquadIds
  };
}

/**
 * Handles the creation of a new match configuration
 * @param {Object} params - Configuration parameters
 * @param {Object} params.matchData - Formatted match data
 * @param {Array} params.allPlayers - All players array
 * @param {Object} params.initialConfig - Initial configuration object
 * @param {Function} params.setCurrentMatchId - Function to set current match ID
 * @param {Function} params.setMatchCreated - Function to set match creation attempted flag
 * @returns {Promise<{success: boolean, matchId?: string, error?: string}>}
 */
export async function saveNewMatchConfiguration(params) {
  const {
    matchData,
    allPlayers,
    selectedSquadIds = [],
    initialConfig,
    setCurrentMatchId,
    setCurrentMatchShareCode,
    setMatchCreated,
    idempotencyKey: rawKey
  } = params;
  const idempotencyKey = rawKey || buildMatchConfigurationIdempotencyKey({
    matchData,
    initialConfig,
    selectedSquadIds
  });

  if (pendingMatchConfigurationCreates.has(idempotencyKey)) {
    return pendingMatchConfigurationCreates.get(idempotencyKey);
  }

  const createPromise = (async () => {
    try {
      // CREATE FLOW: No existing match, create new one
      const createResult = await createMatch(
        matchData,
        allPlayers,
        selectedSquadIds,
        { state: 'pending' }
      );

      if (!createResult.success) {
        console.warn('⚠️ Failed to create pending match:', createResult.error);
        return {
          success: false,
          error: createResult.error
        };
      }

      // The match row now exists, so it must stay tracked (currentMatchId /
      // matchCreated) from here on regardless of whether the config save below
      // succeeds -- callers like handleStartPeriodSetup don't gate navigation
      // on this result and would otherwise proceed into an untracked match
      // with no DB row at all if the config save failed transiently.
      setCurrentMatchId(createResult.matchId);
      setCurrentMatchShareCode(createResult.shareCode || null);
      setMatchCreated(true); // Prevent duplicate match creation

      // Log match_created event (non-blocking)
      logMatchCreatedEvent(createResult.matchId, {
        ownTeamName: matchData.teamName || null,
        opponentTeamName: matchData.opponent || null,
        totalPeriods: matchData.periods || null,
        periodDurationMinutes: matchData.periodDurationMinutes || null
      }).catch(error => {
        console.warn('⚠️ Failed to log match_created event:', error);
      });

      // Save complete initial configuration for resuming. Awaited (unlike the
      // match record insert) so callers that DO check the result (Save
      // Configuration / Get Live Link) can surface a real failure instead of
      // it being silently swallowed. If it fails, the match row is kept
      // (not rolled back) -- ConfigurationScreen's Resume Setup falls back to
      // the match row's own columns via createFallbackResumeDataFromMatch,
      // and the next save attempt retries this write via the UPDATE flow.
      const configSaveResult = await saveInitialMatchConfig(createResult.matchId, initialConfig);

      if (!configSaveResult.success) {
        console.warn('⚠️ Failed to save initial match config:', configSaveResult.error);
        return {
          success: false,
          matchId: createResult.matchId,
          shareCode: createResult.shareCode || null,
          error: configSaveResult.error
        };
      }

      return {
        success: true,
        matchId: createResult.matchId,
        shareCode: createResult.shareCode || null
      };
    } catch (error) {
      console.error('❌ Error creating new match configuration:', error);
      return {
        success: false,
        error: `Failed to create match configuration: ${error.message}`
      };
    }
  })();

  pendingMatchConfigurationCreates.set(idempotencyKey, createPromise);

  try {
    return await createPromise;
  } finally {
    pendingMatchConfigurationCreates.delete(idempotencyKey);
  }
}

/**
 * Handles the update of an existing match configuration
 * @param {Object} params - Configuration parameters
 * @param {string} params.matchId - Current match ID
 * @param {Object} params.matchData - Formatted match data
 * @param {Object} params.initialConfig - Initial configuration object
 * @returns {Promise<{success: boolean, error?: string}>}
 */
export async function updateMatchConfiguration(params) {
  const { matchId, matchData, initialConfig } = params;

  try {
    // UPDATE FLOW: Match already exists, update it with new configuration
    const updateResult = await updateExistingMatch(matchId, matchData);

    if (!updateResult.success) {
      console.warn('⚠️ Failed to update pending match:', updateResult.error);
      // Deliberately no matchId here: the row-level update itself failed
      // (e.g. 0-row -- the match was concurrently discarded or moved out of
      // planned/pending), so this matchId is proven invalid. Callers must
      // not fall back to a previously-known matchId for this case.
      return {
        success: false,
        error: updateResult.error
      };
    }

    // Update initial configuration for resuming. Awaited so a failure here is
    // surfaced to the caller instead of being silently swallowed -- otherwise
    // match.opponent/format/etc. can drift out of sync with initial_config,
    // leaving Resume Setup unable to restore the match.
    const configSaveResult = await saveInitialMatchConfig(matchId, initialConfig);

    if (!configSaveResult.success) {
      console.warn('⚠️ Failed to update initial match config:', configSaveResult.error);
      // The row itself was successfully updated above -- matchId is still
      // valid here, unlike the updateResult failure branch.
      return {
        success: false,
        matchId,
        shareCode: updateResult.shareCode,
        error: configSaveResult.error
      };
    }

    return {
      success: true,
      matchId,
      shareCode: updateResult.shareCode
    };
  } catch (error) {
    console.error('❌ Error updating match configuration:', error);
    return {
      success: false,
      error: `Failed to update match configuration: ${error.message}`
    };
  }
}

/**
 * Main service function that handles match configuration save/update operations
 * Consolidates the logic from handleStartPeriodSetup, handleSaveConfiguration, and saveMatchConfiguration
 * @param {Object} params - Configuration parameters
 * @param {Object} params.teamConfig - Team configuration
 * @param {string} params.selectedFormation - Selected formation
 * @param {number} params.numPeriods - Number of periods
 * @param {number} params.periodDurationMinutes - Period duration
 * @param {string} params.opponentTeam - Opponent team name
 * @param {string} params.captainId - Captain player ID
 * @param {string|null} params.fixedRoleGroup - Fixed role group selection for supported substitution modes
 * @param {string|null} params.substitutionLogic - Selected substitution mode (rotate_roles, same_role_period, same_role_match)
 * @param {string} params.matchType - Match type
 * @param {string} params.venueType - Venue type (home, away, neutral)
 * @param {Object} params.formation - Formation object
 * @param {Object} params.periodGoalieIds - Period goalie assignments
 * @param {Array} params.selectedSquadIds - Selected squad player IDs
 * @param {Array} params.allPlayers - All players array
 * @param {Object} params.currentTeam - Current team object
 * @param {string} params.currentMatchId - Current match ID (if exists)
 * @param {boolean} params.matchCreated - Whether match creation was attempted
 * @param {Function} params.setCurrentMatchId - Function to set current match ID
 * @param {Function} params.setMatchCreated - Function to set match creation attempted flag
 * @returns {Promise<{success: boolean, matchId?: string, message?: string, error?: string}>}
 */
export async function saveMatchConfiguration(params) {
  const {
    teamConfig,
    selectedFormation,
    numPeriods,
    periodDurationMinutes,
    opponentTeam,
    captainId,
    fixedRoleGroup = null,
    substitutionLogic = null,
    matchType,
    venueType = DEFAULT_VENUE_TYPE,
    difficulty,
    formation,
    periodGoalieIds,
    selectedSquadIds,
    allPlayers,
    currentTeam,
    currentMatchId,
    matchCreated,
    setCurrentMatchId,
    setCurrentMatchShareCode,
    setMatchCreated
  } = params;

  // Skip save if no team context
  if (!currentTeam?.id) {
    return {
      success: false,
      error: "Team context required for saving configuration."
    };
  }

  try {
    // Prepare match data for database
    const matchData = formatMatchDataFromGameState({
      teamConfig,
      selectedFormation,
      periods: numPeriods,
      periodDurationMinutes,
      opponentTeam: opponentTeam?.trim() || null,
      captainId,
      matchType,
      venueType,
      difficulty,
      teamName: currentTeam.club?.name || null
    }, currentTeam.id);

    // Create initial configuration object
    const initialConfig = createInitialConfiguration({
      formation,
      teamConfig,
      matchData,
      matchType,
      venueType,
      difficulty,
      opponentTeam,
      numPeriods,
      periodDurationMinutes,
      captainId,
      fixedRoleGroup,
      substitutionLogic,
      periodGoalieIds,
      selectedSquadIds
    });

    let result;
    
    if (currentMatchId && matchCreated) {
      // Update existing match
      result = await updateMatchConfiguration({
        matchId: currentMatchId,
        matchData,
        initialConfig
      });
    } else {
      // Create new match
      result = await saveNewMatchConfiguration({
        matchData,
        allPlayers,
        selectedSquadIds,
        initialConfig,
        setCurrentMatchId,
        setCurrentMatchShareCode,
        setMatchCreated
      });
    }

    if (result.success) {
      // result.matchId is always populated on success (the new id from the
      // CREATE path, or the same matchId param on the UPDATE path) -- no
      // `|| currentMatchId` fallback needed here, unlike the failure branch
      // below where that fallback would be unsafe.
      return {
        success: true,
        matchId: result.matchId,
        shareCode: result.shareCode || null,
        message: `Configuration ${currentMatchId ? 'updated' : 'saved'} successfully`
      };
    } else {
      return {
        success: false,
        // No `|| currentMatchId` fallback here: on a real row-level UPDATE
        // failure (e.g. the match was concurrently discarded), currentMatchId
        // is the ID that was just proven invalid, and falling back to it
        // would hand callers a stale/dead match ID. saveNewMatchConfiguration
        // and updateMatchConfiguration already include matchId themselves
        // whenever the row is still genuinely valid (CREATE succeeded but
        // config save failed / UPDATE succeeded but config save failed) --
        // result.matchId alone is the source of truth here.
        matchId: result.matchId,
        shareCode: result.shareCode || null,
        error: result.error
      };
    }
  } catch (error) {
    console.error('❌ Error managing match configuration:', error);
    return {
      success: false,
      error: `Failed to save configuration: ${error.message}`
    };
  }
}

/**
 * Validation function to check if configuration is complete
 * @param {Object} params - Validation parameters
 * @param {Array} params.selectedSquadIds - Selected squad player IDs
 * @param {number} params.numPeriods - Number of periods
 * @param {Object} params.periodGoalieIds - Period goalie assignments
 * @param {string} [params.format] - Team format identifier used to derive minimum players
 * @param {number} [params.maxPlayersAllowed] - Maximum players permitted (defaults to global max)
 * @returns {{isValid: boolean, error?: string}} Validation result
 */
export function validateConfiguration(params) {
  const {
    selectedSquadIds = [],
    numPeriods = 0,
    periodGoalieIds = {},
    format = FORMATS.FORMAT_5V5,
    maxPlayersAllowed
  } = params;

  const minimumPlayersRequired = getMinimumPlayersForFormat(format);
  const formatMaximum = getMaximumPlayersForFormat(format);
  const normalizedMax = typeof maxPlayersAllowed === 'number' ? maxPlayersAllowed : formatMaximum;
  const maximumPlayersAllowed = Math.max(
    minimumPlayersRequired,
    Math.min(formatMaximum, normalizedMax)
  );

  // Validate squad size
  if (selectedSquadIds.length < minimumPlayersRequired || selectedSquadIds.length > maximumPlayersAllowed) {
    return {
      isValid: false,
      error: `Please select between ${minimumPlayersRequired} and ${maximumPlayersAllowed} players for the squad.`
    };
  }

  // Validate goalie assignments
  const goaliesAssigned = Array.from({ length: numPeriods }, (_, i) => periodGoalieIds[i + 1]).every(Boolean);
  if (!goaliesAssigned) {
    return {
      isValid: false,
      error: "Please assign a goalie for each period."
    };
  }

  return { isValid: true };
}

