import { useEffect, useMemo, useRef, useState } from 'react';
import { getMatchPlayerAvailability } from '../services/matchIntegrationService';

export function useProviderAvailability(matches) {
  const [availabilityByMatch, setAvailabilityByMatch] = useState({});
  const [providerAvailabilityLoading, setProviderAvailabilityLoading] = useState(true);
  const lastFetchedKeyRef = useRef(null);

  // For planned matches linked to an upcoming_match, use upcomingMatchId for the DB query
  const matchIdsKey = useMemo(
    () => {
      if (!Array.isArray(matches)) {
        return '';
      }

      const uniqueIds = Array.from(
        new Set(
          matches
            .map((match) => match?.upcomingMatchId || match?.id)
            .filter(Boolean)
            .map(String)
        )
      );

      uniqueIds.sort();
      return JSON.stringify(uniqueIds);
    },
    [matches]
  );

  // Map upcoming_match.id → match.id so results can be re-keyed after fetch.
  // Stored in a ref so the effect can read the latest mapping without re-running
  // whenever the matches array identity changes between renders.
  const upcomingToMatchIdMapRef = useRef({});
  upcomingToMatchIdMapRef.current = useMemo(() => {
    if (!Array.isArray(matches)) return {};
    const map = {};
    matches.forEach((match) => {
      if (match?.upcomingMatchId && match?.id) {
        map[String(match.upcomingMatchId)] = String(match.id);
      }
    });
    return map;
  }, [matches]);

  // When a match newly gains an upcomingMatchId — typically right after the
  // user first plans an upcoming match, when handlePlanMatch flips the id
  // from upcoming → planned and records the original upcoming id — re-key any
  // already-fetched availability under the new (planned) id. Without this,
  // the data would still be keyed by the upcoming id while the render path
  // looks it up by the planned id, so provider-driven indicators would vanish
  // until the next page load.
  useEffect(() => {
    const map = upcomingToMatchIdMapRef.current;
    if (!map || Object.keys(map).length === 0) return;
    setAvailabilityByMatch((prev) => {
      if (!prev || Object.keys(prev).length === 0) return prev;
      let didChange = false;
      const next = {};
      Object.entries(prev).forEach(([key, value]) => {
        const remapped = map[key] || key;
        if (remapped !== key) didChange = true;
        next[remapped] = value;
      });
      return didChange ? next : prev;
    });
  }, [matches]);

  useEffect(() => {
    const matchIds = matchIdsKey ? JSON.parse(matchIdsKey) : [];

    if (matchIds.length === 0) {
      setAvailabilityByMatch((prev) => (Object.keys(prev).length === 0 ? prev : {}));
      setProviderAvailabilityLoading(false);
      lastFetchedKeyRef.current = matchIdsKey;
      return;
    }

    let isActive = true;
    setProviderAvailabilityLoading(true);

    getMatchPlayerAvailability(matchIds)
      .then((result) => {
        if (!isActive) return;

        if (result?.success) {
          const raw = result.availabilityByMatch || {};
          // Re-key: replace upcoming_match_id keys with match.id where a mapping exists
          const reKeyed = {};
          Object.entries(raw).forEach(([upcomingId, players]) => {
            const matchId = upcomingToMatchIdMapRef.current[upcomingId] || upcomingId;
            reKeyed[matchId] = players;
          });
          setAvailabilityByMatch(reKeyed);
        } else {
          setAvailabilityByMatch((prev) => (Object.keys(prev).length === 0 ? prev : {}));
        }
      })
      .catch((error) => {
        if (!isActive) return;
        console.error('Failed to load provider availability:', error);
        setAvailabilityByMatch((prev) => (Object.keys(prev).length === 0 ? prev : {}));
      })
      .finally(() => {
        if (!isActive) return;
        lastFetchedKeyRef.current = matchIdsKey;
        setProviderAvailabilityLoading(false);
      });

    return () => {
      isActive = false;
    };
  }, [matchIdsKey]); // upcomingToMatchIdMap read via ref — no need in deps

  const providerUnavailableByMatch = useMemo(() => {
    const unavailableByMatch = {};

    Object.entries(availabilityByMatch || {}).forEach(([matchId, players]) => {
      const providerUnavailableIds = Object.entries(players || {})
        .filter(([, status]) => (
          status?.availability === 'unavailable' || status?.response === 'declined'
        ))
        .map(([playerId]) => playerId);

      if (providerUnavailableIds.length > 0) {
        unavailableByMatch[matchId] = providerUnavailableIds;
      }
    });

    return unavailableByMatch;
  }, [availabilityByMatch]);

  const providerResponseByMatch = useMemo(() => {
    const responseByMatch = {};
    Object.entries(availabilityByMatch || {}).forEach(([matchId, players]) => {
      const responses = {};
      Object.entries(players || {}).forEach(([playerId, status]) => {
        if (status?.response) {
          responses[playerId] = status.response;
        }
      });
      if (Object.keys(responses).length > 0) {
        responseByMatch[matchId] = responses;
      }
    });
    return responseByMatch;
  }, [availabilityByMatch]);

  const providerInvitedByMatch = useMemo(() => {
    const invitedByMatch = {};
    Object.entries(availabilityByMatch || {}).forEach(([matchId, players]) => {
      const invitedIds = Object.entries(players || {})
        .filter(([, status]) => status?.inviteStatus === 'invited')
        .map(([playerId]) => playerId);

      if (invitedIds.length > 0) {
        invitedByMatch[matchId] = invitedIds;
      }
    });
    return invitedByMatch;
  }, [availabilityByMatch]);

  const isLoading = providerAvailabilityLoading || lastFetchedKeyRef.current !== matchIdsKey;
  return { providerUnavailableByMatch, providerResponseByMatch, providerInvitedByMatch, providerAvailabilityLoading: isLoading };
}
