import React, { useState, useEffect, useMemo } from 'react';
import PropTypes from 'prop-types';
import { Calendar, MapPin, Trophy, History, PlusCircle } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { useTeam } from '../../contexts/TeamContext';
import { getFinishedMatches } from '../../services/matchStateManager';
import { filterMatchesByCriteria } from '../../utils/matchFilterUtils';
import { getOutcomeBadgeClasses, getOutcomeLabel, getMatchTypeBadgeClasses, getFormatBadgeClasses, getDifficultyBadgeClasses } from '../../utils/badgeUtils';
import { getMatchDifficultyOptions } from '../../constants/matchDifficulties';
import { MatchFiltersPanel } from './MatchFiltersPanel';
import { useStatsFilters } from '../../hooks/useStatsFilters';
import { Button } from '../shared/UI';
import { useIsAtLeastSm } from '../../hooks/useIsAtLeastSm';
import { formatResponsiveMatchDate } from './utils/matchDateFormat';
import { StatsLoadingState } from './shared/StatsLoadingState';
import { StatsErrorState } from './shared/StatsErrorState';
import { Card } from '../shared/Card';
import { SectionHeader } from '../shared/SectionHeader';
import { CoachChip } from '../shared/CoachChip';

export function MatchHistoryTab({ onMatchSelect, onCreateMatch, startDate, endDate, refreshKey = 0 }) {
  const { t, i18n } = useTranslation('statistics');
  const { currentTeam } = useTeam();
  const [matches, setMatches] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const {
    typeFilter,
    outcomeFilter,
    venueFilter,
    opponentFilter,
    playerFilter,
    formatFilter,
    difficultyFilter,
    setTypeFilter,
    setOutcomeFilter,
    setVenueFilter,
    setOpponentFilter,
    setPlayerFilter,
    setFormatFilter,
    setDifficultyFilter,
    clearFilters
  } = useStatsFilters();
  const difficultyLabelByValue = useMemo(() => {
    return getMatchDifficultyOptions(t).reduce((acc, option) => {
      acc[option.value] = option.label;
      return acc;
    }, {});
  }, [t]);
  const isAtLeastSm = useIsAtLeastSm();

  // Fetch match data from database
  useEffect(() => {
    async function fetchMatches() {
      if (!currentTeam?.id) {
        setMatches([]);
        return;
      }

      setLoading(true);
      setError(null);

      const result = await getFinishedMatches(currentTeam.id, startDate, endDate);

      if (result.success) {
        setMatches(result.matches || []);
      } else {
        setError(result.error || t('matchHistory.errorDetails'));
        setMatches([]);
      }

      setLoading(false);
    }

    fetchMatches();
  }, [currentTeam?.id, startDate, endDate, refreshKey, t]);

  const clearAllFilters = clearFilters;

  const filteredMatches = useMemo(() => filterMatchesByCriteria(matches, {
    typeFilter,
    outcomeFilter,
    venueFilter,
    opponentFilter,
    playerFilter,
    formatFilter,
    difficultyFilter,
    startDate,
    endDate
  }), [matches, typeFilter, outcomeFilter, venueFilter, opponentFilter, playerFilter, formatFilter, difficultyFilter, startDate, endDate]);

  // Only show difficulty badges when the visible list contains mixed levels —
  // a single-level list is self-evident and badges would just be noise.
  const hasMixedDifficulty = useMemo(() => {
    const seen = new Set();
    for (const m of filteredMatches) {
      if (m.difficulty) seen.add(m.difficulty);
      if (seen.size >= 2) return true;
    }
    return false;
  }, [filteredMatches]);

  const formatScore = (match) => {
    // Always show team goals first (left), opponent goals second (right)
    return `${match.goalsScored}-${match.goalsConceded}`;
  };

  const formatTime = (dateString) => {
    const date = new Date(dateString);
    return date.toLocaleTimeString('en-US', {
      hour: '2-digit',
      minute: '2-digit',
      hour12: false
    });
  };

  // Show loading state
  if (loading) {
    return <StatsLoadingState message={t('matchHistory.loading')} />;
  }

  // Show error state
  if (error) {
    return <StatsErrorState title={t('matchHistory.error')} message={error} />;
  }

  return (
    <div className="space-y-6">
      {/* Filters */}
      <MatchFiltersPanel
        matches={matches}
        typeFilter={typeFilter}
        outcomeFilter={outcomeFilter}
        venueFilter={venueFilter}
        opponentFilter={opponentFilter}
        playerFilter={playerFilter}
        formatFilter={formatFilter}
        difficultyFilter={difficultyFilter}
        onTypeFilterChange={setTypeFilter}
        onOutcomeFilterChange={setOutcomeFilter}
        onVenueFilterChange={setVenueFilter}
        onOpponentFilterChange={setOpponentFilter}
        onPlayerFilterChange={setPlayerFilter}
        onFormatFilterChange={setFormatFilter}
        onDifficultyFilterChange={setDifficultyFilter}
        onClearAllFilters={clearAllFilters}
      />

      {/* Match List */}
      <Card>
        <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between mb-4">
          <SectionHeader title={t('matchHistory.title')} icon={History} />
          {onCreateMatch && (
            <Button onClick={onCreateMatch} Icon={PlusCircle} size="sm">
              {t('matchHistory.addMatch')}
            </Button>
          )}
        </div>
        <p className="text-slate-400 text-sm mb-4">
          {t('matchHistory.matchesFound', { count: filteredMatches.length })}
        </p>
        <div className="space-y-3">
          {filteredMatches.map((match) => (
            <div
              key={match.id}
              data-testid="match-row"
              className="bg-slate-800 p-4 rounded-lg border border-slate-600 hover:bg-slate-750 transition-colors cursor-pointer"
              onClick={() => onMatchSelect(match.id)}
            >
              <div className="flex items-start justify-between gap-4">
                {/* Left Section: Date & Match Info */}
                <div className="flex items-start gap-4 flex-1 min-w-0">
                  {/* Date and Time */}
                  <div className="flex items-center gap-2 text-slate-400 shrink-0">
                    <Calendar className="h-4 w-4" />
                    <div className="text-sm">
                      {/* Monospace keeps the ISO digits column-aligned on sm+ screens.
                          On narrow screens the compact, proportional date ("Sep 17")
                          reads better unaligned, so font-mono is intentionally dropped
                          for the date while the time below keeps it. */}
                      <div className={isAtLeastSm ? 'font-mono' : ''}>{formatResponsiveMatchDate(match.date, { isAtLeastSm, language: i18n.language })}</div>
                      <div className="font-mono text-xs opacity-75">{formatTime(match.date)}</div>
                    </div>
                  </div>

                  {/* Match Info */}
                  <div className="flex-1 min-w-0">
                    {/* Opponent Name */}
                    <div className="text-slate-200 font-semibold text-lg truncate">
                      {match.opponent}
                    </div>

                    {/* Match Details Row */}
                    <div className="flex items-center gap-3 mt-1">
                      {/* Venue Type - Hidden on extra narrow screens */}
                      {isAtLeastSm && (
                        <div className="flex items-center gap-1 text-slate-400">
                          <MapPin className="h-3 w-3" />
                          <span className="text-sm">
                            {match.venueType === 'home' ? t('matchHistory.venues.home') : match.venueType === 'neutral' ? t('matchHistory.venues.neutral') : t('matchHistory.venues.away')}
                          </span>
                        </div>
                      )}

                      {/* Match Type - Hidden on extra narrow screens */}
                      {isAtLeastSm && (
                        <span className={getMatchTypeBadgeClasses(match.type)}>{match.type}</span>
                      )}

                      {/* Match Format - Hidden on extra narrow screens */}
                      {isAtLeastSm && match.format && (
                        <span className={getFormatBadgeClasses(match.format)}>{match.format}</span>
                      )}

                      {/* Difficulty - Hidden on extra narrow screens; only shown when list has mixed levels */}
                      {isAtLeastSm && hasMixedDifficulty && match.difficulty && (
                        <span className={getDifficultyBadgeClasses(match.difficulty)}>
                          {difficultyLabelByValue[match.difficulty] || match.difficulty}
                        </span>
                      )}

                      {/* Coach who ran the match */}
                      {match.ownedByName && (
                        <CoachChip name={match.ownedByName} size="sm" />
                      )}
                    </div>
                  </div>
                </div>

                {/* Right Section: Score & Result */}
                <div className="text-right shrink-0">
                  <div className="text-2xl font-mono font-bold text-slate-100 mb-1">
                    {formatScore(match)}
                  </div>
                  {/* Win/Loss/Draw - Shown on all screen sizes, right-aligned
                      under the score. On narrow screens this is the only outcome
                      indicator (the details-row badges are hidden there). */}
                  <span className={getOutcomeBadgeClasses(match.outcome)}>
                    {getOutcomeLabel(match.outcome, t)}
                  </span>
                </div>
              </div>
            </div>
          ))}

          {filteredMatches.length === 0 && (
            <div className="p-8 text-center text-slate-400">
              <Trophy className="h-12 w-12 mx-auto mb-4 opacity-50" />
              <p>{t('matchHistory.noMatchesFiltered')}</p>
              <p className="text-sm mt-1">{t('matchHistory.adjustFilters')}</p>
            </div>
          )}
        </div>
      </Card>
    </div>
  );
}

MatchHistoryTab.propTypes = {
  onMatchSelect: PropTypes.func.isRequired,
  onCreateMatch: PropTypes.func,
  startDate: PropTypes.instanceOf(Date),
  endDate: PropTypes.instanceOf(Date),
  refreshKey: PropTypes.number
};
