// Async IP-geolocation fallback for language detection. Calls detect-region
// Edge Function, maps country → language, caches result for 7 days.

import { supabase } from '../lib/supabase';
import { createPersistenceManager } from './persistenceManager';
import { STORAGE_KEYS } from '../constants/storageKeys';
import { languageForCountry } from '../constants/languageMapping';
import { SUPPORTED_LANGUAGES } from './languageDetection';

const CACHE_TTL_MS = 7 * 24 * 60 * 60 * 1000; // 7 days
const DEFAULT_TIMEOUT_MS = 1500;

const geoCachePersistence = createPersistenceManager(STORAGE_KEYS.GEO_LANGUAGE_CACHE, {
  country: null,
  fetchedAt: null
});

const readCachedCountry = () => {
  const cached = geoCachePersistence.loadState();
  if (!cached || !cached.country || typeof cached.fetchedAt !== 'number') {
    return null;
  }
  if (Date.now() - cached.fetchedAt > CACHE_TTL_MS) {
    return null;
  }
  return cached.country;
};

const writeCachedCountry = (country) => {
  if (typeof country !== 'string' || !country) return;
  geoCachePersistence.saveState({
    country: country.toUpperCase(),
    fetchedAt: Date.now()
  });
};

const withTimeout = (promise, timeoutMs) =>
  Promise.race([
    promise,
    new Promise((_, reject) => setTimeout(() => reject(new Error('timeout')), timeoutMs))
  ]);

const invokeDetectRegion = async () => {
  const { data, error } = await supabase.functions.invoke('detect-region', {
    method: 'GET'
  });
  if (error) throw error;
  if (!data || typeof data.country !== 'string') return null;
  return data.country;
};

export async function fetchGeoLanguage({
  supportedLanguages = SUPPORTED_LANGUAGES,
  timeoutMs = DEFAULT_TIMEOUT_MS
} = {}) {
  // 1. Try cached country first (fast path on return visits)
  const cachedCountry = readCachedCountry();
  if (cachedCountry) {
    const lang = languageForCountry(cachedCountry);
    if (lang && supportedLanguages.includes(lang)) {
      return lang;
    }
    return null;
  }

  // 2. Otherwise, call the Edge Function
  let country = null;
  try {
    country = await withTimeout(invokeDetectRegion(), timeoutMs);
  } catch {
    return null;
  }

  if (!country) return null;
  writeCachedCountry(country);

  const lang = languageForCountry(country);
  if (lang && supportedLanguages.includes(lang)) {
    return lang;
  }
  return null;
}
