/**
 * Utilities for cleaning up storage from previous sessions
 * Preserves user preferences while clearing session-specific data.
 * Goes through storageBackend so the same logic works on web (localStorage)
 * and native (@capacitor/preferences).
 */

import {
  PRESERVED_STORAGE_KEYS,
  SESSION_STORAGE_KEYS,
  SESSION_STORAGE_PREFIXES,
  DEPRECATED_KEYS
} from '../constants/storageKeys';
import { storageBackend } from './storageBackend';

// Export preserved keys for backward compatibility
const PRESERVED_KEYS = PRESERVED_STORAGE_KEYS;

/**
 * Key patterns that should be cleaned up (session-specific data)
 * Includes exact match keys and prefix patterns
 */
const CLEANUP_PATTERNS = [
  ...SESSION_STORAGE_KEYS,
  ...SESSION_STORAGE_PREFIXES,
  // Include deprecated/legacy keys for cleanup
  ...Object.values(DEPRECATED_KEYS),
];

/**
 * Check if a localStorage key should be preserved
 */
function shouldPreserveKey(key) {
  return PRESERVED_KEYS.includes(key);
}

/**
 * Check if a localStorage key matches cleanup patterns
 */
function shouldCleanupKey(key) {
  return CLEANUP_PATTERNS.some(pattern => {
    if (pattern.endsWith('-')) {
      // Pattern matching (e.g., 'sport-wizard-timer-' matches 'sport-wizard-timer-12345')
      return key.startsWith(pattern);
    } else {
      // Exact match
      return key === pattern;
    }
  });
}

/**
 * Clean up storage from previous sessions while preserving user preferences.
 * Should be called immediately after successful sign-in.
 */
export function cleanupPreviousSession() {
  try {
    const keysToRemove = [];
    const allKeys = storageBackend.keys();
    const preservedKeys = [];
    const unknownKeys = [];

    for (const key of allKeys) {
      if (!key) continue;

      if (shouldPreserveKey(key)) {
        preservedKeys.push(key);
        continue;
      }

      if (shouldCleanupKey(key)) {
        keysToRemove.push(key);
      } else {
        unknownKeys.push(key);
      }
    }

    keysToRemove.forEach(key => {
      try {
        storageBackend.removeItem(key);
      } catch (error) {
        console.warn(`Failed to remove storage key ${key}:`, error);
      }
    });

    return {
      success: true,
      removedKeys: keysToRemove,
      preservedKeys: PRESERVED_KEYS.filter(key => storageBackend.getItem(key) !== null)
    };

  } catch (error) {
    console.warn('Failed to clean up storage:', error);
    return {
      success: false,
      error: error.message
    };
  }
}

/**
 * Get information about what would be cleaned up (for debugging)
 */
export function getCleanupInfo() {
  const info = {
    toPreserve: [],
    toCleanup: [],
    unknown: []
  };
  
  try {
    for (const key of storageBackend.keys()) {
      if (!key) continue;

      if (shouldPreserveKey(key)) {
        info.toPreserve.push(key);
      } else if (shouldCleanupKey(key)) {
        info.toCleanup.push(key);
      } else {
        info.unknown.push(key);
      }
    }
  } catch (error) {
    console.warn('Failed to analyze storage:', error);
  }
  
  return info;
}

/**
 * Clear ALL storage (for emergency use only).
 * On native, the storageBackend preserves META_KEYS_TO_PRESERVE (e.g. the migration flag).
 */
export function clearAllLocalStorage() {
  try {
    const keyCount = storageBackend.length;
    storageBackend.clear();

    return { success: true, clearedKeys: keyCount };
  } catch (error) {
    console.warn('Failed to clear all storage:', error);
    return { success: false, error: error.message };
  }
}
