import React, { createContext, useCallback, useContext, useEffect, useMemo, useRef, useState } from 'react';
import PropTypes from 'prop-types';

const DEFAULT_DURATION_MS = 3000;

const ToastContext = createContext({
  showSuccess: () => {},
  showWarning: () => {}
});

const variantClasses = {
  success: 'bg-emerald-900/80 border-emerald-600 text-emerald-200 shadow-emerald-500/50',
  warning: 'bg-amber-900/80 border-amber-600 text-amber-200 shadow-amber-500/50'
};

const variantIconPrefix = {
  success: '✓',
  warning: '⚠'
};

export function ToastProvider({ children }) {
  const [toast, setToast] = useState(null);
  const timeoutRef = useRef(null);

  const clearTimer = useCallback(() => {
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
      timeoutRef.current = null;
    }
  }, []);

  const show = useCallback((variant, message, options) => {
    if (!message) return;
    clearTimer();
    setToast({ variant, message });
    const duration = options?.durationMs ?? DEFAULT_DURATION_MS;
    timeoutRef.current = setTimeout(() => {
      setToast(null);
      timeoutRef.current = null;
    }, duration);
  }, [clearTimer]);

  useEffect(() => () => clearTimer(), [clearTimer]);

  const value = useMemo(() => ({
    showSuccess: (message, options) => show('success', message, options),
    showWarning: (message, options) => show('warning', message, options)
  }), [show]);

  const classes = toast ? variantClasses[toast.variant] ?? variantClasses.success : '';
  const prefix = toast ? variantIconPrefix[toast.variant] ?? '' : '';

  return (
    <ToastContext.Provider value={value}>
      {children}
      {toast && (
        <div
          role="status"
          aria-live="polite"
          className={`fixed top-[max(env(safe-area-inset-top),1rem)] left-1/2 transform -translate-x-1/2 z-[60] px-6 py-3 backdrop-blur-sm border rounded-lg shadow-2xl ${classes}`}
        >
          <p className="text-sm font-medium">
            {prefix && <span aria-hidden="true">{prefix} </span>}
            {toast.message}
          </p>
        </div>
      )}
    </ToastContext.Provider>
  );
}

ToastProvider.propTypes = {
  children: PropTypes.node
};

export function useToast() {
  return useContext(ToastContext);
}
