import { VIEWS } from '../constants/viewConstants';
import {
  TAB_VIEWS,
  getTeamManagementPath,
  isTeamManagementPath,
  isValidTeamManagementTab
} from '../constants/teamManagementTabs';
import { createPersistenceManager } from '../utils/persistenceManager';
import { STORAGE_KEYS } from '../constants/storageKeys';
import { createManagedViewRoutingHook } from './createPathRoutingHook';

const tabPersistence = createPersistenceManager(
  STORAGE_KEYS.TEAM_MANAGEMENT_ACTIVE_TAB,
  { tab: TAB_VIEWS.OVERVIEW }
);

const getPersistedTeamManagementPath = () => {
  const stored = tabPersistence.loadState();
  const tab = stored?.tab;
  return getTeamManagementPath(isValidTeamManagementTab(tab) ? tab : TAB_VIEWS.OVERVIEW);
};

export const useTeamManagementRouting = createManagedViewRoutingHook({
  navigateTarget: VIEWS.TEAM_MANAGEMENT,
  ownsPath: isTeamManagementPath,
  getViewPath: getPersistedTeamManagementPath
});
