import React from 'react';
import PropTypes from 'prop-types';
import { useTranslation } from 'react-i18next';
import { ChecklistBox } from './ChecklistBox';
import { RELATABLE_ROLES } from '../../utils/relationshipUtils';

export function RelatedMembersSelect({ members, selectedIds, onToggle, disabled, ariaLabel }) {
  const { t } = useTranslation('team');
  const items = (members || [])
    .filter((m) => RELATABLE_ROLES.includes(m.role) && m.user?.id)
    .map((m) => ({
      id: m.user.id,
      label: m.user?.name || '?',
      sublabel: `(${m.role})`
    }));

  return (
    <ChecklistBox
      items={items}
      selectedIds={selectedIds}
      onToggle={onToggle}
      disabled={disabled}
      ariaLabel={ariaLabel}
      emptyText={t('relatedMembers.noMembersToLink')}
    />
  );
}

RelatedMembersSelect.propTypes = {
  members: PropTypes.arrayOf(PropTypes.shape({
    role: PropTypes.string,
    user: PropTypes.shape({
      id: PropTypes.string,
      name: PropTypes.string
    })
  })),
  selectedIds: PropTypes.arrayOf(PropTypes.string).isRequired,
  onToggle: PropTypes.func.isRequired,
  disabled: PropTypes.bool,
  ariaLabel: PropTypes.string.isRequired,
};
