import React from 'react';
import PropTypes from 'prop-types';
import { useTranslation } from 'react-i18next';
import { Portal } from '../../shared/Portal';
import { findPlayerById } from '../../../utils/playerUtils';
import { DRAG_ACTION_TYPES } from '../../../game/handlers/dragSubstitutionHandlers';

const DRAG_ACTION_LABEL_KEYS = {
  [DRAG_ACTION_TYPES.SUBSTITUTE]: { key: 'drag.actionSubstitute', fallback: 'Substitute' },
  [DRAG_ACTION_TYPES.SWAP]: { key: 'drag.actionSwap', fallback: 'Swap' },
  [DRAG_ACTION_TYPES.GOALIE_SWITCH]: { key: 'drag.actionGoalie', fallback: 'Make goalie' }
};

// Tilt applied to the floating ghost while dragging. Shared so the post-drop
// FLIP animation on the source card can start at the exact same rotation.
export const GHOST_TILT_DEG = -1.2;

function ResolvedGhost({
  ghostStyle,
  badgeLabel,
  badgeTone,
  positionLabel,
  playerName
}) {
  return (
    <div
      data-testid="drag-ghost"
      className="pointer-events-none select-none rounded-md border-2 border-sky-300 bg-slate-800/95 text-sky-100 shadow-[0_18px_36px_-10px_rgba(2,132,199,0.65),0_0_0_1px_rgba(125,211,252,0.55)] px-2 py-1.5"
      style={ghostStyle}
    >
      <div className="text-[12px] font-semibold leading-4 truncate text-sky-100/95">
        {positionLabel}
      </div>
      <div className="text-[13px] font-medium leading-4 truncate text-sky-50">
        {playerName}
      </div>
      {badgeLabel && (
        <div
          className={`absolute -top-2 -right-2 rounded-full px-2 py-0.5 text-[10px] font-bold uppercase tracking-wide shadow-md ${
            badgeTone === 'eligible'
              ? 'bg-sky-400 text-slate-900'
              : 'bg-rose-500 text-white'
          }`}
          data-testid="drag-ghost-badge"
        >
          {badgeLabel}
        </div>
      )}
    </div>
  );
}

ResolvedGhost.propTypes = {
  ghostStyle: PropTypes.object.isRequired,
  badgeLabel: PropTypes.string,
  badgeTone: PropTypes.oneOf(['eligible', 'ineligible']),
  positionLabel: PropTypes.string,
  playerName: PropTypes.string
};

export function DragGhost({
  dragProps,
  formation,
  allPlayers,
  getPlayerNameById,
  resolvePositionLabel
}) {
  const { t } = useTranslation('game');
  const [snapBackPhase, setSnapBackPhase] = React.useState('idle');

  const dragState = dragProps?.dragState;
  const ghostPosition = dragProps?.ghostPosition;
  const ghostSize = dragProps?.ghostSize;
  const ghostOffset = dragProps?.ghostOffset;
  const snapBack = dragProps?.snapBack;

  React.useEffect(() => {
    if (!snapBack) {
      setSnapBackPhase('idle');
      return undefined;
    }
    setSnapBackPhase('start');
    const raf = requestAnimationFrame(() => {
      setSnapBackPhase('end');
    });
    return () => cancelAnimationFrame(raf);
  }, [snapBack]);

  const sourcePlayerId = dragState?.sourcePlayerId || snapBack?.sourcePlayerId || null;
  const sourcePlayer = sourcePlayerId ? findPlayerById(allPlayers, sourcePlayerId) : null;
  const sourcePosition = sourcePlayerId && formation
    ? Object.keys(formation).find((pos) => formation[pos] === sourcePlayerId) || null
    : null;
  const positionLabel = sourcePosition && resolvePositionLabel
    ? resolvePositionLabel(sourcePosition, sourcePlayer)
    : '';
  const playerName = sourcePlayerId
    ? (getPlayerNameById ? getPlayerNameById(sourcePlayerId) : sourcePlayerId)
    : '';

  // Active drag — ghost follows finger.
  if (dragState?.active && ghostPosition && ghostSize) {
    const offsetX = ghostOffset?.x ?? 0;
    const offsetY = ghostOffset?.y ?? 0;
    const left = ghostPosition.x - offsetX;
    const top = ghostPosition.y - offsetY;

    const actionType = dragState.actionType;
    const isEligible = dragState.isEligible;
    const hovered = Boolean(dragState.hoveredPlayerId);
    let badgeLabel = null;
    let badgeTone = null;
    if (hovered) {
      if (isEligible && actionType && DRAG_ACTION_LABEL_KEYS[actionType]) {
        const meta = DRAG_ACTION_LABEL_KEYS[actionType];
        badgeLabel = t(meta.key, { defaultValue: meta.fallback });
        badgeTone = 'eligible';
      } else {
        badgeLabel = t('drag.actionInvalid', { defaultValue: 'No-op' });
        badgeTone = 'ineligible';
      }
    }

    const ghostStyle = {
      position: 'fixed',
      left,
      top,
      width: `${ghostSize.width}px`,
      height: `${ghostSize.height}px`,
      transform: `scale(1.03) rotate(${GHOST_TILT_DEG}deg)`,
      transformOrigin: `${offsetX}px ${offsetY}px`,
      zIndex: 9999,
      touchAction: 'none'
    };

    return (
      <Portal>
        <ResolvedGhost
          ghostStyle={ghostStyle}
          badgeLabel={badgeLabel}
          badgeTone={badgeTone}
          positionLabel={positionLabel}
          playerName={playerName}
        />
      </Portal>
    );
  }

  // Snap-back ghost.
  if (snapBack) {
    const transitionDuration = snapBack.durationMs || 200;
    const dx = snapBack.toX - snapBack.fromX;
    const dy = snapBack.toY - snapBack.fromY;
    const ghostStyle = {
      position: 'fixed',
      left: snapBack.fromX,
      top: snapBack.fromY,
      width: `${snapBack.width}px`,
      height: `${snapBack.height}px`,
      transform: snapBackPhase === 'end' ? `translate(${dx}px, ${dy}px) scale(0.98)` : 'translate(0, 0) scale(1.02)',
      opacity: snapBackPhase === 'end' ? 0.2 : 1,
      transition: `transform ${transitionDuration}ms cubic-bezier(0.4, 0, 0.2, 1), opacity ${transitionDuration}ms ease-out`,
      zIndex: 9999,
      pointerEvents: 'none'
    };

    return (
      <Portal>
        <ResolvedGhost
          ghostStyle={ghostStyle}
          positionLabel={positionLabel}
          playerName={playerName}
        />
      </Portal>
    );
  }

  return null;
}

DragGhost.propTypes = {
  dragProps: PropTypes.shape({
    dragState: PropTypes.object,
    ghostPosition: PropTypes.object,
    ghostSize: PropTypes.object,
    ghostOffset: PropTypes.object,
    snapBack: PropTypes.object
  }),
  formation: PropTypes.object,
  allPlayers: PropTypes.array.isRequired,
  getPlayerNameById: PropTypes.func,
  resolvePositionLabel: PropTypes.func
};

export default DragGhost;
