import { useEffect, useRef } from 'react';
import {
  clearInitialRedirectIf,
  getInitialPathRoutingState,
  releaseInitialRouteSyncLock,
  normalizeRoutingPath,
  shouldDeferInitialRouteSync
} from './pathRoutingState';

export function createManagedViewRoutingHook({
  navigateTarget,
  activeViews,
  ownsPath,
  getViewPath,
  shouldClearRedirect,
  hookName
}) {
  const viewSet = new Set(activeViews || [navigateTarget]);

  return function useManagedViewRouting(view, navigateToView, options = {}) {
    const { authGateActive = false } = options;
    const initialPathRef = useRef(null);
    const initialRouteHandledRef = useRef(false);

    useEffect(() => {
      if (typeof window === 'undefined') {
        initialRouteHandledRef.current = true;
        return;
      }

      if (initialPathRef.current === null) {
        const initialPathState = getInitialPathRoutingState();
        initialPathRef.current = initialPathState.path;

        if (initialPathState.fromRedirect) {
          const shouldClear =
            typeof shouldClearRedirect === 'function'
              ? shouldClearRedirect(initialPathState.path)
              : ownsPath(initialPathState.path);

          if (shouldClear) {
            clearInitialRedirectIf((redirectPath) => redirectPath === initialPathState.path);

            if (hookName) {
              console.log(`[${hookName}] Reading from sessionStorage redirect:`, initialPathState.path);
            }
          }
        }
      }

      if (initialRouteHandledRef.current) {
        return;
      }

      // Defer initial navigation while the app-level auth gate is open. App.js
      // will restore the URL and trigger navigation once the user signs in.
      if (authGateActive) {
        return;
      }

      if (ownsPath(initialPathRef.current) && !viewSet.has(view)) {
        navigateToView?.(navigateTarget);
      }

      initialRouteHandledRef.current = true;
    }, [navigateToView, view, authGateActive]);

    useEffect(() => {
      if (typeof window === 'undefined') {
        return;
      }

      const normalizedPath = normalizeRoutingPath(window.location.pathname || '/');
      const ownsInitialPath = ownsPath(initialPathRef.current);
      const ownsView = viewSet.has(view);

      if (ownsInitialPath && ownsView) {
        releaseInitialRouteSyncLock();
      }

      if (shouldDeferInitialRouteSync({ ownsInitialPath, ownsView })) {
        return;
      }

      let targetPath = null;
      if (ownsView && !ownsPath(normalizedPath)) {
        targetPath = getViewPath(view);
      } else if (!ownsView && ownsPath(normalizedPath)) {
        targetPath = '/';
      }

      if (targetPath !== null && normalizedPath !== targetPath) {
        const search = window.location.search || '';
        const hash = window.location.hash || '';
        const newUrl = `${targetPath}${search}${hash}`;
        window.history.replaceState(window.history.state, '', newUrl);
      }
    }, [view]);
  };
}

/**
 * Factory that creates a path-based routing hook.
 *
 * Each generated hook handles:
 *  1. Initial route detection (URL or sessionStorage fallback)
 *  2. URL sync when the view changes (replaceState)
 *
 * @param {Object} config
 * @param {string}   config.path           - URL path to own, e.g. '/profile'
 * @param {string}   config.navigateTarget - VIEWS constant to navigate to on initial detection
 * @param {string[]} [config.activeViews]  - View constants that keep this path active
 *                                           (defaults to [navigateTarget])
 * @param {string}   config.hookName       - Name used in console logs
 * @returns {Function} A React hook with signature (view, navigateToView) => void
 */
export function createPathRoutingHook({ path, navigateTarget, activeViews, hookName }) {
  return createManagedViewRoutingHook({
    navigateTarget,
    activeViews,
    ownsPath: (candidatePath) => candidatePath === path,
    getViewPath: () => path,
    shouldClearRedirect: (candidatePath) => candidatePath === path,
    hookName
  });
}
