export const ALL_FIXED_ROLE_GROUP_OPTIONS = Object.freeze(
  [...new Set(
    Object.values(SAME_ROLE_GROUP_CONFIG_BY_FORMATION)
      .flatMap(config => config.fixedRoleOptions || [])
  )]
);

const getSameRoleFormationConfig = (teamConfig) => {
  if (!teamConfig) return null;
  return SAME_ROLE_GROUP_CONFIG_BY_FORMATION[teamConfig.formation] || null;
};

export const getSameRoleGroupDefinitions = (teamConfig) => {
  const config = getSameRoleFormationConfig(teamConfig);
  if (!config) return [];

  return config.groups.map(group => ({
    ...group,
    fieldPositions: [...group.fieldPositions]
  }));
};

export const getSameRoleGroupOrder = (teamConfig) =>
  getSameRoleGroupDefinitions(teamConfig).map(group => group.key);

export const getSameRoleRotationOrder = (teamConfig) => {
  const config = getSameRoleFormationConfig(teamConfig);
  if (!config?.rotationOrder) return getSameRoleGroupOrder(teamConfig);
  return [...config.rotationOrder];
};

export const getFixedRoleGroupOptions = (teamConfig) => {
  const config = getSameRoleFormationConfig(teamConfig);
  if (!config?.fixedRoleOptions) return [];
  return [...config.fixedRoleOptions];
};

export const getDefaultFixedRoleGroup = (teamConfig) => {
  const options = getFixedRoleGroupOptions(teamConfig);
  return options[0] || null;
};

export const isValidFixedRoleGroup = (teamConfig, fixedRoleGroup) =>
  getFixedRoleGroupOptions(teamConfig).includes(fixedRoleGroup);

/**
 * Whether an optional fixed-role-group selector should be shown for ROTATE_ROLES mode.
 * True when the formation has a SAME_ROLE_GROUP_CONFIG entry AND there is at least
 * one substitute available.
 */
export const supportsRotateRolesFixedGroup = (teamConfig) => {
  if (!teamConfig) return false;
  const config = getSameRoleFormationConfig(teamConfig);
  if (!config) return false;
  const formatConfig = FORMAT_CONFIGS[teamConfig.format];
  if (!formatConfig) return false;
  const numSubs = teamConfig.squadSize - formatConfig.fieldPlayers - GAME_CONSTANTS.GOALIE_COUNT;
  return numSubs >= 1;
};

/**
 * Returns the field position keys for a given role group key.
 * Used to exclude fixed-group players from the ROTATE_ROLES rotation queue.
 */
export const getFixedGroupFieldPositions = (teamConfig, fixedRoleGroup) => {
  if (!fixedRoleGroup) return [];
  const groups = getSameRoleGroupDefinitions(teamConfig);
  const group = groups.find(g => g.key === fixedRoleGroup);
  return group ? [...group.fieldPositions] : [];
};

export const isPlayerPositionInFixedGroup = (
  position,
  substitutionLogic,
  roleGroups,
  teamConfig,
  fixedRoleGroup
) => {
  if (isSameRoleMode(substitutionLogic)) {
    if (!roleGroups) return false;
    return Object.values(roleGroups).some(
      (group) => !group.substitutePosition && group.fieldPositions?.includes(position)
    );
  }

  if (!fixedRoleGroup) return false;
  return getFixedGroupFieldPositions(teamConfig, fixedRoleGroup).includes(position);
};

/**
 * Check if the substitution logic is a same-role variant
 * @param {string} logic - Substitution logic value
 * @returns {boolean} True if same_role_match or same_role_period
 */
export const isSameRoleMode = (logic) => {
  return logic === SUBSTITUTION_LOGIC_VALUES.SAME_ROLE_MATCH ||
         logic === SUBSTITUTION_LOGIC_VALUES.SAME_ROLE_PERIOD;
};

/**
 * Check if role-grouped substitution is available for the given team config.
 * Requires a same-role-supported formation and either N-1 or N substitutes
 * (where N is the number of role groups).
 * @param {Object} teamConfig - Team configuration object
 * @returns {boolean} True if role-grouped substitution is available
 */
export const isRoleGroupedSubstitutionAvailable = (teamConfig) => {
  if (!teamConfig) return false;
  const config = getSameRoleFormationConfig(teamConfig);
  if (!config) return false;
  const formatConfig = FORMAT_CONFIGS[teamConfig.format];
  if (!formatConfig) return false;
  const numGroups = config.groups.length;
  const numSubs = teamConfig.squadSize - formatConfig.fieldPlayers - GAME_CONSTANTS.GOALIE_COUNT;
  return numSubs === numGroups - 1 || numSubs === numGroups;
};

/**
 * Check if same-role modes require selecting a fixed role group (no substitutions).
 * This applies when there are N-1 substitutes for N role groups (one group has no sub).
 * @param {Object} teamConfig - Team configuration object
 * @returns {boolean} True if fixed role group selection is required
 */
export const requiresFixedRoleGroup = (teamConfig) => {
  if (!teamConfig) return false;
  const config = getSameRoleFormationConfig(teamConfig);
  if (!config) return false;
  const formatConfig = FORMAT_CONFIGS[teamConfig.format];
  if (!formatConfig) return false;
  const numGroups = config.groups.length;
  const numSubs = teamConfig.squadSize - formatConfig.fieldPlayers - GAME_CONSTANTS.GOALIE_COUNT;
  return numSubs === numGroups - 1;
};

/**
 * Creates a composite team configuration object
 * @param {string} format - Field format (5v5, 7v7, etc.)
 * @param {number} squadSize - Total number of players (5-15)
 * @param {string} formation - Tactical formation (2-2, 1-2-1, etc.)
 * @returns {Object} Team configuration object
 */
export const createTeamConfig = (format, squadSize, formation) => {
  return {
    format,
    squadSize,
    formation
  };
};

/**
 * Gets valid formation options for a given format and squad size
 * @param {string} format - Field format
 * @param {number} squadSize - Squad size
 * @returns {string[]} Array of valid formation strings
 */
export const getValidFormations = (format, squadSize) => {
  const formationsForFormat = Object.entries(FORMATION_DEFINITIONS)
    .filter(([, definition]) => {
      if (definition.formats && !definition.formats.includes(format)) {
        return false;
      }
      return true;
    })
    .map(([key]) => key);

  if (formationsForFormat.length > 0) {
    return formationsForFormat;
  }

  // Fallback: retain existing behaviour for unknown formats
  return [FORMATIONS.FORMATION_2_2];
};

/**
 * Validates a team configuration object
 * @param {Object} teamConfig - Team configuration to validate
 * @throws {Error} If configuration is invalid
 * @returns {boolean} True if valid
 */
export const validateTeamConfig = (teamConfig) => {
  const { format, squadSize, formation } = teamConfig;

  // Validate format
  if (!Object.values(FORMATS).includes(format) || !FORMAT_CONFIGS[format]) {
    throw new Error(`Invalid format: ${format}. Must be one of: ${Object.values(FORMATS).join(', ')}`);
  }

  const maximumPlayersForFormat = getMaximumPlayersForFormat(format);

  // Validate squad size
  if (squadSize < GAME_CONSTANTS.MIN_SQUAD_SIZE || squadSize > maximumPlayersForFormat) {
    throw new Error(`Invalid squad size: ${squadSize}. Must be between ${GAME_CONSTANTS.MIN_SQUAD_SIZE} and ${maximumPlayersForFormat} players for ${format}`);
  }

  // Validate formation for the given format
  const validFormations = getValidFormations(format, squadSize);
  if (!validFormations.includes(formation)) {
    throw new Error(`Formation ${formation} not valid for ${format} with ${squadSize} players. Valid formations: ${validFormations.join(', ')}`);
  }

  return true;
};

/**
 * Validates and auto-corrects a team configuration object
 * If the configuration is invalid, it returns a corrected version
 * @param {Object} teamConfig - Team configuration to validate and potentially correct
 * @returns {Object} { isValid: boolean, correctedConfig: Object, corrections: string[] }
 */
export const validateAndCorrectTeamConfig = (teamConfig) => {
  const corrections = [];
  let correctedConfig = { ...teamConfig };

  try {
    validateTeamConfig(teamConfig);
    return { isValid: true, correctedConfig: teamConfig, corrections: [] };
  } catch (error) {
    // Try validation again with corrected config
    try {
      validateTeamConfig(correctedConfig);
      return { isValid: false, correctedConfig, corrections };
    } catch (validationError) {
      // If still invalid, throw the original validation error
      throw error;
    }
  }
};

/**
 * Creates a default team configuration
 * @param {number} squadSize - Squad size
 * @returns {Object} Default team configuration
 */
export const createDefaultTeamConfig = (squadSize, format = FORMATS.FORMAT_5V5) => {
  const resolvedFormat = FORMAT_CONFIGS[format] ? format : FORMATS.FORMAT_5V5;
  const formatConfig = FORMAT_CONFIGS[resolvedFormat];

  const defaultFormation = formatConfig.defaultFormation || FORMATIONS.FORMATION_2_2;

  return createTeamConfig(
    resolvedFormat,
    squadSize,
    defaultFormation
  );
};
