import { isStatisticsPath } from '../constants/statisticsTabs';
import { isTeamManagementPath } from '../constants/teamManagementTabs';

const STATIC_MANAGED_PATHS = new Set([
  '/matches',
  '/tactics',
  '/profile',
  '/team/roster/ranking'
]);

// Accepts either a UUID (legacy share links) or an 8-char Crockford base32
// share code (alphabet: 0-9 + A-Z minus I, L, O, U). A single capture group
// so downstream callers can forward whichever identifier was in the URL.
export const LIVE_MATCH_PATH_REGEX = /^\/live\/([0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}|[0-9A-HJKMNP-TV-Z]{8})$/i;
const PLAN_MATCH_IDS_PATH_REGEX = /^\/plan\/([0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12})(?:,([0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}))*$/i;

let initialPathRoutingState = null;

export const normalizeRoutingPath = (path) => {
  const basePath = typeof path === 'string' ? path.split(/[?#]/, 1)[0] : '';
  return basePath.replace(/\/+$/, '') || '/';
};

export const isManagedAppPath = (path) => {
  const normalizedPath = normalizeRoutingPath(path);

  return (
    STATIC_MANAGED_PATHS.has(normalizedPath) ||
    isStatisticsPath(normalizedPath) ||
    isTeamManagementPath(normalizedPath) ||
    LIVE_MATCH_PATH_REGEX.test(normalizedPath) ||
    normalizedPath === '/plan' ||
    PLAN_MATCH_IDS_PATH_REGEX.test(normalizedPath)
  );
};

const readRedirectPath = () => {
  try {
    const redirect = sessionStorage.getItem('redirect');
    return redirect ? normalizeRoutingPath(redirect) : null;
  } catch (error) {
    return null;
  }
};

export const getInitialPathRoutingState = () => {
  if (initialPathRoutingState !== null) {
    return initialPathRoutingState;
  }

  let path = normalizeRoutingPath(window.location.pathname || '/');
  let fromRedirect = false;

  if (path === '/') {
    const redirectPath = readRedirectPath();
    if (redirectPath) {
      path = redirectPath;
      fromRedirect = true;
    }
  }

  initialPathRoutingState = {
    path,
    fromRedirect,
    lockActive: isManagedAppPath(path)
  };

  return initialPathRoutingState;
};

export const clearInitialRedirectIf = (matcher) => {
  try {
    const redirect = sessionStorage.getItem('redirect');
    if (!redirect) {
      return;
    }

    const normalizedRedirect = normalizeRoutingPath(redirect);
    const shouldClear =
      typeof matcher === 'function'
        ? matcher(normalizedRedirect)
        : normalizedRedirect === normalizeRoutingPath(matcher);

    if (shouldClear) {
      sessionStorage.removeItem('redirect');
    }
  } catch (error) {
    // Ignore sessionStorage failures
  }
};

export const releaseInitialRouteSyncLock = () => {
  if (initialPathRoutingState) {
    initialPathRoutingState.lockActive = false;
  }
};

export const shouldDeferInitialRouteSync = ({ ownsInitialPath, ownsView }) => {
  const state = getInitialPathRoutingState();

  if (!state.lockActive) {
    return false;
  }

  if (ownsInitialPath) {
    return !ownsView;
  }

  return isManagedAppPath(state.path);
};

export const resetPathRoutingStateForTests = () => {
  initialPathRoutingState = null;
};
