import { VIEWS } from '../constants/viewConstants';
import { initializePlayers } from './playerUtils';
import { initialRoster } from '../constants/defaultData';

const DEFAULT_NUM_PERIODS = 3;
const DEFAULT_PERIOD_DURATION_MINUTES = 15;

const EMPTY_FORMATION = {
  goalie: null,
  leftDefender: null,
  rightDefender: null,
  leftAttacker: null,
  rightAttacker: null,
  substitute: null,
};

// Resets all match configuration to a fresh state for a team's roster. Period
// config is reset unconditionally because clearStoredState only resets it when
// match events existed, and team-preference re-derivation is skipped while
// hasActiveConfiguration is set — so a mid-config switch would otherwise leak it.
export function resetMatchConfig(gameState, team, players, onSessionStart) {
  gameState.setView(VIEWS.CONFIG);
  gameState.setCurrentPeriodNumber(1);
  gameState.setGameLog([]);

  if (team && players && players.length > 0 && gameState.syncPlayersFromTeamRoster) {
    try {
      const result = gameState.syncPlayersFromTeamRoster(players);
      if (!result.success) {
        console.warn('⚠️ Config reset: Team sync failed, using initial roster');
        gameState.setAllPlayers(initializePlayers(initialRoster));
      }
    } catch (error) {
      console.warn('⚠️ Config reset: Team sync error, using initial roster:', error);
      gameState.setAllPlayers(initializePlayers(initialRoster));
    }
  } else {
    gameState.setAllPlayers(initializePlayers(initialRoster));
  }

  gameState.setSelectedSquadIds([]);
  gameState.setPeriodGoalieIds({});
  gameState.setNumPeriods(DEFAULT_NUM_PERIODS);
  gameState.setPeriodDurationMinutes(DEFAULT_PERIOD_DURATION_MINUTES);
  gameState.setFormation({ ...EMPTY_FORMATION });
  gameState.resetScore();
  gameState.setOpponentTeam('');
  gameState.clearStoredState();

  onSessionStart();
}
