import React, { useState } from 'react';
import PropTypes from 'prop-types';
import { Trash2 } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { ModalShell } from '../shared/ModalShell';
import { Button, Input } from '../shared/UI';

// Typed-confirmation modal for irreversible account deletion (App Store 5.1.1(v)).
export function DeleteAccountModal({ isOpen, onConfirm, onCancel, isDeleting = false }) {
  const { t } = useTranslation('profile');
  const [typed, setTyped] = useState('');

  if (!isOpen) return null;

  const requiredPhrase = t('modals.deleteAccount.confirmPhrase');
  const matches = typed.trim().toUpperCase() === requiredPhrase.toUpperCase();

  const handleCancel = () => {
    setTyped('');
    onCancel();
  };

  return (
    <ModalShell
      title={t('modals.deleteAccount.title')}
      icon={Trash2}
      iconColor="rose"
      onClose={isDeleting ? undefined : handleCancel}
    >
      <div className="space-y-4">
        <p className="text-slate-200">{t('modals.deleteAccount.intro')}</p>
        <ul className="list-disc list-inside text-slate-300 text-sm space-y-1">
          <li>{t('modals.deleteAccount.bulletData')}</li>
          <li>{t('modals.deleteAccount.bulletTeams')}</li>
          <li>{t('modals.deleteAccount.bulletIrreversible')}</li>
        </ul>
        <div>
          <label htmlFor="delete-account-confirm" className="block text-sm text-slate-300 mb-2">
            {t('modals.deleteAccount.typePrompt', { phrase: requiredPhrase })}
          </label>
          <Input
            id="delete-account-confirm"
            value={typed}
            onChange={(e) => setTyped(e.target.value)}
            placeholder={requiredPhrase}
            disabled={isDeleting}
            autoComplete="off"
          />
        </div>
        <div className="flex flex-col sm:flex-row gap-3 sm:justify-end pt-2">
          <Button onClick={handleCancel} variant="secondary" className="sm:order-1" disabled={isDeleting}>
            {t('buttons.cancel')}
          </Button>
          <Button
            onClick={onConfirm}
            variant="danger"
            className="sm:order-2"
            disabled={!matches || isDeleting}
          >
            {isDeleting ? t('modals.deleteAccount.deleting') : t('modals.deleteAccount.confirm')}
          </Button>
        </div>
      </div>
    </ModalShell>
  );
}

DeleteAccountModal.propTypes = {
  isOpen: PropTypes.bool.isRequired,
  onConfirm: PropTypes.func.isRequired,
  onCancel: PropTypes.func.isRequired,
  isDeleting: PropTypes.bool,
};
