import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import PropTypes from 'prop-types';
import { GripVertical, Plus, Trash2 } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { useTeam } from '../../contexts/TeamContext';
import { Button } from '../shared/UI';
import { useListDragAndDrop } from '../../hooks/useListDragAndDrop';
import { useRankingDrag } from '../../hooks/useRankingDrag';
import { getPlayerRankings, upsertPlayerRankings, updateLevelCount } from '../../services/rankingService';

const DEFAULT_LEVEL_COUNT = 3;
const DEFAULT_PLAYER_LEVEL = 2;
const SAVE_DEBOUNCE_MS = 400;

/** Build the initial playersByLevel map from DB data and roster. */
export function buildInitialPlayersByLevel(rankings, rosterPlayers, levelCount) {
  const rankedIds = new Set(rankings.map((r) => r.player_id));
  const defaultLevel = Math.min(DEFAULT_PLAYER_LEVEL, levelCount);

  // Players with no DB row default to level 2, clamped to the available level range.
  const unrankedPlayers = rosterPlayers.filter((p) => !rankedIds.has(p.id));

  // Sort ranked players within each level by rank_order ASC (0 goes last)
  const byLevel = {};
  for (let l = 1; l <= levelCount; l++) {
    byLevel[l] = [];
  }

  for (const row of rankings) {
    // Clamp out-of-range levels (e.g. stale rows after levelCount was reduced)
    const level = Math.min(row.level, levelCount);
    byLevel[level].push({ id: row.player_id, rank_order: row.rank_order });
  }

  // Sort within each level: rank_order > 0 ascending first, then rank_order = 0
  for (const level of Object.keys(byLevel)) {
    byLevel[level].sort((a, b) => {
      if (a.rank_order === 0 && b.rank_order === 0) return 0;
      if (a.rank_order === 0) return 1;
      if (b.rank_order === 0) return -1;
      return a.rank_order - b.rank_order;
    });
    byLevel[level] = byLevel[level].map((item) => item.id);
  }

  // Append unranked players to the default level.
  for (const player of unrankedPlayers) {
    if (!byLevel[defaultLevel]) {
      byLevel[defaultLevel] = [];
    }
    byLevel[defaultLevel].push(player.id);
  }

  return byLevel;
}

/** Convert playersByLevel map to an array of ranking rows for upsert. */
export function flattenToRankingRows(playersByLevel) {
  const rows = [];
  for (const [levelStr, playerIds] of Object.entries(playersByLevel)) {
    const level = parseInt(levelStr, 10);
    playerIds.forEach((playerId, index) => {
      rows.push({ player_id: playerId, level, rank_order: index + 1 });
    });
  }
  return rows;
}

/** Renormalize levels after removal so they remain 1..newCount. */
export function removeLevelAndRenormalize(playersByLevel, levelCount, levelToRemove) {
  const remainingLevels = [];
  for (let l = 1; l <= levelCount; l++) {
    if (l !== levelToRemove) remainingLevels.push(l);
  }
  // Map old level → new level (1-based)
  const levelMapping = {};
  remainingLevels.forEach((oldLevel, idx) => {
    levelMapping[oldLevel] = idx + 1;
  });

  const newByLevel = {};
  for (const [levelStr, playerIds] of Object.entries(playersByLevel)) {
    const oldLevel = parseInt(levelStr, 10);
    if (oldLevel === levelToRemove) continue;
    const newLevel = levelMapping[oldLevel];
    if (newLevel !== undefined) {
      newByLevel[newLevel] = playerIds;
    }
  }

  return { playersByLevel: newByLevel, levelCount: remainingLevels.length };
}

// ---------------------------------------------------------------------------
// LevelGroup subcomponent
// ---------------------------------------------------------------------------

function LevelGroup({
  level,
  levelCount,
  playerIds,
  playerMap,
  onReorder,
  onRemoveLevel,
  registerContainer,
  onCrossDragMove,
  onCrossDragEnd,
  crossLevelState,
  isHighest,
  canManageTeam,
}) {
  const { t } = useTranslation('team');
  const containerRef = useRef(null);

  // Register this container with the cross-level drag hook
  useEffect(() => {
    return registerContainer(level, containerRef);
  }, [level, registerContainer]);

  const players = useMemo(
    () => playerIds.map((id) => playerMap[id]).filter(Boolean),
    [playerIds, playerMap]
  );

  const handleLocalDragMove = useCallback(
    (data) => onCrossDragMove(data, level),
    [onCrossDragMove, level]
  );

  const handleLocalDragEnd = useCallback(
    (data) => onCrossDragEnd(data, level),
    [onCrossDragEnd, level]
  );

  const {
    isDragging,
    draggedItemId,
    ghostPosition,
    ghostSize,
    ghostOffset,
    handlePointerStart,
    isItemBeingDragged,
    isItemDragActivating,
    getItemShift,
    shouldSuppressClick,
  } = useListDragAndDrop({
    items: players,
    onReorder: (reordered) => onReorder(level, reordered.map((p) => p.id)),
    containerRef,
    onDragMove: handleLocalDragMove,
    onDragEnd: handleLocalDragEnd,
  });

  const ghostPlayer = useMemo(() => {
    if (!draggedItemId) return null;
    return playerMap[draggedItemId] || null;
  }, [draggedItemId, playerMap]);

  const isTargetLevel =
    crossLevelState.active && crossLevelState.targetLevelId === level;
  const isEmpty = playerIds.length === 0;
  // Cannot remove if there is only 1 level remaining or user lacks manage permission
  const canRemove = canManageTeam && isEmpty && levelCount > 1;

  const levelLabel = isHighest
    ? t('playerRanking.levelStrongest', { level })
    : t('playerRanking.levelLabel', { level });

  return (
    <div
      className={`rounded-lg border transition-colors ${
        isTargetLevel
          ? 'border-sky-400 bg-sky-900/20 shadow-[0_0_12px_rgba(56,189,248,0.3)]'
          : 'border-slate-600 bg-slate-800/60'
      }`}
    >
      {/* Level header */}
      <div className="flex items-center justify-between px-3 py-2">
        <span className="text-sm font-semibold text-sky-300">{levelLabel}</span>
        <button
          type="button"
          onClick={() => onRemoveLevel(level)}
          disabled={!canRemove}
          title={
            !canRemove
              ? t('playerRanking.removeLevelDisabled')
              : t('playerRanking.removeLevel')
          }
          className={`p-1 rounded transition-colors ${
            canRemove
              ? 'text-slate-400 hover:text-red-400 hover:bg-red-900/20'
              : 'text-slate-700 cursor-not-allowed'
          }`}
          aria-label={t('playerRanking.removeLevel')}
        >
          <Trash2 className="w-3.5 h-3.5" />
        </button>
      </div>

      {/* Player list */}
      <div ref={containerRef} className="px-2 pb-2 space-y-1 min-h-[2rem]">
        {isEmpty && (
          <p className="text-xs text-slate-500 italic px-2 py-1">
            {t('playerRanking.emptyLevel')}
          </p>
        )}
        {players.map((player) => {
          const isDraggingThis = isItemBeingDragged(player.id);
          const shift = getItemShift(player.id);
          const isActivating = isItemDragActivating(player.id);

          return (
            <div
              key={player.id}
              data-drag-item-id={String(player.id)}
              className={`player-card-draggable flex items-center gap-2 rounded px-2 py-1.5 text-sm border transition-all ${
                isDraggingThis
                  ? 'opacity-0'
                  : 'border-slate-600 bg-slate-700/60 text-slate-200'
              } ${isActivating ? 'drag-activating' : ''}`}
              style={{
                transform: shift ? `translateY(${shift}px)` : undefined,
                transition: isDraggingThis ? 'none' : 'transform 150ms ease',
                ...(isDraggingThis && { height: 0, overflow: 'hidden', paddingTop: 0, paddingBottom: 0, marginTop: 0, marginBottom: 0 }),
              }}
              onPointerDown={canManageTeam ? (e) => handlePointerStart(player.id, e) : undefined}
              onClick={() => {
                if (shouldSuppressClick(player.id)) return;
              }}
            >
              {canManageTeam && (
                <GripVertical className="w-4 h-4 text-slate-500 flex-shrink-0 cursor-grab" />
              )}
              <span className="flex-1 truncate">{player.displayName}</span>
              {player.jerseyNumber != null && (
                <span className="text-xs text-amber-400 font-mono flex-shrink-0">
                  #{player.jerseyNumber}
                </span>
              )}
            </div>
          );
        })}
      </div>

      {/* Drag ghost */}
      {isDragging && ghostPosition && ghostPlayer && (
        <div
          className="flex items-center gap-2 rounded px-2 py-1.5 text-sm border border-sky-400 bg-sky-900/40 text-sky-100 shadow-lg pointer-events-none"
          style={{
            position: 'fixed',
            left: ghostPosition.x - (ghostOffset?.x ?? 0),
            top: ghostPosition.y - (ghostOffset?.y ?? 0),
            zIndex: 9999,
            width: ghostSize?.width ? `${ghostSize.width}px` : undefined,
            minWidth: '8rem',
            transform: 'scale(0.97)',
            transformOrigin: ghostOffset
              ? `${ghostOffset.x}px ${ghostOffset.y}px`
              : 'center center',
          }}
        >
          <GripVertical className="w-4 h-4 text-sky-400 flex-shrink-0" />
          <span className="flex-1 truncate">{ghostPlayer.displayName}</span>
          {ghostPlayer.jerseyNumber != null && (
            <span className="text-xs text-amber-400 font-mono flex-shrink-0">
              #{ghostPlayer.jerseyNumber}
            </span>
          )}
        </div>
      )}
    </div>
  );
}

LevelGroup.propTypes = {
  level: PropTypes.number.isRequired,
  levelCount: PropTypes.number.isRequired,
  playerIds: PropTypes.arrayOf(PropTypes.string).isRequired,
  playerMap: PropTypes.objectOf(
    PropTypes.shape({
      id: PropTypes.string.isRequired,
      displayName: PropTypes.string.isRequired,
      jerseyNumber: PropTypes.number,
    })
  ).isRequired,
  onReorder: PropTypes.func.isRequired,
  onRemoveLevel: PropTypes.func.isRequired,
  registerContainer: PropTypes.func.isRequired,
  onCrossDragMove: PropTypes.func.isRequired,
  onCrossDragEnd: PropTypes.func.isRequired,
  crossLevelState: PropTypes.shape({
    active: PropTypes.bool.isRequired,
    targetLevelId: PropTypes.number,
  }).isRequired,
  isHighest: PropTypes.bool.isRequired,
  canManageTeam: PropTypes.bool.isRequired,
};

// ---------------------------------------------------------------------------
// PlayerRankingScreen
// ---------------------------------------------------------------------------

export function PlayerRankingScreen({
  onNavigateBack,
  pushNavigationState,
  removeFromNavigationStack,
}) {
  const { t } = useTranslation('team');
  const { currentTeam, teamPlayers, canManageTeam } = useTeam();

  const [playersByLevel, setPlayersByLevel] = useState(null);
  const [levelCount, setLevelCount] = useState(DEFAULT_LEVEL_COUNT);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const initializedRef = useRef(false);
  const saveTimeoutRef = useRef(null);
  const teamIdRef = useRef(null);

  // Register browser back handler
  useEffect(() => {
    if (pushNavigationState) {
      pushNavigationState(() => {
        onNavigateBack();
      });
      return () => {
        if (removeFromNavigationStack) removeFromNavigationStack();
      };
    }
  }, [pushNavigationState, removeFromNavigationStack, onNavigateBack]);

  // Load rankings on mount
  useEffect(() => {
    const teamId = currentTeam?.id;
    if (!teamId || !teamPlayers) return;

    teamIdRef.current = teamId;
    const rosterPlayers = teamPlayers.filter((p) => p.on_roster !== false);

    (async () => {
      try {
        const result = await getPlayerRankings(teamId);
        const count = result?.levelCount ?? DEFAULT_LEVEL_COUNT;
        const byLevel = buildInitialPlayersByLevel(
          result?.rankings ?? [],
          rosterPlayers,
          count
        );
        setLevelCount(count);
        setPlayersByLevel(byLevel);
      } catch (err) {
        console.error('Failed to load player rankings:', err);
        setError(t('playerRanking.loadError'));
      } finally {
        setLoading(false);
        initializedRef.current = true;
      }
    })();
  }, [currentTeam?.id, teamPlayers, t]);

  // Auto-save with debounce whenever playersByLevel changes (after init)
  useEffect(() => {
    if (!initializedRef.current || !playersByLevel) return;
    if (!canManageTeam) return;
    const teamId = teamIdRef.current;
    if (!teamId) return;

    if (saveTimeoutRef.current) clearTimeout(saveTimeoutRef.current);
    saveTimeoutRef.current = setTimeout(() => {
      const rows = flattenToRankingRows(playersByLevel);
      (async () => {
        try {
          await upsertPlayerRankings(teamId, rows);
          setError(null);
        } catch (err) {
          console.error('Failed to save player rankings:', err);
          setError(t('playerRanking.saveError'));
        }
      })();
    }, SAVE_DEBOUNCE_MS);

    return () => {
      if (saveTimeoutRef.current) clearTimeout(saveTimeoutRef.current);
    };
  }, [playersByLevel, canManageTeam, t]);

  // Build a lookup map: playerId → player object
  const playerMap = useMemo(() => {
    const map = {};
    (teamPlayers || []).forEach((p) => {
      map[p.id] = {
        id: p.id,
        displayName: p.display_name,
        jerseyNumber: p.jersey_number,
      };
    });
    return map;
  }, [teamPlayers]);

  // Cross-level drag hook
  const { registerContainer, handleDragMove, handleDragEnd, crossLevelState } =
    useRankingDrag({
      onMovePlayer: useCallback(
        (sourceLevel, playerId, targetLevel, beforePlayerId) => {
          setPlayersByLevel((prev) => {
            if (!prev) return prev;
            const sourceList = (prev[sourceLevel] || []).filter(
              (id) => id !== playerId
            );
            const targetList = [...(prev[targetLevel] || [])];
            if (beforePlayerId) {
              const idx = targetList.indexOf(beforePlayerId);
              targetList.splice(idx >= 0 ? idx : targetList.length, 0, playerId);
            } else {
              targetList.push(playerId);
            }
            return { ...prev, [sourceLevel]: sourceList, [targetLevel]: targetList };
          });
        },
        []
      ),
    });

  // Within-level reorder
  const handleReorder = useCallback((level, newPlayerIds) => {
    setPlayersByLevel((prev) => (prev ? { ...prev, [level]: newPlayerIds } : prev));
  }, []);

  // Add a new level (highest + 1, appears at top)
  const handleAddLevel = useCallback(async () => {
    const prevCount = levelCount;
    const newCount = levelCount + 1;
    const newLevel = newCount;
    setLevelCount(newCount);
    setPlayersByLevel((prev) => (prev ? { ...prev, [newLevel]: [] } : prev));
    if (teamIdRef.current) {
      try {
        await updateLevelCount(teamIdRef.current, newCount);
        setError(null);
      } catch (err) {
        console.error('Failed to add level:', err);
        setLevelCount(prevCount);
        setPlayersByLevel((prev) => {
          if (!prev) return prev;
          const { [newLevel]: _removed, ...rest } = prev;
          return rest;
        });
        setError(t('playerRanking.saveError'));
      }
    }
  }, [levelCount, t]);

  // Remove a level (must be empty; renormalizes remaining levels)
  const handleRemoveLevel = useCallback(
    async (level) => {
      if (!playersByLevel) return;
      if ((playersByLevel[level] || []).length > 0) return;
      if (levelCount <= 1) return;

      const prevCount = levelCount;
      const prevByLevel = playersByLevel;
      const { playersByLevel: newByLevel, levelCount: newCount } =
        removeLevelAndRenormalize(playersByLevel, levelCount, level);

      setLevelCount(newCount);
      setPlayersByLevel(newByLevel);

      if (teamIdRef.current) {
        try {
          await updateLevelCount(teamIdRef.current, newCount);
          setError(null);
        } catch (err) {
          console.error('Failed to remove level:', err);
          setLevelCount(prevCount);
          setPlayersByLevel(prevByLevel);
          setError(t('playerRanking.saveError'));
        }
      }
    },
    [playersByLevel, levelCount, t]
  );

  // Levels rendered from highest to lowest
  const levels = useMemo(() => {
    const result = [];
    for (let l = levelCount; l >= 1; l--) result.push(l);
    return result;
  }, [levelCount]);

  if (loading) {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center">
        <p className="text-slate-400">{t('common.loading', { defaultValue: 'Loading…' })}</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-900 text-slate-100">
      <div className="max-w-lg mx-auto px-4 py-6 space-y-4">
        {/* Header */}
        <div className="flex items-center justify-between">
          <h1 className="text-xl font-bold text-sky-300">
            {t('playerRanking.title')}
          </h1>
          <Button onClick={onNavigateBack} variant="secondary" size="sm">
            {t('playerRanking.back')}
          </Button>
        </div>

        {error && (
          <div className="rounded-md bg-red-900/30 border border-red-700 px-3 py-2 text-sm text-red-300">
            {error}
          </div>
        )}

        {!canManageTeam && (
          <div className="rounded-md bg-slate-800 border border-slate-600 px-3 py-2 text-sm text-slate-400">
            {t('playerRanking.readOnlyNotice')}
          </div>
        )}

        {/* Level groups */}
        <div className="space-y-3">
          {levels.map((level, idx) => (
            <LevelGroup
              key={level}
              level={level}
              levelCount={levelCount}
              playerIds={playersByLevel?.[level] || []}
              playerMap={playerMap}
              onReorder={handleReorder}
              onRemoveLevel={handleRemoveLevel}
              registerContainer={registerContainer}
              onCrossDragMove={handleDragMove}
              onCrossDragEnd={handleDragEnd}
              crossLevelState={crossLevelState}
              isHighest={idx === 0}
              canManageTeam={canManageTeam}
            />
          ))}
        </div>

        {/* Add level button */}
        {canManageTeam && (
          <button
            type="button"
            onClick={handleAddLevel}
            className="w-full flex items-center justify-center gap-2 rounded-lg border border-dashed border-slate-600 px-4 py-2.5 text-sm text-slate-400 hover:border-sky-500 hover:text-sky-400 transition-colors select-none"
          >
            <Plus className="w-4 h-4" />
            {t('playerRanking.addLevel')}
          </button>
        )}
      </div>
    </div>
  );
}

PlayerRankingScreen.propTypes = {
  onNavigateBack: PropTypes.func.isRequired,
  pushNavigationState: PropTypes.func,
  removeFromNavigationStack: PropTypes.func,
};

PlayerRankingScreen.defaultProps = {
  pushNavigationState: null,
  removeFromNavigationStack: null,
};
