import React, { useState } from 'react';
import PropTypes from 'prop-types';
import { Button } from '../shared/UI';
import { Alert } from '../shared/Alert';
import { Card } from '../shared/Card';
import { Link, UserPlus } from 'lucide-react';
import { ModalShell } from '../shared/ModalShell';
import { useTranslation } from 'react-i18next';

const candidateName = (player) => {
  const full = player.last_name ? `${player.first_name} ${player.last_name}` : player.first_name;
  return player.jersey_number ? `#${player.jersey_number} ${full}` : full;
};

/**
 * Modal shown when accepting a ghost whose first name matches existing unlinked roster players.
 * Lets the user link to a candidate or fall through to creating a new player.
 */
export function PlayerLinkOrCreateModal({ ghost, candidates, onLink, onCreateNew, onClose }) {
  const { t } = useTranslation('team');
  const [selectedCandidateId, setSelectedCandidateId] = useState(candidates[0]?.id ?? '');
  // Which action is in flight ('link' | 'create' | null) — so each button shows only its own label.
  const [loadingAction, setLoadingAction] = useState(null);
  const loading = loadingAction !== null;
  const [error, setError] = useState(null);

  const handleLink = async () => {
    if (!selectedCandidateId) {
      setError(t('playerLinkOrCreate.errors.selectPlayer'));
      return;
    }
    const candidate = candidates.find((c) => c.id === selectedCandidateId);
    if (!candidate) return;

    let linked = false;
    setLoadingAction('link');
    setError(null);
    try {
      await onLink(candidate);
      linked = true;
    } catch (err) {
      console.error('Error linking ghost to roster player:', err);
      setError(t('playerLinkOrCreate.errors.linkFailed'));
    } finally {
      setLoadingAction(null);
    }
    if (linked) onClose();
  };

  const handleCreateNew = async () => {
    let created = false;
    setLoadingAction('create');
    setError(null);
    try {
      await onCreateNew();
      created = true;
    } catch (err) {
      console.error('Error creating new player from ghost:', err);
      setError(t('playerLinkOrCreate.errors.createFailed'));
    } finally {
      setLoadingAction(null);
    }
    if (created) onClose();
  };

  // Block close paths (X, Escape, backdrop) while a link/create is in flight so the
  // action can't resolve against an unmounted modal.
  const handleShellClose = () => {
    if (!loading) onClose();
  };

  if (!ghost) return null;

  return (
    <ModalShell
      title={t('playerLinkOrCreate.title')}
      subtitle={t('playerLinkOrCreate.subtitle')}
      icon={Link}
      iconColor="amber"
      maxWidth="xl"
      onClose={handleShellClose}
    >
      <div className="space-y-6">
        {error && <Alert variant="error">{error}</Alert>}

        <Card variant="subtle">
          <h3 className="text-sm font-medium text-slate-300 mb-1">{t('playerLinkOrCreate.providerPlayer')}</h3>
          <div className="text-lg font-semibold text-slate-100">{ghost.playerNameInProvider}</div>
          <div className="text-xs text-slate-400 mt-1">
            {t('teamManagement.roster.ghost.from', { provider: ghost.providerName })}
          </div>
        </Card>

        <fieldset className="space-y-2">
          <legend className="text-sm font-medium text-slate-300 mb-2">{t('playerLinkOrCreate.candidatesLabel')}</legend>
          {candidates.map((candidate) => (
            <label
              key={candidate.id}
              className={`flex items-center space-x-3 p-3 rounded border cursor-pointer transition-colors ${
                selectedCandidateId === candidate.id
                  ? 'border-sky-500 bg-slate-700'
                  : 'border-slate-600 bg-slate-800 hover:bg-slate-700'
              }`}
            >
              <input
                type="radio"
                name="link-candidate"
                value={candidate.id}
                checked={selectedCandidateId === candidate.id}
                onChange={() => {
                  setSelectedCandidateId(candidate.id);
                  setError(null);
                }}
                disabled={loading}
                className="text-sky-500 focus:ring-sky-500"
              />
              <span className="text-slate-100 font-medium">{candidateName(candidate)}</span>
            </label>
          ))}
        </fieldset>

        <div className="flex flex-col sm:flex-row sm:flex-wrap items-stretch sm:items-center sm:justify-end gap-3 pt-4 border-t border-slate-600">
          <Button type="button" onClick={handleShellClose} variant="secondary" disabled={loading} className="sm:whitespace-nowrap">
            {t('playerLinkOrCreate.buttons.cancel')}
          </Button>
          <Button type="button" onClick={handleCreateNew} variant="secondary" disabled={loading} Icon={UserPlus} className="sm:whitespace-nowrap">
            {loadingAction === 'create' ? t('playerLinkOrCreate.buttons.creating') : t('playerLinkOrCreate.buttons.createNew')}
          </Button>
          <Button
            type="button"
            onClick={handleLink}
            variant="primary"
            disabled={loading || !selectedCandidateId}
            Icon={Link}
            className="sm:whitespace-nowrap"
          >
            {loadingAction === 'link' ? t('playerLinkOrCreate.buttons.linking') : t('playerLinkOrCreate.buttons.link')}
          </Button>
        </div>
      </div>
    </ModalShell>
  );
}

PlayerLinkOrCreateModal.propTypes = {
  ghost: PropTypes.shape({
    externalPlayerId: PropTypes.string.isRequired,
    playerNameInProvider: PropTypes.string,
    providerName: PropTypes.string,
  }).isRequired,
  candidates: PropTypes.arrayOf(
    PropTypes.shape({
      id: PropTypes.string.isRequired,
      first_name: PropTypes.string.isRequired,
      last_name: PropTypes.string,
      jersey_number: PropTypes.oneOfType([PropTypes.string, PropTypes.number]),
    })
  ).isRequired,
  onLink: PropTypes.func.isRequired,
  onCreateNew: PropTypes.func.isRequired,
  onClose: PropTypes.func.isRequired,
};
