import React from 'react';
import PropTypes from 'prop-types';
import { HelpCircle, Share2, Sparkles } from 'lucide-react';
import { Button } from '../../shared/UI';
import { Tooltip } from '../../shared/Tooltip';
import { AUTO_SELECT_STRATEGY } from '../../../constants/planMatchesConstants';
import { useTranslation } from 'react-i18next';

export function PlanMatchesToolbar({
  sortMetric,
  onSortChange,
  includePrecedingUpcoming = false,
  onToggleIncludePrecedingUpcoming,
  canIncludePrecedingUpcoming = false,
  precedingUpcomingCount = 0,
  statsLoading,
  statsError,
  defaultsError,
  onRecommend,
  onShareLink,
  canShare
}) {
  const { t } = useTranslation('team');

  const includeLabel = t('planMatches.toolbar.includePrecedingLabel');
  const includeHelpBody = canIncludePrecedingUpcoming
    ? t('planMatches.toolbar.includePrecedingHelp', { count: precedingUpcomingCount })
    : t('planMatches.toolbar.includePrecedingDisabled');

  return (
    <div className="flex flex-wrap items-center gap-2 lg:flex-nowrap lg:relative">
      <div className="inline-flex items-center gap-1 rounded-md border border-slate-600 bg-slate-800/80 p-1">
        <button
          type="button"
          onClick={() => onSortChange(AUTO_SELECT_STRATEGY.PRACTICES)}
          className={`flex items-center gap-1 px-2 py-1 text-xs rounded ${
            sortMetric === AUTO_SELECT_STRATEGY.PRACTICES
              ? 'bg-sky-600 text-white'
              : 'text-slate-300 hover:text-slate-100'
          }`}
          title={t('planMatches.toolbar.sortByPractices')}
        >
          P/M
        </button>
        <button
          type="button"
          onClick={() => onSortChange(AUTO_SELECT_STRATEGY.ATTENDANCE)}
          className={`flex items-center gap-1 px-2 py-1 text-xs rounded ${
            sortMetric === AUTO_SELECT_STRATEGY.ATTENDANCE
              ? 'bg-sky-600 text-white'
              : 'text-slate-300 hover:text-slate-100'
          }`}
          title={t('planMatches.toolbar.sortByAttendance')}
        >
          %
        </button>
      </div>
      <label
        className={`inline-flex items-center gap-1.5 rounded-md border border-slate-600 bg-slate-800/80 px-2 py-2 text-xs ${
          canIncludePrecedingUpcoming ? 'text-slate-200 cursor-pointer' : 'text-slate-500 cursor-not-allowed'
        }`}
        title={canIncludePrecedingUpcoming ? undefined : t('planMatches.toolbar.includePrecedingDisabled')}
      >
        <input
          type="checkbox"
          className="h-3 w-3 accent-sky-500 disabled:opacity-50"
          checked={includePrecedingUpcoming}
          disabled={!canIncludePrecedingUpcoming}
          onChange={(e) => onToggleIncludePrecedingUpcoming?.(e.target.checked)}
        />
        <span>{includeLabel}</span>
      </label>
      <Tooltip
        position="bottom"
        content={
          <p className="text-xs text-slate-100 leading-relaxed">{includeHelpBody}</p>
        }
      >
        <span
          role="button"
          aria-label={t('planMatches.toolbar.includePrecedingHelpAria')}
          className="inline-flex items-center text-slate-400 hover:text-slate-200"
        >
          <HelpCircle className="h-4 w-4" />
        </span>
      </Tooltip>
      {statsLoading && (
        <span className="text-xs text-slate-400">{t('planMatches.toolbar.statsLoading')}</span>
      )}
      {statsError && (
        <span className="text-xs text-rose-300">{statsError}</span>
      )}
      {defaultsError && (
        <span className="text-xs text-rose-300">{defaultsError}</span>
      )}
      <div className="w-full flex justify-center lg:w-auto lg:absolute lg:left-1/2 lg:top-1/2 lg:-translate-x-1/2 lg:-translate-y-1/2">
        <Button
          size="md"
          variant="primary"
          onClick={onRecommend}
          className="px-4 shadow-lg shadow-sky-500/40 ring-1 ring-sky-400/60 bg-gradient-to-r from-sky-500 via-sky-400 to-cyan-500 hover:from-sky-400 hover:via-sky-300 hover:to-cyan-400"
          Icon={Sparkles}
        >
          {t('planMatches.toolbar.recommend')}
        </Button>
      </div>
      {canShare && (
        <div className="ml-auto">
          <button
            type="button"
            onClick={onShareLink}
            className="flex items-center gap-1 px-2 py-1.5 text-xs rounded border border-slate-600 bg-slate-800/80 text-slate-300 hover:text-slate-100 hover:border-slate-500 transition-colors"
            title={t('planMatches.toolbar.shareLink')}
          >
            <Share2 size={14} />
            <span className="hidden sm:inline">{t('planMatches.toolbar.share')}</span>
          </button>
        </div>
      )}
    </div>
  );
}

PlanMatchesToolbar.propTypes = {
  sortMetric: PropTypes.string.isRequired,
  onSortChange: PropTypes.func.isRequired,
  includePrecedingUpcoming: PropTypes.bool,
  onToggleIncludePrecedingUpcoming: PropTypes.func,
  canIncludePrecedingUpcoming: PropTypes.bool,
  precedingUpcomingCount: PropTypes.number,
  statsLoading: PropTypes.bool,
  statsError: PropTypes.string,
  defaultsError: PropTypes.string,
  onRecommend: PropTypes.func.isRequired,
  onShareLink: PropTypes.func,
  canShare: PropTypes.bool,
};
