import { useEffect, useRef } from 'react';

// Calls onSwitch(team, players) only on a genuine A->B switch — skips initial load,
// sign-out, and same-id re-renders. onSwitch is held in a ref so an unstable callback
// identity doesn't re-run the effect every render. On a switch, teamPlayers may briefly
// lag currentTeam (separate state slices); the new roster is then reconciled by
// ConfigurationScreen's existing teamPlayers->allPlayers sync, not by any fallback here.
export function useTeamSwitchReset(currentTeam, teamPlayers, onSwitch) {
  const previousTeamIdRef = useRef(null);
  const onSwitchRef = useRef(onSwitch);
  onSwitchRef.current = onSwitch;

  useEffect(() => {
    const prevId = previousTeamIdRef.current;
    const nextId = currentTeam?.id ?? null;
    previousTeamIdRef.current = nextId;

    if (prevId !== null && nextId !== null && prevId !== nextId) {
      onSwitchRef.current(currentTeam, teamPlayers);
    }
  }, [currentTeam, teamPlayers]);
}
