/**
 * Three-way rebase for squad-selection conflicts.
 *
 * Given the selection we last successfully synced, the user's current local
 * selection, and the latest server selection, derive the user's *intent* as
 * an additions/removals diff from the baseline and apply it on top of the
 * server state. Last-write-wins falls out naturally when both sides toggle
 * the same player.
 */

function toArray(value) {
  if (!value) return [];
  if (Array.isArray(value)) return value;
  return [];
}

function toStringIds(ids) {
  return toArray(ids).map((id) => String(id));
}

/**
 * Rebase a local squad selection onto the latest server selection.
 *
 * @param {Object} params
 * @param {Array<string|number>} params.baseline - last-synced selection
 * @param {Array<string|number>} params.local - current local selection
 * @param {Array<string|number>} params.server - latest server selection
 * @returns {{ merged: Array<string>, additions: Array<string>, removals: Array<string>, changed: boolean }}
 *   `merged` preserves the ordering of the server selection first, followed by
 *   any new additions the user made in their local copy.
 */
export function rebaseSquadSelection({ baseline, local, server }) {
  const baselineIds = toStringIds(baseline);
  const localIds = toStringIds(local);
  const serverIds = toStringIds(server);

  const baselineSet = new Set(baselineIds);
  const localSet = new Set(localIds);

  const additions = localIds.filter((id) => !baselineSet.has(id));
  const removals = baselineIds.filter((id) => !localSet.has(id));

  const removalSet = new Set(removals);
  const additionSet = new Set(additions);

  const mergedSet = new Set();
  const merged = [];

  for (const id of serverIds) {
    if (removalSet.has(id)) continue;
    if (!mergedSet.has(id)) {
      mergedSet.add(id);
      merged.push(id);
    }
  }

  for (const id of localIds) {
    if (!additionSet.has(id)) continue;
    if (removalSet.has(id)) continue;
    if (!mergedSet.has(id)) {
      mergedSet.add(id);
      merged.push(id);
    }
  }

  const serverSet = new Set(serverIds);
  const changed = merged.length !== serverIds.length
    || merged.some((id, index) => id !== serverIds[index])
    || additions.some((id) => !serverSet.has(id));

  return { merged, additions, removals, changed };
}

/**
 * Last-write-wins merge for a single scalar field (difficulty).
 * If the local value differs from the baseline, the local edit wins; otherwise
 * the server value is kept. Callers pass the three states and get the resolved
 * value back along with a boolean indicating whether the local edit should be
 * persisted in the retry.
 *
 * @param {Object} params
 * @param {string|null|undefined} params.baseline
 * @param {string|null|undefined} params.local
 * @param {string|null|undefined} params.server
 */
export function rebaseScalar({ baseline, local, server }) {
  const localChanged = baseline !== local;
  return {
    merged: localChanged ? local : server,
    changed: localChanged && local !== server
  };
}
