import React from 'react';
import { GHOST_TILT_DEG } from '../components/game/formations/DragGhost';

// FLIP swap animation for drag-drop. Must be called from exactly one place in
// the tree (GameScreen) — running it from multiple subscribers causes the
// second subscriber's getBoundingClientRect to read the first subscriber's
// just-committed pre-transition transform, which collapses dx/dy to zero and
// kills the source's slide.
export function useDragFlipAnimation(swapAnimation) {
  const flipAnimationKeyRef = React.useRef(null);

  React.useEffect(() => {
    if (!swapAnimation || !swapAnimation.targetPlayerId || !swapAnimation.targetFromRect) {
      return undefined;
    }
    const animationKey = `${swapAnimation.targetPlayerId}|${swapAnimation.sourcePlayerId || ''}:${swapAnimation.startedAt}`;
    if (flipAnimationKeyRef.current === animationKey) {
      return undefined;
    }
    flipAnimationKeyRef.current = animationKey;
    if (typeof document === 'undefined') return undefined;

    const cleanups = [];
    const easing = 'cubic-bezier(0.2, 0.8, 0.2, 1)';
    const durationMs = swapAnimation.durationMs;

    // Target card: pure translate FLIP back to its new slot.
    const targetEl = document.querySelector(`[data-drag-player-id="${swapAnimation.targetPlayerId}"]`);
    if (targetEl) {
      const toRect = targetEl.getBoundingClientRect();
      const fromRect = swapAnimation.targetFromRect;
      const dx = fromRect.left - toRect.left;
      const dy = fromRect.top - toRect.top;
      if (Math.abs(dx) >= 0.5 || Math.abs(dy) >= 0.5) {
        targetEl.style.transition = 'none';
        targetEl.style.transform = `translate(${dx}px, ${dy}px)`;
        targetEl.style.zIndex = '40';
        void targetEl.offsetWidth;
        targetEl.style.transition = `transform ${durationMs}ms ${easing}`;
        targetEl.style.transform = 'translate(0, 0)';
        const timer = setTimeout(() => {
          targetEl.style.transition = '';
          targetEl.style.transform = '';
          targetEl.style.zIndex = '';
        }, durationMs + 30);
        cleanups.push(() => {
          clearTimeout(timer);
          targetEl.style.transition = '';
          targetEl.style.transform = '';
          targetEl.style.zIndex = '';
        });
      }
    }

    // Source card: translate from the ghost's release point AND rotate from the
    // ghost's tilt back to horizontal. Runs even when dx/dy ≈ 0 so the rotation
    // still plays when the user drops nearly on the source's own slot.
    // Also overlays the ghost's color palette (slate-800/95 bg, sky-300 border,
    // sky-100 text, sky glow) for the duration of the slide so the user can
    // visually track the moved card — values mirror DragGhost.js's Tailwind classes.
    if (swapAnimation.sourcePlayerId && swapAnimation.sourceFromRect) {
      const sourceEl = document.querySelector(`[data-drag-player-id="${swapAnimation.sourcePlayerId}"]`);
      if (sourceEl) {
        const toRect = sourceEl.getBoundingClientRect();
        const fromRect = swapAnimation.sourceFromRect;
        const dx = fromRect.left - toRect.left;
        const dy = fromRect.top - toRect.top;
        sourceEl.style.transition = 'none';
        sourceEl.style.transform = `translate(${dx}px, ${dy}px) rotate(${GHOST_TILT_DEG}deg)`;
        sourceEl.style.zIndex = '40';
        sourceEl.style.backgroundColor = 'rgba(30, 41, 59, 0.95)';
        sourceEl.style.borderColor = 'rgb(125, 211, 252)';
        sourceEl.style.color = 'rgb(224, 242, 254)';
        sourceEl.style.boxShadow = '0 18px 36px -10px rgba(2,132,199,0.65), 0 0 0 1px rgba(125,211,252,0.55)';
        void sourceEl.offsetWidth;
        sourceEl.style.transition = `transform ${durationMs}ms ${easing}`;
        sourceEl.style.transform = 'translate(0, 0) rotate(0deg)';
        const clearSourceStyles = () => {
          sourceEl.style.transition = '';
          sourceEl.style.transform = '';
          sourceEl.style.zIndex = '';
          sourceEl.style.backgroundColor = '';
          sourceEl.style.borderColor = '';
          sourceEl.style.color = '';
          sourceEl.style.boxShadow = '';
        };
        const timer = setTimeout(clearSourceStyles, durationMs + 30);
        cleanups.push(() => {
          clearTimeout(timer);
          clearSourceStyles();
        });
      }
    }

    if (cleanups.length === 0) return undefined;
    return () => cleanups.forEach((fn) => fn());
  }, [swapAnimation]);
}
