import React, { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react';
import PropTypes from 'prop-types';
import { Button, CompactSelect } from '../../shared/UI';
import { Portal } from '../../shared';
import { PlayerSelector } from './PlayerSelector';

import { useListDragAndDrop } from '../../../hooks/useListDragAndDrop';
import { DraggablePlayerCard } from './DraggablePlayerCard';
import { useTranslation } from 'react-i18next';
import { DEFAULT_MATCH_DIFFICULTY, getMatchDifficultyOptions } from '../../../constants/matchDifficulties';
import { DEFAULT_MATCH_TYPE, getMatchTypeOptions } from '../../../constants/matchTypes';
import { DEFAULT_VENUE_TYPE, getVenueTypeOptions } from '../../../constants/matchVenues';
import { FORMATS, FORMAT_CONFIGS } from '../../../constants/teamConfiguration';
import { AUTO_SAVE_STATUS } from '../../../hooks/useAutoSavePlan';
import { PENDING_MATCH_STATE, PLANNED_MATCH_STATE } from '../../../constants/planMatchesConstants';

export function MatchCard({
  match,
  matchId,
  matchCount,
  roster,
  rosterById,
  selectedIds,
  invitedIds,
  unavailableIds,
  providerUnavailableIds,
  playerResponses,
  planningStatus,
  canPlan,
  isSelectedInOtherMatch,
  isSelectedAndOnlyAvailableHere,
  onResetProviderOverrides,
  onPlanMatch,
  onToggleSelect,
  onToggleUnavailable,
  formatSchedule,
  isPlayerInMultipleMatches,
  onReorderSelectedPlayers,
  registerContainer,
  onCrossDragMove,
  onCrossDragEnd,
  crossMatchState,
  swapAnimation,
  slideInAnimation,
  sortMetric,
  difficulty,
  onDifficultyChange,
  matchType,
  onMatchTypeChange,
  venueType,
  onVenueTypeChange,
  format,
  onFormatChange,
  autoSaveStatus,
  readOnly = false,
  onRetryAutoSave
}) {
  const { t } = useTranslation('team');
  const difficultyOptions = useMemo(() => (
    getMatchDifficultyOptions(t).map(option => ({ value: option.value, label: option.label }))
  ), [t]);
  const matchTypeOptions = useMemo(() => (
    getMatchTypeOptions(t).map(option => ({ value: option.value, label: option.label }))
  ), [t]);
  const venueTypeOptions = useMemo(() => (
    getVenueTypeOptions(t).map(option => ({ value: option.value, label: option.label }))
  ), [t]);
  // Limit format options to formats that have at least one available formation
  // today; that keeps the dropdown to 5v5 / 7v7 even though FORMATS includes
  // placeholders for future expansions.
  const formatOptions = useMemo(() => (
    Object.values(FORMATS)
      .filter((value) => FORMAT_CONFIGS[value])
      .map((value) => ({ value, label: FORMAT_CONFIGS[value].label }))
  ), []);
  const effectiveDifficulty = difficulty || DEFAULT_MATCH_DIFFICULTY;
  const effectiveMatchType = matchType || DEFAULT_MATCH_TYPE;
  const effectiveVenueType = venueType || DEFAULT_VENUE_TYPE;
  const effectiveFormat = format || FORMATS.FORMAT_5V5;
  const unavailableSet = useMemo(() => new Set(unavailableIds || []), [unavailableIds]);
  const displayRoster = useMemo(() => {
    return [
      ...(roster || []).filter(player => !unavailableSet.has(player.id)),
      ...(roster || []).filter(player => unavailableSet.has(player.id))
    ];
  }, [roster, unavailableSet]);

  const plannedState = planningStatus || null;
  const isPlanning = plannedState === 'loading';
  const isPlanned = plannedState === 'done';
  const isAutoSaveManaged = match?.state === PLANNED_MATCH_STATE || match?.state === PENDING_MATCH_STATE;
  const effectiveStatus = autoSaveStatus?.status || AUTO_SAVE_STATUS.IDLE;
  const autoSaveError = autoSaveStatus?.error || null;

  const statusChipLabel = useMemo(() => {
    if (!isAutoSaveManaged) return null;
    switch (effectiveStatus) {
      case AUTO_SAVE_STATUS.SAVING:
        return t('planMatches.matchCard.autoSaveSaving');
      case AUTO_SAVE_STATUS.PENDING:
        return t('planMatches.matchCard.autoSavePending');
      case AUTO_SAVE_STATUS.ERROR:
        return t('planMatches.matchCard.autoSaveError');
      case AUTO_SAVE_STATUS.OFFLINE:
        return t('planMatches.matchCard.autoSaveOffline');
      case AUTO_SAVE_STATUS.IDLE:
      default:
        return t('planMatches.matchCard.autoSaveIdle');
    }
  }, [effectiveStatus, isAutoSaveManaged, t]);

  const statusChipClass = useMemo(() => {
    switch (effectiveStatus) {
      case AUTO_SAVE_STATUS.ERROR:
        return 'bg-rose-500/10 text-rose-300 border-rose-500/40';
      case AUTO_SAVE_STATUS.OFFLINE:
        return 'bg-amber-500/10 text-amber-300 border-amber-500/40';
      case AUTO_SAVE_STATUS.SAVING:
      case AUTO_SAVE_STATUS.PENDING:
        return 'bg-sky-500/10 text-sky-200 border-sky-500/40';
      case AUTO_SAVE_STATUS.IDLE:
      default:
        return 'bg-slate-700/60 text-slate-300 border-slate-600';
    }
  }, [effectiveStatus]);

  const selectedPlayers = useMemo(() => {
    return (selectedIds || [])
      .map((playerId) => rosterById.get(playerId))
      .filter(Boolean);
  }, [rosterById, selectedIds]);

  const listContainerRef = useRef(null);
  const flipCleanupRef = useRef(null);
  const slideInOverlayRef = useRef(null);
  const slideInDelayRef = useRef(null);
  const [slideInReady, setSlideInReady] = useState(false);

  const isTargetOfSlideIn = slideInAnimation && slideInAnimation.targetMatchId === matchId;

  const isBeingDisplaced = useCallback((playerId) => {
    if (!isTargetOfSlideIn) return false;
    return String(slideInAnimation.targetPlayerId) === String(playerId);
  }, [isTargetOfSlideIn, slideInAnimation]);

  const slideInSourcePlayer = useMemo(() => {
    if (!isTargetOfSlideIn) return null;
    return rosterById.get(slideInAnimation.sourcePlayerId) || null;
  }, [isTargetOfSlideIn, slideInAnimation, rosterById]);

  // Slide-in overlay positioning
  useLayoutEffect(() => {
    if (!isTargetOfSlideIn || !slideInAnimation.targetRect || !slideInAnimation.releasePosition) {
      setSlideInReady(false);
      return;
    }

    const overlay = slideInOverlayRef.current;
    if (!overlay) {
      setSlideInReady(false);
      return;
    }

    const { targetRect, releasePosition } = slideInAnimation;

    // Position overlay at target rect (fixed)
    overlay.style.position = 'fixed';
    overlay.style.left = `${targetRect.left}px`;
    overlay.style.top = `${targetRect.top}px`;
    overlay.style.width = `${targetRect.width}px`;

    // Calculate inverse transform: from release position (pointer-centered) to target slot
    const targetCenterX = targetRect.left + targetRect.width / 2;
    const targetCenterY = targetRect.top + targetRect.height / 2;
    const dx = releasePosition.x - targetCenterX;
    const dy = releasePosition.y - targetCenterY;

    // Start at release position with slight scale-up
    overlay.style.transition = 'none';
    overlay.style.transform = `translate(${dx}px, ${dy}px) scale(1.05)`;
    overlay.style.opacity = '0.9';

    // Force reflow
    overlay.getBoundingClientRect();

    setSlideInReady(true);

    // After a small delay, animate to target position
    slideInDelayRef.current = setTimeout(() => {
      slideInDelayRef.current = null;
      if (overlay) {
        overlay.style.transition = 'transform 400ms ease-out, opacity 400ms ease-out';
        overlay.style.transform = 'translate(0, 0) scale(1)';
        overlay.style.opacity = '1';
      }
    }, 100);

    return () => {
      if (slideInDelayRef.current) {
        clearTimeout(slideInDelayRef.current);
        slideInDelayRef.current = null;
      }
    };
  }, [isTargetOfSlideIn, slideInAnimation]);

  useLayoutEffect(() => {
    if (!swapAnimation || swapAnimation.toMatchId !== matchId) return;

    const container = listContainerRef.current;
    if (!container) return;

    const card = container.querySelector(
      `[data-drag-item-id="${swapAnimation.playerId}"]`
    );
    if (!card) return;

    const toRect = card.getBoundingClientRect();
    const dx = swapAnimation.fromRect.left - toRect.left;
    const dy = swapAnimation.fromRect.top - toRect.top;

    card.style.transition = 'none';
    card.style.transform = `translate(${dx}px, ${dy}px)`;
    card.style.zIndex = '50';

    // Force reflow
    card.getBoundingClientRect();

    card.style.transition = 'transform 300ms ease-out';
    card.style.transform = 'translate(0, 0)';

    if (flipCleanupRef.current) {
      clearTimeout(flipCleanupRef.current);
    }

    flipCleanupRef.current = setTimeout(() => {
      if (card && card.isConnected) {
        card.style.transition = '';
        card.style.transform = '';
        card.style.zIndex = '';
      }
      flipCleanupRef.current = null;
    }, 320);

    return () => {
      if (flipCleanupRef.current) {
        clearTimeout(flipCleanupRef.current);
        flipCleanupRef.current = null;
      }
    };
  }, [swapAnimation, matchId]);

  useEffect(() => {
    if (matchCount > 1 && registerContainer && matchId) {
      return registerContainer(matchId, listContainerRef);
    }
  }, [matchCount, registerContainer, matchId]);

  const handleLocalDragMove = useCallback((moveData) => {
    if (onCrossDragMove && matchId) {
      onCrossDragMove(moveData, matchId);
    }
  }, [onCrossDragMove, matchId]);

  const handleLocalDragEnd = useCallback((endData) => {
    if (onCrossDragEnd && matchId) {
      onCrossDragEnd(endData, matchId);
    }
  }, [onCrossDragEnd, matchId]);

  const isSwapTarget = useCallback((playerId) => {
    if (!crossMatchState?.active) return false;
    return (
      crossMatchState.targetMatchId === matchId &&
      crossMatchState.hoveredPlayerId === String(playerId) &&
      crossMatchState.isEligible
    );
  }, [crossMatchState, matchId]);

  const {
    isDragging,
    draggedItemId,
    ghostPosition,
    ghostSize,
    ghostOffset,
    handlePointerStart,
    isItemBeingDragged,
    isItemDragActivating,
    getItemShift,
    shouldSuppressClick
  } = useListDragAndDrop({
    items: selectedPlayers,
    onReorder: (reorderedPlayers) => {
      if (!onReorderSelectedPlayers) {
        return;
      }
      const newOrderedIds = reorderedPlayers.map((player) => player.id);
      onReorderSelectedPlayers(match.id, newOrderedIds);
    },
    containerRef: listContainerRef,
    activationThreshold: { time: 300, distance: 10 },
    onDragMove: matchCount > 1 ? handleLocalDragMove : undefined,
    onDragEnd: matchCount > 1 ? handleLocalDragEnd : undefined
  });

  const ghostPlayer = useMemo(() => {
    if (!draggedItemId) {
      return null;
    }
    return selectedPlayers.find((player) => String(player.id) === String(draggedItemId)) || null;
  }, [draggedItemId, selectedPlayers]);

  return (
    <div className="bg-slate-800/70 border border-slate-700 rounded-lg p-3 space-y-3" data-testid={`match-card-${matchId}`}>
      <div className="grid grid-cols-2 gap-2 items-start">
        <div className="flex items-center gap-2">
          {isAutoSaveManaged ? (
            <button
              type="button"
              onClick={effectiveStatus === AUTO_SAVE_STATUS.ERROR && onRetryAutoSave ? () => onRetryAutoSave(matchId) : undefined}
              disabled={effectiveStatus !== AUTO_SAVE_STATUS.ERROR || !onRetryAutoSave}
              title={autoSaveError || undefined}
              data-testid={`auto-save-status-${matchId}`}
              className={`text-xs px-2 py-1 rounded border ${statusChipClass} ${effectiveStatus === AUTO_SAVE_STATUS.ERROR && onRetryAutoSave ? 'cursor-pointer hover:brightness-110' : 'cursor-default'}`}
            >
              {statusChipLabel}
            </button>
          ) : (
            <Button
              size="sm"
              variant={isPlanned ? 'secondary' : 'accent'}
              onClick={onPlanMatch}
              disabled={isPlanning || isPlanned || !canPlan || readOnly}
              className="px-2"
            >
              {isPlanning ? t('planMatches.matchCard.saving') : isPlanned ? t('planMatches.matchCard.saved') : t('planMatches.matchCard.save')}
            </Button>
          )}
          <Button
            size="sm"
            variant="secondary"
            onClick={onResetProviderOverrides}
            disabled={isPlanning || isPlanned || !onResetProviderOverrides || readOnly}
            className="px-2"
          >
            {t('planMatches.matchCard.reset')}
          </Button>
        </div>

        <div className="flex items-center justify-end gap-3 min-w-0 text-right">
          <div className="min-w-0">
            <div className="truncate text-sm font-semibold text-slate-100">{match.opponent}</div>
            <div className="text-xs text-slate-400">{formatSchedule(match.matchDate, match.matchTime, match.plannedStartTime)}</div>
          </div>
        </div>
      </div>

      {/*
        One cell per field. Each cell is a two-column inner grid so labels
        occupy a fixed-width column and selects fill the remaining space —
        that way every select starts at the same x within its cell and
        stretches to the cell's right edge, regardless of how long the
        option text is. Outer grid stacks to one column on narrow screens.
      */}
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-4 gap-y-2">
        <div className="grid grid-cols-[5rem_minmax(0,1fr)] items-center gap-2">
          <label htmlFor={`match-difficulty-${matchId}`} className="text-xs text-slate-400 truncate">
            {t('planMatches.matchCard.difficultyLabel')}
          </label>
          <CompactSelect
            id={`match-difficulty-${matchId}`}
            data-testid={`match-difficulty-${matchId}`}
            value={effectiveDifficulty}
            onChange={(value) => onDifficultyChange && onDifficultyChange(matchId, value)}
            disabled={isPlanning || !onDifficultyChange || readOnly}
            options={difficultyOptions}
            className="w-full"
          />
        </div>
        <div className="grid grid-cols-[5rem_minmax(0,1fr)] items-center gap-2">
          <label htmlFor={`match-type-${matchId}`} className="text-xs text-slate-400 truncate">
            {t('planMatches.matchCard.matchTypeLabel')}
          </label>
          <CompactSelect
            id={`match-type-${matchId}`}
            data-testid={`match-type-${matchId}`}
            value={effectiveMatchType}
            onChange={(value) => onMatchTypeChange && onMatchTypeChange(matchId, value)}
            disabled={isPlanning || !onMatchTypeChange || readOnly}
            options={matchTypeOptions}
            className="w-full"
          />
        </div>
        <div className="grid grid-cols-[5rem_minmax(0,1fr)] items-center gap-2">
          <label htmlFor={`match-venue-${matchId}`} className="text-xs text-slate-400 truncate">
            {t('planMatches.matchCard.venueLabel')}
          </label>
          <CompactSelect
            id={`match-venue-${matchId}`}
            data-testid={`match-venue-${matchId}`}
            value={effectiveVenueType}
            onChange={(value) => onVenueTypeChange && onVenueTypeChange(matchId, value)}
            disabled={isPlanning || !onVenueTypeChange || readOnly}
            options={venueTypeOptions}
            className="w-full"
          />
        </div>
        <div className="grid grid-cols-[5rem_minmax(0,1fr)] items-center gap-2">
          <label htmlFor={`match-format-${matchId}`} className="text-xs text-slate-400 truncate">
            {t('planMatches.matchCard.formatLabel')}
          </label>
          <CompactSelect
            id={`match-format-${matchId}`}
            data-testid={`match-format-${matchId}`}
            value={effectiveFormat}
            onChange={(value) => onFormatChange && onFormatChange(matchId, value)}
            disabled={isPlanning || !onFormatChange || readOnly}
            options={formatOptions}
            className="w-full"
          />
        </div>
      </div>

      <div className="grid grid-cols-2 gap-2">
        <div className="space-y-1">
          <div className="flex items-center justify-between text-xs text-slate-400">
            <span>{t('planMatches.matchCard.roster')}</span>
            <span>{roster?.length || 0}</span>
          </div>
          <PlayerSelector
            players={displayRoster}
            selectedIds={selectedIds}
            invitedIds={invitedIds}
            unavailableIds={unavailableIds}
            providerUnavailableIds={providerUnavailableIds}
            onToggleSelect={readOnly ? undefined : onToggleSelect}
            onToggleUnavailable={readOnly ? undefined : onToggleUnavailable}
            isSelectedInOtherMatch={isSelectedInOtherMatch}
            isSelectedAndOnlyAvailableHere={isSelectedAndOnlyAvailableHere}
            sortMetric={sortMetric}
          />
        </div>

        <div className="space-y-1">
          <div className="flex items-center justify-between text-xs text-slate-400">
            <span>{t('planMatches.matchCard.selected')}</span>
            <span>{selectedIds.length}</span>
          </div>
          <div ref={listContainerRef} className="space-y-1 pr-1">
            {selectedPlayers.map((player) => (
              <DraggablePlayerCard
                key={player.id}
                player={player}
                isDragging={isItemBeingDragged(player.id)}
                shift={getItemShift(player.id)}
                onPointerStart={(event) => handlePointerStart(player.id, event)}
                onClick={() => {
                  if (shouldSuppressClick(player.id)) {
                    return;
                  }
                  onToggleSelect(player.id);
                }}
                isInMultipleMatches={isPlayerInMultipleMatches(player.id)}
                isSelectedAndOnlyAvailableHere={isSelectedAndOnlyAvailableHere(player.id)}
                isDragActivating={isItemDragActivating(player.id)}
                isSwapTarget={isSwapTarget(player.id)}
                isSwapLanding={
                  swapAnimation
                  && swapAnimation.sourceNewMatchId === matchId
                  && String(swapAnimation.sourcePlayerId) === String(player.id)
                }
                isBeingDisplaced={isBeingDisplaced(player.id)}
                responseStatus={playerResponses ? playerResponses[player.id] || null : null}
                isUnavailable={unavailableSet.has(player.id)}
                sortMetric={sortMetric}
              />
            ))}
            {selectedPlayers.length === 0 && (
              <div className="rounded border border-slate-700 bg-slate-900/30 px-2 py-2 text-xs text-slate-400">
                {t('planMatches.matchCard.empty')}
              </div>
            )}
            {isDragging && ghostPosition && ghostPlayer && (
              <Portal>
                <div
                  className="fixed pointer-events-none z-[1000] ghost-card"
                  style={{
                    left: ghostPosition.x - (ghostOffset?.x ?? 0),
                    top: ghostPosition.y - (ghostOffset?.y ?? 0),
                    width: ghostSize?.width ? `${ghostSize.width}px` : undefined,
                    transform: 'scale(0.98)',
                    transformOrigin: ghostOffset
                      ? `${ghostOffset.x}px ${ghostOffset.y}px`
                      : 'center center',
                    opacity: 0.9
                  }}
                >
                  <DraggablePlayerCard
                    player={ghostPlayer}
                    isDragging={false}
                    shift={0}
                    isInMultipleMatches={isPlayerInMultipleMatches(ghostPlayer.id)}
                    isSelectedAndOnlyAvailableHere={isSelectedAndOnlyAvailableHere(ghostPlayer.id)}
                    responseStatus={playerResponses ? playerResponses[ghostPlayer.id] || null : null}
                    sortMetric={sortMetric}
                  />
                </div>
              </Portal>
            )}
            {isTargetOfSlideIn && slideInSourcePlayer && (
              <Portal>
                <div
                  ref={slideInOverlayRef}
                  className="slide-in-overlay"
                  style={{ visibility: slideInReady ? 'visible' : 'hidden' }}
                >
                  <DraggablePlayerCard
                    player={slideInSourcePlayer}
                    isDragging={false}
                    shift={0}
                    isInMultipleMatches={isPlayerInMultipleMatches(slideInSourcePlayer.id)}
                    isSelectedAndOnlyAvailableHere={isSelectedAndOnlyAvailableHere(slideInSourcePlayer.id)}
                    responseStatus={playerResponses ? playerResponses[slideInSourcePlayer.id] || null : null}
                    sortMetric={sortMetric}
                  />
                </div>
              </Portal>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

MatchCard.propTypes = {
  match: PropTypes.shape({
    id: PropTypes.oneOfType([PropTypes.string, PropTypes.number]).isRequired,
    opponent: PropTypes.string,
    matchDate: PropTypes.string,
    matchTime: PropTypes.string,
    plannedStartTime: PropTypes.string
  }).isRequired,
  matchId: PropTypes.oneOfType([PropTypes.string, PropTypes.number]).isRequired,
  matchCount: PropTypes.number.isRequired,
  roster: PropTypes.arrayOf(
    PropTypes.shape({
      id: PropTypes.oneOfType([PropTypes.string, PropTypes.number]).isRequired,
      displayName: PropTypes.string.isRequired
    })
  ),
  rosterById: PropTypes.instanceOf(Map).isRequired,
  selectedIds: PropTypes.arrayOf(
    PropTypes.oneOfType([PropTypes.string, PropTypes.number])
  ).isRequired,
  invitedIds: PropTypes.arrayOf(
    PropTypes.oneOfType([PropTypes.string, PropTypes.number])
  ),
  unavailableIds: PropTypes.arrayOf(
    PropTypes.oneOfType([PropTypes.string, PropTypes.number])
  ),
  providerUnavailableIds: PropTypes.arrayOf(
    PropTypes.oneOfType([PropTypes.string, PropTypes.number])
  ),
  playerResponses: PropTypes.objectOf(
    PropTypes.oneOf(['accepted', 'declined', 'no_response'])
  ),
  planningStatus: PropTypes.oneOf(['loading', 'done', null]),
  canPlan: PropTypes.bool,
  isSelectedInOtherMatch: PropTypes.func,
  isSelectedAndOnlyAvailableHere: PropTypes.func.isRequired,
  onResetProviderOverrides: PropTypes.func,
  onPlanMatch: PropTypes.func.isRequired,
  onToggleSelect: PropTypes.func.isRequired,
  onToggleUnavailable: PropTypes.func,
  formatSchedule: PropTypes.func.isRequired,
  isPlayerInMultipleMatches: PropTypes.func.isRequired,
  onReorderSelectedPlayers: PropTypes.func,
  registerContainer: PropTypes.func,
  onCrossDragMove: PropTypes.func,
  onCrossDragEnd: PropTypes.func,
  crossMatchState: PropTypes.shape({
    active: PropTypes.bool,
    targetMatchId: PropTypes.oneOfType([PropTypes.string, PropTypes.number]),
    hoveredPlayerId: PropTypes.string,
    isEligible: PropTypes.bool
  }),
  swapAnimation: PropTypes.shape({
    playerId: PropTypes.oneOfType([PropTypes.string, PropTypes.number]),
    toMatchId: PropTypes.oneOfType([PropTypes.string, PropTypes.number]),
    fromRect: PropTypes.object,
    sourceNewMatchId: PropTypes.oneOfType([PropTypes.string, PropTypes.number]),
    sourcePlayerId: PropTypes.oneOfType([PropTypes.string, PropTypes.number])
  }),
  slideInAnimation: PropTypes.shape({
    targetMatchId: PropTypes.oneOfType([PropTypes.string, PropTypes.number]),
    targetPlayerId: PropTypes.oneOfType([PropTypes.string, PropTypes.number]),
    sourcePlayerId: PropTypes.oneOfType([PropTypes.string, PropTypes.number]),
    targetRect: PropTypes.object,
    releasePosition: PropTypes.shape({
      x: PropTypes.number,
      y: PropTypes.number
    })
  }),
  sortMetric: PropTypes.string,
  difficulty: PropTypes.string,
  onDifficultyChange: PropTypes.func,
  matchType: PropTypes.string,
  onMatchTypeChange: PropTypes.func,
  venueType: PropTypes.string,
  onVenueTypeChange: PropTypes.func,
  format: PropTypes.string,
  onFormatChange: PropTypes.func,
  autoSaveStatus: PropTypes.shape({
    status: PropTypes.oneOf(Object.values(AUTO_SAVE_STATUS)),
    lastSyncedAt: PropTypes.string,
    lastUpdatedBy: PropTypes.string,
    error: PropTypes.string
  }),
  readOnly: PropTypes.bool,
  onRetryAutoSave: PropTypes.func
};
