/**
 * Plan Matches Link Utilities
 *
 * Shared functions for generating and copying plan-matches URLs.
 * Used by PlanMatchesScreen for sharing planned match selections with fellow coaches.
 */

/**
 * Generate a shareable URL for planned matches.
 * @param {string[]} matchIds - Array of match UUIDs
 * @returns {string} Plan matches URL (e.g. https://example.com/plan/id1,id2)
 * @throws {Error} If matchIds is empty or not provided
 */
export function generatePlanMatchesUrl(matchIds) {
  if (!Array.isArray(matchIds) || matchIds.length === 0) {
    throw new Error('At least one match ID is required to generate plan matches URL');
  }
  return `${window.location.origin}/plan/${matchIds.join(',')}`;
}

/**
 * Copy plan matches URL to clipboard.
 *
 * Attempts to copy the URL to clipboard using the Clipboard API.
 * If the Clipboard API is not available or fails, returns the URL
 * for fallback display.
 *
 * @param {string[]} matchIds - Array of match UUIDs
 * @returns {Promise<{success: boolean, url: string, error?: string}>}
 */
export async function copyPlanMatchesUrlToClipboard(matchIds) {
  let url;
  try {
    url = generatePlanMatchesUrl(matchIds);
  } catch (error) {
    return { success: false, url: '', error: error.message };
  }
  try {
    if (navigator.clipboard && navigator.clipboard.writeText) {
      await navigator.clipboard.writeText(url);
      return { success: true, url };
    }
    return { success: false, url, error: 'Clipboard API not available' };
  } catch (error) {
    console.error('Failed to copy plan matches URL:', error);
    return { success: false, url, error: error.message };
  }
}
