import { useState, useEffect, useCallback, useRef } from 'react';
import { supabase } from '../lib/supabase';

/**
 * Subscribes to real-time ownership changes for a single running match.
 * Sets `takenOver` to true only when the current user *was* the owner of
 * the match during this subscription and ownership has now flipped to a
 * different user on a still-running match.
 *
 * The hook resolves the user's "was owner" status from two sources:
 *   1. An initial fetch of `match.owned_by` when the subscription begins.
 *   2. Any subsequent realtime event whose `owned_by` equals `userId`
 *      (e.g. self-claim after starting a match).
 *
 * Realtime events that arrive before the initial fetch resolves are
 * buffered and replayed once the fetch completes, preserving order.
 *
 * `ownedByOther` is true when the watched match is currently claimed by a
 * different user (DB `owned_by` is set and not this user). An unclaimed match
 * (`owned_by` null — the original runner) reads as false: that runner is the
 * de-facto owner.
 *
 * @param {string|null} matchId - The match to watch
 * @param {string|null} userId  - The current user's auth ID (auth.users.id)
 * @returns {{ takenOver: boolean, ownedByOther: boolean, clear: Function }}
 */
export function useMatchOwnershipWatch(matchId, userId) {
  const [takenOver, setTakenOver] = useState(false);
  const [ownedByOther, setOwnedByOther] = useState(false);
  const wasOwnerRef = useRef(false);

  useEffect(() => {
    if (!matchId || !userId) {
      setOwnedByOther(false);
      return;
    }

    let cancelled = false;
    const pendingEvents = [];
    let fetchDone = false;
    wasOwnerRef.current = false;
    setTakenOver(false);
    setOwnedByOther(false);

    const processEvent = (payload) => {
      const next = payload?.new;
      if (!next) return;
      setOwnedByOther(Boolean(next.owned_by) && next.owned_by !== userId);
      if (next.owned_by === userId) {
        wasOwnerRef.current = true;
        return;
      }
      if (
        wasOwnerRef.current &&
        next.owned_by &&
        next.owned_by !== userId &&
        next.state === 'running'
      ) {
        setTakenOver(true);
      }
    };

    const channel = supabase
      .channel(`match_ownership:${matchId}`)
      .on(
        'postgres_changes',
        {
          event: 'UPDATE',
          schema: 'public',
          table: 'match',
          filter: `id=eq.${matchId}`,
        },
        (payload) => {
          if (!fetchDone) {
            pendingEvents.push(payload);
            return;
          }
          processEvent(payload);
        }
      )
      .subscribe();

    (async () => {
      try {
        const { data } = await supabase
          .from('match')
          .select('owned_by, state')
          .eq('id', matchId)
          .maybeSingle();
        if (cancelled) return;
        setOwnedByOther(Boolean(data?.owned_by) && data.owned_by !== userId);
        if (data?.owned_by === userId) {
          wasOwnerRef.current = true;
        }
      } catch (err) {
        // Swallow: wasOwnerRef stays false (safe default — no false
        // positives), and the finally block still drains pending events
        // so subsequent realtime updates aren't stranded.
        console.error('[useMatchOwnershipWatch] initial fetch failed', err);
      } finally {
        if (!cancelled) {
          fetchDone = true;
          while (pendingEvents.length > 0) {
            processEvent(pendingEvents.shift());
          }
        }
      }
    })();

    return () => {
      cancelled = true;
      supabase.removeChannel(channel);
    };
  }, [matchId, userId]);

  const clear = useCallback(() => setTakenOver(false), []);

  return { takenOver, ownedByOther, clear };
}
