import { useEffect, useRef } from 'react';
import { supabase } from '../lib/supabase';

/**
 * Subscribe to plan-relevant updates on `match` rows for a team.
 *
 * Fires `onPlanChange({ matchId, planVersion, selection, difficulty,
 * matchType, venueType, format, formation, lastUpdatedBy, updatedAt,
 * state })` whenever another coach edits `initial_config`, `difficulty`,
 * `type`, `venue_type`, or `format` on a planned/pending match. Callers
 * use this to reconcile their local view with remote edits.
 *
 * The listener is wired to the same Postgres table as
 * `useRealtimeTeamMatches`, but we only forward the fields the planner cares
 * about and rely on `plan_version` as the OCC token.
 *
 * @param {string|null|undefined} teamId
 * @param {(payload: Object) => void} onPlanChange
 */
export function useRealtimeMatchPlan(teamId, onPlanChange) {
  const callbackRef = useRef(onPlanChange);
  callbackRef.current = onPlanChange;

  useEffect(() => {
    if (!teamId) return undefined;

    let isActive = true;

    const channel = supabase
      .channel(`plan_match_changes:${teamId}`)
      .on(
        'postgres_changes',
        {
          event: 'UPDATE',
          schema: 'public',
          table: 'match',
          filter: `team_id=eq.${teamId}`
        },
        (payload) => {
          if (!isActive) return;
          const updated = payload?.new;
          if (!updated) return;

          // Only forward events for rows that can actually be edited from the planner.
          if (updated.state !== 'planned' && updated.state !== 'pending') {
            return;
          }

          const initialConfig = updated.initial_config || null;
          const selection = Array.isArray(initialConfig?.squadSelection)
            ? initialConfig.squadSelection
            : [];

          const cb = callbackRef.current;
          if (typeof cb !== 'function') return;
          cb({
            matchId: updated.id,
            planVersion: updated.plan_version,
            selection,
            difficulty: updated.difficulty || null,
            matchType: updated.type || null,
            venueType: updated.venue_type || null,
            format: updated.format || null,
            formation: initialConfig?.teamConfig?.formation || null,
            lastUpdatedBy: updated.last_updated_by || null,
            updatedAt: updated.updated_at || null,
            state: updated.state || null,
            initialConfig
          });
        }
      )
      .subscribe();

    return () => {
      isActive = false;
      channel.unsubscribe();
    };
  }, [teamId]);
}
