/**
 * Live Match Link Utilities
 *
 * Shared functions for generating and copying live match URLs.
 * Used by ConfigurationScreen and HamburgerMenu for consistent behavior.
 */

/**
 * Generate live match URL.
 *
 * Accepts either the match UUID (legacy) or the short 8-char share code.
 * Prefer passing the share code for shorter, SMS-friendly links.
 *
 * @param {string} matchIdentifier - Match UUID or 8-char share code
 * @returns {string} Live match URL
 * @throws {Error} If matchIdentifier is not provided
 */
export function generateLiveMatchUrl(matchIdentifier) {
  if (!matchIdentifier) {
    throw new Error('Match ID is required to generate live match URL');
  }
  return `${window.location.origin}/live/${matchIdentifier}`;
}

/**
 * Pick the best identifier for a live match URL from a match record.
 * Prefers `share_code` / `shareCode` (short, opaque) over the UUID.
 *
 * @param {{id?: string, share_code?: string, shareCode?: string} | null | undefined} matchRecord
 * @returns {string} The chosen identifier
 * @throws {Error} If neither share code nor id is present
 */
export function pickLiveMatchIdentifier(matchRecord) {
  if (!matchRecord) {
    throw new Error('Match record is required to pick live match identifier');
  }
  const identifier = matchRecord.shareCode || matchRecord.share_code || matchRecord.id;
  if (!identifier) {
    throw new Error('Match record has no shareCode or id');
  }
  return identifier;
}

/**
 * Copy live match URL to clipboard
 *
 * Attempts to copy the URL to clipboard using the Clipboard API.
 * If the Clipboard API is not available or fails, returns the URL
 * for fallback display in a modal.
 *
 * @param {string} matchId - Match ID (UUID)
 * @returns {Promise<{success: boolean, url: string, error?: string}>}
 */
export async function copyLiveMatchUrlToClipboard(matchId) {
  try {
    const url = generateLiveMatchUrl(matchId);

    if (navigator.clipboard && navigator.clipboard.writeText) {
      await navigator.clipboard.writeText(url);
      return { success: true, url };
    } else {
      // Fallback for browsers without Clipboard API
      return {
        success: false,
        url,
        error: 'Clipboard API not available'
      };
    }
  } catch (error) {
    console.error('Failed to copy live match URL:', error);
    const url = generateLiveMatchUrl(matchId);
    return {
      success: false,
      url,
      error: error.message
    };
  }
}

/**
 * Format a kickoff time to local HH:MM, rounded to the nearest 5 minutes.
 * Accepts epoch ms, ISO string, or Date. Returns null for missing/invalid input.
 */
export function formatKickoffTime(input) {
  if (input === null || input === undefined) {
    return null;
  }
  const date = input instanceof Date ? input : new Date(input);
  if (Number.isNaN(date.getTime())) {
    return null;
  }
  const minutes = date.getMinutes();
  const roundedMinutes = Math.round(minutes / 5) * 5;
  const rounded = new Date(date);
  rounded.setMinutes(roundedMinutes, 0, 0);
  const hh = String(rounded.getHours()).padStart(2, '0');
  const mm = String(rounded.getMinutes()).padStart(2, '0');
  return `${hh}:${mm}`;
}
