import { PLAYER_ROLES } from '../constants/playerConstants';
import { getPositionRole } from '../game/logic/positionUtils';

export const FIELD_ROLE_DISPLAY_ORDER = [
  PLAYER_ROLES.ATTACKER,
  PLAYER_ROLES.MIDFIELDER,
  PLAYER_ROLES.DEFENDER
];

// Legacy canonical role → substitute mapping for traditional 2-2-2 same-role mode.
// New formation-aware same-role mappings are defined in teamConfiguration helpers.
// Kept for backwards compatibility with any remaining role-only consumers.
export const ROLE_TO_SUBSTITUTE_INDEX = {
  [PLAYER_ROLES.ATTACKER.toLowerCase()]: 0,
  [PLAYER_ROLES.MIDFIELDER.toLowerCase()]: 1,
  [PLAYER_ROLES.DEFENDER.toLowerCase()]: 2,
};

export const groupFieldPositionsByRole = (fieldPositions = []) => {
  if (!Array.isArray(fieldPositions) || fieldPositions.length === 0) {
    return [];
  }

  const groups = new Map();

  fieldPositions.forEach(position => {
    const role = getPositionRole(position);
    if (!role) return;

    if (!groups.has(role)) {
      groups.set(role, []);
    }
    groups.get(role).push(position);
  });

  const ordered = [];
  FIELD_ROLE_DISPLAY_ORDER.forEach(role => {
    if (groups.has(role)) {
      ordered.push({ role, positions: groups.get(role) });
    }
  });

  return ordered;
};

export const orderFieldPositionsForDisplay = (positions = []) => {
  if (!Array.isArray(positions)) {
    return [];
  }

  const ordered = [];

  FIELD_ROLE_DISPLAY_ORDER.forEach(role => {
    positions.forEach(position => {
      if (getPositionRole(position) === role) {
        ordered.push(position);
      }
    });
  });

  const orderedSet = new Set(ordered);
  positions.forEach(position => {
    if (!orderedSet.has(position)) {
      ordered.push(position);
    }
  });

  return ordered;
};
