import React, { useState, useRef, useEffect, useCallback } from 'react';
import PropTypes from 'prop-types';
import { Users, Plus } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { ModalShell } from '../shared/ModalShell';
import { Card } from '../shared/Card';
import { useTeam } from '../../contexts/TeamContext';
import { formatTeamName } from '../../utils/teamUtils';
import { VIEWS } from '../../constants/viewConstants';
import { nextWizardNonce } from '../../utils/wizardNonce';

export function TeamSelectionModal({ isOpen, onNavigateTo }) {
  const { t } = useTranslation('team');
  const { userTeams, currentTeam, switchCurrentTeam, clearTeamSelectionPrompt } = useTeam();
  const [selectingTeamId, setSelectingTeamId] = useState(null);
  const [error, setError] = useState(null);
  const selectingRef = useRef(false);

  // The modal stays mounted at App level (isOpen only toggles a null return),
  // so clear any prior error each time it reopens — e.g. from the hamburger menu.
  useEffect(() => {
    if (isOpen) setError(null);
  }, [isOpen]);

  const handleSelect = useCallback(async (teamId) => {
    if (selectingRef.current) return;
    // Selecting the already-active team is a no-op switch; just close the modal.
    if (teamId === currentTeam?.id) {
      clearTeamSelectionPrompt();
      return;
    }
    selectingRef.current = true;
    setSelectingTeamId(teamId);
    setError(null);
    try {
      await switchCurrentTeam(teamId);
      // Explicitly dismiss so the close contract doesn't depend on
      // switchCurrentTeam's internal side effect.
      clearTeamSelectionPrompt();
    } catch (e) {
      console.error('Error switching team:', e);
      setError(t('teamSelection.error'));
    } finally {
      // Modal stays mounted at App level (isOpen only toggles a null return),
      // so reset both on every attempt or the stale id keeps every row disabled.
      selectingRef.current = false;
      setSelectingTeamId(null);
    }
  }, [currentTeam, switchCurrentTeam, clearTeamSelectionPrompt, t]);

  // Open the wizard to create or request to join a team, dismissing the selection gate.
  const handleCreateOrJoin = useCallback(() => {
    if (selectingRef.current) return;
    // Navigate first so the wizard is primed before the gate closes.
    onNavigateTo(VIEWS.TEAM_MANAGEMENT, {
      openCreateWizard: true,
      openCreateWizardNonce: nextWizardNonce(),
    });
    clearTeamSelectionPrompt();
  }, [clearTeamSelectionPrompt, onNavigateTo]);

  if (!isOpen || !userTeams || userTeams.length === 0) {
    return null;
  }

  return (
    <ModalShell
      title={t('teamSelection.title')}
      icon={Users}
      iconColor="sky"
      maxWidth="lg"
      onClose={selectingTeamId ? undefined : clearTeamSelectionPrompt}
    >
      <p className="text-slate-300 text-sm mb-6">{t('teamSelection.description')}</p>
      {error && (
        <p className="text-rose-400 text-sm mb-4">{error}</p>
      )}
      <div className="space-y-2">
        {userTeams.map((team) => (
          <Card key={team.id} variant="subtle">
            <button
              type="button"
              onClick={() => handleSelect(team.id)}
              disabled={Boolean(selectingTeamId)}
              aria-label={team.id === currentTeam?.id
                ? t('teamSelection.activeTeamLabel', { name: formatTeamName(team) })
                : t('teamSelection.selectTeamLabel', { name: formatTeamName(team) })}
              className="w-full flex items-center justify-between text-left disabled:opacity-60"
            >
              <div>
                <p className="font-medium text-slate-100">{formatTeamName(team)}</p>
                <p className="text-slate-400 text-sm">
                  {team.userRole || t('teamSelection.member')}
                </p>
              </div>
              <span className={`text-sm font-medium ${team.id === currentTeam?.id ? 'text-emerald-400' : 'text-sky-400'}`}>
                {team.id === currentTeam?.id
                  ? t('teamSelection.active')
                  : selectingTeamId === team.id
                    ? t('teamSelection.selecting')
                    : t('teamSelection.select')}
              </span>
            </button>
          </Card>
        ))}
      </div>
      {/* Secondary action: a quiet text-link (shared Button has no subordinate variant) below the primary "pick a team" choice. */}
      <div className="mt-4 pt-4 border-t border-slate-600">
        <button
          type="button"
          onClick={handleCreateOrJoin}
          disabled={Boolean(selectingTeamId)}
          className="flex items-center gap-2 text-sm font-medium text-sky-400 hover:text-sky-300 transition-colors disabled:opacity-60"
        >
          <Plus className="w-4 h-4" />
          <span>{t('teamSelector.createOrJoin')}</span>
        </button>
      </div>
    </ModalShell>
  );
}

TeamSelectionModal.propTypes = {
  isOpen: PropTypes.bool.isRequired,
  onNavigateTo: PropTypes.func.isRequired,
};
