import React from 'react';
import PropTypes from 'prop-types';
import { useTranslation } from 'react-i18next';
import { Button } from '../shared/UI';
import { TeamSelector } from './TeamSelector';

export function SelectTeamView({ subtitle, onNavigateBack, onCreateTeam }) {
  const { t } = useTranslation('team');

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-bold text-sky-300">{t('teamSelection.title')}</h1>
        <Button onClick={onNavigateBack} variant="secondary" size="sm">
          {t('teamManagement.header.back')}
        </Button>
      </div>
      {subtitle && <p className="text-slate-400">{subtitle}</p>}
      <TeamSelector onCreateNew={onCreateTeam} />
    </div>
  );
}

SelectTeamView.propTypes = {
  subtitle: PropTypes.string,
  onNavigateBack: PropTypes.func.isRequired,
  onCreateTeam: PropTypes.func.isRequired
};
