import React, { useMemo } from 'react';
import PropTypes from 'prop-types';
import { Button, Input } from '../../shared/UI';
import { ModalShell } from '../../shared/ModalShell';
import { AUTO_SELECT_STRATEGY, DISTRIBUTION_STRATEGY, SINGLE_MATCH_STRATEGY } from '../../../constants/planMatchesConstants';
import { DIFFICULTY_RANK } from '../../../constants/matchDifficulties';
import { useTranslation } from 'react-i18next';

export function AutoSelectModal({
  isOpen,
  matches,
  autoSelectMatches,
  rosterCount,
  targetCounts,
  autoSelectSettings,
  onUpdateTargetCount,
  onUpdateSettings,
  onCancel,
  onConfirm,
  formatSchedule
}) {
  const { t } = useTranslation('team');

  // Compute the default strong match based on difficulty rankings.
  // If matches have different difficulties, preselect the harder match.
  const defaultStrongMatchId = useMemo(() => {
    if (!autoSelectMatches || autoSelectMatches.length < 2) {
      return autoSelectMatches?.[0]?.id ?? null;
    }
    const sorted = [...autoSelectMatches].sort((a, b) =>
      (DIFFICULTY_RANK[b.difficulty] || 0) - (DIFFICULTY_RANK[a.difficulty] || 0)
    );
    if ((DIFFICULTY_RANK[sorted[0].difficulty] || 0) > (DIFFICULTY_RANK[sorted[1].difficulty] || 0)) {
      return sorted[0].id;
    }
    return autoSelectMatches[0].id;
  }, [autoSelectMatches]);

  if (!isOpen) {
    return null;
  }

  const isMultiMatch = matches.length > 1;

  return (
    <ModalShell
      title={t('planMatches.autoSelect.title')}
      onClose={onCancel}
    >
        <div className="space-y-5">
          {/* Squad size section */}
          <div className="space-y-3">
            <div className="border-b border-slate-600 pb-1">
              <h4 className="text-sm font-medium text-sky-300">
                {isMultiMatch ? t('planMatches.autoSelect.squadSizeMulti') : t('planMatches.autoSelect.squadSizeSingle')}
              </h4>
            </div>
            <div className="space-y-2">
              {autoSelectMatches.map((match) => (
                <div key={match.id} className="flex items-center justify-between gap-3">
                  <div className="min-w-0">
                    <div className="truncate text-sm text-slate-100">{match.opponent}</div>
                    <div className="text-xs text-slate-400">{formatSchedule(match.matchDate, match.matchTime, match.plannedStartTime)}</div>
                  </div>
                  <div className="w-20">
                    <Input
                      type="number"
                      min="0"
                      max={rosterCount}
                      value={targetCounts[match.id] ?? ''}
                      onChange={(event) => onUpdateTargetCount(match.id, event.target.value)}
                      className="text-xs py-1 px-2"
                    />
                  </div>
                </div>
              ))}
            </div>
          </div>

          {!isMultiMatch && (
            <div className="space-y-2">
              <div className="border-b border-slate-600 pb-1">
                <h4 className="text-sm font-medium text-sky-300">{t('planMatches.autoSelect.recommendationType')}</h4>
              </div>
              <label className="flex items-center gap-2 text-sm text-slate-200">
                <input
                  type="radio"
                  name="single-match-strategy"
                  checked={autoSelectSettings.singleMatchStrategy === SINGLE_MATCH_STRATEGY.BY_METRIC}
                  onChange={() => onUpdateSettings({
                    ...autoSelectSettings,
                    singleMatchStrategy: SINGLE_MATCH_STRATEGY.BY_METRIC
                  })}
                  className="h-4 w-4 border-slate-500 text-sky-500 focus:ring-sky-500"
                />
                {t('planMatches.autoSelect.byMetric')}
              </label>
              <label className="flex items-center gap-2 text-sm text-slate-200">
                <input
                  type="radio"
                  name="single-match-strategy"
                  checked={autoSelectSettings.singleMatchStrategy === SINGLE_MATCH_STRATEGY.STRONGEST}
                  onChange={() => onUpdateSettings({
                    ...autoSelectSettings,
                    singleMatchStrategy: SINGLE_MATCH_STRATEGY.STRONGEST
                  })}
                  className="h-4 w-4 border-slate-500 text-sky-500 focus:ring-sky-500"
                />
                {t('planMatches.autoSelect.strongestTeam')}
              </label>
              <label className="flex items-center gap-2 text-sm text-slate-200">
                <input
                  type="radio"
                  name="single-match-strategy"
                  checked={autoSelectSettings.singleMatchStrategy === SINGLE_MATCH_STRATEGY.GROWTH}
                  onChange={() => onUpdateSettings({
                    ...autoSelectSettings,
                    singleMatchStrategy: SINGLE_MATCH_STRATEGY.GROWTH
                  })}
                  className="h-4 w-4 border-slate-500 text-sky-500 focus:ring-sky-500"
                />
                {t('planMatches.autoSelect.growthSquad')}
              </label>
            </div>
          )}

          {isMultiMatch && (
            <>
              {/* Coverage checkbox */}
              <label className="flex items-center gap-2 text-sm text-slate-200">
                <input
                  type="checkbox"
                  checked={autoSelectSettings.ensureCoverage}
                  onChange={(event) => onUpdateSettings({
                    ...autoSelectSettings,
                    ensureCoverage: event.target.checked
                  })}
                  className="h-4 w-4 rounded border-slate-500 text-sky-500 focus:ring-sky-500"
                />
                {t('planMatches.autoSelect.ensureCoverage')}
              </label>

              {/* Overlap priority section */}
              <div className="space-y-2">
                <div className="border-b border-slate-600 pb-1">
                  <h4 className="text-sm font-medium text-sky-300">{t('planMatches.autoSelect.overlapPriorityHint')}</h4>
                </div>
                <label className="flex items-center gap-2 text-sm text-slate-200">
                  <input
                    type="radio"
                    name="auto-select-strategy"
                    checked={autoSelectSettings.metric === AUTO_SELECT_STRATEGY.PRACTICES}
                    onChange={() => onUpdateSettings({
                      ...autoSelectSettings,
                      metric: AUTO_SELECT_STRATEGY.PRACTICES
                    })}
                    className="h-4 w-4 border-slate-500 text-sky-500 focus:ring-sky-500"
                  />
                  {t('planMatches.autoSelect.prioritizePractices')}
                </label>
                <label className="flex items-center gap-2 text-sm text-slate-200">
                  <input
                    type="radio"
                    name="auto-select-strategy"
                    checked={autoSelectSettings.metric === AUTO_SELECT_STRATEGY.ATTENDANCE}
                    onChange={() => onUpdateSettings({
                      ...autoSelectSettings,
                      metric: AUTO_SELECT_STRATEGY.ATTENDANCE
                    })}
                    className="h-4 w-4 border-slate-500 text-sky-500 focus:ring-sky-500"
                  />
                  {t('planMatches.autoSelect.prioritizeAttendance')}
                </label>
              </div>

              {/* Distribution strategy section */}
              {autoSelectSettings.ensureCoverage && (
                <div className="space-y-2">
                  <div className="border-b border-slate-600 pb-1">
                    <h4 className="text-sm font-medium text-sky-300">{t('planMatches.autoSelect.distributionStrategy')}</h4>
                  </div>
                  <label className="flex items-center gap-2 text-sm text-slate-200">
                    <input
                      type="radio"
                      name="distribution-strategy"
                      checked={autoSelectSettings.distributionStrategy === DISTRIBUTION_STRATEGY.EQUAL}
                      onChange={() => onUpdateSettings({
                        ...autoSelectSettings,
                        distributionStrategy: DISTRIBUTION_STRATEGY.EQUAL
                      })}
                      className="h-4 w-4 border-slate-500 text-sky-500 focus:ring-sky-500"
                    />
                    {t('planMatches.autoSelect.equallyStrong')}
                  </label>
                  <label className="flex items-center gap-2 text-sm text-slate-200">
                    <input
                      type="radio"
                      name="distribution-strategy"
                      checked={autoSelectSettings.distributionStrategy === DISTRIBUTION_STRATEGY.ONE_STRONG}
                      onChange={() => onUpdateSettings({
                        ...autoSelectSettings,
                        distributionStrategy: DISTRIBUTION_STRATEGY.ONE_STRONG
                      })}
                      className="h-4 w-4 border-slate-500 text-sky-500 focus:ring-sky-500"
                    />
                    {t('planMatches.autoSelect.oneStrongTeam')}
                  </label>
                  {autoSelectSettings.distributionStrategy === DISTRIBUTION_STRATEGY.ONE_STRONG && (
                    <div className="ml-6 space-y-1 rounded-md bg-slate-700/40 p-2">
                      <p className="text-xs text-slate-400">{t('planMatches.autoSelect.selectStrongMatch')}</p>
                      {autoSelectMatches.map((match) => (
                        <label key={match.id} className="flex items-center gap-2 text-sm text-slate-200">
                          <input
                            type="radio"
                            name="strong-match"
                            checked={(autoSelectSettings.strongMatchId || defaultStrongMatchId) === match.id}
                            onChange={() => onUpdateSettings({
                              ...autoSelectSettings,
                              strongMatchId: match.id
                            })}
                            className="h-4 w-4 border-slate-500 text-sky-500 focus:ring-sky-500"
                          />
                          <span className="truncate">{match.opponent}</span>
                          <span className="text-xs text-slate-400">{formatSchedule(match.matchDate, match.matchTime, match.plannedStartTime)}</span>
                        </label>
                      ))}
                    </div>
                  )}
                  <label className="flex items-center gap-2 text-sm text-slate-200">
                    <input
                      type="radio"
                      name="distribution-strategy"
                      checked={autoSelectSettings.distributionStrategy === DISTRIBUTION_STRATEGY.RANDOM}
                      onChange={() => onUpdateSettings({
                        ...autoSelectSettings,
                        distributionStrategy: DISTRIBUTION_STRATEGY.RANDOM
                      })}
                      className="h-4 w-4 border-slate-500 text-sky-500 focus:ring-sky-500"
                    />
                    {t('planMatches.autoSelect.randomly')}
                  </label>
                </div>
              )}
            </>
          )}
        </div>
        <div className="pt-4 mt-1 border-t border-slate-600 flex flex-col sm:flex-row gap-2 sm:justify-end">
          <Button variant="secondary" onClick={onCancel}>
            {t('planMatches.autoSelect.cancel')}
          </Button>
          <Button
            variant="accent"
            onClick={() => onConfirm({
              strongMatchId: autoSelectSettings.strongMatchId || defaultStrongMatchId
            })}
          >
            {t('planMatches.autoSelect.apply')}
          </Button>
        </div>
    </ModalShell>
  );
}

AutoSelectModal.propTypes = {
  isOpen: PropTypes.bool.isRequired,
  matches: PropTypes.arrayOf(PropTypes.shape({
    id: PropTypes.string.isRequired,
    opponent: PropTypes.string,
    matchDate: PropTypes.string,
    matchTime: PropTypes.string,
    plannedStartTime: PropTypes.string,
    difficulty: PropTypes.string
  })).isRequired,
  autoSelectMatches: PropTypes.arrayOf(PropTypes.shape({
    id: PropTypes.string.isRequired,
    opponent: PropTypes.string,
    matchDate: PropTypes.string,
    matchTime: PropTypes.string,
    plannedStartTime: PropTypes.string,
    difficulty: PropTypes.string
  })).isRequired,
  rosterCount: PropTypes.number,
  targetCounts: PropTypes.objectOf(PropTypes.number).isRequired,
  autoSelectSettings: PropTypes.shape({
    ensureCoverage: PropTypes.bool,
    metric: PropTypes.oneOf(Object.values(AUTO_SELECT_STRATEGY)),
    distributionStrategy: PropTypes.oneOf(Object.values(DISTRIBUTION_STRATEGY)),
    singleMatchStrategy: PropTypes.oneOf(Object.values(SINGLE_MATCH_STRATEGY)),
    strongMatchId: PropTypes.string
  }).isRequired,
  onUpdateTargetCount: PropTypes.func.isRequired,
  onUpdateSettings: PropTypes.func.isRequired,
  onCancel: PropTypes.func.isRequired,
  onConfirm: PropTypes.func.isRequired,
  formatSchedule: PropTypes.func.isRequired
};
