import React, { useEffect } from 'react';
import PropTypes from 'prop-types';

const SIZE_STYLES = {
  sm: 'h-4 w-4',
  md: 'h-8 w-8',
  lg: 'h-12 w-12',
};

export function LoadingSpinner({ size = 'lg', message, className = '', 'aria-label': ariaLabel, liveRegion = false }) {
  useEffect(() => {
    if (process.env.NODE_ENV !== 'production' && liveRegion) {
      if (!ariaLabel && !message) {
        console.warn('LoadingSpinner: liveRegion=true requires either aria-label or message for screen reader support.');
      } else if (ariaLabel && message) {
        console.warn('LoadingSpinner: supply aria-label OR message, not both. aria-label takes precedence.');
      }
    }
  }, [liveRegion, ariaLabel, message]);
  // Use sr-only span (not aria-label on the container) so live-region text is
  // DOM content, announced reliably across NVDA+Firefox and other AT/browser pairs.
  // When message is also provided, omit the sr-only span to avoid double-announcement.
  const liveRegionProps = liveRegion ? { role: 'status' } : {};
  return (
    <div {...liveRegionProps} className={`flex flex-col items-center justify-center ${className}`}>
      {liveRegion && ariaLabel && !message && <span className="sr-only">{ariaLabel}</span>}
      <div aria-hidden="true" className={`animate-spin rounded-full border-b-2 border-sky-400 ${SIZE_STYLES[size]}`} />
      {message && <p className="text-slate-400 mt-3 text-sm">{message}</p>}
    </div>
  );
}

LoadingSpinner.propTypes = {
  size: PropTypes.oneOf(['sm', 'md', 'lg']),
  message: PropTypes.string,
  className: PropTypes.string,
  'aria-label': PropTypes.string,
  liveRegion: PropTypes.bool,
};
