import { StatusBar, Style } from '@capacitor/status-bar';
import { SplashScreen } from '@capacitor/splash-screen';
import { Capacitor } from '@capacitor/core';
import { isNativePlatform } from './platform';
import { SLATE_900 } from '../constants/themeColors';

let splashHidden = false;

export async function initNativeStatusBar() {
  if (!isNativePlatform()) return;
  try {
    await StatusBar.setStyle({ style: Style.Dark });
    if (Capacitor.getPlatform() === 'android') {
      await StatusBar.setBackgroundColor({ color: SLATE_900 });
    }
  } catch (e) {
    console.warn('[nativePlugins] StatusBar init failed', e);
  }
}

// Idempotent on success; if hide() rejects we leave splashHidden false so the
// next call can retry — otherwise launchAutoHide:false would strand the splash.
export async function hideNativeSplashScreen() {
  if (!isNativePlatform() || splashHidden) return;
  try {
    await SplashScreen.hide();
    splashHidden = true;
  } catch (e) {
    console.warn('[nativePlugins] SplashScreen hide failed', e);
  }
}
