import React, { useEffect, useRef, useState } from 'react';
import PropTypes from 'prop-types';
import { Clock } from 'lucide-react';

const HOURS = Array.from({ length: 24 }, (_, i) => String(i).padStart(2, '0'));
const MINUTES = Array.from({ length: 12 }, (_, i) => String(i * 5).padStart(2, '0'));

export function TimePickerInput({
  value,
  onChange,
  id,
  disabled = false,
  placeholder = 'HH:MM',
  className = '',
  error = false,
}) {
  const [isOpen, setIsOpen] = useState(false);
  const containerRef = useRef(null);
  const hourListRef = useRef(null);
  const minuteListRef = useRef(null);

  const parts = value ? value.split(':') : [];
  const selectedHour = parts[0] ? parts[0].padStart(2, '0') : '';
  const selectedMinute = parts[1] ? parts[1].slice(0, 2).padStart(2, '0') : '';

  // Find the closest 5-min step for highlighting
  const nearestMinute = selectedMinute
    ? String(Math.round(parseInt(selectedMinute, 10) / 5) * 5).padStart(2, '0').replace('60', '55')
    : '';

  useEffect(() => {
    if (!isOpen) return;
    const handleClickOutside = (event) => {
      if (containerRef.current && !containerRef.current.contains(event.target)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [isOpen]);

  // Scroll selected items into view when dropdown opens
  useEffect(() => {
    if (!isOpen) return;
    if (hourListRef.current) {
      const idx = selectedHour ? HOURS.indexOf(selectedHour) : HOURS.indexOf('12');
      const el = hourListRef.current.children[Math.max(idx, 0)];
      if (el && typeof el.scrollIntoView === 'function') {
        el.scrollIntoView({ block: 'center' });
      }
    }
    if (minuteListRef.current) {
      const idx = nearestMinute ? MINUTES.indexOf(nearestMinute) : 0;
      const el = minuteListRef.current.children[Math.max(idx, 0)];
      if (el && typeof el.scrollIntoView === 'function') {
        el.scrollIntoView({ block: 'center' });
      }
    }
  }, [isOpen, selectedHour, nearestMinute]);

  const handleSelect = (type, val) => {
    const hour = type === 'hour' ? val : (selectedHour || '00');
    const minute = type === 'minute' ? val : (nearestMinute || '00');
    onChange(`${hour}:${minute}`);
    // Close once both values are set
    if (type === 'minute' && hour) setIsOpen(false);
  };

  return (
    <div className={`relative ${className}`} ref={containerRef}>
      <button
        type="button"
        id={id}
        disabled={disabled}
        onClick={() => { if (!disabled) setIsOpen(prev => !prev); }}
        className={`w-full bg-slate-600 border text-slate-100 py-1.5 px-3 rounded-md leading-tight focus:outline-none focus:ring-2 transition-colors h-[38px] flex items-center gap-2 ${
          error
            ? 'border-rose-500 focus:ring-rose-400 focus:border-rose-500'
            : 'border-slate-500 focus:ring-sky-400 focus:border-sky-500'
        } ${disabled ? 'opacity-60 cursor-not-allowed' : 'cursor-pointer'}`}
      >
        <Clock size={15} className="shrink-0 text-slate-400" />
        <span className={`flex-1 text-left text-sm font-mono ${value ? 'text-slate-100' : 'text-slate-400'}`}>
          {value ? value.slice(0, 5) : placeholder}
        </span>
      </button>

      {isOpen && (
        <div className="absolute z-50 mt-1 left-0 bg-slate-800 border border-slate-600 rounded-lg shadow-xl overflow-hidden">
          <div className="flex">
            {/* Hours column */}
            <div
              ref={hourListRef}
              role="listbox"
              aria-label="Hours"
              className="overflow-y-auto max-h-48 w-[4.5rem] py-1 scrollbar-thin"
            >
              {HOURS.map(h => (
                <button
                  key={h}
                  type="button"
                  role="option"
                  aria-selected={h === selectedHour}
                  onClick={() => handleSelect('hour', h)}
                  className={`w-full px-2 py-1.5 text-center text-sm transition-colors rounded-sm ${
                    h === selectedHour
                      ? 'bg-sky-600 text-white font-semibold'
                      : 'text-slate-300 hover:bg-slate-700 hover:text-slate-100'
                  }`}
                >
                  {h}
                </button>
              ))}
            </div>

            {/* Separator */}
            <div className="flex items-center justify-center px-1 text-slate-500 font-bold text-base select-none border-x border-slate-700">
              :
            </div>

            {/* Minutes column */}
            <div
              ref={minuteListRef}
              role="listbox"
              aria-label="Minutes"
              className="overflow-y-auto max-h-48 w-[4.5rem] py-1"
            >
              {MINUTES.map(m => (
                <button
                  key={m}
                  type="button"
                  role="option"
                  aria-selected={m === nearestMinute}
                  onClick={() => handleSelect('minute', m)}
                  className={`w-full px-2 py-1.5 text-center text-sm transition-colors rounded-sm ${
                    m === nearestMinute
                      ? 'bg-sky-600 text-white font-semibold'
                      : 'text-slate-300 hover:bg-slate-700 hover:text-slate-100'
                  }`}
                >
                  {m}
                </button>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

TimePickerInput.propTypes = {
  value: PropTypes.string,
  onChange: PropTypes.func.isRequired,
  id: PropTypes.string,
  disabled: PropTypes.bool,
  placeholder: PropTypes.string,
  className: PropTypes.string,
  error: PropTypes.bool,
};
