// Sync language resolution: URL ?lang → stored pref → navigator.languages.
// Returns null when nothing matches so callers can decide the fallback.

import { LANGUAGE_OPTIONS, PREFERENCE_STORAGE_KEY } from '../constants/audioAlerts';
import { createPersistenceManager } from './persistenceManager';

export const SUPPORTED_LANGUAGES = LANGUAGE_OPTIONS.map(option => option.value);

const primarySubtag = (tag) => {
  if (typeof tag !== 'string' || !tag) return null;
  return tag.split(/[-_]/)[0].toLowerCase();
};

const matchSupported = (candidate, supportedLanguages) => {
  const primary = primarySubtag(candidate);
  if (!primary) return null;
  return supportedLanguages.includes(primary) ? primary : null;
};

const readUrlLanguage = (search, supportedLanguages) => {
  if (typeof search !== 'string' || !search) return null;
  try {
    const params = new URLSearchParams(
      search.startsWith('?') ? search.slice(1) : search
    );
    const raw = params.get('lang');
    return matchSupported(raw, supportedLanguages);
  } catch {
    return null;
  }
};

const readNavigatorLanguage = (supportedLanguages) => {
  if (typeof navigator === 'undefined') return null;

  // Prefer navigator.languages (ordered user preference). Only fall back
  // to navigator.language when the array is missing or empty.
  let candidates = [];
  if (Array.isArray(navigator.languages) && navigator.languages.length > 0) {
    candidates = navigator.languages;
  } else if (typeof navigator.language === 'string') {
    candidates = [navigator.language];
  }

  for (const candidate of candidates) {
    const match = matchSupported(candidate, supportedLanguages);
    if (match) return match;
  }
  return null;
};

export function resolveSyncLanguage({
  search = '',
  storedLanguage = null,
  supportedLanguages = SUPPORTED_LANGUAGES
} = {}) {
  const fromUrl = readUrlLanguage(search, supportedLanguages);
  if (fromUrl) return fromUrl;

  if (typeof storedLanguage === 'string' && supportedLanguages.includes(storedLanguage)) {
    return storedLanguage;
  }

  const fromNavigator = readNavigatorLanguage(supportedLanguages);
  if (fromNavigator) return fromNavigator;

  return null;
}

// Default state is empty so absent fields return undefined rather than being
// filled in from a default object. This lets us tell "nothing stored" apart
// from "stored language is 'en'".
const storedPreferencesReader = createPersistenceManager(PREFERENCE_STORAGE_KEY, {});

// Used by i18n.js at init time, before PreferencesContext has mounted.
export function readStoredLanguage() {
  const stored = storedPreferencesReader.loadState();
  if (stored && typeof stored.language === 'string') {
    return stored.language;
  }
  return null;
}
