import React, { useState, useRef } from 'react';
import { Button } from '../shared/UI';
import { Card } from '../shared/Card';
import { ModalShell } from '../shared/ModalShell';
import { TeamSwitchChoiceModal } from './TeamSwitchChoiceModal';
import { useTeam } from '../../contexts/TeamContext';
import { useToast } from '../../contexts/ToastContext';
import { useTranslation } from 'react-i18next';
import { formatTeamName } from '../../utils/teamUtils';
import { useTeamSwitchAction } from '../../hooks/useTeamSwitchAction';
import {
  Users,
  MessageSquare,
  Clock,
  CheckCircle,
  XCircle,
  UserCheck,
  Calendar
} from 'lucide-react';

export function InvitationNotificationModal({
  isOpen,
  invitations,
  onClose,
  onInvitationProcessed
}) {
  const { t, i18n } = useTranslation('team');
  const {
    currentTeam,
    acceptTeamInvitation,
    declineTeamInvitation,
    getUserTeams,
    switchCurrentTeam,
    getClubMemberships,
    clearTeamSelectionPrompt,
    loading
  } = useTeam();
  const [processingInvitations, setProcessingInvitations] = useState(new Set());
  // When set, prompt the user to switch to the newly joined team or stay put.
  const [switchChoice, setSwitchChoice] = useState(null);
  // Serializes acceptances: two concurrent accepts could each set switchChoice,
  // with the second silently overwriting the first's pending switch-or-stay choice.
  // See: "ignores a second accept while the first is in flight" test.
  const acceptingRef = useRef(false);
  // Mirrors acceptingRef in state so that every Accept button row is disabled while
  // any acceptance is in-flight (not just the row whose id is in processingInvitations).
  const [isAccepting, setIsAccepting] = useState(false);
  const { showSuccess, showWarning } = useToast();
  const { confirming: switching, runSwitch } = useTeamSwitchAction();

  // Defined before the early return so it stays available even when the parent
  // removes the invitation from the list (or closes the modal) after acceptance.
  const handleConfirmSwitch = () => {
    if (!switchChoice) return;
    runSwitch(switchChoice.newTeam.id, () => setSwitchChoice(null));
  };

  const handleStay = () => {
    setSwitchChoice(null);
    // Mirror dismissTeamChoice (URL-invite flow): mark the prompt dismissed so a
    // post-invite userTeams refresh can't re-pop the generic TeamSelectionModal.
    clearTeamSelectionPrompt();
  };

  // Return null only when neither the choice modal nor the invitation list has anything to show.
  // If switchChoice is set we must keep rendering even if the parent closed the invitation list.
  if (!switchChoice && (!isOpen || !invitations || invitations.length === 0)) {
    return null;
  }

  const handleAcceptInvitation = async (invitation) => {
    if (processingInvitations.has(invitation.id) || acceptingRef.current) return;
    acceptingRef.current = true;
    setIsAccepting(true);

    // Capture whether the user already has an active team before refreshing.
    const hadActiveTeam = Boolean(currentTeam);
    const previousTeam = currentTeam;

    setProcessingInvitations(prev => new Set([...prev, invitation.id]));

    try {
      const result = await acceptTeamInvitation(invitation.id);

      if (result.success) {
        showSuccess(t('invitationNotification.successJoined', { teamName: invitation.team.name }));

        // Refresh team data; only auto-switch when the user has no active team.
        try {
          const refreshedTeams = await getUserTeams();

          // API responses always include team.id, but fall back to the top-level
          // teamId field (present in older invitation shapes) as a safety net.
          const targetTeamId = invitation.team?.id ?? invitation.teamId;
          const newTeam = refreshedTeams && refreshedTeams.length > 0
            ? refreshedTeams.find(team => team.id === targetTeamId)
            : null;

          if (newTeam) {
            // Refresh club memberships to ensure hasClubs is updated
            try {
              await getClubMemberships();
            } catch (clubError) {
              console.error('Error refreshing club memberships:', clubError);
            }

            if (hadActiveTeam) {
              // User already has an active team: offer a choice, do not auto-switch.
              setSwitchChoice({ newTeam, previousTeam });
            } else {
              // No active team to preserve: auto-switch to the newly joined team.
              // switchCurrentTeam already fetches players internally.
              try {
                await switchCurrentTeam(newTeam.id, refreshedTeams);
              } catch (switchError) {
                console.error('Error switching to newly joined team:', switchError);
                showWarning(t('teamSelection.error'));
              }
            }
          }
        } catch (refreshError) {
          console.error('Error refreshing team data:', refreshError);
        }

        onInvitationProcessed?.(invitation, 'accepted');
      } else {
        console.error('Failed to accept invitation:', result.error);
      }
    } catch (error) {
      console.error('Error accepting invitation:', error);
    } finally {
      acceptingRef.current = false;
      setIsAccepting(false);
      setProcessingInvitations(prev => {
        const newSet = new Set(prev);
        newSet.delete(invitation.id);
        return newSet;
      });
    }
  };

  const handleDeclineInvitation = async (invitation) => {
    if (processingInvitations.has(invitation.id)) return;

    setProcessingInvitations(prev => new Set([...prev, invitation.id]));

    try {
      const result = await declineTeamInvitation(invitation.id);

      if (result.success) {
        onInvitationProcessed?.(invitation, 'declined');
      } else {
        console.error('Failed to decline invitation:', result.error);
      }
    } catch (error) {
      console.error('Error declining invitation:', error);
    } finally {
      setProcessingInvitations(prev => {
        const newSet = new Set(prev);
        newSet.delete(invitation.id);
        return newSet;
      });
    }
  };

  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleDateString(i18n.language, {
      month: 'short',
      day: 'numeric',
      year: 'numeric'
    });
  };

  // The choice modal and the invitation list are mutually exclusive: switchChoice
  // is only set after an accept succeeds, at which point the list is hidden.
  //
  // INVARIANT: this component's TeamSwitchChoiceModal and the one rendered in App.js
  // (driven by useInvitationProcessing.pendingTeamChoice for the URL-invite flow) must
  // never be visible simultaneously. In practice this is guaranteed because: (a) the URL
  // flow processes the invitation token before the notification modal ever opens, and (b)
  // a user cannot be mid-URL-invite and mid-notification-accept at the same time given the
  // acceptingRef serialisation guard. If this assumption ever breaks, the two modals would
  // stack on top of each other. A single-source-of-truth refactor (lifting switchChoice to
  // App.js) would be the proper fix.
  const showList = !switchChoice && isOpen && invitations?.length > 0;
  return (
    <>
      <TeamSwitchChoiceModal
        choice={switchChoice}
        onConfirm={handleConfirmSwitch}
        onCancel={handleStay}
        confirming={switching}
      />
      {showList && (
        <ModalShell
          title={t('invitationNotification.title')}
          icon={Users}
          iconColor="blue"
          onClose={onClose}
          maxWidth="2xl"
          className="max-h-[90vh] overflow-y-auto"
        >
          <p className="text-slate-300 text-sm mb-6">
            {invitations.length === 1
              ? t('invitationNotification.inviteDescription')
              : t('invitationNotification.inviteDescriptionPlural', { count: invitations.length })}
          </p>

          {/* Invitations List */}
          <div className="space-y-4">
            {invitations.map((invitation) => (
              <Card
                key={invitation.id}
                variant="subtle"
              >
                <div className="flex items-start justify-between mb-3">
                  <div>
                    <h3 className="font-medium text-slate-100 mb-1">
                      {formatTeamName(invitation.team)}
                    </h3>
                    <div className="flex items-center space-x-4 text-sm text-slate-400">
                      <div className="flex items-center space-x-1">
                        <UserCheck className="w-4 h-4" />
                        <span>{t('invitationNotification.role', { role: invitation.role })}</span>
                      </div>
                      <div className="flex items-center space-x-1">
                        <Calendar className="w-4 h-4" />
                        <span>{t('invitationNotification.expires', { date: formatDate(invitation.expiresAt) })}</span>
                      </div>
                    </div>
                  </div>
                </div>

                {invitation.invitedBy && (
                  <p className="text-sm text-slate-300 mb-3">
                    {t('invitationNotification.invitedBy', { name: invitation.invitedBy.name })}
                  </p>
                )}

                {invitation.message && (
                  <div className="mb-4 p-3 bg-slate-600/30 rounded border-l-4 border-blue-400">
                    <div className="flex items-start space-x-2">
                      <MessageSquare className="w-4 h-4 text-blue-400 mt-0.5 flex-shrink-0" />
                      <p className="text-sm text-slate-200">{invitation.message}</p>
                    </div>
                  </div>
                )}

                <div className="flex items-center justify-end space-x-3">
                  <Button
                    onClick={() => handleDeclineInvitation(invitation)}
                    disabled={loading || processingInvitations.has(invitation.id)}
                    variant="secondary"
                    size="sm"
                    Icon={processingInvitations.has(invitation.id) ? null : XCircle}
                  >
                    {processingInvitations.has(invitation.id) ? (
                      <>
                        <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-slate-400"></div>
                        {t('invitationNotification.buttons.declining')}
                      </>
                    ) : (
                      t('invitationNotification.buttons.decline')
                    )}
                  </Button>
                  <Button
                    onClick={() => handleAcceptInvitation(invitation)}
                    disabled={loading || isAccepting || processingInvitations.has(invitation.id)}
                    variant="primary"
                    size="sm"
                    Icon={processingInvitations.has(invitation.id) ? null : CheckCircle}
                  >
                    {processingInvitations.has(invitation.id) ? (
                      <>
                        <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white"></div>
                        {t('invitationNotification.buttons.accepting')}
                      </>
                    ) : isAccepting ? (
                      t('invitationNotification.buttons.pleaseWait')
                    ) : (
                      t('invitationNotification.buttons.accept')
                    )}
                  </Button>
                </div>
              </Card>
            ))}
          </div>

          <div className="mt-6 pt-4 border-t border-slate-600">
            <div className="flex items-center justify-end">
              <Button onClick={onClose} variant="secondary" Icon={Clock}>
                {t('invitationNotification.buttons.decideLater')}
              </Button>
            </div>
          </div>
        </ModalShell>
      )}
    </>
  );
}
