// Helpers for player↔user relationships (player_user). The coaching-parent chip
// must reflect only relationships to coaches/admins, never ordinary parents.

export const COACH_ROLES = ['admin', 'coach'];

// Members that can be linked to a player: coaches/admins and parents (not players).
export const RELATABLE_ROLES = ['admin', 'coach', 'parent'];

// First related user who is a coach/admin, or null. Accepts a relatedUsers array
// (from getTeamPlayers/getTeamRoster) on the player object. The chip is a single
// indicator, so only the first coach/admin is surfaced if a player has several.
export function getCoachRelation(player) {
  if (!player) return null;
  const related = player.relatedUsers || [];
  return related.find((u) => COACH_ROLES.includes(u.role)) || null;
}

export function hasCoachRelation(player) {
  return Boolean(getCoachRelation(player));
}

// Immutably add/remove an id from a selection array (for checkbox toggles).
export function toggleInArray(arr, id) {
  return arr.includes(id) ? arr.filter((x) => x !== id) : [...arr, id];
}
