import { animateStateChange } from '../animation/animationSupport';
import {
  calculatePositionSwitch,
  calculateGoalieSwitch
} from '../logic/gameStateLogic';
import { findPlayerById } from '../../utils/playerUtils';
import { PLAYER_STATUS } from '../../constants/playerConstants';

export const DRAG_ACTION_TYPES = {
  SUBSTITUTE: 'substitute',
  SWAP: 'swap',
  GOALIE_SWITCH: 'goalie-switch'
};

const getPlayerStatus = (player) => player?.stats?.currentStatus || null;

const isOnField = (player) => getPlayerStatus(player) === PLAYER_STATUS.ON_FIELD;
const isSubstitute = (player) => getPlayerStatus(player) === PLAYER_STATUS.SUBSTITUTE;
const isGoalie = (player) => getPlayerStatus(player) === PLAYER_STATUS.GOALIE;
const isInactive = (player) => Boolean(player?.stats?.isInactive);

export const resolveDragAction = (sourcePlayer, targetPlayer) => {
  if (!sourcePlayer || !targetPlayer) {
    return { eligible: false, reason: 'missing-player' };
  }
  if (sourcePlayer.id === targetPlayer.id) {
    return { eligible: false, reason: 'same-player' };
  }
  if (isInactive(sourcePlayer) || isInactive(targetPlayer)) {
    return { eligible: false, reason: 'inactive-player' };
  }

  const sourceOnField = isOnField(sourcePlayer);
  const sourceSub = isSubstitute(sourcePlayer);
  const sourceGoalie = isGoalie(sourcePlayer);
  const targetOnField = isOnField(targetPlayer);
  const targetSub = isSubstitute(targetPlayer);
  const targetGoalie = isGoalie(targetPlayer);

  // Field <-> Substitute: one-off substitution.
  if ((sourceOnField && targetSub) || (sourceSub && targetOnField)) {
    return { eligible: true, actionType: DRAG_ACTION_TYPES.SUBSTITUTE };
  }
  // Field <-> Field: swap positions.
  if (sourceOnField && targetOnField) {
    return { eligible: true, actionType: DRAG_ACTION_TYPES.SWAP };
  }
  // Substitute <-> Substitute: swap queue order.
  if (sourceSub && targetSub) {
    return { eligible: true, actionType: DRAG_ACTION_TYPES.SWAP };
  }
  // Goalie interactions.
  if (sourceGoalie || targetGoalie) {
    return { eligible: true, actionType: DRAG_ACTION_TYPES.GOALIE_SWITCH };
  }

  return { eligible: false, reason: 'unhandled-combination' };
};

export const createDragSubstitutionHandlers = ({
  gameStateFactory,
  substitutionHandlers,
  stateUpdaters,
  animationHooks
}) => {
  if (!gameStateFactory || !substitutionHandlers || !stateUpdaters || !animationHooks) {
    return null;
  }

  const {
    setFormation,
    setAllPlayers,
    setRotationQueue,
    setRoleGroups,
    setNextToSubOutIds,
    setNextPlayerIdToSubOut
  } = stateUpdaters;

  const {
    setAnimationState,
    setHideNextOffIndicator,
    setRecentlySubstitutedPlayers
  } = animationHooks;

  const findPositionKey = (formation, playerId) =>
    formation
      ? Object.keys(formation).find((key) => formation[key] === playerId)
      : null;

  // Apply optional state fields from the calculator output. Use `!== undefined`
  // so a deliberate `null` from the calculator correctly clears the state.
  // setRotationQueue is required by the destructure so no `&& setter` guard;
  // the others are optional setters and use the guard.
  const applyOptionalStateFields = (newGameState) => {
    if (newGameState.rotationQueue !== undefined) {
      setRotationQueue(newGameState.rotationQueue);
    }
    if (newGameState.roleGroups !== undefined && setRoleGroups) {
      setRoleGroups(newGameState.roleGroups);
    }
    if (newGameState.nextToSubOutIds !== undefined && setNextToSubOutIds) {
      setNextToSubOutIds(newGameState.nextToSubOutIds);
    }
    if (newGameState.nextPlayerIdToSubOut !== undefined && setNextPlayerIdToSubOut) {
      setNextPlayerIdToSubOut(newGameState.nextPlayerIdToSubOut);
    }
  };

  // Drag drops own their own FLIP animation in IndividualFormation, so the slide
  // + glow pipeline of animateStateChange must be suppressed. skipAnimation=true
  // applies the calculator result synchronously without setAnimationState calls.
  const DRAG_OPTIONS = { skipAnimation: true };

  const performGoalieSwitch = (newGoalieId) => {
    animateStateChange(
      gameStateFactory(),
      (state) => calculateGoalieSwitch(state, newGoalieId),
      (newGameState) => {
        setFormation(newGameState.formation);
        setAllPlayers(newGameState.allPlayers);
        applyOptionalStateFields(newGameState);
      },
      setAnimationState,
      setHideNextOffIndicator,
      setRecentlySubstitutedPlayers,
      DRAG_OPTIONS
    );
  };

  const performPositionSwitch = (sourceId, targetId) => {
    animateStateChange(
      gameStateFactory(),
      (state) => calculatePositionSwitch(state, sourceId, targetId),
      (newGameState) => {
        setFormation(newGameState.formation);
        setAllPlayers(newGameState.allPlayers);
        applyOptionalStateFields(newGameState);
      },
      setAnimationState,
      setHideNextOffIndicator,
      setRecentlySubstitutedPlayers,
      DRAG_OPTIONS
    );
  };

  const performSubstituteSwap = (sourceId, targetId) => {
    const state = gameStateFactory();
    const formation = state.formation || {};
    const sourcePos = findPositionKey(formation, sourceId);
    const targetPos = findPositionKey(formation, targetId);
    if (!sourcePos || !targetPos) {
      return;
    }

    // Direct swap of the two substitute slot contents. This is symmetric — dragging
    // substitute_3 onto substitute_1 moves it to substitute_1, not substitute_2 (which
    // is what calculateSubstituteReorder would do, since it only shifts by one slot).
    // The issue describes a pure swap of queue positions, so direct swap matches intent
    // for both directions and for any squad size.
    animateStateChange(
      state,
      (innerState) => {
        const newFormation = { ...innerState.formation };
        newFormation[sourcePos] = targetId;
        newFormation[targetPos] = sourceId;
        const newAllPlayers = (innerState.allPlayers || []).map((player) => {
          if (player.id === sourceId) {
            return { ...player, stats: { ...player.stats, currentPositionKey: targetPos } };
          }
          if (player.id === targetId) {
            return { ...player, stats: { ...player.stats, currentPositionKey: sourcePos } };
          }
          return player;
        });
        // Mirror the swap in rotationQueue so the fairness/"next to sub" logic
        // matches the visible substitute order. Without this, the queue keeps
        // its pre-swap order and downstream decisions disagree with the UI.
        let newRotationQueue = innerState.rotationQueue;
        if (Array.isArray(innerState.rotationQueue)) {
          const sourceQueueIdx = innerState.rotationQueue.indexOf(sourceId);
          const targetQueueIdx = innerState.rotationQueue.indexOf(targetId);
          if (sourceQueueIdx !== -1 && targetQueueIdx !== -1) {
            newRotationQueue = [...innerState.rotationQueue];
            newRotationQueue[sourceQueueIdx] = targetId;
            newRotationQueue[targetQueueIdx] = sourceId;
          }
        }
        return {
          ...innerState,
          formation: newFormation,
          allPlayers: newAllPlayers,
          rotationQueue: newRotationQueue,
          playersToHighlight: [sourceId, targetId]
        };
      },
      (newGameState) => {
        setFormation(newGameState.formation);
        setAllPlayers(newGameState.allPlayers);
        applyOptionalStateFields(newGameState);
      },
      setAnimationState,
      setHideNextOffIndicator,
      setRecentlySubstitutedPlayers,
      DRAG_OPTIONS
    );
  };

  const performImmediateSubstitution = (fieldPlayerId, substituteId, formation) => {
    const fieldPlayerPosition = findPositionKey(formation, fieldPlayerId);
    if (!fieldPlayerPosition) {
      return;
    }
    if (typeof substitutionHandlers.handleSelectSubstituteForImmediate !== 'function') {
      return;
    }
    // Synthesize the substituteSelectionModal payload the existing handler expects.
    // Pass skipAnimation: true so the existing substitute-now slide/glow pipeline is
    // bypassed — the drag layer owns the visual via its FLIP swap.
    substitutionHandlers.handleSelectSubstituteForImmediate(
      {
        fieldPlayerId,
        fieldPlayerPosition,
        isOpen: true
      },
      substituteId,
      DRAG_OPTIONS
    );
  };

  const handleDragDrop = ({ sourcePlayerId, targetPlayerId }) => {
    if (!sourcePlayerId || !targetPlayerId || sourcePlayerId === targetPlayerId) {
      return;
    }

    const state = gameStateFactory();
    const allPlayers = state.allPlayers || [];
    const sourcePlayer = findPlayerById(allPlayers, sourcePlayerId);
    const targetPlayer = findPlayerById(allPlayers, targetPlayerId);

    const action = resolveDragAction(sourcePlayer, targetPlayer);
    if (!action.eligible) {
      return;
    }

    switch (action.actionType) {
      case DRAG_ACTION_TYPES.GOALIE_SWITCH: {
        // Goalie switch — calculateGoalieSwitch always uses the non-goalie player's
        // current position as where the old goalie lands. Works for both field↔goalie
        // and substitute↔goalie cases.
        const newGoalieId = isGoalie(sourcePlayer) ? targetPlayerId : sourcePlayerId;
        performGoalieSwitch(newGoalieId);
        return;
      }
      case DRAG_ACTION_TYPES.SWAP: {
        if (isOnField(sourcePlayer) && isOnField(targetPlayer)) {
          performPositionSwitch(sourcePlayerId, targetPlayerId);
          return;
        }
        if (isSubstitute(sourcePlayer) && isSubstitute(targetPlayer)) {
          performSubstituteSwap(sourcePlayerId, targetPlayerId);
          return;
        }
        return;
      }
      case DRAG_ACTION_TYPES.SUBSTITUTE: {
        // Determine which player is the field player and which is the substitute.
        const fieldPlayerId = isOnField(sourcePlayer) ? sourcePlayerId : targetPlayerId;
        const subPlayerId = fieldPlayerId === sourcePlayerId ? targetPlayerId : sourcePlayerId;
        performImmediateSubstitution(fieldPlayerId, subPlayerId, state.formation);
        return;
      }
      default:
        return;
    }
  };

  return { handleDragDrop };
};
