import { STORAGE_KEYS } from '../constants/storageKeys';
import * as persistenceManagerModule from './persistenceManager';

/**
 * Persists a "pre-planned" line-up for the upcoming period while a match
 * period is still being played.
 *
 * Persisted shape — *intent only*:
 *
 *   {
 *     periodNumber: number,         // upcoming period this plan is for
 *     formation: object,            // position → playerId mapping
 *     periodGoalieId: id|null       // for analytics/match-record tracking
 *   }
 *
 * Notes on what is **deliberately not persisted**:
 *
 * - `roleGroups`, `nextToSubOutIds`, `nextPlayerIdToSubOut`,
 *   `nextPlayerToSubOut`, `rotationQueue` are all *derived* from
 *   `(formation, current player time stats, teamConfig)`. Persisting them
 *   risks staleness (e.g., the user manually swaps two players → derived
 *   state no longer matches the formation) and uniqueness violations on
 *   hydration. Instead we rebuild them at hydration time from the merged
 *   formation + fresh stats.
 *
 * - The pre-plan is consumed at most once: hydrated when the user opens
 *   the setup screen for that period, then cleared when that period
 *   actually starts.
 */

// A no-op fallback used when callers (typically test mocks of
// `persistenceManager`) don't expose `createPersistenceManager`. This keeps
// `useGameState` (which transitively imports this module) safe to load in
// any test environment without forcing every existing mock to be updated.
//
// Required by `src/hooks/__tests__/useGameState.startingRole.test.js`,
// which mocks `persistenceManager` with only `createGamePersistenceManager`.
// Other test files that need the real `createPersistenceManager` (e.g.
// `useGameState.matchPersistence.test.js`) spread `...jest.requireActual`
// in their mock and don't hit this fallback.
const NOOP_MANAGER = {
  loadState: () => null,
  saveState: () => false,
  clearState: () => false,
};

let cachedManager = null;
const getManager = () => {
  if (cachedManager) return cachedManager;
  const factory = persistenceManagerModule.createPersistenceManager;
  cachedManager = typeof factory === 'function'
    ? factory(STORAGE_KEYS.PRE_PLANNED_PERIOD, null)
    : NOOP_MANAGER;
  return cachedManager;
};

// Test-only helper: reset the cached manager so a fresh one is created on
// next access (e.g. after a test re-mocks `persistenceManager`).
export const __resetPrePlanPersistenceForTests = () => {
  cachedManager = null;
};

// Reduce a possibly-rich plan to the persisted-shape only. Tolerates older
// plans (which may include now-derived fields like `roleGroups`) by silently
// dropping fields that are no longer persisted.
const toPersistedShape = (plan) => ({
  periodNumber: plan.periodNumber,
  formation: plan.formation && typeof plan.formation === 'object' ? plan.formation : null,
  periodGoalieId: plan.periodGoalieId ?? plan.formation?.goalie ?? null,
});

export const prePlanPersistence = {
  load() {
    const state = getManager().loadState();
    if (!state || typeof state !== 'object' || typeof state.periodNumber !== 'number') {
      return null;
    }
    if (!state.formation || typeof state.formation !== 'object') {
      return null;
    }
    return state;
  },

  /**
   * Returns the saved plan only if it targets the given period number,
   * otherwise null. Use this to drive hydration on entry to a setup screen.
   */
  loadIfMatches(periodNumber) {
    const state = this.load();
    if (!state || state.periodNumber !== periodNumber) return null;
    return state;
  },

  save(plan) {
    if (!plan || typeof plan !== 'object' || typeof plan.periodNumber !== 'number') {
      return false;
    }
    if (!plan.formation || typeof plan.formation !== 'object') {
      return false;
    }
    return getManager().saveState(toPersistedShape(plan));
  },

  clear() {
    return getManager().clearState();
  },
};
