import React from 'react';
import PropTypes from 'prop-types';
import { ArrowUpCircle, ArrowDownCircle } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { findPlayerById } from '../../../utils/playerUtils';
import { getFieldPositions, getSubstitutePositions, getPositionRole } from '../../../game/logic/positionUtils';
import { supportsInactiveUsers } from '../../../constants/gameModes';
import {
  getPositionIcon,
  getPositionDisplayName,
  getIndicatorProps,
  getPositionEvents,
  getSubstituteTargetPositions,
  getSubstituteTargetPositionsFromRoleGroups
} from '../../../game/ui/positionUtils';
import { getFixedGroupFieldPositions, isSameRoleMode } from '../../../constants/teamConfiguration';
import { getPlayerStyling } from '../../../game/ui/playerStyling';
import { getPlayerAnimation } from '../../../game/ui/playerAnimation';
import { PlayerStatsDisplay } from './components/PlayerStatsDisplay';
import { FORMATION_STYLES, ICON_STYLES } from './constants';
import { orderFieldPositionsForDisplay } from '../../../utils/positionDisplayOrder';

const EMPTY_FORMATION = {};

// Wrap a card's tap handlers so a recent drag on the same card suppresses the upstream tap.
const buildWrappedTapEvents = (longPressEvents, shouldSuppressClick, playerId) => {
  if (!shouldSuppressClick) return longPressEvents;
  const wrapped = { ...longPressEvents };
  if (typeof longPressEvents.onTouchEnd === 'function') {
    wrapped.onTouchEnd = (e) => {
      if (shouldSuppressClick(playerId)) {
        if (e && typeof e.preventDefault === 'function') e.preventDefault();
        return;
      }
      longPressEvents.onTouchEnd(e);
    };
  }
  if (typeof longPressEvents.onMouseUp === 'function') {
    wrapped.onMouseUp = (e) => {
      if (shouldSuppressClick(playerId)) {
        if (e && typeof e.preventDefault === 'function') e.preventDefault();
        return;
      }
      longPressEvents.onMouseUp(e);
    };
  }
  return wrapped;
};

export function IndividualFormation({
  teamConfig,
  selectedFormation,
  formation,
  allPlayers,
  animationState,
  recentlySubstitutedPlayers,
  hideNextOffIndicator,
  quickTapHandlers,
  goalieHandlers,
  getPlayerNameById,
  getPlayerTimeStats,
  nextPlayerIdToSubOut,
  substitutionCount = 1,
  rotationQueue = [],
  roleGroups = null,
  substitutionLogic = null,
  nextToSubOutIds = null,
  fixedRoleGroup = null,
  showLiveDeficit = false,
  renderSection = 'all',
  dragProps = null,
  ...domProps
}) {
  const { t } = useTranslation('game');
  const inactiveLabel = t('formation.inactive');

  // Drag-state values are identical for every card in this render — hoist them so
  // renderIndividualPosition doesn't recompute the same lookups per card.
  const dragSourceId = dragProps?.dragState?.sourcePlayerId || null;
  const dragHoveredId = dragProps?.dragState?.hoveredPlayerId || null;
  const dragIsActive = Boolean(dragProps?.dragState?.active);
  const dragIsEligible = Boolean(dragProps?.dragState?.isEligible);
  const dragHandlePointerDown = dragProps?.handlePointerDown || null;
  const dragShouldSuppressClick = dragProps?.shouldSuppressClick || null;
  const snapBackSourceId = dragProps?.snapBack?.sourcePlayerId || null;

  // Create formation-aware team config for position utilities
  const formationAwareTeamConfig = React.useMemo(() => {
    if (selectedFormation && selectedFormation !== teamConfig.formation) {
      return {
        ...teamConfig,
        formation: selectedFormation
      };
    }
    return teamConfig;
  }, [selectedFormation, teamConfig]);

  // Get formation-specific position lists from formation definitions
  const fieldPositions = getFieldPositions(formationAwareTeamConfig);
  const substitutePositions = getSubstitutePositions(formationAwareTeamConfig);
  const orderedFieldPositions = React.useMemo(() => {
    return orderFieldPositionsForDisplay(fieldPositions);
  }, [fieldPositions]);

  const groupedFieldSections = React.useMemo(() => {
    if (renderSection !== 'field') {
      return null;
    }

    const isSameRole = isSameRoleMode(substitutionLogic) && roleGroups;
    const fixedGroupPositions = !isSameRole
      ? new Set(getFixedGroupFieldPositions(formationAwareTeamConfig, fixedRoleGroup))
      : null;

    if (!isSameRole && (!fixedGroupPositions || fixedGroupPositions.size === 0)) {
      return null;
    }

    const buildSectionMeta = (position) => {
      if (isSameRole) {
        const groupKey = Object.entries(roleGroups).find(([, group]) =>
          group.fieldPositions?.includes(position)
        )?.[0];

        return {
          key: groupKey || `unmapped:${position}`,
          isBordered: true
        };
      }

      if (fixedGroupPositions.has(position)) {
        return {
          key: 'fixed-group',
          isBordered: true
        };
      }

      return {
        key: `single:${position}`,
        isBordered: false
      };
    };

    const sections = [];
    let currentSection = null;

    orderedFieldPositions.forEach((position) => {
      const meta = buildSectionMeta(position);
      if (
        !currentSection ||
        currentSection.key !== meta.key ||
        currentSection.isBordered !== meta.isBordered
      ) {
        if (currentSection) {
          sections.push(currentSection);
        }
        currentSection = {
          ...meta,
          positions: [position]
        };
      } else {
        currentSection.positions.push(position);
      }
    });

    if (currentSection) {
      sections.push(currentSection);
    }

    return sections;
  }, [renderSection, substitutionLogic, roleGroups, formationAwareTeamConfig, fixedRoleGroup, orderedFieldPositions]);

  // Mode capabilities
  const modeSupportsInactive = supportsInactiveUsers(formationAwareTeamConfig);

  // Map substitute positions to their target field positions
  const substituteTargetMapping = React.useMemo(() => {
    if (isSameRoleMode(substitutionLogic) && roleGroups) {
      return getSubstituteTargetPositionsFromRoleGroups(roleGroups, formation || EMPTY_FORMATION);
    }
    // In rotate-roles mode, all substitutes show their target position (not limited by substitutionCount)
    return getSubstituteTargetPositions(
      rotationQueue,
      formation || EMPTY_FORMATION,
      fieldPositions,
      substitutePositions,
      substitutePositions.length
    );
  }, [substitutionLogic, roleGroups, rotationQueue, formation, fieldPositions, substitutePositions]);

  // Create display labels for target positions with player names
  const incomingPositionLabels = React.useMemo(
    () => {
      const labels = {};
      Object.entries(substituteTargetMapping).forEach(([subPosition, targetFieldPosition]) => {
        const positionName = getPositionDisplayName(
          targetFieldPosition,
          null,
          formationAwareTeamConfig,
          substitutePositions,
          t
        );

        // Find the player at the target field position
        const playerIdAtPosition = formation?.[targetFieldPosition];
        const playerName = playerIdAtPosition && getPlayerNameById
          ? getPlayerNameById(playerIdAtPosition)
          : null;

        // Format: "PlayerName - Position"
        labels[subPosition] = playerName ? `${playerName} - ${positionName}` : positionName;
      });
      return labels;
    },
    [substituteTargetMapping, formationAwareTeamConfig, substitutePositions, formation, getPlayerNameById, t]
  );

  // Handle null/undefined formation after hook definitions to satisfy rules of hooks
  if (!formation) {
    return <div className="space-y-1.5" {...domProps}></div>;
  }

  // Determine which positions to render based on renderSection prop
  let positionsToRender;
  if (renderSection === 'field') {
    // Render goalie and field positions only
    positionsToRender = [...orderedFieldPositions, 'goalie'];
  } else if (renderSection === 'substitutes') {
    // Render substitute positions only
    positionsToRender = substitutePositions;
  } else {
    // Render all positions (default behavior)
    positionsToRender = [...orderedFieldPositions, 'goalie', ...substitutePositions];
  }

  const renderIndividualPosition = (position, renderIndex) => {
    const playerId = formation[position];

    if (!playerId) return null;
    
    const isFieldPosition = fieldPositions.includes(position);
    const isSubstitutePosition = substitutePositions.includes(position);
    const isGoaliePosition = position === 'goalie';
    const canBeSelected = isFieldPosition;

    // Check if this player was recently substituted
    const isRecentlySubstituted = recentlySubstitutedPlayers.has(playerId);

    // Get player object (needed for next-off indicator logic)
    const player = findPlayerById(allPlayers, playerId);
    // Check if player is inactive (only for modes that support it)
    const isInactive = modeSupportsInactive ? (player?.stats.isInactive || false) : false;

    // Compute effective queue and count for indicators (same-role mode uses nextToSubOutIds)
    const effectiveRotationQueue = (isSameRoleMode(substitutionLogic) && nextToSubOutIds)
      ? nextToSubOutIds
      : rotationQueue;
    const effectiveSubCount = (isSameRoleMode(substitutionLogic) && nextToSubOutIds)
      ? Math.min(substitutionCount, nextToSubOutIds.length)
      : substitutionCount;

    // Get indicator props using utility
    let { isNextOff, isNextOn } = getIndicatorProps(
      player,
      position,
      formationAwareTeamConfig,
      nextPlayerIdToSubOut,
      substitutePositions,
      effectiveSubCount,
      effectiveRotationQueue
    );


    // Get proper role from position mapping (works for all formations)
    const playerRole = getPositionRole(position);

    // Get styling and animation using utilities
    const { animationClass, zIndexClass, styleProps } = getPlayerAnimation(playerId, animationState);
    const { bgColor, textColor, borderColor, glowClass } = getPlayerStyling({
      isFieldPosition,
      isInactive,
      isNextOff,
      isNextOn,
      isRecentlySubstituted,
      hideNextOffIndicator,
      supportsInactiveUsers: modeSupportsInactive,
      role: playerRole,
      isGoalie: isGoaliePosition
    });

    // Get utilities
    const longPressEvents = isGoaliePosition && goalieHandlers ? goalieHandlers.goalieEvents : getPositionEvents(quickTapHandlers, position);
    const positionDisplayName = getPositionDisplayName(position, player, formationAwareTeamConfig, substitutePositions, t);
    const icon = getPositionIcon(position, substitutePositions);
    const incomingPositionLabel = incomingPositionLabels[position] || null;
    const shouldShowIncomingPosition = isSubstitutePosition && incomingPositionLabel && (!modeSupportsInactive || !isInactive);
    const playerName = getPlayerNameById ? getPlayerNameById(playerId) : playerId;

    const isDragSource = dragIsActive && dragSourceId === String(playerId);
    const isSnapBackSource = !dragIsActive && snapBackSourceId === String(playerId);
    const isHoveredDropTarget = dragIsActive && dragHoveredId === String(playerId) && !isDragSource;

    const dragPointerHandlers = dragHandlePointerDown && !isInactive ? {
      onPointerDown: (event) => dragHandlePointerDown(playerId, event)
    } : null;

    const wrappedTapEvents = buildWrappedTapEvents(longPressEvents, dragShouldSuppressClick, playerId);

    // The card stays in flow at full size, but its content is hidden so the
    // floating ghost is the only visible representation of the dragged player.
    // The dashed outline + dimmed bg make the empty slot obvious.
    const isSourceSlot = isDragSource || isSnapBackSource;
    const sourceSlotClass = isSourceSlot
      ? 'border-dashed border-sky-400/50 bg-slate-800/60 shadow-none'
      : '';
    const dropTargetClass = isHoveredDropTarget
      ? (dragIsEligible
          ? 'ring-2 ring-sky-300/80 shadow-[0_0_14px_rgba(56,189,248,0.45)]'
          : 'ring-2 ring-rose-400/60 shadow-[0_0_10px_rgba(244,63,94,0.35)]')
      : '';

    const cardClassName = `${FORMATION_STYLES.containerBase} ${borderColor} ${bgColor} ${textColor} ${glowClass} ${animationClass} ${zIndexClass} ${canBeSelected || isSubstitutePosition ? FORMATION_STYLES.interactive : ''} ${dropTargetClass} ${sourceSlotClass}`;
    const contentVisibilityStyle = isSourceSlot ? { visibility: 'hidden' } : undefined;

    return (
      <div
        key={position}
        data-testid={`player-${playerId}`}
        data-drag-player-id={String(playerId)}
        className={cardClassName}
        style={styleProps}
        {...wrappedTapEvents}
        {...(dragPointerHandlers || {})}
      >
        <h3
          className="text-[13px] leading-4 font-semibold mb-0.5 flex items-center justify-between gap-2"
          style={contentVisibilityStyle}
        >
          <span className="flex min-w-0 items-center gap-1.5">
            <span className="truncate">
              {positionDisplayName}
            </span>
            {shouldShowIncomingPosition && (
              <span className="truncate text-[10px] leading-3 font-normal text-slate-200">
                ({incomingPositionLabel})
              </span>
            )}
            {modeSupportsInactive && isInactive && <span className="flex-shrink-0 text-[11px] leading-3 text-slate-600">{inactiveLabel}</span>}
          </span>
          <div className="flex h-5 min-w-5 flex-shrink-0 items-center justify-end space-x-1">
            {/* Primary indicators (full opacity) - only show for active players */}
            {(!modeSupportsInactive || !isInactive) && isNextOff && !hideNextOffIndicator && <ArrowDownCircle className={`${ICON_STYLES.large} ${ICON_STYLES.indicators.nextOff} inline-block`} />}
            {(!modeSupportsInactive || !isInactive) && isNextOn && !hideNextOffIndicator && <ArrowUpCircle className={`${ICON_STYLES.large} ${ICON_STYLES.indicators.nextOn} inline-block`} />}
          </div>
        </h3>
        <div
          className="flex items-center justify-between gap-2 text-sm leading-4"
          style={contentVisibilityStyle}
        >
          <div className="min-w-0 truncate">{icon} {playerName}</div>
          <PlayerStatsDisplay playerId={playerId} getPlayerTimeStats={getPlayerTimeStats} showLiveDeficit={showLiveDeficit} />
        </div>
      </div>
    );
  };

  if (groupedFieldSections) {
    return (
      <div className="space-y-1.5" {...domProps}>
        {groupedFieldSections.map((section) => (
          section.isBordered ? (
            <div key={section.key} className="border-2 border-sky-400 rounded-lg p-1 space-y-1.5 bg-slate-700/30">
              {section.positions.map((position, index) => renderIndividualPosition(position, index))}
            </div>
          ) : (
            <React.Fragment key={section.key}>
              {section.positions.map((position, index) => renderIndividualPosition(position, index))}
            </React.Fragment>
          )
        ))}
        {renderIndividualPosition('goalie', -1)}
      </div>
    );
  }

  return (
    <div className="space-y-1.5" {...domProps}>
      {positionsToRender.map((position, index) =>
        renderIndividualPosition(position, index)
      )}
    </div>
  );
}

IndividualFormation.propTypes = {
  teamConfig: PropTypes.object.isRequired,
  selectedFormation: PropTypes.string,
  formation: PropTypes.object,
  allPlayers: PropTypes.array.isRequired,
  animationState: PropTypes.object.isRequired,
  recentlySubstitutedPlayers: PropTypes.instanceOf(Set).isRequired,
  hideNextOffIndicator: PropTypes.bool,
  quickTapHandlers: PropTypes.object,
  goalieHandlers: PropTypes.object,
  getPlayerNameById: PropTypes.func,
  getPlayerTimeStats: PropTypes.func.isRequired,
  nextPlayerIdToSubOut: PropTypes.string,
  substitutionCount: PropTypes.number,
  rotationQueue: PropTypes.array,
  roleGroups: PropTypes.object,
  substitutionLogic: PropTypes.string,
  nextToSubOutIds: PropTypes.array,
  fixedRoleGroup: PropTypes.string,
  showLiveDeficit: PropTypes.bool,
  renderSection: PropTypes.string,
  dragProps: PropTypes.shape({
    dragState: PropTypes.shape({
      active: PropTypes.bool,
      sourcePlayerId: PropTypes.string,
      hoveredPlayerId: PropTypes.string,
      actionType: PropTypes.string,
      isEligible: PropTypes.bool
    }),
    ghostPosition: PropTypes.shape({ x: PropTypes.number, y: PropTypes.number }),
    ghostSize: PropTypes.shape({ width: PropTypes.number, height: PropTypes.number }),
    ghostOffset: PropTypes.shape({ x: PropTypes.number, y: PropTypes.number }),
    swapAnimation: PropTypes.shape({
      targetPlayerId: PropTypes.string,
      targetFromRect: PropTypes.object,
      sourcePlayerId: PropTypes.string,
      sourceFromRect: PropTypes.object,
      durationMs: PropTypes.number,
      startedAt: PropTypes.number
    }),
    snapBack: PropTypes.shape({
      sourcePlayerId: PropTypes.string,
      fromX: PropTypes.number,
      fromY: PropTypes.number,
      toX: PropTypes.number,
      toY: PropTypes.number,
      width: PropTypes.number,
      height: PropTypes.number,
      durationMs: PropTypes.number
    }),
    handlePointerDown: PropTypes.func,
    shouldSuppressClick: PropTypes.func
  })
};

// Memoize IndividualFormation to prevent unnecessary re-renders
export default React.memo(IndividualFormation);
