import React, { useState, useRef, useEffect, useCallback } from 'react';
import PropTypes from 'prop-types';
import { Sparkles, Plus, Trash2 } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { Button, ConfirmationModal, Input } from '../shared/UI';
import { Alert } from '../shared/Alert';
import { Card } from '../shared/Card';
import { DemoBadge } from '../shared/DemoBadge';
import { useAuth } from '../../contexts/AuthContext';
import { useTeam } from '../../contexts/TeamContext';
import { useToast } from '../../contexts/ToastContext';
import { VIEWS } from '../../constants/viewConstants';
import { ChangePassword } from '../auth/ChangePassword';
import { PlayerRelationshipRequestModal } from '../team/PlayerRelationshipRequestModal';
import { sanitizeNameInput, isValidNameInput } from '../../utils/inputSanitization';
import { useTeamSwitchAction } from '../../hooks/useTeamSwitchAction';
import { useDemoTeamActions } from '../../hooks/useDemoTeamActions';
import { nextWizardNonce } from '../../utils/wizardNonce';
import { PendingTeamRequests } from './PendingTeamRequests';
import { DeleteAccountModal } from './DeleteAccountModal';

const LEAVE_TEAM_BLOCKING_ERRORS = ['last_team_member', 'last_team_admin'];

export function ProfileScreen({ onNavigateBack, onNavigateTo, pushNavigationState, removeFromNavigationStack, matchState }) {
  const { t, i18n } = useTranslation('profile');
  const { user, userProfile, updateProfile, loading, authError, clearAuthError, profileName, markProfileCompleted, deleteAccount } = useAuth();
  const {
    currentTeam,
    userTeams,
    loading: teamLoading,
    leaveTeam,
    deleteTeam,
    demoTeam,
    isParent,
    error: teamError,
    clearError: clearTeamError
  } = useTeam();
  const { showSuccess, showWarning } = useToast();
  const { generateDemoTeam } = useDemoTeamActions();
  const { confirming: switchConfirming, runSwitch } = useTeamSwitchAction();
  const [isEditing, setIsEditing] = useState(false);
  const [editedName, setEditedName] = useState(userProfile?.name || '');
  const [errors, setErrors] = useState({});
  const [showChangePassword, setShowChangePassword] = useState(false);
  const [showAccountInfo, setShowAccountInfo] = useState(false);
  const [showDangerZone, setShowDangerZone] = useState(false);
  const [leavingTeamId, setLeavingTeamId] = useState(null);
  const [switchingTeamId, setSwitchingTeamId] = useState(null);
  const [leaveTeamConfirmation, setLeaveTeamConfirmation] = useState(null);
  const [leaveTeamBlocked, setLeaveTeamBlocked] = useState(null);
  const [isDeletingTeam, setIsDeletingTeam] = useState(false);
  const [isGeneratingDemo, setIsGeneratingDemo] = useState(false);
  const [showPlayerLinkModal, setShowPlayerLinkModal] = useState(false);
  const [showDeleteAccount, setShowDeleteAccount] = useState(false);
  const [isDeletingAccount, setIsDeletingAccount] = useState(false);
  const nameInputRef = useRef(null);

  const handleOpenPlayerLinkModal = () => {
    setShowPlayerLinkModal(true);
    pushNavigationState?.(() => setShowPlayerLinkModal(false));
  };

  const handleClosePlayerLinkModal = () => {
    setShowPlayerLinkModal(false);
    removeFromNavigationStack?.();
  };

  const handleOpenDeleteAccount = () => {
    setShowDeleteAccount(true);
    pushNavigationState?.(() => setShowDeleteAccount(false));
  };

  const handleCloseDeleteAccount = () => {
    if (isDeletingAccount) return;
    setShowDeleteAccount(false);
    removeFromNavigationStack?.();
  };

  const handleConfirmDeleteAccount = async () => {
    if (isDeletingAccount) return;
    setIsDeletingAccount(true);
    try {
      const result = await deleteAccount();
      if (result?.error) {
        showWarning(t('modals.deleteAccount.error'));
        return;
      }
      // Success: AuthContext cleared the session; the auth gate will route to sign-in.
      setShowDeleteAccount(false);
      removeFromNavigationStack?.();
    } finally {
      setIsDeletingAccount(false);
    }
  };

  const handleGenerateDemoTeam = async () => {
    if (isGeneratingDemo) return;
    setIsGeneratingDemo(true);
    try {
      await generateDemoTeam();
    } finally {
      setIsGeneratingDemo(false);
    }
  };

  // Register browser back handler
  useEffect(() => {
    if (pushNavigationState) {
      pushNavigationState(() => {
        onNavigateBack();
      });
    }

    return () => {
      if (removeFromNavigationStack) {
        removeFromNavigationStack();
      }
    };
  }, [pushNavigationState, removeFromNavigationStack, onNavigateBack]);

  // Clear auth errors when user starts editing
  useEffect(() => {
    if (isEditing && authError) {
      clearAuthError();
    }
  }, [isEditing, authError, clearAuthError]);

  const handleEdit = () => {
    setIsEditing(true);
    setEditedName(userProfile?.name || '');
    setErrors({});
  };

  // Auto-focus name input when editing starts
  useEffect(() => {
    if (isEditing && nameInputRef.current) {
      nameInputRef.current.focus();
    }
  }, [isEditing]);

  const handleCancel = () => {
    setIsEditing(false);
    setEditedName(userProfile?.name || '');
    setErrors({});
  };

  const validateForm = () => {
    const newErrors = {};

    const trimmedName = editedName.trim();

    if (!trimmedName) {
      newErrors.name = t('validation.nameRequired');
    } else if (trimmedName.length < 2) {
      newErrors.name = t('validation.nameTooShort');
    } else if (!isValidNameInput(trimmedName)) {
      newErrors.name = t('validation.nameInvalidChars');
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSave = async () => {
    if (!validateForm()) {
      return;
    }

    try {
      // Sanitize the name input for security
      const sanitizedName = sanitizeNameInput(editedName.trim());
      
      const { profile, error } = await updateProfile({
        name: sanitizedName
      });

      if (error) {
        setErrors({ general: error.message });
      } else if (profile) {
        setIsEditing(false);
        showSuccess(t('messages.updateSuccess'));
        // Mark profile as completed if name was added
        if (profile.name && profile.name.trim()) {
          markProfileCompleted();
        }
      }
    } catch (error) {
      setErrors({ general: t('messages.unexpectedError') });
    }
  };

  const handleKeyDown = (e) => {
    if (e.key === 'Enter' && !loading) {
      e.preventDefault(); // Prevent any default form submission behavior
      handleSave();
    }
  };

  const getErrorMessage = () => {
    if (errors.general) return errors.general;
    if (authError) return authError;
    if (teamError && !leaveTeamBlocked) return teamError;
    return null;
  };

  const formatDate = (dateString) => {
    if (!dateString) return t('formatting.notAvailable');
    try {
      const locale = i18n.language === 'sv' ? 'sv-SE' : 'en-US';
      return new Date(dateString).toLocaleDateString(locale, {
        year: 'numeric',
        month: 'long',
        day: 'numeric'
      });
    } catch {
      return t('formatting.invalidDate');
    }
  };

  const getUserDisplayName = () => {
    if (userProfile?.name) {
      return userProfile.name;
    }
    if (user?.email) {
      return user.email.split('@')[0]; // Fallback to email username
    }
    return t('formatting.defaultUser');
  };

  const getInitials = () => {
    const displayName = getUserDisplayName();
    const names = displayName.split(' ');
    if (names.length > 1) {
      return `${names[0][0]}${names[names.length - 1][0]}`.toUpperCase();
    }
    return displayName.slice(0, 2).toUpperCase();
  };

  const formatTeamName = (team) => {
    if (!team) return t('formatting.unknownTeam');
    return team.club?.long_name ? `${team.club.long_name} ${team.name}` : team.name;
  };

  const getLeaveTeamBlockedMessage = () => {
    if (!leaveTeamBlocked?.team) return '';
    const teamName = formatTeamName(leaveTeamBlocked.team);
    if (leaveTeamBlocked.reason === 'last_team_member') {
      return t('modals.cantLeaveTeam.lastMember', { teamName });
    }
    return t('modals.cantLeaveTeam.lastAdmin', { teamName });
  };

  const handleLeaveTeam = (team) => {
    if (!team?.id) {
      return;
    }

    setLeaveTeamConfirmation(team);
  };

  const handleSwitchTeam = async (teamId) => {
    setSwitchingTeamId(teamId);
    try {
      await runSwitch(teamId);
    } finally {
      setSwitchingTeamId(null);
    }
  };

  const confirmLeaveTeam = async () => {
    if (!leaveTeamConfirmation?.id || !leaveTeam) {
      setLeaveTeamConfirmation(null);
      return;
    }

    setLeavingTeamId(leaveTeamConfirmation.id);
    try {
      const result = await leaveTeam(leaveTeamConfirmation);
      if (result?.error && LEAVE_TEAM_BLOCKING_ERRORS.includes(result.error)) {
        setLeaveTeamBlocked({
          team: leaveTeamConfirmation,
          reason: result.error
        });
        if (clearTeamError) {
          clearTeamError();
        }
      } else {
        setLeaveTeamBlocked(null);
      }
    } finally {
      setLeavingTeamId(null);
      setLeaveTeamConfirmation(null);
    }
  };

  const confirmDeleteTeam = async () => {
    if (!leaveTeamBlocked?.team?.id || !deleteTeam || isDeletingTeam) {
      return;
    }

    setIsDeletingTeam(true);
    try {
      await deleteTeam(leaveTeamBlocked.team);
    } finally {
      setIsDeletingTeam(false);
      setLeaveTeamBlocked(null);
    }
  };

  const handleLeaveTeamBlockedCancel = () => {
    setLeaveTeamBlocked(null);
    if (clearTeamError) {
      clearTeamError();
    }
  };

  const teams = userTeams || [];
  const hasTeams = teams.length > 0;

  // Universal entry point: open the wizard at club selection so the user can pick any club (not just their current one).
  const handleCreateOrJoinTeam = useCallback(() => {
    onNavigateTo(VIEWS.TEAM_MANAGEMENT, {
      openCreateWizard: true,
      openCreateWizardNonce: nextWizardNonce(),
      openCreateWizardForceClub: true,
    });
  }, [onNavigateTo]);

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-bold text-sky-300">{t('screen.title')}</h1>
        <Button
          onClick={onNavigateBack}
          variant="secondary"
          size="sm"
        >
          {t('screen.back')}
        </Button>
      </div>

      {/* Error Message */}
      {getErrorMessage() && (
        <Alert variant="error">{getErrorMessage()}</Alert>
      )}

      {/* Profile Card */}
      <div className="bg-slate-700 rounded-lg border border-slate-600 overflow-hidden">
        {/* Profile Header */}
        <div className="bg-gradient-to-r from-sky-600 to-sky-700 px-6 py-8">
          <div className="flex items-center space-x-4">
            {/* Avatar */}
            <div className="w-20 h-20 bg-sky-800 rounded-full flex items-center justify-center border-4 border-sky-400">
              <span className="text-sky-100 text-2xl font-bold">
                {getInitials()}
              </span>
            </div>
            
            {/* User Info */}
            <div className="flex-1">
              <h2 className="text-2xl font-bold text-white">
                {getUserDisplayName()}
              </h2>
              <p className="text-sky-200 opacity-90">
                {user?.email}
              </p>
              {user?.email_confirmed_at && (
                <div className="flex items-center space-x-1 mt-1">
                  <svg className="w-4 h-4 text-emerald-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                  </svg>
                  <span className="text-emerald-300 text-sm">{t('personalInfo.emailVerified')}</span>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Profile Details */}
        <div className="p-6 space-y-6">
          {/* Personal Information */}
          <div>
            <h3 className="text-lg font-semibold text-slate-200 mb-4">{t('personalInfo.title')}</h3>

            <div className="space-y-4">
              {/* Name Field */}
              <div>
                <label className="block text-sm font-medium text-slate-300 mb-2">
                  {t('personalInfo.fullName')}
                </label>
                {isEditing ? (
                  <div className="space-y-2">
                    <Input
                      ref={nameInputRef}
                      value={editedName}
                      onChange={(e) => {
                        setEditedName(e.target.value);
                        if (errors.name) {
                          setErrors(prev => ({ ...prev, name: null }));
                        }
                      }}
                      onKeyDown={handleKeyDown}
                      placeholder={t('personalInfo.namePlaceholder')}
                      disabled={loading}
                      error={!!errors.name}
                    />
                    {errors.name && (
                      <p className="text-rose-400 text-sm">{errors.name}</p>
                    )}
                    <div className="flex space-x-2">
                      <Button
                        onClick={handleSave}
                        variant="primary"
                        size="sm"
                        disabled={loading}
                      >
                        {loading ? t('buttons.saving') : t('buttons.save')}
                      </Button>
                      <Button
                        onClick={handleCancel}
                        variant="secondary"
                        size="sm"
                        disabled={loading}
                      >
                        {t('buttons.cancel')}
                      </Button>
                    </div>
                  </div>
                ) : (
                  <div className="flex items-center justify-between">
                    <span className="text-slate-100">
                      {profileName}
                    </span>
                    <Button
                      onClick={handleEdit}
                      variant="secondary"
                      size="sm"
                      className={profileName === t('formatting.notSet') ? 'animate-glow-and-fade' : ''}
                    >
                      {t('buttons.edit')}
                    </Button>
                  </div>
                )}
              </div>

              {/* Email Field (Read-only) */}
              <div>
                <label className="block text-sm font-medium text-slate-300 mb-2">
                  {t('personalInfo.emailAddress')}
                </label>
                <div className="flex items-center justify-between">
                  <span className="text-slate-100">{user?.email}</span>
                  <span className="text-xs text-slate-400">{t('personalInfo.readOnly')}</span>
                </div>
              </div>

              {/* Password Field */}
              <div>
                <label className="block text-sm font-medium text-slate-300 mb-2">
                  {t('personalInfo.password')}
                </label>
                <div className="flex items-center justify-between">
                  <span className="text-slate-400 text-sm">••••••••••••</span>
                  <Button
                    onClick={() => setShowChangePassword(true)}
                    variant="secondary"
                    size="sm"
                  >
                    {t('personalInfo.changePassword')}
                  </Button>
                </div>
                <p className="text-slate-500 text-xs mt-1">
                  {t('personalInfo.passwordHint')}
                </p>
              </div>
            </div>
          </div>

          {/* Account Information - Collapsible */}
          <div>
            <button
              onClick={() => setShowAccountInfo(!showAccountInfo)}
              className="w-full flex items-center justify-between text-left hover:bg-slate-600 hover:bg-opacity-30 rounded-lg p-2 -m-2 transition-colors"
            >
              <h3 className="text-lg font-semibold text-slate-200">{t('accountInfo.title')}</h3>
              <svg
                className={`w-5 h-5 text-slate-400 transition-transform ${
                  showAccountInfo ? 'rotate-180' : ''
                }`}
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
              </svg>
            </button>
            
            {showAccountInfo && (
              <div className="mt-4 grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-slate-300 mb-1">
                    {t('accountInfo.created')}
                  </label>
                  <span className="text-slate-100 text-sm">
                    {formatDate(user?.created_at)}
                  </span>
                </div>

                <div>
                  <label className="block text-sm font-medium text-slate-300 mb-1">
                    {t('accountInfo.updated')}
                  </label>
                  <span className="text-slate-100 text-sm">
                    {formatDate(userProfile?.updated_at)}
                  </span>
                </div>

                <div>
                  <label className="block text-sm font-medium text-slate-300 mb-1">
                    {t('accountInfo.userId')}
                  </label>
                  <span className="text-slate-400 text-xs font-mono break-all">
                    {user?.id}
                  </span>
                </div>

                <div>
                  <label className="block text-sm font-medium text-slate-300 mb-1">
                    {t('accountInfo.emailStatus')}
                  </label>
                  <span className={`text-sm ${
                    user?.email_confirmed_at
                      ? 'text-emerald-400'
                      : 'text-amber-400'
                  }`}>
                    {user?.email_confirmed_at ? t('accountInfo.verified') : t('accountInfo.pendingVerification')}
                  </span>
                </div>
              </div>
            )}
          </div>

          {/* Team Management */}
          <div className="border-t border-slate-600 pt-6">
            <h3 className="text-lg font-semibold text-slate-200 mb-4">{t('teamManagement.title')}</h3>

            {teamLoading ? (
              <Card variant="dark">
                <p className="text-slate-400 text-sm text-center">{t('teamManagement.loading')}</p>
              </Card>
            ) : (
              <div className="space-y-4">
                {/* Current Active Team */}
                {currentTeam && (
                  <button
                    onClick={() => onNavigateTo(VIEWS.TEAM_MANAGEMENT)}
                    className="w-full bg-sky-900/30 border border-sky-600 rounded-lg p-4 hover:bg-sky-900/40 transition-colors"
                  >
                    <div className="flex items-center justify-between">
                      <div className="text-left">
                        <h4 className="font-medium text-sky-200">{t('teamManagement.currentTeam')}</h4>
                        <p className="text-sky-100 font-semibold flex items-center gap-2">
                          <span>{currentTeam.club?.long_name ? `${currentTeam.club.long_name} ${currentTeam.name}` : currentTeam.name}</span>
                          {currentTeam.is_demo && <DemoBadge />}
                        </p>
                        <p className="text-sky-300 text-sm">
                          {currentTeam.userRole || t('teamManagement.member')}
                        </p>
                      </div>
                      <div className="w-3 h-3 bg-emerald-400 rounded-full"></div>
                    </div>
                  </button>
                )}

                {currentTeam && isParent && (
                  <Button
                    onClick={handleOpenPlayerLinkModal}
                    variant="secondary"
                    className="w-full"
                  >
                    {t('team:playerRequestModal.openButton')}
                  </Button>
                )}

                {hasTeams ? (
                  <div>
                    <h4 className="font-medium text-slate-300 mb-3">{t('teamManagement.yourTeams', { count: teams.length })}</h4>
                    <div className="space-y-2">
                      {teams.map((team) => (
                        <div
                          key={team.id}
                          className={`p-3 rounded-lg border transition-colors ${
                            currentTeam && team.id === currentTeam.id
                              ? 'bg-sky-900/20 border-sky-600'
                              : 'bg-slate-800 border-slate-600 hover:bg-slate-700'
                          }`}
                        >
                          <div className="flex items-center justify-between">
                            <div className="flex-1">
                              <p className="font-medium text-slate-100 flex items-center gap-2">
                                <span>{team.club?.long_name ? `${team.club.long_name} ${team.name}` : team.name}</span>
                                {team.is_demo && <DemoBadge />}
                              </p>
                              <p className="text-slate-400 text-sm">
                                {team.userRole || t('teamManagement.member')}
                                {team.active === false && ` • ${t('teamManagement.inactive')}`}
                              </p>
                            </div>
                            <div className="flex items-center gap-2">
                              {currentTeam && team.id !== currentTeam.id && matchState !== 'running' && (
                                <button
                                  onClick={() => handleSwitchTeam(team.id)}
                                  disabled={switchConfirming}
                                  className="text-sky-400 hover:text-sky-300 text-sm font-medium transition-colors disabled:opacity-60"
                                >
                                  {switchConfirming && switchingTeamId === team.id ? t('teamManagement.switching') : t('teamManagement.switch')}
                                </button>
                              )}
                              <Button
                                onClick={() => handleLeaveTeam(team)}
                                variant="danger"
                                size="sm"
                                disabled={leavingTeamId === team.id}
                              >
                                {leavingTeamId === team.id ? t('teamManagement.leaving') : t('teamManagement.leave')}
                              </Button>
                            </div>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                ) : (
                  <div className="bg-slate-800 rounded-lg p-6 border border-slate-600 text-center">
                    <div className="w-16 h-16 bg-slate-700 rounded-full flex items-center justify-center mx-auto mb-4">
                      <svg className="w-8 h-8 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z" />
                      </svg>
                    </div>
                    <h4 className="font-medium text-slate-200 mb-2">{t('emptyStates.noTeams.title')}</h4>
                    <p className="text-slate-400 text-sm mb-4">
                      {t('emptyStates.noTeams.description')}
                    </p>
                    <Button
                      onClick={() => onNavigateTo(VIEWS.TEAM_MANAGEMENT)}
                      variant="primary"
                      size="sm"
                      className="mx-auto"
                    >
                      {t('emptyStates.noTeams.action')}
                    </Button>
                  </div>
                )}

                {/* The user's own pending join requests — hidden when there are none. */}
                <PendingTeamRequests />

                {/* Generate a demo team to explore the rotation engine. Shown
                    whenever the coach has no active demo team. */}
                {!demoTeam && (
                  <div className="border-t border-slate-700 pt-4">
                    <Button
                      onClick={handleGenerateDemoTeam}
                      variant="secondary"
                      size="sm"
                      Icon={Sparkles}
                      disabled={isGeneratingDemo}
                      className="w-full sm:w-auto"
                    >
                      {isGeneratingDemo ? t('team:demo.generate.generating') : t('team:demo.generate.button')}
                    </Button>
                    <p className="text-slate-500 text-xs mt-2">{t('team:demo.generate.helper')}</p>
                  </div>
                )}

                {/* Shown only with teams; the no-teams empty state above already routes to the wizard. */}
                {hasTeams && (
                  <div className="border-t border-slate-700 pt-4">
                    <Button
                      onClick={handleCreateOrJoinTeam}
                      variant="secondary"
                      size="sm"
                      Icon={Plus}
                      className="w-full sm:w-auto"
                    >
                      {t('team:teamSelector.createOrJoin')}
                    </Button>
                    <p className="text-slate-500 text-xs mt-2">{t('profile:teamManagement.createOrJoinHelper')}</p>
                  </div>
                )}
              </div>
            )}
          </div>

          {/* Danger Zone — collapsible; in-app account deletion (App Store 5.1.1(v)) */}
          <div className="border-t border-slate-600 pt-6">
            <button
              onClick={() => setShowDangerZone(!showDangerZone)}
              className="w-full flex items-center justify-between text-left hover:bg-slate-600 hover:bg-opacity-30 rounded-lg p-2 -m-2 transition-colors"
            >
              <h3 className="text-lg font-semibold text-rose-300">{t('dangerZone.title')}</h3>
              <svg
                className={`w-5 h-5 text-slate-400 transition-transform ${
                  showDangerZone ? 'rotate-180' : ''
                }`}
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
              </svg>
            </button>

            {showDangerZone && (
              <div className="mt-4">
                <p className="text-slate-400 text-sm mb-4">{t('dangerZone.deleteAccount.description')}</p>
                <Button
                  onClick={handleOpenDeleteAccount}
                  variant="danger"
                  size="sm"
                  Icon={Trash2}
                  disabled={isDeletingAccount}
                  className="w-full sm:w-auto"
                >
                  {t('dangerZone.deleteAccount.button')}
                </Button>
              </div>
            )}
          </div>
        </div>
      </div>

      <DeleteAccountModal
        isOpen={showDeleteAccount}
        onConfirm={handleConfirmDeleteAccount}
        onCancel={handleCloseDeleteAccount}
        isDeleting={isDeletingAccount}
      />

      {/* Change Password Modal */}
      <ChangePassword
        isOpen={showChangePassword}
        onClose={() => setShowChangePassword(false)}
      />

      <ConfirmationModal
        isOpen={Boolean(leaveTeamConfirmation)}
        onConfirm={confirmLeaveTeam}
        onCancel={() => setLeaveTeamConfirmation(null)}
        title={t('modals.leaveTeam.title')}
        message={
          leaveTeamConfirmation
            ? t('modals.leaveTeam.message', { teamName: formatTeamName(leaveTeamConfirmation) })
            : ''
        }
        confirmText={t('modals.leaveTeam.confirm')}
        cancelText={t('buttons.cancel')}
        variant="danger"
      />

      <ConfirmationModal
        isOpen={Boolean(leaveTeamBlocked)}
        onConfirm={confirmDeleteTeam}
        onCancel={handleLeaveTeamBlockedCancel}
        title={t('modals.cantLeaveTeam.title')}
        message={getLeaveTeamBlockedMessage()}
        confirmText={isDeletingTeam ? t('modals.cantLeaveTeam.deletingButton') : t('modals.cantLeaveTeam.deleteButton')}
        cancelText={t('buttons.cancel')}
        variant="danger"
      />

      {showPlayerLinkModal && currentTeam && (
        <PlayerRelationshipRequestModal
          team={currentTeam}
          onClose={handleClosePlayerLinkModal}
        />
      )}
    </div>
  );
}

ProfileScreen.propTypes = {
  onNavigateBack: PropTypes.func.isRequired,
  onNavigateTo: PropTypes.func.isRequired,
  pushNavigationState: PropTypes.func.isRequired,
  removeFromNavigationStack: PropTypes.func.isRequired,
  matchState: PropTypes.string,
};
