/**
 * Utility functions for handling password reset tokens and URL parameters
 */

/**
 * Dedicated path for password-reset callbacks. Supabase is configured to
 * redirect reset emails here so detection is path-based and unambiguous.
 */
export const RESET_PASSWORD_PATH = '/auth/reset-password';

/**
 * Detects if the current URL contains password reset tokens or codes.
 *
 * Detection is path-based to avoid ambiguity with OAuth / magic-link /
 * invitation flows that also use `?code=`:
 *  - On `/auth/reset-password`: any `?code=` or recovery tokens → reset.
 *  - On `/` with `?access_token=…&type=recovery`: reset (backward compat
 *    with in-flight reset emails sent before the dedicated path rollout).
 *  - Elsewhere: never treated as reset.
 *
 * @returns {Object} Object with detection results and token/code data
 */
export function detectResetTokens() {
  if (typeof window === 'undefined') {
    return { hasTokens: false, format: null, tokens: { accessToken: null, refreshToken: null, type: null }, code: null };
  }

  const urlParams = new URLSearchParams(window.location.search);
  const pathname = window.location.pathname;

  const accessToken = urlParams.get('access_token');
  const refreshToken = urlParams.get('refresh_token');
  const type = urlParams.get('type');
  const code = urlParams.get('code');

  const hasRecoveryTokens = !!(accessToken && refreshToken && type === 'recovery');
  const onResetPath = pathname === RESET_PASSWORD_PATH;

  // Tokens format: valid on the dedicated reset path OR on `/` for backward
  // compat with emails already in users' inboxes at the time of rollout.
  const tokensAccepted = hasRecoveryTokens && (onResetPath || pathname === '/');

  // Code format: only accepted on the dedicated reset path. At `/`, a bare
  // `?code=` is ambiguous with OAuth / invitation flows and is handled by
  // their own detectors, not here.
  const codeAccepted = !!code && onResetPath;

  return {
    hasTokens: tokensAccepted || codeAccepted,
    format: tokensAccepted ? 'tokens' : (codeAccepted ? 'code' : null),
    tokens: {
      accessToken,
      refreshToken,
      type
    },
    code: codeAccepted ? code : null
  };
}

/**
 * Clears password reset parameters from the URL without triggering a page reload
 */
export function clearResetTokensFromUrl() {
  if (typeof window !== 'undefined' && window.history && window.history.replaceState) {
    const url = new URL(window.location);
    url.searchParams.delete('access_token');
    url.searchParams.delete('refresh_token');
    url.searchParams.delete('type');
    url.searchParams.delete('code');
    
    window.history.replaceState({}, document.title, url.toString());
  }
}

/**
 * Checks if the user is currently authenticated via a password reset session
 * This helps distinguish between normal authenticated users and users who just clicked a reset link
 * @param {Object} user - The current user object from Supabase
 * @returns {boolean} True if this appears to be a password reset session
 */
export function isPasswordResetSession(user) {
  // Check if we have reset tokens or code in URL
  const { hasTokens } = detectResetTokens();
  
  // Return true if:
  // 1. User is authenticated AND
  // 2. We have reset tokens/codes OR the URL was just cleaned up but user is newly authenticated
  return hasTokens && !!user;
}

/**
 * Checks if we should automatically show the password reset modal.
 *
 * Path-strict: only the dedicated reset path counts. The previous substring
 * checks (`pathname.includes('reset')` / `search.includes('password')`) fired
 * for unrelated URLs — most notably OAuth error responses whose
 * `error_description` contains the word "password" — and popped the reset
 * modal over the app after a failed OAuth attempt.
 *
 * @param {Object} user - Current user object
 * @returns {boolean} True if password reset modal should be shown
 */
export function shouldShowPasswordResetModal(user) {
  const { hasTokens } = detectResetTokens();
  if (hasTokens) return true;

  if (user && typeof window !== 'undefined') {
    return window.location.pathname === RESET_PASSWORD_PATH;
  }

  return false;
}