// Re-key a single entry inside a `{ [matchId]: value }` state map.
// Used after a temporary match id is replaced with its real DB id on first
// save, so per-match state (selections, difficulty, unavailable markers, …)
// follows the match instead of being orphaned under the old key.
export const migratePerMatchKey = (setter, oldId, newId) => {
  if (oldId === newId) return;
  setter((prev) => {
    if (!prev || !(oldId in prev)) return prev;
    const { [oldId]: value, ...rest } = prev;
    return { ...rest, [newId]: value };
  });
};
