import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useTranslation } from 'react-i18next';
import { Sparkles } from 'lucide-react';
import { ModalShell } from './ModalShell';
import { Button } from './UI';
import { useTeam } from '../../contexts/TeamContext';
import { useToast } from '../../contexts/ToastContext';
import { useDemoTeamActions } from '../../hooks/useDemoTeamActions';
import { useBrowserBackIntercept } from '../../hooks/useBrowserBackIntercept';

// One-time opt-in prompt offering a brand-new coach a demo team to explore.
// Reads eligibility and actions from TeamContext; renders nothing otherwise.
export function DemoTeamPromptModal() {
  const { t } = useTranslation('team');
  const { demoPromptEligible, declineDemoPrompt } = useTeam();
  const { acceptDemoTeam } = useDemoTeamActions();
  const { showWarning } = useToast();
  const { pushNavigationState, removeFromNavigationStack } = useBrowserBackIntercept();
  const [dontAskAgain, setDontAskAgain] = useState(false);
  const [submitting, setSubmitting] = useState(false);

  // Keep the latest checkbox value available to the back-button handler closure.
  const dontAskAgainRef = useRef(dontAskAgain);
  dontAskAgainRef.current = dontAskAgain;

  const handleDecline = useCallback(async () => {
    setSubmitting(true);
    try {
      const result = await declineDemoPrompt({ dontAskAgain: dontAskAgainRef.current });
      if (dontAskAgainRef.current && result?.error) {
        showWarning(t('demo.prompt.dismissError'));
      }
    } finally {
      setSubmitting(false);
    }
  }, [declineDemoPrompt, showWarning, t]);

  // Android/browser back dismisses the prompt like "Not now".
  useEffect(() => {
    if (!demoPromptEligible) return undefined;
    pushNavigationState(() => { handleDecline(); }, 'demo-team-prompt');
    return () => removeFromNavigationStack();
  }, [demoPromptEligible, handleDecline, pushNavigationState, removeFromNavigationStack]);

  if (!demoPromptEligible) return null;

  // Plain function (unlike handleDecline) — not referenced in any effect dep array.
  const handleAccept = async () => {
    setSubmitting(true);
    try {
      await acceptDemoTeam();
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <ModalShell
      title={t('demo.prompt.title')}
      icon={Sparkles}
      iconColor="amber"
      onClose={submitting ? undefined : handleDecline}
      maxWidth="md"
    >
      <p className="text-slate-200 mb-4">{t('demo.prompt.message')}</p>

      <label className="flex items-center gap-2 mb-5 text-sm text-slate-300 cursor-pointer select-none">
        <input
          type="checkbox"
          checked={dontAskAgain}
          onChange={(e) => setDontAskAgain(e.target.checked)}
          disabled={submitting}
          className="h-4 w-4 rounded border-slate-500 bg-slate-700 text-sky-500 focus:ring-sky-400"
        />
        {t('demo.prompt.dontAskAgain')}
      </label>

      <div className="flex flex-col sm:flex-row gap-3 sm:justify-end">
        <Button
          onClick={handleDecline}
          variant="secondary"
          className="w-full sm:w-auto sm:order-1"
          disabled={submitting}
        >
          {t('demo.prompt.decline')}
        </Button>
        <Button
          onClick={handleAccept}
          variant="primary"
          className="w-full sm:w-auto sm:order-2"
          disabled={submitting}
        >
          {t('demo.prompt.accept')}
        </Button>
      </div>
    </ModalShell>
  );
}
