import { useEffect, useRef } from 'react';
import { VIEWS } from '../constants/viewConstants';
import {
  clearInitialRedirectIf,
  getInitialPathRoutingState,
  releaseInitialRouteSyncLock,
  shouldDeferInitialRouteSync
} from './pathRoutingState';

const UUID_PATTERN = '[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}';
const PLAN_IDS_REGEX = new RegExp(
  `^/plan/(${UUID_PATTERN}(?:,${UUID_PATTERN})*)$`,
  'i'
);

/**
 * Hook to handle /plan and /plan/{matchId1},{matchId2} route detection and navigation.
 *
 * - Bare /plan: navigates to TEAM_MATCHES (existing behaviour — shows match list)
 * - /plan/{ids}: extracts match IDs, calls setPlanMatchIdsFromUrl so App.js can
 *   orchestrate auth-gating and data fetching before navigating to PLAN_MATCHES.
 *
 * @param {string} view - Current view from game state
 * @param {Function} navigateToView - Navigate to a VIEWS constant
 * @param {Function} setPlanMatchIdsFromUrl - Setter for plan match IDs extracted from URL
 * @param {string[]|null} activePlanMatchIds - Currently active plan match IDs (for URL sync)
 */
export function usePlanMatchesRouting(view, navigateToView, setPlanMatchIdsFromUrl, activePlanMatchIds = null, options = {}) {
  const { authGateActive = false } = options;
  const initialPathRef = useRef(null);
  const initialRouteHandledRef = useRef(false);
  const currentMatchIdsRef = useRef(null);
  const hasSyncedInitialRouteRef = useRef(false);

  // --- Initial route detection ---
  useEffect(() => {
    if (typeof window === 'undefined') {
      initialRouteHandledRef.current = true;
      return;
    }

    if (initialPathRef.current === null) {
      const initialPathState = getInitialPathRoutingState();
      initialPathRef.current = initialPathState.path;

      if (initialPathState.fromRedirect && (initialPathState.path === '/plan' || initialPathState.path.startsWith('/plan/'))) {
        clearInitialRedirectIf((redirectPath) => redirectPath === initialPathState.path);
      }
    }

    if (initialRouteHandledRef.current) {
      return;
    }

    // Defer initial navigation while the app-level auth gate is open.
    if (authGateActive) {
      return;
    }

    const path = initialPathRef.current;

    // /plan/{id1},{id2,...} — extract match IDs, defer navigation to App.js effect
    const idsMatch = path.match(PLAN_IDS_REGEX);
    if (idsMatch && idsMatch[1]) {
      const matchIds = idsMatch[1].split(',');
      currentMatchIdsRef.current = matchIds;
      setPlanMatchIdsFromUrl?.(matchIds);
      initialRouteHandledRef.current = true;
      return;
    }

    // Bare /plan — navigate to team matches list (existing behaviour)
    if (path === '/plan') {
      const activeViews = new Set([VIEWS.TEAM_MATCHES, VIEWS.PLAN_MATCHES]);
      if (!activeViews.has(view)) {
        navigateToView?.(VIEWS.TEAM_MATCHES);
      }
    }

    initialRouteHandledRef.current = true;
  }, [navigateToView, setPlanMatchIdsFromUrl, view, authGateActive]);

  // Track activePlanMatchIds for URL sync
  useEffect(() => {
    if (activePlanMatchIds && activePlanMatchIds !== currentMatchIdsRef.current) {
      currentMatchIdsRef.current = activePlanMatchIds;
    }
  }, [activePlanMatchIds]);

  // --- URL sync ---
  useEffect(() => {
    if (typeof window === 'undefined') {
      return;
    }

    const normalizedPath = (window.location.pathname || '').replace(/\/+$/, '') || '/';
    const isPlanPath = normalizedPath === '/plan' || normalizedPath.startsWith('/plan/');
    const ownsInitialPath = initialPathRef.current === '/plan' || PLAN_IDS_REGEX.test(initialPathRef.current || '');
    const ownsView = view === VIEWS.PLAN_MATCHES || view === VIEWS.TEAM_MATCHES;

    // Mark once we've synced so subsequent view changes can update the URL
    if (isPlanPath && view === VIEWS.PLAN_MATCHES && currentMatchIdsRef.current) {
      hasSyncedInitialRouteRef.current = true;
    }

    if (ownsInitialPath && ownsView) {
      releaseInitialRouteSyncLock();
    }

    if (shouldDeferInitialRouteSync({ ownsInitialPath, ownsView })) {
      return;
    }

    // Avoid overriding a direct /plan/{ids} navigation before the view syncs
    if (
      isPlanPath &&
      currentMatchIdsRef.current &&
      !hasSyncedInitialRouteRef.current &&
      view !== VIEWS.PLAN_MATCHES
    ) {
      return;
    }

    const resolvedIds = currentMatchIdsRef.current || activePlanMatchIds;

    let targetPath = null;
    if (view === VIEWS.PLAN_MATCHES && resolvedIds && resolvedIds.length > 0) {
      targetPath = `/plan/${resolvedIds.join(',')}`;
    } else if (view === VIEWS.PLAN_MATCHES) {
      targetPath = '/plan';
    } else if (isPlanPath) {
      // Leaving plan views — clean up to /
      targetPath = '/';
    }

    if (targetPath !== null && normalizedPath !== targetPath) {
      const search = window.location.search || '';
      const hash = window.location.hash || '';
      const newUrl = `${targetPath}${search}${hash}`;
      window.history.replaceState(window.history.state, '', newUrl);

      if (targetPath.startsWith('/plan/')) {
        hasSyncedInitialRouteRef.current = true;
      }
    }
  }, [activePlanMatchIds, view]);
}
