import {
  FORMATIONS,
  SUBSTITUTION_LOGIC_VALUES,
  getSameRoleGroupDefinitions,
  getSameRoleRotationOrder,
  getFixedGroupFieldPositions
} from '../constants/teamConfiguration';
import { getFormationDefinition } from './formationConfigUtils';
import { PLAYER_ROLES } from '../constants/playerConstants';
import { roleToDatabase } from '../constants/roleConstants';

// Role constants for formation logic (database format for consistency)
const DB_DEFENDER = roleToDatabase(PLAYER_ROLES.DEFENDER);
const DB_ATTACKER = roleToDatabase(PLAYER_ROLES.ATTACKER);
const DB_MIDFIELDER = roleToDatabase(PLAYER_ROLES.MIDFIELDER);

// Helper to get mode definition - uses centralized formation utilities
const getDefinition = (teamConfig, selectedFormation = null) => {
  return getFormationDefinition(teamConfig, selectedFormation);
};



/**
 * Generates formation recommendations for individual modes (6, 7, or 8+ players)
 * For Period 1 (no stats), creates basic positional rotation queue
 * For Period 2+, creates time-based rotation queue
 * 
 * @param {string} currentGoalieId - ID of the current goalie
 * @param {Array} playerStats - Array of player stats
 * @param {Array} squad - Array of squad players
 * @param {Object} teamConfig - Team configuration object
 * @param {string} selectedFormation - Formation type (2-2, 1-2-1, etc.)
 * @returns {Object} Formation recommendation with formation, rotationQueue, and nextToRotateOff
 */
const generateIndividualFormationRecommendation = (
  currentGoalieId,
  playerStats,
  squad,
  teamConfig,
  selectedFormation = null,
  fixedRoleGroup = null,
  previousFormation = null
) => {
  const modeDefinition = getDefinition(teamConfig, selectedFormation || teamConfig?.formation);
  if (!modeDefinition) {
    return {
      formation: { goalie: currentGoalieId },
      rotationQueue: [],
      nextToRotateOff: null
    };
  }

  const formationKey = selectedFormation || teamConfig?.formation || FORMATIONS.FORMATION_2_2;

  if (formationKey === FORMATIONS.FORMATION_1_2_1) {
    return generate121FormationRecommendation(currentGoalieId, playerStats, squad, teamConfig, fixedRoleGroup, previousFormation);
  }

  if (formationKey === FORMATIONS.FORMATION_2_2) {
    return generate22FormationRecommendation(currentGoalieId, playerStats, squad, teamConfig, fixedRoleGroup, previousFormation);
  }

  return generateFormationRecommendation(currentGoalieId, playerStats, squad, teamConfig, formationKey, fixedRoleGroup, previousFormation);
};

/**
 * Generate formation recommendations for both 2-2 and 1-2-1 formations (consolidated logic)
 */
const generateFormationRecommendation = (currentGoalieId, playerStats, squad, teamConfig, formation, fixedRoleGroup = null, previousFormation = null) => {
  const outfielders = squad.filter(p => p.id !== currentGoalieId);
  
  // Get stats for all outfielders - include midfielder time for 1-2-1 formations
  const outfieldersWithStats = outfielders.map(p => {
    const pStats = playerStats.find(s => s.id === p.id);
    const defenderTime = pStats?.stats.timeAsDefenderSeconds || 0;
    const midfielderTime = pStats?.stats.timeAsMidfielderSeconds || 0;
    const attackerTime = pStats?.stats.timeAsAttackerSeconds || 0;
    const totalOutfieldTime = pStats?.stats.timeOnFieldSeconds || 0;
    
    const baseStats = {
      ...p,
      totalOutfieldTime,
      defenderTime,
      midfielderTime,
      attackerTime,
      isInactive: pStats?.stats.isInactive || false
    };

    // Add formation-specific stats
    if (formation === FORMATIONS.FORMATION_1_2_1) {
      return {
        ...baseStats,
        // Calculate role deficits for 1-2-1 balancing
        defenderDeficit: calculateRoleDeficit(defenderTime, midfielderTime, attackerTime, DB_DEFENDER),
        midfielderDeficit: calculateRoleDeficit(defenderTime, midfielderTime, attackerTime, DB_MIDFIELDER),
        attackerDeficit: calculateRoleDeficit(defenderTime, midfielderTime, attackerTime, DB_ATTACKER)
      };
    } else {
      return {
        ...baseStats,
        // Calculate surplus attacker time for 2-2 balancing
        surplusAttackerTime: attackerTime - defenderTime
      };
    }
  });

  // Separate active and inactive players
  const activePlayers = outfieldersWithStats.filter(p => !p.isInactive);
  const inactivePlayers = outfieldersWithStats.filter(p => p.isInactive);

  // For ROTATE_ROLES with a fixed role group, derive the fixed players from the previous
  // period's formation so they stay in their positions rather than being re-assigned by time.
  const fixedPlayerIds = [];
  const fixedPlayerIdSet = new Set();
  if (fixedRoleGroup && previousFormation) {
    const fixedPositions = getFixedGroupFieldPositions(teamConfig, fixedRoleGroup);
    fixedPositions.forEach(pos => {
      const playerId = previousFormation[pos];
      if (playerId && playerId !== currentGoalieId && activePlayers.some(p => p.id === playerId)) {
        fixedPlayerIds.push(playerId);
        fixedPlayerIdSet.add(playerId);
      }
    });
  }
  const nonFixedActivePlayers = fixedPlayerIdSet.size > 0
    ? activePlayers.filter(p => !fixedPlayerIdSet.has(p.id))
    : activePlayers;

  // Handle the case where there are no active substitutes (≤4 active players)
  if (activePlayers.length <= 4) {
    return handleLimitedPlayersFormation(currentGoalieId, activePlayers, inactivePlayers, teamConfig, formation);
  }

  // Create rotation queue for active players - Fixed: Ensure field players come first

  // Get mode configuration to determine positions
  const modeConfig = getDefinition(teamConfig, formation);
  const fieldSlotCount = modeConfig?.fieldPositions?.length || 4;
  const adjustedFieldSlotCount = fieldSlotCount - fixedPlayerIds.length;

  // For formation recommendation, we don't have existing formation data
  // So we'll determine field vs substitute based on time (least time = field players)
  const sortedByTime = nonFixedActivePlayers.sort((a, b) => a.totalOutfieldTime - b.totalOutfieldTime);
  const currentFieldPlayers = sortedByTime.slice(0, adjustedFieldSlotCount);
  const currentSubstitutes = sortedByTime.slice(adjustedFieldSlotCount);


  // Sort field players by most time first (ready to rotate off)
  const fieldPlayersOrdered = currentFieldPlayers.sort((a, b) => b.totalOutfieldTime - a.totalOutfieldTime);

  // Sort substitutes by least time first (ready to come on)
  const substitutesOrdered = currentSubstitutes.sort((a, b) => a.totalOutfieldTime - b.totalOutfieldTime);

  // Build rotation queue: field players first (can rotate off), then substitutes
  const rotationQueue = [...fieldPlayersOrdered, ...substitutesOrdered];


  // Create formation based on type - Fixed: Use players with least time for field positions
  // We want the players with the least total time to be on the field (for fairness)
  const playersForField = nonFixedActivePlayers
    .sort((a, b) => a.totalOutfieldTime - b.totalOutfieldTime)
    .slice(0, adjustedFieldSlotCount);


  let formationResult;

  if (fixedPlayerIds.length > 0) {
    // Fixed role group: assign non-fixed players to non-fixed field positions by time,
    // then place fixed players in their designated positions from the previous period.
    const allFieldPositions = modeConfig?.fieldPositions || [];
    const fixedGroupPositions = getFixedGroupFieldPositions(teamConfig, fixedRoleGroup);
    const nonFixedFieldPositions = allFieldPositions.filter(pos => !fixedGroupPositions.includes(pos));
    formationResult = { goalie: currentGoalieId };
    nonFixedFieldPositions.forEach((pos, i) => {
      formationResult[pos] = playersForField[i]?.id || null;
    });
    fixedGroupPositions.forEach((pos, i) => {
      formationResult[pos] = fixedPlayerIds[i] || null;
    });
  } else if (formation === FORMATIONS.FORMATION_1_2_1) {
    const positionAssignments = assign121Positions(playersForField);
    formationResult = {
      goalie: currentGoalieId,
      defender: positionAssignments.defender?.id || null,
      left: positionAssignments.left?.id || null,
      right: positionAssignments.right?.id || null,
      attacker: positionAssignments.attacker?.id || null
    };
  } else if (formation === FORMATIONS.FORMATION_2_2) {
    const fieldPlayersByAttackerSurplus = [...playersForField].sort((a, b) => b.surplusAttackerTime - a.surplusAttackerTime);
    const defenders = fieldPlayersByAttackerSurplus.slice(0, 2);
    const attackers = fieldPlayersByAttackerSurplus.slice(2, 4);

    formationResult = {
      goalie: currentGoalieId,
      leftDefender: defenders[0]?.id || null,
      rightDefender: defenders[1]?.id || null,
      leftAttacker: attackers[0]?.id || null,
      rightAttacker: attackers[1]?.id || null
    };
  } else {
    formationResult = buildFormationForMode(currentGoalieId, modeConfig, playersForField, substitutesOrdered, inactivePlayers);
  }

  const substitutePositions = modeConfig?.substitutePositions || [];
  addSubstitutePositions(formationResult, substitutePositions, substitutesOrdered, inactivePlayers);

  const rotationQueueIds = rotationQueue.map(p => p.id);

  // Exclude fixed-group players from the rotation queue for ROTATE_ROLES mode
  const filteredRotationQueueIds = fixedPlayerIdSet.size > 0
    ? rotationQueueIds.filter(id => !fixedPlayerIdSet.has(id))
    : rotationQueueIds;

  const nextToRotateOff = filteredRotationQueueIds[0] || null;

  return {
    formation: formationResult,
    rotationQueue: filteredRotationQueueIds,
    nextToRotateOff
  };
};

const buildFormationForMode = (currentGoalieId, modeDefinition, playersForField, substitutesOrdered, inactivePlayers) => {
  const formation = { goalie: currentGoalieId };
  const remainingPlayers = [...playersForField];

  const defenderPositions = (modeDefinition.fieldPositions || []).filter(position => position.toLowerCase().includes('defender'));
  const midfielderPositions = (modeDefinition.fieldPositions || []).filter(position => position.toLowerCase().includes('mid'));
  const attackerPositions = (modeDefinition.fieldPositions || []).filter(position => position.toLowerCase().includes('attack') || position === 'attacker');

  const assignRolePositions = (positions, role) => {
    positions.forEach(position => {
      remainingPlayers.sort((a, b) => getRoleTimeByKey(a, role) - getRoleTimeByKey(b, role));
      const player = remainingPlayers.shift();
      formation[position] = player?.id || null;
    });
  };

  assignRolePositions(defenderPositions, 'defender');
  assignRolePositions(midfielderPositions, 'midfielder');
  assignRolePositions(attackerPositions, 'attacker');

  const unfilledPositions = (modeDefinition.fieldPositions || []).filter(position => formation[position] === undefined);
  if (unfilledPositions.length > 0 && remainingPlayers.length > 0) {
    remainingPlayers.sort((a, b) => a.totalOutfieldTime - b.totalOutfieldTime);
    unfilledPositions.forEach((position, index) => {
      formation[position] = remainingPlayers[index]?.id || null;
    });
  }

  const substitutePositions = modeDefinition.substitutePositions || [];
  addSubstitutePositions(formation, substitutePositions, substitutesOrdered, inactivePlayers);

  return formation;
};

const getRoleTimeByKey = (player, role) => {
  switch (role) {
    case 'defender':
      return player.defenderTime ?? 0;
    case 'midfielder':
      return player.midfielderTime ?? 0;
    case 'attacker':
      return player.attackerTime ?? 0;
    default:
      return player.totalOutfieldTime ?? 0;
  }
};

/**
 * Handle formation when there are ≤4 active players (consolidated for both formations)
 */
const handleLimitedPlayersFormation = (currentGoalieId, activePlayers, inactivePlayers, teamConfig, formation) => {
  const availableActivePlayers = activePlayers.sort((a, b) => a.totalOutfieldTime - b.totalOutfieldTime);
  const modeConfig = getDefinition(teamConfig, formation);
  const fieldPositions = modeConfig?.fieldPositions || [];
  const substitutePositions = modeConfig?.substitutePositions || [];

  const formationResult = { goalie: currentGoalieId };

  fieldPositions.forEach((position, index) => {
    formationResult[position] = availableActivePlayers[index]?.id || null;
  });

  const remainingActive = availableActivePlayers.slice(fieldPositions.length);
  addSubstitutePositions(formationResult, substitutePositions, remainingActive, inactivePlayers);
  
  return {
    formation: formationResult,
    rotationQueue: [],
    nextToRotateOff: null
  };
};

/**
 * Add substitute positions to formation (consolidated logic)
 */
const addSubstitutePositions = (formation, substitutePositions, activeSubstitutes, inactivePlayers) => {
  const activeIds = activeSubstitutes.map(player => player.id);
  const inactiveIds = inactivePlayers.map(player => player.id);

  substitutePositions.forEach((positionKey, index) => {
    if (index < activeIds.length) {
      formation[positionKey] = activeIds[index] || null;
    } else {
      const inactiveIndex = index - activeIds.length;
      formation[positionKey] = inactiveIds[inactiveIndex] || null;
    }
  });
};

/**
 * Generate formation recommendations for 2-2 formation (wrapper)
 */
const generate22FormationRecommendation = (currentGoalieId, playerStats, squad, teamConfig, fixedRoleGroup = null, previousFormation = null) => {
  return generateFormationRecommendation(currentGoalieId, playerStats, squad, teamConfig, FORMATIONS.FORMATION_2_2, fixedRoleGroup, previousFormation);
};

/**
 * Generate formation recommendations for 1-2-1 formation (wrapper)
 */
const generate121FormationRecommendation = (currentGoalieId, playerStats, squad, teamConfig, fixedRoleGroup = null, previousFormation = null) => {
  return generateFormationRecommendation(currentGoalieId, playerStats, squad, teamConfig, FORMATIONS.FORMATION_1_2_1, fixedRoleGroup, previousFormation);
};

/**
 * Calculate role deficit for time balancing in 1-2-1 formation
 */
const calculateRoleDeficit = (defenderTime, midfielderTime, attackerTime, role) => {
  const totalOutfieldTime = defenderTime + midfielderTime + attackerTime;
  
  if (totalOutfieldTime === 0) return 0;
  
  const expectedRoleTime = totalOutfieldTime / 3; // Equal distribution across 3 roles
  let currentRoleTime;
  
  switch (role) {
    case DB_DEFENDER:
      currentRoleTime = defenderTime;
      break;
    case DB_MIDFIELDER:
      currentRoleTime = midfielderTime;
      break;
    case DB_ATTACKER:
      currentRoleTime = attackerTime;
      break;
    default:
      return 0;
  }
  
  return Math.max(0, expectedRoleTime - currentRoleTime);
};

/**
 * Assign 1-2-1 positions ensuring no conflicts
 */
const assign121Positions = (fieldPlayers) => {
  // Sort candidates by role deficits
  const defenderCandidates = [...fieldPlayers].sort((a, b) => b.defenderDeficit - a.defenderDeficit);
  const midfielderCandidates = [...fieldPlayers].sort((a, b) => b.midfielderDeficit - a.midfielderDeficit);
  const attackerCandidates = [...fieldPlayers].sort((a, b) => b.attackerDeficit - a.attackerDeficit);
  
  const assignments = {};
  const usedPlayers = new Set();
  
  // Assign defender first (highest deficit)
  const defender = defenderCandidates.find(p => !usedPlayers.has(p.id));
  if (defender) {
    assignments.defender = defender;
    usedPlayers.add(defender.id);
  }
  
  // Assign attacker second (highest deficit among remaining)
  const attacker = attackerCandidates.find(p => !usedPlayers.has(p.id));
  if (attacker) {
    assignments.attacker = attacker;
    usedPlayers.add(attacker.id);
  }
  
  // Assign midfielders (highest deficits among remaining)
  const midfielders = midfielderCandidates.filter(p => !usedPlayers.has(p.id)).slice(0, 2);
  assignments.left = midfielders[0] || null;
  assignments.right = midfielders[1] || null;
  
  // Fill any missing positions with remaining players
  const remainingPlayers = fieldPlayers.filter(p => !usedPlayers.has(p.id));
  if (!assignments.left && remainingPlayers.length > 0) {
    assignments.left = remainingPlayers.shift();
  }
  if (!assignments.right && remainingPlayers.length > 0) {
    assignments.right = remainingPlayers.shift();
  }
  
  return assignments;
};


const cloneRoleGroups = (roleGroups) => {
  if (!roleGroups || typeof roleGroups !== 'object') {
    return {};
  }

  return Object.fromEntries(
    Object.entries(roleGroups).map(([groupKey, group]) => [groupKey, {
      ...group,
      queue: [...(group?.queue || [])],
      fieldPositions: [...(group?.fieldPositions || [])]
    }])
  );
};

/**
 * Generates formation recommendations for same-role substitution modes.
 *
 * For same_role_match: preserves role groups, picks sub within each group by most field time.
 * For same_role_period: rotates groups between periods (def→mid→att→def), then picks sub by time.
 *
 * @param {string} currentGoalieId - ID of the goalie for the new period
 * @param {Array} playerStats - Array of player stats from the previous period
 * @param {Object} currentRoleGroups - Current role groups object keyed by same-role group
 * @param {Object} teamConfig - Team configuration
 * @param {string} substitutionLogic - The substitution logic value
 * @param {string|null} previousGoalieId - ID of the goalie from the previous period
 * @returns {Object} { formation, roleGroups, nextToSubOutIds }
 */
const generateSameRoleFormationRecommendation = (
  currentGoalieId,
  playerStats,
  currentRoleGroups,
  teamConfig,
  substitutionLogic,
  previousGoalieId = null
) => {
  if (!currentRoleGroups) {
    return { formation: { goalie: currentGoalieId }, roleGroups: null, nextToSubOutIds: [] };
  }

  const modeDefinition = getDefinition(teamConfig, teamConfig?.formation);
  if (!modeDefinition) {
    return { formation: { goalie: currentGoalieId }, roleGroups: null, nextToSubOutIds: [] };
  }

  const groupDefinitions = getSameRoleGroupDefinitions(teamConfig);
  const groupOrder = groupDefinitions.map(group => group.key);

  // Build a stats lookup for quick access
  const statsById = {};
  if (playerStats) {
    playerStats.forEach(p => {
      statsById[p.id] = p.stats || {};
    });
  }

  // Track inactive players so we can carry their status across the period boundary.
  const inactiveIds = new Set(
    Object.entries(statsById)
      .filter(([, s]) => s?.isInactive === true)
      .map(([id]) => id)
  );

  let newRoleGroups;

  if (substitutionLogic === SUBSTITUTION_LOGIC_VALUES.SAME_ROLE_PERIOD) {
    // Rotate groups by formation-specific order (defensive -> midfield/wing -> attacking buckets).
    const rotatedGroups = cloneRoleGroups(currentRoleGroups);
    const rotationOrder = getSameRoleRotationOrder(teamConfig)
      .filter(groupKey => currentRoleGroups[groupKey]);

    if (rotationOrder.length > 1) {
      for (let i = 0; i < rotationOrder.length; i++) {
        const sourceRole = rotationOrder[i];
        const targetRole = rotationOrder[(i + 1) % rotationOrder.length];
        const sourceGroup = currentRoleGroups[sourceRole];
        const targetGroup = currentRoleGroups[targetRole];
        if (!sourceGroup) continue;

        rotatedGroups[targetRole] = {
          ...rotatedGroups[targetRole],
          queue: [...(sourceGroup.queue || [])],
          fieldPositions: [...(targetGroup?.fieldPositions || sourceGroup.fieldPositions || [])],
          substitutePosition: targetGroup?.substitutePosition ?? sourceGroup.substitutePosition ?? null
        };
      }
    }

    newRoleGroups = rotatedGroups;
  } else {
    // same_role_match: preserve groups as-is
    newRoleGroups = cloneRoleGroups(currentRoleGroups);
  }

  // Swap goalie into vacated group: if the new goalie was in a group queue,
  // replace them with the previous goalie so the old goalie takes a field role
  if (previousGoalieId && currentGoalieId !== previousGoalieId) {
    for (const role of Object.keys(newRoleGroups)) {
      const group = newRoleGroups[role];
      if (!group?.queue) continue;
      const idx = group.queue.indexOf(currentGoalieId);
      if (idx !== -1) {
        const previousGoalieInAnyGroup = Object.values(newRoleGroups).some(
          g => g.queue?.includes(previousGoalieId)
        );
        if (!previousGoalieInAnyGroup) {
          group.queue[idx] = previousGoalieId;
        }
        break;
      }
    }
  }

  const substitutePositions = modeDefinition.substitutePositions || [];

  // In same_role_period mode with a fixed role group (9-player squad), the rotation brings 3
  // players into the designated fixed-role slot while the group that received the old fixed
  // group's 2 players is left under-filled. Re-balance before the substitutePosition
  // normalisation runs: keep the 2 incoming players with the least total field time in the
  // fixed slot and move the one with the most time to the under-filled receiving group.
  if (substitutionLogic === SUBSTITUTION_LOGIC_VALUES.SAME_ROLE_PERIOD) {
    const originalFixedEntry = Object.entries(currentRoleGroups).find(
      ([, g]) => g.substitutePosition === null && g.queue?.length === 2
    );

    if (originalFixedEntry) {
      const [fixedGroupKey] = originalFixedEntry;
      const fixedGroup = newRoleGroups[fixedGroupKey];

      if (fixedGroup && fixedGroup.queue.length === 3) {
        // Sort the 3 incoming players: least total field time first. Inactive players
        // must never remain in the fixed (2-player) group because it has no substitute
        // slot — force them to surplus out into the under-filled rotating group.
        const sorted = [...fixedGroup.queue].sort((a, b) => {
          const aInactive = inactiveIds.has(a) ? 1 : 0;
          const bInactive = inactiveIds.has(b) ? 1 : 0;
          if (aInactive !== bInactive) return aInactive - bInactive;
          return (statsById[a]?.timeOnFieldSeconds || 0) - (statsById[b]?.timeOnFieldSeconds || 0);
        });
        const keepInFixed = sorted.slice(0, 2); // 2 least time (and active) → remain in fixed group
        const surplus = sorted[2];              // most time (or inactive) → joins the under-filled group

        // Find the group that received the old fixed-group's players (now has only 2 players)
        const receivingEntry = Object.entries(newRoleGroups).find(
          ([key, g]) => key !== fixedGroupKey && g.queue?.length === 2
        );

        if (receivingEntry && surplus) {
          const [receivingKey, receivingGroup] = receivingEntry;
          newRoleGroups[fixedGroupKey] = { ...fixedGroup, queue: keepInFixed };
          newRoleGroups[receivingKey] = { ...receivingGroup, queue: [...receivingGroup.queue, surplus] };
        }
      }
    }
  }

  // Role groups with queue length different from 3 must not keep substitute positions.
  for (const group of Object.values(newRoleGroups)) {
    if (group.queue && group.queue.length !== 3) {
      group.substitutePosition = null;
    }
  }

  // Re-assign available substitute positions to 3-player groups. Active-sub groups come
  // first (in formation-specific group order) so groups whose substitute is inactive
  // receive the bottom-most substitute positions and inactive players appear at the
  // bottom of the substitute list on the GameScreen.
  const groupsWithSub = Object.entries(newRoleGroups)
    .filter(([, g]) => g.queue?.length === 3)
    .sort(([roleA, groupA], [roleB, groupB]) => {
      const aHasInactive = groupA.queue.some(id => inactiveIds.has(id)) ? 1 : 0;
      const bHasInactive = groupB.queue.some(id => inactiveIds.has(id)) ? 1 : 0;
      if (aHasInactive !== bHasInactive) return aHasInactive - bHasInactive;
      const indexA = groupOrder.indexOf(roleA);
      const indexB = groupOrder.indexOf(roleB);
      const normalizedIndexA = indexA === -1 ? Number.MAX_SAFE_INTEGER : indexA;
      const normalizedIndexB = indexB === -1 ? Number.MAX_SAFE_INTEGER : indexB;
      return normalizedIndexA - normalizedIndexB;
    });

  groupsWithSub.forEach(([role], idx) => {
    newRoleGroups[role].substitutePosition = substitutePositions[idx] || null;
  });

  const formation = { goalie: currentGoalieId };
  const nextToSubOutIds = [];

  // For each role group, pick the sub (most field time) and assign positions.
  const orderedGroups = Object.entries(newRoleGroups)
    .sort(([a], [b]) => {
      const indexA = groupOrder.indexOf(a);
      const indexB = groupOrder.indexOf(b);
      const normalizedIndexA = indexA === -1 ? Number.MAX_SAFE_INTEGER : indexA;
      const normalizedIndexB = indexB === -1 ? Number.MAX_SAFE_INTEGER : indexB;
      return normalizedIndexA - normalizedIndexB;
    });

  for (const [role, group] of orderedGroups) {
    if (!group || !group.queue || group.queue.length === 0) continue;

    if (group.queue.length === 2) {
      // Fixed group in squad-size-9 same-role mode: both players stay on field.
      group.queue.forEach((playerId, i) => {
        if (group.fieldPositions?.[i]) {
          formation[group.fieldPositions[i]] = playerId;
        }
      });
      group.substitutePosition = null;
      // A 2-player fixed group has no substitute slot, so it cannot carry inactive status.
      delete group.hasInactiveSub;
      continue;
    }

    // If the group contains an inactive player, they must take the substitute slot
    // regardless of field time. Otherwise pick the player with the most field time.
    const inactiveInGroup = group.queue.find(id => inactiveIds.has(id));
    const subPlayer = inactiveInGroup
      ? inactiveInGroup
      : [...group.queue].sort((a, b) => {
          const aTime = statsById[a]?.timeOnFieldSeconds || 0;
          const bTime = statsById[b]?.timeOnFieldSeconds || 0;
          return bTime - aTime;
        })[0];

    const fieldPlayers = group.queue.filter(id => id !== subPlayer);

    // Queue order among field players: most time first (next to come off at queue[0])
    const fieldSorted = [...fieldPlayers].sort((a, b) => {
      const aTime = statsById[a]?.timeOnFieldSeconds || 0;
      const bTime = statsById[b]?.timeOnFieldSeconds || 0;
      return bTime - aTime;
    });
    group.queue = [...fieldSorted, subPlayer];

    // Refresh hasInactiveSub flag: freeze the group iff its substitute is inactive.
    if (inactiveIds.has(subPlayer)) {
      newRoleGroups[role].hasInactiveSub = true;
    } else {
      delete newRoleGroups[role].hasInactiveSub;
    }

    // Assign field positions
    if (group.fieldPositions) {
      group.fieldPositions.forEach((pos, i) => {
        formation[pos] = fieldSorted[i] || null;
      });
    }

    // Assign substitute position
    if (group.substitutePosition) {
      formation[group.substitutePosition] = subPlayer;
    }

    // Track next to sub out (first in queue = most field time among field players).
    // Frozen groups (hasInactiveSub) should not appear in the rotation suggestion.
    if (
      group.substitutePosition &&
      fieldSorted[0] &&
      !newRoleGroups[role].hasInactiveSub
    ) {
      nextToSubOutIds.push(fieldSorted[0]);
    }
  }

  // Sort by substitute position to match UI list order
  const filteredNextToSubOutIds = nextToSubOutIds.filter(Boolean);
  filteredNextToSubOutIds.sort((a, b) => {
    const aPos = Object.values(newRoleGroups).find(g => g.queue?.[0] === a)?.substitutePosition || '';
    const bPos = Object.values(newRoleGroups).find(g => g.queue?.[0] === b)?.substitutePosition || '';
    return aPos.localeCompare(bPos);
  });

  return {
    formation,
    roleGroups: newRoleGroups,
    nextToSubOutIds: filteredNextToSubOutIds
  };
};

// Export the individual formation function
export { generateIndividualFormationRecommendation, generateSameRoleFormationRecommendation };
