import { parseExternalPlayerName } from './playerUtils';

// Lowercase + strip diacritics for forgiving first-name comparison.
export const normalizeNameToken = (value) => {
  if (!value || typeof value !== 'string') return '';
  return value
    .normalize('NFD')
    .replace(/\p{Diacritic}/gu, '')
    .trim()
    .toLowerCase();
};

// First name of a SportAdmin-style name, normalized. Returns '' if unparseable.
// The single-char floor (e.g. 'A' -> '') is enforced upstream by parseExternalPlayerName.
export const getGhostFirstNameToken = (playerNameInProvider) => {
  try {
    const parsed = parseExternalPlayerName(playerNameInProvider);
    return normalizeNameToken(parsed.first_name);
  } catch {
    return '';
  }
};

// Surname of a SportAdmin-style name, preserving original casing. Returns '' when the
// name has no surname (single name) or is unparseable. parseExternalPlayerName already
// truncates to the 50-char DB limit.
export const getGhostLastName = (playerNameInProvider) => {
  try {
    return parseExternalPlayerName(playerNameInProvider).last_name || '';
  } catch {
    return '';
  }
};

// A roster player is a link candidate when on_roster and not already linked to any provider.
const isUnlinkedRosterPlayer = (player, matchedConnections) => {
  if (!player || player.on_roster !== true) return false;
  const connections = matchedConnections?.get?.(player.id);
  return !connections || connections.length === 0;
};

// Unlinked roster players whose normalized first_name equals the ghost's first-name token.
export const computeFirstNameCandidates = (playerNameInProvider, rosterPlayers, matchedConnections) => {
  const token = getGhostFirstNameToken(playerNameInProvider);
  if (!token || !Array.isArray(rosterPlayers)) return [];

  return rosterPlayers.filter(
    (player) =>
      isUnlinkedRosterPlayer(player, matchedConnections) &&
      normalizeNameToken(player.first_name) === token
  );
};

// Ghosts (connected status) that have at least one first-name candidate, paired with their candidates.
export const computeMatchableGhosts = (unmatchedExternalPlayers, rosterPlayers, matchedConnections) => {
  if (!Array.isArray(unmatchedExternalPlayers)) return [];

  return unmatchedExternalPlayers
    // Only offer the bulk flow for ghosts from a stable connection. verifying/error/retrying
    // are transient — surfacing them risks prompting matches for ghosts that may disappear.
    .filter((ghost) => ghost.connectorStatus === 'connected')
    .map((ghost) => ({
      ghost,
      candidates: computeFirstNameCandidates(ghost.playerNameInProvider, rosterPlayers, matchedConnections)
    }))
    .filter((entry) => entry.candidates.length > 0);
};
