import React from 'react';
import PropTypes from 'prop-types';

// Scrollable bordered list of labelled checkboxes. Shared by the related-members
// selector and the invite player picker so the markup stays in one place.
export function ChecklistBox({ items, selectedIds, onToggle, disabled, ariaLabel, emptyText }) {
  if (!items || items.length === 0) {
    return emptyText ? <p className="text-xs text-slate-400 italic">{emptyText}</p> : null;
  }

  return (
    <div
      role="group"
      aria-label={ariaLabel}
      className="space-y-2 max-h-48 overflow-y-auto rounded-lg border border-slate-600 bg-slate-700/50 p-2"
    >
      {items.map((item) => (
        <label
          key={item.id}
          className={`flex items-center gap-2 text-sm ${disabled ? 'opacity-50 cursor-not-allowed' : 'cursor-pointer'}`}
        >
          <input
            type="checkbox"
            checked={selectedIds.includes(item.id)}
            disabled={disabled}
            onChange={() => onToggle(item.id)}
            className="accent-sky-500"
          />
          <span className="text-slate-200">{item.label}</span>
          {item.sublabel && <span className="text-xs text-slate-400">{item.sublabel}</span>}
        </label>
      ))}
    </div>
  );
}

ChecklistBox.propTypes = {
  items: PropTypes.arrayOf(PropTypes.shape({
    id: PropTypes.string.isRequired,
    label: PropTypes.node.isRequired,
    sublabel: PropTypes.node
  })).isRequired,
  selectedIds: PropTypes.arrayOf(PropTypes.string).isRequired,
  onToggle: PropTypes.func.isRequired,
  disabled: PropTypes.bool,
  ariaLabel: PropTypes.string.isRequired,
  emptyText: PropTypes.string,
};
