import { formatPlayerName } from './formatUtils';
import { PLAYER_ROLES } from '../constants/playerConstants';
import { getPositionRole } from '../game/logic/positionUtils';

const LINEUP_ROLE_ORDER = [
  PLAYER_ROLES.ATTACKER,
  PLAYER_ROLES.MIDFIELDER,
  PLAYER_ROLES.DEFENDER,
  PLAYER_ROLES.GOALIE,
  PLAYER_ROLES.SUBSTITUTE
];

const getPositionOrderIndex = (position) => {
  const role = getPositionRole(position);
  const roleIndex = LINEUP_ROLE_ORDER.indexOf(role);
  return roleIndex === -1 ? Number.POSITIVE_INFINITY : roleIndex;
};

/**
 * Build a starting lineup array from a formation map and player list.
 * @param {Object} formation - Map of position → playerId
 * @param {Array} allPlayers - Array of player objects with id and name fields
 * @returns {Array<{position: string, name: string}>}
 */
export const buildStartingLineupData = (formation, allPlayers = []) => {
  if (!formation || typeof formation !== 'object') return [];

  const findPlayerName = (playerId) => {
    if (!playerId) return null;
    const player = allPlayers.find(p => p.id === playerId);
    return player ? formatPlayerName(player) : null;
  };

  return Object.entries(formation)
    .filter(([, playerId]) => Boolean(playerId))
    .map(([position, playerId], index) => {
      const name = findPlayerName(playerId);
      return {
        index,
        sortOrder: getPositionOrderIndex(position),
        position,
        name: name || null
      };
    })
    .sort((a, b) => {
      if (a.sortOrder !== b.sortOrder) {
        return a.sortOrder - b.sortOrder;
      }
      return a.index - b.index;
    })
    .map(({ position, name }) => ({ position, name }));
};
