import React, { useState, useEffect, useMemo, useRef, useCallback } from 'react';
import PropTypes from 'prop-types';
import { useTranslation } from 'react-i18next';
import { LogIn, UserPlus } from 'lucide-react';
import { Button } from '../shared/UI';
import { createPersistenceManager } from '../../utils/persistenceManager';
import { STORAGE_KEYS } from '../../constants/storageKeys';
import welcomeSplash from '../../assets/images/welcome-splash.jpg';

// Keep in sync with the carousel-progress animation duration in tailwind.config.js.
export const AUTO_ADVANCE_MS = 20000;
// After a manual tap/swipe, auto-advance pauses then resumes once idle.
export const RESUME_AFTER_MS = 10000;
const SWIPE_THRESHOLD_PX = 40;

const carouselPersistence = createPersistenceManager(STORAGE_KEYS.WELCOME_CAROUSEL, { lastShownIndex: null });

function prefersReducedMotion() {
  if (typeof window === 'undefined' || typeof window.matchMedia !== 'function') {
    return false;
  }
  return window.matchMedia('(prefers-reduced-motion: reduce)').matches;
}

function pickInitialIndex(count) {
  if (!count) return 0;
  const { lastShownIndex } = carouselPersistence.loadState();
  let i = Math.floor(Math.random() * count);
  if (count > 1 && i === lastShownIndex) i = (i + 1) % count;
  return i;
}

export function WelcomeScreen({ authModal }) {
  const { t } = useTranslation('welcome');

  const messages = useMemo(() => {
    const m = t('messages', { returnObjects: true });
    return Array.isArray(m) && m.length ? m : [];
  }, [t]);
  const len = messages.length;

  const reduceMotion = useMemo(() => prefersReducedMotion(), []);

  const [index, setIndex] = useState(() => pickInitialIndex(len));
  const [direction, setDirection] = useState(1);
  const [paused, setPaused] = useState(false);

  const intervalRef = useRef(null);
  const resumeRef = useRef(null);
  const dragStartX = useRef(null);

  // Persist the currently visible message (not just the initial pick) so a visit
  // that auto-advances past 6s doesn't leave a stale lastShownIndex behind.
  useEffect(() => {
    if (len) {
      carouselPersistence.saveState({ lastShownIndex: index });
    }
  }, [index, len]);

  const stopAuto = useCallback(() => {
    if (intervalRef.current) {
      clearInterval(intervalRef.current);
      intervalRef.current = null;
    }
  }, []);

  const startAuto = useCallback(() => {
    if (reduceMotion || len <= 1) return;
    stopAuto();
    intervalRef.current = setInterval(() => {
      setDirection(1);
      setIndex((i) => (i + 1) % len);
    }, AUTO_ADVANCE_MS);
  }, [len, reduceMotion, stopAuto]);

  useEffect(() => {
    startAuto();
    const resumeTimer = resumeRef;
    return () => {
      stopAuto();
      clearTimeout(resumeTimer.current);
    };
  }, [startAuto, stopAuto]);

  const goTo = useCallback((i) => {
    if (i === index) return;
    // Forward = next-in-sequence, including the last→first wrap; everything else
    // (incl. the first→last backward wrap) slides in from the left.
    const isForward = (i > index && !(index === 0 && i === len - 1)) || (index === len - 1 && i === 0);
    setDirection(isForward ? 1 : -1);
    setIndex(i);
    // Pause auto-advance on interaction, then resume once the user goes idle.
    stopAuto();
    clearTimeout(resumeRef.current);
    if (!reduceMotion && len > 1) {
      setPaused(true);
      resumeRef.current = setTimeout(() => {
        setPaused(false);
        startAuto();
      }, RESUME_AFTER_MS);
    }
  }, [index, len, reduceMotion, startAuto, stopAuto]);

  const handlePointerDown = (e) => {
    dragStartX.current = e.clientX;
    // Capture the pointer so a release outside the element still fires pointerup
    // on it (guarded: jsdom and some environments don't implement capture).
    if (typeof e.currentTarget.setPointerCapture === 'function') {
      try {
        e.currentTarget.setPointerCapture(e.pointerId);
      } catch {
        // Capture is best-effort; the recorded drag start alone is enough for swipe.
        dragStartX.current = e.clientX;
      }
    }
  };

  const handlePointerEnd = (e) => {
    if (dragStartX.current === null) return;
    const dx = e.clientX - dragStartX.current;
    dragStartX.current = null;
    if (len > 1 && Math.abs(dx) > SWIPE_THRESHOLD_PX) {
      goTo(dx < 0 ? (index + 1) % len : (index - 1 + len) % len);
    }
  };

  const handlePointerCancel = () => {
    dragStartX.current = null;
  };

  const current = messages[index] || { headline: '', subtitle: '' };
  const enterAnim = reduceMotion ? '' : (direction >= 0 ? 'animate-carousel-in-right' : 'animate-carousel-in-left');

  return (
    <main className="flex flex-col items-center text-center space-y-6 py-4 px-4 bg-slate-900 min-h-screen overflow-y-auto">
      <div
        data-testid="welcome-carousel"
        className="w-full max-w-md flex flex-col items-center space-y-4 select-none"
        onPointerDown={handlePointerDown}
        onPointerUp={handlePointerEnd}
        onPointerCancel={handlePointerCancel}
        onPointerLeave={handlePointerCancel}
        style={{ touchAction: 'pan-y' }}
      >
        <div className="space-y-3 min-h-[7.5rem] overflow-hidden">
          <div key={index} className={enterAnim}>
            <h2 className="text-2xl sm:text-3xl font-bold text-sky-400">{current.headline}</h2>
            <p className="text-slate-300 text-sm sm:text-base mt-3">{current.subtitle}</p>
          </div>
        </div>

        {len > 1 && (
          <div className="flex items-center justify-center gap-1.5 h-5">
            {messages.map((_, i) => {
              const active = i === index;
              const showProgress = active && !reduceMotion && !paused;
              return (
                <button
                  key={i}
                  type="button"
                  aria-label={t('messageIndicator', { number: i + 1 })}
                  aria-current={active ? true : undefined}
                  onClick={() => goTo(i)}
                  className="p-1.5 flex items-center justify-center"
                >
                  <span
                    className={`relative block h-1.5 rounded-full overflow-hidden transition-all duration-300 ease-out ${
                      active ? 'w-5 bg-sky-900/70' : 'w-1.5 bg-slate-600'
                    }`}
                  >
                    {active && (
                      showProgress ? (
                        <span key={index} className="absolute inset-y-0 left-0 w-0 bg-sky-400 animate-carousel-progress" />
                      ) : (
                        <span className="absolute inset-0 bg-sky-400" />
                      )
                    )}
                  </span>
                </button>
              );
            })}
          </div>
        )}

        <div className="w-full max-w-xs aspect-[5/4] rounded-2xl overflow-hidden shadow-lg">
          <img
            src={welcomeSplash}
            alt=""
            width={800}
            height={800}
            className="w-full h-full object-cover object-center pointer-events-none"
            draggable={false}
          />
        </div>
      </div>

      <div className="flex flex-col sm:flex-row gap-3 w-full max-w-xs">
        <Button
          onClick={() => authModal.openLogin()}
          variant="primary"
          size="lg"
          Icon={LogIn}
          className="flex-1"
        >
          {t('signIn')}
        </Button>
        <Button
          onClick={() => authModal.openSignup()}
          variant="secondary"
          size="lg"
          Icon={UserPlus}
          className="flex-1"
        >
          {t('signUp')}
        </Button>
      </div>
    </main>
  );
}

WelcomeScreen.propTypes = {
  authModal: PropTypes.shape({
    openLogin: PropTypes.func.isRequired,
    openSignup: PropTypes.func.isRequired
  }).isRequired
};
