import React from 'react';
import PropTypes from 'prop-types';
import { ConfirmationModal } from '../shared/UI';
import { useTranslation } from 'react-i18next';
import { formatTeamName } from '../../utils/teamUtils';

/** Switch-or-stay prompt shown when a user accepts an invite while already on another team. */
export function TeamSwitchChoiceModal({ choice, onConfirm = () => {}, onCancel = () => {}, confirming = false }) {
  const { t } = useTranslation('team');
  if (!choice) return null;
  const { newTeam, previousTeam } = choice;
  return (
    <ConfirmationModal
      isOpen
      title={t('invitationNotification.switchChoice.title')}
      message={t('invitationNotification.switchChoice.message', {
        newTeam: formatTeamName(newTeam),
        currentTeam: formatTeamName(previousTeam),
      })}
      confirmText={t('invitationNotification.switchChoice.switch', { teamName: formatTeamName(newTeam) })}
      cancelText={t('invitationNotification.switchChoice.stay', { teamName: formatTeamName(previousTeam) })}
      variant="primary"
      onConfirm={onConfirm}
      onCancel={onCancel}
      confirmDisabled={confirming}
      cancelDisabled={confirming}
    />
  );
}

const teamShape = PropTypes.shape({
  id: PropTypes.string.isRequired,
  name: PropTypes.string.isRequired,
  club: PropTypes.shape({ long_name: PropTypes.string }),
});

TeamSwitchChoiceModal.propTypes = {
  choice: PropTypes.shape({
    newTeam: teamShape.isRequired,
    previousTeam: teamShape.isRequired,
  }),
  onConfirm: PropTypes.func,
  onCancel: PropTypes.func,
  confirming: PropTypes.bool,
};
