// True when an in-progress match is bound to a team the user can no longer
// manage — deleted, deactivated, or membership removed (e.g. deleting the demo
// team via delete_team, which deactivates the team and drops the team_user row).
// Such a match can never be saved (RLS rejects every write), so it must be
// discarded rather than left to fail at period-end with a raw RLS / "No match
// ID" error. Returns false whenever the situation is ambiguous (signed out,
// teams not loaded yet, unknown match team) to avoid discarding a valid match.
export function isActiveMatchTeamOrphaned({
  user,
  teamDataResolved,
  currentMatchId,
  matchState,
  currentMatchTeamId,
  userTeams,
}) {
  if (!user) return false;
  if (!teamDataResolved) return false;

  const hasActiveMatch = Boolean(currentMatchId) && matchState !== 'finished';
  if (!hasActiveMatch) return false;

  // No recorded team → can't decide (legacy/in-memory match). Don't discard.
  if (!currentMatchTeamId) return false;

  // undefined can't arise in production (TeamContext initialises userTeams as [])
  // and teamDataResolved already gates the loading case. Treat it as empty: with
  // no teams to match against after resolution, the match team is unreachable, so
  // the match is orphaned.
  const teams = Array.isArray(userTeams) ? userTeams : [];
  const stillManageable = teams.some(
    (team) => team?.id === currentMatchTeamId && team?.active !== false
  );
  return !stillManageable;
}
