import { getLocalDateFromISO } from '../../../utils/timeUtils';

// Explicit map keeps the supported languages visible so a contributor adding a
// third locale sees exactly what to extend. Unknown codes fall back to en-US
// (the app ships only en + sv today).
const LOCALE_MAP = { en: 'en-US', sv: 'sv-SE' };

/**
 * Formats a match date responsively for the statistics screens.
 *
 * On `sm`+ screens the full local ISO date (YYYY-MM-DD) is returned so the
 * monospace digits stay column-aligned. On narrower screens a compact,
 * locale-aware "Mon D" form is returned to save horizontal space; the year is
 * dropped for current-year matches and kept otherwise to avoid ambiguity. Both
 * paths use the viewer's local timezone.
 *
 * Lives under the statistics module (rather than the generic `timeUtils`) so the
 * viewport/layout concern (`isAtLeastSm`) stays out of the pure time utilities.
 *
 * @param {string} dateString - ISO timestamp string for the match.
 * @param {Object} options
 * @param {boolean} options.isAtLeastSm - Whether the viewport is `sm`+ (>=640px).
 * @param {string} options.language - Active i18n language code (e.g. 'en', 'sv').
 * @param {Date} [options.now=new Date()] - Reference instant for the current-year
 *   check; injectable for deterministic year-boundary tests.
 * @returns {string} Formatted date string ('' for missing/invalid input).
 */
export const formatResponsiveMatchDate = (dateString, { isAtLeastSm, language, now = new Date() }) => {
  if (isAtLeastSm) {
    return getLocalDateFromISO(dateString);
  }
  // Mirror getLocalDateFromISO's fallback so both paths return '' (not the
  // literal "Invalid Date") for missing or unparseable input.
  if (!dateString) return '';
  const date = new Date(dateString);
  if (Number.isNaN(date.getTime())) return '';
  const locale = LOCALE_MAP[language] ?? 'en-US';
  const isCurrentYear = date.getFullYear() === now.getFullYear();
  return date.toLocaleDateString(locale, {
    month: 'short',
    day: 'numeric',
    ...(isCurrentYear ? {} : { year: 'numeric' })
  });
};
