/**
 * Intended-path mechanism for deep-link sign-in.
 *
 * When an unauthenticated user opens a URL that requires sign-in (e.g. /team/loans
 * shared by another user), we capture the intended path before opening the auth
 * modal and restore it after a successful sign-in.
 *
 * Stored in sessionStorage so the value survives the Google OAuth same-origin
 * redirect round-trip (provider → /auth/callback → app reload).
 */

const STORAGE_KEY = 'auth_intended_path';

const PUBLIC_PATHS = new Set(['/', '/auth/callback', '/auth/reset-password']);

const AUTH_REQUIRED_PREFIXES = [
  '/team',
  '/stats',
  '/profile',
  '/matches',
  '/tactics',
  '/plan'
];

const normalize = (path) => {
  if (typeof path !== 'string' || path.length === 0) return '';
  const base = path.split(/[?#]/, 1)[0];
  return base.replace(/\/+$/, '') || '/';
};

export const isAuthRequiredPath = (path) => {
  const normalized = normalize(path);
  if (!normalized) return false;
  if (PUBLIC_PATHS.has(normalized)) return false;
  return AUTH_REQUIRED_PREFIXES.some(
    (prefix) => normalized === prefix || normalized.startsWith(`${prefix}/`)
  );
};

export const setIntendedPath = (path) => {
  if (typeof path !== 'string' || path.length === 0) return;
  try {
    sessionStorage.setItem(STORAGE_KEY, path);
  } catch {
    // sessionStorage unavailable (SSR, privacy mode) — silently ignore
  }
};

export const getIntendedPath = () => {
  try {
    return sessionStorage.getItem(STORAGE_KEY);
  } catch {
    return null;
  }
};

export const consumeIntendedPath = () => {
  const value = getIntendedPath();
  try {
    sessionStorage.removeItem(STORAGE_KEY);
  } catch {
    // ignore
  }
  return value;
};

export const clearIntendedPath = () => {
  try {
    sessionStorage.removeItem(STORAGE_KEY);
  } catch {
    // ignore
  }
};
