import React, { useState, useEffect, useCallback } from 'react';
import { Clock } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { useTeam } from '../../contexts/TeamContext';
import { TeamAccessRequestModal } from '../team/TeamAccessRequestModal';

// Lists the user's own pending team-access requests and lets them open the
// Team Access modal (request mode) to view or cancel one. Renders nothing
// when there are no pending requests.
export function PendingTeamRequests() {
  const { t, i18n } = useTranslation('profile');
  const { getUserTeamRequests } = useTeam();
  const [pending, setPending] = useState([]);
  const [selectedTeam, setSelectedTeam] = useState(null);

  const loadRequests = useCallback(async () => {
    try {
      const requests = await getUserTeamRequests();
      // Require a joined team so a malformed row can't render or open the modal with no team.
      setPending((requests || []).filter((r) => r.status === 'pending' && r.team));
    } catch (err) {
      console.error('Failed to load pending team requests:', err);
      setPending([]);
    }
  }, [getUserTeamRequests]);

  useEffect(() => {
    loadRequests();
  }, [loadRequests]);

  // Closing the modal (incl. after a cancel) refetches so a withdrawn request drops off.
  const handleCloseModal = useCallback(() => {
    setSelectedTeam(null);
    loadRequests();
  }, [loadRequests]);

  // Deliberately render nothing while loading or when empty — no spinner: this is a
  // secondary section and most users have no pending requests, so a flash of empty UI
  // is worse than the section appearing once data arrives.
  if (pending.length === 0) {
    return null;
  }

  return (
    <div className="border-t border-slate-700 pt-4">
      <h4 className="font-medium text-slate-300 mb-3">
        {t('teamManagement.pendingRequests.title', { count: pending.length })}
      </h4>
      <div className="space-y-2">
        {pending.map((request) => {
          const team = request.team;
          const teamLabel = team?.club?.long_name
            ? `${team.club.long_name} ${team.name}`
            : team?.name;
          const roleLabel = t(`team:roleManagement.roles.${request.requested_role}`, {
            defaultValue: request.requested_role
          });
          return (
            <button
              key={request.id}
              onClick={() => setSelectedTeam(team)}
              className="w-full text-left p-3 rounded-lg border bg-slate-800 border-slate-600 hover:bg-slate-700 transition-colors"
            >
              <div className="flex items-center justify-between gap-2">
                <div className="flex-1 min-w-0">
                  <p className="font-medium text-slate-100 truncate">{teamLabel}</p>
                  <p className="text-slate-400 text-sm">
                    {t('teamManagement.pendingRequests.role', { role: roleLabel })}
                    {' • '}
                    {new Date(request.created_at).toLocaleDateString(i18n.language)}
                  </p>
                </div>
                <span className="inline-flex items-center gap-1 px-2 py-1 text-xs font-medium rounded-full bg-amber-100 text-amber-800 flex-shrink-0">
                  <Clock className="h-3 w-3" />
                  {t('teamManagement.pendingRequests.badge')}
                </span>
              </div>
            </button>
          );
        })}
      </div>

      {selectedTeam && (
        <TeamAccessRequestModal
          team={selectedTeam}
          onClose={handleCloseModal}
          onSuccess={handleCloseModal}
        />
      )}
    </div>
  );
}
