import { App } from '@capacitor/app';
import { Browser } from '@capacitor/browser';
import { isNativePlatform } from './platform';
import { RESET_PASSWORD_PATH } from './resetTokenUtils';

const SCHEME_PREFIX = 'sportwizard://';

/**
 * Parse a `sportwizard://...` deep-link URL.
 *
 * Pure function — exported for unit tests. No side effects, no Capacitor
 * imports needed to test.
 *
 * @param {string} url - Full URL string from the `appUrlOpen` event.
 * @returns {{
 *   kind: 'oauth-callback' | 'password-reset' | 'unknown',
 *   rawPath: string,
 *   code?: string,
 *   accessToken?: string,
 *   refreshToken?: string,
 *   type?: string
 * }}
 */
export function parseSportwizardUrl(url) {
  if (typeof url !== 'string' || !url.startsWith(SCHEME_PREFIX)) {
    return { kind: 'unknown', rawPath: '' };
  }

  // Strip the scheme and parse via the URL constructor with a placeholder
  // origin. Querystring + fragment parsing comes for free.
  let parsed;
  try {
    parsed = new URL(`https://x/${url.slice(SCHEME_PREFIX.length)}`);
  } catch {
    return { kind: 'unknown', rawPath: '' };
  }

  const rawPath = parsed.pathname || '/';
  const query = parsed.searchParams;
  const fragmentParams = new URLSearchParams(
    parsed.hash.startsWith('#') ? parsed.hash.slice(1) : parsed.hash
  );

  if (rawPath === '/auth/callback') {
    const code = query.get('code');
    return code
      ? { kind: 'oauth-callback', rawPath, code }
      : { kind: 'unknown', rawPath };
  }

  if (rawPath === '/auth/reset-password') {
    const code = query.get('code');
    if (code) {
      return { kind: 'password-reset', rawPath, code };
    }
    const accessToken = fragmentParams.get('access_token') || query.get('access_token');
    const refreshToken = fragmentParams.get('refresh_token') || query.get('refresh_token');
    const type = fragmentParams.get('type') || query.get('type');
    if (accessToken && refreshToken && type === 'recovery') {
      return { kind: 'password-reset', rawPath, accessToken, refreshToken, type };
    }
    return { kind: 'unknown', rawPath };
  }

  return { kind: 'unknown', rawPath };
}

function rewriteHistoryForReset(parsed) {
  if (typeof window === 'undefined' || !window.history?.replaceState) return;
  const params = new URLSearchParams();
  if (parsed.code) {
    params.set('code', parsed.code);
  } else {
    params.set('access_token', parsed.accessToken);
    params.set('refresh_token', parsed.refreshToken);
    params.set('type', parsed.type);
  }
  window.history.replaceState(null, '', `${RESET_PASSWORD_PATH}?${params.toString()}`);
}

/**
 * Register the native deep-link listener. No-op on web.
 *
 * The listener intercepts `sportwizard://auth/callback` (Google OAuth code
 * exchange) and `sportwizard://auth/reset-password` (password reset email
 * link), then routes them through the existing auth flows. Non-auth paths
 * are logged and ignored — wider URL-driven navigation is out of scope for
 * M3 (#419).
 *
 * Important: never log the full URL or any tokens — they are credentials.
 *
 * @param {{ supabase: object, authModal: { openReset: () => void, closeModal?: () => void } }} deps
 * @returns {Promise<{ remove: () => Promise<void> }>} Listener handle. The
 *   handle is a no-op cleanup on web.
 */
export async function registerNativeDeepLinkListener({ supabase, authModal }) {
  if (!isNativePlatform()) {
    return { remove: async () => {} };
  }

  const handler = async ({ url }) => {
    const parsed = parseSportwizardUrl(url);

    if (parsed.kind === 'oauth-callback') {
      try {
        await supabase.auth.exchangeCodeForSession(parsed.code);
        // On web the OAuth round-trip causes a full page reload which incidentally
        // resets the auth modal. On native there is no reload, so close it here.
        authModal?.closeModal?.();
      } catch (error) {
        // Don't log error.message — Supabase may include the code or URL.
        console.error('[nativeDeepLinks] OAuth code exchange failed');
      } finally {
        try {
          await Browser.close();
        } catch {
          // Browser may already be closed; ignore.
        }
      }
      return;
    }

    if (parsed.kind === 'password-reset') {
      rewriteHistoryForReset(parsed);
      authModal?.openReset?.();
      return;
    }

    console.debug(`[nativeDeepLinks] Ignored deep link path=${parsed.rawPath}`);
  };

  // Cold-start: Capacitor delivers the launch URL via getLaunchUrl(), not appUrlOpen.
  let launchUrl;
  try {
    const launch = await App.getLaunchUrl();
    launchUrl = launch?.url;
  } catch {
    // getLaunchUrl may throw outside a native context or on older runtimes.
  }
  if (launchUrl) {
    await handler({ url: launchUrl });
  }

  return App.addListener('appUrlOpen', handler);
}
