import { useEffect } from 'react';
import { persistCurrentMatchState } from '../services/matchStateManager';

const DEBOUNCE_MS = 500;
const SNAPSHOT_VERSION = 1;

/**
 * Persists a combined game+timer state snapshot to match.current_state on every
 * discrete change during a running match. Fire-and-forget.
 *
 * Must be called from AppContent in App.js, which has access to both
 * useGameState() and useTimers() return values.
 */
export function useMatchStatePersistence(gameState, timers, userId) {
  const {
    currentMatchId,
    matchState,
    isPeriodSetupPending,
    matchCreated,
    allPlayers,
    selectedSquadIds,
    numPeriods,
    periodDurationMinutes,
    periodGoalieIds,
    teamConfig,
    selectedFormation,
    alertMinutes,
    captainId,
    currentPeriodNumber,
    formation,
    nextPlayerToSubOut,
    nextPlayerIdToSubOut,
    rotationQueue,
    gameLog,
    opponentTeam,
    matchType,
    venueType,
    ownScore,
    opponentScore,
    trackGoalScorer,
    matchEvents,
    matchStartTime,
    goalScorers,
    timerPauseStartTime,
    totalMatchPausedDuration,
    lastSubstitutionTimestamp,
    substitutionLogic,
    fixedRoleGroup,
    roleGroups,
    nextToSubOutIds,
    hasActiveConfiguration,
  } = gameState;

  const {
    isPeriodActive,
    periodStartTime,
    lastSubstitutionTime,
    secondLastSubstitutionTime,
    pauseStartTime,
    totalPausedDuration,
  } = timers;

  useEffect(() => {
    const shouldPersist =
      currentMatchId &&
      userId &&
      (matchState === 'running' || (isPeriodSetupPending && matchCreated));

    if (!shouldPersist) return;

    const timeoutId = setTimeout(() => {
      const snapshot = {
        version: SNAPSHOT_VERSION,
        savedAt: new Date().toISOString(),
        gameState: {
          allPlayers,
          selectedSquadIds,
          numPeriods,
          periodDurationMinutes,
          periodGoalieIds,
          teamConfig,
          selectedFormation,
          alertMinutes,
          captainId,
          currentPeriodNumber,
          formation,
          nextPlayerToSubOut,
          nextPlayerIdToSubOut,
          rotationQueue,
          gameLog,
          opponentTeam,
          matchType,
          venueType,
          ownScore,
          opponentScore,
          trackGoalScorer,
          matchEvents,
          matchStartTime,
          goalScorers,
          timerPauseStartTime,
          totalMatchPausedDuration,
          currentMatchId,
          matchCreated,
          matchState,
          isPeriodSetupPending,
          hasActiveConfiguration,
          substitutionLogic,
          fixedRoleGroup,
          roleGroups,
          nextToSubOutIds,
          lastSubstitutionTimestamp,
        },
        timerState: {
          isPeriodActive,
          periodStartTime,
          lastSubstitutionTime,
          secondLastSubstitutionTime,
          pauseStartTime,
          totalPausedDuration,
        },
      };

      // Fire-and-forget — intentionally not awaited
      persistCurrentMatchState(currentMatchId, snapshot, userId);
    }, DEBOUNCE_MS);

    return () => clearTimeout(timeoutId);
  }, [
    userId,
    currentMatchId, matchState, isPeriodSetupPending, matchCreated,
    allPlayers, selectedSquadIds, numPeriods, periodDurationMinutes,
    periodGoalieIds, teamConfig, selectedFormation, alertMinutes, captainId,
    currentPeriodNumber, formation, nextPlayerToSubOut, nextPlayerIdToSubOut,
    rotationQueue, gameLog, opponentTeam, matchType, venueType, ownScore,
    opponentScore, trackGoalScorer, matchEvents, matchStartTime, goalScorers,
    timerPauseStartTime, totalMatchPausedDuration, lastSubstitutionTimestamp,
    hasActiveConfiguration, substitutionLogic, fixedRoleGroup, roleGroups,
    nextToSubOutIds,
    isPeriodActive, periodStartTime, lastSubstitutionTime,
    secondLastSubstitutionTime, pauseStartTime, totalPausedDuration,
  ]);
}
