export function TeamManagementScreen({ onNavigateBack, onNavigateTo, openToTab, openAddRosterPlayerModal, openCreateWizard, openCreateWizardNonce, openCreateWizardForceClub }) {
  const { t } = useTranslation('team');
  const { showSuccess } = useToast();
  const { user } = useAuth();
  const { 
    hasTeams, 
    hasClubs, 
    currentTeam, 
    isTeamAdmin, 
    canManageTeam,
    pendingRequestsCount,
    loading: teamLoading,
    getTeamAccessRequests,
    getPlayerRelationshipRequests,
    getTeamMembers
  } = useTeam();
  
  const { pushNavigationState, removeFromNavigationStack } = useBrowserBackIntercept();

  // Create persistence manager for tab state
  const tabPersistence = useMemo(
    () => createPersistenceManager(STORAGE_KEYS.TEAM_MANAGEMENT_ACTIVE_TAB, { tab: TAB_VIEWS.OVERVIEW }),
    []
  );

  // Track if this is the initial mount to prevent overriding persisted tab on page refresh
  const isInitialMount = useRef(true);

  const [activeTab, setActiveTab] = useUrlBackedTabState({
    persistence: tabPersistence,
    defaultTab: TAB_VIEWS.OVERVIEW,
    isValidTab: isValidTeamManagementTab,
    getTabFromPath: getTeamManagementTabFromPath,
    getPathForTab: getTeamManagementPath,
    isPathOwned: isTeamManagementPath,
    externalTab: openToTab
  });
  const [showCreateWizard, setShowCreateWizard] = useState(false);
  const [wizardForceClubSelection, setWizardForceClubSelection] = useState(false);
  const [showAccessModal, setShowAccessModal] = useState(false);
  const [showInviteModal, setShowInviteModal] = useState(false);
  const [showInviteDemoBlockedModal, setShowInviteDemoBlockedModal] = useState(false);
  const [showRoleModal, setShowRoleModal] = useState(false);
  const [teamMembers, setTeamMembers] = useState([]);


  // Role context for the centralized tab access policy.
  const tabAccessCtx = React.useMemo(
    () => makeAccessCtx(currentTeam, user),
    [currentTeam, user]
  );

  // Main team management view - define tabs early to avoid hooks order issues.
  // Visibility is driven entirely by the centralized access policy
  // (canAccessTeamManagementTab) so the component can never drift from it.
  const tabs = React.useMemo(() => {
    const orderedTabs = [
      {
        id: TAB_VIEWS.OVERVIEW,
        label: t('teamManagement.tabs.overview.label'),
        icon: Users,
        description: t('teamManagement.tabs.overview.description')
      },
      {
        id: TAB_VIEWS.ROSTER,
        label: t('teamManagement.tabs.roster.label'),
        icon: Rows4,
        description: t('teamManagement.tabs.roster.description')
      },
      {
        id: TAB_VIEWS.LOANS,
        label: t('teamManagement.tabs.loans.label'),
        icon: Repeat,
        description: t('teamManagement.tabs.loans.description')
      },
      {
        id: TAB_VIEWS.ACCESS,
        label: t('teamManagement.tabs.access.label'),
        icon: Shield,
        description: t('teamManagement.tabs.access.description'),
        badge: pendingRequestsCount > 0 ? pendingRequestsCount : null
      },
      {
        id: TAB_VIEWS.CONNECTORS,
        label: t('teamManagement.tabs.connectors.label'),
        icon: Link,
        description: t('teamManagement.tabs.connectors.description')
      },
      {
        id: TAB_VIEWS.PREFERENCES,
        label: t('teamManagement.tabs.preferences.label'),
        icon: Settings,
        description: t('teamManagement.tabs.preferences.description')
      }
    ];

    return orderedTabs.filter((tab) => canAccessTeamManagementTab(tab.id, tabAccessCtx));
  }, [tabAccessCtx, pendingRequestsCount, t]);

  // Ensure activeTab always matches a role-permitted tab. Fail-closed: a tab the
  // current role can't access (e.g. a parent deep-linking to /team/roster) falls
  // back to the first allowed tab (Overview) even on initial mount, so a forbidden
  // tab can never render its content. We still skip the initial-mount fallback
  // when the persisted/URL tab IS permitted, to preserve that selection.
  useEffect(() => {
    // Defensive guard for the tabs[0] access below. Can't fire in practice:
    // OVERVIEW only requires isAuthenticated and this screen is gated behind auth,
    // so an authenticated user always has at least the Overview tab.
    if (tabs.length === 0) return;

    const activeTabExists = tabs.some(tab => tab.id === activeTab);

    if (isInitialMount.current) {
      isInitialMount.current = false;
      if (activeTabExists) {
        return;
      }
    }

    if (!activeTabExists) {
      setActiveTab(tabs[0].id);
    }
  }, [activeTab, tabs, setActiveTab]);

  // Load team data when current team changes
  const loadTeamData = useCallback(async () => {
    if (!currentTeam) return;
    
    if (isTeamAdmin) {
      // Refresh both request slices in context so the badge and the summary
      // (which read pendingRequestsCount) reflect join + player requests.
      await Promise.all([
        getTeamAccessRequests(currentTeam.id),
        getPlayerRelationshipRequests(currentTeam.id)
      ]);
    }

    const members = await getTeamMembers(currentTeam.id);
    setTeamMembers(members);
  }, [currentTeam, isTeamAdmin, getTeamAccessRequests, getPlayerRelationshipRequests, getTeamMembers]);

  useEffect(() => {
    loadTeamData();
  }, [loadTeamData]);

  const handleCreateTeam = () => {
    setWizardForceClubSelection(false);
    setShowCreateWizard(true);
  };

  const handleWizardComplete = (result) => {
    setShowCreateWizard(false);
    // A join request submitted via the wizard isn't a new team — confirm the request and skip the reload.
    if (result?.accessRequested) {
      showSuccess(t('teamManagement.success.accessRequested'));
      return;
    }
    showSuccess(t('teamManagement.success.teamCreated'));
    loadTeamData();
  };

  const handleWizardCancel = () => {
    setShowCreateWizard(false);
  };

  // Open the wizard when an external CTA sends a fresh nonce; forceClub must ship with that nonce (demo CTA forces real-club selection).
  const lastWizardNonceRef = useRef(null);
  useEffect(() => {
    if (openCreateWizard && openCreateWizardNonce !== lastWizardNonceRef.current) {
      lastWizardNonceRef.current = openCreateWizardNonce;
      setWizardForceClubSelection(Boolean(openCreateWizardForceClub));
      setShowCreateWizard(true);
    }
  }, [openCreateWizard, openCreateWizardNonce, openCreateWizardForceClub]);

  const handleAccessModalSuccess = (message) => {
    setShowAccessModal(false);
    showSuccess(message || t('teamManagement.success.accessProcessed'));
    loadTeamData();
  };

  const handleShowRoleModal = () => {
    setShowRoleModal(true);
    // Add modal to browser back button handling
    pushNavigationState(() => {
      setShowRoleModal(false);
    });
  };

  const handleRoleModalClose = () => {
    setShowRoleModal(false);
    removeFromNavigationStack();
  };

  const handleRoleModalRefresh = async () => {
    await loadTeamData();
  };

  // Show loading state — but never while the wizard is open, or its own async
  // calls (createTeam/switch) would toggle teamLoading and unmount it mid-flow.
  if (teamLoading && !showCreateWizard) {
    return (
      <div className="space-y-6">
        <div className="flex items-center justify-between">
          <h1 className="text-2xl font-bold text-sky-300">{t('teamManagement.header.title')}</h1>
          <Button
            onClick={onNavigateBack}
            variant="secondary"
            size="sm"
          >
            {t('teamManagement.header.back')}
          </Button>
        </div>
        <div className="p-2 bg-slate-700 rounded-lg border border-slate-600">
          <LoadingSpinner size="sm" message={t('teamManagement.loading.teamInfo')} />
        </div>
      </div>
    );
  }

  // If user is not authenticated, don't show team management
  if (!user) {
    return null;
  }

  // Show create team wizard if needed
  if (showCreateWizard || (!hasClubs || (hasClubs && !hasTeams))) {
    return (
      <div className="space-y-6">
        <div className="flex items-center justify-between">
          <h1 className="text-2xl font-bold text-sky-300">{t('teamManagement.header.teamSetup')}</h1>
          <Button
            onClick={onNavigateBack}
            variant="secondary"
            size="sm"
          >
            {t('teamManagement.header.back')}
          </Button>
        </div>

        <TeamCreationWizard
          onComplete={handleWizardComplete}
          onCancel={handleWizardCancel}
          forceClubSelection={wizardForceClubSelection}
        />
      </div>
    );
  }

  if (!currentTeam) {
    return (
      <SelectTeamView
        onNavigateBack={onNavigateBack}
        onCreateTeam={handleCreateTeam}
      />
    );
  }


  const renderTabContent = () => {
    switch (activeTab) {
      case TAB_VIEWS.OVERVIEW:
        return <TeamOverview team={currentTeam} members={teamMembers} />;
      case TAB_VIEWS.ACCESS:
        return <AccessManagement
          team={currentTeam}
          pendingCount={pendingRequestsCount}
          onRefresh={loadTeamData}
          onShowModal={() => setShowAccessModal(true)}
          onShowInviteModal={() => {
            // Demo teams can't invite members — explain instead of opening the modal.
            if (currentTeam?.is_demo) {
              setShowInviteDemoBlockedModal(true);
            } else {
              setShowInviteModal(true);
            }
          }}
          onShowRoleModal={handleShowRoleModal}
        />;
      case TAB_VIEWS.ROSTER:
        return (
          <RosterManagement
            team={currentTeam}
            onRefresh={loadTeamData}
            onNavigateToConnectors={() => setActiveTab('connectors')}
            onNavigateTo={onNavigateTo}
            activeTab={activeTab}
            openAddPlayerModal={openAddRosterPlayerModal}
          />
        );
      case TAB_VIEWS.LOANS:
        return (
          <PlayerLoansTab
            currentTeam={currentTeam}
            canManageTeam={canManageTeam}
          />
        );
      case TAB_VIEWS.CONNECTORS:
        return <TeamConnectors team={currentTeam} onRefresh={loadTeamData} />;
      case TAB_VIEWS.PREFERENCES:
        return (
          <TeamPreferences
            team={currentTeam}
            onRefresh={loadTeamData}
          />
        );
      default:
        return <TeamOverview team={currentTeam} members={teamMembers} />;
    }
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-bold text-sky-300">{t('teamManagement.header.title')}</h1>
        <Button
          onClick={onNavigateBack}
          variant="secondary"
          size="sm"
        >
          {t('teamManagement.header.back')}
        </Button>
      </div>

      {/* Team Header */}
      <div className="bg-slate-700 rounded-lg border border-slate-600 overflow-hidden">
        <div className="bg-gradient-to-r from-sky-600 to-sky-700 px-6 py-4">
          <div className="flex items-center space-x-4">
            <div className="w-12 h-12 bg-sky-800 rounded-full flex items-center justify-center border-2 border-sky-400">
              <Users className="w-6 h-6 text-sky-100" />
            </div>
            <div className="flex-1">
              <h2 className="text-xl font-bold text-white flex items-center gap-2">
                {currentTeam.name}
                {currentTeam.is_demo && <DemoBadge />}
              </h2>
              <p className="text-sky-200 opacity-90">
                {currentTeam.club?.long_name || t('teamManagement.teamHeader.noClub')}
              </p>
            </div>
            <div className="text-right">
              <div className="text-sky-200 text-sm">
                {isTeamAdmin ? t('teamManagement.teamHeader.roleAdmin') : canManageTeam ? t('teamManagement.teamHeader.roleCoach') : t('teamManagement.teamHeader.roleUser')}
              </div>
              <div className="text-sky-300 text-xs">
                {teamMembers.length} {teamMembers.length !== 1 ? t('teamManagement.teamHeader.usersPlural') : t('teamManagement.teamHeader.users')}
              </div>
            </div>
          </div>
        </div>

        {/* Tab Navigation */}
        <div className="border-b border-slate-600">
          <TabBar tabs={tabs} activeTab={activeTab} onTabChange={setActiveTab} variant="scroll" />
        </div>

        {/* Tab Content */}
        <div className="p-2">
          {renderTabContent()}
        </div>
      </div>

      {/* Access Request Modal */}
      {showAccessModal && (
        <TeamAccessRequestModal
          team={currentTeam}
          onClose={() => setShowAccessModal(false)}
          onSuccess={handleAccessModalSuccess}
          isStandaloneMode={true}
        />
      )}

      {/* Team Invite Modal */}
      {showInviteModal && (
        <TeamInviteModal
          isOpen={showInviteModal}
          onClose={() => setShowInviteModal(false)}
          team={currentTeam}
        />
      )}

      {/* Demo team blocked modal — invitations aren't available for demo teams */}
      <NotificationModal
        isOpen={showInviteDemoBlockedModal}
        onClose={() => setShowInviteDemoBlockedModal(false)}
        title={t('demo.invitationsBlocked.title')}
        message={t('demo.invitationsBlocked.message')}
        buttonText={t('demo.invitationsBlocked.acknowledge')}
      />

      {/* Team Role Management Modal */}
      {showRoleModal && (
        <TeamRoleManagementModal
          isOpen={showRoleModal}
          onClose={handleRoleModalClose}
          team={currentTeam}
          members={teamMembers}
          onRefresh={handleRoleModalRefresh}
          currentUserRole={currentTeam?.userRole || 'member'}
        />
      )}
    </div>
  );
}

// Team Overview Component
function TeamOverview({ team, members }) {
  const { t } = useTranslation('team');

  return (
    <div className="space-y-6">
      <div>
        <h3 className="text-lg font-semibold text-slate-200 mb-4">{t('teamManagement.overview.title')}</h3>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-medium text-slate-300 mb-1">
              {t('teamManagement.overview.teamName')}
            </label>
            <span className="text-slate-100 text-sm font-medium">{team.name}</span>
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-300 mb-1">
              {t('teamManagement.overview.club')}
            </label>
            <div className="space-y-1">
              {team.club?.long_name && (
                <div className="text-slate-100 text-sm">
                  <span className="font-medium">{team.club.long_name}</span>
                </div>
              )}
            </div>
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-300 mb-1">
              {t('teamManagement.overview.teamCreated')}
            </label>
            <span className="text-slate-100 text-sm font-medium">
              {team.created_at ? new Date(team.created_at).toLocaleDateString(undefined, {
                year: 'numeric',
                month: 'long',
                day: 'numeric'
              }) : t('teamManagement.overview.unknown')}
            </span>
          </div>
        </div>
      </div>

      {/* Team Members */}
      <div>
        <h3 className="text-lg font-semibold text-slate-200 mb-4">{t('teamManagement.overview.teamUsers')}</h3>
        <div className="space-y-2">
          {members.sort((a, b) => {
            const nameA = a.user?.name || a.user?.email?.split('@')[0] || t('teamManagement.overview.unknownUser');
            const nameB = b.user?.name || b.user?.email?.split('@')[0] || t('teamManagement.overview.unknownUser');
            return nameA.localeCompare(nameB);
          }).map((member) => (
            <div key={member.id} className="flex items-center justify-between py-2 px-3 bg-slate-800 rounded-lg">
              <div>
                <span className="text-slate-100 font-medium">
                  {member.user?.name || member.user?.email?.split('@')[0] || t('teamManagement.overview.unknownUser')}
                </span>
                {member.user?.email && (
                  <span className="hidden sm:inline text-slate-400 text-sm ml-2">
                    ({member.user.email})
                  </span>
                )}
              </div>
              <span className={`text-xs px-2 py-1 rounded-full ${
                member.role === 'admin'
                  ? 'bg-emerald-600 text-emerald-100'
                  : member.role === 'coach'
                  ? 'bg-sky-600 text-sky-100'
                  : member.role === 'player'
                  ? 'bg-purple-600 text-purple-100'
                  : member.role === 'parent'
                  ? 'bg-orange-600 text-orange-100'
                  : 'bg-slate-600 text-slate-100'
              }`}>
                {t(`roleManagement.roles.${member.role}`, { defaultValue: member.role })}
              </span>
            </div>
          ))}
          {members.length === 0 && (
            <EmptyState title={t('teamManagement.overview.noUsers')} />
          )}
        </div>
      </div>
    </div>
  );
}

