import React from 'react';
import PropTypes from 'prop-types';
import i18next from 'i18next';

// Catches render errors from the lazy LegalScreen so a thrown public (pre-auth)
// legal route shows a recovery link instead of a blank page. Suspense handles
// the loading state; it does not catch render errors — this does.
export class LegalErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false };
  }

  static getDerivedStateFromError() {
    return { hasError: true };
  }

  componentDidCatch(error, info) {
    // Surface the error so a thrown legal route isn't swallowed silently in
    // production. Swap for an error-reporting service (e.g. Sentry) if added.
    console.error('[LegalErrorBoundary]', error, info?.componentStack);
  }

  render() {
    if (this.state.hasError) {
      return (
        <div className="min-h-screen bg-slate-900 text-slate-100 flex items-center justify-center p-6 text-center">
          <p>
            {i18next.t('common:legal.errorBoundaryBody')}{' '}
            <a href="/" className="text-sky-400 underline hover:text-sky-300">
              {i18next.t('common:legal.errorBoundaryReturn')}
            </a>
          </p>
        </div>
      );
    }
    return this.props.children;
  }
}

LegalErrorBoundary.propTypes = {
  children: PropTypes.node,
};

export default LegalErrorBoundary;
