import { useCallback, useEffect, useRef, useState } from 'react';
import { ANIMATION_DURATION } from '../game/animation/animationSupport';

const DEFAULT_LONG_PRESS_MS = 200;
const DEFAULT_ACTIVATION_DISTANCE = 10;
const EDGE_AUTOSCROLL_THRESHOLD_PX = 50;
const EDGE_AUTOSCROLL_MAX_PX_PER_FRAME = 14;
const CLICK_SUPPRESS_WINDOW_MS = 300;
// Match the SUB NOW slide so drag substitutions feel familiar. animateStateChange's
// skipAnimation branch fires the post-drop glow ANIMATION_DURATION after state-apply,
// so the cards land exactly when the pulse starts — same rhythm as a tap-driven sub.
const SWAP_FLIP_DURATION_MS = ANIMATION_DURATION;
const SNAP_BACK_DURATION_MS = 200;

const getElementPlayerId = (element) => {
  if (!element) return null;
  if (typeof element.closest !== 'function') return null;
  const node = element.closest('[data-drag-player-id]');
  return node ? node.dataset.dragPlayerId : null;
};

const getCardElement = (playerId) => {
  if (!playerId || typeof document === 'undefined') return null;
  return document.querySelector(`[data-drag-player-id="${playerId}"]`);
};

export function useGameScreenDrag({
  isDragEnabled = true,
  isPlayerEligibleAsSource,
  isPlayerEligibleAsTarget,
  resolveDropAction,
  onDrop,
  longPressMs = DEFAULT_LONG_PRESS_MS,
  activationDistance = DEFAULT_ACTIVATION_DISTANCE
}) {
  const [dragState, setDragState] = useState({
    active: false,
    sourcePlayerId: null,
    hoveredPlayerId: null,
    actionType: null,
    isEligible: false
  });
  const [ghostPosition, setGhostPosition] = useState(null);
  const [ghostSize, setGhostSize] = useState(null);
  const [ghostOffset, setGhostOffset] = useState(null);
  const [swapAnimation, setSwapAnimation] = useState(null);
  const [snapBack, setSnapBack] = useState(null);

  const sessionRef = useRef(null);
  const longPressTimerRef = useRef(null);
  const autoScrollRafRef = useRef(null);
  const lastPointerYRef = useRef(null);
  const ghostRafRef = useRef(null);
  const ghostPositionRef = useRef(null);
  const moveListenerRef = useRef(null);
  const upListenerRef = useRef(null);
  const cancelListenerRef = useRef(null);
  const keyListenerRef = useRef(null);
  const touchMoveListenerRef = useRef(null);
  const swapAnimationTimeoutRef = useRef(null);
  const snapBackTimeoutRef = useRef(null);
  const suppressClickRef = useRef({ playerId: null, until: 0 });
  const dragStateRef = useRef(dragState);
  dragStateRef.current = dragState;

  const isPlayerEligibleAsSourceRef = useRef(isPlayerEligibleAsSource);
  const isPlayerEligibleAsTargetRef = useRef(isPlayerEligibleAsTarget);
  const resolveDropActionRef = useRef(resolveDropAction);
  const onDropRef = useRef(onDrop);
  const isDragEnabledRef = useRef(isDragEnabled);
  isPlayerEligibleAsSourceRef.current = isPlayerEligibleAsSource;
  isPlayerEligibleAsTargetRef.current = isPlayerEligibleAsTarget;
  resolveDropActionRef.current = resolveDropAction;
  onDropRef.current = onDrop;
  isDragEnabledRef.current = isDragEnabled;

  const clearLongPressTimer = useCallback(() => {
    if (longPressTimerRef.current) {
      clearTimeout(longPressTimerRef.current);
      longPressTimerRef.current = null;
    }
  }, []);

  const stopAutoScroll = useCallback(() => {
    if (autoScrollRafRef.current) {
      cancelAnimationFrame(autoScrollRafRef.current);
      autoScrollRafRef.current = null;
    }
  }, []);

  const cancelGhostRaf = useCallback(() => {
    if (ghostRafRef.current) {
      cancelAnimationFrame(ghostRafRef.current);
      ghostRafRef.current = null;
    }
  }, []);

  const scheduleGhostPositionUpdate = useCallback((clientX, clientY) => {
    ghostPositionRef.current = { x: clientX, y: clientY };
    if (ghostRafRef.current) return;
    ghostRafRef.current = requestAnimationFrame(() => {
      ghostRafRef.current = null;
      if (ghostPositionRef.current) {
        setGhostPosition(ghostPositionRef.current);
      }
    });
  }, []);

  const tickAutoScroll = useCallback(() => {
    const y = lastPointerYRef.current;
    if (y == null || typeof window === 'undefined') {
      autoScrollRafRef.current = null;
      return;
    }

    const viewportHeight = window.innerHeight || 0;
    let delta = 0;

    if (y < EDGE_AUTOSCROLL_THRESHOLD_PX) {
      const proximity = Math.max(0, EDGE_AUTOSCROLL_THRESHOLD_PX - y) / EDGE_AUTOSCROLL_THRESHOLD_PX;
      delta = -Math.ceil(proximity * EDGE_AUTOSCROLL_MAX_PX_PER_FRAME);
    } else if (y > viewportHeight - EDGE_AUTOSCROLL_THRESHOLD_PX) {
      const proximity = Math.max(0, y - (viewportHeight - EDGE_AUTOSCROLL_THRESHOLD_PX)) / EDGE_AUTOSCROLL_THRESHOLD_PX;
      delta = Math.ceil(proximity * EDGE_AUTOSCROLL_MAX_PX_PER_FRAME);
    }

    if (delta !== 0) {
      const maxScroll = (document.documentElement.scrollHeight || 0) - viewportHeight;
      const currentScroll = window.scrollY || 0;
      const nextScroll = Math.max(0, Math.min(maxScroll, currentScroll + delta));
      if (nextScroll !== currentScroll) {
        window.scrollTo(0, nextScroll);
      }
      autoScrollRafRef.current = requestAnimationFrame(tickAutoScroll);
    } else {
      autoScrollRafRef.current = null;
    }
  }, []);

  const ensureAutoScrollRunning = useCallback(() => {
    if (autoScrollRafRef.current == null) {
      autoScrollRafRef.current = requestAnimationFrame(tickAutoScroll);
    }
  }, [tickAutoScroll]);

  const updateHoveredTarget = useCallback((clientX, clientY) => {
    const session = sessionRef.current;
    if (!session || !session.activated || typeof document === 'undefined') return;
    if (typeof document.elementFromPoint !== 'function') return;

    const elementAtPoint = document.elementFromPoint(clientX, clientY);
    const hoveredId = getElementPlayerId(elementAtPoint);

    if (!hoveredId || hoveredId === session.sourcePlayerId) {
      if (dragStateRef.current.hoveredPlayerId !== null || dragStateRef.current.actionType !== null) {
        setDragState((prev) => ({
          ...prev,
          hoveredPlayerId: null,
          actionType: null,
          isEligible: false
        }));
      }
      return;
    }

    const targetEligible = isPlayerEligibleAsTargetRef.current
      ? !!isPlayerEligibleAsTargetRef.current(hoveredId)
      : true;

    let actionType = null;
    let isEligible = false;
    if (targetEligible && resolveDropActionRef.current) {
      const resolved = resolveDropActionRef.current(session.sourcePlayerId, hoveredId);
      if (resolved && resolved.eligible) {
        actionType = resolved.actionType || null;
        isEligible = true;
      }
    }

    const prev = dragStateRef.current;
    if (
      prev.hoveredPlayerId === hoveredId &&
      prev.actionType === actionType &&
      prev.isEligible === isEligible
    ) {
      return;
    }

    setDragState((prevState) => ({
      ...prevState,
      hoveredPlayerId: hoveredId,
      actionType,
      isEligible
    }));
  }, []);

  const cleanupListeners = useCallback(() => {
    if (typeof window === 'undefined') return;
    if (moveListenerRef.current) {
      window.removeEventListener('pointermove', moveListenerRef.current);
      moveListenerRef.current = null;
    }
    if (upListenerRef.current) {
      window.removeEventListener('pointerup', upListenerRef.current);
      upListenerRef.current = null;
    }
    if (cancelListenerRef.current) {
      window.removeEventListener('pointercancel', cancelListenerRef.current);
      cancelListenerRef.current = null;
    }
    if (keyListenerRef.current) {
      window.removeEventListener('keydown', keyListenerRef.current);
      keyListenerRef.current = null;
    }
    if (touchMoveListenerRef.current) {
      window.removeEventListener('touchmove', touchMoveListenerRef.current);
      touchMoveListenerRef.current = null;
    }
  }, []);

  const clearGhostState = useCallback(() => {
    setGhostPosition(null);
    setGhostSize(null);
    setGhostOffset(null);
    ghostPositionRef.current = null;
  }, []);

  const resetSessionState = useCallback(() => {
    clearLongPressTimer();
    stopAutoScroll();
    cancelGhostRaf();
    cleanupListeners();
    sessionRef.current = null;
    lastPointerYRef.current = null;
    setDragState({
      active: false,
      sourcePlayerId: null,
      hoveredPlayerId: null,
      actionType: null,
      isEligible: false
    });
    if (typeof document !== 'undefined' && document.body) {
      document.body.classList.remove('game-drag-active');
    }
  }, [cancelGhostRaf, cleanupListeners, clearLongPressTimer, stopAutoScroll]);

  const markSuppressClick = useCallback((playerId) => {
    suppressClickRef.current = {
      playerId: String(playerId ?? ''),
      until: Date.now() + CLICK_SUPPRESS_WINDOW_MS
    };
  }, []);

  const shouldSuppressClick = useCallback((playerId) => {
    const { playerId: suppressed, until } = suppressClickRef.current;
    return Boolean(suppressed && suppressed === String(playerId ?? '') && Date.now() < until);
  }, []);

  const activateDrag = useCallback(() => {
    const session = sessionRef.current;
    if (!session || session.activated) return;

    const cardEl = getCardElement(session.sourcePlayerId);
    if (cardEl) {
      const rect = cardEl.getBoundingClientRect();
      session.startSize = { width: rect.width, height: rect.height };
      session.startOffset = {
        x: Math.max(0, Math.min(rect.width, session.lastX - rect.left)),
        y: Math.max(0, Math.min(rect.height, session.lastY - rect.top))
      };
      setGhostSize(session.startSize);
      setGhostOffset(session.startOffset);
    }

    session.activated = true;
    setDragState({
      active: true,
      sourcePlayerId: session.sourcePlayerId,
      hoveredPlayerId: null,
      actionType: null,
      isEligible: false
    });
    scheduleGhostPositionUpdate(session.lastX, session.lastY);

    if (session.startTarget && session.pointerId != null && typeof session.startTarget.setPointerCapture === 'function') {
      try {
        session.startTarget.setPointerCapture(session.pointerId);
      } catch (_err) {
        // Pointer capture is best-effort.
      }
    }
    if (typeof document !== 'undefined' && document.body) {
      document.body.classList.add('game-drag-active');
    }
    updateHoveredTarget(session.lastX, session.lastY);
  }, [scheduleGhostPositionUpdate, updateHoveredTarget]);

  const triggerSnapBack = useCallback((sourcePlayerId, sourceRect, ghostStart) => {
    if (!sourceRect || !ghostStart) return false;
    if (snapBackTimeoutRef.current) {
      clearTimeout(snapBackTimeoutRef.current);
      snapBackTimeoutRef.current = null;
    }
    setSnapBack({
      sourcePlayerId,
      fromX: ghostStart.x,
      fromY: ghostStart.y,
      toX: sourceRect.left,
      toY: sourceRect.top,
      width: sourceRect.width,
      height: sourceRect.height,
      durationMs: SNAP_BACK_DURATION_MS,
      startedAt: Date.now()
    });
    snapBackTimeoutRef.current = setTimeout(() => {
      snapBackTimeoutRef.current = null;
      setSnapBack(null);
    }, SNAP_BACK_DURATION_MS + 40);
    return true;
  }, []);

  const triggerSwapAnimation = useCallback((targetPlayerId, targetFromRect, sourcePlayerId, sourceFromRect) => {
    if (!targetPlayerId || !targetFromRect) return;
    if (swapAnimationTimeoutRef.current) {
      clearTimeout(swapAnimationTimeoutRef.current);
      swapAnimationTimeoutRef.current = null;
    }
    setSwapAnimation({
      targetPlayerId,
      targetFromRect,
      sourcePlayerId: sourcePlayerId || null,
      sourceFromRect: sourceFromRect || null,
      durationMs: SWAP_FLIP_DURATION_MS,
      startedAt: Date.now()
    });
    swapAnimationTimeoutRef.current = setTimeout(() => {
      swapAnimationTimeoutRef.current = null;
      setSwapAnimation(null);
    }, SWAP_FLIP_DURATION_MS + 60);
  }, []);

  const finalizeDrag = useCallback((finalEvent) => {
    const session = sessionRef.current;
    if (!session) return;

    const state = dragStateRef.current;
    const wasActivated = session.activated;
    const sourceId = session.sourcePlayerId;
    const targetId = state.hoveredPlayerId;
    const actionType = state.actionType;
    const eligible = wasActivated && state.active && state.isEligible && targetId;

    let sourceRect = null;
    let targetRect = null;
    if (wasActivated) {
      const sourceEl = getCardElement(sourceId);
      if (sourceEl) sourceRect = sourceEl.getBoundingClientRect();
      if (targetId) {
        const targetEl = getCardElement(targetId);
        if (targetEl) targetRect = targetEl.getBoundingClientRect();
      }
    }

    if (eligible && onDropRef.current) {
      try {
        onDropRef.current({ sourcePlayerId: sourceId, targetPlayerId: targetId, actionType });
      } catch (_err) {
        // Don't let handler errors poison cleanup.
      }
      markSuppressClick(sourceId);
      if (targetId && targetRect) {
        // Build the source's "from" rect from where the ghost sat at release —
        // ghostPosition is the pointer, startOffset is the touch point inside the
        // card, startSize is the card dimensions. Matches DragGhost's positioning.
        let sourceFromRect = null;
        const ghostPos = ghostPositionRef.current;
        const startOffset = session.startOffset;
        const startSize = session.startSize;
        if (ghostPos && startOffset && startSize) {
          sourceFromRect = {
            left: ghostPos.x - startOffset.x,
            top: ghostPos.y - startOffset.y,
            width: startSize.width,
            height: startSize.height
          };
        }
        triggerSwapAnimation(targetId, targetRect, sourceId, sourceFromRect);
      }
    } else if (wasActivated) {
      markSuppressClick(sourceId);
      const ghostStart = ghostPositionRef.current
        ? {
            x: ghostPositionRef.current.x - (session.startOffset?.x ?? 0),
            y: ghostPositionRef.current.y - (session.startOffset?.y ?? 0)
          }
        : null;
      triggerSnapBack(sourceId, sourceRect, ghostStart);
    }

    if (typeof document !== 'undefined' && document.body) {
      document.body.classList.remove('game-drag-active');
    }
    if (finalEvent && typeof finalEvent.preventDefault === 'function' && wasActivated && finalEvent.cancelable) {
      finalEvent.preventDefault();
    }

    resetSessionState();
    clearGhostState();
  }, [clearGhostState, markSuppressClick, resetSessionState, triggerSnapBack, triggerSwapAnimation]);

  const cancelDrag = useCallback(() => {
    resetSessionState();
    clearGhostState();
  }, [clearGhostState, resetSessionState]);

  const handlePointerDown = useCallback(
    (playerId, event) => {
      if (!isDragEnabled) return;
      if (event.pointerType === 'mouse' && event.button !== 0) return;
      if (sessionRef.current) return;

      const eligibleAsSource = isPlayerEligibleAsSourceRef.current
        ? !!isPlayerEligibleAsSourceRef.current(playerId)
        : true;
      if (!eligibleAsSource) return;

      sessionRef.current = {
        sourcePlayerId: String(playerId),
        pointerId: event.pointerId,
        startX: event.clientX,
        startY: event.clientY,
        lastX: event.clientX,
        lastY: event.clientY,
        // Use event.target (not event.currentTarget): currentTarget is set to null
        // by the DOM after the React event handler returns, so it would be unusable
        // by the time the long-press setTimeout fires and reaches activateDrag.
        startTarget: event.target instanceof Element ? event.target : null,
        startSize: null,
        startOffset: null,
        activated: false
      };
      lastPointerYRef.current = event.clientY;

      longPressTimerRef.current = setTimeout(() => {
        longPressTimerRef.current = null;
        // Re-check isDragEnabled at activation time. The flag may have flipped to
        // false during the long-press window (e.g., an animation started, the match
        // paused, or a modal opened) — activating would bypass those gates.
        if (!isDragEnabledRef.current) {
          cancelDrag();
          return;
        }
        if (sessionRef.current && !sessionRef.current.activated) {
          activateDrag();
        }
      }, longPressMs);

      const handleMove = (moveEvent) => {
        const session = sessionRef.current;
        if (!session || moveEvent.pointerId !== session.pointerId) return;

        session.lastX = moveEvent.clientX;
        session.lastY = moveEvent.clientY;
        lastPointerYRef.current = moveEvent.clientY;

        if (!session.activated) {
          const dx = Math.abs(moveEvent.clientX - session.startX);
          const dy = Math.abs(moveEvent.clientY - session.startY);
          if (Math.max(dx, dy) >= activationDistance) {
            cancelDrag();
          }
          return;
        }

        if (moveEvent.cancelable) {
          moveEvent.preventDefault();
        }

        scheduleGhostPositionUpdate(moveEvent.clientX, moveEvent.clientY);
        updateHoveredTarget(moveEvent.clientX, moveEvent.clientY);
        ensureAutoScrollRunning();
      };

      const handleUp = (endEvent) => {
        const session = sessionRef.current;
        if (!session || endEvent.pointerId !== session.pointerId) return;
        finalizeDrag(endEvent);
      };

      const handleCancel = (cancelEvent) => {
        const session = sessionRef.current;
        if (!session || cancelEvent.pointerId !== session.pointerId) return;
        cancelDrag();
      };

      const handleKey = (keyEvent) => {
        if (keyEvent.key === 'Escape') {
          cancelDrag();
        }
      };

      moveListenerRef.current = handleMove;
      upListenerRef.current = handleUp;
      cancelListenerRef.current = handleCancel;
      keyListenerRef.current = handleKey;

      if (typeof window !== 'undefined') {
        window.addEventListener('pointermove', handleMove, { passive: false });
        window.addEventListener('pointerup', handleUp, { passive: false });
        window.addEventListener('pointercancel', handleCancel, { passive: false });
        window.addEventListener('keydown', handleKey);

        // Touch sessions need a separate non-passive touchmove listener: pointer
        // events' preventDefault does NOT block the underlying touchmove (per the
        // pointer-events spec), so the browser would still scroll once drag
        // activates. We gate scroll dynamically — pass-through before activation
        // (so quick swipes scroll the page), preventDefault after (so the ghost
        // follows the finger without the page sliding underneath).
        if (event.pointerType === 'touch') {
          const handleTouchMove = (touchEvent) => {
            const session = sessionRef.current;
            if (session && session.activated && touchEvent.cancelable) {
              touchEvent.preventDefault();
            }
          };
          touchMoveListenerRef.current = handleTouchMove;
          window.addEventListener('touchmove', handleTouchMove, { passive: false });
        }
      }
    },
    [
      activateDrag,
      activationDistance,
      cancelDrag,
      ensureAutoScrollRunning,
      finalizeDrag,
      isDragEnabled,
      longPressMs,
      scheduleGhostPositionUpdate,
      updateHoveredTarget
    ]
  );

  useEffect(() => {
    return () => {
      clearLongPressTimer();
      stopAutoScroll();
      cancelGhostRaf();
      cleanupListeners();
      if (swapAnimationTimeoutRef.current) {
        clearTimeout(swapAnimationTimeoutRef.current);
        swapAnimationTimeoutRef.current = null;
      }
      if (snapBackTimeoutRef.current) {
        clearTimeout(snapBackTimeoutRef.current);
        snapBackTimeoutRef.current = null;
      }
      if (typeof document !== 'undefined' && document.body) {
        document.body.classList.remove('game-drag-active');
      }
    };
  }, [cancelGhostRaf, cleanupListeners, clearLongPressTimer, stopAutoScroll]);

  return {
    dragState,
    ghostPosition,
    ghostSize,
    ghostOffset,
    swapAnimation,
    snapBack,
    handlePointerDown,
    shouldSuppressClick
  };
}
