import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import { Button, ConfirmationModal, Select, Textarea } from '../shared/UI';
import { Alert } from '../shared/Alert';
import { Card } from '../shared/Card';
import { FormGroup } from '../shared/FormGroup';
import { ModalShell } from '../shared/ModalShell';
import { ChecklistBox } from './ChecklistBox';
import { toggleInArray } from '../../utils/relationshipUtils';
import { useTeam } from '../../contexts/TeamContext';
import { useAuth } from '../../contexts/AuthContext';
import { useBrowserBackIntercept } from '../../hooks/useBrowserBackIntercept';
import { canManageRole, isAdminRole } from '../../constants/accessPolicy';
import {
  Users,
  MessageSquare,
  Clock,
  CheckCircle,
  XCircle,
  AlertTriangle,
  UserCheck
} from 'lucide-react';

// Identify a user by the part of their email before the @ when no name is set.
const emailPrefix = (email) => email?.split('@')[0];

export function TeamAccessRequestModal({ team, onClose, onSuccess, isStandaloneMode = false }) {
  const { t } = useTranslation('team');
  const {
    requestTeamAccess,
    getTeamAccessRequests,
    getUserTeamRequests,
    approveTeamAccess,
    rejectTeamAccess,
    cancelTeamAccess,
    getPlayerRelationshipRequests,
    approvePlayerRelationship,
    rejectPlayerRelationship,
    getTeamPlayers,
    getTeamMembers,
    removeTeamMember,
    loading,
    error,
    userTeams
  } = useTeam();
  const { user } = useAuth();
  const { pushNavigationState, removeFromNavigationStack } = useBrowserBackIntercept();

  // Permissions must reflect the team being VIEWED (the `team` prop), not the
  // user's currently-active team — otherwise a manager of one team sees the
  // management UI for every team. Derive the role from this team's membership.
  const teamRole = useMemo(
    () => (userTeams || []).find((t) => t.id === team?.id)?.userRole,
    [userTeams, team]
  );
  const canManageTeam = canManageRole(teamRole);
  const isTeamAdmin = isAdminRole(teamRole);
  const isCoach = teamRole === 'coach';

  // Localize a DB role value (parent/coach/admin) for display; falls back to the
  // raw value if no translation exists.
  const roleLabel = (role) => t(`roleManagement.roles.${role}`, { defaultValue: role });

  // Identify a team member when no name is set: fall back to the email prefix
  // (matching the Overview tab), then a localized "unnamed user" label.
  const memberDisplayName = (member) =>
    member?.user?.name
    || emailPrefix(member?.user?.email)
    || t('accessRequestModal.manage.request.unnamedUser');

  const [activeTab, setActiveTab] = useState('request');
  const [requestForm, setRequestForm] = useState({
    role: 'coach',
    message: '',
    claimedPlayersNote: ''
  });
  const [pendingRequests, setPendingRequests] = useState([]);
  const [playerRequests, setPlayerRequests] = useState([]);
  const [rosterPlayers, setRosterPlayers] = useState([]);
  const [claimSelections, setClaimSelections] = useState({});
  const [userRequests, setUserRequests] = useState([]);
  const [teamMembers, setTeamMembers] = useState([]);
  const [successMessage, setSuccessMessage] = useState('');
  const [justSubmitted, setJustSubmitted] = useState(false);
  const [memberToRemove, setMemberToRemove] = useState(null);

  const loadPendingRequests = useCallback(async () => {
    if (!team) return;
    const requests = await getTeamAccessRequests(team.id);
    setPendingRequests(requests);
  }, [team, getTeamAccessRequests]);

  const loadPlayerRequests = useCallback(async () => {
    if (!team) return;
    const requests = await getPlayerRelationshipRequests(team.id);
    setPlayerRequests(requests);
  }, [team, getPlayerRelationshipRequests]);

  const loadRosterPlayers = useCallback(async () => {
    if (!team) return;
    const players = await getTeamPlayers(team.id);
    setRosterPlayers(players || []);
  }, [team, getTeamPlayers]);

  const loadUserRequests = useCallback(async () => {
    if (!team) return;
    const requests = await getUserTeamRequests();
    // Filter requests for this specific team
    const teamRequests = requests.filter(req => req.team.id === team.id);
    setUserRequests(teamRequests);
  }, [team, getUserTeamRequests]);

  const loadTeamMembers = useCallback(async () => {
    if (!team) return;
    const members = await getTeamMembers(team.id);
    setTeamMembers(members);
  }, [team, getTeamMembers]);

  // Load data when modal opens
  useEffect(() => {
    if (team) {
      if (isStandaloneMode || canManageTeam) {
        // In standalone mode or for team managers, load management data
        loadPendingRequests();
        loadPlayerRequests();
        if (isTeamAdmin) {
          loadTeamMembers();
        }
        setActiveTab('manage'); // Show management tab
      } else {
        // For external users requesting access, load their requests
        loadUserRequests();
        setActiveTab('request'); // Show request tab
      }
    }
  }, [team, canManageTeam, isTeamAdmin, isStandaloneMode, loadPendingRequests, loadPlayerRequests, loadTeamMembers, loadUserRequests]);

  // Roster is only needed to link claimed players when a join request includes a
  // free-text claim — load it lazily rather than on every manager modal open.
  useEffect(() => {
    if (pendingRequests.some((r) => r.claimed_players_note)) {
      loadRosterPlayers();
    }
  }, [pendingRequests, loadRosterPlayers]);

  const handleSubmitRequest = async () => {
    if (!team) return;

    const result = await requestTeamAccess(
      team.id,
      requestForm.role,
      requestForm.message.trim(),
      true, // Skip loading state to prevent modal closure
      requestForm.role === 'parent' ? requestForm.claimedPlayersNote.trim() : ''
    );

    if (result) {
      // Show persistent success banner
      setSuccessMessage(t('accessRequestModal.request.success.submitted'));
      setJustSubmitted(true);

      // Don't auto-close modal - let user close manually after seeing confirmation
      // onSuccess?.('Request submitted successfully');

      // Reload user requests to show the new request
      await loadUserRequests();

      // Reset form
      setRequestForm({ role: 'coach', message: '', claimedPlayersNote: '' });
    }
  };

  // After a successful submit, any dismissal means "done" → complete the flow; otherwise it's a plain cancel.
  const handleClose = useCallback(() => {
    if (justSubmitted) {
      onSuccess?.();
    } else {
      onClose?.();
    }
  }, [justSubmitted, onSuccess, onClose]);

  const clearClaimSelection = (requestId) => {
    setClaimSelections((prev) => {
      if (!(requestId in prev)) return prev;
      const next = { ...prev };
      delete next[requestId];
      return next;
    });
  };

  const handleApproveRequest = async (requestId, role) => {
    const result = await approveTeamAccess(requestId, role, claimSelections[requestId] || []);
    if (result) {
      await loadPendingRequests();
      clearClaimSelection(requestId);
      onSuccess?.(t('accessRequestModal.success.requestApproved'));
    }
  };

  const handleRejectRequest = async (requestId, notes) => {
    const result = await rejectTeamAccess(requestId, notes);
    if (result) {
      await loadPendingRequests();
      clearClaimSelection(requestId);
    }
  };

  const toggleClaimPlayer = (requestId, playerId) => {
    setClaimSelections((prev) => ({
      ...prev,
      [requestId]: toggleInArray(prev[requestId] || [], playerId)
    }));
  };

  const handleApprovePlayerRequest = async (requestId) => {
    const result = await approvePlayerRelationship(requestId);
    if (result) {
      await loadPlayerRequests();
      onSuccess?.(t('accessRequestModal.success.requestApproved'));
    }
  };

  // No boilerplate review note — parents shouldn't see a canned reason. The
  // service stores null when no note is given.
  const handleRejectPlayerRequest = async (requestId) => {
    const result = await rejectPlayerRelationship(requestId);
    if (result) {
      await loadPlayerRequests();
    }
  };

  const handleCancelRequest = async (requestId) => {
    const result = await cancelTeamAccess(requestId);
    if (result) {
      await loadUserRequests();
    }
  };


  const handleRemoveMember = (member) => {
    setMemberToRemove(member);
    pushNavigationState(() => setMemberToRemove(null), 'TeamAccessRequestModal-RemoveMember');
  };

  const handleCancelRemoveMember = () => {
    setMemberToRemove(null);
    removeFromNavigationStack();
  };

  const handleConfirmRemoveMember = async () => {
    const member = memberToRemove;
    if (!member) return;

    // Close the dialog and clear the nav-stack entry up front, before awaiting.
    // This prevents a dangling browser-back entry if the removal is slow/fails,
    // and unmounting the confirm button closes the double-submit window.
    // `removeTeamMember` never rejects — it surfaces failures via the context
    // `error` (rendered above) and returns null — so no try/catch is needed.
    setMemberToRemove(null);
    removeFromNavigationStack();

    const result = await removeTeamMember(member.id);
    // Only refresh + notify on success, matching the prior window.confirm flow's
    // fail-gracefully contract.
    if (result) {
      await loadTeamMembers();
      onSuccess?.(t('accessRequestModal.manage.members.removed', {
        name: memberDisplayName(member),
        team: team?.name || t('accessRequestModal.manage.members.unknownTeam')
      }));
    }
  };

  const hasExistingRequest = userRequests.some(req => req.status === 'pending');

  const renderRequestTab = () => (
    <div className="space-y-4">
      <div className="text-center mb-6">
        <Users className="h-8 w-8 text-emerald-400 mx-auto mb-3" />
        <h3 className="text-lg font-semibold text-sky-300">{t('accessRequestModal.request.header.title')}</h3>
        <p className="text-slate-400 text-sm mt-2">
          {t('accessRequestModal.request.header.subtitle')} <strong>{team?.club?.long_name ? `${team.club.long_name} ${team.name}` : team?.name}</strong>
        </p>
      </div>

      {successMessage ? (
        /* Show success banner when there's a success message */
        <Alert variant="success">{successMessage}</Alert>
      ) : hasExistingRequest && !justSubmitted ? (
        /* Show pending warning only if user has existing request but didn't just submit */
        <div className="p-4 bg-amber-900/20 border border-amber-600/50 rounded-lg">
          <div className="flex items-center gap-3">
            <Clock className="h-5 w-5 text-amber-600" />
            <div>
              <p className="text-amber-100 font-medium">{t('accessRequestModal.request.warnings.pendingTitle')}</p>
              <p className="text-amber-200 text-sm">
                {t('accessRequestModal.request.warnings.pendingMessage')}
              </p>
            </div>
          </div>
        </div>
      ) : !successMessage ? (
        /* Show form only if no success message */
        <>
          <FormGroup label={t('accessRequestModal.request.form.roleLabel')}>
            <Select
              value={requestForm.role}
              onChange={(value) => setRequestForm(prev => ({ ...prev, role: value }))}
              options={[
                { value: 'coach', label: t('accessRequestModal.request.form.roles.coach') },
                { value: 'parent', label: t('accessRequestModal.request.form.roles.parent') },
                { value: 'admin', label: t('accessRequestModal.request.form.roles.admin') }
              ]}
            />
            <p className="text-slate-500 text-xs mt-1">
              {t('accessRequestModal.request.form.roleHint')}
            </p>
          </FormGroup>

          <FormGroup label={t('accessRequestModal.request.form.messageLabel')}>
            <Textarea
              value={requestForm.message}
              onChange={(e) => setRequestForm(prev => ({ ...prev, message: e.target.value }))}
              placeholder={t('accessRequestModal.request.form.messagePlaceholder')}
              rows={4}
              maxLength={500}
            />
            <p className="text-slate-500 text-xs mt-1">
              {t('accessRequestModal.request.form.characterCount', { count: requestForm.message.length })}
            </p>
          </FormGroup>

          {requestForm.role === 'parent' && (
            <FormGroup label={t('accessRequestModal.request.form.claimedPlayersLabel')}>
              <Textarea
                value={requestForm.claimedPlayersNote}
                onChange={(e) => setRequestForm(prev => ({ ...prev, claimedPlayersNote: e.target.value }))}
                placeholder={t('accessRequestModal.request.form.claimedPlayersPlaceholder')}
                rows={2}
                maxLength={500}
              />
              <p className="text-slate-500 text-xs mt-1">
                {t('accessRequestModal.request.form.claimedPlayersHint')}
              </p>
            </FormGroup>
          )}

          <div className="flex justify-between">
            <Button
              onClick={onClose}
              variant="secondary"
            >
              {t('accessRequestModal.request.buttons.cancel')}
            </Button>
            <Button
              onClick={handleSubmitRequest}
              disabled={loading || !requestForm.role}
              Icon={loading ? null : MessageSquare}
            >
              {loading ? t('accessRequestModal.request.buttons.sending') : t('accessRequestModal.request.buttons.sendRequest')}
            </Button>
          </div>
        </>
      ) : null}

      {/* Show Close button after successful submission */}
      {successMessage && (
        <div className="flex justify-center mt-4">
          <Button
            onClick={handleClose}
            variant="primary"
          >
            {t('accessRequestModal.request.buttons.close')}
          </Button>
        </div>
      )}

      {/* Show user's previous requests */}
      {userRequests.length > 0 && (
        <div className="mt-6 pt-6 border-t border-slate-600">
          <h4 className="font-medium text-slate-200 mb-3">{t('accessRequestModal.request.yourRequests.title')}</h4>
          <div className="space-y-2">
            {userRequests.map((request) => (
              <div key={request.id} className="p-3">
                <div className="flex items-center justify-between">
                  <div>
                    <div className="flex items-center gap-2">
                      <span className={`inline-flex items-center px-2 py-1 text-xs font-medium rounded-full ${
                        request.status === 'pending' 
                          ? 'bg-amber-100 text-amber-800' 
                          : request.status === 'approved'
                          ? 'bg-emerald-100 text-emerald-800'
                          : 'bg-rose-100 text-rose-800'
                      }`}>
                        {request.status === 'pending' && <Clock className="h-3 w-3 mr-1" />}
                        {request.status === 'approved' && <CheckCircle className="h-3 w-3 mr-1" />}
                        {request.status === 'rejected' && <XCircle className="h-3 w-3 mr-1" />}
                        {t(`accessRequestModal.request.status.${request.status}`)}
                      </span>
                      <span className="text-sm text-slate-400">
                        {t('accessRequestModal.request.yourRequests.role', { role: roleLabel(request.requested_role) })}
                      </span>
                    </div>
                    <p className="text-xs text-slate-500 mt-1">
                      {new Date(request.created_at).toLocaleDateString()}
                    </p>
                  </div>
                  {request.status === 'pending' && (
                    <Button
                      size="sm"
                      variant="secondary"
                      onClick={() => handleCancelRequest(request.id)}
                      disabled={loading}
                    >
                      {t('accessRequestModal.request.yourRequests.cancel')}
                    </Button>
                  )}
                </div>
                {request.message && (
                  <p className="text-sm text-slate-300 mt-2 p-2 bg-slate-700 rounded">
                    "{request.message}"
                  </p>
                )}
                {request.review_notes && (
                  <p className="text-sm text-slate-400 mt-2 p-2 bg-slate-600 rounded">
                    <strong>{t('accessRequestModal.request.yourRequests.reviewLabel')}</strong> {request.review_notes}
                  </p>
                )}
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );

  const renderManageTab = () => (
    <div className="space-y-4">
      <div className="text-center mb-6">
        <UserCheck className="h-8 w-8 text-sky-400 mx-auto mb-3" />
        <h3 className="text-lg font-semibold text-sky-300">
          {t('accessRequestModal.manage.header.title')}
          {isTeamAdmin && <span className="text-xs bg-emerald-600 text-emerald-100 px-2 py-1 rounded-full ml-2">{t('accessRequestModal.manage.header.badgeAdmin')}</span>}
          {isCoach && !isTeamAdmin && <span className="text-xs bg-sky-600 text-sky-100 px-2 py-1 rounded-full ml-2">{t('accessRequestModal.manage.header.badgeCoach')}</span>}
        </h3>
        <p className="text-slate-400 text-sm mt-2">
          {t('accessRequestModal.manage.header.subtitle')} <strong>{team?.name}</strong>
          {isTeamAdmin && <span className="block text-xs mt-1">{t('accessRequestModal.manage.header.adminPrivileges')}</span>}
        </p>
      </div>

      {pendingRequests.length === 0 ? (
        <div className="text-center py-8">
          <CheckCircle className="h-12 w-12 text-slate-400 mx-auto mb-4" />
          <p className="text-slate-400">{t('accessRequestModal.manage.empty.title')}</p>
          <p className="text-slate-500 text-sm mt-2">
            {t('accessRequestModal.manage.empty.description')}
          </p>
        </div>
      ) : (
        <div className="space-y-4">
          <Card variant="subtle" padding="sm" className="mb-4">
            <p className="text-xs text-slate-400">
              {t('accessRequestModal.manage.privacyNotice')}
            </p>
          </Card>
          {pendingRequests.map((request) => (
            <div key={request.id} className="p-4">
              <div className="space-y-4">
                <div className="flex items-start justify-between">
                  <div>
                    <h4 className="font-medium text-slate-100">
                      {/* Same fallback chain as memberDisplayName, but the request shape carries
                          the email as request.user_email (not member.user.email) so it stays inline. */}
                      {request.user?.name || emailPrefix(request.user_email) || t('accessRequestModal.manage.request.unnamedUser')}
                    </h4>
                    {request.user_email && (
                      <p className="text-sm text-slate-400 mt-0.5">
                        {request.user_email}
                      </p>
                    )}
                    <p className="text-sm text-slate-400 mt-1">
                      {t('accessRequestModal.manage.request.requestedRole')} <strong>{roleLabel(request.requested_role)}</strong>
                    </p>
                    <p className="text-xs text-slate-500 mt-1">
                      {new Date(request.created_at).toLocaleDateString()} {t('accessRequestModal.manage.request.atTime')}{' '}
                      {new Date(request.created_at).toLocaleTimeString()}
                    </p>
                  </div>
                  <span className="inline-flex items-center px-2 py-1 text-xs font-medium rounded-full bg-amber-100 text-amber-800">
                    <Clock className="h-3 w-3 mr-1" />
                    {t('accessRequestModal.manage.request.statusPending')}
                  </span>
                </div>

                {request.message && (
                  <Card padding="sm">
                    <p className="text-sm text-slate-200 font-medium mb-1">{t('accessRequestModal.manage.request.messageLabel')}</p>
                    <p className="text-sm text-slate-300">"{request.message}"</p>
                  </Card>
                )}

                {request.claimed_players_note && (
                  <Card padding="sm">
                    <p className="text-sm text-slate-200 font-medium mb-1">{t('accessRequestModal.manage.request.claimedPlayersLabel')}</p>
                    <p className="text-sm text-slate-300 mb-3">"{request.claimed_players_note}"</p>
                    {rosterPlayers.length > 0 && (
                      <>
                        <p className="text-xs text-slate-400 mb-2">{t('accessRequestModal.manage.request.linkPlayersHint')}</p>
                        <ChecklistBox
                          items={rosterPlayers.map(player => ({
                            id: player.id,
                            label: player.display_name || player.first_name,
                            sublabel: player.jersey_number ? `#${player.jersey_number}` : undefined
                          }))}
                          selectedIds={claimSelections[request.id] || []}
                          onToggle={(playerId) => toggleClaimPlayer(request.id, playerId)}
                          disabled={loading}
                          ariaLabel={t('accessRequestModal.manage.request.claimedPlayersLabel')}
                        />
                      </>
                    )}
                  </Card>
                )}

                {request.user_id === user?.id ? (
                  /* Best-effort UI guard against self-approval; RLS is the real boundary
                     (user may be null mid-auth, in which case buttons show until it settles). */
                  <div className="flex justify-end pt-2 border-t border-slate-600">
                    <span className="text-xs text-slate-400 italic">
                      {t('accessRequestModal.manage.request.ownRequest')}
                    </span>
                  </div>
                ) : (
                  <div className="flex justify-end gap-2 pt-2 border-t border-slate-600">
                    <Button
                      size="sm"
                      variant="secondary"
                      onClick={() => handleRejectRequest(request.id, t('accessRequestModal.manage.buttons.rejectReason'))}
                      disabled={loading}
                      Icon={XCircle}
                    >
                      {t('accessRequestModal.manage.buttons.reject')}
                    </Button>
                    <Button
                      size="sm"
                      onClick={() => handleApproveRequest(request.id, request.requested_role)}
                      disabled={loading}
                      Icon={CheckCircle}
                    >
                      {t('accessRequestModal.manage.buttons.approve', { role: roleLabel(request.requested_role) })}
                    </Button>
                  </div>
                )}
              </div>
            </div>
          ))}
        </div>
      )}
      
      {/* Parent → player relationship requests (coach + admin) */}
      {playerRequests.length > 0 && (
        <div className="mt-8 pt-6 border-t border-slate-600">
          <h4 className="font-medium text-slate-200 mb-4 flex items-center">
            <UserCheck className="h-4 w-4 mr-2" />
            {t('accessRequestModal.manage.playerRequests.title', { count: playerRequests.length })}
          </h4>
          <div className="space-y-4">
            {playerRequests.map((request) => (
              <div key={request.id} className="p-4">
                <div className="space-y-4">
                  <div className="flex items-start justify-between">
                    <div>
                      <h5 className="font-medium text-slate-100">
                        {request.user?.name || t('accessRequestModal.manage.request.unnamedUser')}
                      </h5>
                      <p className="text-sm text-slate-400 mt-1">
                        {t('accessRequestModal.manage.playerRequests.claimsPlayer')}{' '}
                        <strong>{request.player?.display_name || request.player?.first_name}</strong>
                        {request.player?.jersey_number ? ` #${request.player.jersey_number}` : ''}
                      </p>
                      <p className="text-xs text-slate-500 mt-1">
                        {new Date(request.created_at).toLocaleDateString()}
                      </p>
                    </div>
                    <span className="inline-flex items-center px-2 py-1 text-xs font-medium rounded-full bg-amber-100 text-amber-800">
                      <Clock className="h-3 w-3 mr-1" />
                      {t('accessRequestModal.manage.request.statusPending')}
                    </span>
                  </div>

                  {request.message && (
                    <Card padding="sm">
                      <p className="text-sm text-slate-200 font-medium mb-1">{t('accessRequestModal.manage.request.messageLabel')}</p>
                      <p className="text-sm text-slate-300">"{request.message}"</p>
                    </Card>
                  )}

                  {request.user_id === user?.id ? (
                    /* Best-effort UI guard against self-approval; RLS is the real boundary. */
                    <div className="flex justify-end pt-2 border-t border-slate-600">
                      <span className="text-xs text-slate-400 italic">
                        {t('accessRequestModal.manage.request.ownRequest')}
                      </span>
                    </div>
                  ) : (
                    <div className="flex justify-end gap-2 pt-2 border-t border-slate-600">
                      <Button
                        size="sm"
                        variant="secondary"
                        onClick={() => handleRejectPlayerRequest(request.id)}
                        disabled={loading}
                        Icon={XCircle}
                      >
                        {t('accessRequestModal.manage.buttons.reject')}
                      </Button>
                      <Button
                        size="sm"
                        onClick={() => handleApprovePlayerRequest(request.id)}
                        disabled={loading}
                        Icon={CheckCircle}
                      >
                        {t('accessRequestModal.manage.playerRequests.approve')}
                      </Button>
                    </div>
                  )}
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Team Member Management - Admin Only */}
      {isTeamAdmin && (
        <div className="mt-8 pt-6 border-t border-slate-600">
          <h4 className="font-medium text-slate-200 mb-4 flex items-center">
            <Users className="h-4 w-4 mr-2" />
            {t('accessRequestModal.manage.members.title', { count: teamMembers.length })}
          </h4>
          
          {teamMembers.length === 0 ? (
            <div className="text-center py-4">
              <p className="text-slate-400">{t('accessRequestModal.manage.members.empty')}</p>
            </div>
          ) : (
            <div className="space-y-3">
              {teamMembers.map((member) => (
                <Card key={member.id} padding="sm">
                  <div className="flex items-center justify-between">
                    <div>
                      <h5 className="font-medium text-slate-100">
                        {memberDisplayName(member)}
                      </h5>
                      <div className="flex items-center gap-2 mt-1">
                        <span className={`inline-flex items-center px-2 py-1 text-xs font-medium rounded-full ${
                          member.role === 'admin' 
                            ? 'bg-emerald-100 text-emerald-800'
                            : member.role === 'coach'
                            ? 'bg-sky-100 text-sky-800'
                            : 'bg-slate-100 text-slate-800'
                        }`}>
                          {t(`roleManagement.roles.${member.role}`, { defaultValue: member.role })}
                        </span>
                        <span className="text-xs text-slate-500">
                          {t('accessRequestModal.manage.members.joined', { date: new Date(member.created_at).toLocaleDateString() })}
                        </span>
                      </div>
                    </div>
                    
                    <div className="flex items-center">
                      <Button
                        size="sm"
                        variant="danger"
                        onClick={() => handleRemoveMember(member)}
                        disabled={loading || member.role === 'admin'}
                        title={member.role === 'admin' ? t('accessRequestModal.manage.members.cannotRemoveAdmin') : t('accessRequestModal.manage.members.removeMember')}
                      >
                        {t('accessRequestModal.manage.members.remove')}
                      </Button>
                    </div>
                  </div>
                </Card>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );

  if (!team) {
    return null;
  }

  const tabs = [
    ...(canManageTeam ? [{ 
      id: 'manage', 
      label: isTeamAdmin ? t('accessRequestModal.tabs.teamManagement') : t('accessRequestModal.tabs.manageRequests'),
      count: pendingRequests.length + playerRequests.length
    }] : []),
    // Only show request tab if not in standalone mode (meaning user is not already a team member)
    ...(!isStandaloneMode ? [{ id: 'request', label: t('accessRequestModal.tabs.request'), count: null }] : [])
  ];

  return (
    <ModalShell
      title={t('accessRequestModal.header.title')}
      onClose={handleClose}
      maxWidth="2xl"
    >
          {error && (
            <Alert variant="error" icon={AlertTriangle} className="mb-4">{error}</Alert>
          )}

          {/* Tab Navigation */}
          {tabs.length > 1 && (
            <div className="flex space-x-1 bg-slate-700 p-1 rounded-lg mb-4">
              {tabs.map((tab) => (
                <button
                  key={tab.id}
                  onClick={() => setActiveTab(tab.id)}
                  className={`flex-1 flex items-center justify-center gap-2 px-3 py-2 text-sm font-medium rounded-md transition-colors ${
                    activeTab === tab.id
                      ? 'bg-slate-600 text-slate-100'
                      : 'text-slate-300 hover:text-slate-100 hover:bg-slate-600'
                  }`}
                >
                  {tab.label}
                  {tab.count !== null && tab.count > 0 && (
                    <span className="bg-amber-500 text-amber-900 text-xs px-2 py-1 rounded-full">
                      {tab.count}
                    </span>
                  )}
                </button>
              ))}
            </div>
          )}

        <div className="overflow-y-auto max-h-[calc(90vh-200px)]">
          {activeTab === 'request' && renderRequestTab()}
          {activeTab === 'manage' && renderManageTab()}
        </div>

        <ConfirmationModal
          isOpen={Boolean(memberToRemove)}
          onCancel={handleCancelRemoveMember}
          onConfirm={handleConfirmRemoveMember}
          title={t('accessRequestModal.manage.members.confirmRemoveTitle')}
          message={
            memberToRemove
              ? t('accessRequestModal.manage.members.confirmRemove', { name: memberDisplayName(memberToRemove) })
              : ''
          }
          confirmText={t('accessRequestModal.manage.members.confirmRemoveButton')}
          cancelText={t('accessRequestModal.manage.members.confirmRemoveCancel')}
        />
    </ModalShell>
  );
}
