import React, { useMemo, useCallback } from 'react';
import PropTypes from 'prop-types';
import { useTranslation } from 'react-i18next';
import { Square, Pause, Play, SquarePlay, Undo2, RefreshCcw, ArrowLeft, CalendarClock } from 'lucide-react';
import { Button, FieldPlayerModal, SubstitutePlayerModal, GoalieModal, ScoreManagerModal, ConfirmationModal, SubstituteSelectionModal } from '../shared/UI';
import GoalScorerModal from '../shared/GoalScorerModal';
import { PLAYER_ROLES, PLAYER_STATUS } from '../../constants/playerConstants';
import { TEAM_CONFIG } from '../../constants/teamConstants';
import { findPlayerById, hasActiveSubstitutes } from '../../utils/playerUtils';
import { calculateCurrentStintDuration } from '../../game/time/timeCalculator';
import { getCurrentTimestamp } from '../../utils/timeUtils';
import { calculateMatchTime } from '../../utils/gameEventLogger';
import { getExpectedOnFieldPlayerCount } from '../../game/logic/positionUtils';
import { createPersistenceManager } from '../../utils/persistenceManager';
import { formatPlayerName } from '../../utils/formatUtils';

// New modular imports
import { useGameModals } from '../../hooks/useGameModals';
import { useGameUIState } from '../../hooks/useGameUIState';
import { useTeamNameAbbreviation } from '../../hooks/useTeamNameAbbreviation';
import { FormationRenderer } from './formations';
import { DragGhost } from './formations/DragGhost';
import { getPositionDisplayName } from '../../game/ui/positionUtils';
import { getSubstitutePositions } from '../../game/logic/positionUtils';
import { createSubstitutionHandlers } from '../../game/handlers/substitutionHandlers';
import { createFieldPositionHandlers } from '../../game/handlers/fieldPositionHandlers';
import { useFieldPositionHandlers } from '../../hooks/useFieldPositionHandlers';
import { useQuickTapWithScrollDetection } from '../../hooks/useQuickTapWithScrollDetection';
import { useGameScreenDrag } from '../../hooks/useGameScreenDrag';
import { useDragFlipAnimation } from '../../hooks/useDragFlipAnimation';
import { createDragSubstitutionHandlers, resolveDragAction } from '../../game/handlers/dragSubstitutionHandlers';
import { createTimerHandlers } from '../../game/handlers/timerHandlers';
import { createScoreHandlers } from '../../game/handlers/scoreHandlers';
import { createGoalieHandlers } from '../../game/handlers/goalieHandlers';
import { sortPlayersByGoalScoringRelevance } from '../../utils/playerSortingUtils';
import { SubstitutionCountInlineControl } from './SubstitutionCountControls';
import { STORAGE_KEYS } from '../../constants/storageKeys';
import { isSameRoleMode } from '../../constants/teamConfiguration';
import { recalculateScheduledGroupsForSubstitutionCount } from '../../game/logic/gameStateLogic';

// Create persistence manager for substitution count
const substitutionCountPersistence = createPersistenceManager(STORAGE_KEYS.SUBSTITUTION_COUNT, { count: 1 });

// Animation timing constants are now imported from animationSupport

const getOrdinalSuffix = (number, t) => {
  if (number === 1) return t('period.ordinal.1st');
  if (number === 2) return t('period.ordinal.2nd');
  if (number === 3) return t('period.ordinal.3rd');
  if (number === 4) return t('period.ordinal.4th');
  return t('period.ordinal.nth', { number });
};

export function GameScreen({
  currentPeriodNumber,
  formation,
  setFormation,
  allPlayers,
  setAllPlayers,
  matchTimerSeconds,
  subTimerSeconds,
  isSubTimerPaused,
  pauseSubTimer,
  resumeSubTimer,
  formatTime,
  resetSubTimer,
  handleUndoSubstitution: handleUndoSubstitutionTimer,
  handleEndPeriod,
  handleStartPrePlanning,
  numPeriods,
  isEndingPeriod = false,
  nextPlayerToSubOut,
  nextPlayerIdToSubOut,
  selectedSquadPlayers,
  setNextPlayerToSubOut,
  setNextPlayerIdToSubOut,
  teamConfig,
  selectedFormation,
  alertMinutes,
  pushNavigationState,
  removeFromNavigationStack,
  onNavigateBack,
  ownScore,
  opponentScore,
  opponentTeam,
  addGoalScored,
  addGoalConceded,
  setScore,
  rotationQueue,
  setRotationQueue,
  matchEvents,
  goalScorers,
  matchStartTime,
  matchState,
  currentMatchId,
  handleActualMatchStart,
  periodDurationMinutes,
  trackGoalScorer = true,
  trackAssists = false,
  showLiveDeficit = false,
  getPlayerName,
  setShowNewGameModal,
  ownTeamName,
  setRoleGroups,
  setNextToSubOutIds,
  roleGroups,
  substitutionLogic,
  nextToSubOutIds,
  fixedRoleGroup = null
}) {
  // Translation hook
  const { t } = useTranslation('game');


  // Use new modular hooks
  const modalHandlers = useGameModals(pushNavigationState, removeFromNavigationStack);
  const uiState = useGameUIState();
  const { setShouldResetSubTimerOnNextSub } = uiState;
  
  // Team name management
  const resolvedOwnTeamName = ownTeamName || TEAM_CONFIG.OWN_TEAM_NAME;
  const opponentTeamName = opponentTeam || TEAM_CONFIG.DEFAULT_OPPONENT_TEAM_NAME;
  const { scoreRowRef, displayOwnTeam, displayOpponentTeam } = useTeamNameAbbreviation(
    resolvedOwnTeamName, opponentTeamName, ownScore, opponentScore
  );

  // Animation state for start button
  const [isStartAnimating, setIsStartAnimating] = React.useState(false);

  // Helper functions  
  const getPlayerNameById = React.useCallback((id) => getPlayerName(id), [getPlayerName]);
  
  // Memoize eligible players to prevent unnecessary re-renders and state resets
  const eligiblePlayers = useMemo(() => {
    const filteredPlayers = selectedSquadPlayers.filter(p => p.stats && !p.stats.isInactive);
    return sortPlayersByGoalScoringRelevance(filteredPlayers);
  }, [selectedSquadPlayers]);

  // Load substitution count from PersistenceManager, default to 1
  const [substitutionCount, setSubstitutionCount] = React.useState(() => {
    const stored = substitutionCountPersistence.loadState();
    const count = parseInt(stored.count, 10);
    return !isNaN(count) && count >= 1 ? count : 1;
  });

  const maxSubstitutionCount = React.useMemo(() => {
    // Get number of on-field outfield positions from team config (4 for 5v5, 6 for 7v7)
    const onFieldOutfieldCount = Math.max(1, getExpectedOnFieldPlayerCount(teamConfig) || 0);

    // Count active substitutes (non-inactive players not on field)
    const activeSubstitutes = allPlayers.filter(p =>
      p.stats?.currentStatus === PLAYER_STATUS.SUBSTITUTE &&
      !p.stats?.isInactive
    ).length;

    // Max is the smaller of: on-field outfield positions OR active substitutes
    return Math.max(1, Math.min(onFieldOutfieldCount, activeSubstitutes));
  }, [teamConfig, allPlayers]);

  React.useEffect(() => {
    if (substitutionCount > maxSubstitutionCount) {
      setSubstitutionCount(maxSubstitutionCount);
    }
  }, [substitutionCount, maxSubstitutionCount]);

  // Save substitution count to PersistenceManager whenever it changes
  React.useEffect(() => {
    substitutionCountPersistence.saveState({ count: substitutionCount });
  }, [substitutionCount]);

  // Recalculate scheduled role groups when substitutionCount or roleGroups change in same-role mode.
  // recalculateScheduledGroupsForSubstitutionCount returns null when no change is needed,
  // which prevents unnecessary updates and infinite loops.
  React.useEffect(() => {
    if (!isSameRoleMode(substitutionLogic) || !roleGroups) return;
    const result = recalculateScheduledGroupsForSubstitutionCount(roleGroups, substitutionCount);
    if (result === null) return;
    setRoleGroups(result.roleGroups);
    if (result.nextToSubOutIds) setNextToSubOutIds(result.nextToSubOutIds);
    if (result.nextPlayerIdToSubOut !== undefined) setNextPlayerIdToSubOut(result.nextPlayerIdToSubOut);
  }, [substitutionCount, substitutionLogic, roleGroups, setRoleGroups, setNextToSubOutIds, setNextPlayerIdToSubOut]);

  const handleSubstitutionCountChange = React.useCallback((nextValue) => {
    setSubstitutionCount(nextValue);
  }, []);

  // Helper to create game state object for pure logic functions
  const createGameState = React.useCallback(() => {
    const effectiveSubstitutionCount = uiState.substitutionCountOverride ?? substitutionCount;
    const gameState = {
      formation,
      allPlayers,
      teamConfig,
      selectedFormation,
      nextPlayerToSubOut,
      nextPlayerIdToSubOut,
      rotationQueue,
      selectedSquadPlayers,
      fieldPlayerModal: modalHandlers.modals.fieldPlayer,
      lastSubstitution: uiState.lastSubstitution,
      subTimerSeconds,
      isSubTimerPaused,
      currentPeriodNumber,
      matchTimerSeconds,
      ownScore,
      opponentScore,
      currentMatchId,
      substitutionCount: effectiveSubstitutionCount,
      substitutionOverride: uiState.substitutionOverride,
      shouldResetSubTimerOnNextSub: uiState.shouldResetSubTimerOnNextSub,
      roleGroups,
      substitutionLogic,
      fixedRoleGroup
    };

    return gameState;
  }, [
    formation,
    allPlayers,
    teamConfig,
    selectedFormation,
    nextPlayerToSubOut,
    nextPlayerIdToSubOut,
    rotationQueue,
    selectedSquadPlayers,
    modalHandlers.modals.fieldPlayer,
    uiState.lastSubstitution,
    subTimerSeconds,
    isSubTimerPaused,
    currentPeriodNumber,
    matchTimerSeconds,
    ownScore,
    opponentScore,
    currentMatchId,
    substitutionCount,
    uiState.substitutionCountOverride,
    uiState.substitutionOverride,
    uiState.shouldResetSubTimerOnNextSub,
    roleGroups,
    substitutionLogic,
    fixedRoleGroup
  ]);

  // State updaters object for handlers
  const stateUpdaters = React.useMemo(() => ({
    setFormation,
    setAllPlayers,
    setNextPlayerToSubOut,
    setNextPlayerIdToSubOut,
    setRotationQueue,
    setShouldSubstituteNow: uiState.setShouldSubstituteNow,
    setSubstitutionOverride: uiState.setSubstitutionOverride,
    clearSubstitutionOverride: uiState.clearSubstitutionOverride,
    setLastSubstitution: uiState.setLastSubstitution,
    setLastSubstitutionTimestamp: () => {}, // Legacy - not used in new architecture
    setScore, // Direct access for atomic updates
    setOwnScore: (score) => setScore(score, opponentScore),
    setOpponentScore: (score) => setScore(ownScore, score),
    addGoalScored,
    addGoalConceded,
    resetSubTimer,
    handleUndoSubstitutionTimer,
    setSubstitutionCountOverride: uiState.setSubstitutionCountOverride,
    clearSubstitutionCountOverride: uiState.clearSubstitutionCountOverride,
    setShouldResetSubTimerOnNextSub,
    setRoleGroups,
    setNextToSubOutIds
  }), [
    setFormation, setAllPlayers,
    setNextPlayerToSubOut, setNextPlayerIdToSubOut,
    setRotationQueue, uiState.setShouldSubstituteNow, uiState.setSubstitutionOverride,
    uiState.clearSubstitutionOverride, uiState.setLastSubstitution,
    setScore, ownScore, opponentScore, addGoalScored, addGoalConceded, resetSubTimer,
    handleUndoSubstitutionTimer, uiState.setSubstitutionCountOverride, uiState.clearSubstitutionCountOverride,
    setShouldResetSubTimerOnNextSub, setRoleGroups, setNextToSubOutIds
  ]);

  const getPlayerDisplayNameById = useCallback((playerId) => {
    const player = findPlayerById(allPlayers, playerId);
    return player ? formatPlayerName(player) : null;
  }, [allPlayers]);

  // Animation hooks object for handlers
  const animationHooks = React.useMemo(() => ({
    setAnimationState: uiState.setAnimationState,
    setHideNextOffIndicator: uiState.setHideNextOffIndicator,
    setRecentlySubstitutedPlayers: uiState.setRecentlySubstitutedPlayers
  }), [uiState.setAnimationState, uiState.setHideNextOffIndicator, uiState.setRecentlySubstitutedPlayers]);

  // Timer controls object for handlers
  const timerControls = React.useMemo(() => ({
    pauseSubTimer,
    resumeSubTimer
  }), [pauseSubTimer, resumeSubTimer]);

  // Create handlers using the new handler factories
  const getEffectiveSubstitutionCount = React.useCallback(
    () => uiState.substitutionCountOverride ?? substitutionCount,
    [uiState.substitutionCountOverride, substitutionCount]
  );

  const substitutionHandlers = React.useMemo(() =>
    createSubstitutionHandlers(
      createGameState,
      stateUpdaters,
      animationHooks,
      modalHandlers,
      teamConfig,
      getEffectiveSubstitutionCount,
      t
    ), [createGameState, stateUpdaters, animationHooks, modalHandlers, teamConfig, getEffectiveSubstitutionCount, t]
  );

  const fieldPositionCallbacks = React.useMemo(() =>
    createFieldPositionHandlers(
      teamConfig,
      formation,
      allPlayers,
      nextPlayerIdToSubOut,
      modalHandlers,
      selectedFormation,  // Pass selectedFormation for formation-aware position callbacks
      substitutionCount,  // Pass substitutionCount for multi-sub logic
      rotationQueue,      // Pass rotationQueue for multi-sub player detection
      nextToSubOutIds,    // Same-role mode: IDs of players next to sub out
      substitutionLogic,  // Same-role mode: substitution logic type
      roleGroups,
      fixedRoleGroup
    ), [teamConfig, formation, allPlayers, nextPlayerIdToSubOut, modalHandlers, selectedFormation, substitutionCount, rotationQueue, nextToSubOutIds, substitutionLogic, roleGroups, fixedRoleGroup]
  );

  const quickTapHandlers = useFieldPositionHandlers(fieldPositionCallbacks, teamConfig);

  const timerHandlers = React.useMemo(() =>
    createTimerHandlers(
      selectedSquadPlayers,
      stateUpdaters,
      timerControls,
      createGameState
    ), [selectedSquadPlayers, stateUpdaters, timerControls, createGameState]
  );

  const scoreHandlers = React.useMemo(() =>
    createScoreHandlers(
      stateUpdaters,
      modalHandlers,
      { shouldTrackGoalScorer: trackGoalScorer, shouldTrackAssists: trackAssists, getPlayerNameById: getPlayerDisplayNameById }
    ), [stateUpdaters, modalHandlers, trackGoalScorer, trackAssists, getPlayerDisplayNameById]
  );

  const goalieHandlerCallbacks = React.useMemo(() =>
    createGoalieHandlers(
      createGameState,
      stateUpdaters,
      animationHooks,
      modalHandlers,
      allPlayers,
      selectedSquadPlayers
    ), [createGameState, stateUpdaters, animationHooks, modalHandlers, allPlayers, selectedSquadPlayers]
  );

  const goalieEvents = useQuickTapWithScrollDetection(goalieHandlerCallbacks.goalieCallback);
  const scoreEvents = useQuickTapWithScrollDetection(scoreHandlers.scoreCallback);
  
  const goalieHandlers = React.useMemo(() => ({
    ...goalieHandlerCallbacks,
    goalieEvents
  }), [goalieHandlerCallbacks, goalieEvents]);

  const dragSubstitutionHandlers = React.useMemo(() =>
    createDragSubstitutionHandlers({
      gameStateFactory: createGameState,
      substitutionHandlers,
      stateUpdaters,
      animationHooks
    }),
    [createGameState, substitutionHandlers, stateUpdaters, animationHooks]
  );

  const isDragEnabled = matchState === 'running'
    && (uiState.animationState?.phase === undefined || uiState.animationState.phase === 'idle')
    && (!uiState.recentlySubstitutedPlayers || uiState.recentlySubstitutedPlayers.size === 0);

  const allPlayersRef = React.useRef(allPlayers);
  allPlayersRef.current = allPlayers;

  const isPlayerEligible = React.useCallback((playerId) => {
    const player = findPlayerById(allPlayersRef.current, playerId);
    if (!player) return false;
    return !player.stats?.isInactive;
  }, []);

  const resolveDropAction = React.useCallback((sourceId, targetId) => {
    const source = findPlayerById(allPlayersRef.current, sourceId);
    const target = findPlayerById(allPlayersRef.current, targetId);
    return resolveDragAction(source, target);
  }, []);

  const handleDragDrop = React.useCallback(({ sourcePlayerId, targetPlayerId }) => {
    if (!dragSubstitutionHandlers?.handleDragDrop) return;
    dragSubstitutionHandlers.handleDragDrop({ sourcePlayerId, targetPlayerId });
  }, [dragSubstitutionHandlers]);

  const {
    dragState,
    ghostPosition,
    ghostSize,
    ghostOffset,
    swapAnimation,
    snapBack,
    handlePointerDown: handleDragPointerDown,
    shouldSuppressClick
  } = useGameScreenDrag({
    isDragEnabled,
    isPlayerEligibleAsSource: isPlayerEligible,
    isPlayerEligibleAsTarget: isPlayerEligible,
    resolveDropAction,
    onDrop: handleDragDrop
  });

  // Drive the post-drop FLIP from one place. Running it inside IndividualFormation
  // fires it once per rendered section (field + substitutes), and the second
  // subscriber reads the first's in-progress transition start as the "current"
  // position via getBoundingClientRect, collapsing the source's translate to zero.
  useDragFlipAnimation(swapAnimation);

  const dragProps = React.useMemo(() => ({
    dragState,
    ghostPosition,
    ghostSize,
    ghostOffset,
    swapAnimation,
    snapBack,
    handlePointerDown: handleDragPointerDown,
    shouldSuppressClick
  }), [dragState, ghostPosition, ghostSize, ghostOffset, swapAnimation, snapBack, handleDragPointerDown, shouldSuppressClick]);

  const resolveGhostPositionLabel = React.useCallback((position, player) => {
    const subPositions = getSubstitutePositions(teamConfig);
    return getPositionDisplayName(position, player, teamConfig, subPositions, t);
  }, [teamConfig, t]);

  // Check if SUB NOW button should be enabled (at least one active substitute)
  const canSubstitute = React.useMemo(() => {
    return hasActiveSubstitutes(allPlayers, teamConfig);
  }, [allPlayers, teamConfig]);

  const substitutionButtonLabel = React.useMemo(() => {
    if (substitutionCount === 1) {
      return t('substitution.buttonSingle');
    }
    return t('substitution.buttonMultiple', { count: substitutionCount });
  }, [substitutionCount, t]);

  // Function to get player time stats
  const getPlayerTimeStats = React.useCallback((playerId) => {
    const player = findPlayerById(allPlayers, playerId);
    if (!player) {
      return { totalOutfieldTime: 0, attackDefenderDiff: 0 };
    }
    
    const stats = player.stats;
    
    // When timer is paused, only use the stored stats without calculating current stint
    if (isSubTimerPaused) {
      const totalOutfieldTime = stats.timeOnFieldSeconds || 0;
      const attackDefenderDiff = (stats.timeAsAttackerSeconds || 0) - (stats.timeAsDefenderSeconds || 0);
      
      return { totalOutfieldTime, attackDefenderDiff };
    }
    
    // Calculate current stint time using time module
    let currentStintTime = 0;
    if (stats.currentStatus === PLAYER_STATUS.ON_FIELD) {
      currentStintTime = calculateCurrentStintDuration(stats.lastStintStartTimeEpoch, getCurrentTimestamp());
    }
    
    // Total outfield time includes completed time plus current stint if on field
    const totalOutfieldTime = (stats.timeOnFieldSeconds || 0) + currentStintTime;
    
    // Calculate attacker-defender difference with current stint
    let attackerTime = stats.timeAsAttackerSeconds || 0;
    let defenderTime = stats.timeAsDefenderSeconds || 0;
    
    if (stats.currentStatus === PLAYER_STATUS.ON_FIELD && stats.currentRole) {
      if (stats.currentRole === PLAYER_ROLES.ATTACKER) {  // Use constant
        attackerTime += currentStintTime;
      } else if (stats.currentRole === PLAYER_ROLES.DEFENDER) {  // Use constant
        defenderTime += currentStintTime;
      }
      // Note: Midfielder time is intentionally not added to attacker-defender difference
      // as per user requirements - midfielders should not affect the balance
    }
    
    const attackDefenderDiff = attackerTime - defenderTime;
    
    return { totalOutfieldTime, attackDefenderDiff };
  }, [allPlayers, isSubTimerPaused]);

  // Handle substitution automation when shouldSubstituteNow is set
  React.useEffect(() => {
    if (uiState.shouldSubstituteNow) {
      uiState.setShouldSubstituteNow(false);
      substitutionHandlers.handleSubstitutionWithHighlight();
    }
  }, [uiState.shouldSubstituteNow, uiState.setShouldSubstituteNow, substitutionHandlers, uiState]);

  const handleRegularSubstitutionClick = React.useCallback(() => {
    setShouldResetSubTimerOnNextSub(true);
    substitutionHandlers.handleSubstitutionWithHighlight();
  }, [setShouldResetSubTimerOnNextSub, substitutionHandlers]);
  // Handle undo substitution using handler pattern
  const handleUndoSubstitutionClick = () => {
    if (uiState.lastSubstitution) {
      substitutionHandlers.handleUndo(uiState.lastSubstitution);
      // Clear the last substitution after handling
      uiState.clearLastSubstitution();
    }
  };

  // Handle animated match start with 2-second transition
  const handleAnimatedMatchStart = () => {
    if (isStartAnimating) return; // Prevent multiple clicks during animation
    
    // Start match immediately - timers begin counting
    handleActualMatchStart();
    
    // Start visual animation
    setIsStartAnimating(true);
    
    // After animation completes, clean up animation state
    setTimeout(() => {
      setIsStartAnimating(false);
    }, 2000);
  };

  // Handle back navigation to setup screen - useCallback to prevent re-registration on timer re-renders
  const handleBackToSetup = React.useCallback(() => {
    if (isStartAnimating) return;
    onNavigateBack();
  }, [isStartAnimating, onNavigateBack]);

  // Handle back navigation during running match - show match abandonment warning
  const handleMatchAbandonmentWarning = React.useCallback(() => {
    // Use the existing "Start a new game?" modal from App.js
    setShowNewGameModal(true);
    
    // Register the modal close handler with browser back system
    if (pushNavigationState) {
      pushNavigationState(() => {
        setShowNewGameModal(false);
      }, 'GameScreen-CloseAbandonmentModal');
    }
  }, [setShowNewGameModal, pushNavigationState]);

  // Set up browser back button interception for both pending and running matches
  React.useEffect(() => {
    if (matchState === 'pending' && pushNavigationState) {
      pushNavigationState(handleBackToSetup, 'GameScreen-BackToSetup');
      
      // Clean up navigation state when component unmounts or match state changes
      return () => {
        if (removeFromNavigationStack) {
          removeFromNavigationStack();
        }
      };
    } else if (matchState === 'running' && pushNavigationState) {
      pushNavigationState(handleMatchAbandonmentWarning, 'GameScreen-MatchAbandonment');
      
      // Clean up navigation state when component unmounts or match state changes
      return () => {
        if (removeFromNavigationStack) {
          removeFromNavigationStack();
        }
      };
    }
  }, [matchState, pushNavigationState, removeFromNavigationStack, handleBackToSetup, handleMatchAbandonmentWarning]);

  // Calculate display values for timers - show initial values when match is pending or during animation
  const displayMatchTimerSeconds = (matchState === 'pending' || isStartAnimating) 
    ? periodDurationMinutes * 60 
    : matchTimerSeconds;
  const displaySubTimerSeconds = (matchState === 'pending' || isStartAnimating)
    ? 0
    : subTimerSeconds;

  // Whether the goal-scorer modal is currently on its assist-selection step.
  const isAssistStep = modalHandlers.modals.goalScorer.selectionType === 'assist';

  return (
    <div className="relative space-y-4">
      {/* Start Match Overlay - shown when match is pending or during animation */}
      {(matchState === 'pending' || isStartAnimating) && (
        <div className={`absolute inset-0 z-50 flex items-center justify-center p-8 transition-opacity duration-[2000ms] ${isStartAnimating ? 'opacity-0' : 'opacity-100'}`}>
          {/* Subtle Glass effect backdrop - less blurry so GameScreen is visible */}
          <div className={`absolute inset-0 bg-black transition-all duration-[2000ms] ${isStartAnimating ? 'bg-opacity-0 backdrop-blur-none' : 'bg-opacity-30 backdrop-blur-sm'}`} />
          <div className={`absolute inset-0 bg-gradient-to-br from-sky-900/10 to-slate-900/15 transition-opacity duration-[2000ms] ${isStartAnimating ? 'opacity-0' : 'opacity-100'}`} />
          
          {/* Cool Clickable Icon */}
          <div className={`relative z-10 text-center transition-opacity duration-[2000ms] ${isStartAnimating ? 'opacity-0' : 'opacity-100'}`}>
            {/* Main Clickable Icon */}
            <div
              onClick={handleAnimatedMatchStart}
              className={`group relative inline-block select-none transition-opacity duration-[2000ms] ${isStartAnimating ? 'cursor-default opacity-0' : 'cursor-pointer opacity-100'}`}
            >
              {/* Multi-layer Glow Effects */}
              <div className="absolute inset-0 animate-pulse">
                <div className="absolute inset-0 bg-sky-400 rounded-full blur-3xl opacity-20 group-hover:opacity-40 transition-opacity duration-500" />
                <div className="absolute inset-0 bg-sky-300 rounded-full blur-2xl opacity-30 group-hover:opacity-60 transition-opacity duration-300" />
                <div className="absolute inset-0 bg-white rounded-full blur-xl opacity-10 group-hover:opacity-30 transition-opacity duration-200" />
              </div>
              
              {/* Icon with Effects */}
              <SquarePlay 
                size={160} 
                className="relative text-sky-400 hover:text-sky-300 active:text-sky-500 
                          drop-shadow-2xl 
                          transform group-hover:scale-110 group-active:scale-95 
                          transition-all duration-300 ease-out
                          filter group-hover:brightness-110 group-active:brightness-90
                          group-hover:drop-shadow-[0_0_30px_rgba(56,189,248,0.8)]
                          group-active:drop-shadow-[0_0_50px_rgba(56,189,248,1)]" 
              />
              
              {/* Ripple Effect on Click */}
              <div className={`absolute inset-0 rounded-full transition-opacity ${isStartAnimating ? 'opacity-100 animate-ping duration-[2000ms]' : 'opacity-0 group-active:opacity-100 group-active:animate-ping duration-75'} bg-sky-400/20`} />
              {/* Extended ripple effects during animation */}
              {isStartAnimating && (
                <>
                  <div className="absolute inset-0 rounded-full opacity-60 animate-ping bg-sky-300/15 animation-delay-300" style={{animationDuration: '2000ms'}} />
                  <div className="absolute inset-0 rounded-full opacity-40 animate-ping bg-sky-200/10 animation-delay-600" style={{animationDuration: '2000ms'}} />
                </>
              )}
            </div>
            
            {/* Descriptive Text */}
            <div className={`mt-8 space-y-2 transition-opacity duration-[2000ms] ${isStartAnimating ? 'opacity-0' : 'opacity-100'}`}>
              <p className="text-3xl font-bold text-white drop-shadow-lg tracking-wide">
                {currentPeriodNumber === 1 ? t('startScreen.startMatch') : t('startScreen.startPeriod', { ordinal: getOrdinalSuffix(currentPeriodNumber, t) })}
              </p>
              <p className="text-center text-sky-100/70 text-lg font-medium tracking-wide drop-shadow-sm">
                {t('startScreen.instructions')}
              </p>
            </div>

            {/* Back to Setup Button */}
            <div className={`mt-6 transition-opacity duration-[2000ms] ${isStartAnimating ? 'opacity-0 pointer-events-none' : 'opacity-100'}`}>
              <div
                onClick={handleBackToSetup}
                className="group relative inline-flex items-center justify-center space-x-2 px-4 py-2 cursor-pointer select-none
                          text-sky-100/60 hover:text-sky-100/90
                          bg-white/5 hover:bg-white/10 rounded-md
                          transform hover:scale-105 active:scale-95
                          transition-all duration-200 ease-out
                          drop-shadow-sm hover:drop-shadow-md"
              >
                <ArrowLeft className="h-5 w-5" />
                <span className="text-sm font-medium tracking-wide">{t('startScreen.backToSetup')}</span>
              </div>
            </div>
          </div>
        </div>
      )}

      <h2 className="text-xl font-semibold text-sky-300 text-center">{t('period.label', { number: currentPeriodNumber })}</h2>



      {/* Timers */}
      <div className="grid grid-cols-2 gap-4 text-center">
        <div className="p-2 bg-slate-700 rounded-lg">
          <p className="text-xs text-sky-200 mb-0.5">{t('timers.matchClock')}</p>
          <p className={`text-2xl font-mono ${displayMatchTimerSeconds < 0 ? 'text-red-400' : 'text-sky-400'}`}>
            {displayMatchTimerSeconds < 0 ? '+' : ''}{formatTime(Math.abs(displayMatchTimerSeconds))}
          </p>
        </div>
        <div className="p-2 bg-slate-700 rounded-lg relative">
          <p className="text-xs text-sky-200 mb-0.5">{t('timers.substitutionTimer')}</p>
          <div className="relative flex items-center justify-center">
            <p className={`text-2xl font-mono ${alertMinutes > 0 && displaySubTimerSeconds >= alertMinutes * 60 ? 'text-red-400' : 'text-emerald-400'}`}>
              {formatTime(displaySubTimerSeconds)}
            </p>
            <button
              onClick={isSubTimerPaused ? timerHandlers.handleResumeTimer : timerHandlers.handlePauseTimer}
              className="absolute right-0 p-1 hover:bg-slate-600 rounded-full transition-colors duration-150 flex-shrink-0"
              title={isSubTimerPaused ? t('timers.resumeTooltip') : t('timers.pauseTooltip')}
            >
              {isSubTimerPaused ? <Play className="h-4 w-4" /> : <Pause className="h-4 w-4" />}
            </button>
          </div>
        </div>
      </div>

      {/* Score Display */}
      <div className="p-2 bg-slate-700 rounded-lg text-center">
        <div ref={scoreRowRef} className="flex items-center justify-center space-x-2.5">
          <button
            onClick={() => scoreHandlers.handleAddGoalScored(createGameState())}
            className="flex-1 px-3 py-2 bg-sky-600 hover:bg-sky-500 rounded-md text-white font-semibold transition-colors"
          >
            {displayOwnTeam}
          </button>
          <div 
            {...scoreEvents}
            className="text-2xl font-mono font-bold text-sky-200 cursor-pointer select-none px-1.5 py-2 rounded-md hover:bg-slate-600 transition-colors whitespace-nowrap flex-shrink-0"
          >
            {ownScore} - {opponentScore}
          </div>
          <button
            onClick={() => scoreHandlers.handleAddGoalConceded(createGameState())}
            className="flex-1 px-3 py-2 bg-slate-600 hover:bg-slate-500 rounded-md text-white font-semibold transition-colors"
          >
            {displayOpponentTeam}
          </button>
        </div>
        <p className="text-xs text-slate-400 mt-1">{t('score.instructions')}</p>
      </div>

      {/* Field Players Section */}
      <FormationRenderer
          teamConfig={teamConfig}
          selectedFormation={selectedFormation}
          formation={formation}
          allPlayers={allPlayers}
          animationState={uiState.animationState}
          recentlySubstitutedPlayers={uiState.recentlySubstitutedPlayers}
          hideNextOffIndicator={uiState.hideNextOffIndicator || !canSubstitute}
          nextPlayerIdToSubOut={nextPlayerIdToSubOut}

          substitutionCount={substitutionCount}
          rotationQueue={rotationQueue}
          roleGroups={roleGroups}
          substitutionLogic={substitutionLogic}
          nextToSubOutIds={nextToSubOutIds}
          fixedRoleGroup={fixedRoleGroup}
          quickTapHandlers={quickTapHandlers}
          goalieHandlers={goalieHandlers}
          getPlayerNameById={getPlayerNameById}
          getPlayerTimeStats={getPlayerTimeStats}
          showLiveDeficit={showLiveDeficit}
          dragProps={dragProps}
          renderSection="field"
        />

      {/* SUB NOW Button - positioned between field and substitute players */}
      <div
        className="flex gap-2 mt-4 z-30 relative"
        data-testid="substitution-action-row"
      >
        <SubstitutionCountInlineControl
          value={substitutionCount}
          min={1}
          max={maxSubstitutionCount}
          onChange={handleSubstitutionCountChange}
          disabled={!canSubstitute}
          className="flex-shrink-0"
        />
        <Button
          onClick={handleRegularSubstitutionClick}
          Icon={RefreshCcw}
          className="flex-1"
          disabled={!canSubstitute}
          title={canSubstitute ? t('substitution.makeSubstitution') : t('substitution.cannotSubstitute')}
        >
          {substitutionButtonLabel}
        </Button>
        <button
          onClick={handleUndoSubstitutionClick}
          disabled={!uiState.lastSubstitution}
          className={`w-12 h-12 rounded-md flex items-center justify-center transition-all duration-200 ${
            uiState.lastSubstitution
              ? 'bg-slate-600 hover:bg-slate-500 text-slate-100 shadow-md cursor-pointer'
              : 'bg-slate-800 text-slate-600 cursor-not-allowed opacity-50'
          }`}
          title={uiState.lastSubstitution ? t('substitution.undoTooltip') : t('substitution.undoDisabled')}
        >
          <Undo2 className="h-5 w-5" />
        </button>
      </div>

      {/* Substitute Players Section */}
      <FormationRenderer
          teamConfig={teamConfig}
          selectedFormation={selectedFormation}
          formation={formation}
          allPlayers={allPlayers}
          animationState={uiState.animationState}
          recentlySubstitutedPlayers={uiState.recentlySubstitutedPlayers}
          hideNextOffIndicator={uiState.hideNextOffIndicator || !canSubstitute}
          nextPlayerIdToSubOut={nextPlayerIdToSubOut}

          substitutionCount={substitutionCount}
          rotationQueue={rotationQueue}
          roleGroups={roleGroups}
          substitutionLogic={substitutionLogic}
          nextToSubOutIds={nextToSubOutIds}
          fixedRoleGroup={fixedRoleGroup}
          quickTapHandlers={quickTapHandlers}
          goalieHandlers={goalieHandlers}
          getPlayerNameById={getPlayerNameById}
          getPlayerTimeStats={getPlayerTimeStats}
          showLiveDeficit={showLiveDeficit}
          dragProps={dragProps}
          renderSection="substitutes"
        />

      <DragGhost
        dragProps={dragProps}
        formation={formation}
        allPlayers={allPlayers}
        getPlayerNameById={getPlayerNameById}
        resolvePositionLabel={resolveGhostPositionLabel}
      />

      {/* Action Buttons */}
      <div className="flex flex-col gap-3 mt-4">
        {/* Pre-plan Next Period Button — visible only when this isn't the final period */}
        {typeof handleStartPrePlanning === 'function' && currentPeriodNumber < numPeriods && (
          <Button onClick={handleStartPrePlanning} Icon={CalendarClock} variant="secondary" className="w-full">
            {t('actions.prePlanNextPeriod')}
          </Button>
        )}
        {/* End Period Button */}
        <Button
          onClick={handleEndPeriod}
          Icon={Square}
          variant="danger"
          className="w-full"
          disabled={isEndingPeriod}
        >
          {t('actions.endPeriod')}
        </Button>
      </div>

      {/* Field Player Modal */}
      <FieldPlayerModal
        isOpen={modalHandlers.modals.fieldPlayer.isOpen}
        onSetNext={() => substitutionHandlers.handleSetNextSubstitution(modalHandlers.modals.fieldPlayer)}
        onRemoveFromNext={() => substitutionHandlers.handleRemoveFromNextSubstitution(modalHandlers.modals.fieldPlayer)}
        onSubNow={() => substitutionHandlers.handleSubstituteNow(modalHandlers.modals.fieldPlayer)}
        onCancel={substitutionHandlers.handleCancelFieldPlayerModal}
        onChangePosition={substitutionHandlers.handleChangePosition}
        playerName={modalHandlers.modals.fieldPlayer.playerName}
        availablePlayers={modalHandlers.modals.fieldPlayer.availablePlayers}
        showPositionChange={modalHandlers.modals.fieldPlayer.type === 'player'}
        showPositionOptions={modalHandlers.modals.fieldPlayer.showPositionOptions}
        showSubstitutionOptions={modalHandlers.modals.fieldPlayer.type === 'player'}
        canSubstitute={canSubstitute}
        isPlayerAboutToSubOff={modalHandlers.modals.fieldPlayer.isPlayerAboutToSubOff || false}
        showGoOffNextOption={!(modalHandlers.modals.fieldPlayer.isInFixedGroup || false)}
      />

      {/* Substitute Player Modal */}
      <SubstitutePlayerModal
        isOpen={modalHandlers.modals.substitute.isOpen}
        onInactivate={() => substitutionHandlers.handleInactivatePlayer(modalHandlers.modals.substitute, allPlayers, formation)}
        onActivate={() => substitutionHandlers.handleActivatePlayer(modalHandlers.modals.substitute)}
        onCancel={substitutionHandlers.handleCancelSubstituteModal}
        onSetAsNextToGoIn={() => substitutionHandlers.handleSetAsNextToGoIn(modalHandlers.modals.substitute, formation)}
        onChangeNextPosition={(targetPosition) => substitutionHandlers.handleChangeNextPosition(modalHandlers.modals.substitute, targetPosition)}
        playerName={modalHandlers.modals.substitute.playerName}
        isCurrentlyInactive={modalHandlers.modals.substitute.isCurrentlyInactive}
        canSetAsNextToGoIn={modalHandlers.modals.substitute.canSetAsNextToGoIn}
        canChangeNextPosition={modalHandlers.modals.substitute.canChangeNextPosition}
        availableNextPositions={modalHandlers.modals.substitute.availableNextPositions}
        showPositionSelection={modalHandlers.modals.substitute.showPositionSelection}
      />

      {/* Goalie Replacement Modal */}
      <GoalieModal
        isOpen={modalHandlers.modals.goalie.isOpen}
        onCancel={goalieHandlers.handleCancelGoalieModal}
        onSelectGoalie={goalieHandlers.handleSelectNewGoalie}
        currentGoalieName={modalHandlers.modals.goalie.currentGoalieName}
        availablePlayers={modalHandlers.modals.goalie.availablePlayers}
      />

      {/* Score Manager Modal */}
      <ScoreManagerModal
        isOpen={modalHandlers.modals.scoreEdit.isOpen}
        onCancel={modalHandlers.closeScoreEditModal}
        ownScore={ownScore}
        opponentScore={opponentScore}
        ownTeamName={resolvedOwnTeamName}
        opponentTeam={opponentTeamName}
        matchEvents={matchEvents}
        goalScorers={goalScorers}
        allPlayers={allPlayers}
        onAddGoalScored={() => scoreHandlers.handleAddGoalScored(createGameState())}
        onAddGoalConceded={() => scoreHandlers.handleAddGoalConceded(createGameState())}
        onEditGoalScorer={scoreHandlers.handleEditGoalScorer}
        onDeleteGoal={(eventId) => scoreHandlers.handleDeleteGoal(eventId, createGameState())}
        calculateMatchTime={(timestamp) => calculateMatchTime(timestamp, matchStartTime)}
        formatTime={formatTime}
        getPlayerName={getPlayerName}
        allowScorerSelection={trackGoalScorer}
      />

      {/* Undo Confirmation Modal */}
      <ConfirmationModal
        isOpen={modalHandlers.modals.undoConfirm.isOpen}
        onConfirm={handleUndoSubstitutionClick}
        onCancel={modalHandlers.closeUndoConfirmModal}
        title={t('substitution.undoModal.title')}
        message={t('substitution.undoModal.message')}
        confirmText={t('substitution.undoModal.confirm')}
        cancelText={t('substitution.undoModal.cancel')}
        variant="warning"
      />

      {/* Goal Scorer Modal — doubles as the assist-selection step (selectionType: 'assist') */}
      <GoalScorerModal
        isOpen={trackGoalScorer && modalHandlers.modals.goalScorer.isOpen}
        onClose={scoreHandlers.handleCancelGoalScorer}
        onSelectScorer={(selectedId) => (
          isAssistStep
            ? scoreHandlers.handleSelectAssist(modalHandlers.modals.goalScorer.eventId, selectedId)
            : scoreHandlers.handleSelectGoalScorer(modalHandlers.modals.goalScorer.eventId, selectedId)
        )}
        onCorrectGoal={(eventId, selectedId) => (
          isAssistStep
            ? scoreHandlers.handleCorrectAssist(eventId, selectedId)
            : scoreHandlers.handleCorrectGoalScorer(eventId, selectedId)
        )}
        eligiblePlayers={
          isAssistStep
            ? eligiblePlayers.filter(p => p.id !== modalHandlers.modals.goalScorer.excludePlayerId)
            : eligiblePlayers
        }
        mode={modalHandlers.modals.goalScorer.mode}
        selectionType={modalHandlers.modals.goalScorer.selectionType}
        eventId={modalHandlers.modals.goalScorer.eventId}
        currentScorerId={modalHandlers.modals.goalScorer.currentScorerId}
        existingGoalData={modalHandlers.modals.goalScorer.existingGoalData}
        matchTime={modalHandlers.modals.goalScorer.matchTime}
        goalType={modalHandlers.modals.goalScorer.goalType}
      />

      {/* Substitute Selection Modal */}
      <SubstituteSelectionModal
        isOpen={modalHandlers.modals.substituteSelection.isOpen}
        onCancel={substitutionHandlers.handleCancelSubstituteSelection}
        onSelectSubstitute={(substituteId) => substitutionHandlers.handleSelectSubstituteForImmediate(modalHandlers.modals.substituteSelection, substituteId)}
        fieldPlayerName={modalHandlers.modals.substituteSelection.fieldPlayerName}
        availableSubstitutes={modalHandlers.modals.substituteSelection.availableSubstitutes}
      />
    </div>
  );
}

// Custom comparison function for React.memo
const arePropsEqual = (prevProps, nextProps) => {
  // Compare primitive props
  const shallowComparedProps = [
    'currentPeriodNumber', 'matchTimerSeconds', 'subTimerSeconds', 'isSubTimerPaused',
    'teamConfig', 'selectedFormation', 'nextPlayerToSubOut',
    'nextPlayerIdToSubOut', 'ownScore', 'opponentScore',
    'trackGoalScorer', 'substitutionLogic', 'roleGroups', 'nextToSubOutIds', 'fixedRoleGroup',
    'isEndingPeriod'
  ];
  
  for (const prop of shallowComparedProps) {
    if (prevProps[prop] !== nextProps[prop]) {
      return false;
    }
  }
  
  // Compare complex objects with shallow comparison
  // Formation object comparison
  if (JSON.stringify(prevProps.formation) !== JSON.stringify(nextProps.formation)) {
    return false;
  }
  
  // Players array comparison (shallow)
  if (prevProps.allPlayers?.length !== nextProps.allPlayers?.length) {
    return false;
  }
  
  // Compare players by reference (assuming immutable updates)
  if (prevProps.allPlayers && nextProps.allPlayers) {
    for (let i = 0; i < prevProps.allPlayers.length; i++) {
      if (prevProps.allPlayers[i] !== nextProps.allPlayers[i]) {
        return false;
      }
    }
  }
  
  // Rotation queue comparison
  if (prevProps.rotationQueue?.length !== nextProps.rotationQueue?.length) {
    return false;
  }
  
  if (prevProps.rotationQueue && nextProps.rotationQueue) {
    for (let i = 0; i < prevProps.rotationQueue.length; i++) {
      if (prevProps.rotationQueue[i] !== nextProps.rotationQueue[i]) {
        return false;
      }
    }
  }
  
  // All props are equal
  return true;
};

GameScreen.propTypes = {
  setRoleGroups: PropTypes.func.isRequired,
  setNextToSubOutIds: PropTypes.func.isRequired,
  roleGroups: PropTypes.objectOf(PropTypes.shape({
    queue: PropTypes.arrayOf(PropTypes.string),
    fieldPositions: PropTypes.arrayOf(PropTypes.string),
    substitutePosition: PropTypes.string,
    isScheduled: PropTypes.bool
  })),
  substitutionLogic: PropTypes.string,
  nextToSubOutIds: PropTypes.arrayOf(PropTypes.string),
  fixedRoleGroup: PropTypes.string,
  showLiveDeficit: PropTypes.bool,
  handleStartPrePlanning: PropTypes.func,
  numPeriods: PropTypes.number,
  isEndingPeriod: PropTypes.bool
};

// Export memoized component
export default React.memo(GameScreen, arePropsEqual);
