import React from 'react';
import PropTypes from 'prop-types';
import { useTranslation } from 'react-i18next';
import { PRIVACY_PATH, TERMS_PATH, getLegalUrl } from '../../constants/legalUrls';
import { isNativePlatform } from '../../utils/platform';

// Privacy Policy + Terms links. On the web they open in the SAME tab — the legal
// route replaces the app tree and LegalScreen renders a "← Sport Wizard" link
// back. On native, Capacitor routes target="_blank" anchors to the system
// browser (LegalScreen is never mounted there), which is what we want. Used in
// the app footer, AuthModal, PreferencesModal, and PolicyUpdateBanner. Callers
// supply alignment (e.g. justify-center) via className.
export function LegalLinks({ className = '' }) {
  const { t } = useTranslation('common');
  const native = isNativePlatform();
  const newTabLabel = t('opensInNewTab');
  const privacyLabel = t('legal.privacyLink');
  const termsLabel = t('legal.termsLink');
  // New-tab attributes and the "opens in a new tab" accessible hint only apply on
  // native, where the link opens the system browser. React omits an
  // aria-label={undefined} from the DOM, so the web links carry no hint.
  const linkProps = native ? { target: '_blank', rel: 'noopener noreferrer' } : {};
  return (
    <div className={`flex items-center gap-3 ${className}`}>
      <a
        href={getLegalUrl(PRIVACY_PATH)}
        {...linkProps}
        aria-label={native ? `${privacyLabel} (${newTabLabel})` : undefined}
        className="text-sky-400 hover:text-sky-300 underline"
      >
        {privacyLabel}
      </a>
      <span aria-hidden="true" className="text-slate-600">·</span>
      <a
        href={getLegalUrl(TERMS_PATH)}
        {...linkProps}
        aria-label={native ? `${termsLabel} (${newTabLabel})` : undefined}
        className="text-sky-400 hover:text-sky-300 underline"
      >
        {termsLabel}
      </a>
    </div>
  );
}

LegalLinks.propTypes = {
  className: PropTypes.string,
};
