// ISO 3166-1 alpha-2 country → supported language. Extend when new
// translations ship.
export const COUNTRY_TO_LANGUAGE = {
  SE: 'sv',
  FI: 'sv', // Swedish is an official language of Finland
  AX: 'sv'  // Åland Islands
};

export function languageForCountry(countryCode) {
  if (typeof countryCode !== 'string') {
    return null;
  }
  return COUNTRY_TO_LANGUAGE[countryCode.toUpperCase()] || null;
}
