import { AUTO_SELECT_STRATEGY, DISTRIBUTION_STRATEGY, SINGLE_MATCH_STRATEGY } from '../constants/planMatchesConstants';

const getMetricValue = (player, metric) => {
  return metric === AUTO_SELECT_STRATEGY.ATTENDANCE
    ? player.attendanceRate
    : player.practicesPerMatch;
};

export const buildSortedRoster = (rosterWithStats, metric) => {
  return [...(rosterWithStats || [])].sort((a, b) => {
    const diff = (getMetricValue(b, metric) || 0) - (getMetricValue(a, metric) || 0);
    if (diff !== 0) return diff;
    return (a.displayName || '').localeCompare(b.displayName || '');
  });
};

/**
 * Compute a single strength score from a player's level and position within that level.
 * Higher score = stronger player. Scores are distributed evenly within each level's
 * 1000-point band so transitions between levels are smooth.
 *
 * @param {number} level - Skill level (higher = stronger)
 * @param {number} positionInLevel - 1-based position within the level (1 = strongest)
 * @param {number} playersInLevel - Total players in this level
 * @returns {number}
 */
export const getStrengthScore = (level, positionInLevel, playersInLevel) => {
  const effectiveLevel = level ?? 2;
  const count = Math.max(1, playersInLevel || 1);
  const pos = Math.max(1, positionInLevel || 1);
  return effectiveLevel * 1000 - (pos - 1) * (1000 / count);
};

/**
 * Enrich a roster array with strengthScore based on player rankings.
 * Players without a ranking row default to level 2 and are placed last within that level.
 *
 * @param {Array} roster - Array of player objects (must have .id)
 * @param {Array} rankings - Array of { player_id, level, rank_order } from getPlayerRankings
 * @returns {Array} New roster array with strengthScore added to each player
 */
export const attachStrengthScores = (roster, rankings) => {
  if (!roster || roster.length === 0) return roster || [];

  const rankingMap = new Map();
  if (rankings) {
    rankings.forEach(r => rankingMap.set(r.player_id, r));
  }

  // Group players by level
  const playersByLevel = new Map();
  roster.forEach(player => {
    const ranking = rankingMap.get(player.id);
    const level = ranking?.level ?? 2;
    if (!playersByLevel.has(level)) {
      playersByLevel.set(level, []);
    }
    playersByLevel.get(level).push({
      player,
      rankOrder: ranking?.rank_order ?? 0
    });
  });

  // Within each level, sort: ranked players (rank_order > 0) by rank_order ASC, then unranked (0) at end
  const scoreMap = new Map();
  for (const [level, entries] of playersByLevel) {
    entries.sort((a, b) => {
      if (a.rankOrder === 0 && b.rankOrder === 0) return 0;
      if (a.rankOrder === 0) return 1;
      if (b.rankOrder === 0) return -1;
      return a.rankOrder - b.rankOrder;
    });
    const count = entries.length;
    entries.forEach((entry, index) => {
      scoreMap.set(entry.player.id, getStrengthScore(level, index + 1, count));
    });
  }

  return roster.map(player => ({
    ...player,
    strengthScore: scoreMap.get(player.id) ?? getStrengthScore(2, 1, 1)
  }));
};

// Callers must pass a roster that has already been through attachStrengthScores,
// which assigns every player a non-zero strengthScore (unranked players land in
// the level-2 mid-band, never at 0). The `?? 0` is a defensive fallback only —
// in production it never fires.
const buildStrengthSortedRoster = (rosterWithStats, direction) => {
  const factor = direction === 'asc' ? 1 : -1;
  return [...(rosterWithStats || [])].sort((a, b) => {
    const diff = ((a.strengthScore ?? 0) - (b.strengthScore ?? 0)) * factor;
    if (diff !== 0) return diff;
    return (a.displayName || '').localeCompare(b.displayName || '');
  });
};

export const autoSelectSingleMatch = ({
  rosterWithStats,
  metric,
  targetCount,
  unavailableIds,
  singleMatchStrategy
}) => {
  const target = Math.max(0, targetCount || 0);
  const unavailableSet = new Set(unavailableIds || []);

  let sorted;
  if (singleMatchStrategy === SINGLE_MATCH_STRATEGY.STRONGEST) {
    sorted = buildStrengthSortedRoster(rosterWithStats, 'desc');
  } else if (singleMatchStrategy === SINGLE_MATCH_STRATEGY.GROWTH) {
    sorted = buildStrengthSortedRoster(rosterWithStats, 'asc');
  } else {
    sorted = buildSortedRoster(rosterWithStats, metric);
  }

  return sorted
    .filter(player => !unavailableSet.has(player.id))
    .slice(0, target)
    .map(player => player.id);
};

/**
 * Distribute non-overlap players across matches by the chosen strategy.
 */
const distributeByStrategy = ({
  nonOverlapPlayers,
  matchIds,
  selections,
  targets,
  isAvailableFor,
  rosterById,
  distributionStrategy,
  strongMatchId
}) => {
  const addToMatch = (playerId, matchId) => {
    if (selections[matchId].size < targets[matchId]) {
      selections[matchId].add(playerId);
      return true;
    }
    return false;
  };

  if (distributionStrategy === DISTRIBUTION_STRATEGY.EQUAL) {
    // Snake-draft: sort by strength desc, place each into match with lower total strength
    const sorted = [...nonOverlapPlayers].sort((a, b) =>
      (rosterById.get(b.id)?.strengthScore ?? 0) - (rosterById.get(a.id)?.strengthScore ?? 0)
    );
    const totalStrength = matchIds.reduce((acc, id) => {
      acc[id] = 0;
      for (const playerId of selections[id]) {
        acc[id] += rosterById.get(playerId)?.strengthScore ?? 0;
      }
      return acc;
    }, {});

    for (const player of sorted) {
      const availableMatchIds = matchIds.filter(id =>
        isAvailableFor(player, id) && selections[id].size < targets[id]
      );
      if (availableMatchIds.length === 0) continue;
      // Pick match with lowest total strength
      availableMatchIds.sort((a, b) => totalStrength[a] - totalStrength[b]);
      const chosenMatch = availableMatchIds[0];
      if (addToMatch(player.id, chosenMatch)) {
        totalStrength[chosenMatch] += rosterById.get(player.id)?.strengthScore ?? 0;
      }
    }
  } else if (distributionStrategy === DISTRIBUTION_STRATEGY.ONE_STRONG) {
    // Sort by strength desc, fill strong match first, then the other
    const sorted = [...nonOverlapPlayers].sort((a, b) =>
      (rosterById.get(b.id)?.strengthScore ?? 0) - (rosterById.get(a.id)?.strengthScore ?? 0)
    );
    const effectiveStrongId = matchIds.includes(strongMatchId) ? strongMatchId : matchIds[0];
    const otherMatchIds = matchIds.filter(id => id !== effectiveStrongId);

    // Fill strong match first
    for (const player of sorted) {
      if (isAvailableFor(player, effectiveStrongId) && selections[effectiveStrongId].size < targets[effectiveStrongId]) {
        addToMatch(player.id, effectiveStrongId);
      }
    }
    // Fill other matches with remaining players
    for (const player of sorted) {
      if (selections[effectiveStrongId]?.has(player.id)) continue;
      for (const matchId of otherMatchIds) {
        if (isAvailableFor(player, matchId) && selections[matchId].size < targets[matchId]) {
          addToMatch(player.id, matchId);
          break;
        }
      }
    }
  } else {
    // RANDOM: Fisher-Yates shuffle, then round-robin to emptiest
    const shuffled = [...nonOverlapPlayers];
    for (let i = shuffled.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
    }
    for (const player of shuffled) {
      const availableMatchIds = matchIds.filter(id =>
        isAvailableFor(player, id) && selections[id].size < targets[id]
      );
      if (availableMatchIds.length === 0) continue;
      availableMatchIds.sort((a, b) => selections[a].size - selections[b].size);
      addToMatch(player.id, availableMatchIds[0]);
    }
  }
};

export const autoSelectMultipleMatches = ({
  rosterWithStats,
  metric,
  matches,
  targetCounts,
  unavailableByMatch,
  ensureCoverage,
  distributionStrategy,
  strongMatchId
}) => {
  const sorted = buildSortedRoster(rosterWithStats, metric);
  const matchIds = (matches || []).map(match => match.id);
  const targets = matchIds.reduce((acc, id) => {
    acc[id] = targetCounts?.[id] || 0;
    return acc;
  }, {});

  const totalSlots = matchIds.reduce((sum, id) => sum + targets[id], 0);

  const unavailableSets = matchIds.reduce((acc, id) => {
    acc[id] = new Set(unavailableByMatch?.[id] || []);
    return acc;
  }, {});

  const isAvailableFor = (player, matchId) => !unavailableSets[matchId].has(player.id);

  const placeablePlayers = sorted.filter(player =>
    matchIds.some(id => isAvailableFor(player, id))
  );

  const doCoverage = ensureCoverage && totalSlots >= placeablePlayers.length;

  const selections = matchIds.reduce((acc, id) => {
    acc[id] = new Set();
    return acc;
  }, {});

  const addToMatch = (playerId, matchId) => {
    if (selections[matchId].size < targets[matchId]) {
      selections[matchId].add(playerId);
      return true;
    }
    return false;
  };

  const useDistribution = doCoverage && distributionStrategy &&
    Object.values(DISTRIBUTION_STRATEGY).includes(distributionStrategy);

  if (!doCoverage) {
    matchIds.forEach(matchId => {
      sorted.forEach(player => {
        if (selections[matchId].size >= targets[matchId]) return;
        if (!isAvailableFor(player, matchId)) return;
        addToMatch(player.id, matchId);
      });
    });
  } else {
    // Step 1: Pre-fill overlap from top available-for-all players
    const delta = totalSlots - placeablePlayers.length;
    const minOverlapNeeded = Math.max(0, Math.ceil(delta / (matchIds.length - 1)));
    const availableForAll = sorted.filter(player =>
      matchIds.every(id => isAvailableFor(player, id))
    );
    const overlapPlayers = new Set();
    for (const player of availableForAll) {
      if (overlapPlayers.size >= minOverlapNeeded) break;
      overlapPlayers.add(player.id);
    }
    for (const playerId of overlapPlayers) {
      matchIds.forEach(matchId => addToMatch(playerId, matchId));
    }

    // Step 2: Place single-match-only players into their only available match
    const placed = new Set(overlapPlayers);
    sorted.forEach(player => {
      if (placed.has(player.id)) return;
      const availableMatchIds = matchIds.filter(id =>
        isAvailableFor(player, id) && selections[id].size < targets[id]
      );
      if (availableMatchIds.length === 1) {
        addToMatch(player.id, availableMatchIds[0]);
        placed.add(player.id);
      }
    });

    if (useDistribution) {
      // Collect non-overlap players that haven't been placed yet
      const nonOverlapPlayers = sorted.filter(player =>
        !placed.has(player.id) && matchIds.some(id => isAvailableFor(player, id))
      );

      // Build rosterById map for strength lookups
      const rosterById = new Map();
      (rosterWithStats || []).forEach(p => rosterById.set(p.id, p));

      distributeByStrategy({
        nonOverlapPlayers,
        matchIds,
        selections,
        targets,
        isAvailableFor,
        rosterById,
        distributionStrategy,
        strongMatchId
      });
    } else {
      // Step 3: Round-robin remaining multi-match players to emptiest available match
      sorted.forEach(player => {
        if (placed.has(player.id)) return;
        const availableMatchIds = matchIds.filter(id =>
          isAvailableFor(player, id) && selections[id].size < targets[id]
        );
        if (availableMatchIds.length === 0) return;
        availableMatchIds.sort((a, b) => selections[a].size - selections[b].size);
        addToMatch(player.id, availableMatchIds[0]);
        placed.add(player.id);
      });
    }

    // Step 4: Fill remaining unfilled slots greedily (top-ranked first, creating overlap)
    matchIds.forEach(matchId => {
      sorted.forEach(player => {
        if (selections[matchId].size >= targets[matchId]) return;
        if (!isAvailableFor(player, matchId)) return;
        if (selections[matchId].has(player.id)) return;
        addToMatch(player.id, matchId);
      });
    });
  }

  return matchIds.reduce((acc, id) => {
    acc[id] = [...selections[id]];
    return acc;
  }, {});
};
