import { useCallback, useEffect, useState } from 'react';
import { createPersistenceManager } from '../utils/persistenceManager';
import { STORAGE_KEYS } from '../constants/storageKeys';
import { isNativePlatform } from '../utils/platform';

const persistence = createPersistenceManager(STORAGE_KEYS.INSTALL_PROMPT, {
  dismissedAt: null,
});

// Module-level singleton: all hook instances share one deferred event so that
// only one component can ever call prompt() on it, avoiding double-consume bugs
// when AuthModal (InstallAppCTA) and PreferencesModal are both mounted.
let sharedDeferredEvent = null;
const eventCapturedSetters = new Set();

function setSharedEvent(event) {
  sharedDeferredEvent = event;
  const captured = event !== null;
  eventCapturedSetters.forEach((setter) => setter(captured));
}

function detectInstalled() {
  if (typeof window === 'undefined') return false;
  if (window.matchMedia && window.matchMedia('(display-mode: standalone)').matches) {
    return true;
  }
  // iOS Safari standalone flag
  if (typeof window.navigator !== 'undefined' && window.navigator.standalone === true) {
    return true;
  }
  return false;
}

/**
 * Captures the browser's `beforeinstallprompt` event so we can surface our own
 * "Install Sport Wizard" affordance at a deliberate moment (AuthModal,
 * PreferencesModal). The native mini-infobar is suppressed via preventDefault.
 *
 * iOS Safari does not fire this event — `canInstall` will stay false there.
 *
 * All mounted instances share the same deferred event via module-level state,
 * so calling promptInstall() from any component correctly consumes it once.
 * Each mounted instance registers its own beforeinstallprompt listener; calling
 * preventDefault() and setSharedEvent() multiple times on the same event is
 * idempotent and causes no harm.
 *
 * Dismissal persists indefinitely to localStorage. Users who dismiss will not
 * see the CTA again unless they clear site data. This is intentional for M1.
 */
export function useInstallPrompt() {
  const [eventCaptured, setEventCaptured] = useState(() => sharedDeferredEvent !== null);
  const [isInstalled, setIsInstalled] = useState(detectInstalled);
  const [isDismissed, setIsDismissed] = useState(() => Boolean(persistence.loadState().dismissedAt));

  useEffect(() => {
    if (typeof window === 'undefined') return undefined;

    // Register this instance's setter so it receives shared event updates.
    eventCapturedSetters.add(setEventCaptured);

    const handleBeforeInstallPrompt = (event) => {
      event.preventDefault();
      setSharedEvent(event);
    };

    const handleAppInstalled = () => {
      setSharedEvent(null);
      setIsInstalled(true);
    };

    window.addEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
    window.addEventListener('appinstalled', handleAppInstalled);

    return () => {
      eventCapturedSetters.delete(setEventCaptured);
      window.removeEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
      window.removeEventListener('appinstalled', handleAppInstalled);
    };
  }, []);

  const promptInstall = useCallback(async () => {
    const deferred = sharedDeferredEvent;
    if (!deferred) return 'unavailable';

    deferred.prompt();
    try {
      const choice = await deferred.userChoice;
      setSharedEvent(null);
      if (choice && choice.outcome === 'accepted') {
        setIsInstalled(true);
        return 'accepted';
      }
      // Persist suppression so the CTA doesn't re-appear if Chrome re-fires
      // beforeinstallprompt after navigation.
      persistence.saveState({ dismissedAt: new Date().toISOString() });
      setIsDismissed(true);
      return 'dismissed';
    } catch (_error) {
      setSharedEvent(null);
      return 'unavailable';
    }
  }, []);

  const dismiss = useCallback(() => {
    persistence.saveState({ dismissedAt: new Date().toISOString() });
    setIsDismissed(true);
  }, []);

  const native = isNativePlatform();
  const canInstall = !native && !isInstalled && !isDismissed && eventCaptured;

  return {
    canInstall,
    isInstalled,
    promptInstall,
    dismiss,
  };
}
