import React, { useState, useEffect, useRef } from 'react';
import { useTranslation } from 'react-i18next';
import { Button, NotificationModal } from '../shared/UI';
import { Alert } from '../shared/Alert';
import { LoadingSpinner } from '../shared/LoadingSpinner';
import { Card } from '../shared/Card';
import { Link, Info, Plus } from 'lucide-react';
import { ConnectorCard } from './ConnectorCard';
import { SportAdminConnectModal } from './SportAdminConnectModal';
import { DisconnectConfirmModal } from './DisconnectConfirmModal';
import { ComingSoonBadge } from '../shared/ComingSoonBadge';
import { useTeamConnector } from '../../hooks/useTeamConnector';
import { useTeam } from '../../contexts/TeamContext';
import { useToast } from '../../contexts/ToastContext';
import { ProviderLogo } from './ProviderLogo';
import { triggerScraperWorkflow } from '../../services/connectorService';
import {
  getAllProviders,
  CONNECTOR_PROVIDERS,
  CONNECTOR_STATUS
} from '../../constants/connectorProviders';

export function ConnectorsSection({ team }) {
  const { t } = useTranslation('connectors');
  const { isTeamAdmin } = useTeam();
  const { showSuccess } = useToast();
  const {
    connectors,
    loading,
    error,
    syncingConnectorId,
    connectProvider,
    disconnectProvider,
    manualSync,
    retryConnector,
    getLatestSyncJob,
    clearError
  } = useTeamConnector(team?.id);

  const [showConnectModal, setShowConnectModal] = useState(false);
  const [showDemoBlockedModal, setShowDemoBlockedModal] = useState(false);
  const [showDisconnectModal, setShowDisconnectModal] = useState(false);
  const [selectedConnector, setSelectedConnector] = useState(null);
  const [noticeMessage, setNoticeMessage] = useState('');
  const [syncJobs, setSyncJobs] = useState({});
  const syncJobsIntervalRef = useRef(null);

  // Load latest sync jobs for each connector
  useEffect(() => {
    let isActive = true;
    const loadSyncJobs = async () => {
      if (connectors.length === 0) {
        if (isActive) {
          setSyncJobs({});
        }
        return;
      }

      const jobs = {};
      for (const connector of connectors) {
        try {
          const job = await getLatestSyncJob(connector.id);
          if (job) {
            jobs[connector.id] = job;
          }
        } catch (err) {
          console.error('Error loading sync job for connector:', connector.id, err);
        }
      }

      if (isActive) {
        setSyncJobs(jobs);
      }
    };

    if (syncJobsIntervalRef.current) {
      clearInterval(syncJobsIntervalRef.current);
      syncJobsIntervalRef.current = null;
    }

    if (connectors.length > 0) {
      loadSyncJobs();
      syncJobsIntervalRef.current = setInterval(loadSyncJobs, 30000);
    } else {
      setSyncJobs({});
    }

    return () => {
      isActive = false;
      if (syncJobsIntervalRef.current) {
        clearInterval(syncJobsIntervalRef.current);
        syncJobsIntervalRef.current = null;
      }
    };
  }, [connectors, getLatestSyncJob]);

  useEffect(() => {
    if (noticeMessage) {
      const timer = setTimeout(() => {
        setNoticeMessage('');
      }, 5000);
      return () => clearTimeout(timer);
    }
  }, [noticeMessage]);

  // Only show to team admins
  if (!isTeamAdmin) {
    return null;
  }

  // Get all available providers
  const allProviders = getAllProviders();

  // Get connected provider IDs
  const connectedProviderIds = connectors.map(c => c.provider);

  const hasConnectedProvider = connectors.some(
    (c) => c.status === CONNECTOR_STATUS.CONNECTED
  );

  // Handle connect provider
  const handleConnect = (providerId) => {
    // Demo teams can't connect external platforms — explain instead of opening the modal.
    if (team?.is_demo) {
      setShowDemoBlockedModal(true);
      return;
    }
    // For now, only SportAdmin is supported
    if (providerId === CONNECTOR_PROVIDERS.SPORTADMIN.id) {
      setShowConnectModal(true);
    }
  };

  // Reopen the credential modal in place — the edge function upserts on team+provider, so no disconnect is needed.
  const handleUpdateCredentials = () => {
    setShowConnectModal(true);
  };

  const triggerImmediateSync = (successLogMessage) => {
    triggerScraperWorkflow(team.id).then(response => {
      if (response.success) {
        console.log(successLogMessage);
      } else {
        console.warn('Failed to trigger scraper workflow, will run on schedule:', response.message);
        setNoticeMessage(t('connectorsSection.immediateSyncFailed'));
      }
    }).catch(err => {
      console.warn('Error triggering scraper workflow:', err);
      setNoticeMessage(t('connectorsSection.immediateSyncFailed'));
    });
  };

  // Handle connection success
  const handleConnected = async (credentials) => {
    try {
      await connectProvider(CONNECTOR_PROVIDERS.SPORTADMIN.id, credentials);
      setShowConnectModal(false);
      showSuccess(t('connectorsSection.connectedSuccess'), { durationMs: 10000 });

      // Trigger immediate scraper run for verification (non-blocking)
      triggerImmediateSync('Scraper workflow triggered for verification');
    } catch (err) {
      // Error will be shown in modal
      throw err;
    }
  };

  // Handle manual sync
  const handleManualSync = async (connectorId) => {
    try {
      await manualSync(connectorId);
      showSuccess(t('connectorsSection.syncStarted'), { durationMs: 5000 });

      // Trigger immediate scraper run (non-blocking)
      triggerImmediateSync('Scraper workflow triggered for manual sync');
    } catch (err) {
      // Error handled by hook
      console.error('Manual sync error:', err);
    }
  };

  // Handle disconnect
  const handleDisconnect = (connector) => {
    setSelectedConnector(connector);
    setShowDisconnectModal(true);
  };

  // Handle disconnect confirm
  const handleDisconnectConfirm = async () => {
    try {
      await disconnectProvider(selectedConnector.id);
      setShowDisconnectModal(false);
      setSelectedConnector(null);
      showSuccess(t('connectorsSection.disconnectedSuccess'), { durationMs: 5000 });
    } catch (err) {
      // Error will be shown in modal
      throw err;
    }
  };

  // Handle retry
  const handleRetry = async (connectorId) => {
    try {
      await retryConnector(connectorId);
      showSuccess(t('connectorsSection.retryingConnection'), { durationMs: 5000 });
    } catch (err) {
      console.error('Retry error:', err);
    }
  };

  return (
    <div className="space-y-6">
      {/* Section Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center space-x-3">
          <Link className="w-5 h-5 text-sky-400" />
          <h4 className="text-md font-medium text-slate-300">{t('connectorsSection.title')}</h4>
        </div>
      </div>

      {/* Info Banner */}
      {!hasConnectedProvider && (
        <Alert variant="info" icon={Info}>
          {t('connectorsSection.infoBanner')}
        </Alert>
      )}

      {/* Notice Message */}
      {noticeMessage && (
        <Alert variant="warning">{noticeMessage}</Alert>
      )}

      {/* Error Message */}
      {error && (
        <Alert variant="error">
          <div className="flex items-center justify-between">
            <span>{error}</span>
            <button
              onClick={clearError}
              className="text-rose-300 hover:text-rose-100 text-xs underline ml-2"
            >
              {t('connectorsSection.dismiss')}
            </button>
          </div>
        </Alert>
      )}

      {/* Loading State */}
      {loading && connectors.length === 0 && (
        <div className="py-8">
          <LoadingSpinner size="md" message={t('connectorsSection.loadingConnectors')} />
        </div>
      )}

      {/* Connected Providers */}
      {connectors.length > 0 && (
        <div className="space-y-4">
          <h5 className="text-sm font-medium text-slate-400">{t('connectorsSection.connectedProviders')}</h5>
          {connectors.map((connector) => {
            // Only SportAdmin's modal captures credentials; extend when other providers add credential entry.
            const canUpdateCredentials = connector.provider === CONNECTOR_PROVIDERS.SPORTADMIN.id;
            return (
              <ConnectorCard
                key={connector.id}
                connector={connector}
                onManualSync={() => handleManualSync(connector.id)}
                onDisconnect={() => handleDisconnect(connector)}
                onRetry={() => handleRetry(connector.id)}
                onUpdateCredentials={canUpdateCredentials ? handleUpdateCredentials : undefined}
                loading={syncingConnectorId === connector.id}
                latestSyncJob={syncJobs[connector.id]}
              />
            );
          })}
        </div>
      )}

      {/* Available Providers */}
      <div className="space-y-4">
        <h5 className="text-sm font-medium text-slate-400">{t('connectorsSection.availableProviders')}</h5>
        <div className="grid grid-cols-1 gap-4">
          {allProviders.map((provider) => {
            const isConnected = connectedProviderIds.includes(provider.id);
            const isComingSoon = provider.comingSoon;

            return (
              <Card
                key={provider.id}
                padding="sm"
                className={`${
                  isComingSoon
                    ? 'opacity-60'
                    : isConnected
                    ? '!border-emerald-600'
                    : ''
                }`}
              >
                <div className="flex items-center justify-between gap-3">
                  <div className="flex items-center space-x-3 min-w-0">
                    <ProviderLogo provider={provider} />
                  </div>
                  <div className="flex items-center space-x-2 flex-shrink-0">
                    {isConnected && (
                      <span className="px-2 py-1 bg-emerald-600 text-emerald-100 rounded text-xs font-medium">
                        {t('connectorsSection.connected')}
                      </span>
                    )}
                    {isComingSoon && (
                      <ComingSoonBadge className="shrink-0" />
                    )}
                    {!isConnected && !isComingSoon && (
                      <Button
                        onClick={() => handleConnect(provider.id)}
                        variant="primary"
                        size="sm"
                        className="shrink-0"
                        Icon={Plus}
                      >
                        {t('connectorsSection.connect')}
                      </Button>
                    )}
                  </div>
                </div>
              </Card>
            );
          })}
        </div>
      </div>

      {/* Connect Modal */}
      <SportAdminConnectModal
        isOpen={showConnectModal}
        onClose={() => setShowConnectModal(false)}
        team={team}
        onConnected={handleConnected}
      />

      {/* Demo team blocked modal */}
      <NotificationModal
        isOpen={showDemoBlockedModal}
        onClose={() => setShowDemoBlockedModal(false)}
        title={t('connectorsSection.demoBlocked.title')}
        message={t('connectorsSection.demoBlocked.message')}
        buttonText={t('connectorsSection.demoBlocked.acknowledge')}
      />

      {/* Disconnect Modal */}
      <DisconnectConfirmModal
        isOpen={showDisconnectModal}
        onClose={() => {
          setShowDisconnectModal(false);
          setSelectedConnector(null);
        }}
        connector={selectedConnector}
        onConfirm={handleDisconnectConfirm}
      />
    </div>
  );
}
