import { copyLiveMatchUrlToClipboard, formatKickoffTime } from './liveMatchLinkUtils';

const WHATSAPP_SHARE_URL = 'https://wa.me/';

export function formatMatchResultMessage({
  ownTeamName,
  opponentName,
  finalScoreLabel,
  ownScore,
  opponentScore
}) {
  return `${ownTeamName} - ${opponentName}\n${finalScoreLabel}: ${ownScore}-${opponentScore}`;
}

export function formatLiveMatchShareMessage({
  ownTeamName,
  opponentName,
  matchStartLabel,
  kickoffTime,
  liveUrl
}) {
  const lines = [`${ownTeamName} - ${opponentName}`];
  if (kickoffTime) {
    lines.push(`${matchStartLabel}: ${kickoffTime}`);
  }
  lines.push(liveUrl);
  return lines.join('\n');
}

export async function shareTextMessage(message) {
  if (typeof navigator !== 'undefined' && typeof navigator.share === 'function') {
    try {
      await navigator.share({ text: message });
      return { success: true, method: 'webShare' };
    } catch (error) {
      if (error && error.name === 'AbortError') {
        return { success: false, method: 'cancelled' };
      }
      return { success: false, method: 'error', error: error?.message };
    }
  }

  try {
    const url = `${WHATSAPP_SHARE_URL}?text=${encodeURIComponent(message)}`;
    if (typeof window !== 'undefined' && typeof window.open === 'function') {
      window.open(url, '_blank', 'noopener,noreferrer');
      return { success: true, method: 'whatsappUrl' };
    }
    return { success: false, method: 'error', error: 'window.open unavailable' };
  } catch (error) {
    return { success: false, method: 'error', error: error?.message };
  }
}

export async function shareMatchResult(message) {
  return shareTextMessage(message);
}

export async function shareLiveMatchLink({
  identifier,
  ownTeamName,
  opponentName,
  matchStartLabel,
  kickoffInput
}) {
  const copyResult = await copyLiveMatchUrlToClipboard(identifier);
  const url = copyResult.url;
  const kickoffTime = formatKickoffTime(kickoffInput);
  const message = formatLiveMatchShareMessage({
    ownTeamName,
    opponentName,
    matchStartLabel,
    kickoffTime,
    liveUrl: url
  });
  const share = await shareTextMessage(message);
  return { url, copied: copyResult.success, share };
}

/**
 * Classify a shareLiveMatchLink result into the feedback a caller should show.
 * Keeps the three call sites from drifting on the copied/share.method logic.
 * 'copied'   -> link is on the clipboard: show the "copied" success toast.
 * 'shared'   -> no clipboard copy, but the native share sheet / WhatsApp opened.
 * 'fallback' -> neither worked (share errored or was cancelled with no copy):
 *               surface the URL so the user can grab it manually.
 */
export function getShareLinkFeedback(shareResult) {
  if (shareResult.copied) {
    return 'copied';
  }
  const method = shareResult.share?.method;
  if (method === 'webShare' || method === 'whatsappUrl') {
    return 'shared';
  }
  return 'fallback';
}
