import { useState, useEffect, useRef } from 'react';
import { useTranslation } from 'react-i18next';
import { supabase } from '../lib/supabase';
import { getActiveMatches } from '../services/matchStateManager';

async function resolveOwnerName(userId, cache) {
  if (!userId) return null;
  if (cache.has(userId)) return cache.get(userId);

  const { data, error } = await supabase
    .from('user_profile')
    .select('name')
    .eq('id', userId)
    .single();

  if (error || !data) {
    cache.set(userId, null);
    return null;
  }
  cache.set(userId, data.name);
  return data.name;
}

/**
 * Subscribe to real-time updates for team matches
 * Fetches initial active matches and subscribes to changes via Supabase Realtime
 *
 * @param {string} teamId - Team ID to subscribe to
 * @returns {{ matches: Array, loading: boolean, error: string|null, refetch: Function }}
 */
export function useRealtimeTeamMatches(teamId) {
  const { t } = useTranslation('team');
  const [matches, setMatches] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const subscriptionRef = useRef(null);
  const profileCacheRef = useRef(new Map());

  useEffect(() => {
    if (!teamId) {
      setMatches([]);
      setLoading(false);
      return;
    }

    let isActive = true;

    // Fetch initial matches
    const fetchMatches = async () => {
      try {
        setLoading(true);
        setError(null);
        const result = await getActiveMatches(teamId);

        if (result.success) {
          if (isActive) {
            // Seed profile cache from enriched results so realtime handlers can
            // look up names synchronously when the same owner reappears.
            (result.matches || []).forEach(match => {
              if (match.ownedBy) {
                profileCacheRef.current.set(match.ownedBy, match.ownedByName ?? null);
              }
            });
            setMatches(result.matches || []);
          }
        } else {
          if (isActive) {
            setError(result.error || t('teamMatches.error.loadFailed'));
          }
        }
      } catch (err) {
        console.error('Error fetching active matches:', err);
        if (isActive) {
          setError(t('teamMatches.error.loadFailed'));
        }
      } finally {
        if (isActive) {
          setLoading(false);
        }
      }
    };

    fetchMatches();

    // Subscribe to Realtime changes
    subscriptionRef.current = supabase
      .channel(`team_matches:${teamId}`)
      .on(
        'postgres_changes',
        {
          event: '*',
          schema: 'public',
          table: 'match',
          filter: `team_id=eq.${teamId}`
        },
        (payload) => {
          if (!isActive) return;

          console.log('Match change detected:', payload);

          const lookupOwnerName = (ownerId) =>
            ownerId ? (profileCacheRef.current.get(ownerId) ?? null) : null;

          const scheduleOwnerResolve = (ownerId, matchId) => {
            if (!ownerId || profileCacheRef.current.has(ownerId)) return;
            resolveOwnerName(ownerId, profileCacheRef.current).then((name) => {
              if (!isActive || name == null) return;
              setMatches(prev => prev.map(m => (
                m.id === matchId && m.ownedBy === ownerId
                  ? { ...m, ownedByName: name }
                  : m
              )));
            });
          };

          if (payload.eventType === 'INSERT') {
            const newMatch = payload.new;
            // Only add if it's planned, pending, or running
            if (newMatch.state === 'planned' || newMatch.state === 'pending' || newMatch.state === 'running') {
              setMatches(prev => [
                {
                  id: newMatch.id,
                  shareCode: newMatch.share_code || null,
                  opponent: newMatch.opponent || 'Internal Match',
                  state: newMatch.state,
                  createdAt: newMatch.created_at,
                  startedAt: newMatch.started_at,
                  plannedStartTime: newMatch.planned_start_time,
                  ownedBy: newMatch.owned_by,
                  ownedByName: lookupOwnerName(newMatch.owned_by),
                  takenOverAt: newMatch.taken_over_at ?? null,
                  type: newMatch.type,
                  venueType: newMatch.venue_type,
                  difficulty: newMatch.difficulty
                },
                ...prev
              ]);
              scheduleOwnerResolve(newMatch.owned_by, newMatch.id);
            }
          } else if (payload.eventType === 'UPDATE') {
            const updated = payload.new;

            // Remove match if it became finished
            if (updated.state === 'finished') {
              setMatches(prev => prev.filter(m => m.id !== updated.id));
            } else if (updated.state === 'planned' || updated.state === 'pending' || updated.state === 'running') {
              // Update existing match
              setMatches(prev => {
                const exists = prev.some(m => m.id === updated.id);

                if (exists) {
                  // Update existing
                  return prev.map(match =>
                    match.id === updated.id
                      ? {
                          ...match,
                          id: updated.id,
                          shareCode: updated.share_code || match.shareCode || null,
                          opponent: updated.opponent || 'Internal Match',
                          state: updated.state,
                          createdAt: updated.created_at,
                          startedAt: updated.started_at,
                          plannedStartTime: updated.planned_start_time,
                          ownedBy: updated.owned_by,
                          ownedByName: lookupOwnerName(updated.owned_by),
                          takenOverAt: updated.taken_over_at ?? null,
                          type: updated.type,
                          venueType: updated.venue_type,
                          difficulty: updated.difficulty
                        }
                      : match
                  );
                } else {
                  // Add new (in case it transitioned from finished to planned/pending/running)
                  return [
                    {
                      id: updated.id,
                      shareCode: updated.share_code || null,
                      opponent: updated.opponent || 'Internal Match',
                      state: updated.state,
                      createdAt: updated.created_at,
                      startedAt: updated.started_at,
                      plannedStartTime: updated.planned_start_time,
                      ownedBy: updated.owned_by,
                      ownedByName: lookupOwnerName(updated.owned_by),
                      takenOverAt: updated.taken_over_at ?? null,
                      type: updated.type,
                      venueType: updated.venue_type,
                      difficulty: updated.difficulty
                    },
                    ...prev
                  ];
                }
              });
              scheduleOwnerResolve(updated.owned_by, updated.id);
            }
          } else if (payload.eventType === 'DELETE') {
            // Remove deleted match
            setMatches(prev => prev.filter(m => m.id !== payload.old.id));
          }
        }
      )
      .on(
        'postgres_changes',
        {
          event: 'UPDATE',
          schema: 'public',
          table: 'upcoming_match',
          filter: `team_id=eq.${teamId}`
        },
        async (payload) => {
          if (!isActive) return;

          // When planned_match_id is set for the first time, a pending match was just linked
          // to this upcoming match. Refetch to get the correct matchDate/matchTime from the join.
          if (payload.new.planned_match_id && !payload.old.planned_match_id) {
            const result = await getActiveMatches(teamId);
            if (result.success && isActive) {
              (result.matches || []).forEach(match => {
                if (match.ownedBy) {
                  profileCacheRef.current.set(match.ownedBy, match.ownedByName ?? null);
                }
              });
              setMatches(result.matches || []);
            }
          }
        }
      )
      .subscribe();

    // Cleanup on unmount
    return () => {
      isActive = false;
      if (subscriptionRef.current) {
        subscriptionRef.current.unsubscribe();
      }
    };
  }, [teamId, setMatches, setLoading, setError, t]);

  // Refetch function for manual refresh
  const refetch = async () => {
    if (!teamId) return;

    try {
      setError(null);
      const result = await getActiveMatches(teamId);

      if (result.success) {
        (result.matches || []).forEach(match => {
          if (match.ownedBy) {
            profileCacheRef.current.set(match.ownedBy, match.ownedByName ?? null);
          }
        });
        setMatches(result.matches || []);
      } else {
        setError(result.error || t('teamMatches.error.loadFailed'));
      }
    } catch (err) {
      console.error('Error refetching active matches:', err);
      setError(t('teamMatches.error.loadFailed'));
    }
  };

  return {
    matches,
    loading,
    error,
    refetch
  };
}
