import { useCallback, useMemo } from 'react';
import { STORAGE_KEYS } from '../constants/storageKeys';
import { AUTO_SELECT_STRATEGY, DISTRIBUTION_STRATEGY, SINGLE_MATCH_STRATEGY } from '../constants/planMatchesConstants';
import { usePersistentState } from './usePersistentState';
import { areStatusMapsEqual } from '../utils/comparisonUtils';

const AUTO_SELECT_DEFAULT_STATE = {
  teamId: null,
  ensureCoverage: true,
  metric: AUTO_SELECT_STRATEGY.PRACTICES,
  distributionStrategy: DISTRIBUTION_STRATEGY.EQUAL,
  singleMatchStrategy: SINGLE_MATCH_STRATEGY.BY_METRIC,
  strongMatchId: null,
  targetCounts: {},
  lastSquadSize: null
};

const validateSingleMatchStrategy = (value, fallback = SINGLE_MATCH_STRATEGY.BY_METRIC) =>
  Object.values(SINGLE_MATCH_STRATEGY).includes(value) ? value : fallback;

export const useAutoSelectPreferences = (teamId) => {
  const [autoSelectPreferences, setAutoSelectPreferences] = usePersistentState(
    STORAGE_KEYS.PLAN_MATCH_AUTO_SELECT_SETTINGS,
    AUTO_SELECT_DEFAULT_STATE,
    teamId
  );

  const autoSelectSettings = useMemo(() => {
    const ensureCoverage = typeof autoSelectPreferences?.ensureCoverage === 'boolean'
      ? autoSelectPreferences.ensureCoverage
      : true;
    const metric = Object.values(AUTO_SELECT_STRATEGY).includes(autoSelectPreferences?.metric)
      ? autoSelectPreferences.metric
      : AUTO_SELECT_STRATEGY.PRACTICES;
    const distributionStrategy = Object.values(DISTRIBUTION_STRATEGY).includes(autoSelectPreferences?.distributionStrategy)
      ? autoSelectPreferences.distributionStrategy
      : DISTRIBUTION_STRATEGY.EQUAL;
    const singleMatchStrategy = validateSingleMatchStrategy(autoSelectPreferences?.singleMatchStrategy);
    const strongMatchId = autoSelectPreferences?.strongMatchId ?? null;
    return { ensureCoverage, metric, distributionStrategy, singleMatchStrategy, strongMatchId };
  }, [autoSelectPreferences?.ensureCoverage, autoSelectPreferences?.metric, autoSelectPreferences?.distributionStrategy, autoSelectPreferences?.singleMatchStrategy, autoSelectPreferences?.strongMatchId]);

  const targetCounts = useMemo(() => {
    if (autoSelectPreferences?.targetCounts && typeof autoSelectPreferences.targetCounts === 'object') {
      return autoSelectPreferences.targetCounts;
    }
    return {};
  }, [autoSelectPreferences?.targetCounts]);

  const setAutoSelectSettings = useCallback((updater) => {
    setAutoSelectPreferences((prev) => {
      const base = prev && typeof prev === 'object' ? prev : AUTO_SELECT_DEFAULT_STATE;
      const prevCoverage = typeof base.ensureCoverage === 'boolean' ? base.ensureCoverage : true;
      const prevMetric = Object.values(AUTO_SELECT_STRATEGY).includes(base.metric)
        ? base.metric
        : AUTO_SELECT_STRATEGY.PRACTICES;
      const prevDistribution = Object.values(DISTRIBUTION_STRATEGY).includes(base.distributionStrategy)
        ? base.distributionStrategy
        : DISTRIBUTION_STRATEGY.EQUAL;
      const prevSingleMatchStrategy = validateSingleMatchStrategy(base.singleMatchStrategy);
      const prevStrongMatchId = base.strongMatchId ?? null;
      const nextSettings = typeof updater === 'function'
        ? updater({ ensureCoverage: prevCoverage, metric: prevMetric, distributionStrategy: prevDistribution, singleMatchStrategy: prevSingleMatchStrategy, strongMatchId: prevStrongMatchId })
        : updater;
      const nextCoverage = typeof nextSettings?.ensureCoverage === 'boolean'
        ? nextSettings.ensureCoverage
        : prevCoverage;
      const nextMetric = Object.values(AUTO_SELECT_STRATEGY).includes(nextSettings?.metric)
        ? nextSettings.metric
        : prevMetric;
      const nextDistribution = Object.values(DISTRIBUTION_STRATEGY).includes(nextSettings?.distributionStrategy)
        ? nextSettings.distributionStrategy
        : prevDistribution;
      const nextSingleMatchStrategy = validateSingleMatchStrategy(nextSettings?.singleMatchStrategy, prevSingleMatchStrategy);
      const nextStrongMatchId = nextSettings?.strongMatchId ?? prevStrongMatchId;
      if (nextCoverage === prevCoverage && nextMetric === prevMetric &&
          nextDistribution === prevDistribution && nextSingleMatchStrategy === prevSingleMatchStrategy &&
          nextStrongMatchId === prevStrongMatchId) {
        return prev;
      }
      return {
        ...base,
        teamId: teamId ?? null,
        ensureCoverage: nextCoverage,
        metric: nextMetric,
        distributionStrategy: nextDistribution,
        singleMatchStrategy: nextSingleMatchStrategy,
        strongMatchId: nextStrongMatchId,
        targetCounts: base.targetCounts || {}
      };
    });
  }, [teamId, setAutoSelectPreferences]);

  const lastSquadSize = useMemo(() => {
    const stored = autoSelectPreferences?.lastSquadSize;
    return typeof stored === 'number' && stored > 0 ? stored : null;
  }, [autoSelectPreferences?.lastSquadSize]);

  const setLastSquadSize = useCallback((size) => {
    setAutoSelectPreferences((prev) => {
      const base = prev && typeof prev === 'object' ? prev : AUTO_SELECT_DEFAULT_STATE;
      const prevSize = typeof base.lastSquadSize === 'number' && base.lastSquadSize > 0 ? base.lastSquadSize : null;
      if (size === prevSize) {
        return prev;
      }
      return {
        ...base,
        teamId: teamId ?? null,
        lastSquadSize: size
      };
    });
  }, [teamId, setAutoSelectPreferences]);

  const setTargetCounts = useCallback((updater) => {
    setAutoSelectPreferences((prev) => {
      const base = prev && typeof prev === 'object' ? prev : AUTO_SELECT_DEFAULT_STATE;
      const prevTargets = base.targetCounts && typeof base.targetCounts === 'object' ? base.targetCounts : {};
      const nextTargets = typeof updater === 'function' ? updater(prevTargets) : updater;
      if (areStatusMapsEqual(prevTargets, nextTargets)) {
        return prev;
      }
      return {
        ...base,
        teamId: teamId ?? null,
        ensureCoverage: typeof base.ensureCoverage === 'boolean' ? base.ensureCoverage : true,
        metric: Object.values(AUTO_SELECT_STRATEGY).includes(base.metric)
          ? base.metric
          : AUTO_SELECT_STRATEGY.PRACTICES,
        targetCounts: nextTargets
      };
    });
  }, [teamId, setAutoSelectPreferences]);

  return {
    autoSelectSettings,
    targetCounts,
    lastSquadSize,
    setAutoSelectSettings,
    setTargetCounts,
    setLastSquadSize
  };
};
