import React, { useState, useEffect, useMemo, useCallback } from 'react';
import PropTypes from 'prop-types';
import { Calendar, Clock, Share2, AlertCircle, Eye, Play, Plus, Trash2 } from 'lucide-react';
import { Button, Input, NotificationModal, ConfirmationModal } from '../shared/UI';
import { CoachChip } from '../shared/CoachChip';
import { TimePickerInput } from '../shared/TimePicker';
import { Alert } from '../shared/Alert';
import { LoadingSpinner } from '../shared/LoadingSpinner';
import { EmptyState } from '../shared/EmptyState';
import { ModalShell } from '../shared/ModalShell';
import { useTeam } from '../../contexts/TeamContext';
import { useAuth } from '../../contexts/AuthContext';
import { useToast } from '../../contexts/ToastContext';
import { useTranslation } from 'react-i18next';
import { createGamePersistenceManager } from '../../utils/persistenceManager';
import { useRealtimeTeamMatches } from '../../hooks/useRealtimeTeamMatches';
import { useUpcomingTeamMatches } from '../../hooks/useUpcomingTeamMatches';
import { pickLiveMatchIdentifier } from '../../utils/liveMatchLinkUtils';
import { shareLiveMatchLink, getShareLinkFeedback } from '../../utils/shareUtils';
import { formatLocalDateTimeFromISO, getLocalDateTimeSortKeyFromISO } from '../../utils/timeUtils';
import { getDifficultyBadgeClasses } from '../../utils/badgeUtils';
import { VIEWS } from '../../constants/viewConstants';
import { getMatchDifficultyOptions } from '../../constants/matchDifficulties';
import { MANUAL_MATCH_SENTINEL_ID, MANUAL_MATCH_STATE, MAX_SIMULTANEOUS_MATCHES, PENDING_MATCH_STATE, PLANNED_MATCH_STATE } from '../../constants/planMatchesConstants';
import { discardPendingMatch } from '../../services/matchStateManager';
import { SelectTeamView } from './SelectTeamView';

/**
 * Team Matches List Screen
 * Shows active matches (planned/pending/running) and upcoming matches from connected providers
 * Allows coaches to copy live match links, resume setup, or navigate to LiveMatchScreen
 */
export function TeamMatchesScreen({ onNavigateBack, onNavigateTo, pushNavigationState, removeFromNavigationStack, onTakeOverMatch }) {
  const { t } = useTranslation(['team', 'configuration', 'common']);
  const { currentTeam, canManageTeam } = useTeam();
  const { user } = useAuth();
  const { showSuccess } = useToast();
  const localGameState = useMemo(() => createGamePersistenceManager().loadState(), []);
  const difficultyLabelByValue = useMemo(
    () => getMatchDifficultyOptions(t).reduce((acc, option) => {
      acc[option.value] = option.label;
      return acc;
    }, {}),
    [t]
  );
  const {
    matches: activeMatches,
    loading: activeMatchesLoading,
    error: activeMatchesError,
    refetch: refetchActiveMatches
  } = useRealtimeTeamMatches(currentTeam?.id);
  const {
    matches: upcomingMatches,
    loading: upcomingMatchesLoading,
    error: upcomingMatchesError,
    refetch: refetchUpcomingMatches
  } = useUpcomingTeamMatches(currentTeam?.id);
  const [notification, setNotification] = useState({ isOpen: false, title: '', message: '' });
  const [copyingMatchId, setCopyingMatchId] = useState(null);
  const [deletingMatchId, setDeletingMatchId] = useState(null);
  const [takeOverMatchId, setTakeOverMatchId] = useState(null);
  const [takingOverMatchId, setTakingOverMatchId] = useState(null);
  const [showPlanModal, setShowPlanModal] = useState(false);
  const [planSelectionIds, setPlanSelectionIds] = useState([]);
  const [showCreateMatchModal, setShowCreateMatchModal] = useState(false);
  const [newMatchOpponent, setNewMatchOpponent] = useState('');
  const [newMatchDate, setNewMatchDate] = useState('');
  const [newMatchTime, setNewMatchTime] = useState('');
  const plannedMatches = activeMatches.filter(match => match.state === PLANNED_MATCH_STATE);
  const orderedActiveMatches = [...activeMatches].sort((a, b) => {
    const stateOrder = {
      running: 0,
      pending: 1,
      planned: 2
    };
    const aOrder = stateOrder[a.state] ?? 99;
    const bOrder = stateOrder[b.state] ?? 99;

    if (aOrder !== bOrder) {
      return aOrder - bOrder;
    }

    const getScheduleSortKey = (match) => {
      if ((match?.state === PLANNED_MATCH_STATE || match?.state === PENDING_MATCH_STATE) && match?.matchDate) {
        return `${match.matchDate}T${(match.matchTime || '00:00:00').slice(0, 5)}`;
      }

      if (match?.plannedStartTime) {
        return getLocalDateTimeSortKeyFromISO(match.plannedStartTime);
      }

      return match?.createdAt || '';
    };

    const aScheduleKey = getScheduleSortKey(a);
    const bScheduleKey = getScheduleSortKey(b);
    if (aScheduleKey !== bScheduleKey) {
      return aScheduleKey.localeCompare(bScheduleKey);
    }

    return (a.createdAt || '').localeCompare(b.createdAt || '');
  });
  const plannableMatches = [...upcomingMatches, ...plannedMatches].sort((a, b) => {
    const getPlannableSortKey = (match) => {
      if (match?.matchDate) {
        return `${match.matchDate}T${(match.matchTime || '00:00:00').slice(0, 5)}`;
      }

      if (match?.plannedStartTime) {
        return getLocalDateTimeSortKeyFromISO(match.plannedStartTime);
      }

      return '';
    };

    const aKey = getPlannableSortKey(a);
    const bKey = getPlannableSortKey(b);
    if (!aKey && !bKey) return 0;
    if (!aKey) return 1;
    if (!bKey) return -1;
    return aKey.localeCompare(bKey);
  });

  const handleShareLink = async (match) => {
    setCopyingMatchId(match.id);

    try {
      const kickoffInput = match.state === 'running' ? match.startedAt : match.plannedStartTime;
      const shareResult = await shareLiveMatchLink({
        identifier: pickLiveMatchIdentifier(match),
        ownTeamName: currentTeam?.club?.name || currentTeam?.name,
        opponentName: match.opponent,
        matchStartLabel: t('common:share.matchStartLabel'),
        kickoffInput
      });

      const feedback = getShareLinkFeedback(shareResult);
      if (feedback === 'copied') {
        showSuccess(t('teamMatches.notifications.linkCopiedMessage'));
      } else if (feedback === 'fallback') {
        setNotification({
          isOpen: true,
          title: t('teamMatches.notifications.liveMatchUrl'),
          message: shareResult.url || t('teamMatches.notifications.couldNotCopy')
        });
      }
    } catch (err) {
      console.error('Failed to share link:', err);
      setNotification({
        isOpen: true,
        title: t('teamMatches.notifications.error'),
        message: t('teamMatches.error.copyFailed')
      });
    } finally {
      setCopyingMatchId(null);
    }
  };

  const isRunningMatchOwner = (match) =>
    match.state === 'running' &&
    match.ownedBy === user?.id &&
    localGameState.currentMatchId === match.id;

  const canTakeOverMatch = (match) =>
    match.state === 'running' &&
    match.ownedBy !== user?.id &&
    (currentTeam?.userRole === 'admin' || currentTeam?.userRole === 'coach');

  const handleConfirmTakeOver = useCallback(async () => {
    if (localGameState.currentMatchId && localGameState.currentMatchId !== takeOverMatchId) {
      setTakeOverMatchId(null);
      setNotification({
        isOpen: true,
        title: t('teamMatches.takeOver.blockedTitle'),
        message: t('teamMatches.takeOver.blockedMessage'),
      });
      return;
    }
    const matchIdToTakeOver = takeOverMatchId;
    setTakingOverMatchId(matchIdToTakeOver);
    setTakeOverMatchId(null);
    try {
      await onTakeOverMatch(matchIdToTakeOver);
    } catch {
      setNotification({
        isOpen: true,
        title: t('teamMatches.takeOver.errorTitle'),
        message: t('teamMatches.takeOver.errorMessage'),
      });
    } finally {
      setTakingOverMatchId(null);
    }
  }, [localGameState.currentMatchId, takeOverMatchId, setTakeOverMatchId, setNotification, setTakingOverMatchId, onTakeOverMatch, t]);

  const handleBackToMatch = (matchId) => {
    const targetView = localGameState.isPeriodSetupPending
      ? VIEWS.PERIOD_SETUP
      : VIEWS.GAME;
    onNavigateTo(targetView, { matchId });
  };

  const handleOpenLive = (matchId) => {
    // Navigate with data instead of imperative setters
    onNavigateTo(VIEWS.LIVE_MATCH, {
      matchId,
      entryPoint: VIEWS.TEAM_MATCHES
    });
  };

  const handleResumeSetup = (matchId) => {
    onNavigateTo(VIEWS.CONFIG, {
      resumeMatchId: matchId
    });
  };

  const handleSetupPlannedMatch = (matchId) => {
    onNavigateTo(VIEWS.CONFIG, {
      resumeMatchId: matchId
    });
  };

  const handleDeletePendingMatch = async (matchId) => {
    if (deletingMatchId) return;

    setDeletingMatchId(matchId);

    try {
      const result = await discardPendingMatch(matchId);

      if (result.success) {
        showSuccess(t('teamMatches.notifications.matchDeletedMessage'));
        await refetchActiveMatches();
      } else {
        setNotification({
          isOpen: true,
          title: t('teamMatches.notifications.error'),
          message: result.error || t('teamMatches.error.deleteFailed')
        });
      }
    } catch (err) {
      console.error('Failed to delete pending match:', err);
      setNotification({
        isOpen: true,
        title: t('teamMatches.notifications.error'),
        message: t('teamMatches.error.deleteFailed')
      });
    } finally {
      setDeletingMatchId(null);
    }
  };

  const handleRetry = async () => {
    await Promise.all([refetchActiveMatches(), refetchUpcomingMatches()]);
  };

  const openCreateMatchModal = () => {
    setNewMatchOpponent('');
    setNewMatchDate('');
    setNewMatchTime('');
    setShowCreateMatchModal(true);
    if (pushNavigationState) {
      pushNavigationState(() => setShowCreateMatchModal(false), 'TeamMatchesScreen-CreateMatchModal');
    }
  };

  const closeCreateMatchModal = () => {
    setShowCreateMatchModal(false);
    setNewMatchOpponent('');
    setNewMatchDate('');
    setNewMatchTime('');
    if (removeFromNavigationStack) {
      removeFromNavigationStack();
    }
  };

  const handleCreateNewMatch = (event) => {
    event?.preventDefault();

    const opponent = newMatchOpponent.trim();
    const plannedStartTime = newMatchDate
      ? new Date(`${newMatchDate}T${newMatchTime || '00:00'}`).toISOString()
      : null;
    closeCreateMatchModal();
    onNavigateTo(VIEWS.PLAN_MATCHES, {
      matchesToPlan: [{
        id: MANUAL_MATCH_SENTINEL_ID,
        state: MANUAL_MATCH_STATE,
        opponent,
        plannedStartTime
      }]
    });
  };

  const openPlanModal = (matchId) => {
    setPlanSelectionIds([matchId]);
    setShowPlanModal(true);
    if (pushNavigationState) {
      pushNavigationState(() => setShowPlanModal(false), 'TeamMatchesScreen-PlanModal');
    }
  };

  const closePlanModal = () => {
    setShowPlanModal(false);
    if (removeFromNavigationStack) {
      removeFromNavigationStack();
    }
  };

  const handlePlanMatch = (match) => {
    if (plannableMatches.length <= 1) {
      onNavigateTo(VIEWS.PLAN_MATCHES, {
        matchesToPlan: [match]
      });
      return;
    }

    openPlanModal(match.id);
  };

  const togglePlannedMatchSelection = (matchId) => {
    setPlanSelectionIds((prev) => {
      if (prev.includes(matchId)) {
        return prev.filter(id => id !== matchId);
      }
      if (prev.length >= MAX_SIMULTANEOUS_MATCHES) {
        return prev;
      }
      return [...prev, matchId];
    });
  };

  const confirmPlanSelection = () => {
    const selectedMatches = plannableMatches.filter(match => planSelectionIds.includes(match.id));
    if (selectedMatches.length === 0) {
      return;
    }

    closePlanModal();
    onNavigateTo(VIEWS.PLAN_MATCHES, {
      matchesToPlan: selectedMatches
    });
  };

  // Register browser back handler
  useEffect(() => {
    if (pushNavigationState) {
      pushNavigationState(() => {
        onNavigateBack();
      });
    }

    return () => {
      if (removeFromNavigationStack) {
        removeFromNavigationStack();
      }
    };
  }, [pushNavigationState, removeFromNavigationStack, onNavigateBack]);

  const formatIsoDate = (date) => {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const formatTimestamp = (timestamp) => {
    if (!timestamp) return t('teamMatches.timestamps.noDate');

    const date = new Date(timestamp);
    const now = new Date();
    const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const yesterday = new Date(today);
    yesterday.setDate(yesterday.getDate() - 1);

    if (date >= today) {
      return t('teamMatches.timestamps.today', { time: date.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' }) });
    } else if (date >= yesterday) {
      return t('teamMatches.timestamps.yesterday', { time: date.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' }) });
    }

    return formatIsoDate(date);
  };

  const formatActiveMatchSchedule = (match) => {
    // Planned and pending matches linked to an upcoming provider match should display provider schedule.
    if ((match?.state === 'planned' || match?.state === 'pending') && match?.matchDate) {
      return formatUpcomingSchedule(match.matchDate, match.matchTime);
    }
    if (match?.plannedStartTime) {
      const localSchedule = formatLocalDateTimeFromISO(match.plannedStartTime);
      if (localSchedule) {
        return localSchedule;
      }
    }
    return formatTimestamp(match?.createdAt);
  };

  const formatUpcomingMatchTime = (matchTime) => {
    if (!matchTime) return null;
    return matchTime.slice(0, 5);
  };

  const formatUpcomingSchedule = (matchDate, matchTime, plannedStartTime) => {
    if (matchDate) {
      const trimmedTime = formatUpcomingMatchTime(matchTime);
      return trimmedTime ? `${matchDate} ${trimmedTime}` : matchDate;
    }
    if (plannedStartTime) {
      const localSchedule = formatLocalDateTimeFromISO(plannedStartTime);
      if (localSchedule) return localSchedule;
    }
    return t('teamMatches.timestamps.dateTbd');
  };

  const getStateBadge = (state) => {
    if (state === 'running') {
      return (
        <span className="px-2 py-1 text-xs font-medium bg-emerald-600 text-emerald-100 rounded-full">
          {t('teamMatches.states.running')}
        </span>
      );
    } else if (state === 'pending') {
      return (
        <span className="px-2 py-1 text-xs font-medium bg-sky-600 text-sky-100 rounded-full">
          {t('teamMatches.states.pending')}
        </span>
      );
    } else if (state === 'planned') {
      return (
        <span className="px-2 py-1 text-xs font-medium bg-violet-600 text-violet-100 rounded-full">
          {t('teamMatches.states.planned')}
        </span>
      );
    } else if (state === 'upcoming') {
      return (
        <span className="px-2 py-1 text-xs font-medium bg-amber-600 text-amber-100 rounded-full">
          {t('teamMatches.states.upcoming')}
        </span>
      );
    }
    return null;
  };

  const hasActiveMatches = activeMatches.length > 0;
  const hasUpcomingMatches = upcomingMatches.length > 0;
  const isLoading = (activeMatchesLoading || upcomingMatchesLoading) && !hasActiveMatches && !hasUpcomingMatches;
  const errorMessage = activeMatchesError || upcomingMatchesError;
  const header = (
    <div className="flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between sm:gap-3">
      <h1 className="text-2xl font-bold text-sky-300">{t('teamMatches.title')}</h1>
      <div className="flex items-center gap-2">
        {canManageTeam && (
          <Button onClick={openCreateMatchModal} variant="accent" size="sm" Icon={Plus}>
            {t('teamMatches.createMatch.button')}
          </Button>
        )}
        <Button onClick={onNavigateBack} variant="secondary" size="sm">
          {t('teamMatches.back')}
        </Button>
      </div>
    </div>
  );
  const createMatchModal = showCreateMatchModal ? (
    <ModalShell
      title={t('teamMatches.createMatch.modalTitle')}
      onClose={closeCreateMatchModal}
      maxWidth="sm"
    >
      <form onSubmit={handleCreateNewMatch} className="space-y-4">
        <div>
          <label htmlFor="newMatchOpponent" className="block text-sm font-medium text-sky-200 mb-2">
            {t('teamMatches.createMatch.opponentLabel')}
          </label>
          <Input
            id="newMatchOpponent"
            value={newMatchOpponent}
            onChange={(event) => setNewMatchOpponent(event.target.value)}
            placeholder={t('teamMatches.createMatch.opponentPlaceholder')}
            maxLength={50}
            autoFocus
          />
        </div>
        <div>
          <label htmlFor="newMatchDate" className="block text-sm font-medium text-sky-200 mb-2">
            {t('teamMatches.createMatch.dateLabel')}
          </label>
          <Input
            type="date"
            id="newMatchDate"
            value={newMatchDate}
            onChange={(event) => setNewMatchDate(event.target.value)}
          />
        </div>
        <div>
          <label htmlFor="newMatchTime" className="block text-sm font-medium text-sky-200 mb-2">
            {t('teamMatches.createMatch.timeLabel')}
          </label>
          <TimePickerInput
            id="newMatchTime"
            value={newMatchTime}
            onChange={setNewMatchTime}
            placeholder={t('teamMatches.createMatch.timePlaceholder')}
          />
        </div>
        <div className="pt-4 border-t border-slate-600 flex flex-col sm:flex-row gap-2 sm:justify-end">
          <Button variant="secondary" onClick={closeCreateMatchModal}>
            {t('teamMatches.createMatch.cancel')}
          </Button>
          <Button type="submit" variant="accent">
            {t('teamMatches.createMatch.create')}
          </Button>
        </div>
      </form>
    </ModalShell>
  ) : null;

  if (!currentTeam) {
    return (
      <SelectTeamView
        subtitle={t('teamMatches.selectTeamSubtitle')}
        onNavigateBack={onNavigateBack}
        onCreateTeam={() => onNavigateTo(VIEWS.TEAM_MANAGEMENT)}
      />
    );
  }

  // Loading state
  if (isLoading) {
    return (
      <div className="space-y-6">
        {header}

        <div className="bg-slate-700 rounded-lg border border-slate-600 p-8">
          <LoadingSpinner size="sm" message={t('teamMatches.loading')} />
        </div>
        {createMatchModal}
      </div>
    );
  }

  // Error state
  if (errorMessage && !hasActiveMatches && !hasUpcomingMatches) {
    return (
      <div className="space-y-6">
        {header}

        <Alert variant="error" icon={AlertCircle}>
          <div>
            <p className="text-rose-200 font-medium">{t('teamMatches.error.loadFailed')}</p>
            <p className="text-rose-300 text-sm mt-1">{errorMessage}</p>
            <Button onClick={handleRetry} variant="secondary" size="sm" className="mt-3">
              {t('teamMatches.error.tryAgain')}
            </Button>
          </div>
        </Alert>
        {createMatchModal}
      </div>
    );
  }

  // Empty state
  if (!hasActiveMatches && !hasUpcomingMatches) {
    return (
      <div className="space-y-6">
        {header}

        <EmptyState
          icon={Calendar}
          title={t('teamMatches.empty.title')}
          message={t('teamMatches.empty.description')}
        />
        {canManageTeam && (
          <div className="flex justify-center">
            <Button onClick={openCreateMatchModal} variant="accent" Icon={Plus}>
              {t('teamMatches.createMatch.button')}
            </Button>
          </div>
        )}
        {createMatchModal}
      </div>
    );
  }

  // Matches list
  return (
    <div className="space-y-6">
      {header}

      {hasActiveMatches && (
        <div className="space-y-3">
          {orderedActiveMatches.map((match) => {
            const isPlanned = match.state === 'planned';
            const isPending = match.state === 'pending';
            const isLiveReady = match.state === 'pending' || match.state === 'running';
            const isDeleting = deletingMatchId === match.id;

            return (
              <div
                key={match.id}
                className="bg-slate-700 rounded-lg border border-slate-600 p-4 hover:bg-slate-600 transition-colors"
              >
                <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
                  <div className="flex-1 min-w-0 space-y-2">
                    <div className="flex items-start gap-2 flex-wrap">
                      <h3 className="text-base sm:text-lg font-semibold text-slate-100">
                        {match.opponent}
                      </h3>
                      {getStateBadge(match.state)}
                      {match.state === 'running' && match.ownedByName && (
                        <CoachChip name={match.ownedByName} size="sm" />
                      )}
                    </div>

                    <div className="flex items-center gap-2 sm:gap-3 text-xs sm:text-sm text-slate-400 flex-wrap">
                      <div className="flex items-center space-x-1">
                        <Clock className="w-3.5 h-3.5" />
                        <span>{formatActiveMatchSchedule(match)}</span>
                      </div>
                      {match.type && (
                        <span className="px-2 py-0.5 bg-slate-600 text-slate-300 rounded text-xs">
                          {t(`configuration:matchTypes.${match.type}.label`, { defaultValue: match.type })}
                        </span>
                      )}
                      {match.venueType && (
                        <span className="px-2 py-0.5 bg-slate-600 text-slate-300 rounded text-xs">
                          {t(`configuration:venueTypes.${match.venueType}.label`, { defaultValue: match.venueType })}
                        </span>
                      )}
                      {match.difficulty && (
                        <span className={getDifficultyBadgeClasses(match.difficulty)}>
                          {difficultyLabelByValue[match.difficulty] || match.difficulty}
                        </span>
                      )}
                    </div>
                  </div>

                  <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-2 w-full sm:w-auto">
                    {canManageTeam && isPlanned && (
                      <Button
                        onClick={() => handleSetupPlannedMatch(match.id)}
                        variant="primary"
                        size="sm"
                        Icon={Play}
                        className="w-full sm:w-auto"
                        disabled={isDeleting}
                      >
                        {t('teamMatches.buttons.setUpMatch')}
                      </Button>
                    )}
                    {canManageTeam && isPlanned && (
                      <Button
                        onClick={() => handlePlanMatch(match)}
                        variant="accent"
                        size="sm"
                        className="w-full sm:w-auto"
                        disabled={isDeleting}
                      >
                        {t('teamMatches.buttons.plan')}
                      </Button>
                    )}
                    {canManageTeam && isPending && (
                      <Button
                        onClick={() => handleResumeSetup(match.id)}
                        variant="accent"
                        size="sm"
                        Icon={Play}
                        className="w-full sm:w-auto"
                        disabled={isDeleting}
                      >
                        {t('teamMatches.buttons.resumeSetup')}
                      </Button>
                    )}
                    {isRunningMatchOwner(match) && (
                      <Button
                        onClick={() => handleBackToMatch(match.id)}
                        variant="accent"
                        size="sm"
                        Icon={Play}
                        className="w-full sm:w-auto"
                      >
                        {t('teamMatches.buttons.backToMatch')}
                      </Button>
                    )}
                    {canTakeOverMatch(match) && (
                      <Button
                        onClick={() => setTakeOverMatchId(match.id)}
                        variant="danger"
                        size="sm"
                        disabled={takingOverMatchId === match.id}
                        className="w-full sm:w-auto"
                      >
                        {takingOverMatchId === match.id
                          ? t('teamMatches.takeOver.takingOver')
                          : t('teamMatches.takeOver.button')}
                      </Button>
                    )}
                    {isLiveReady && (
                      <Button
                        onClick={() => handleOpenLive(match.id)}
                        variant="primary"
                        size="sm"
                        Icon={Eye}
                        className="w-full sm:w-auto"
                      >
                        {t('teamMatches.buttons.openLive')}
                      </Button>
                    )}
                    {isLiveReady && (
                      <Button
                        onClick={() => handleShareLink(match)}
                        variant="secondary"
                        size="sm"
                        Icon={Share2}
                        disabled={copyingMatchId === match.id}
                        className="w-full sm:w-auto"
                      >
                        {copyingMatchId === match.id ? t('teamMatches.buttons.sharing') : t('teamMatches.buttons.shareLink')}
                      </Button>
                    )}
                    {canManageTeam && (isPlanned || isPending) && (
                      <Button
                        onClick={() => handleDeletePendingMatch(match.id)}
                        variant="danger"
                        size="sm"
                        Icon={isDeleting ? undefined : Trash2}
                        disabled={isDeleting}
                        className="w-full sm:w-auto"
                      >
                        {isDeleting ? t('teamMatches.buttons.deleting') : t('teamMatches.buttons.delete')}
                      </Button>
                    )}
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {hasUpcomingMatches && (
        <div className="space-y-3">
          <div className="space-y-1">
            <h2 className="text-lg font-semibold text-slate-200">{t('teamMatches.upcoming.title')}</h2>
            <p className="text-xs text-slate-400">
              {t('teamMatches.upcoming.description')}
            </p>
          </div>
          {upcomingMatches.map((match) => (
            <div
              key={match.id}
              className="bg-slate-700 rounded-lg border border-amber-500/40 p-4 hover:bg-slate-600 transition-colors"
            >
              <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
                <div className="flex-1 min-w-0 space-y-2">
                  <div className="flex items-start gap-2 flex-wrap">
                    <h3 className="text-base sm:text-lg font-semibold text-slate-100">
                      {match.opponent}
                    </h3>
                    {getStateBadge('upcoming')}
                  </div>
                  <p className="text-xs text-amber-200">{t('teamMatches.upcoming.notPlanned')}</p>
                  <div className="flex items-center gap-2 sm:gap-3 text-xs sm:text-sm text-slate-400 flex-wrap">
                    <div className="flex items-center space-x-1">
                      <Calendar className="w-3.5 h-3.5" />
                      <span>{formatUpcomingSchedule(match.matchDate, match.matchTime)}</span>
                    </div>
                    {match.venue && (
                      <span className="px-2 py-0.5 bg-slate-600 text-slate-300 rounded text-xs">
                        {match.venue}
                      </span>
                    )}
                  </div>
                </div>

                {canManageTeam && (
                  <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-2 w-full sm:w-auto">
                    <Button
                      variant="accent"
                      size="sm"
                      className="w-full sm:w-auto"
                      onClick={() => handlePlanMatch(match)}
                    >
                      {t('teamMatches.buttons.plan')}
                    </Button>
                  </div>
                )}
              </div>
            </div>
          ))}
        </div>
      )}

      {showPlanModal && (
        <ModalShell
          title={t('teamMatches.planModal.title')}
          onClose={closePlanModal}
          maxWidth="lg"
        >
            <div className="space-y-3 max-h-[60vh] overflow-y-auto">
              {(() => {
                const maxReached = planSelectionIds.length >= MAX_SIMULTANEOUS_MATCHES;
                return plannableMatches.map((match) => {
                  const isSelected = planSelectionIds.includes(match.id);
                  const isDisabled = !isSelected && maxReached;
                  const scheduleLabel = formatUpcomingSchedule(match.matchDate, match.matchTime, match.plannedStartTime);
                  const stateLabel = match.state === 'planned'
                    ? t('teamMatches.states.planned')
                    : t('teamMatches.states.upcoming');
                  return (
                    <label
                      key={match.id}
                      className={`flex items-center justify-between gap-3 rounded-md border px-3 py-2 text-sm transition-colors ${
                        isDisabled
                          ? 'opacity-50 cursor-not-allowed border-slate-700 bg-slate-800/40 text-slate-400'
                          : isSelected
                            ? 'cursor-pointer border-sky-500 bg-sky-900/30 text-sky-100'
                            : 'cursor-pointer border-slate-600 bg-slate-700/40 text-slate-200 hover:border-slate-500'
                      }`}
                    >
                      <div className="flex items-center gap-3 min-w-0">
                        <input
                          type="checkbox"
                          checked={isSelected}
                          disabled={isDisabled}
                          onChange={() => togglePlannedMatchSelection(match.id)}
                          className="h-4 w-4 rounded border-slate-500 text-sky-500 focus:ring-sky-500"
                          aria-label={t('team:teamMatches.planModal.selectMatch', { opponent: match.opponent })}
                        />
                        <div className="min-w-0">
                          <div className="truncate font-medium">{match.opponent}</div>
                          <div className="text-xs text-slate-400">
                            {stateLabel} - {scheduleLabel}
                          </div>
                        </div>
                      </div>
                    </label>
                  );
                });
              })()}
              {planSelectionIds.length >= MAX_SIMULTANEOUS_MATCHES && (
                <p className="text-xs text-slate-400">
                  {t('teamMatches.planModal.maxMatchesReached', { max: MAX_SIMULTANEOUS_MATCHES })}
                </p>
              )}
            </div>
            <div className="pt-4 border-t border-slate-600 flex flex-col sm:flex-row gap-2 sm:justify-end">
              <Button variant="secondary" onClick={closePlanModal}>
                {t('teamMatches.planModal.cancel')}
              </Button>
              <Button
                variant="accent"
                onClick={confirmPlanSelection}
                disabled={planSelectionIds.length === 0}
              >
                {t('teamMatches.planModal.planSelected')}
              </Button>
            </div>
        </ModalShell>
      )}

      {createMatchModal}

      <NotificationModal
        isOpen={notification.isOpen}
        onClose={() => setNotification({ isOpen: false, title: '', message: '' })}
        title={notification.title}
        message={notification.message}
      />

      <ConfirmationModal
        isOpen={takeOverMatchId !== null}
        onConfirm={handleConfirmTakeOver}
        onCancel={() => setTakeOverMatchId(null)}
        title={t('teamMatches.takeOver.confirmTitle')}
        message={t('teamMatches.takeOver.confirmMessage')}
        confirmText={t('teamMatches.takeOver.confirmButton')}
        cancelText={t('common:cancel')}
        variant="danger"
      />

    </div>
  );
}

TeamMatchesScreen.propTypes = {
  onNavigateBack: PropTypes.func.isRequired,
  onNavigateTo: PropTypes.func.isRequired,
  pushNavigationState: PropTypes.func,
  removeFromNavigationStack: PropTypes.func,
  onTakeOverMatch: PropTypes.func.isRequired,
};
