import { createPersistenceManager } from './persistenceManager';
import { STORAGE_KEYS } from '../constants/storageKeys';

export const CONSENT_VERSION = 1;

export const CONSENT_CHANGE_EVENT = 'sportwizard:cookie-consent-changed';

export const CONSENT_STATUS = Object.freeze({
  UNSET: 'unset',
  GRANTED: 'granted',
  DENIED: 'denied',
});

export const CONSENT_DEFAULTS = Object.freeze({
  status: CONSENT_STATUS.UNSET,
  version: CONSENT_VERSION,
  decidedAt: null,
});

export const consentPersistence = createPersistenceManager(
  STORAGE_KEYS.COOKIE_CONSENT,
  { ...CONSENT_DEFAULTS }
);

export function loadConsent() {
  const stored = consentPersistence.loadState();
  if (!stored || stored.version !== CONSENT_VERSION) {
    return { ...CONSENT_DEFAULTS };
  }
  return stored;
}

function notifyConsentChanged() {
  // The `storage` event only fires in OTHER tabs, so same-tab hook instances
  // (e.g. CookieConsentBanner + PreferencesModal) need a separate signal to
  // stay in sync after a write.
  if (typeof window === 'undefined') return;
  window.dispatchEvent(new Event(CONSENT_CHANGE_EVENT));
}

export function saveConsent(status) {
  const result = consentPersistence.saveState({
    status,
    version: CONSENT_VERSION,
    decidedAt: new Date().toISOString(),
  });
  notifyConsentChanged();
  return result;
}

export function clearConsent() {
  const result = consentPersistence.clearState();
  notifyConsentChanged();
  return result;
}
