import React, { useState, useCallback, useEffect, useRef, useMemo } from 'react';
import PropTypes from 'prop-types';
import { ArrowRight, Users, Building, UserPlus, Check } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { Button, Input, ConfirmationModal } from '../shared/UI';
import { Alert } from '../shared/Alert';
import { Card } from '../shared/Card';
import { FormGroup } from '../shared/FormGroup';
import { ClubAutocomplete } from './ClubAutocomplete';
import { TeamAutocomplete } from './TeamAutocomplete';
import { ClubJoinModal } from './ClubJoinModal';
import { TeamAccessRequestModal } from './TeamAccessRequestModal';
import { useTeam } from '../../contexts/TeamContext';
import { useToast } from '../../contexts/ToastContext';
import { sanitizeNameInput } from '../../utils/inputSanitization';

const STEPS = {
  CLUB_SELECTION: 'club_selection',
  CLUB_CREATION: 'club_creation',
  TEAM_SELECTION: 'team_selection',
  TEAM_CREATION: 'team_creation',
  PLAYER_CREATION: 'player_creation',
  COMPLETE: 'complete'
};

export function TeamCreationWizard({ onComplete, onCancel, forceClubSelection = false }) {
  const { t } = useTranslation('team');
  const {
    createClub,
    getTeamsByClub,
    createTeam,
    createPlayer,
    switchCurrentTeam,
    demoTeam,
    deleteTeam,
    isClubCreator,
    isClubMember,
    hasClubs,
    userClubs,
    loading,
    error,
    clearError
  } = useTeam();

  // Wizard state
  const [currentStep, setCurrentStep] = useState(STEPS.CLUB_SELECTION);
  const [selectedClub, setSelectedClub] = useState(null);
  const [clubTeams, setClubTeams] = useState([]);
  const [createdTeam, setCreatedTeam] = useState(null);
  const [players, setPlayers] = useState([]);
  const [showClubJoinModal, setShowClubJoinModal] = useState(false);
  const [clubToJoin, setClubToJoin] = useState(null);
  const [showTeamAccessModal, setShowTeamAccessModal] = useState(false);
  const [selectedTeamForAccess, setSelectedTeamForAccess] = useState(null);
  const [showRemoveDemoModal, setShowRemoveDemoModal] = useState(false);
  const { showSuccess, showWarning } = useToast();
  // Once the user commits to a club, stop the init effect from re-deriving the step
  // when creating/joining a club refreshes userClubs (which would clobber progress).
  const userNavigatedRef = useRef(false);

  // Clubs the user already belongs to, surfaced as default suggestions so same-club joins stay one tap.
  const memberClubs = useMemo(
    () => (userClubs || []).map((m) => m.club).filter(Boolean),
    [userClubs]
  );

  // Form state
  const [clubForm, setClubForm] = useState({ name: '', shortName: '', longName: '' });
  const [teamForm, setTeamForm] = useState({ name: '' });
  const [playerForm, setPlayerForm] = useState({ displayName: '' });
  const [errors, setErrors] = useState({});

  const clearFormErrors = useCallback(() => {
    setErrors({});
    clearError();
  }, [clearError]);

  // Initialize wizard step based on user's club status. Stops once the user has
  // navigated, so a mid-flow userClubs refresh (create/join club) can't reset the step.
  useEffect(() => {
    if (userNavigatedRef.current) return;
    if (forceClubSelection) {
      // Caller wants cross-club choice (demo banner, profile create/join): never auto-select the sole club.
      setCurrentStep(STEPS.CLUB_SELECTION);
    } else if (hasClubs && userClubs.length === 1) {
      // If user has exactly one club, auto-select it and go to team selection
      const clubMembership = userClubs[0];
      const club = clubMembership.club; // Extract actual club object
      setSelectedClub(club);
      getTeamsByClub(club.id).then(teams => {
        setClubTeams(teams);
        setCurrentStep(STEPS.TEAM_SELECTION);
      });
    } else if (hasClubs && userClubs.length > 1) {
      // If user has multiple clubs, they need to choose which one
      // We could show a club selector, but for now let them use the regular flow
      setCurrentStep(STEPS.CLUB_SELECTION);
    } else {
      // If user has no clubs, start with club selection
      setCurrentStep(STEPS.CLUB_SELECTION);
    }
  }, [hasClubs, userClubs, getTeamsByClub, forceClubSelection]);

  // Handle club selection from autocomplete
  const handleClubSelect = useCallback(async (club) => {
    userNavigatedRef.current = true;
    clearFormErrors();

    // Already in this club (creator or member) → skip the join step. Creator check first: it reads created_by, so it holds even before userClubs syncs.
    if (isClubCreator(club) || isClubMember(club)) {
      setSelectedClub(club);
      const teams = await getTeamsByClub(club.id);
      setClubTeams(teams);
      setCurrentStep(STEPS.TEAM_SELECTION);
    } else {
      // Not a member yet — offer to join the club first.
      setClubToJoin(club);
      setShowClubJoinModal(true);
    }
  }, [getTeamsByClub, clearFormErrors, isClubCreator, isClubMember]);

  // Handle create new club from autocomplete
  const handleCreateNewClub = useCallback((clubName) => {
    userNavigatedRef.current = true;
    const displayName = clubName
      .split(' ')
      .filter(word => word !== word.toUpperCase())
      .join(' ');

    setClubForm({
      name: displayName.trim() || clubName,
      shortName: '',
      longName: clubName
    });
    setCurrentStep(STEPS.CLUB_CREATION);
  }, []);

  // Handle club creation
  const handleClubCreation = useCallback(async () => {
    clearFormErrors();

    // Validation
    if (!clubForm.name.trim()) {
      setErrors({ clubName: t('wizard.validation.clubNameRequired') });
      return;
    }

    const club = await createClub({
      name: clubForm.name.trim(),
      shortName: clubForm.shortName.trim() || null,
      longName: clubForm.longName.trim() || null
    });

    if (club) {
      setSelectedClub(club);
      setClubTeams([]); // New club has no teams
      setCurrentStep(STEPS.TEAM_CREATION);
    }
  }, [clubForm, createClub, clearFormErrors, t]);

  // Handle create new team from autocomplete
  const handleCreateNewTeam = useCallback((teamName) => {
    setTeamForm({ name: teamName });
    setCurrentStep(STEPS.TEAM_CREATION);
  }, []);

  // Handle existing team selection - show team access request modal
  const handleExistingTeamSelect = useCallback((team) => {
    clearError(); // Clear any previous error messages from team creation
    // Enhance team object with club information
    const enhancedTeam = {
      ...team,
      club: selectedClub // selectedClub already contains long_name
    };
    setSelectedTeamForAccess(enhancedTeam);
    setShowTeamAccessModal(true);
  }, [clearError, selectedClub]);

  // Handle team creation
  const handleTeamCreation = useCallback(async () => {
    clearFormErrors();

    // Validation
    if (!teamForm.name.trim()) {
      setErrors({ teamName: t('wizard.validation.teamNameRequired') });
      return;
    }

    const team = await createTeam({
      clubId: selectedClub.id,
      name: teamForm.name.trim()
    });

    if (team) {
      setCreatedTeam(team);
      // Switch to the newly created team
      await switchCurrentTeam(team.id);
      setCurrentStep(STEPS.PLAYER_CREATION);
    }
  }, [teamForm, selectedClub, createTeam, switchCurrentTeam, clearFormErrors, t]);

  // Handle player creation
  const handleAddPlayer = useCallback(async () => {
    clearFormErrors();

    // Validation
    if (!playerForm.displayName.trim()) {
      setErrors({ playerName: t('wizard.validation.playerNameRequired') });
      return;
    }

    const trimmedName = playerForm.displayName.trim();
    const [firstName, ...lastNameParts] = trimmedName.split(/\s+/);
    const player = await createPlayer({
      firstName: firstName || trimmedName,
      lastName: lastNameParts.length > 0 ? lastNameParts.join(' ') : null,
      displayName: trimmedName
    });

    if (player) {
      const normalizedPlayer = {
        ...player,
        displayName: player.display_name || trimmedName,
        firstName: player.first_name || firstName || trimmedName,
        lastName: player.last_name ?? (lastNameParts.length > 0 ? lastNameParts.join(' ') : null)
      };
      setPlayers(prev => [...prev, normalizedPlayer]);
      setPlayerForm({ displayName: '' });
    }
  }, [playerForm, createPlayer, clearFormErrors, t]);

  // Handle wizard completion
  const handleComplete = useCallback(() => {
    setCurrentStep(STEPS.COMPLETE);
    // Small delay to show success, then complete
    setTimeout(() => {
      // First real team created while a demo team still exists: offer to remove it.
      if (demoTeam && createdTeam && createdTeam.id !== demoTeam.id) {
        setShowRemoveDemoModal(true);
      } else {
        onComplete();
      }
    }, 1500);
  }, [onComplete, demoTeam, createdTeam]);

  // Remove the demo team and switch to the new real team; always complete.
  // A failed removal still switches and warns rather than stranding the user.
  const handleRemoveDemoConfirm = useCallback(async () => {
    setShowRemoveDemoModal(false);
    if (demoTeam) {
      try {
        await deleteTeam(demoTeam);
      } catch (err) {
        showWarning(t('demo.removePrompt.error'));
      }
    }
    if (createdTeam) {
      try {
        await switchCurrentTeam(createdTeam.id);
      } catch (err) {
        console.error('Failed to switch to the new team after demo removal:', err);
      }
    }
    onComplete();
  }, [demoTeam, deleteTeam, createdTeam, switchCurrentTeam, onComplete, showWarning, t]);

  // Keep the demo team, but still switch to the new real team.
  const handleRemoveDemoCancel = useCallback(async () => {
    setShowRemoveDemoModal(false);
    if (createdTeam) {
      try {
        await switchCurrentTeam(createdTeam.id);
      } catch (err) {
        console.error('Failed to switch to the new team:', err);
      }
    }
    onComplete();
  }, [createdTeam, switchCurrentTeam, onComplete]);

  // Handle club join modal success
  const handleClubJoinSuccess = useCallback(async () => {
    if (!clubToJoin) return;
    
    // Close modal
    setShowClubJoinModal(false);
    
    // Set as selected club and proceed to team selection
    setSelectedClub(clubToJoin);
    const teams = await getTeamsByClub(clubToJoin.id);
    setClubTeams(teams);
    setCurrentStep(STEPS.TEAM_SELECTION);
    
    // Clear modal state
    setClubToJoin(null);
  }, [clubToJoin, getTeamsByClub]);

  // Handle club join modal close
  const handleClubJoinClose = useCallback(() => {
    setShowClubJoinModal(false);
    setClubToJoin(null);
  }, []);

  // Handle team access request modal success
  const handleTeamAccessSuccess = useCallback((message) => {
    if (message) {
      showSuccess(message);
    }

    // Toast persists independently of the wizard, so close immediately.
    setShowTeamAccessModal(false);
    setSelectedTeamForAccess(null);
    // No team was created — flag the outcome so the parent confirms the request, not a creation.
    onComplete({ accessRequested: true });
  }, [onComplete, showSuccess]);

  // Handle team access request modal close
  const handleTeamAccessClose = useCallback(() => {
    setShowTeamAccessModal(false);
    setSelectedTeamForAccess(null);
  }, []);

  const renderClubSelection = () => (
    <div className="space-y-4">
      <div className="text-center mb-6">
        <Building className="h-8 w-8 text-sky-400 mx-auto mb-3" />
        <h3 className="text-lg font-semibold text-sky-300">{t('wizard.clubSelection.title')}</h3>
        <p className="text-slate-400 text-sm mt-2">
          {t('wizard.clubSelection.description')}
        </p>
      </div>

      <ClubAutocomplete
        placeholder={t('wizard.clubSelection.placeholder')}
        onSelect={handleClubSelect}
        onCreateNew={handleCreateNewClub}
        defaultClubs={memberClubs}
      />

      <div className="flex justify-end">
        <Button onClick={onCancel} variant="secondary">
          {t('wizard.clubSelection.cancel')}
        </Button>
      </div>
    </div>
  );

  const renderClubCreation = () => (
    <div className="space-y-4">
      <div className="text-center mb-6">
        <Building className="h-8 w-8 text-emerald-400 mx-auto mb-3" />
        <h3 className="text-lg font-semibold text-sky-300">{t('wizard.clubCreation.title')}</h3>
        <p className="text-slate-400 text-sm mt-2">
          {t('wizard.clubCreation.description')}
        </p>
      </div>

      <FormGroup label={t('wizard.clubCreation.fullNameLabel')} htmlFor="clubLongName" error={errors.clubLongName}>
        <Input
          id="clubLongName"
          value={clubForm.longName}
          onChange={(e) => setClubForm(prev => ({ ...prev, longName: sanitizeNameInput(e.target.value) }))}
          placeholder={t('wizard.clubCreation.fullNamePlaceholder')}
          error={!!errors.clubLongName}
        />
      </FormGroup>

      <FormGroup label={t('wizard.clubCreation.displayNameLabel')} htmlFor="clubName" error={errors.clubName}>
        <Input
          id="clubName"
          value={clubForm.name}
          onChange={(e) => setClubForm(prev => ({ ...prev, name: sanitizeNameInput(e.target.value) }))}
          placeholder={t('wizard.clubCreation.displayNamePlaceholder')}
          error={!!errors.clubName}
        />
      </FormGroup>

      <FormGroup label={t('wizard.clubCreation.shortNameLabel')} htmlFor="clubShortName">
        <Input
          id="clubShortName"
          value={clubForm.shortName}
          onChange={(e) => setClubForm(prev => ({ ...prev, shortName: sanitizeNameInput(e.target.value) }))}
          placeholder={t('wizard.clubCreation.shortNamePlaceholder')}
        />
        <p className="text-slate-500 text-xs mt-1">{t('wizard.clubCreation.shortNameHelper')}</p>
      </FormGroup>

      <div className="flex justify-end">
        <Button
          onClick={handleClubCreation}
          disabled={loading}
          Icon={loading ? null : ArrowRight}
        >
          {loading ? t('wizard.clubCreation.creating') : t('wizard.clubCreation.createButton')}
        </Button>
      </div>
    </div>
  );

  const renderTeamSelection = () => {
    const description = t('wizard.teamSelection.description', { clubName: selectedClub.name });
    const parts = description.split(/(<strong>.*?<\/strong>)/);

    return (
      <div className="space-y-4">
        <div className="text-center mb-6">
          <Users className="h-8 w-8 text-sky-400 mx-auto mb-3" />
          <h3 className="text-lg font-semibold text-sky-300">{t('wizard.teamSelection.title')}</h3>
          <p className="text-slate-400 text-sm mt-2">
            {parts.map((part, index) => {
              if (part.startsWith('<strong>') && part.endsWith('</strong>')) {
                const text = part.replace(/<\/?strong>/g, '');
                return <strong key={index}>{text}</strong>;
              }
              return <span key={index}>{part}</span>;
            })}
          </p>
        </div>

        <TeamAutocomplete
          teams={clubTeams}
          onSelect={handleExistingTeamSelect}
          onCreateNew={handleCreateNewTeam}
          placeholder={t('wizard.teamSelection.placeholder')}
          loading={loading}
        />

        <div className="flex justify-end">
          <Button onClick={onCancel} variant="secondary">
            {t('wizard.clubSelection.cancel')}
          </Button>
        </div>
      </div>
    );
  };

  const renderTeamCreation = () => {
    const description = t('wizard.teamCreation.description', { clubName: selectedClub.name });
    const parts = description.split(/(<strong>.*?<\/strong>)/);

    return (
      <div className="space-y-4">
        <div className="text-center mb-6">
          <Users className="h-8 w-8 text-emerald-400 mx-auto mb-3" />
          <h3 className="text-lg font-semibold text-sky-300">{t('wizard.teamCreation.title')}</h3>
          <p className="text-slate-400 text-sm mt-2">
            {parts.map((part, index) => {
              if (part.startsWith('<strong>') && part.endsWith('</strong>')) {
                const text = part.replace(/<\/?strong>/g, '');
                return <strong key={index}>{text}</strong>;
              }
              return <span key={index}>{part}</span>;
            })}
          </p>
        </div>

        <FormGroup label={t('wizard.teamCreation.teamNameLabel')} htmlFor="teamName" error={errors.teamName}>
          <Input
            id="teamName"
            value={teamForm.name}
            onChange={(e) => setTeamForm(prev => ({ ...prev, name: sanitizeNameInput(e.target.value) }))}
            placeholder={t('wizard.teamCreation.teamNamePlaceholder')}
            error={!!errors.teamName}
          />
          <p className="text-slate-500 text-xs mt-1">{t('wizard.teamCreation.teamNameHelper')}</p>
        </FormGroup>

        <div className="flex justify-end">
          <Button
            onClick={handleTeamCreation}
            disabled={loading}
            Icon={loading ? null : ArrowRight}
          >
            {loading ? t('wizard.teamCreation.creating') : t('wizard.teamCreation.createButton')}
          </Button>
        </div>
      </div>
    );
  };

  const renderPlayerCreation = () => {
    const description = t('wizard.playerCreation.description', { teamName: createdTeam?.name });
    const parts = description.split(/(<strong>.*?<\/strong>)/);

    return (
      <div className="space-y-4">
        <div className="text-center mb-6">
          <UserPlus className="h-8 w-8 text-emerald-400 mx-auto mb-3" />
          <h3 className="text-lg font-semibold text-sky-300">{t('wizard.playerCreation.title')}</h3>
          <p className="text-slate-400 text-sm mt-2">
            {parts.map((part, index) => {
              if (part.startsWith('<strong>') && part.endsWith('</strong>')) {
                const text = part.replace(/<\/?strong>/g, '');
                return <strong key={index}>{text}</strong>;
              }
              return <span key={index}>{part}</span>;
            })}
          </p>
        </div>

        <div className="flex space-x-2">
          <div className="flex-1">
            <Input
              value={playerForm.displayName}
              onChange={(e) => setPlayerForm(prev => ({ ...prev, displayName: sanitizeNameInput(e.target.value) }))}
              placeholder={t('wizard.playerCreation.playerNamePlaceholder')}
              error={!!errors.playerName}
              onKeyDown={(e) => {
                if (e.key === 'Enter' && playerForm.displayName.trim()) {
                  handleAddPlayer();
                }
              }}
            />
            {errors.playerName && (
              <p className="text-rose-400 text-sm mt-1">{errors.playerName}</p>
            )}
          </div>
          <Button
            onClick={handleAddPlayer}
            disabled={loading || !playerForm.displayName.trim()}
            Icon={UserPlus}
          >
            {t('wizard.playerCreation.addButton')}
          </Button>
        </div>

        {players.length > 0 && (
          <div className="space-y-2">
            <h4 className="text-sm font-medium text-slate-300">{t('wizard.playerCreation.addedPlayersHeader', { count: players.length })}</h4>
            <div className="max-h-32 overflow-y-auto space-y-1">
              {players.map((player) => (
                <div key={player.id} className="flex items-center p-2 bg-slate-700 rounded text-sm">
                  <span className="text-slate-100">{player.displayName || player.display_name || player.first_name}</span>
                </div>
              ))}
            </div>
          </div>
        )}

        <Card variant="subtle" className="text-center">
          <p className="text-slate-300 text-sm">
            {t('wizard.playerCreation.laterNote')}
          </p>
        </Card>

        <div className="flex justify-end">
          <Button
            onClick={handleComplete}
            variant="accent"
            Icon={Check}
          >
            {t('wizard.playerCreation.completeButton')}
          </Button>
        </div>
      </div>
    );
  };

  const renderComplete = () => {
    const description = t('wizard.complete.description', { teamName: createdTeam?.name });
    const parts = description.split(/(<strong>.*?<\/strong>)/);

    return (
      <div className="text-center py-8">
        <div className="animate-pulse">
          <Check className="h-12 w-12 text-emerald-400 mx-auto mb-4" />
        </div>
        <h3 className="text-lg font-semibold text-emerald-300 mb-2">{t('wizard.complete.title')}</h3>
        <p className="text-slate-400">
          {parts.map((part, index) => {
            if (part.startsWith('<strong>') && part.endsWith('</strong>')) {
              const text = part.replace(/<\/?strong>/g, '');
              return <strong key={index}>{text}</strong>;
            }
            return <span key={index}>{part}</span>;
          })}
        </p>
      </div>
    );
  };

  const renderCurrentStep = () => {
    switch (currentStep) {
      case STEPS.CLUB_SELECTION:
        return renderClubSelection();
      case STEPS.CLUB_CREATION:
        return renderClubCreation();
      case STEPS.TEAM_SELECTION:
        return renderTeamSelection();
      case STEPS.TEAM_CREATION:
        return renderTeamCreation();
      case STEPS.PLAYER_CREATION:
        return renderPlayerCreation();
      case STEPS.COMPLETE:
        return renderComplete();
      default:
        return renderClubSelection();
    }
  };

  return (
    <>
      <Card padding="lg">
        {error && (
          <Alert variant="error" className="mb-4">{error}</Alert>
        )}

        {renderCurrentStep()}
      </Card>

      {/* Club Join Modal */}
      {showClubJoinModal && clubToJoin && (
        <ClubJoinModal
          club={clubToJoin}
          onSuccess={handleClubJoinSuccess}
          onClose={handleClubJoinClose}
        />
      )}

      {/* Team Access Request Modal */}
      {showTeamAccessModal && selectedTeamForAccess && (
        <TeamAccessRequestModal
          team={selectedTeamForAccess}
          onSuccess={handleTeamAccessSuccess}
          onClose={handleTeamAccessClose}
        />
      )}

      {/* Offer to remove the demo team after the first real team is created */}
      <ConfirmationModal
        isOpen={showRemoveDemoModal}
        onConfirm={handleRemoveDemoConfirm}
        onCancel={handleRemoveDemoCancel}
        title={t('demo.removePrompt.title')}
        message={t('demo.removePrompt.message')}
        confirmText={t('demo.removePrompt.confirm')}
        cancelText={t('demo.removePrompt.cancel')}
        variant="danger"
      />
    </>
  );
}

TeamCreationWizard.propTypes = {
  onComplete: PropTypes.func.isRequired,
  onCancel: PropTypes.func.isRequired,
  forceClubSelection: PropTypes.bool,
};
