/**
 * Date utilities shared across services and components.
 */

/**
 * Compute the [startOfToday, startOfTomorrow) ISO range in the local timezone.
 * Returns ISO 8601 strings so the caller can pass them directly to PostgREST
 * timestamptz filters.
 *
 * Lives in utils (rather than alongside its first caller) so multiple services
 * can share it without creating a circular import.
 * @param {Date} [now=new Date()] - Reference instant; defaults to now.
 * @returns {{startOfTodayISO: string, startOfTomorrowISO: string}}
 */
export function getLocalDayBoundsISO(now = new Date()) {
  const startOfToday = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const startOfTomorrow = new Date(startOfToday);
  startOfTomorrow.setDate(startOfTomorrow.getDate() + 1);
  return {
    startOfTodayISO: startOfToday.toISOString(),
    startOfTomorrowISO: startOfTomorrow.toISOString()
  };
}
