import { logEvent, EVENT_TYPES, calculateMatchTime, getAllEvents, markEventAsUndone, updateEventData } from '../../utils/gameEventLogger';
import { OWN_GOAL_SCORER_ID } from '../../constants/playerConstants';

export const createScoreHandlers = (
  stateUpdaters,
  modalHandlers,
  options = {}
) => {
  const { 
    setScore,
    addGoalScored,
    addGoalConceded
  } = stateUpdaters;
  
  const { 
    openScoreEditModal, 
    closeScoreEditModal, 
    openGoalScorerModal, 
    closeGoalScorerModal,
    setPendingGoalData,
    getPendingGoalData,
    clearPendingGoal
  } = modalHandlers;
  const {
    shouldTrackGoalScorer = true,
    shouldTrackAssists = false,
    getPlayerNameById = null
  } = options;

  // An assist is prompted only for a real, named scorer (skip own goals and
  // "no specific scorer"). The assister can't be the scorer.
  const isRealScorer = (scorerId) => !!scorerId && scorerId !== OWN_GOAL_SCORER_ID;

  const resolvePlayerDisplayName = (playerId) => {
    if (!playerId || typeof getPlayerNameById !== 'function') {
      return null;
    }

    try {
      return getPlayerNameById(playerId) || null;
    } catch (error) {
      return null;
    }
  };

  // Generate unique event ID for goals
  const generateEventId = () => {
    const timestamp = Date.now();
    const random = Math.random().toString(36).substr(2, 9);
    return `evt_${timestamp}_${random}`;
  };

  // Unified helper to find event by ID with proper error handling
  const findEventById = (eventId) => {
    const allEvents = getAllEvents();
    const event = allEvents.find(e => e.id === eventId && !e.undone);
    
    if (!event) {
      console.warn(`Goal event not found: ${eventId}`);
      return null;
    }
    
    return event;
  };

  // Helper to determine team type from event type
  const getTeamFromEventType = (eventType) => {
    return eventType === EVENT_TYPES.GOAL_SCORED ? 'scored' : 'conceded';
  };

  // Helper to create pending goal data structure
  const createPendingGoalData = (goalType, eventId, gameState) => {
    const { ownScore, opponentScore, currentPeriodNumber, currentMatchId } = gameState;
    const now = Date.now();

    return {
      eventId,
      type: goalType === 'scored' ? EVENT_TYPES.GOAL_SCORED : EVENT_TYPES.GOAL_CONCEDED,
      periodNumber: currentPeriodNumber,
      ownScore: goalType === 'scored' ? ownScore + 1 : ownScore,
      opponentScore: goalType === 'conceded' ? opponentScore + 1 : opponentScore,
      goalType: goalType,
      matchId: currentMatchId,
      timestamp: now
    };
  };

  // Unified goal handling for both goals scored and conceded
  const handleAddGoal = (goalType, gameState = null) => {
    // For backward compatibility, if no gameState provided, just add goal immediately
    if (!gameState) {
      if (goalType === 'scored') {
        addGoalScored();
      } else {
        addGoalConceded();
      }
      return;
    }
    
    const eventId = generateEventId();
    const pendingGoalData = createPendingGoalData(goalType, eventId, gameState);
    
    if (goalType === 'scored') {
      // If goal scorer tracking is disabled, log immediately without modal flow
      if (!shouldTrackGoalScorer) {
        if (clearPendingGoal) {
          clearPendingGoal();
        }

        addGoalScored();

        logEvent(pendingGoalData.type, {
          eventId: pendingGoalData.eventId,
          periodNumber: pendingGoalData.periodNumber,
          ownScore: pendingGoalData.ownScore,
          opponentScore: pendingGoalData.opponentScore,
          scorerId: null,
          goalType: pendingGoalData.goalType,
          matchId: gameState.currentMatchId
        }, pendingGoalData.timestamp);

        return;
      }

      // Store as pending goal, don't increment score yet
      setPendingGoalData(pendingGoalData);
      
      // Open goal scorer modal for own team goals scored only
      if (openGoalScorerModal) {
        openGoalScorerModal({
          eventId,
          goalType,
          mode: 'new',
          // A team-click always starts a fresh goal at the scorer step — reset
          // any sticky assist-step state left over from a prior goal.
          selectionType: 'scorer',
          excludePlayerId: null,
          currentScorerId: null,
          matchTime: calculateMatchTime(pendingGoalData.timestamp),
          periodNumber: pendingGoalData.periodNumber
        });
      } else {
        console.error('Goal scorer modal not available - cannot process goal with gameState');
        console.error('This indicates a configuration problem. Modal handlers may not be properly initialized.');
        // Clear pending data to prevent orphaning
        if (clearPendingGoal) {
          clearPendingGoal();
        }
        return;
      }
    } else {
      // For opponent team goals: immediately increment score and log event (no modal)
      addGoalConceded();
      
      // Log the goal event immediately with no scorer attribution
      logEvent(pendingGoalData.type, {
        eventId: pendingGoalData.eventId,
        periodNumber: pendingGoalData.periodNumber,
        ownScore: pendingGoalData.ownScore,
        opponentScore: pendingGoalData.opponentScore,
        scorerId: null, // No scorer attribution for opponent goals
        goalType: pendingGoalData.goalType,
        matchId: gameState.currentMatchId
      }, pendingGoalData.timestamp);
    }
  };

  const handleAddGoalScored = (gameState = null) => {
    return handleAddGoal('scored', gameState);
  };

  const handleAddGoalConceded = (gameState = null) => {
    return handleAddGoal('conceded', gameState);
  };

  // Finalize a pending (new) goal, logging the goal_scored/goal_conceded event with
  // the resolved scorer and (optionally) assist attribution.
  const finalizePendingGoal = (pendingGoal, scorerId, assistId = null) => {
    if (pendingGoal.type === EVENT_TYPES.GOAL_SCORED) {
      addGoalScored();
    } else if (pendingGoal.type === EVENT_TYPES.GOAL_CONCEDED) {
      addGoalConceded();
    }

    const scorerName = resolvePlayerDisplayName(scorerId);
    const assistName = resolvePlayerDisplayName(assistId);

    logEvent(pendingGoal.type, {
      eventId: pendingGoal.eventId,
      periodNumber: pendingGoal.periodNumber,
      ownScore: pendingGoal.ownScore,
      opponentScore: pendingGoal.opponentScore,
      scorerId: scorerId || null,
      ...(scorerName ? { scorerName, display_name: scorerName } : {}),
      ...(assistId ? { assistId } : {}),
      ...(assistName ? { assist_display_name: assistName } : {}),
      goalType: pendingGoal.goalType,
      matchId: pendingGoal.matchId
    }, pendingGoal.timestamp);

    clearPendingGoal();
  };

  const handleSelectGoalScorer = (eventId, scorerId) => {
    if (!shouldTrackGoalScorer) {
      closeGoalScorerModal();
      return;
    }

    // Get pending goal data
    const pendingGoal = getPendingGoalData();

    if (!pendingGoal || pendingGoal.eventId !== eventId) {
      // Stale handoff: drop the orphaned pending record and close. The modal no
      // longer self-closes, so this path must clean up on its own.
      clearPendingGoal();
      closeGoalScorerModal();
      return;
    }

    // When assist tracking is on and a real scorer was chosen, prompt for the
    // assister before finalizing instead of closing the modal.
    if (shouldTrackAssists && isRealScorer(scorerId) && openGoalScorerModal) {
      setPendingGoalData({ ...pendingGoal, scorerId });
      openGoalScorerModal({
        eventId,
        goalType: pendingGoal.goalType,
        mode: 'new',
        selectionType: 'assist',
        excludePlayerId: scorerId,
        currentScorerId: null,
        matchTime: calculateMatchTime(pendingGoal.timestamp),
        periodNumber: pendingGoal.periodNumber
      });
      return;
    }

    finalizePendingGoal(pendingGoal, scorerId, null);
    closeGoalScorerModal();
  };

  // Second capture step: the assister was selected for a pending goal.
  const handleSelectAssist = (eventId, assistId) => {
    const pendingGoal = getPendingGoalData();

    if (!pendingGoal || pendingGoal.eventId !== eventId) {
      // Stale handoff: drop the orphaned pending record before closing, matching
      // handleSelectGoalScorer's mismatch path.
      clearPendingGoal();
      closeGoalScorerModal();
      return;
    }

    finalizePendingGoal(pendingGoal, pendingGoal.scorerId || null, assistId || null);
    closeGoalScorerModal();
  };

  const handleCorrectGoalScorer = (eventId, newScorerId) => {
    if (!shouldTrackGoalScorer) {
      closeGoalScorerModal();
      return;
    }

    const scorerName = resolvePlayerDisplayName(newScorerId);
    const updatePayload = {
      scorerId: newScorerId
    };

    if (scorerName) {
      updatePayload.scorerName = scorerName;
      updatePayload.display_name = scorerName;
    }

    // Changing the scorer to an own goal / no-scorer clears any prior assist —
    // an assist only makes sense for a real, named scorer.
    if (!isRealScorer(newScorerId)) {
      updatePayload.assistId = null;
      updatePayload.assist_display_name = null;
    }

    // Update the original goal event with new scorer
    const updateSuccess = updateEventData(eventId, updatePayload);

    if (updateSuccess) {
      const isOwnGoal = newScorerId === OWN_GOAL_SCORER_ID;
      // Log correction event for audit trail and to drive DB update of the
      // original goal_scored/goal_conceded row (see eventPersistenceService).
      logEvent(EVENT_TYPES.GOAL_CORRECTED, {
        originalEventId: eventId,
        scorerId: newScorerId,
        scorerName: scorerName || null,
        isOwnGoal,
        correctionType: 'scorer_correction'
      });

      // When assist tracking is on and the corrected scorer is real, prompt to
      // change/clear the assist as a follow-up step. Only after a successful
      // scorer update — otherwise the assist could be patched onto an event
      // whose scorer never changed, leaving the two inconsistent.
      if (shouldTrackAssists && isRealScorer(newScorerId) && openGoalScorerModal) {
        const goalEvent = findEventById(eventId);
        openGoalScorerModal({
          eventId,
          team: goalEvent ? getTeamFromEventType(goalEvent.type) : 'scored',
          mode: 'correct',
          selectionType: 'assist',
          excludePlayerId: newScorerId,
          // On the assist step, currentScorerId is overloaded to carry the
          // current assister's ID so GoalScorerModal pre-selects them.
          currentScorerId: goalEvent?.data?.assistId || null,
          matchTime: goalEvent ? calculateMatchTime(goalEvent.timestamp) : '00:00',
          periodNumber: goalEvent?.data?.periodNumber || 1
        });
        return;
      }
    } else {
      console.warn('Failed to update goal scorer for event:', eventId);
    }

    closeGoalScorerModal();
  };

  // Edit/clear the assist on an existing goal (correction follow-up step).
  const handleCorrectAssist = (eventId, newAssistId) => {
    const assistName = resolvePlayerDisplayName(newAssistId);
    const updatePayload = {
      assistId: newAssistId || null,
      assist_display_name: newAssistId ? (assistName || null) : null
    };

    const updateSuccess = updateEventData(eventId, updatePayload);

    if (updateSuccess) {
      logEvent(EVENT_TYPES.GOAL_CORRECTED, {
        originalEventId: eventId,
        assistId: newAssistId || null,
        assistName: assistName || null,
        correctionType: 'assist_correction'
      });
    } else {
      console.warn('Failed to update goal assist for event:', eventId);
    }

    closeGoalScorerModal();
  };

  // Removed: handleUndoGoal function

  const handleDeleteGoal = (eventId, gameState = null) => {
    // Find the goal event to delete
    const goalEvent = findEventById(eventId);

    if (!goalEvent) {
      // Warning already logged in findEventById
      return;
    }

    // Verify this is actually a goal event
    if (![EVENT_TYPES.GOAL_SCORED, EVENT_TYPES.GOAL_CONCEDED].includes(goalEvent.type)) {
      console.warn(`Attempted to delete non-goal event: ${eventId}, type: ${goalEvent.type}`);
      return;
    }

    // Mark the goal as undone using the proper function
    const markSuccess = markEventAsUndone(goalEvent.id, 'manual_deletion');

    if (!markSuccess) {
      console.error(`Failed to mark goal event as undone: ${eventId}`);
      return;
    }

    // Get updated events after marking as undone
    const updatedEvents = getAllEvents();

    const remainingGoals = updatedEvents.filter(event =>
      [EVENT_TYPES.GOAL_SCORED, EVENT_TYPES.GOAL_CONCEDED].includes(event.type) && !event.undone
    );

    const newOwnScore = remainingGoals.filter(goal => goal.type === EVENT_TYPES.GOAL_SCORED).length;
    const newOpponentScore = remainingGoals.filter(goal => goal.type === EVENT_TYPES.GOAL_CONCEDED).length;

    setScore(newOwnScore, newOpponentScore);

    const periodNumber = gameState?.currentPeriodNumber ?? goalEvent.data?.periodNumber ?? null;

    logEvent(EVENT_TYPES.GOAL_DELETED, {
      originalEventId: goalEvent.id,
      periodNumber,
      ownScore: newOwnScore,
      opponentScore: newOpponentScore
    });
  };

  const handleEditGoalScorer = (eventId) => {
    if (!shouldTrackGoalScorer) {
      return;
    }

    // Open goal scorer modal for editing existing goal
    if (!openGoalScorerModal) {
      console.warn('Goal scorer modal not available for editing');
      return;
    }

    const goalEvent = findEventById(eventId);
    if (!goalEvent) {
      // Warning already logged in findEventById
      return;
    }

    openGoalScorerModal({
      eventId: goalEvent.id,
      team: getTeamFromEventType(goalEvent.type),
      mode: 'correct',
      selectionType: 'scorer',
      matchTime: calculateMatchTime(goalEvent.timestamp),
      periodNumber: goalEvent.data?.periodNumber || 1,
      currentScorerId: goalEvent.data?.scorerId || null
    });
  };

  const handleScoreEdit = (newOwnScore, newOpponentScore) => {
    setScore(newOwnScore, newOpponentScore);
    closeScoreEditModal();
  };

  const handleOpenScoreEdit = () => {
    openScoreEditModal();
  };

  const scoreCallback = () => {
    handleOpenScoreEdit();
  };

  const handleCancelGoalScorer = () => {
    // Get and clear pending goal data
    const pendingGoal = getPendingGoalData();

    if (pendingGoal) {
      // If the coach backs out of the assist step (scorer already chosen),
      // the goal is still real — finalize it with the scorer and no assist
      // rather than discarding the goal entirely.
      if (pendingGoal.scorerId) {
        finalizePendingGoal(pendingGoal, pendingGoal.scorerId, null);
      } else {
        clearPendingGoal();
      }
    }

    closeGoalScorerModal();
  };
  
  return {
    handleAddGoalScored,
    handleAddGoalConceded,
    handleSelectGoalScorer,
    handleSelectAssist,
    handleCorrectGoalScorer,
    handleCorrectAssist,
    handleScoreEdit,
    handleOpenScoreEdit,
    handleCancelGoalScorer,
    handleDeleteGoal,
    handleEditGoalScorer,
    scoreCallback
  };
};
