import React from 'react';
import { useTranslation } from 'react-i18next';
import { Download, X } from 'lucide-react';
import { useInstallPrompt } from '../../hooks/useInstallPrompt';

/**
 * Compact "Install Sport Wizard" call-to-action used inside AuthModal.
 * Renders nothing when the browser hasn't fired beforeinstallprompt, when
 * the app is already installed, when running natively (Capacitor), or when
 * the user has dismissed the prompt previously.
 */
export function InstallAppCTA() {
  const { t } = useTranslation('auth');
  const { canInstall, promptInstall, dismiss } = useInstallPrompt();

  if (!canInstall) return null;

  return (
    <div aria-live="polite" className="mt-4 rounded-md border border-slate-600 bg-slate-700/40 p-3 flex items-start gap-3">
      <Download className="h-5 w-5 text-sky-400 flex-shrink-0 mt-0.5" aria-hidden="true" />
      <div className="flex-1 min-w-0">
        <p className="text-sm text-slate-200">{t('authModal.install.label')}</p>
        <div className="mt-2 flex items-center gap-3">
          <button
            type="button"
            onClick={() => promptInstall()}
            className="px-3 py-1 text-sm font-medium rounded-md bg-sky-600 hover:bg-sky-500 text-white"
          >
            {t('authModal.install.button')}
          </button>
          <button
            type="button"
            onClick={dismiss}
            className="px-3 py-1 text-sm text-slate-300 hover:text-slate-100"
          >
            {t('authModal.install.dismiss')}
          </button>
        </div>
      </div>
      <button
        type="button"
        onClick={dismiss}
        aria-label={t('authModal.install.dismiss')}
        className="text-slate-400 hover:text-slate-200"
      >
        <X className="h-4 w-4" aria-hidden="true" />
      </button>
    </div>
  );
}
