import React, { useState, useMemo, useEffect } from 'react';
import { User, Award, Clock, Users, Target } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { useTeam } from '../../contexts/TeamContext';
import { getFinishedMatches, getPlayerStats } from '../../services/matchStateManager';
import { getTeamLoans, getDefaultLoanMatchWeight } from '../../services/playerLoanService';
import { formatMinutesAsTime, formatSecondsAsTime, formatMatchCount } from '../../utils/formatUtils';
import { MatchFiltersPanel } from './MatchFiltersPanel';
import { useStatsFilters } from '../../hooks/useStatsFilters';
import { filterMatchesByCriteria } from '../../utils/matchFilterUtils';
import { STORAGE_KEYS } from '../../constants/storageKeys';
import { useTableSort } from '../../hooks/useTableSort';
import { useColumnOrderPersistence } from '../../hooks/useColumnOrderPersistence';
import { StatCard } from './shared/StatCard';
import { StatsLoadingState } from './shared/StatsLoadingState';
import { StatsErrorState } from './shared/StatsErrorState';
import { StatsEmptyState } from './shared/StatsEmptyState';
import { SortableStatsTable } from './shared/SortableStatsTable';
import { Alert } from '../shared/Alert';
import { useMatchWeightsPreference } from '../../hooks/useMatchWeightsPreference';
import { useTrackingPreferences } from '../../hooks/useTrackingPreferences';

const SORT_COLUMNS = {
  NAME: 'displayName',
  MATCHES: 'weightedMatchesIncludingLoans',
  ACTUAL_MATCHES: 'actualMatches',
  ACTUAL_MATCHES_INCLUDING_LOANS: 'actualMatchesIncludingLoans',
  GOALS: 'goalsScored',
  ASSISTS: 'assists',
  AVG_TIME: 'averageTimePerMatch',
  AVG_TIME_ACTUAL: 'averageTimePerMatchActual',
  TOTAL_TIME: 'totalFieldTimeSeconds',
  SUB_START: 'percentStartedAsSubstitute',
  DEFENDER: 'percentTimeAsDefender',
  MIDFIELDER: 'percentTimeAsMidfielder',
  ATTACKER: 'percentTimeAsAttacker',
  GOALKEEPER: 'percentTimeAsGoalkeeper',
  CAPTAIN: 'matchesAsCaptain',
  FAIR_PLAY: 'fairPlayAwards',
  LOAN_MATCHES: 'loanMatches'
};

export function PlayerStatsTab({ startDate, endDate }) {
  const { t } = useTranslation('statistics');
  const { currentTeam, loadTeamPreferences, isParent, relatedPlayerIds, teamPlayers } = useTeam();
  const [players, setPlayers] = useState([]);
  const [matches, setMatches] = useState([]);
  const [loading, setLoading] = useState(false);
  const [matchesLoading, setMatchesLoading] = useState(false);
  const [error, setError] = useState(null);
  const [matchesError, setMatchesError] = useState(null);
  const [loanWeight, setLoanWeight] = useState(getDefaultLoanMatchWeight());
  const [prefResult, setPrefResult] = useState(null);
  const useMatchWeights = useMatchWeightsPreference({ teamId: currentTeam?.id, loadTeamPreferences, prefResult });
  const { trackGoalScorer, trackAssists } = useTrackingPreferences({ teamId: currentTeam?.id, loadTeamPreferences, prefResult });
  const [loanMap, setLoanMap] = useState(new Map());
  const [loanError, setLoanError] = useState(null);
  const {
    typeFilter,
    outcomeFilter,
    venueFilter,
    opponentFilter,
    playerFilter,
    formatFilter,
    difficultyFilter,
    setTypeFilter,
    setOutcomeFilter,
    setVenueFilter,
    setOpponentFilter,
    setPlayerFilter,
    setFormatFilter,
    setDifficultyFilter,
    clearFilters
  } = useStatsFilters();

  // When any filter-panel filter is active, loans are excluded from the stats view —
  // loan records carry no type/outcome/venue/format/difficulty data to evaluate filters against.
  const isAnyFilterActive = useMemo(
    () => (
      typeFilter.length > 0 ||
      outcomeFilter.length > 0 ||
      venueFilter.length > 0 ||
      opponentFilter.length > 0 ||
      playerFilter.length > 0 ||
      formatFilter.length > 0 ||
      difficultyFilter.length > 0
    ),
    [typeFilter, outcomeFilter, venueFilter, opponentFilter, playerFilter, formatFilter, difficultyFilter]
  );

  // Fetch matches for populating filter options
  useEffect(() => {
    async function fetchMatches() {
      if (!currentTeam?.id) {
        setMatches([]);
        setMatchesError(null);
        setMatchesLoading(false);
        return;
      }

      setMatchesLoading(true);
      setMatchesError(null);

      const result = await getFinishedMatches(currentTeam.id, startDate, endDate);

      if (result.success) {
        setMatches(result.matches || []);
      } else {
        setMatchesError(result.error || t('playerStats.failedToLoadMatches'));
        setMatches([]);
      }

      setMatchesLoading(false);
    }

    fetchMatches();
  }, [currentTeam?.id, startDate, endDate, t]);

  // Fetch loan data and loan weight preference
  useEffect(() => {
    async function fetchLoanData() {
      if (!currentTeam?.id) {
        setLoanMap(new Map());
        setLoanWeight(getDefaultLoanMatchWeight());
        setLoanError(null);
        return;
      }

      setLoanError(null);

      try {
        const [loanResult, prefData] = await Promise.all([
          getTeamLoans(currentTeam.id, { startDate, endDate }),
          loadTeamPreferences ? loadTeamPreferences(currentTeam.id) : Promise.resolve({})
        ]);

        if (loanResult.success) {
          const nextMap = new Map();
          (loanResult.loans || []).forEach((loan) => {
            if (!loan?.player_id) return;
            const existing = nextMap.get(loan.player_id) || [];
            existing.push(loan);
            nextMap.set(loan.player_id, existing);
          });
          setLoanMap(nextMap);
        } else {
          setLoanMap(new Map());
          setLoanError(loanResult.error || t('playerStats.failedToLoadLoanMatches'));
        }

        const weightValue = prefData?.loanMatchWeight;
        const parsedWeight = typeof weightValue === 'number' ? weightValue : parseFloat(weightValue);
        setLoanWeight(Number.isNaN(parsedWeight) ? getDefaultLoanMatchWeight() : parsedWeight);

        setPrefResult(prefData);
      } catch (err) {
        console.error('Failed to load loan data:', err);
        setLoanMap(new Map());
        setLoanError(t('playerStats.failedToLoadLoanMatches'));
        setLoanWeight(getDefaultLoanMatchWeight());
      }
    }

    fetchLoanData();
  }, [currentTeam?.id, startDate, endDate, loadTeamPreferences, t]);

  // Fetch player stats from database
  useEffect(() => {
    async function fetchPlayerStats() {
      if (!currentTeam?.id) {
        setPlayers([]);
        return;
      }

      setLoading(true);
      setError(null);

      const result = await getPlayerStats(currentTeam.id, startDate, endDate, {
        typeFilter,
        outcomeFilter,
        venueFilter,
        opponentFilter,
        playerFilter,
        formatFilter,
        difficultyFilter
      });

      if (result.success) {
        setPlayers(result.players || []);
      } else {
        setError(result.error || t('playerStats.errorDetails'));
        setPlayers([]);
      }

      setLoading(false);
    }

    fetchPlayerStats();
  }, [
    currentTeam?.id,
    startDate,
    endDate,
    typeFilter,
    outcomeFilter,
    venueFilter,
    opponentFilter,
    playerFilter,
    formatFilter,
    difficultyFilter,
    t
  ]);

  const enhancedPlayers = useMemo(() => {
    const weight = Number.isFinite(loanWeight) ? loanWeight : getDefaultLoanMatchWeight();
    const playersById = new Map(players.map(player => [player.id, player]));
    const supplementalPlayers = [];

    // Loan-only players are surfaced only when no filter-panel filter is active.
    if (!isAnyFilterActive) {
      loanMap.forEach((loans, playerId) => {
        if (playersById.has(playerId)) return;
        const loanPlayer = loans.find((loan) => loan?.player)?.player;
        const displayName = loanPlayer?.display_name || loanPlayer?.first_name || t('playerStats.unnamedPlayer');

        supplementalPlayers.push({
          id: playerId,
          displayName,
          weightedMatches: 0,
          actualMatches: 0,
          goalsScored: 0,
          assists: 0,
          totalFieldTimeSeconds: 0,
          averageTimePerMatch: 0,
          percentStartedAsSubstitute: 0,
          percentTimeAsDefender: 0,
          percentTimeAsMidfielder: 0,
          percentTimeAsAttacker: 0,
          percentTimeAsGoalkeeper: 0,
          matchesAsCaptain: 0,
          fairPlayAwards: 0
        });
      });
    }

    return [...players, ...supplementalPlayers].map((player) => {
      const loans = isAnyFilterActive ? [] : (loanMap.get(player.id) || []);
      const loanMatches = loans.length;
      const weightedLoanMatches = loanMatches * weight;
      const totalWeightedMatches = player.weightedMatches + weightedLoanMatches;
      // Use weightedLoanMatches (not raw loanMatches) to match connectorService.js logic.
      // loanMatchWeight always applies to loan matches regardless of the useMatchWeights preference.
      const totalActualMatches = player.actualMatches + weightedLoanMatches;

      return {
        ...player,
        loanMatches,
        weightedMatchesIncludingLoans: totalWeightedMatches,
        actualMatchesIncludingLoans: totalActualMatches,
        loanWeight: weight
      };
    });
  }, [players, loanMap, loanWeight, t, isAnyFilterActive]);

  const filteredMatches = useMemo(() => {
    return filterMatchesByCriteria(matches, {
      typeFilter,
      outcomeFilter,
      venueFilter,
      opponentFilter,
      playerFilter,
      formatFilter,
      difficultyFilter,
      startDate,
      endDate
    });
  }, [
    matches,
    typeFilter,
    outcomeFilter,
    venueFilter,
    opponentFilter,
    playerFilter,
    formatFilter,
    difficultyFilter,
    startDate,
    endDate
  ]);

  const clearAllFilters = clearFilters;

  // Parents only see rows for players they're related to (frontend-only restriction). Non-parents get the original array by reference.
  const visiblePlayers = useMemo(() => {
    if (!isParent) return enhancedPlayers;
    const allowed = new Set(relatedPlayerIds);
    return enhancedPlayers.filter((p) => allowed.has(p.id));
  }, [enhancedPlayers, isParent, relatedPlayerIds]);

  // Define table columns
  const baseColumns = useMemo(
    () => [
      {
        key: SORT_COLUMNS.NAME,
        label: t('playerStats.columns.player'),
        sortable: true,
        className: 'text-left font-medium',
        render: (player) => (
          <div className="flex items-center space-x-2">
            <User className="h-4 w-4 text-slate-400" />
            <span className="text-slate-100">{player.displayName}</span>
          </div>
        )
      },
      ...(useMatchWeights ? [
        {
          key: SORT_COLUMNS.MATCHES,
          label: t('playerStats.columns.matches'),
          sortable: true,
          className: 'text-center',
          render: (player) => (
            <span className="text-slate-300 font-mono">{formatMatchCount(player.weightedMatchesIncludingLoans)}</span>
          )
        },
        {
          key: SORT_COLUMNS.ACTUAL_MATCHES,
          label: t('playerStats.columns.actualMatches'),
          sortable: true,
          className: 'text-center',
          render: (player) => (
            <span className="text-slate-300 font-mono">{player.actualMatches}</span>
          )
        },
      ] : [
        {
          key: SORT_COLUMNS.ACTUAL_MATCHES_INCLUDING_LOANS,
          label: t('playerStats.columns.matchesActual'),
          sortable: true,
          className: 'text-center',
          render: (player) => (
            <span className="text-slate-300 font-mono">{player.actualMatchesIncludingLoans}</span>
          )
        },
      ]),
      {
        key: SORT_COLUMNS.LOAN_MATCHES,
        label: t('playerStats.columns.loanMatches'),
        sortable: true,
        className: 'text-center',
        render: (player) => (
          <span className="text-slate-300 font-mono">
            {player.loanMatches > 0 ? player.loanMatches : '-'}
          </span>
        )
      },
      ...(trackGoalScorer ? [{
        key: SORT_COLUMNS.GOALS,
        label: t('playerStats.columns.goals'),
        sortable: true,
        className: 'text-center',
        render: (player) => (
          <span className="text-slate-300 font-mono">{player.goalsScored}</span>
        )
      }] : []),
      ...(trackAssists ? [{
        key: SORT_COLUMNS.ASSISTS,
        label: t('playerStats.columns.assists'),
        sortable: true,
        className: 'text-center',
        render: (player) => (
          <span className="text-slate-300 font-mono">{player.assists ?? 0}</span>
        )
      }] : []),
      {
        key: useMatchWeights ? SORT_COLUMNS.AVG_TIME : SORT_COLUMNS.AVG_TIME_ACTUAL,
        label: t('playerStats.columns.avgTime'),
        sortable: true,
        className: 'text-center',
        render: (player) => (
          <div className="flex items-center justify-center space-x-1">
            <span className="text-slate-300 font-mono">{formatMinutesAsTime(useMatchWeights ? player.averageTimePerMatch : player.averageTimePerMatchActual)}</span>
          </div>
        )
      },
      {
        key: SORT_COLUMNS.TOTAL_TIME,
        label: t('playerStats.columns.outfieldTime'),
        sortable: true,
        className: 'text-center',
        render: (player) => (
          <span className="text-slate-300 font-mono">{formatSecondsAsTime(player.totalFieldTimeSeconds)}</span>
        )
      },
      {
        key: SORT_COLUMNS.SUB_START,
        label: t('playerStats.columns.startedAsSub'),
        sortable: true,
        className: 'text-center',
        render: (player) => (
          <span className="text-slate-300 font-mono">{player.percentStartedAsSubstitute}%</span>
        )
      },
      {
        key: SORT_COLUMNS.DEFENDER,
        label: t('playerStats.columns.defender'),
        sortable: true,
        className: 'text-center',
        render: (player) => (
          <span className="text-slate-300 font-mono">{player.percentTimeAsDefender}%</span>
        )
      },
      {
        key: SORT_COLUMNS.MIDFIELDER,
        label: t('playerStats.columns.midfielder'),
        sortable: true,
        className: 'text-center',
        render: (player) => (
          <span className="text-slate-300 font-mono">{player.percentTimeAsMidfielder}%</span>
        )
      },
      {
        key: SORT_COLUMNS.ATTACKER,
        label: t('playerStats.columns.attacker'),
        sortable: true,
        className: 'text-center',
        render: (player) => (
          <span className="text-slate-300 font-mono">{player.percentTimeAsAttacker}%</span>
        )
      },
      {
        key: SORT_COLUMNS.GOALKEEPER,
        label: t('playerStats.columns.goalkeeper'),
        sortable: true,
        className: 'text-center',
        render: (player) => (
          <span className="text-slate-300 font-mono">{player.percentTimeAsGoalkeeper}%</span>
        )
      },
      {
        key: SORT_COLUMNS.CAPTAIN,
        label: t('playerStats.columns.captain'),
        sortable: true,
        className: 'text-center',
        render: (player) => (
          <span className="text-slate-300 font-mono">{player.matchesAsCaptain}</span>
        )
      },
      {
        key: SORT_COLUMNS.FAIR_PLAY,
        label: t('playerStats.columns.fairPlay'),
        sortable: true,
        className: 'text-center',
        render: (player) => (
          <span className="text-slate-300 font-mono">{player.fairPlayAwards}</span>
        )
      }
    ],
    [t, useMatchWeights, trackGoalScorer, trackAssists]
  );

  // Use column order persistence hook
  const dragDropHandlers = useColumnOrderPersistence(
    baseColumns,
    STORAGE_KEYS.STATISTICS_PLAYER_COLUMN_ORDER
  );

  // Use table sort hook
  const {
    sortedData: sortedPlayers,
    sortBy,
    handleSort,
    renderSortIndicator
  } = useTableSort(visiblePlayers, SORT_COLUMNS.NAME, 'asc', dragDropHandlers.isReordering);

  // Calculate summary statistics
  const summaryStats = useMemo(() => {
    if (visiblePlayers.length === 0) {
      return {
        totalPlayers: 0,
        averageFieldTime: 0,
        averageGoalsPerPlayer: 0,
        totalGoals: 0,
        topScorer: null
      };
    }

    const totalPlayers = visiblePlayers.length;
    const totalFieldTime = visiblePlayers.reduce((sum, player) => sum + player.averageTimePerMatch, 0);
    const averageFieldTime = totalFieldTime / totalPlayers;
    const totalGoals = visiblePlayers.reduce((sum, player) => sum + player.goalsScored, 0);
    const averageGoalsPerPlayer = totalGoals / totalPlayers;
    const topScorer = visiblePlayers.reduce((top, player) =>
      player.goalsScored > top.goalsScored ? player : top
    );

    return {
      totalPlayers,
      averageFieldTime,
      averageGoalsPerPlayer,
      totalGoals,
      topScorer
    };
  }, [visiblePlayers]);

  const hasPlayerData = sortedPlayers.length > 0;
  // Gate on a loaded roster (teamPlayers populated) so a parent doesn't flash this state while relationships are still resolving on boot.
  // A genuinely player-less team also fails this guard and falls through to the generic "no data" state — intended, since there's nothing to link to.
  const parentHasNoRelatedPlayers = isParent && (teamPlayers?.length ?? 0) > 0 && relatedPlayerIds.length === 0;
  // Loans are excluded by filters, so they shouldn't keep an "empty" state from showing.
  const effectiveLoanCount = isAnyFilterActive ? 0 : loanMap.size;
  const noMatchesAvailable = !matchesLoading && matches.length === 0 && effectiveLoanCount === 0;
  const noMatchesForFilters = !matchesLoading && matches.length > 0 && filteredMatches.length === 0 && effectiveLoanCount === 0;
  const isReady = !loading && !error;

  return (
    <div className="space-y-6">
      {/* Filters */}
      <MatchFiltersPanel
        matches={matches}
        typeFilter={typeFilter}
        outcomeFilter={outcomeFilter}
        venueFilter={venueFilter}
        opponentFilter={opponentFilter}
        playerFilter={playerFilter}
        formatFilter={formatFilter}
        difficultyFilter={difficultyFilter}
        showPlayerFilter={false}
        onTypeFilterChange={setTypeFilter}
        onOutcomeFilterChange={setOutcomeFilter}
        onVenueFilterChange={setVenueFilter}
        onOpponentFilterChange={setOpponentFilter}
        onPlayerFilterChange={setPlayerFilter}
        onFormatFilterChange={setFormatFilter}
        onDifficultyFilterChange={setDifficultyFilter}
        onClearAllFilters={clearAllFilters}
      />

      {error && (
        <StatsErrorState title={t('playerStats.error')} message={error} />
      )}

      {loading && !error && (
        <StatsLoadingState message={t('playerStats.loading')} />
      )}

      {isReady && matchesError && (
        <Alert variant="warning">{matchesError}</Alert>
      )}

      {isReady && loanError && (
        <Alert variant="warning">{loanError}</Alert>
      )}

      {isReady && parentHasNoRelatedPlayers && (
        <StatsEmptyState
          title={t('playerStats.noRelatedPlayers')}
          message={t('playerStats.noRelatedPlayersMessage')}
        />
      )}

      {isReady && !parentHasNoRelatedPlayers && noMatchesAvailable && (
        <StatsEmptyState
          title={t('playerStats.noMatchesAvailable')}
          message={t('playerStats.addMatchesOrAdjust')}
        />
      )}

      {isReady && !parentHasNoRelatedPlayers && !noMatchesAvailable && noMatchesForFilters && (
        <StatsEmptyState
          title={t('playerStats.noMatchesFiltered')}
          message={t('playerStats.adjustFilters')}
        />
      )}

      {isReady && !parentHasNoRelatedPlayers && !noMatchesAvailable && !noMatchesForFilters && !hasPlayerData && !matchesLoading && (
        <StatsEmptyState
          title={t('playerStats.noStatsRecorded')}
        />
      )}

      {isReady && hasPlayerData && (
        <>
          {/* Summary Stats — hidden for parents (team-wide aggregates) */}
          {!isParent && (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
              <StatCard
                icon={Users}
                title={t('playerStats.totalPlayers')}
                value={summaryStats.totalPlayers}
                subtitle={t('playerStats.activePlayers')}
              />

              <StatCard
                icon={Clock}
                title={t('playerStats.avgPlayingTime')}
                value={formatMinutesAsTime(summaryStats.averageFieldTime)}
                subtitle={t('playerStats.perMatch')}
              />

              <StatCard
                icon={Target}
                title={t('playerStats.avgGoals')}
                value={summaryStats.averageGoalsPerPlayer.toFixed(1)}
                subtitle={`${t('playerStats.totalGoalsLabel')} ${summaryStats.totalGoals}`}
              />

              <StatCard
                icon={Award}
                title={t('playerStats.topScorer')}
                value={summaryStats.topScorer ? summaryStats.topScorer.displayName : '-'}
                subtitle={summaryStats.topScorer ? `${summaryStats.topScorer.goalsScored} ${t('playerStats.goals')}` : t('playerStats.noData')}
              />
            </div>
          )}

          {/* Player Stats Table */}
          <SortableStatsTable
            data={sortedPlayers}
            orderedColumns={dragDropHandlers.orderedColumns}
            sortBy={sortBy}
            dragDropHandlers={dragDropHandlers}
            onSort={handleSort}
            renderSortIndicator={renderSortIndicator}
            headerIcon={Users}
            headerTitle={t('playerStats.title')}
            headerSubtitle={useMatchWeights ? t('playerStats.tableSubtitle', { weight: formatMatchCount(loanWeight) }) : t('playerStats.tableSubtitleNoWeights')}
            idKey="id"
          />
        </>
      )}
    </div>
  );
}
