import React, { useState, useMemo } from 'react';
import PropTypes from 'prop-types';
import { Button, Select } from '../shared/UI';
import { Alert } from '../shared/Alert';
import { Link, Check } from 'lucide-react';
import { ModalShell } from '../shared/ModalShell';
import { useTranslation } from 'react-i18next';

const CREATE_NEW = '__create_new__';

/**
 * Bulk modal listing every matchable ghost with a per-row candidate dropdown.
 * A single Save applies all selections (link existing or create new) in one action.
 */
export function BulkPlayerLinkModal({ entries, onSubmit, onSuccess, onClose, submitInFlightRef }) {
  const { t } = useTranslation('team');
  const [selections, setSelections] = useState(() => {
    const initial = {};
    entries.forEach(({ ghost, candidates }) => {
      initial[ghost.externalPlayerId] = candidates[0]?.id || CREATE_NEW;
    });
    return initial;
  });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [failedIds, setFailedIds] = useState([]);
  const [succeededIds, setSucceededIds] = useState([]);

  const optionsFor = useMemo(() => {
    const map = {};
    entries.forEach(({ ghost, candidates }) => {
      map[ghost.externalPlayerId] = [
        ...candidates.map((c) => ({
          value: c.id,
          label: c.last_name ? `${c.first_name} ${c.last_name}` : c.first_name
        })),
        { value: CREATE_NEW, label: t('bulkPlayerLink.createNewOption') }
      ];
    });
    return map;
  }, [entries, t]);

  const handleSubmit = async () => {
    if (submitInFlightRef) submitInFlightRef.current = true;
    setLoading(true);
    setError(null);
    const failures = [];
    const succeeded = [...succeededIds];
    let allSucceeded = false;

    try {
      // Sequential (not parallel) so each row's failure is tracked individually and a
      // retry can skip already-succeeded rows; squad sizes (5–15) keep this cheap.
      for (const { ghost, candidates } of entries) {
        // Skip rows that already succeeded so a retry never re-creates/re-links them.
        if (succeeded.includes(ghost.externalPlayerId)) continue;
        const selectedId = selections[ghost.externalPlayerId];
        try {
          if (selectedId === CREATE_NEW) {
            await onSubmit({ ghost, action: 'create', candidate: null });
          } else {
            const candidate = candidates.find((c) => c.id === selectedId);
            if (!candidate) throw new Error('Selected candidate not found');
            await onSubmit({ ghost, action: 'link', candidate });
          }
          succeeded.push(ghost.externalPlayerId);
        } catch (err) {
          console.error('Bulk link row failed:', ghost.externalPlayerId, err);
          failures.push(ghost.externalPlayerId);
        }
      }

      setSucceededIds(succeeded);
      setFailedIds(failures);

      if (failures.length === 0) {
        onSuccess?.(succeeded.length);
        allSucceeded = true;
      } else {
        setError(t('bulkPlayerLink.errors.partialFailure', { count: failures.length }));
      }
    } finally {
      setLoading(false);
      if (submitInFlightRef) submitInFlightRef.current = false;
    }
    // Fire-and-forget: onClose() unmounts the modal, so its async refresh runs in the
    // background after teardown. Errors are handled by the parent's own try/catch.
    // Must be after the finally block so setLoading(false) runs while still mounted.
    if (allSucceeded) onClose();
  };

  // Block all close paths (X, Escape, backdrop) while a submit is in flight to avoid
  // racing handleSubmit's row iteration / refresh against the modal teardown.
  const handleShellClose = () => {
    if (!loading) onClose();
  };

  if (!entries || entries.length === 0) return null;

  return (
    <ModalShell
      title={t('bulkPlayerLink.title')}
      subtitle={t('bulkPlayerLink.subtitle')}
      icon={Link}
      iconColor="amber"
      onClose={handleShellClose}
      maxWidth="xl"
    >
      <div className="space-y-6">
        {error && <Alert variant="error">{error}</Alert>}

        <div className="space-y-3">
          {entries.map(({ ghost }) => {
            const isFailed = failedIds.includes(ghost.externalPlayerId);
            const isSucceeded = succeededIds.includes(ghost.externalPlayerId);
            const rowClass = isFailed
              ? 'border-rose-500 bg-rose-900/20'
              : isSucceeded
                ? 'border-emerald-500 bg-emerald-900/20'
                : 'border-slate-600 bg-slate-800';
            return (
              <div
                key={ghost.externalPlayerId}
                className={`p-3 rounded border ${rowClass}`}
              >
                <div className="text-sm font-semibold text-slate-100 mb-2">{ghost.playerNameInProvider}</div>
                <Select
                  value={selections[ghost.externalPlayerId]}
                  onChange={(value) =>
                    setSelections((prev) => ({ ...prev, [ghost.externalPlayerId]: value }))
                  }
                  options={optionsFor[ghost.externalPlayerId]}
                  disabled={loading || isSucceeded}
                  error={isFailed}
                  aria-label={ghost.playerNameInProvider}
                />
                {isFailed && (
                  <p className="mt-1 text-xs text-rose-300">{t('bulkPlayerLink.errors.rowFailed')}</p>
                )}
                {isSucceeded && (
                  <p className="mt-1 text-xs text-emerald-300 flex items-center gap-1">
                    <Check size={12} aria-hidden="true" /> {t('bulkPlayerLink.rowSucceeded')}
                  </p>
                )}
              </div>
            );
          })}
        </div>

        <div className="flex items-center justify-end space-x-3 pt-4 border-t border-slate-600">
          <Button type="button" onClick={handleShellClose} variant="secondary" disabled={loading}>
            {t('bulkPlayerLink.buttons.cancel')}
          </Button>
          <Button type="button" onClick={handleSubmit} variant="primary" disabled={loading} Icon={Link}>
            {loading
              ? t('bulkPlayerLink.buttons.saving')
              : failedIds.length > 0
                ? t('bulkPlayerLink.buttons.retry')
                : t('bulkPlayerLink.buttons.save')}
          </Button>
        </div>
      </div>
    </ModalShell>
  );
}

BulkPlayerLinkModal.propTypes = {
  entries: PropTypes.arrayOf(
    PropTypes.shape({
      ghost: PropTypes.shape({
        externalPlayerId: PropTypes.string.isRequired,
        playerNameInProvider: PropTypes.string,
      }).isRequired,
      candidates: PropTypes.arrayOf(
        PropTypes.shape({
          id: PropTypes.string.isRequired,
          first_name: PropTypes.string.isRequired,
          last_name: PropTypes.string,
        })
      ).isRequired,
    })
  ).isRequired,
  onSubmit: PropTypes.func.isRequired,
  onSuccess: PropTypes.func,
  onClose: PropTypes.func.isRequired,
  submitInFlightRef: PropTypes.shape({ current: PropTypes.bool }),
};
