import React from 'react';
import PropTypes from 'prop-types';

const VARIANT_STYLES = {
  default: 'bg-slate-700 border-slate-600',
  dark: 'bg-slate-800 border-slate-600',
  highlighted: 'bg-sky-900/30 border-sky-600/50',
  subtle: 'bg-slate-700/50 border-slate-600',
};

const PADDING_STYLES = {
  sm: 'p-3',
  md: 'p-4',
  lg: 'p-6',
};

export function Card({ variant = 'default', padding = 'md', className = '', testId, children }) {
  return (
    <div
      className={`rounded-lg border ${VARIANT_STYLES[variant]} ${PADDING_STYLES[padding]} ${className}`}
      data-testid={testId}
    >
      {children}
    </div>
  );
}

Card.propTypes = {
  variant: PropTypes.oneOf(['default', 'dark', 'highlighted', 'subtle']),
  padding: PropTypes.oneOf(['sm', 'md', 'lg']),
  className: PropTypes.string,
  testId: PropTypes.string,
  children: PropTypes.node.isRequired,
};
