  // `target` — the team that was switched to (or null when none was found).
  const seedAndSwitchDemoTeam = useCallback(async () => {
    const result = await seedDemoTeam();
    if (!result?.success) return result;
    // Switch to the demo. result.team is absent on the already_exists path, so
    // fall back to the demo team in the refreshed list.
    const teams = await getUserTeams();
    const target = result.team
      ? teams.find((team) => team.id === result.team.id) || result.team
      : teams.find((team) => team.is_demo);
    if (target) {
      await switchCurrentTeam(target.id, teams);
    }
    return { ...result, target: target || null };
  }, [seedDemoTeam, getUserTeams, switchCurrentTeam]);

  // Accept the demo prompt: seed, switch, and suppress the prompt for this user.
  const acceptDemoPrompt = useCallback(async () => {
    const result = await seedAndSwitchDemoTeam();
    if (result?.success) {
      // Suppress the prompt (a demo now exists / is being created).
      if (user) {
        demoPromptPersistence.saveState({ userId: user.id });
      }
      setDemoDismissTick((tick) => tick + 1);
    }
    return result;
  }, [user, demoPromptPersistence, seedAndSwitchDemoTeam]);

