  // Approve team access request (for team coaches). For a parent join request
  // the approver may also link claimed roster players via playerIds — approving
  // the join then creates those player_user relationships in one step.
  //
  // These are sequential writes rather than a single transaction, but each write
  // is idempotent and the request status is flipped LAST. So if any step fails
  // mid-way the request stays 'pending' (still visible to managers) and simply
  // re-approving it replays the no-op'd writes through to completion.
  const approveTeamAccess = useCallback(async (requestId, approvedRole, playerIds = []) => {
    try {
      setLoading(true);
      clearError();

      // First, get the request details
      const { data: request, error: requestError } = await supabase
        .from('team_access_request')
        .select('team_id, user_id')
        .eq('id', requestId)
        .single();

      if (requestError) {
        console.error('Error fetching request:', requestError);
        setError(t('errors.fetchRequestDetails'));
        return null;
      }

      // Add user to team_user table (idempotent so a retry after a later-step
      // failure doesn't trip the team_id/user_id unique constraint).
      const { error: teamUserError } = await supabase
        .from('team_user')
        .upsert(
          [{
            team_id: request.team_id,
            user_id: request.user_id,
            role: approvedRole
          }],
          { onConflict: 'team_id,user_id', ignoreDuplicates: true }
        );

      if (teamUserError) {
        console.error('Error adding user to team:', teamUserError);
        setError(t('errors.addUserToTeam'));
        return null;
      }

      // Link any claimed players now that the user is a team member.
      if (Array.isArray(playerIds) && playerIds.length > 0) {
        const { error: relError } = await supabase
          .from('player_user')
          .upsert(
            playerIds.map((playerId) => ({
              player_id: playerId,
              user_id: request.user_id,
              created_by: user.id
            })),
            { onConflict: 'player_id,user_id', ignoreDuplicates: true }
          );

        if (relError) {
          console.error('Error linking claimed players:', relError);
          setError(t('errors.addPlayerRelationship'));
          return null;
        }
      }

      // Update request status
      const { data, error } = await supabase
        .from('team_access_request')
        .update({
          status: 'approved',
          reviewed_by: user.id,
          reviewed_at: new Date().toISOString()
        })
        .eq('id', requestId)
        .select(`
          id, status, reviewed_at,
          user:user_id (id, name),
          team:team_id (
            id,
            name,
            club:club_id (id, name, short_name, long_name)
          )
        `)
        .single();

      if (error) {
        console.error('Error updating request status:', error);
        setError(t('errors.updateRequestStatus'));
        return null;
      }

      // Refresh pending requests after approval
      if (currentTeam) {
        checkPendingRequests();
      }

      return data;
    } catch (err) {
      console.error('Exception in approveTeamAccess:', err);
      setError(t('errors.approveTeamAccess'));
      return null;
    } finally {
      setLoading(false);
    }
  }, [user, clearError, currentTeam, checkPendingRequests, t]);

