import { useEffect, useRef } from 'react';
import { VIEWS } from '../constants/viewConstants';
import {
  getInitialPathRoutingState,
  LIVE_MATCH_PATH_REGEX,
  normalizeRoutingPath
} from './pathRoutingState';
import {
  clearIntendedPath,
  consumeIntendedPath,
  getIntendedPath,
  isAuthRequiredPath,
  setIntendedPath
} from '../utils/intendedPath';
import { isPasswordRecoveryInProgress } from '../utils/passwordRecoveryState';

const PLAN_IDS_PATH_REGEX = /^\/plan\/([0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}(?:,[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12})*)$/i;

const resolveViewFromPath = (path) => {
  const normalized = normalizeRoutingPath(path);
  if (normalized === '/profile') return VIEWS.PROFILE;
  if (normalized === '/matches') return VIEWS.TEAM_MATCHES;
  if (normalized === '/tactics') return VIEWS.TACTICAL_BOARD;
  if (normalized === '/team' || normalized.startsWith('/team/')) return VIEWS.TEAM_MANAGEMENT;
  if (normalized === '/stats' || normalized.startsWith('/stats/')) return VIEWS.STATISTICS;
  if (normalized === '/plan') return VIEWS.TEAM_MATCHES;
  return null;
};

/**
 * Deep-link auth gate (Issue #371).
 *
 * When an unauthenticated user lands on a protected URL (e.g. `/team/loans`),
 * captures the intended path, pins the URL, and opens the sign-in modal so the
 * destination survives until sign-in completes — including the Google OAuth
 * round-trip via `/auth/callback`.
 *
 * Returns `authGateActive` so the caller can defer per-feature routing hooks
 * while the gate is open.
 */
export function useDeepLinkAuthGate({
  user,
  authLoading,
  authModal,
  navigateToView,
  setLiveMatchId,
  setPlanMatchIdsFromUrl
}) {
  const initialPathStateRef = useRef(null);
  if (initialPathStateRef.current === null && typeof window !== 'undefined') {
    initialPathStateRef.current = getInitialPathRoutingState();
  }
  const initialPath = initialPathStateRef.current?.path;

  // Defer routing while user is unknown OR known unauthenticated AND the initial
  // URL is auth-protected.
  const authGateActive = !user && isAuthRequiredPath(initialPath);

  // Effect A: capture intended path + open modal.
  useEffect(() => {
    if (authLoading) return;
    if (user) return;
    if (!isAuthRequiredPath(initialPath)) return;
    if (getIntendedPath() === initialPath) return;
    setIntendedPath(initialPath);
    if (typeof window !== 'undefined') {
      const currentPath = normalizeRoutingPath(window.location.pathname || '/');
      if (currentPath !== normalizeRoutingPath(initialPath)) {
        const search = window.location.search || '';
        const hash = window.location.hash || '';
        window.history.replaceState(window.history.state, '', `${initialPath}${search}${hash}`);
      }
    }
    authModal?.openLogin?.();
  }, [authLoading, user, initialPath, authModal]);

  // Effect B: restore intended path after successful sign-in.
  useEffect(() => {
    if (!user) return;
    if (typeof window === 'undefined') return;
    // A forgot-password OTP also signs the user in, but the auth modal must
    // stay open so they can set a new password. Don't treat this as a
    // deep-link sign-in: leave the modal open and bail.
    if (isPasswordRecoveryInProgress()) {
      // Intentionally drop the captured intent (don't restore it). The recovery
      // sign-in isn't the deep-link sign-in we were waiting for; honoring the
      // path here would yank the user off the reset modal mid-flow. The
      // trade-off is they land at / rather than the original deep link after
      // setting their password — acceptable vs. breaking the reset.
      clearIntendedPath();
      return;
    }
    const currentPath = normalizeRoutingPath(window.location.pathname || '/');
    const onCallback = currentPath === '/auth/callback';
    const intended = getIntendedPath();

    if (intended) {
      const intendedNormalized = normalizeRoutingPath(intended);
      if (currentPath !== intendedNormalized && !onCallback) {
        clearIntendedPath();
        return;
      }
      consumeIntendedPath();

      if (currentPath !== intendedNormalized) {
        // When restoring from /auth/callback, drop the OAuth query/hash artifacts
        // (?code=…, #access_token=…) so they don't leak onto the destination path
        // and trick other detectors (e.g. detectResetTokens) into misclassifying
        // them as password-reset codes.
        const restoringFromCallback = onCallback;
        const search = restoringFromCallback ? '' : (window.location.search || '');
        const hash = restoringFromCallback ? '' : (window.location.hash || '');
        window.history.replaceState(window.history.state, '', `${intended}${search}${hash}`);
      }

      const liveMatch = intended.match(LIVE_MATCH_PATH_REGEX);
      if (liveMatch && liveMatch[1]) {
        setLiveMatchId?.(liveMatch[1]);
        navigateToView?.(VIEWS.LIVE_MATCH, { matchId: liveMatch[1] });
      } else {
        const planMatch = intended.match(PLAN_IDS_PATH_REGEX);
        if (planMatch && planMatch[1]) {
          setPlanMatchIdsFromUrl?.(planMatch[1].split(','));
        } else {
          const targetView = resolveViewFromPath(intended);
          if (targetView) {
            navigateToView?.(targetView);
          }
        }
      }

      authModal?.closeModal?.();
      return;
    }

    if (onCallback) {
      window.history.replaceState(window.history.state, '', '/');
    }
  }, [user, navigateToView, authModal, setLiveMatchId, setPlanMatchIdsFromUrl]);

  // Effect C: clear stale intended path if the user dismisses the modal without
  // signing in, so it won't re-apply later from an unrelated context.
  const prevAuthModalOpenRef = useRef(authModal?.isOpen);
  useEffect(() => {
    const wasOpen = prevAuthModalOpenRef.current;
    prevAuthModalOpenRef.current = authModal?.isOpen;
    if (wasOpen && !authModal?.isOpen && !user) {
      clearIntendedPath();
    }
  }, [authModal?.isOpen, user]);

  return { authGateActive };
}

// Exported for tests
export const __testing = { resolveViewFromPath, PLAN_IDS_PATH_REGEX };
