import { useEffect, useRef, useState } from 'react';
import { normalizeRoutingPath } from './pathRoutingState';

export function useUrlBackedTabState({
  persistence,
  defaultTab,
  isValidTab,
  getTabFromPath,
  getPathForTab,
  isPathOwned,
  externalTab = null
}) {
  const [activeTab, setActiveTab] = useState(() => {
    if (typeof window !== 'undefined') {
      const pathTab = getTabFromPath(window.location.pathname);
      if (pathTab) {
        return pathTab;
      }
    }

    if (isValidTab(externalTab)) {
      return externalTab;
    }

    const stored = persistence.loadState();
    const storedTab = stored && typeof stored === 'object' ? stored.tab : null;
    return isValidTab(storedTab) ? storedTab : defaultTab;
  });

  useEffect(() => {
    persistence.saveState({ tab: activeTab });
  }, [activeTab, persistence]);

  const lastAppliedExternalTabRef = useRef(isValidTab(externalTab) ? externalTab : null);
  useEffect(() => {
    if (!isValidTab(externalTab)) {
      lastAppliedExternalTabRef.current = null;
      return;
    }
    if (lastAppliedExternalTabRef.current === externalTab) {
      return;
    }
    lastAppliedExternalTabRef.current = externalTab;
    setActiveTab(externalTab);
  }, [externalTab, isValidTab]);

  useEffect(() => {
    if (typeof window === 'undefined') {
      return;
    }

    const normalizedPath = normalizeRoutingPath(window.location.pathname || '/');
    const targetPath = getPathForTab(activeTab);

    if (!isPathOwned(normalizedPath) || normalizedPath === targetPath) {
      return;
    }

    const search = window.location.search || '';
    const hash = window.location.hash || '';
    window.history.replaceState(window.history.state, '', `${targetPath}${search}${hash}`);
  }, [activeTab, getPathForTab, isPathOwned]);

  return [activeTab, setActiveTab];
}
