import { useCallback, useEffect, useRef, useState } from 'react';

const INITIAL_STATE = {
  active: false,
  sourceLevelId: null,
  sourcePlayerId: null,
  targetLevelId: null,
  hoveredPlayerId: null, // null = drop at end of target group
};

/**
 * Manages cross-level drag-and-drop for the PlayerRankingScreen.
 *
 * Handles the case where a player is dragged from one level group into another.
 * Within-group reordering is handled separately by useListDragAndDrop instances.
 *
 * Move semantics (not swap): the dragged player is removed from the source level
 * and inserted at the hovered position in the target level (or appended if no
 * player is being hovered).
 *
 * Usage:
 *   const { registerContainer, handleDragMove, handleDragEnd, crossLevelState } =
 *     useRankingDrag({ onMovePlayer });
 *
 *   // In each level group component:
 *   const cleanupRef = useEffect(() => registerContainer(levelId, containerRef), [levelId]);
 *
 *   // Pass handleDragMove and handleDragEnd to useListDragAndDrop via onDragMove / onDragEnd.
 *
 * @param {{ onMovePlayer: (sourceLevel: number, playerId: string, targetLevel: number, beforePlayerId: string|null) => void }} params
 *   onMovePlayer is called with:
 *     - sourceLevel: level the player came from
 *     - playerId: the player being moved
 *     - targetLevel: level the player is dropped into
 *     - beforePlayerId: insert before this player, or null to append at end
 */
export function useRankingDrag({ onMovePlayer }) {
  const [crossLevelState, setCrossLevelState] = useState(INITIAL_STATE);

  const crossLevelStateRef = useRef(INITIAL_STATE);
  const containerRefs = useRef(new Map());
  const onMovePlayerRef = useRef(onMovePlayer);
  onMovePlayerRef.current = onMovePlayer;

  const registerContainer = useCallback((levelId, containerRef) => {
    containerRefs.current.set(levelId, containerRef);
    return () => {
      containerRefs.current.delete(levelId);
    };
  }, []);

  const handleDragMove = useCallback(({ itemId, clientX, clientY }, sourceLevelId) => {
    let targetLevelId = null;
    let targetContainerRef = null;

    for (const [levelId, ref] of containerRefs.current.entries()) {
      if (levelId === sourceLevelId) continue;
      const el = ref.current;
      if (!el) continue;
      const rect = el.getBoundingClientRect();
      if (
        clientX >= rect.left &&
        clientX <= rect.right &&
        clientY >= rect.top &&
        clientY <= rect.bottom
      ) {
        targetLevelId = levelId;
        targetContainerRef = ref;
        break;
      }
    }

    if (targetLevelId === null || !targetContainerRef) {
      if (crossLevelStateRef.current.active) {
        crossLevelStateRef.current = INITIAL_STATE;
        setCrossLevelState(INITIAL_STATE);
      }
      return;
    }

    const container = targetContainerRef.current;
    if (!container) return;

    const nodes = Array.from(container.querySelectorAll('[data-drag-item-id]'));
    let hoveredPlayerId = null;

    for (const node of nodes) {
      const rect = node.getBoundingClientRect();
      // Use the top half of each card to decide insertion point:
      // hovering the top half of a card means "insert before it"
      if (
        clientX >= rect.left &&
        clientX <= rect.right &&
        clientY >= rect.top &&
        clientY < rect.top + rect.height / 2
      ) {
        hoveredPlayerId = node.dataset.dragItemId;
        break;
      }
    }

    const prev = crossLevelStateRef.current;
    if (
      prev.targetLevelId === targetLevelId &&
      prev.hoveredPlayerId === hoveredPlayerId &&
      prev.sourcePlayerId === itemId
    ) {
      return;
    }

    const nextState = {
      active: true,
      sourceLevelId,
      sourcePlayerId: itemId,
      targetLevelId,
      hoveredPlayerId,
    };
    crossLevelStateRef.current = nextState;
    setCrossLevelState(nextState);
  }, []);

  const handleDragEnd = useCallback(({ cancelled }, sourceLevelId) => {
    const state = crossLevelStateRef.current;

    if (!cancelled && state.active && state.targetLevelId !== null && onMovePlayerRef.current) {
      onMovePlayerRef.current(
        sourceLevelId,
        state.sourcePlayerId,
        state.targetLevelId,
        state.hoveredPlayerId // null = append at end
      );
    }

    crossLevelStateRef.current = INITIAL_STATE;
    setCrossLevelState(INITIAL_STATE);
  }, []);

  // Clean up container registry on unmount
  useEffect(() => {
    const registry = containerRefs.current;
    return () => {
      registry.clear();
    };
  }, []);

  return {
    registerContainer,
    handleDragMove,
    handleDragEnd,
    crossLevelState,
  };
}
