import React, { useEffect, useMemo, useRef, useState } from 'react';
import PropTypes from 'prop-types';
import { useTranslation } from 'react-i18next';
import { Sparkles } from 'lucide-react';
import { Button } from './UI';
import { useAuth } from '../../contexts/AuthContext';
import { useTeam } from '../../contexts/TeamContext';

// Floating, scroll-persistent banner shown while a demo team is active. Offers a
// one-tap path to the user's real team — create one, switch to it, or pick from many.
// Disappears automatically once the active team is a real (non-demo) team.
export function DemoTeamBanner({ onCreateRealTeam }) {
  const { t } = useTranslation('team');
  const { user } = useAuth();
  const { currentTeam, userTeams, switchCurrentTeam, showTeamSelectionPrompt } = useTeam();

  const shouldShow = Boolean(user && currentTeam?.is_demo);
  const [visible, setVisible] = useState(false);
  const bannerRef = useRef(null);

  const realTeams = useMemo(() => (userTeams || []).filter((team) => !team?.is_demo), [userTeams]);

  useEffect(() => {
    if (!shouldShow) {
      setVisible(false);
      return undefined;
    }
    const id = requestAnimationFrame(() => setVisible(true));
    return () => cancelAnimationFrame(id);
  }, [shouldShow]);

  // Reserve scroll space for the fixed banner by publishing its measured height as a
  // CSS custom property; <main> reads it as bottom padding so content clears the banner.
  useEffect(() => {
    const el = bannerRef.current;
    if (!el) return undefined;
    // Only mobile's full-width bottom banner occludes <main>; the sm+ floating card doesn't.
    const setHeight = () => {
      const isDesktop = window.matchMedia('(min-width: 640px)').matches;
      document.documentElement.style.setProperty('--demo-banner-height', isDesktop ? '0px' : `${el.offsetHeight}px`);
    };
    setHeight();
    const observer = new ResizeObserver(setHeight);
    observer.observe(el);
    return () => {
      observer.disconnect();
      document.documentElement.style.setProperty('--demo-banner-height', '0px');
    };
  }, [shouldShow]);

  if (!shouldShow) return null;

  let ctaLabel;
  let onCta;
  if (realTeams.length === 0) {
    ctaLabel = t('demo.banner.cta');
    onCta = onCreateRealTeam;
  } else if (realTeams.length === 1) {
    ctaLabel = t('demo.banner.switchCta', { teamName: realTeams[0].name });
    onCta = () => switchCurrentTeam(realTeams[0].id);
  } else {
    ctaLabel = t('demo.banner.switchManyCta');
    onCta = showTeamSelectionPrompt;
  }

  return (
    <div
      ref={bannerRef}
      data-testid="demo-team-banner"
      className={`fixed bottom-0 inset-x-0 sm:bottom-4 sm:left-4 sm:right-auto sm:max-w-sm z-40 pb-[env(safe-area-inset-bottom)] transition-transform duration-300 ease-out ${visible ? 'translate-y-0' : 'translate-y-full'}`}
    >
      <div className="bg-slate-800 border border-slate-600 rounded-t-lg sm:rounded-lg shadow-2xl p-4 m-0 sm:m-2">
        <div className="flex items-start gap-2 mb-2">
          <Sparkles className="h-5 w-5 text-amber-300 shrink-0 mt-0.5" />
          <div>
            <h3 className="text-sky-300 font-semibold text-sm">{t('demo.banner.title')}</h3>
            <p className="text-slate-300 text-xs mt-1">{t('demo.banner.body')}</p>
          </div>
        </div>
        <Button
          onClick={onCta}
          variant="primary"
          size="sm"
          className="w-full"
        >
          {ctaLabel}
        </Button>
      </div>
    </div>
  );
}

DemoTeamBanner.propTypes = {
  onCreateRealTeam: PropTypes.func.isRequired,
};
