import React from 'react';
import PropTypes from 'prop-types';
import { ShieldOff } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { Button } from './UI';

// Shared fail-closed panel shown when a user reaches a screen their role can't
// access. Always offers a way back to a screen they can use — never a dead-end.
export function AccessDeniedView({ onNavigateHome }) {
  const { t } = useTranslation('common');

  return (
    <div className="min-h-screen bg-slate-900 text-slate-100 flex items-center justify-center px-4">
      <div className="bg-slate-800 border border-slate-600 rounded-lg p-6 sm:p-8 max-w-md w-full text-center space-y-4">
        <div className="flex justify-center">
          <div className="bg-slate-700 rounded-full p-3">
            <ShieldOff className="w-8 h-8 text-sky-400" aria-hidden="true" />
          </div>
        </div>
        <h1 className="text-xl font-bold text-sky-300">{t('accessDenied.title')}</h1>
        <p className="text-sm text-slate-300">{t('accessDenied.message')}</p>
        {typeof onNavigateHome === 'function' && (
          <div className="flex justify-center pt-2">
            <Button onClick={onNavigateHome} variant="primary">
              {t('accessDenied.backHome')}
            </Button>
          </div>
        )}
      </div>
    </div>
  );
}

AccessDeniedView.propTypes = {
  onNavigateHome: PropTypes.func
};
