/**
 * Centralized fail-closed access policy.
 *
 * Single source of truth for which roles may see each view and each
 * team-management tab. The destination enforces access; hiding buttons is
 * best-effort UX. Any view/tab not declared here is denied (default-deny),
 * so a newly added screen cannot silently become reachable by the wrong role.
 */
import { VIEWS } from './viewConstants';
import { TAB_VIEWS } from './teamManagementTabs';

export const ACCESS_DECISIONS = {
  ALLOW: 'allow',
  REDIRECT: 'redirect',
  DENY: 'deny'
};

// Canonical team-role predicates. These are the single source of truth for the
// capabilities of a role; TeamContext derives canManageTeam/isTeamAdmin from
// these so the policy drives the context, not the other way around. Add a new
// managing role here once and both the policy and the context follow.
export const canManageRole = (role) => role === 'admin' || role === 'coach';
export const isAdminRole = (role) => role === 'admin';

// Role context shape: { userRole, isAuthenticated }
const isParentRole = (ctx) => ctx?.userRole === 'parent';

// Build the role context the policy predicates consume. Canonical shape — use
// this everywhere a ctx is constructed so call sites can't silently diverge.
export const makeAccessCtx = (currentTeam, user) => ({
  userRole: currentTeam?.userRole,
  isAuthenticated: Boolean(user)
});

// Coaching access: any authenticated user who is NOT a restricted role. A
// teamless authenticated user (userRole undefined) keeps coaching access so
// they can create a team and start a game; only known restricted roles
// (currently parent) are gated out of the coaching flow. Exported so UI that
// leads into the coaching/match flow (e.g. the floating "back to match" button)
// can hide itself for roles that can't reach the destination.
export const canCoach = (ctx) => Boolean(ctx?.isAuthenticated) && !isParentRole(ctx);

// Predicate per view. A view absent from this map is denied by default.
const VIEW_ACCESS = {
  // Public views — reachable by anyone, including anonymous users.
  [VIEWS.LIVE_MATCH]: () => true,
  [VIEWS.TACTICAL_BOARD]: () => true,

  // Available to every authenticated role (parent, coach, admin).
  [VIEWS.STATISTICS]: (ctx) => Boolean(ctx?.isAuthenticated),
  [VIEWS.PROFILE]: (ctx) => Boolean(ctx?.isAuthenticated),
  [VIEWS.TEAM_MATCHES]: (ctx) => Boolean(ctx?.isAuthenticated),
  // Team Management gates its restricted tabs internally (see tab policy).
  [VIEWS.TEAM_MANAGEMENT]: (ctx) => Boolean(ctx?.isAuthenticated),

  // Coaching-only views — denied to parents.
  [VIEWS.CONFIG]: canCoach,
  [VIEWS.PERIOD_SETUP]: canCoach,
  [VIEWS.GAME]: canCoach,
  [VIEWS.STATS]: canCoach,
  [VIEWS.PLAYER_RANKING]: canCoach,
  [VIEWS.PLAN_MATCHES]: canCoach
};

// Views that, when a user cannot use them, should redirect to the user's home
// screen rather than show an access-denied panel. These are the landing/match-flow
// views a parent can only reach by auto-landing (default view on login, or a
// running match restored into the session) — never via a visible button — so a
// silent redirect to home is the intuitive outcome. Views a parent could reach by
// explicitly following a stale link (PLAYER_RANKING, PLAN_MATCHES) stay out of this
// set and show the access-denied panel, which is the clearer signal there.
const REDIRECT_ON_DENY = new Set([
  VIEWS.CONFIG,
  VIEWS.GAME,
  VIEWS.PERIOD_SETUP,
  VIEWS.STATS
]);

/**
 * The home/redirect target for a role. Parents land on Statistics; coaches and
 * admins keep the coaching default (Config / New Game). Anonymous users fall
 * back to the coaching default, where the existing auth gate takes over.
 */
export const getHomeView = (ctx) => {
  if (isParentRole(ctx)) {
    return VIEWS.STATISTICS;
  }
  // Coaches/admins and anonymous users both land here. For anon this is never
  // acted on — renderView's !user → WelcomeScreen guard intercepts first.
  return VIEWS.CONFIG;
};

const canAccessView = (view, ctx) => {
  const predicate = VIEW_ACCESS[view];
  if (typeof predicate !== 'function') {
    return false; // default-deny
  }
  return Boolean(predicate(ctx));
};

/**
 * Decide what to do when a user reaches a view.
 * Returns { decision, redirectTo? }.
 */
export const resolveViewAccess = (view, ctx) => {
  if (canAccessView(view, ctx)) {
    return { decision: ACCESS_DECISIONS.ALLOW };
  }

  if (REDIRECT_ON_DENY.has(view)) {
    return { decision: ACCESS_DECISIONS.REDIRECT, redirectTo: getHomeView(ctx) };
  }

  return { decision: ACCESS_DECISIONS.DENY, redirectTo: getHomeView(ctx) };
};

// Predicate per team-management tab, built from the canonical role predicates
// above. A tab absent from this map is denied by default.
const isTeamManager = (ctx) => canManageRole(ctx?.userRole);
const isTeamAdmin = (ctx) => isAdminRole(ctx?.userRole);

const TEAM_MANAGEMENT_TAB_ACCESS = {
  [TAB_VIEWS.OVERVIEW]: (ctx) => Boolean(ctx?.isAuthenticated),
  [TAB_VIEWS.ROSTER]: isTeamManager,
  [TAB_VIEWS.LOANS]: isTeamManager,
  [TAB_VIEWS.ACCESS]: isTeamAdmin,
  [TAB_VIEWS.CONNECTORS]: isTeamAdmin,
  [TAB_VIEWS.PREFERENCES]: isTeamManager
};

export const canAccessTeamManagementTab = (tab, ctx) => {
  const predicate = TEAM_MANAGEMENT_TAB_ACCESS[tab];
  if (typeof predicate !== 'function') {
    return false; // default-deny
  }
  return Boolean(predicate(ctx));
};
