import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { Button, NotificationModal } from '../shared/UI';
import { Alert } from '../shared/Alert';
import { Card } from '../shared/Card';
import { useTeam } from '../../contexts/TeamContext';
import { useAuth } from '../../contexts/AuthContext';
import { useToast } from '../../contexts/ToastContext';
import { useTranslation } from 'react-i18next';
import { FORMAT_CONFIGS, getMinimumPlayersForFormat } from '../../constants/teamConfiguration';
import { createManualPlannedMatch, planUpcomingMatch, replanPlannedMatch } from '../../services/matchPlanningService';
import { getPrecedingPlannedMatches, getSquadSelectionsForMatches, getUserDisplayName } from '../../services/matchStateManager';
import { useAutoSelectPreferences } from '../../hooks/useAutoSelectPreferences';
import { useAttendanceStats } from '../../hooks/useAttendanceStats';
import { usePlanProgress } from '../../hooks/usePlanProgress';
import { usePlanningDefaults } from '../../hooks/usePlanningDefaults';
import { useUnavailablePlayersByMatch } from '../../hooks/useUnavailablePlayersByMatch';
import { useProviderAvailability } from '../../hooks/useProviderAvailability';
import { useCrossMatchDrag } from '../../hooks/useCrossMatchDrag';
import { useAutoSavePlan } from '../../hooks/useAutoSavePlan';
import { useRealtimeMatchPlan } from '../../hooks/useRealtimeMatchPlan';
import { MatchCard } from './planMatches/MatchCard';
import { AutoSelectModal } from './planMatches/AutoSelectModal';
import { PlanMatchesToolbar } from './planMatches/PlanMatchesToolbar';
import { attachStrengthScores, autoSelectMultipleMatches, autoSelectSingleMatch, buildSortedRoster } from '../../utils/autoSelectAlgorithms';
import { formatLocalDateTimeFromISO } from '../../utils/timeUtils';
import { copyPlanMatchesUrlToClipboard } from '../../utils/planMatchesLinkUtils';
import { migratePerMatchKey } from '../../utils/migratePerMatchKey';
import { getPlayerRankings } from '../../services/rankingService';
import { MANUAL_MATCH_SENTINEL_ID, PENDING_MATCH_STATE, PLANNED_MATCH_STATE, PLAN_MATCHES_GLOW_EFFECTS } from '../../constants/planMatchesConstants';

const DEBUG_ENABLED = process.env.NODE_ENV !== 'production';

// Resolve the effective scheduled Date for a match in the planning session.
// Mirrors formatSchedule's priority: prefer matchDate (+matchTime), fall back
// to plannedStartTime. Returns null when neither yields a valid date.
function resolveEffectiveMatchDate(match) {
  if (match?.matchDate) {
    const time = match.matchTime ? match.matchTime.slice(0, 8) : '00:00:00';
    const parsed = new Date(`${match.matchDate}T${time}`);
    if (!Number.isNaN(parsed.getTime())) return parsed;
  }
  if (match?.plannedStartTime) {
    const parsed = new Date(match.plannedStartTime);
    if (!Number.isNaN(parsed.getTime())) return parsed;
  }
  return null;
}

export function PlanMatchesScreen({
  onNavigateBack,
  pushNavigationState,
  removeFromNavigationStack,
  matchesToPlan = []
}) {
  const { t } = useTranslation('team');
  const { currentTeam, teamPlayers, loadTeamPreferences, canManageTeam } = useTeam();
  const { user } = useAuth();
  const { showSuccess, showWarning } = useToast();
  const currentUserId = user?.id || null;
  const readOnly = !canManageTeam;
  const [notification, setNotification] = useState({ isOpen: false, title: '', message: '' });
  const [showAutoSelectModal, setShowAutoSelectModal] = useState(false);
  const [autoSelectMatchId, setAutoSelectMatchId] = useState(null);
  const [difficultyByMatch, setDifficultyByMatch] = useState({});
  const [matchTypeByMatch, setMatchTypeByMatch] = useState({});
  const [venueTypeByMatch, setVenueTypeByMatch] = useState({});
  const [formatByMatch, setFormatByMatch] = useState({});
  // Formation paired with the last format change per match — only carried into
  // auto-save when the format actually changes; otherwise undefined so the
  // service leaves the existing teamConfig.formation alone.
  const [formationByMatch, setFormationByMatch] = useState({});

  const {
    unavailablePlayersByMatch,
    providerAvailableOverridesByMatch,
    setUnavailablePlayersByMatch,
    setProviderAvailableOverridesByMatch
  } = useUnavailablePlayersByMatch(currentTeam?.id);
  const { autoSelectSettings, targetCounts, lastSquadSize, setAutoSelectSettings, setTargetCounts, setLastSquadSize } = useAutoSelectPreferences(
    currentTeam?.id
  );
  const {
    matches,
    updateMatchById,
    selectedPlayersByMatch,
    sortMetric,
    includePrecedingUpcoming,
    inviteSeededMatchIds,
    setSelectedPlayersByMatch,
    setSortMetric,
    setIncludePrecedingUpcoming,
    setPlannedMatchIds,
    setInviteSeededMatchIds,
    planningStatus,
    setPlanningStatus
  } = usePlanProgress({
    teamId: currentTeam?.id,
    matchesToPlan,
    debugEnabled: DEBUG_ENABLED
  });
  const resetPlanningStatusForMatch = useCallback((matchId) => {
    setPlanningStatus(prev => {
      if (!prev[matchId]) return prev;
      return { ...prev, [matchId]: null };
    });
  }, [setPlanningStatus]);

  // Track which planned/pending match IDs have been fetched for saved squad selections
  const fetchedSavedSelectionRef = useRef(new Set());
  const isMountedRef = useRef(true);
  // Auto-save flush-on-unmount/navigation; populated once useAutoSavePlan runs below.
  const flushAutoSavesRef = useRef(null);

  useEffect(() => {
    isMountedRef.current = true;
    return () => { isMountedRef.current = false; };
  }, []);

  // Reset tracked IDs when team changes
  useEffect(() => {
    fetchedSavedSelectionRef.current = new Set();
  }, [currentTeam?.id]);

  // Seed selectedPlayersByMatch and difficultyByMatch from DB for planned/pending matches.
  // Guarded by the component-level mount flag (not an effect-local one) so results still apply
  // when `matches` reflows mid-fetch — otherwise the cleanup on rerun silently drops the response.
  useEffect(() => {
    const seedableMatchIds = matches
      .filter(m => m.state === PLANNED_MATCH_STATE || m.state === PENDING_MATCH_STATE)
      .map(m => m.id)
      .filter(id => !fetchedSavedSelectionRef.current.has(id));

    if (seedableMatchIds.length === 0) return;

    // Mark as fetched immediately to prevent duplicate requests
    seedableMatchIds.forEach(id => fetchedSavedSelectionRef.current.add(id));

    getSquadSelectionsForMatches(seedableMatchIds).then(result => {
      if (!isMountedRef.current) return;
      if (!result.success) return;

      // Auto-save means the DB is authoritative for planned/pending matches.
      // Always overwrite local cache so we don't display a stale local edit
      // after a round-trip (the pre-auto-save behavior that caused
      // ConfigurationScreen and the planner to disagree).
      const fetchedSelections = result.selections || {};
      if (Object.keys(fetchedSelections).length > 0) {
        setSelectedPlayersByMatch(prev => {
          let didChange = false;
          const next = { ...prev };
          Object.entries(fetchedSelections).forEach(([matchId, playerIds]) => {
            const current = next[matchId] || [];
            const sameLength = current.length === playerIds.length;
            const sameOrder = sameLength && current.every((id, i) => id === playerIds[i]);
            if (!sameOrder) {
              next[matchId] = playerIds;
              didChange = true;
            }
          });
          return didChange ? next : prev;
        });
      }

      const mergeScalarMap = (setter, fetched) => {
        if (!fetched || Object.keys(fetched).length === 0) return;
        setter(prev => {
          let didChange = false;
          const next = { ...prev };
          Object.entries(fetched).forEach(([matchId, value]) => {
            if (next[matchId] !== value) {
              next[matchId] = value;
              didChange = true;
            }
          });
          return didChange ? next : prev;
        });
      };

      mergeScalarMap(setDifficultyByMatch, result.difficulties);
      mergeScalarMap(setMatchTypeByMatch, result.matchTypes);
      mergeScalarMap(setVenueTypeByMatch, result.venueTypes);
      mergeScalarMap(setFormatByMatch, result.formats);
    });
  }, [matches, setSelectedPlayersByMatch]);

  const autoSelectMatches = useMemo(() => {
    // Overlay any unsaved difficulty edits from the dropdowns so downstream
    // logic (e.g. AutoSelectModal's "One strong team" preselection) reflects
    // what the user sees, not just what's persisted on the match row.
    const withCurrentDifficulty = (match) => ({
      ...match,
      difficulty: difficultyByMatch[match.id] || match.difficulty
    });

    if (matches.length > 1) {
      return matches.map(withCurrentDifficulty);
    }
    if (autoSelectMatchId) {
      return matches.filter(match => match.id === autoSelectMatchId).map(withCurrentDifficulty);
    }
    return matches.map(withCurrentDifficulty);
  }, [autoSelectMatchId, matches, difficultyByMatch]);
  const { providerUnavailableByMatch, providerResponseByMatch, providerInvitedByMatch, providerAvailabilityLoading } = useProviderAvailability(matches);
  const mergedUnavailableByMatch = useMemo(() => {
    const merged = {};
    const allMatchIds = new Set([
      ...Object.keys(unavailablePlayersByMatch || {}),
      ...Object.keys(providerAvailableOverridesByMatch || {}),
      ...Object.keys(providerUnavailableByMatch || {}),
      ...matches.map((match) => String(match.id))
    ]);

    allMatchIds.forEach((matchId) => {
      const manualIds = unavailablePlayersByMatch[matchId] || [];
      const providerIds = providerUnavailableByMatch[matchId] || [];
      const providerOverrideSet = new Set(providerAvailableOverridesByMatch[matchId] || []);
      const effectiveProviderIds = providerIds.filter((playerId) => !providerOverrideSet.has(playerId));
      const uniqueIds = Array.from(new Set([...manualIds, ...effectiveProviderIds]));
      if (uniqueIds.length > 0) {
        merged[matchId] = uniqueIds;
      }
    });

    return merged;
  }, [matches, providerAvailableOverridesByMatch, providerUnavailableByMatch, unavailablePlayersByMatch]);

  const endDate = useMemo(() => new Date(), []);
  const startDate = useMemo(() => {
    const date = new Date();
    date.setMonth(date.getMonth() - 6);
    return date;
  }, []);

  const earliestSessionDate = useMemo(() => {
    let earliest = null;
    matches.forEach((match) => {
      const candidate = resolveEffectiveMatchDate(match);
      if (candidate && (!earliest || candidate < earliest)) {
        earliest = candidate;
      }
    });
    return earliest;
  }, [matches]);

  const sessionMatchIds = useMemo(() => matches.map((m) => String(m.id)), [matches]);

  const [precedingPlannedMatches, setPrecedingPlannedMatches] = useState([]);

  useEffect(() => {
    if (!currentTeam?.id || !earliestSessionDate) {
      setPrecedingPlannedMatches([]);
      return;
    }
    let active = true;
    getPrecedingPlannedMatches(currentTeam.id, earliestSessionDate.toISOString(), {
      excludeMatchIds: sessionMatchIds
    }).then((result) => {
      if (!active) return;
      if (result?.success) {
        setPrecedingPlannedMatches(result.matches || []);
      } else {
        console.warn('[PlanMatchesScreen] Failed to fetch preceding planned matches; the "Include upcoming" checkbox may incorrectly appear disabled.', result?.error);
        setPrecedingPlannedMatches([]);
      }
    }).catch((error) => {
      if (!active) return;
      console.warn('[PlanMatchesScreen] Unexpected error fetching preceding planned matches; the "Include upcoming" checkbox may incorrectly appear disabled.', error);
      setPrecedingPlannedMatches([]);
    });
    return () => { active = false; };
  }, [currentTeam?.id, earliestSessionDate, sessionMatchIds]);

  const virtualMatchesByPlayer = useMemo(() => {
    const map = new Map();
    precedingPlannedMatches.forEach((match) => {
      (match.squadSelection || []).forEach((playerId) => {
        map.set(playerId, (map.get(playerId) || 0) + 1);
      });
    });
    return map;
  }, [precedingPlannedMatches]);

  const canIncludePrecedingUpcoming = precedingPlannedMatches.length > 0;
  const effectiveIncludePreceding = includePrecedingUpcoming && canIncludePrecedingUpcoming;
  const effectiveVirtualMatchMap = useMemo(() => (
    effectiveIncludePreceding ? virtualMatchesByPlayer : null
  ), [effectiveIncludePreceding, virtualMatchesByPlayer]);

  const { attendanceStats, statsLoading, statsError } = useAttendanceStats(
    currentTeam?.id,
    startDate,
    endDate,
    effectiveVirtualMatchMap
  );
  const { defaults, defaultsError } = usePlanningDefaults(currentTeam?.id, loadTeamPreferences);

  const [rankings, setRankings] = useState(null);
  useEffect(() => {
    if (!currentTeam?.id) return;
    let active = true;
    getPlayerRankings(currentTeam.id).then(result => {
      if (active && result) setRankings(result.rankings);
    });
    return () => { active = false; };
  }, [currentTeam?.id]);

  const handleNavigateBack = useCallback(async () => {
    try {
      const fn = flushAutoSavesRef.current;
      if (typeof fn === 'function') {
        await fn();
      }
    } finally {
      if (onNavigateBack) onNavigateBack();
    }
  }, [onNavigateBack]);

  useEffect(() => {
    if (pushNavigationState) {
      pushNavigationState(() => {
        handleNavigateBack();
      });
    }

    return () => {
      if (removeFromNavigationStack) {
        removeFromNavigationStack();
      }
    };
  }, [pushNavigationState, removeFromNavigationStack, handleNavigateBack]);

  useEffect(() => {
    if (matches.length === 0) return;

    if (DEBUG_ENABLED) {
      console.debug('[PlanMatchesScreen] ensure selectedPlayersByMatch', {
        matchesCount: matches.length
      });
    }

    setSelectedPlayersByMatch((prev) => {
      let didChange = false;
      const next = { ...prev };
      matches.forEach((match) => {
        if (!next[match.id]) {
          next[match.id] = [];
          didChange = true;
        }
      });
      return didChange ? next : prev;
    });
  }, [matches, setSelectedPlayersByMatch]);

  // Track seeded match IDs locally to avoid re-triggering the effect
  const inviteSeededRef = useRef(new Set(inviteSeededMatchIds.map(String)));

  // Sync ref when persisted state loads (e.g., from a prior session)
  useEffect(() => {
    inviteSeededMatchIds.forEach((id) => inviteSeededRef.current.add(String(id)));
  }, [inviteSeededMatchIds]);

  // Auto-select invited players for matches that haven't been seeded yet
  useEffect(() => {
    if (providerAvailabilityLoading) return;
    if (matches.length === 0) return;

    const unseededMatchIds = matches
      .map((m) => String(m.id))
      .filter((id) => !inviteSeededRef.current.has(id));

    if (unseededMatchIds.length === 0) return;

    // Mark all unseeded matches as seeded in both ref and persisted state
    unseededMatchIds.forEach((id) => inviteSeededRef.current.add(id));
    setInviteSeededMatchIds((prev) => [...prev, ...unseededMatchIds]);

    // Build map of invited player IDs per unseeded match
    const invitedByUnseeded = {};
    unseededMatchIds.forEach((matchId) => {
      const invited = providerInvitedByMatch[matchId];
      if (invited && invited.length > 0) {
        const unavailableSet = new Set(mergedUnavailableByMatch[matchId] || []);
        const available = invited.filter((id) => !unavailableSet.has(id));
        if (available.length > 0) {
          invitedByUnseeded[matchId] = available;
        }
      }
    });

    if (Object.keys(invitedByUnseeded).length === 0) return;

    setSelectedPlayersByMatch((prev) => {
      let didChange = false;
      const next = { ...prev };
      Object.entries(invitedByUnseeded).forEach(([matchId, playerIds]) => {
        const current = next[matchId] || [];
        if (current.length === 0) {
          next[matchId] = playerIds;
          didChange = true;
        }
      });
      return didChange ? next : prev;
    });
  }, [
    providerAvailabilityLoading,
    matches,
    providerInvitedByMatch,
    mergedUnavailableByMatch,
    setInviteSeededMatchIds,
    setSelectedPlayersByMatch
  ]);

  const rosterPlayers = useMemo(() => {
    return (teamPlayers || [])
      .filter(player => player.on_roster !== false)
      .map(player => ({
        id: player.id,
        displayName: player.display_name || player.first_name || t('planMatches.unknownPlayer'),
        firstName: player.first_name || null,
        lastName: player.last_name || null,
        jerseyNumber: player.jersey_number,
        relatedUsers: player.relatedUsers || []
      }));
  }, [teamPlayers, t]);

  useEffect(() => {
    if (!defaults || matches.length === 0) return;

    const minimumPlayers = Math.max(0, getMinimumPlayersForFormat(defaults.format));
    const rosterCount = rosterPlayers.length;
    const defaultTarget = rosterCount > 0
      ? (typeof lastSquadSize === 'number' && lastSquadSize > 0
        ? Math.min(rosterCount, lastSquadSize)
        : Math.min(rosterCount, minimumPlayers + 2))
      : 0;

    if (DEBUG_ENABLED) {
      console.debug('[PlanMatchesScreen] ensure targetCounts', {
        matchesCount: matches.length,
        rosterCount,
        defaultTarget
      });
    }

    setTargetCounts((prev) => {
      let didChange = false;
      const next = { ...prev };
      matches.forEach((match) => {
        if (typeof next[match.id] !== 'number') {
          next[match.id] = defaultTarget;
          didChange = true;
        }
      });
      return didChange ? next : prev;
    });
  }, [defaults, matches, rosterPlayers.length, lastSquadSize, setTargetCounts]);

  const statsByPlayerId = useMemo(() => {
    const map = new Map();
    attendanceStats.forEach((stat) => {
      map.set(stat.playerId, stat);
    });
    return map;
  }, [attendanceStats]);

  const rosterWithStats = useMemo(() => {
    const withAttendance = rosterPlayers.map(player => {
      const stats = statsByPlayerId.get(player.id);
      return {
        ...player,
        practicesPerMatch: stats?.practicesPerMatch ?? 0,
        attendanceRate: stats?.attendanceRate ?? 0
      };
    });
    return attachStrengthScores(withAttendance, rankings);
  }, [rosterPlayers, statsByPlayerId, rankings]);

  const rosterById = useMemo(() => {
    const map = new Map();
    rosterWithStats.forEach(player => {
      map.set(player.id, player);
    });
    return map;
  }, [rosterWithStats]);

  const sortedRoster = useMemo(() => {
    return buildSortedRoster(rosterWithStats, sortMetric);
  }, [rosterWithStats, sortMetric]);

  const formatSchedule = (matchDate, matchTime, plannedStartTime) => {
    if (matchDate) {
      if (!matchTime) return matchDate;
      const trimmed = matchTime.slice(0, 5);
      return `${matchDate} ${trimmed}`;
    }

    if (plannedStartTime) {
      const localSchedule = formatLocalDateTimeFromISO(plannedStartTime);
      if (localSchedule) return localSchedule;
    }

    return t('teamMatches.timestamps.dateTbd');
  };

  const getUnavailableSet = useCallback((matchId) => new Set(mergedUnavailableByMatch[matchId] || []), [mergedUnavailableByMatch]);

  // Expose the latest selection/difficulty maps to useAutoSavePlan through refs so
  // the debounced flush always reads post-state values, not the snapshots closed
  // over at save-scheduling time.
  const selectedPlayersByMatchRef = useRef(selectedPlayersByMatch);
  selectedPlayersByMatchRef.current = selectedPlayersByMatch;
  const difficultyByMatchRef = useRef(difficultyByMatch);
  difficultyByMatchRef.current = difficultyByMatch;
  const matchTypeByMatchRef = useRef(matchTypeByMatch);
  matchTypeByMatchRef.current = matchTypeByMatch;
  const venueTypeByMatchRef = useRef(venueTypeByMatch);
  venueTypeByMatchRef.current = venueTypeByMatch;
  const formatByMatchRef = useRef(formatByMatch);
  formatByMatchRef.current = formatByMatch;
  const formationByMatchRef = useRef(formationByMatch);
  formationByMatchRef.current = formationByMatch;

  const getSelectionForMatch = useCallback((matchId) => selectedPlayersByMatchRef.current[matchId] || [], []);
  const getDifficultyForMatch = useCallback((matchId) => difficultyByMatchRef.current[matchId] || null, []);
  const getMatchTypeForMatch = useCallback((matchId) => matchTypeByMatchRef.current[matchId] || null, []);
  const getVenueTypeForMatch = useCallback((matchId) => venueTypeByMatchRef.current[matchId] || null, []);
  const getFormatForMatch = useCallback((matchId) => formatByMatchRef.current[matchId] || null, []);
  const getFormationForMatch = useCallback((matchId) => formationByMatchRef.current[matchId] || null, []);

  // Per-match remote-edit toast entries. Each entry carries the editor name
  // and opponent label so the floating toast stack can render the full message
  // without looking up the match again.
  const [remoteEditorNames, setRemoteEditorNames] = useState({});
  const remoteEditorLookupRef = useRef(new Map());
  const remoteEditorTimeoutsRef = useRef(new Map());

  const resolveRemoteEditorName = useCallback((userId, matchId, opponent) => {
    if (!userId || !matchId) return;
    if (userId === currentUserId) return;

    const stash = () => {
      setRemoteEditorNames(prev => ({
        ...prev,
        [matchId]: {
          name: remoteEditorLookupRef.current.get(userId) || null,
          opponent: opponent || '',
          fading: false
        }
      }));
      const previous = remoteEditorTimeoutsRef.current.get(matchId);
      if (previous) {
        clearTimeout(previous.fade);
        clearTimeout(previous.remove);
      }
      // Trigger a fade-out during the final 1s of the 10s display so the toast
      // doesn't disappear abruptly — opacity transitions via the className below.
      const fade = setTimeout(() => {
        setRemoteEditorNames(prev => {
          const current = prev[matchId];
          if (!current) return prev;
          return { ...prev, [matchId]: { ...current, fading: true } };
        });
      }, 9000);
      const remove = setTimeout(() => {
        setRemoteEditorNames(prev => {
          const { [matchId]: _omit, ...rest } = prev;
          return rest;
        });
        remoteEditorTimeoutsRef.current.delete(matchId);
      }, 10000);
      remoteEditorTimeoutsRef.current.set(matchId, { fade, remove });
    };

    if (remoteEditorLookupRef.current.has(userId)) {
      stash();
      return;
    }

    getUserDisplayName(userId).then((result) => {
      remoteEditorLookupRef.current.set(userId, result?.name || null);
      stash();
    });
  }, [currentUserId]);

  useEffect(() => () => {
    remoteEditorTimeoutsRef.current.forEach((timers) => {
      clearTimeout(timers.fade);
      clearTimeout(timers.remove);
    });
    remoteEditorTimeoutsRef.current.clear();
  }, []);

  // Latest matches ref so handleAutoSaveRemoteUpdate can resolve opponent labels
  // without re-creating its callback every time matches reflow.
  const matchesRef = useRef(matches);
  matchesRef.current = matches;

  const handleAutoSaveRemoteUpdate = useCallback(({ matchId, selection, difficulty, matchType, venueType, format, formation, lastUpdatedBy, source }) => {
    if (!matchId) return;

    setSelectedPlayersByMatch(prev => {
      const current = prev[matchId] || [];
      const normalized = Array.isArray(selection) ? selection : [];
      const sameLength = current.length === normalized.length;
      const sameOrder = sameLength && current.every((id, i) => id === normalized[i]);
      if (sameOrder) return prev;
      return { ...prev, [matchId]: normalized };
    });

    const mergeScalar = (setter, value) => {
      if (!value) return;
      setter(prev => {
        if (prev[matchId] === value) return prev;
        return { ...prev, [matchId]: value };
      });
    };

    mergeScalar(setDifficultyByMatch, difficulty);
    mergeScalar(setMatchTypeByMatch, matchType);
    mergeScalar(setVenueTypeByMatch, venueType);
    mergeScalar(setFormatByMatch, format);
    // When format changes (locally-won rebase, or a remote edit), sync the
    // paired formation so a subsequent local save can't send a stale
    // formationByMatch entry alongside a changed format.
    if (format) {
      setFormationByMatch(prev => {
        const next = formation || null;
        if (prev[matchId] === next) return prev;
        if (next === null) {
          if (!(matchId in prev)) return prev;
          const { [matchId]: _omit, ...rest } = prev;
          return rest;
        }
        return { ...prev, [matchId]: next };
      });
    }

    if (source === 'remote' && lastUpdatedBy && lastUpdatedBy !== currentUserId) {
      const match = (matchesRef.current || []).find(m => String(m.id) === String(matchId));
      const opponent = match?.opponent || '';
      resolveRemoteEditorName(lastUpdatedBy, matchId, opponent);
    }
  }, [currentUserId, resolveRemoteEditorName, setSelectedPlayersByMatch]);

  const {
    statusByMatch: autoSaveStatusByMatch,
    scheduleSave: scheduleAutoSave,
    flushAllPendingSaves: flushAutoSaves,
    retry: retryAutoSave,
    handleRemoteUpdate: handleAutoSaveRealtime
  } = useAutoSavePlan({
    matches,
    getSelection: getSelectionForMatch,
    getDifficulty: getDifficultyForMatch,
    getMatchType: getMatchTypeForMatch,
    getVenueType: getVenueTypeForMatch,
    getFormat: getFormatForMatch,
    getFormation: getFormationForMatch,
    onRemoteUpdate: handleAutoSaveRemoteUpdate,
    currentUserId,
    enabled: !readOnly
  });

  useRealtimeMatchPlan(currentTeam?.id, handleAutoSaveRealtime);

  flushAutoSavesRef.current = flushAutoSaves;

  // Best-effort flush on unmount so in-flight edits are persisted before the
  // component goes away.
  useEffect(() => () => {
    const fn = flushAutoSavesRef.current;
    if (typeof fn === 'function') fn();
  }, []);

  const scheduleAutoSaveIfManaged = useCallback((matchId) => {
    if (readOnly) return;
    const match = matches.find(m => String(m.id) === String(matchId));
    if (!match) return;
    if (match.state !== PLANNED_MATCH_STATE && match.state !== PENDING_MATCH_STATE) return;
    scheduleAutoSave(matchId);
  }, [matches, readOnly, scheduleAutoSave]);

  const togglePlayerSelection = useCallback((matchId, playerId) => {
    const unavailableSet = getUnavailableSet(matchId);

    setSelectedPlayersByMatch((prev) => {
      const current = new Set(prev[matchId] || []);
      const isSelected = current.has(playerId);

      // Unavailable players can be removed from an existing selection,
      // but cannot be newly added from the roster column.
      if (unavailableSet.has(playerId) && !isSelected) {
        return prev;
      }

      if (isSelected) {
        current.delete(playerId);
      } else {
        current.add(playerId);
      }
      return {
        ...prev,
        [matchId]: Array.from(current)
      };
    });
    resetPlanningStatusForMatch(matchId);
    scheduleAutoSaveIfManaged(matchId);
  }, [getUnavailableSet, resetPlanningStatusForMatch, scheduleAutoSaveIfManaged, setSelectedPlayersByMatch]);

  const togglePlayerUnavailable = useCallback((matchId, playerId) => {
    const providerUnavailableSet = new Set(providerUnavailableByMatch[matchId] || []);
    const providerOverrideSet = new Set(providerAvailableOverridesByMatch[matchId] || []);

    if (providerUnavailableSet.has(playerId)) {
      const isOverrideActive = providerOverrideSet.has(playerId);

      setProviderAvailableOverridesByMatch((prev) => {
        const current = new Set(prev[matchId] || []);
        if (isOverrideActive) {
          current.delete(playerId);
        } else {
          current.add(playerId);
        }
        return {
          ...prev,
          [matchId]: Array.from(current)
        };
      });

      if (!isOverrideActive) {
        setUnavailablePlayersByMatch((prev) => {
          const current = new Set(prev[matchId] || []);
          if (!current.has(playerId)) {
            return prev;
          }
          current.delete(playerId);
          return {
            ...prev,
            [matchId]: Array.from(current)
          };
        });
      }

      if (isOverrideActive) {
        setSelectedPlayersByMatch((prev) => {
          const current = new Set(prev[matchId] || []);
          if (current.has(playerId)) {
            current.delete(playerId);
            return {
              ...prev,
              [matchId]: Array.from(current)
            };
          }
          return prev;
        });
        scheduleAutoSaveIfManaged(matchId);
      }

      return;
    }

    const wasUnavailable = (unavailablePlayersByMatch[matchId] || []).includes(playerId);

    setUnavailablePlayersByMatch((prev) => {
      const current = new Set(prev[matchId] || []);
      if (current.has(playerId)) {
        current.delete(playerId);
      } else {
        current.add(playerId);
      }
      return {
        ...prev,
        [matchId]: Array.from(current)
      };
    });

    if (!wasUnavailable) {
      setSelectedPlayersByMatch((prev) => {
        const current = new Set(prev[matchId] || []);
        if (current.has(playerId)) {
          current.delete(playerId);
          return {
            ...prev,
            [matchId]: Array.from(current)
          };
        }
        return prev;
      });
      scheduleAutoSaveIfManaged(matchId);
    }
  }, [
    providerAvailableOverridesByMatch,
    providerUnavailableByMatch,
    scheduleAutoSaveIfManaged,
    setProviderAvailableOverridesByMatch,
    setSelectedPlayersByMatch,
    setUnavailablePlayersByMatch,
    unavailablePlayersByMatch
  ]);

  const handleResetProviderOverrides = useCallback((matchId) => {
    setProviderAvailableOverridesByMatch(prev => {
      const next = { ...prev };
      delete next[matchId];
      return next;
    });

    const invited = providerInvitedByMatch[matchId] || [];
    const providerUnavailableSet = new Set(providerUnavailableByMatch[matchId] || []);
    const manualUnavailableSet = new Set(unavailablePlayersByMatch[matchId] || []);
    const availableInvited = invited.filter(id =>
      !providerUnavailableSet.has(id) && !manualUnavailableSet.has(id)
    );

    setSelectedPlayersByMatch(prev => ({
      ...prev,
      [matchId]: availableInvited
    }));
    resetPlanningStatusForMatch(matchId);
    scheduleAutoSaveIfManaged(matchId);
  }, [
    providerInvitedByMatch,
    providerUnavailableByMatch,
    unavailablePlayersByMatch,
    resetPlanningStatusForMatch,
    scheduleAutoSaveIfManaged,
    setProviderAvailableOverridesByMatch,
    setSelectedPlayersByMatch
  ]);

  const handleReorderSelectedPlayers = useCallback((matchId, newOrderedIds) => {
    setSelectedPlayersByMatch((prev) => ({
      ...prev,
      [matchId]: newOrderedIds
    }));
    scheduleAutoSaveIfManaged(matchId);
  }, [scheduleAutoSaveIfManaged, setSelectedPlayersByMatch]);

  const handleSwapPlayers = useCallback((sourceMatchId, sourcePlayerId, targetMatchId, targetPlayerId) => {
    setSelectedPlayersByMatch(prev => {
      const sourceList = [...(prev[sourceMatchId] || [])];
      const targetList = [...(prev[targetMatchId] || [])];
      const si = sourceList.indexOf(sourcePlayerId);
      const ti = targetList.indexOf(targetPlayerId);
      if (si === -1 || ti === -1) return prev;
      sourceList[si] = targetPlayerId;
      targetList[ti] = sourcePlayerId;
      return { ...prev, [sourceMatchId]: sourceList, [targetMatchId]: targetList };
    });
    resetPlanningStatusForMatch(sourceMatchId);
    resetPlanningStatusForMatch(targetMatchId);
    scheduleAutoSaveIfManaged(sourceMatchId);
    scheduleAutoSaveIfManaged(targetMatchId);
  }, [resetPlanningStatusForMatch, scheduleAutoSaveIfManaged, setSelectedPlayersByMatch]);

  const { registerContainer, handleDragMove, handleDragEnd, crossMatchState, swapAnimation, slideInAnimation } = useCrossMatchDrag({
    selectedPlayersByMatch,
    unavailablePlayersByMatch: mergedUnavailableByMatch,
    onSwapPlayers: handleSwapPlayers
  });

  const updateTargetCount = (matchId, value) => {
    const parsed = Number(value);
    const safeValue = Number.isFinite(parsed) ? Math.max(0, parsed) : 0;
    const capped = rosterPlayers.length > 0 ? Math.min(rosterPlayers.length, safeValue) : safeValue;
    setTargetCounts((prev) => ({
      ...prev,
      [matchId]: capped
    }));
    setLastSquadSize(capped);
  };

  const runAutoSelectSingleMatch = useCallback((matchId, metric, singleMatchStrategy) => {
    const selected = autoSelectSingleMatch({
      rosterWithStats,
      metric,
      targetCount: targetCounts[matchId] || 0,
      unavailableIds: mergedUnavailableByMatch[matchId],
      singleMatchStrategy
    });

    setSelectedPlayersByMatch((prev) => ({
      ...prev,
      [matchId]: selected
    }));
    resetPlanningStatusForMatch(matchId);
    scheduleAutoSaveIfManaged(matchId);
  }, [mergedUnavailableByMatch, resetPlanningStatusForMatch, rosterWithStats, scheduleAutoSaveIfManaged, targetCounts, setSelectedPlayersByMatch]);

  const runAutoSelectMultipleMatches = useCallback((metric, ensureCoverage, distributionStrategy, strongMatchId) => {
    const nextSelections = autoSelectMultipleMatches({
      rosterWithStats,
      metric,
      matches,
      targetCounts,
      unavailableByMatch: mergedUnavailableByMatch,
      ensureCoverage,
      distributionStrategy,
      strongMatchId
    });

    setSelectedPlayersByMatch((prev) => ({
      ...prev,
      ...nextSelections
    }));
    matches.forEach(match => {
      resetPlanningStatusForMatch(match.id);
      scheduleAutoSaveIfManaged(match.id);
    });
  }, [matches, mergedUnavailableByMatch, resetPlanningStatusForMatch, rosterWithStats, scheduleAutoSaveIfManaged, targetCounts, setSelectedPlayersByMatch]);

  const isPlayerInMultipleMatches = useCallback((playerId) => {
    const matchesWithPlayer = matches.filter(match =>
      (selectedPlayersByMatch[match.id] || []).includes(playerId)
    );
    return matchesWithPlayer.length > 1;
  }, [matches, selectedPlayersByMatch]);

  const handleDifficultyChange = useCallback((matchId, value) => {
    setDifficultyByMatch((prev) => ({ ...prev, [matchId]: value }));
    resetPlanningStatusForMatch(matchId);
    scheduleAutoSaveIfManaged(matchId);
  }, [resetPlanningStatusForMatch, scheduleAutoSaveIfManaged]);

  const handleMatchTypeChange = useCallback((matchId, value) => {
    setMatchTypeByMatch((prev) => ({ ...prev, [matchId]: value }));
    resetPlanningStatusForMatch(matchId);
    scheduleAutoSaveIfManaged(matchId);
  }, [resetPlanningStatusForMatch, scheduleAutoSaveIfManaged]);

  const handleVenueTypeChange = useCallback((matchId, value) => {
    setVenueTypeByMatch((prev) => ({ ...prev, [matchId]: value }));
    resetPlanningStatusForMatch(matchId);
    scheduleAutoSaveIfManaged(matchId);
  }, [resetPlanningStatusForMatch, scheduleAutoSaveIfManaged]);

  const handleFormatChange = useCallback((matchId, value) => {
    // Pair the format change with a formation valid for the new format. Prefer
    // the team's preferred formation (defaults.formation, derived from
    // team_preferences) when it's compatible; otherwise fall back to the
    // format's default formation.
    const formatConfig = FORMAT_CONFIGS[value];
    const preferredFormation = defaults?.formation || null;
    const nextFormation = formatConfig?.formations?.includes(preferredFormation)
      ? preferredFormation
      : (formatConfig?.defaultFormation || null);

    setFormatByMatch((prev) => ({ ...prev, [matchId]: value }));
    if (nextFormation) {
      setFormationByMatch((prev) => ({ ...prev, [matchId]: nextFormation }));
    }
    resetPlanningStatusForMatch(matchId);
    scheduleAutoSaveIfManaged(matchId);
  }, [defaults?.formation, resetPlanningStatusForMatch, scheduleAutoSaveIfManaged]);

  const isPlayerSelectedInOtherMatch = useCallback((matchId, playerId) => {
    return matches.some(other =>
      other.id !== matchId && (selectedPlayersByMatch[other.id] || []).includes(playerId)
    );
  }, [matches, selectedPlayersByMatch]);

  const isPlayerSelectedAndOnlyAvailableHere = useCallback((matchId, playerId) => {
    // Only applies when planning 2+ matches
    if (matches.length < 2) {
      return false;
    }

    // Player must be selected for this match
    const selectedForCurrentMatch = (selectedPlayersByMatch[matchId] || []).includes(playerId);
    if (!selectedForCurrentMatch) {
      return false;
    }

    // Player must be unavailable in at least one other match
    return matches.some(other =>
      other.id !== matchId && (mergedUnavailableByMatch[other.id] || []).includes(playerId)
    );
  }, [matches, mergedUnavailableByMatch, selectedPlayersByMatch]);

  const handleAutoSelect = () => {
    setAutoSelectMatchId(null);
    setShowAutoSelectModal(true);
    if (pushNavigationState) {
      pushNavigationState(() => setShowAutoSelectModal(false), 'PlanMatches-AutoSelect');
    }
  };

  const handleAutoSelectConfirm = (resolved = {}) => {
    setShowAutoSelectModal(false);
    if (removeFromNavigationStack) {
      removeFromNavigationStack();
    }
    if (matches.length > 1) {
      runAutoSelectMultipleMatches(
        autoSelectSettings.metric,
        autoSelectSettings.ensureCoverage,
        autoSelectSettings.distributionStrategy,
        resolved.strongMatchId ?? autoSelectSettings.strongMatchId
      );
      setAutoSelectMatchId(null);
      return;
    }

    const matchId = autoSelectMatchId || matches[0]?.id;
    if (matchId) {
      runAutoSelectSingleMatch(matchId, sortMetric, autoSelectSettings.singleMatchStrategy);
    }
    setAutoSelectMatchId(null);
  };

  const handleAutoSelectCancel = () => {
    setShowAutoSelectModal(false);
    if (removeFromNavigationStack) {
      removeFromNavigationStack();
    }
    setAutoSelectMatchId(null);
  };

  const handlePlanMatch = async (match) => {
    if (!currentTeam?.id || !defaults) {
      return;
    }

    // Drain pending auto-saves so "Set up match" reads the freshest squad
    // from the DB; otherwise ConfigurationScreen might open with a version
    // one toggle stale.
    const flush = flushAutoSavesRef.current;
    if (typeof flush === 'function') {
      try { await flush(); } catch (_e) { /* best effort */ }
    }

    const selectedIds = selectedPlayersByMatch[match.id] || [];
    if (selectedIds.length === 0) {
      setNotification({
        isOpen: true,
        title: t('planMatches.notifications.noPlayersTitle'),
        message: t('planMatches.notifications.noPlayersMessage')
      });
      return;
    }

    setPlanningStatus((prev) => ({
      ...prev,
      [match.id]: 'loading'
    }));

    const isPlannedMatch = match.state === PLANNED_MATCH_STATE;
    const isNewMatch = match.id === MANUAL_MATCH_SENTINEL_ID;
    const teamName = currentTeam.club?.name || currentTeam.name || null;
    const overrideFormat = formatByMatch[match.id] || defaults.format;
    // Resolve the formation using the same preference→default logic as
    // handleFormatChange. A candidate can come from a local format edit
    // (formationByMatch) or from the team preference (defaults.formation);
    // either way, we only accept it if it is valid for overrideFormat.
    // Otherwise fall back to the format's default formation. This guards
    // against stale pairings (e.g. Coach A sets format=7v7 remotely, so
    // Coach B's formatByMatch receives '7v7' via the realtime update, but
    // their formationByMatch entry is empty and defaults.formation may be
    // a 5v5 formation).
    const overrideFormatConfig = FORMAT_CONFIGS[overrideFormat];
    const candidateFormation = formationByMatch[match.id] || defaults.formation;
    const overrideFormation = overrideFormatConfig?.formations?.includes(candidateFormation)
      ? candidateFormation
      : (overrideFormatConfig?.defaultFormation || defaults.formation);
    const matchDefaults = {
      ...defaults,
      format: overrideFormat,
      formation: overrideFormation,
      matchType: matchTypeByMatch[match.id] || defaults.matchType,
      venueType: venueTypeByMatch[match.id] || defaults.venueType,
      difficulty: difficultyByMatch[match.id] || defaults.difficulty
    };
    let result;
    if (isPlannedMatch) {
      result = await replanPlannedMatch({
        upcomingMatch: match,
        selectedSquadIds: selectedIds,
        rosterPlayers: teamPlayers,
        defaults: matchDefaults
      });
    } else if (isNewMatch) {
      result = await createManualPlannedMatch({
        teamId: currentTeam.id,
        teamName,
        opponent: match.opponent,
        plannedStartTime: match.plannedStartTime || null,
        selectedSquadIds: selectedIds,
        rosterPlayers: teamPlayers,
        defaults: matchDefaults
      });
    } else {
      result = await planUpcomingMatch({
        teamId: currentTeam.id,
        teamName,
        upcomingMatch: match,
        selectedSquadIds: selectedIds,
        rosterPlayers: teamPlayers,
        defaults: matchDefaults
      });
    }

    if (result.success) {
      const savedMatchId = result.matchId || match.id;
      const matchIdChanged = savedMatchId !== match.id;
      // For upcoming → planned transitions, remember the original upcoming id
      // so useProviderAvailability keeps its query key stable. Without this,
      // matchIdsKey would flip from [upcomingId] to [plannedId], triggering a
      // fetch for plannedId (which returns nothing — provider data is keyed by
      // upcoming_match_id in the DB) and wiping the existing provider
      // unavailability indicators.
      const isUpcomingTransition = matchIdChanged && !isPlannedMatch && !isNewMatch;
      const matchUpdates = { id: savedMatchId, state: PLANNED_MATCH_STATE };
      if (isUpcomingTransition) {
        matchUpdates.upcomingMatchId = match.id;
      }

      // Update the match entry with the real DB ID and planned state
      updateMatchById(match.id, matchUpdates);

      // If the match ID changed (new/upcoming → DB record), migrate per-match keys
      if (matchIdChanged) {
        migratePerMatchKey(setSelectedPlayersByMatch, match.id, savedMatchId);
        migratePerMatchKey(setDifficultyByMatch, match.id, savedMatchId);
        migratePerMatchKey(setMatchTypeByMatch, match.id, savedMatchId);
        migratePerMatchKey(setVenueTypeByMatch, match.id, savedMatchId);
        migratePerMatchKey(setFormatByMatch, match.id, savedMatchId);
        migratePerMatchKey(setFormationByMatch, match.id, savedMatchId);
        migratePerMatchKey(setUnavailablePlayersByMatch, match.id, savedMatchId);
        migratePerMatchKey(setProviderAvailableOverridesByMatch, match.id, savedMatchId);
      }

      setPlanningStatus((prev) => ({
        ...prev,
        [savedMatchId]: 'done'
      }));
      setPlannedMatchIds((prev) => {
        const id = String(savedMatchId);
        if (prev.some((existing) => String(existing) === id)) {
          return prev;
        }
        return [...prev, id];
      });
      if (result.warning) {
        showWarning(result.warning);
      } else {
        showSuccess(t(
          isPlannedMatch
            ? 'planMatches.notifications.squadUpdated'
            : isNewMatch
              ? 'planMatches.notifications.matchCreated'
              : 'planMatches.notifications.pendingCreated'
        ));
      }
    } else {
      setPlanningStatus((prev) => ({
        ...prev,
        [match.id]: 'error'
      }));
      setNotification({
        isOpen: true,
        title: t('planMatches.notifications.planningFailed'),
        message: result.error || t('planMatches.notifications.planningFailedMessage')
      });
    }
  };

  // Shareable match IDs: only real DB matches (not manual sentinel), in planned/pending state
  const shareableMatchIds = useMemo(() => {
    return matches
      .filter(m => m.id && m.id !== MANUAL_MATCH_SENTINEL_ID && (m.state === PLANNED_MATCH_STATE || m.state === PENDING_MATCH_STATE))
      .map(m => m.id);
  }, [matches]);

  const handleCopyPlanLink = useCallback(async () => {
    if (shareableMatchIds.length === 0) return;
    const result = await copyPlanMatchesUrlToClipboard(shareableMatchIds);
    if (result.success) {
      showSuccess(t('planMatches.shareLinkCopied'));
    } else {
      showWarning(t('planMatches.shareLinkFailed'));
    }
  }, [shareableMatchIds, showSuccess, showWarning, t]);

  if (!currentTeam?.id) {
    return (
      <div className="space-y-4">
        <div className="flex items-center justify-between">
          <h1 className="text-2xl font-bold text-sky-300">{t('planMatches.title')}</h1>
          <Button onClick={handleNavigateBack} variant="secondary" size="sm">
            {t('planMatches.back')}
          </Button>
        </div>
        <Card padding="lg" className="text-slate-300 text-sm">
          {t('planMatches.teamRequired')}
        </Card>
      </div>
    );
  }

  if (matches.length === 0) {
    return (
      <div className="space-y-4">
        <div className="flex items-center justify-between">
          <h1 className="text-2xl font-bold text-sky-300">{t('planMatches.title')}</h1>
          <Button onClick={handleNavigateBack} variant="secondary" size="sm">
            {t('planMatches.back')}
          </Button>
        </div>
        <Card padding="lg" className="text-slate-300 text-sm">
          {t('planMatches.noMatches')}
        </Card>
      </div>
    );
  }

  return (
    <div className="space-y-4 lg:space-y-3">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <h1 className="text-2xl font-bold text-sky-300">{t('planMatches.title')}</h1>
        </div>
        <Button onClick={handleNavigateBack} variant="secondary" size="sm">
          {t('planMatches.back')}
        </Button>
      </div>

      <PlanMatchesToolbar
        sortMetric={sortMetric}
        onSortChange={setSortMetric}
        includePrecedingUpcoming={effectiveIncludePreceding}
        onToggleIncludePrecedingUpcoming={setIncludePrecedingUpcoming}
        canIncludePrecedingUpcoming={canIncludePrecedingUpcoming}
        precedingUpcomingCount={precedingPlannedMatches.length}
        statsLoading={statsLoading}
        statsError={statsError}
        defaultsError={defaultsError}
        onRecommend={handleAutoSelect}
        onShareLink={handleCopyPlanLink}
        canShare={shareableMatchIds.length > 0}
      />

      {readOnly && <Alert variant="warning">{t('planMatches.matchCard.readOnlyBanner')}</Alert>}

      <div className={`grid gap-4 ${matches.length > 1 ? 'lg:grid-cols-2' : ''}`}>
        {matches.map((match) => {
          const selectedIds = selectedPlayersByMatch[match.id] || [];
          const invitedIds = providerInvitedByMatch[match.id] || [];
          const unavailableIds = mergedUnavailableByMatch[match.id] || [];
          const providerUnavailableIds = providerUnavailableByMatch[match.id] || [];
          const matchResponses = providerResponseByMatch[match.id] || null;
          const invitationsSent = matchResponses && selectedIds.some(
            (playerId) => matchResponses[playerId] === 'accepted'
          );
          const playerResponses = invitationsSent ? matchResponses : null;

          return (
            <MatchCard
              key={match.id}
              match={match}
              matchId={match.id}
              matchCount={matches.length}
              roster={sortedRoster}
              rosterById={rosterById}
              selectedIds={selectedIds}
              invitedIds={invitedIds}
              unavailableIds={unavailableIds}
              providerUnavailableIds={providerUnavailableIds}
              playerResponses={playerResponses}
              sortMetric={sortMetric}
              planningStatus={planningStatus[match.id]}
              canPlan={Boolean(defaults)}
              difficulty={difficultyByMatch[match.id] || defaults?.difficulty}
              onDifficultyChange={handleDifficultyChange}
              matchType={matchTypeByMatch[match.id] || defaults?.matchType}
              onMatchTypeChange={handleMatchTypeChange}
              venueType={venueTypeByMatch[match.id] || defaults?.venueType}
              onVenueTypeChange={handleVenueTypeChange}
              format={formatByMatch[match.id] || defaults?.format}
              onFormatChange={handleFormatChange}
              onResetProviderOverrides={() => handleResetProviderOverrides(match.id)}
              onPlanMatch={() => handlePlanMatch(match)}
              onToggleSelect={(playerId) => togglePlayerSelection(match.id, playerId)}
              onToggleUnavailable={(playerId) => togglePlayerUnavailable(match.id, playerId)}
              formatSchedule={formatSchedule}
              isSelectedInOtherMatch={(playerId) => isPlayerSelectedInOtherMatch(match.id, playerId)}
              isSelectedAndOnlyAvailableHere={(playerId) => isPlayerSelectedAndOnlyAvailableHere(match.id, playerId)}
              isPlayerInMultipleMatches={isPlayerInMultipleMatches}
              onReorderSelectedPlayers={handleReorderSelectedPlayers}
              registerContainer={registerContainer}
              onCrossDragMove={handleDragMove}
              onCrossDragEnd={handleDragEnd}
              crossMatchState={crossMatchState}
              swapAnimation={swapAnimation}
              slideInAnimation={slideInAnimation}
              autoSaveStatus={autoSaveStatusByMatch[match.id]}
              readOnly={readOnly}
              onRetryAutoSave={retryAutoSave}
            />
          );
        })}
      </div>

      <AutoSelectModal
        isOpen={showAutoSelectModal}
        matches={matches}
        autoSelectMatches={autoSelectMatches}
        rosterCount={rosterPlayers.length}
        targetCounts={targetCounts}
        autoSelectSettings={autoSelectSettings}
        onUpdateTargetCount={updateTargetCount}
        onUpdateSettings={setAutoSelectSettings}
        onCancel={handleAutoSelectCancel}
        onConfirm={handleAutoSelectConfirm}
        formatSchedule={formatSchedule}
      />

      <NotificationModal
        isOpen={notification.isOpen}
        onClose={() => setNotification({ isOpen: false, title: '', message: '' })}
        title={notification.title}
        message={notification.message}
      />

      {Object.keys(remoteEditorNames).length > 0 && (
        <div
          className="fixed top-[max(env(safe-area-inset-top),4rem)] left-1/2 -translate-x-1/2 z-50 flex flex-col gap-2 items-center pointer-events-none"
          role="status"
          aria-live="polite"
        >
          {Object.entries(remoteEditorNames).map(([matchId, entry]) => (
            <div
              key={matchId}
              className={`pointer-events-auto px-6 py-3 bg-sky-900/80 backdrop-blur-sm border border-sky-600 rounded-lg shadow-2xl shadow-sky-500/50 transition-opacity duration-1000 ease-linear ${entry.fading ? 'opacity-0' : 'opacity-100'} ${PLAN_MATCHES_GLOW_EFFECTS.remoteEdit}`}
            >
              <p className="text-sky-300 text-sm font-medium">
                {entry.name
                  ? t('planMatches.matchCard.autoSaveRemoteFloating', { name: entry.name, opponent: entry.opponent })
                  : t('planMatches.matchCard.autoSaveRemoteFloatingAnon', { opponent: entry.opponent })}
              </p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
