import { useState, useEffect } from 'react';
import { BREAKPOINTS } from '../constants/layoutConstants';

// Module-level: closes over nothing reactive (only the BREAKPOINTS constant and
// the window global), so it's stable without useCallback. SSR/test-safe — returns
// false when `window` is unavailable.
const isViewportAtLeastSm = () =>
  typeof window !== 'undefined' && window.innerWidth >= BREAKPOINTS.SM;

/**
 * Tracks whether the viewport is at least the Tailwind `sm` breakpoint (640px).
 *
 * Single source of truth for the responsive layout decisions in the statistics
 * tabs (e.g. condensing match dates and hiding secondary badges on narrow
 * screens).
 *
 * @returns {boolean} true when the viewport is at least `BREAKPOINTS.SM` wide.
 */
export function useIsAtLeastSm() {
  // Lazy initializer computes the correct value before first paint (and is
  // SSR-safe). matchMedia drives subsequent updates.
  const [value, setValue] = useState(isViewportAtLeastSm);

  useEffect(() => {
    if (typeof window === 'undefined' || !window.matchMedia) return undefined;
    // A media-query listener fires only when the breakpoint boundary is crossed,
    // unlike a `resize` listener which fires on every pixel of drag.
    const mql = window.matchMedia(`(min-width: ${BREAKPOINTS.SM}px)`);
    const onChange = (event) => setValue(event.matches);
    mql.addEventListener('change', onChange);
    return () => mql.removeEventListener('change', onChange);
  }, []);

  return value;
}
