import React, { useState, useEffect } from 'react';
import PropTypes from 'prop-types';
import { useTranslation } from 'react-i18next';
import { Button } from '../shared/UI';
import { Alert } from '../shared/Alert';
import { ModalShell } from '../shared/ModalShell';
import { Card } from '../shared/Card';
import { useAuth } from '../../contexts/AuthContext';
import { getInvitationContext, markInviteGatewayPending, clearInviteGatewayPending } from '../../utils/invitationUtils';
import { GoogleAuthButton } from './GoogleAuthButton';
import { AppleAuthButton } from './AppleAuthButton';
import { shouldOfferAppleSignIn } from '../../utils/platform';
import {
  Mail,
  Users,
  Shield,
  UserPlus,
  LogIn
} from 'lucide-react';

export function InvitationWelcome({ invitationParams, onRequestSignIn, onRequestSignUp, onClose }) {
  const { t } = useTranslation('auth');
  const { user, signInWithGoogle, signInWithApple } = useAuth();
  const [oauthError, setOauthError] = useState('');
  const appleAvailable = shouldOfferAppleSignIn();

  const invitationContext = getInvitationContext(invitationParams);

  // If the visitor is already authenticated (e.g. they clicked a still-valid
  // quick-link and the session was set), close the gateway so the standard
  // pending-invitation notification can surface and complete the join.
  useEffect(() => {
    if (user) {
      onClose();
    }
  }, [user, onClose]);

  const getRoleIcon = (role) => {
    switch (role?.toLowerCase()) {
      case 'admin': return Shield;
      case 'coach': return Users;
      case 'parent': return UserPlus;
      case 'player': return Users;
      default: return Users;
    }
  };

  // Display name from the URL-carried team/club names. Never a fake "loading".
  const getTeamDisplayName = () => {
    const team = invitationContext?.teamName;
    const club = invitationContext?.clubName;
    if (club && team) return `${club} ${team}`;
    if (team) return team;
    if (club) return club;
    return t('invitation.gateway.teamFallback');
  };

  // OAuth redirects away on success, so the flag must be set before the call.
  // If it returns/throws an error, no redirect happened — clear the flag so a
  // later unrelated sign-in doesn't trigger a spurious "no invitation" notice.
  const handleGoogle = async () => {
    setOauthError('');
    markInviteGatewayPending();
    try {
      const { error } = await signInWithGoogle();
      if (error) {
        clearInviteGatewayPending();
        setOauthError(error.message);
      }
    } catch (err) {
      clearInviteGatewayPending();
      setOauthError(err.message || t('invitation.gateway.oauthFailed'));
    }
  };

  const handleApple = async () => {
    setOauthError('');
    markInviteGatewayPending();
    try {
      const { error } = await signInWithApple();
      if (error) {
        clearInviteGatewayPending();
        setOauthError(error.message);
      }
    } catch (err) {
      clearInviteGatewayPending();
      setOauthError(err.message || t('invitation.gateway.oauthFailed'));
    }
  };

  const handleSignUp = () => {
    markInviteGatewayPending();
    onRequestSignUp?.();
  };

  const handleSignIn = () => {
    markInviteGatewayPending();
    onRequestSignIn?.();
  };

  const RoleIcon = getRoleIcon(invitationContext?.role);

  return (
    <ModalShell
      title={t('invitation.title')}
      subtitle={t('invitation.subtitle')}
      icon={Mail}
      iconColor="sky"
      onClose={onClose}
    >
      {/* Invitation Details */}
      {invitationContext && (
        <Card className="mb-6">
          <div className="space-y-3">
            <div className="flex items-center space-x-3">
              <Users className="w-5 h-5 text-sky-400" />
              <div>
                <p className="text-slate-300 font-medium">{t('invitation.teamLabel')}</p>
                <p className="text-slate-400 text-sm">{getTeamDisplayName()}</p>
              </div>
            </div>

            <div className="flex items-center space-x-3">
              <RoleIcon className="w-5 h-5 text-emerald-400" />
              <div>
                <p className="text-slate-300 font-medium">{t('invitation.roleLabel')}</p>
                <p className="text-slate-400 text-sm">{invitationContext.displayRole}</p>
              </div>
            </div>
          </div>
        </Card>
      )}

      <p className="text-slate-300 text-sm font-medium mb-4">{t('invitation.gateway.prompt')}</p>

      {oauthError && (
        <Alert variant="error" className="mb-4">{oauthError}</Alert>
      )}

      {/* OAuth + account options */}
      <div className="space-y-3">
        <GoogleAuthButton onClick={handleGoogle} mode="continue" />
        {appleAvailable && (
          <AppleAuthButton onClick={handleApple} mode="continue" />
        )}

        <div className="flex items-center gap-3 text-xs text-slate-500">
          <div className="h-px flex-1 bg-slate-600" />
          <span>{t('providers.divider')}</span>
          <div className="h-px flex-1 bg-slate-600" />
        </div>

        <Button
          onClick={handleSignUp}
          variant="primary"
          size="lg"
          Icon={UserPlus}
          className="w-full"
        >
          {t('invitation.gateway.createAccount')}
        </Button>

        <Button
          onClick={handleSignIn}
          variant="secondary"
          size="lg"
          Icon={LogIn}
          className="w-full"
        >
          {t('invitation.gateway.signIn')}
        </Button>
      </div>

      {/* Validity note */}
      <div className="mt-6 text-center">
        <p className="text-xs text-slate-500">{t('invitation.validity')}</p>
      </div>
    </ModalShell>
  );
}

InvitationWelcome.propTypes = {
  invitationParams: PropTypes.object,
  onRequestSignIn: PropTypes.func,
  onRequestSignUp: PropTypes.func,
  onClose: PropTypes.func.isRequired
};
