import React, { useState, useEffect, useCallback, useMemo } from 'react';
import PropTypes from 'prop-types';
import { useTranslation } from 'react-i18next';
import { Button, Textarea } from '../shared/UI';
import { Alert } from '../shared/Alert';
import { FormGroup } from '../shared/FormGroup';
import { ModalShell } from '../shared/ModalShell';
import { ChecklistBox } from './ChecklistBox';
import { useTeam } from '../../contexts/TeamContext';
import { toggleInArray } from '../../utils/relationshipUtils';
import { HeartHandshake, Clock, CheckCircle, XCircle, MessageSquare } from 'lucide-react';

// Lets a parent already on the team request a relationship to a roster player.
// The request is pending until a coach/admin approves it (never self-asserted).
export function PlayerRelationshipRequestModal({ team, onClose }) {
  const { t } = useTranslation('team');
  const {
    getTeamPlayers,
    getRelatedPlayerIds,
    requestPlayerRelationship,
    getUserPlayerRequests,
    cancelPlayerRelationship,
    clearError,
    loading,
    error
  } = useTeam();

  const [rosterPlayers, setRosterPlayers] = useState([]);
  const [relatedIds, setRelatedIds] = useState([]);
  const [userRequests, setUserRequests] = useState([]);
  const [selectedIds, setSelectedIds] = useState([]);
  const [message, setMessage] = useState('');
  const [successMessage, setSuccessMessage] = useState('');

  const loadUserRequests = useCallback(async () => {
    if (!team?.id) return;
    const requests = await getUserPlayerRequests();
    setUserRequests(requests.filter((r) => r.player?.team_id === team.id));
  }, [team?.id, getUserPlayerRequests]);

  useEffect(() => {
    if (!team?.id) return;
    clearError(); // drop any stale global error so it doesn't show on open
    getTeamPlayers(team.id).then((players) => setRosterPlayers(players || [])).catch(() => setRosterPlayers([]));
    getRelatedPlayerIds(team.id).then(setRelatedIds).catch(() => setRelatedIds([]));
    loadUserRequests();
  }, [team?.id, clearError, getTeamPlayers, getRelatedPlayerIds, loadUserRequests]);

  const togglePlayer = (playerId) => setSelectedIds((prev) => toggleInArray(prev, playerId));

  // Players the parent is already linked to or already has a pending request for
  // are not selectable — keeps the request list to genuinely new claims.
  const selectableItems = useMemo(() => {
    const pendingPlayerIds = userRequests
      .filter((r) => r.status === 'pending')
      .map((r) => r.player?.id)
      .filter(Boolean);
    const excludedIds = new Set([...relatedIds, ...pendingPlayerIds]);
    return rosterPlayers
      .filter((p) => !excludedIds.has(p.id))
      .map((p) => ({
        id: p.id,
        label: p.display_name || p.first_name,
        sublabel: p.jersey_number ? `#${p.jersey_number}` : undefined
      }));
  }, [userRequests, relatedIds, rosterPlayers]);

  const handleSubmit = async () => {
    if (selectedIds.length === 0) return;
    setSuccessMessage(''); // clear any prior banner so it can't linger next to an error
    const submitted = selectedIds;
    const results = await Promise.all(
      submitted.map((playerId) => requestPlayerRelationship(playerId, message.trim()))
    );
    await loadUserRequests();
    // Keep only the ones that failed selected — the successes are now pending and
    // excluded, so a retry must not resubmit them (would hit the unique index).
    setSelectedIds(submitted.filter((_, i) => !results[i]));
    if (results.every(Boolean)) {
      setSuccessMessage(t('playerRequestModal.success.submitted'));
      setMessage('');
    }
  };

  const handleCancel = async (requestId) => {
    const result = await cancelPlayerRelationship(requestId);
    if (result) {
      await loadUserRequests();
    }
  };

  if (!team) return null;

  const teamLabel = team.club?.long_name ? `${team.club.long_name} ${team.name}` : team.name;

  return (
    <ModalShell title={t('playerRequestModal.header.title')} onClose={onClose} maxWidth="lg">
      {error && (
        <Alert variant="error" className="mb-4">{error}</Alert>
      )}

      <div className="text-center mb-6">
        <HeartHandshake className="h-8 w-8 text-rose-400 mx-auto mb-3" />
        <p className="text-slate-400 text-sm">
          {t('playerRequestModal.header.subtitle')} <strong>{teamLabel}</strong>
        </p>
      </div>

      {successMessage && (
        <Alert variant="success" className="mb-4">{successMessage}</Alert>
      )}

      {selectableItems.length > 0 ? (
        <>
          <FormGroup label={t('playerRequestModal.form.playersLabel')}>
            <ChecklistBox
              items={selectableItems}
              selectedIds={selectedIds}
              onToggle={togglePlayer}
              disabled={loading}
              ariaLabel={t('playerRequestModal.form.playersLabel')}
            />
            <p className="text-slate-500 text-xs mt-1">{t('playerRequestModal.form.playersHint')}</p>
          </FormGroup>

          <FormGroup label={t('playerRequestModal.form.messageLabel')}>
            <Textarea
              value={message}
              onChange={(e) => setMessage(e.target.value)}
              placeholder={t('playerRequestModal.form.messagePlaceholder')}
              rows={3}
              maxLength={1000}
            />
          </FormGroup>

          <div className="flex justify-between">
            <Button onClick={onClose} variant="secondary">
              {t('playerRequestModal.buttons.cancel')}
            </Button>
            <Button
              onClick={handleSubmit}
              disabled={loading || selectedIds.length === 0}
              Icon={loading ? null : MessageSquare}
            >
              {loading ? t('playerRequestModal.buttons.sending') : t('playerRequestModal.buttons.send')}
            </Button>
          </div>
        </>
      ) : (
        <p className="text-slate-400 text-sm text-center py-4">
          {t('playerRequestModal.empty.noSelectablePlayers')}
        </p>
      )}

      {userRequests.length > 0 && (
        <div className="mt-6 pt-6 border-t border-slate-600">
          <h4 className="font-medium text-slate-200 mb-3">{t('playerRequestModal.yourRequests.title')}</h4>
          <div className="space-y-2">
            {userRequests.map((request) => (
              <div key={request.id} className="p-3">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <span className={`inline-flex items-center px-2 py-1 text-xs font-medium rounded-full ${
                      request.status === 'pending'
                        ? 'bg-amber-100 text-amber-800'
                        : request.status === 'approved'
                        ? 'bg-emerald-100 text-emerald-800'
                        : 'bg-rose-100 text-rose-800'
                    }`}>
                      {request.status === 'pending' && <Clock className="h-3 w-3 mr-1" />}
                      {request.status === 'approved' && <CheckCircle className="h-3 w-3 mr-1" />}
                      {(request.status === 'rejected' || request.status === 'cancelled') && <XCircle className="h-3 w-3 mr-1" />}
                      {t(`playerRequestModal.status.${request.status}`)}
                    </span>
                    <span className="text-sm text-slate-300">
                      {request.player?.display_name || request.player?.first_name}
                    </span>
                  </div>
                  {request.status === 'pending' && (
                    <Button size="sm" variant="secondary" onClick={() => handleCancel(request.id)} disabled={loading}>
                      {t('playerRequestModal.yourRequests.cancel')}
                    </Button>
                  )}
                </div>
                {request.review_notes && (
                  <p className="text-sm text-slate-400 mt-2 p-2 bg-slate-600 rounded">
                    <strong>{t('playerRequestModal.yourRequests.reviewLabel')}</strong> {request.review_notes}
                  </p>
                )}
              </div>
            ))}
          </div>
        </div>
      )}
    </ModalShell>
  );
}

PlayerRelationshipRequestModal.propTypes = {
  team: PropTypes.shape({
    id: PropTypes.string,
    name: PropTypes.string,
    club: PropTypes.shape({ long_name: PropTypes.string })
  }),
  onClose: PropTypes.func.isRequired
};
