import { useState, useEffect } from 'react';
import { PREFERENCE_KEYS, DEFAULT_PREFERENCES } from '../types/preferences';

/**
 * Hook to load the useMatchWeights team preference.
 *
 * @param {Object} options
 * @param {string|null} options.teamId - Current team ID
 * @param {Function} options.loadTeamPreferences - Function to load team preferences
 * @param {Object} [options.prefResult] - Already-loaded preferences object (skips fetching)
 * @returns {boolean} Whether match weights are enabled
 */
export function useMatchWeightsPreference({ teamId, loadTeamPreferences, prefResult }) {
  const [useMatchWeights, setUseMatchWeights] = useState(
    DEFAULT_PREFERENCES[PREFERENCE_KEYS.USE_MATCH_WEIGHTS]
  );

  useEffect(() => {
    // loadTeamPreferences already parses values, so read directly without re-parsing.
    if (prefResult !== undefined && prefResult !== null) {
      const raw = prefResult?.[PREFERENCE_KEYS.USE_MATCH_WEIGHTS];
      setUseMatchWeights(
        raw === undefined ? DEFAULT_PREFERENCES[PREFERENCE_KEYS.USE_MATCH_WEIGHTS] : raw
      );
      return;
    }

    async function fetchPreferences() {
      if (!teamId || !loadTeamPreferences) return;
      try {
        const prefs = await loadTeamPreferences(teamId);
        const raw = prefs?.[PREFERENCE_KEYS.USE_MATCH_WEIGHTS];
        setUseMatchWeights(
          raw === undefined ? DEFAULT_PREFERENCES[PREFERENCE_KEYS.USE_MATCH_WEIGHTS] : raw
        );
      } catch (err) {
        console.warn('[useMatchWeightsPreference] Failed to load preferences, using default', err);
      }
    }
    fetchPreferences();
  }, [teamId, loadTeamPreferences, prefResult]);

  return useMatchWeights;
}
