import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { autoSaveMatchPlan, getPlanFingerprintsForMatches } from '../services/matchStateManager';
import { rebaseSquadSelection } from '../utils/planRebase';
import { PENDING_MATCH_STATE, PLANNED_MATCH_STATE } from '../constants/planMatchesConstants';

const DEBOUNCE_MS = 750;

export const AUTO_SAVE_STATUS = {
  IDLE: 'idle',
  PENDING: 'pending',
  SAVING: 'saving',
  ERROR: 'error',
  OFFLINE: 'offline'
};

function isBrowserOnline() {
  if (typeof navigator === 'undefined') return true;
  if (typeof navigator.onLine !== 'boolean') return true;
  return navigator.onLine;
}

function normalizeArray(ids) {
  return Array.isArray(ids) ? ids.map((id) => String(id)) : [];
}

function idsEqual(a, b) {
  const la = normalizeArray(a);
  const lb = normalizeArray(b);
  if (la.length !== lb.length) return false;
  for (let i = 0; i < la.length; i += 1) {
    if (la[i] !== lb[i]) return false;
  }
  return true;
}

/**
 * useAutoSavePlan
 *
 * Owns the PlanMatchesScreen auto-save lifecycle:
 *   - Debounces per-match edits to `match.initial_config.squadSelection`,
 *     `match.difficulty`, `match.type`, `match.venue_type`, and `match.format`.
 *   - Applies OCC via `plan_version` and three-way-rebases on conflict.
 *   - Tracks per-match status for UI (idle/pending/saving/error/offline).
 *   - Flushes outstanding saves on demand (navigation, unmount, tab hide).
 *
 * Callers pass:
 *   - `matches`: the list of matches currently rendered (only planned/pending
 *     rows are eligible).
 *   - `getSelection(matchId)`: latest selected player ids for a match.
 *   - `getDifficulty(matchId)`: latest difficulty string for a match.
 *   - `getMatchType(matchId)`: latest match-type string for a match.
 *   - `getVenueType(matchId)`: latest venue-type string for a match.
 *   - `getFormat(matchId)`: latest format string for a match.
 *   - `getFormation(matchId)`: latest formation paired with a format change
 *     (only meaningful when `format` differs from baseline).
 *   - `onRemoteUpdate({ matchId, selection, difficulty, matchType, venueType,
 *     format, lastUpdatedBy })`: called when a realtime event (or conflict
 *     rebase) updates the local view; callers must merge the new state into
 *     their own stores.
 *   - `currentUserId`: used to drop our own realtime echoes.
 *   - `enabled`: gates the whole hook — when false (e.g. read-only user), no
 *     saves or fetches occur.
 */
export function useAutoSavePlan({
  matches,
  getSelection,
  getDifficulty,
  getMatchType,
  getVenueType,
  getFormat,
  getFormation,
  onRemoteUpdate,
  currentUserId = null,
  enabled = true
} = {}) {
  const [statusByMatch, setStatusByMatch] = useState({});

  const getSelectionRef = useRef(getSelection);
  getSelectionRef.current = getSelection;
  const getDifficultyRef = useRef(getDifficulty);
  getDifficultyRef.current = getDifficulty;
  const getMatchTypeRef = useRef(getMatchType);
  getMatchTypeRef.current = getMatchType;
  const getVenueTypeRef = useRef(getVenueType);
  getVenueTypeRef.current = getVenueType;
  const getFormatRef = useRef(getFormat);
  getFormatRef.current = getFormat;
  const getFormationRef = useRef(getFormation);
  getFormationRef.current = getFormation;
  const onRemoteUpdateRef = useRef(onRemoteUpdate);
  onRemoteUpdateRef.current = onRemoteUpdate;
  const currentUserIdRef = useRef(currentUserId);
  currentUserIdRef.current = currentUserId;
  const enabledRef = useRef(enabled);
  enabledRef.current = enabled;

  // Per-match bookkeeping (not React state — mutating these should not trigger renders).
  const trackerRef = useRef(new Map());
  const debounceTimersRef = useRef(new Map());
  const isMountedRef = useRef(true);

  const getTracker = useCallback((matchId) => {
    const key = String(matchId);
    let entry = trackerRef.current.get(key);
    if (!entry) {
      entry = {
        matchId: key,
        planVersion: null,
        baselineSelection: [],
        baselineDifficulty: null,
        baselineMatchType: null,
        baselineVenueType: null,
        baselineFormat: null,
        baselineFormation: null,
        inflight: null,
        needsFlush: false
      };
      trackerRef.current.set(key, entry);
    }
    return entry;
  }, []);

  const patchStatus = useCallback((matchId, updates) => {
    if (!isMountedRef.current) return;
    const key = String(matchId);
    setStatusByMatch((prev) => {
      const current = prev[key] || {};
      const next = { ...current, ...updates };
      // Shallow change detection to avoid re-renders on no-op updates.
      const changed = Object.keys(next).some((field) => current[field] !== next[field]);
      if (!changed) return prev;
      return { ...prev, [key]: next };
    });
  }, []);

  const eligibleMatchIds = useMemo(() => {
    return (matches || [])
      .filter((match) => match?.id)
      .filter((match) => match.state === PLANNED_MATCH_STATE || match.state === PENDING_MATCH_STATE)
      .map((match) => String(match.id));
  }, [matches]);

  // Seed plan fingerprints (plan_version, baseline selection) on mount and whenever
  // new planned/pending matches enter the list.
  useEffect(() => {
    if (!enabled) return undefined;
    if (eligibleMatchIds.length === 0) return undefined;

    const idsToFetch = eligibleMatchIds.filter((id) => {
      const tracker = trackerRef.current.get(id);
      return !tracker || tracker.planVersion == null;
    });
    if (idsToFetch.length === 0) return undefined;

    let cancelled = false;
    getPlanFingerprintsForMatches(idsToFetch).then((result) => {
      if (cancelled || !isMountedRef.current) return;
      if (!result?.success) return;
      const fingerprints = result.fingerprints || {};
      Object.entries(fingerprints).forEach(([matchId, info]) => {
        const tracker = getTracker(matchId);
        tracker.planVersion = info.planVersion;
        tracker.baselineSelection = normalizeArray(info.selection);
        tracker.baselineDifficulty = info.difficulty || null;
        tracker.baselineMatchType = info.matchType || null;
        tracker.baselineVenueType = info.venueType || null;
        tracker.baselineFormat = info.format || null;
        tracker.baselineFormation = info.formation || null;
        patchStatus(matchId, {
          status: AUTO_SAVE_STATUS.IDLE,
          lastSyncedAt: info.updatedAt || null,
          lastUpdatedBy: info.lastUpdatedBy || null,
          error: null
        });
      });
    });

    return () => { cancelled = true; };
  }, [enabled, eligibleMatchIds, getTracker, patchStatus]);

  const clearTimer = useCallback((matchId) => {
    const key = String(matchId);
    const timer = debounceTimersRef.current.get(key);
    if (timer) {
      clearTimeout(timer);
      debounceTimersRef.current.delete(key);
    }
  }, []);

  const flushMatch = useCallback(async (matchId) => {
    if (!enabledRef.current) return { skipped: true };
    const key = String(matchId);
    const tracker = getTracker(key);

    clearTimer(key);

    // Serialize per-match: if a save is inflight, chain this flush behind it.
    if (tracker.inflight) {
      tracker.needsFlush = true;
      try { await tracker.inflight; } catch (_e) { /* swallow; handled below */ }
      if (!tracker.needsFlush) return { skipped: true };
    }

    const runFlush = async () => {
      tracker.needsFlush = false;

      const currentSelection = normalizeArray(getSelectionRef.current?.(key));
      const currentDifficulty = getDifficultyRef.current?.(key) || null;
      const currentMatchType = getMatchTypeRef.current?.(key) || null;
      const currentVenueType = getVenueTypeRef.current?.(key) || null;
      const currentFormat = getFormatRef.current?.(key) || null;
      const currentFormation = getFormationRef.current?.(key) || null;

      const baselineSelection = tracker.baselineSelection;
      const baselineDifficulty = tracker.baselineDifficulty;
      const baselineMatchType = tracker.baselineMatchType;
      const baselineVenueType = tracker.baselineVenueType;
      const baselineFormat = tracker.baselineFormat;

      const selectionUnchanged = idsEqual(currentSelection, baselineSelection);
      const difficultyUnchanged = (currentDifficulty || null) === (baselineDifficulty || null);
      const matchTypeUnchanged = (currentMatchType || null) === (baselineMatchType || null);
      const venueTypeUnchanged = (currentVenueType || null) === (baselineVenueType || null);
      const formatUnchanged = (currentFormat || null) === (baselineFormat || null);
      if (selectionUnchanged && difficultyUnchanged && matchTypeUnchanged && venueTypeUnchanged && formatUnchanged) {
        patchStatus(key, { status: AUTO_SAVE_STATUS.IDLE, error: null });
        return { skipped: true };
      }

      if (!isBrowserOnline()) {
        patchStatus(key, { status: AUTO_SAVE_STATUS.OFFLINE, error: null });
        tracker.needsFlush = true;
        return { skipped: true, offline: true };
      }

      patchStatus(key, { status: AUTO_SAVE_STATUS.SAVING, error: null });

      const attemptSave = async (
        { selection, difficulty, matchType, venueType, format, formation, baselineSel, baselineDiff, baselineMt, baselineVt, baselineFmt },
        attempt = 0
      ) => {
        const formatChanged = format && format !== baselineFmt;
        const result = await autoSaveMatchPlan({
          matchId: key,
          selectedSquadIds: selection,
          difficulty: difficulty || undefined,
          matchType: matchType || undefined,
          venueType: venueType || undefined,
          format: format || undefined,
          // Only carry formation when the format itself is changing — otherwise
          // we might overwrite a coach's hand-tuned formation in initial_config
          // with a stale value from team preferences.
          formation: formatChanged && formation ? formation : undefined,
          expectedPlanVersion: tracker.planVersion
        });

        if (result.success) {
          tracker.planVersion = result.newPlanVersion ?? tracker.planVersion;
          tracker.baselineSelection = normalizeArray(result.initialConfig?.squadSelection);
          tracker.baselineDifficulty = result.difficulty || difficulty || null;
          tracker.baselineMatchType = result.matchType || matchType || null;
          tracker.baselineVenueType = result.venueType || venueType || null;
          tracker.baselineFormat = result.format || format || null;
          // Only the format-change branch sends formation, so prefer the
          // server's echoed value but fall back to what we sent. Outside that
          // branch, formation is whatever the column already held.
          tracker.baselineFormation = result.formation || formation || tracker.baselineFormation;
          patchStatus(key, {
            status: AUTO_SAVE_STATUS.IDLE,
            lastSyncedAt: result.updatedAt || new Date().toISOString(),
            lastUpdatedBy: result.lastUpdatedBy || currentUserIdRef.current || null,
            error: null
          });
          return { ok: true };
        }

        if (result.conflict && result.serverState) {
          const { merged, additions, removals } = rebaseSquadSelection({
            baseline: baselineSel,
            local: selection,
            server: result.serverState.selection
          });

          // Update OCC token and baseline to the latest server state.
          tracker.planVersion = result.serverState.planVersion;
          tracker.baselineSelection = normalizeArray(result.serverState.selection);
          tracker.baselineDifficulty = result.serverState.difficulty || null;
          tracker.baselineMatchType = result.serverState.matchType || null;
          tracker.baselineVenueType = result.serverState.venueType || null;
          tracker.baselineFormat = result.serverState.format || null;
          tracker.baselineFormation = result.serverState.formation || null;

          // Last-write-wins per scalar field.
          const mergedDifficulty = (difficulty && difficulty !== baselineDiff)
            ? difficulty
            : result.serverState.difficulty || null;
          const mergedMatchType = (matchType && matchType !== baselineMt)
            ? matchType
            : result.serverState.matchType || null;
          const mergedVenueType = (venueType && venueType !== baselineVt)
            ? venueType
            : result.serverState.venueType || null;
          const mergedFormat = (format && format !== baselineFmt)
            ? format
            : result.serverState.format || null;
          const mergedFormation = formatChanged ? formation : null;

          // Let callers update their in-memory state. `mergedFormation` is
          // only meaningful when our local format change won the rebase
          // (otherwise it's null); either way callers should treat it as the
          // authoritative pairing for `mergedFormat` so a stale local
          // formationByMatch entry can't leak into a subsequent save.
          if (typeof onRemoteUpdateRef.current === 'function') {
            onRemoteUpdateRef.current({
              matchId: key,
              selection: merged,
              difficulty: mergedDifficulty,
              matchType: mergedMatchType,
              venueType: mergedVenueType,
              format: mergedFormat,
              formation: mergedFormation,
              lastUpdatedBy: result.serverState.lastUpdatedBy || null,
              source: 'rebase'
            });
          }

          const serverSel = normalizeArray(result.serverState.selection);
          const mergedMatchesServer = additions.length === 0
            && removals.length === 0
            && idsEqual(merged, serverSel)
            && (mergedDifficulty || null) === (result.serverState.difficulty || null)
            && (mergedMatchType || null) === (result.serverState.matchType || null)
            && (mergedVenueType || null) === (result.serverState.venueType || null)
            && (mergedFormat || null) === (result.serverState.format || null);

          if (mergedMatchesServer) {
            patchStatus(key, {
              status: AUTO_SAVE_STATUS.IDLE,
              lastSyncedAt: result.serverState.updatedAt || null,
              lastUpdatedBy: result.serverState.lastUpdatedBy || null,
              error: null
            });
            return { ok: true };
          }

          // Guard against unbounded recursion when multiple clients keep
          // bumping plan_version between our retries. Surface an error after
          // the first merged retry still conflicts; the caller can flush again.
          if (attempt >= 1) {
            patchStatus(key, {
              status: AUTO_SAVE_STATUS.ERROR,
              error: 'Concurrent edit — please retry'
            });
            tracker.needsFlush = true;
            return { ok: false, error: 'Concurrent edit — please retry' };
          }

          // Retry once with merged state.
          return attemptSave({
            selection: merged,
            difficulty: mergedDifficulty,
            matchType: mergedMatchType,
            venueType: mergedVenueType,
            format: mergedFormat,
            formation: mergedFormation,
            baselineSel: tracker.baselineSelection,
            baselineDiff: tracker.baselineDifficulty,
            baselineMt: tracker.baselineMatchType,
            baselineVt: tracker.baselineVenueType,
            baselineFmt: tracker.baselineFormat
          }, attempt + 1);
        }

        patchStatus(key, {
          status: AUTO_SAVE_STATUS.ERROR,
          error: result.error || 'Save failed'
        });
        tracker.needsFlush = true;
        return { ok: false, error: result.error };
      };

      const outcome = await attemptSave({
        selection: currentSelection,
        difficulty: currentDifficulty,
        matchType: currentMatchType,
        venueType: currentVenueType,
        format: currentFormat,
        formation: currentFormation,
        baselineSel: baselineSelection,
        baselineDiff: baselineDifficulty,
        baselineMt: baselineMatchType,
        baselineVt: baselineVenueType,
        baselineFmt: baselineFormat
      });

      return outcome;
    };

    const promise = runFlush();
    tracker.inflight = promise;
    try {
      return await promise;
    } finally {
      if (tracker.inflight === promise) {
        tracker.inflight = null;
      }
    }
  }, [clearTimer, getTracker, patchStatus]);

  const scheduleSave = useCallback((matchId) => {
    if (!enabledRef.current) return;
    const key = String(matchId);
    const tracker = getTracker(key);
    tracker.needsFlush = true;

    patchStatus(key, { status: AUTO_SAVE_STATUS.PENDING, error: null });

    clearTimer(key);
    const timeout = setTimeout(() => {
      debounceTimersRef.current.delete(key);
      flushMatch(key);
    }, DEBOUNCE_MS);
    debounceTimersRef.current.set(key, timeout);
  }, [clearTimer, flushMatch, getTracker, patchStatus]);

  const flushAllPendingSaves = useCallback(async () => {
    if (!enabledRef.current) return;
    const keys = Array.from(new Set([
      ...debounceTimersRef.current.keys(),
      ...Array.from(trackerRef.current.values())
        .filter((t) => t.needsFlush)
        .map((t) => t.matchId)
    ]));
    await Promise.all(keys.map((matchId) => flushMatch(matchId)));
  }, [flushMatch]);

  const retry = useCallback((matchId) => {
    flushMatch(matchId);
  }, [flushMatch]);

  const handleRemoteUpdate = useCallback((payload) => {
    // Remote updates are forwarded even for read-only users so their view stays
    // in sync with other coaches. Only the save path is gated by `enabled`.
    if (!payload?.matchId) return;
    const key = String(payload.matchId);
    const tracker = getTracker(key);

    // Own echo: if we already saw this plan_version via our own save, ignore.
    if (
      tracker.planVersion != null
      && payload.planVersion != null
      && payload.planVersion <= tracker.planVersion
    ) {
      return;
    }

    tracker.planVersion = payload.planVersion ?? tracker.planVersion;
    const remoteSelection = normalizeArray(payload.selection);
    tracker.baselineSelection = remoteSelection;
    tracker.baselineDifficulty = payload.difficulty || null;
    tracker.baselineMatchType = payload.matchType || null;
    tracker.baselineVenueType = payload.venueType || null;
    tracker.baselineFormat = payload.format || null;
    tracker.baselineFormation = payload.formation || null;

    // If there is no local pending save, surface the remote state directly.
    const hasPending = debounceTimersRef.current.has(key)
      || tracker.needsFlush
      || tracker.inflight;

    if (!hasPending) {
      if (typeof onRemoteUpdateRef.current === 'function') {
        onRemoteUpdateRef.current({
          matchId: key,
          selection: remoteSelection,
          difficulty: payload.difficulty || null,
          matchType: payload.matchType || null,
          venueType: payload.venueType || null,
          format: payload.format || null,
          formation: payload.formation || null,
          lastUpdatedBy: payload.lastUpdatedBy || null,
          source: 'remote'
        });
      }
    }

    patchStatus(key, {
      lastSyncedAt: payload.updatedAt || null,
      lastUpdatedBy: payload.lastUpdatedBy || null,
      remoteEditor: payload.lastUpdatedBy && payload.lastUpdatedBy !== currentUserIdRef.current
        ? payload.lastUpdatedBy
        : null
    });
  }, [getTracker, patchStatus]);

  // Component lifecycle: unmount + tab visibility + online/offline.
  useEffect(() => {
    isMountedRef.current = true;
    const debounceTimers = debounceTimersRef.current;
    const flushDueToPageHide = () => {
      if (typeof document !== 'undefined' && document.visibilityState === 'hidden') {
        flushAllPendingSaves();
      }
    };
    const handleOnline = () => {
      // Trigger a flush for anything that was parked in OFFLINE state.
      trackerRef.current.forEach((tracker) => {
        if (tracker.needsFlush) {
          flushMatch(tracker.matchId);
        }
      });
    };

    if (typeof document !== 'undefined') {
      document.addEventListener('visibilitychange', flushDueToPageHide);
    }
    if (typeof window !== 'undefined') {
      window.addEventListener('online', handleOnline);
    }

    return () => {
      isMountedRef.current = false;
      if (typeof document !== 'undefined') {
        document.removeEventListener('visibilitychange', flushDueToPageHide);
      }
      if (typeof window !== 'undefined') {
        window.removeEventListener('online', handleOnline);
      }
      // Best-effort final flush on unmount.
      flushAllPendingSaves();
      debounceTimers.forEach((timer) => clearTimeout(timer));
      debounceTimers.clear();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return {
    statusByMatch,
    scheduleSave,
    flushAllPendingSaves,
    retry,
    handleRemoteUpdate
  };
}
