import { VIEWS } from '../constants/viewConstants';
import {
  STATS_TABS,
  getStatisticsPath,
  isStatisticsPath,
  isValidStatisticsTab
} from '../constants/statisticsTabs';
import { createPersistenceManager } from '../utils/persistenceManager';
import { STORAGE_KEYS } from '../constants/storageKeys';
import { createManagedViewRoutingHook } from './createPathRoutingHook';

const tabPersistence = createPersistenceManager(
  STORAGE_KEYS.STATISTICS_ACTIVE_TAB,
  { tab: STATS_TABS.TEAM }
);

const getPersistedStatisticsPath = () => {
  const stored = tabPersistence.loadState();
  const tab = stored?.tab;
  return getStatisticsPath(isValidStatisticsTab(tab) ? tab : STATS_TABS.TEAM);
};

export const useStatisticsRouting = createManagedViewRoutingHook({
  navigateTarget: VIEWS.STATISTICS,
  ownsPath: isStatisticsPath,
  getViewPath: getPersistedStatisticsPath
});
