/**
 * Tracks whether a password-recovery (forgot-password OTP) flow is mid-flight.
 *
 * Verifying a recovery OTP signs the user in, which would otherwise trip the
 * deep-link auth gate into closing the auth modal and navigating away — before
 * the user can set a new password. This flag lets the gate tell a recovery
 * sign-in apart from a normal one. Stored in sessionStorage to mirror the
 * intended-path mechanism it guards against.
 *
 * An in-memory fallback covers environments where sessionStorage is blocked
 * (Safari ITP strict mode, some WebViews, private modes). Without it, a failed
 * write would silently re-introduce the modal-closing bug. The fallback is
 * per-tab and only spans the synchronous sign-in → gate chain, so there's no
 * cross-tab leakage risk.
 */

const STORAGE_KEY = 'password_recovery_in_progress';

let memoryFallback = false;

export const setPasswordRecoveryInProgress = () => {
  memoryFallback = true;
  try {
    sessionStorage.setItem(STORAGE_KEY, 'true');
  } catch {
    // sessionStorage unavailable — rely on memoryFallback
  }
};

export const clearPasswordRecoveryInProgress = () => {
  memoryFallback = false;
  try {
    sessionStorage.removeItem(STORAGE_KEY);
  } catch {
    // ignore
  }
};

export const isPasswordRecoveryInProgress = () => {
  try {
    return sessionStorage.getItem(STORAGE_KEY) === 'true' || memoryFallback;
  } catch {
    return memoryFallback;
  }
};
