import { useCallback, useEffect, useRef, useState } from 'react';
import {
  CONSENT_CHANGE_EVENT,
  CONSENT_STATUS,
  clearConsent,
  loadConsent,
  saveConsent,
} from '../utils/consentPersistence';
import { STORAGE_KEYS } from '../constants/storageKeys';

function callGtag(...args) {
  if (typeof window !== 'undefined' && typeof window.gtag === 'function') {
    window.gtag(...args);
  }
}

function applyGranted() {
  callGtag('consent', 'update', {
    ad_storage: 'denied',
    ad_user_data: 'denied',
    ad_personalization: 'denied',
    analytics_storage: 'granted',
  });
}

function applyDenied() {
  callGtag('consent', 'update', {
    ad_storage: 'denied',
    ad_user_data: 'denied',
    ad_personalization: 'denied',
    analytics_storage: 'denied',
  });
  callGtag('set', 'url_passthrough', true);
}

export function useCookieConsent() {
  const [state, setState] = useState(() => loadConsent());
  const lastAppliedStatusRef = useRef(null);

  useEffect(() => {
    if (lastAppliedStatusRef.current === state.status) return;
    if (state.status === CONSENT_STATUS.GRANTED) {
      applyGranted();
      lastAppliedStatusRef.current = state.status;
    } else if (state.status === CONSENT_STATUS.DENIED) {
      applyDenied();
      lastAppliedStatusRef.current = state.status;
    }
  }, [state.status]);

  useEffect(() => {
    if (typeof window === 'undefined') return undefined;
    const syncFromStorage = () => {
      const next = loadConsent();
      setState((prev) => (prev.status === next.status && prev.decidedAt === next.decidedAt ? prev : next));
    };
    const handleStorage = (event) => {
      if (event.key !== STORAGE_KEYS.COOKIE_CONSENT) return;
      syncFromStorage();
    };
    window.addEventListener('storage', handleStorage);
    window.addEventListener(CONSENT_CHANGE_EVENT, syncFromStorage);
    return () => {
      window.removeEventListener('storage', handleStorage);
      window.removeEventListener(CONSENT_CHANGE_EVENT, syncFromStorage);
    };
  }, []);

  const accept = useCallback(() => {
    applyGranted();
    saveConsent(CONSENT_STATUS.GRANTED);
    lastAppliedStatusRef.current = CONSENT_STATUS.GRANTED;
    setState(loadConsent());
  }, []);

  const reject = useCallback(() => {
    applyDenied();
    saveConsent(CONSENT_STATUS.DENIED);
    lastAppliedStatusRef.current = CONSENT_STATUS.DENIED;
    setState(loadConsent());
  }, []);

  const reset = useCallback(() => {
    applyDenied();
    clearConsent();
    lastAppliedStatusRef.current = null;
    setState(loadConsent());
  }, []);

  return {
    status: state.status,
    decidedAt: state.decidedAt,
    accept,
    reject,
    reset,
  };
}
