import { Capacitor } from '@capacitor/core';

/**
 * Returns true when the app is running inside a Capacitor native shell (iOS / Android).
 *
 * UI gating rule (#401): Any UI showing pricing, upgrade buttons, links to web
 * purchase flows, or pricing copy MUST be hidden when this returns true. This
 * includes QR codes and "subscribe at our website" text. Apple Guideline 3.1.1 /
 * 3.1.3 — store rejection risk. Enforced in CI by scripts/check-no-pricing.sh.
 * See docs/native-policy.md.
 */
export function isNativePlatform() {
  return Capacitor.isNativePlatform();
}

// True when launched as an installed PWA (home-screen / standalone window),
// as opposed to a regular browser tab. Covers the standard `display-mode`
// media query plus iOS Safari's non-standard `navigator.standalone`.
export function isStandaloneDisplayMode() {
  if (typeof window === 'undefined') return false;
  // Only 'standalone' signals a true home-screen install; 'fullscreen' and
  // 'minimal-ui' manifest modes are intentionally excluded.
  if (typeof window.matchMedia === 'function'
      && window.matchMedia('(display-mode: standalone)').matches) {
    return true;
  }
  return window.navigator.standalone === true;
}

// Apple Sign-In is required on iOS (Guideline 4.8) and useful on the web.
// Android has no first-party Apple SDK and Google remains the only social option there.
export function shouldOfferAppleSignIn() {
  if (!Capacitor.isNativePlatform()) return true;
  return Capacitor.getPlatform() === 'ios';
}
