import React, { createContext, useContext, useEffect, useState, useCallback, useRef } from 'react';
import { useTranslation } from 'react-i18next';
import { supabase } from '../lib/supabase';
import { getCachedUserProfile, cacheUserProfile, clearAllCache, cacheAuthUser, getCachedAuthUserAnyAge, getCachedUserProfileAnyAge } from '../utils/cacheUtils';
import { cleanupAbandonedMatches } from '../services/matchCleanupService';
import { cleanupPreviousSession } from '../utils/sessionCleanupUtils';
import { detectSessionType, shouldCleanupSession, clearAllSessionData, markPendingSignIn, clearPendingSignIn, markSignOutGuard, DETECTION_TYPES } from '../services/sessionDetectionService';
import { setOtpSentTime, clearOtpSentTime } from '../utils/timeUtils';
import { isNativePlatform } from '../utils/platform';
import { Browser } from '@capacitor/browser';
import { Capacitor } from '@capacitor/core';
import { SignInWithApple } from '@capacitor-community/apple-sign-in';

const NATIVE_OAUTH_CALLBACK_URL = 'sportwizard://auth/callback';
const NATIVE_RESET_PASSWORD_URL = 'sportwizard://auth/reset-password';

function generateAppleNonce() {
  const bytes = new Uint8Array(16);
  window.crypto.getRandomValues(bytes);
  return Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
}

async function sha256Hex(value) {
  const data = new TextEncoder().encode(value);
  const buffer = await window.crypto.subtle.digest('SHA-256', data);
  return Array.from(new Uint8Array(buffer), (b) => b.toString(16).padStart(2, '0')).join('');
}

// Feature flag to control session expiry warnings
const ENABLE_SESSION_EXPIRY_WARNINGS = false;

const AuthContext = createContext({
  // Core state
  user: null,
  userProfile: null,
  loading: true,
  authError: null,
  sessionExpiry: null,
  
  // Session detection
  sessionDetectionResult: null,
  
  // Computed properties
  isAuthenticated: false,
  isEmailConfirmed: false,
  hasValidProfile: false,
  profileName: '',
  needsProfileCompletion: false,
  
  // Session management
  showSessionWarning: false,
  extendSession: async () => {},
  dismissSessionWarning: () => {},
  clearAuthError: () => {},
  markProfileCompleted: () => {},
  
  // Auth functions
  signUp: async () => {},
  signIn: async () => {},
  signInWithGoogle: async () => {},
  signInWithApple: async () => {},
  signOut: async () => {},
  verifyOtp: async () => {},
  resendOtp: async () => {},
  resetPassword: async () => {},
  updatePassword: async () => {},
  updateProfile: async () => {},
  deleteAccount: async () => {},
});


export function AuthProvider({ children }) {
  const { t } = useTranslation(['auth', 'profile']);
  const [user, setUser] = useState(null);
  const [userProfile, setUserProfile] = useState(null);
  const [loading, setLoading] = useState(true);
  const [authError, setAuthError] = useState(null);
  const [sessionExpiry, setSessionExpiry] = useState(null);
  const [showSessionWarning, setShowSessionWarning] = useState(false);
  const [needsProfileCompletion, setNeedsProfileCompletion] = useState(false);
  const [skipProfileFetch, setSkipProfileFetch] = useState(false);
  const [sessionDetectionResult, setSessionDetectionResult] = useState(null);

  // Clear any auth errors when user changes
  useEffect(() => {
    if (authError) {
      setAuthError(null);
    }
  }, [user, authError]);

  // Simple profile fetch function with timeout
  const fetchUserProfile = useCallback(async (userId, session = null, detectionResult = null) => {
    try {

      // Check cache first if session detection indicates page refresh
      if (detectionResult?.type === DETECTION_TYPES.PAGE_REFRESH) {
        const cachedProfile = getCachedUserProfile();
        if (cachedProfile && cachedProfile.id === userId) {
          setUserProfile(cachedProfile);
          const needsCompletion = !cachedProfile.name || cachedProfile.name.trim().length === 0;
          setNeedsProfileCompletion(needsCompletion);
          
          // Return cached data immediately, skip database query
          return cachedProfile;
        }
      }
      
      // Use provided session data to avoid auth deadlock
      if (!session) {
        // Fallback: only call auth methods if no session provided
        const sessionCheck = await supabase.auth.getSession();
        session = sessionCheck.data?.session;
      }

      
      // Create the database query
      const queryPromise = supabase
        .from('user_profile')
        .select('*')
        .eq('id', userId)
        .single();
      
      // Timeout guards against a stalled Supabase client; with the in-memory
      // auth lock and visibility-refresh in place, the query should complete in
      // <1s, so 8s is plenty while still bounding the worst-case UI stall.
      const timeoutPromise = new Promise((_, reject) =>
        setTimeout(() => reject(new Error('Profile fetch timeout')), 8000)
      );

      const { data, error } = await Promise.race([queryPromise, timeoutPromise]);

      if (error) {
        if (error.code === 'PGRST116') {
          // No profile found - treat as incomplete but do not crash
          setUserProfile(null);
          setNeedsProfileCompletion(true);
          return null;
        }
        throw error;
      }
      
      setUserProfile(data);
      
      // Cache the successful result
      cacheUserProfile(data);
      
      // Check if profile needs completion
      const needsCompletion = !data || !data.name || data.name.trim().length === 0;
      setNeedsProfileCompletion(needsCompletion);
      
      return data;
      
    } catch (error) {
      console.error('Error fetching profile:', error.message);
      setUserProfile(null);
      // Do not force profile completion prompt on transient fetch failures
      return null;
    }
  }, []);

  // Session management functions
  const extendSession = useCallback(async () => {
    try {
      const { data: { session }, error } = await supabase.auth.refreshSession();
      if (error) throw error;
      
      if (session) {
        const expiryTime = new Date(session.expires_at * 1000);
        setSessionExpiry(expiryTime);
        setShowSessionWarning(false);
      }
      return { success: true };
    } catch (error) {
      return { success: false, error: error.message };
    }
  }, []);

  const dismissSessionWarning = useCallback(() => {
    setShowSessionWarning(false);
  }, []);

  const clearAuthError = useCallback(() => {
    setAuthError(null);
  }, []);

  // Mark profile as completed
  const markProfileCompleted = useCallback(() => {
    setNeedsProfileCompletion(false);
  }, []);

  // Session expiry monitoring
  const setupSessionMonitoring = useCallback((session) => {
    if (!session) {
      setSessionExpiry(null);
      setShowSessionWarning(false);
      return;
    }

    const expiryTime = new Date(session.expires_at * 1000);
    setSessionExpiry(expiryTime);
    
    
    // Warn user 5 minutes before expiry (disabled via feature flag)
    if (ENABLE_SESSION_EXPIRY_WARNINGS) {
      const warningTime = expiryTime.getTime() - Date.now() - (5 * 60 * 1000);
      if (warningTime > 0) {
        setTimeout(() => {
          setShowSessionWarning(true);
        }, warningTime);
      }
    }
  }, []);

  const initialDetectionRef = useRef(null);
  const hasCachedProfileRef = useRef(false);
  // Track if we've already processed initial session to prevent duplicates
  const initializedRef = useRef(false);
  const currentFetchRef = useRef(null);
  const currentUserIdRef = useRef(null);
  // Mirror sessionExpiry into a ref so the visibilitychange listener can read
  // the latest value without re-registering on every token refresh.
  const sessionExpiryRef = useRef(null);
  useEffect(() => {
    sessionExpiryRef.current = sessionExpiry;
  }, [sessionExpiry]);

  // Early detection to hydrate state from cache before Supabase finishes recovery.
  // We intentionally read cache ignoring TTL here — a stale user/profile is strictly
  // better than a blue loading screen while the Supabase refresh is in flight. The
  // subsequent INITIAL_SESSION / TOKEN_REFRESHED events overwrite with fresh data.
  useEffect(() => {
    const detection = detectSessionType();
    initialDetectionRef.current = detection;
    setSessionDetectionResult(detection);
    if (process.env.NODE_ENV === 'development') {
      console.log(`[session-detection] consumed (app mount) -> ${detection.type}`);
    }

    if (detection.type === DETECTION_TYPES.PAGE_REFRESH) {
      const cachedUser = getCachedAuthUserAnyAge();
      const cachedProfile = getCachedUserProfileAnyAge();

      if (cachedUser) {
        setUser(cachedUser);
      }

      if (cachedProfile && (!cachedUser || cachedProfile.id === cachedUser.id)) {
        setUserProfile(cachedProfile);
        const needsCompletion = !cachedProfile?.name || cachedProfile.name.trim().length === 0;
        setNeedsProfileCompletion(needsCompletion);
        hasCachedProfileRef.current = true;
      }

      if (cachedUser || cachedProfile) {
        setLoading(false);
      }
    }
  }, []);


  // Main auth state change handler
  useEffect(() => {
    // Listen for auth changes - this will handle initial session too
    const { data: { subscription } } = supabase.auth.onAuthStateChange(
      async (event, session) => {

        // Handle sign out
        if (event === 'SIGNED_OUT' || !session?.user) {
          setUser(null);
          setUserProfile(null);
          setSessionExpiry(null);
          setNeedsProfileCompletion(false);
          setLoading(false);
          initializedRef.current = false;
          currentUserIdRef.current = null;
          return;
        }

        // Token refresh: just update session info, no need to re-fetch profile.
        // This is the common case when returning to the app after a period of inactivity
        // where the access token (1hr JWT) has expired and was automatically refreshed.
        // Skipping the profile re-fetch avoids an unnecessary DB round-trip that would
        // otherwise add ~1-3 seconds on top of the token refresh latency.
        if (event === 'TOKEN_REFRESHED' && initializedRef.current && session?.user) {
          if (currentUserIdRef.current === session.user.id) {
            setUser(session.user);
            cacheAuthUser(session.user);
            setupSessionMonitoring(session);
            return;
          }
        }

        // For any session events with a user, check if we've already initialized to prevent duplicates
        if ((event === 'SIGNED_IN' || event === 'INITIAL_SESSION') && initializedRef.current && session?.user) {
          // Extra check: are we processing the same user?
          if (currentUserIdRef.current === session.user.id) {
            return;
          }
        }

        // Process the session
        if (session?.user) {
          const userId = session.user.id;
          
          // Check if we're already processing this user
          if (currentUserIdRef.current === userId && currentFetchRef.current) {
            return;
          }
          
          setUser(session.user);
          cacheAuthUser(session.user);
          setupSessionMonitoring(session);
          currentUserIdRef.current = userId;
          
          // Use advanced session detection to determine cleanup strategy
          const reusedInitialDetection = !!initialDetectionRef.current;
          const detectionResult = initialDetectionRef.current || detectSessionType();
          initialDetectionRef.current = detectionResult;
          if (process.env.NODE_ENV === 'development') {
            console.log(
              `[session-detection] consumed (auth event: ${event}) -> ${detectionResult.type}` +
              `${reusedInitialDetection ? ' (reused app-mount detection — NOT re-detected)' : ''}`
            );
          }

          // Store detection result for other components to access
          setSessionDetectionResult(detectionResult);
          
          // Set session flag immediately after detection to prevent false positives on subsequent runs
          sessionStorage.setItem('auth_session_initialized', 'true');
          
          // Only clean up localStorage based on reliable detection
          if (shouldCleanupSession(detectionResult)) {
            cleanupPreviousSession();
          } else {
          }
          
          // Run match cleanup in background (fire-and-forget)
          if (detectionResult.type === DETECTION_TYPES.NEW_SIGN_IN) {
            cleanupAbandonedMatches().catch(error => {
              // Log cleanup errors but don't disrupt login flow
              if (process.env.NODE_ENV === 'development') {
                console.warn('⚠️ Match cleanup failed during login:', error.message);
              }
            });
          }
          
          // Cancel any existing profile fetch for different user
          if (currentFetchRef.current) {
          }
          
          // Skip profile fetch during invitation password setup to prevent delays
          if (skipProfileFetch) {
            initializedRef.current = true;
            setLoading(false);
          } else {
            const isPageRefresh = detectionResult.type === DETECTION_TYPES.PAGE_REFRESH;
            const skipImmediateFetch = isPageRefresh && hasCachedProfileRef.current;

            // Fetch profile with proper tracking and detection result when needed
            if (!skipImmediateFetch) {
              const fetchPromise = fetchUserProfile(userId, session, detectionResult);
              currentFetchRef.current = fetchPromise;

              if (isPageRefresh) {
                fetchPromise.finally(() => {
                  if (currentFetchRef.current === fetchPromise) {
                    currentFetchRef.current = null;
                  }
                });
                initializedRef.current = true;
                setLoading(false);
              } else {
                try {
                  await fetchPromise;
                } finally {
                  currentFetchRef.current = null;
                  initializedRef.current = true;
                  setLoading(false);
                }
              }
            } else {
              // We already hydrated from cache; mark initialization complete without hitting Supabase
              initializedRef.current = true;
              setLoading(false);
            }
          }
        }
      }
    );

    return () => {
      subscription.unsubscribe();
    };
  }, [fetchUserProfile, setupSessionMonitoring, skipProfileFetch]); // Include required dependencies

  // When the tab becomes visible after being idle, proactively refresh the session
  // if the access token is within its expiry margin. This collapses the waterfall
  // where the first data query would otherwise block behind auth-js's on-demand
  // refresh (observed as a 10-15s stall after long idle — see plan notes).
  // Reads sessionExpiry via a ref so the listener is registered once and doesn't
  // churn on every token refresh.
  useEffect(() => {
    if (typeof document === 'undefined') return undefined;

    const EXPIRY_MARGIN_MS = 90 * 1000;
    const onVisibility = () => {
      if (document.visibilityState !== 'visible') return;
      if (!initializedRef.current) return;
      const expiresAtMs = sessionExpiryRef.current?.getTime?.();
      if (!expiresAtMs) return;
      if (expiresAtMs - Date.now() > EXPIRY_MARGIN_MS) return;
      supabase.auth.refreshSession().catch((err) => {
        if (process.env.NODE_ENV === 'development') {
          console.warn('Proactive refreshSession on visibilitychange failed:', err?.message);
        }
      });
    };

    document.addEventListener('visibilitychange', onVisibility);
    return () => document.removeEventListener('visibilitychange', onVisibility);
  }, []);

  // Auth functions
  const signUp = async (email, password, name) => {
    try {
      setLoading(true);
      setAuthError(null);
      
      const signUpParams = {
        email,
        password,
        options: {
          data: { name } // Store name in user metadata
        }
      };
      
      const { data, error } = await supabase.auth.signUp(signUpParams);

      if (error) throw error;

      // No session returned means email confirmation is required. Supabase
      // also produces this shape (with data.user === null) when email-
      // enumeration-protection obfuscates an already-registered email — same
      // UX is correct in both cases: route to the verify-email screen.
      if (!data.session) {
        setOtpSentTime(email);

        return {
          user: null,
          error: null,
          message: t('signUp.checkEmailMessage')
        };
      }

      // User was created and signed in immediately
      return { user: data.user, error: null };
    } catch (error) {
      const errorMessage = error.message || t('signUp.failedToSignUp');
      setAuthError(errorMessage);
      console.error('Sign up error:', error.message);
      return { user: null, error: { message: errorMessage } };
    } finally {
      setLoading(false);
    }
  };

  const signIn = async (email, password) => {
    try {
      setLoading(true);
      setAuthError(null);

      const { data, error } = await supabase.auth.signInWithPassword({
        email,
        password
      });

      if (error) throw error;

      markPendingSignIn();
      const detection = detectSessionType();
      if (process.env.NODE_ENV === 'development') {
        console.log(`[session-detection] consumed (explicit password sign-in) -> ${detection.type}`);
      }
      setSessionDetectionResult(detection);

      return { user: data.user, error: null };
    } catch (error) {
      const errorMessage = error.message || 'Failed to sign in';
      setAuthError(errorMessage);
      return { user: null, error: { message: errorMessage } };
    } finally {
      setLoading(false);
    }
  };

  const signInWithGoogle = async (email = '') => {
    try {
      setLoading(true);
      setAuthError(null);
      markPendingSignIn();

      const native = isNativePlatform();
      const options = native
        ? { redirectTo: NATIVE_OAUTH_CALLBACK_URL, skipBrowserRedirect: true }
        : { redirectTo: `${window.location.origin}/auth/callback` };

      // Google honors login_hint as an account chooser hint.
      if (email) {
        options.queryParams = { login_hint: email };
      }

      const { data, error } = await supabase.auth.signInWithOAuth({
        provider: 'google',
        options
      });

      if (error) throw error;

      if (native && data?.url) {
        await Browser.open({ url: data.url, presentationStyle: 'popover' });
      }

      return { data, error: null };
    } catch (error) {
      clearPendingSignIn();
      const errorMessage = error.message || t('errors.googleSignInFailed');
      setAuthError(errorMessage);
      return { data: null, error: { message: errorMessage } };
    } finally {
      setLoading(false);
    }
  };

  const signInWithApple = async (email = '') => {
    try {
      setLoading(true);
      setAuthError(null);
      markPendingSignIn();

      const native = isNativePlatform();
      const platform = Capacitor.getPlatform();

      if (native && platform === 'ios') {
        const servicesId = process.env.REACT_APP_APPLE_SERVICES_ID;
        if (!servicesId) {
          // eslint-disable-next-line no-console
          console.error('Apple Sign-In: REACT_APP_APPLE_SERVICES_ID is not configured');
          throw new Error(t('errors.appleSignInNotConfigured'));
        }

        // iOS: use the native Apple Sign-In sheet, then exchange the identity token with Supabase.
        const rawNonce = generateAppleNonce();
        const hashedNonce = await sha256Hex(rawNonce);

        const result = await SignInWithApple.authorize({
          clientId: servicesId,
          redirectURI: NATIVE_OAUTH_CALLBACK_URL,
          scopes: 'email name',
          state: rawNonce,
          nonce: hashedNonce,
        });

        const identityToken = result?.response?.identityToken;
        if (!identityToken) {
          throw new Error(t('errors.appleSignInFailed'));
        }

        const { data, error } = await supabase.auth.signInWithIdToken({
          provider: 'apple',
          token: identityToken,
          nonce: rawNonce,
        });

        if (error) throw error;
        clearPendingSignIn();
        return { data, error: null };
      }

      if (native && platform === 'android') {
        // Apple Sign-In is not offered on Android (button is hidden). Defense in depth.
        throw new Error(t('errors.appleSignInUnavailableAndroid'));
      }

      // Web: standard OAuth redirect via Supabase.
      const webOptions = { redirectTo: `${window.location.origin}/auth/callback` };
      if (email) {
        // Apple ignores login_hint, but Supabase accepts the parameter.
        webOptions.queryParams = { login_hint: email };
      }
      const { data, error } = await supabase.auth.signInWithOAuth({
        provider: 'apple',
        options: webOptions,
      });

      if (error) throw error;
      return { data, error: null };
    } catch (error) {
      clearPendingSignIn();
      // Apple's native sheet surfaces user-cancellation as ASAuthorizationError 1001.
      // Match on code or the "1001" token in the NSError-style message. A bare
      // /cancel/i is too broad — Supabase or network errors could legitimately
      // contain the word "cancel" and would be incorrectly swallowed.
      const message = error?.message || '';
      const cancelled =
        error?.code === 1001 ||
        error?.code === '1001' ||
        /\b1001\b/.test(message);
      if (cancelled) {
        return { data: null, error: null };
      }
      const errorMessage = message || t('errors.appleSignInFailed');
      setAuthError(errorMessage);
      return { data: null, error: { message: errorMessage } };
    } finally {
      setLoading(false);
    }
  };

  const signOut = async () => {
    try {
      setLoading(true);
      setAuthError(null);

      const { error } = await supabase.auth.signOut();
      if (error) throw error;

      // Clear local state
      setUser(null);
      setUserProfile(null);
      setSessionExpiry(null);
      
      // Clear all cached data on sign out
      clearAllCache();
      cacheAuthUser(null);
      
      // Mark sign-out guard so detection treats follow-up refresh as PAGE_REFRESH
      markSignOutGuard();

      // Clear session detection state to ensure fresh detection on next sign-in
      clearAllSessionData();
      
      // Reset refs to prevent stale state
      initializedRef.current = false;
      currentUserIdRef.current = null;

      return { error: null };
    } catch (error) {
      const errorMessage = error.message || 'Failed to sign out';
      setAuthError(errorMessage);
      return { error: { message: errorMessage } };
    } finally {
      setLoading(false);
    }
  };

  const deleteAccount = async () => {
    try {
      setLoading(true);
      setAuthError(null);

      const { data, error } = await supabase.functions.invoke('delete-account', {
        body: {},
      });

      if (error) throw error;
      if (data?.success === false) {
        throw new Error(data?.error || 'Failed to delete account');
      }

      // Purge local session/cache the same way sign-out does. The server has
      // already invalidated the user, so signOut() may 4xx — clear regardless.
      await supabase.auth.signOut().catch(() => {});
      setUser(null);
      setUserProfile(null);
      setSessionExpiry(null);
      clearAllCache();
      cacheAuthUser(null);
      markSignOutGuard();
      clearAllSessionData();
      initializedRef.current = false;
      currentUserIdRef.current = null;

      return { error: null };
    } catch (error) {
      const errorMessage = error.message || 'Failed to delete account';
      setAuthError(errorMessage);
      return { error: { message: errorMessage } };
    } finally {
      setLoading(false);
    }
  };

  const verifyOtp = async (email, token, type = 'signup') => {
    try {
      setLoading(true);
      setAuthError(null);

      const { data, error } = await supabase.auth.verifyOtp({
        email,
        token,
        type
      });

      if (error) throw error;

      clearOtpSentTime(email); // Clear timestamp on successful verification

      return { user: data.user, error: null };
    } catch (error) {
      const errorMessage = error.message || 'Verification failed';
      setAuthError(errorMessage);
      return { user: null, error: { message: errorMessage } };
    } finally {
      setLoading(false);
    }
  };

  const resendOtp = async (email, type = 'signup') => {
    try {
      setLoading(true);
      setAuthError(null);

      const { data, error } = await supabase.auth.resend({
        type: type,
        email: email
      });

      if (error) throw error;

      // Note: Supabase resend() API does not return user object, so we fall back to client timestamp
      setOtpSentTime(email); // Uses Date.now() fallback

      return {
        data,
        error: null,
        message: 'Verification code sent! Please check your email.'
      };
    } catch (error) {
      const errorMessage = error.message || 'Failed to resend verification code';
      setAuthError(errorMessage);
      return {
        data: null,
        error: { message: errorMessage }
      };
    } finally {
      setLoading(false);
    }
  };

  const resetPassword = async (email) => {
    try {
      setLoading(true);
      setAuthError(null);

      const redirectTo = isNativePlatform()
        ? NATIVE_RESET_PASSWORD_URL
        : `${window.location.origin}/auth/reset-password`;

      const { error } = await supabase.auth.resetPasswordForEmail(email, {
        redirectTo
      });

      if (error) throw error;

      return { 
        error: null, 
        message: 'Password reset code sent to your email. Please check your inbox and enter the code to continue.'
      };
    } catch (error) {
      const errorMessage = error.message || 'Failed to send password reset email';
      setAuthError(errorMessage);
      return { error: { message: errorMessage }, message: null };
    } finally {
      setLoading(false);
    }
  };

  const updatePassword = async (newPassword) => {
    try {
      // No `if (!user)` guard here: unlike a typical password-change flow, this
      // is also the password-RESET path, where a valid recovery session exists
      // but the React `user` state can still be null. updateUser operates on the
      // session, so gating on `user` would break recovery.
      setLoading(true);
      setAuthError(null);

      const { error } = await supabase.auth.updateUser({
        password: newPassword
      });

      if (error) throw error;

      // Generic copy — callers (reset flow, change-password) own the
      // context-specific success wording.
      return {
        error: null,
        message: 'Password updated successfully.'
      };
    } catch (error) {
      const errorMessage = error.message || 'Failed to update password';
      setAuthError(errorMessage);
      return { error: { message: errorMessage }, message: null };
    } finally {
      setLoading(false);
    }
  };

  const updateProfile = async (profileData) => {
    try {
      if (!user) throw new Error('No authenticated user');
      
      setLoading(true);
      setAuthError(null);

      const { data, error } = await supabase
        .from('user_profile')
        .upsert({ 
          id: user.id, 
          ...profileData 
        })
        .select()
        .single();

      if (error) throw error;

      setUserProfile(data);
      
      // Cache the updated profile to localStorage to prevent loss on page refresh
      cacheUserProfile(data);
      
      return { profile: data, error: null };
    } catch (error) {
      const errorMessage = error.message || 'Failed to update profile';
      setAuthError(errorMessage);
      return { profile: null, error: { message: errorMessage } };
    } finally {
      setLoading(false);
    }
  };

  // Computed properties
  const isAuthenticated = !!user;
  const isEmailConfirmed = user?.email_confirmed_at != null;
  const hasValidProfile = !!userProfile && !!userProfile.id && userProfile.id === user?.id;
  const profileName = userProfile?.name || t('profile:formatting.notSet');

  // Profile fetch control functions
  const enableProfileFetchSkip = useCallback(() => {
    setSkipProfileFetch(true);
  }, []);

  const disableProfileFetchSkip = useCallback(() => {
    setSkipProfileFetch(false);
  }, []);

  const value = {
    // Core state
    user,
    userProfile,
    loading,
    authError,
    sessionExpiry,
    
    // Session detection
    sessionDetectionResult,
    
    // Computed properties
    isAuthenticated,
    isEmailConfirmed,
    hasValidProfile,
    profileName,
    needsProfileCompletion,
    
    // Session management
    showSessionWarning,
    extendSession,
    dismissSessionWarning,
    clearAuthError,
    markProfileCompleted,
    
    // Profile fetch control
    enableProfileFetchSkip,
    disableProfileFetchSkip,
    
    // Auth functions
    signUp,
    signIn,
    signInWithGoogle,
    signInWithApple,
    signOut,
    verifyOtp,
    resendOtp,
    resetPassword,
    updatePassword,
    updateProfile,
    deleteAccount,
  };

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};
