/**
 * Get active matches (planned/pending/running) for a team
 * Used by Team Matches List to show matches coaches can access
 * @param {string} teamId - Team ID
 * @returns {Promise<{success: boolean, matches?: Array, error?: string}>}
 */
export async function getActiveMatches(teamId) {
  try {
    if (!teamId) {
      return {
        success: false,
        error: 'Team ID is required'
      };
    }

    const { data, error } = await supabase
      .from('match')
      .select('id, share_code, opponent, state, created_at, started_at, planned_start_time, type, venue_type, difficulty, owned_by, taken_over_at, upcoming_match(id, match_date, match_time)')
      .eq('team_id', teamId)
      .in('state', ['planned', 'pending', 'running'])
      .is('deleted_at', null)
      .order('created_at', { ascending: false });

    if (error) {
      console.error('Failed to get active matches:', error);
      return {
        success: false,
        error: `Database error: ${error.message}`
      };
    }

    const profileMap = await fetchUserProfileNames(
      (data || []).map(match => match.owned_by)
    );

    // Transform to UI format
    const matches = (data || []).map(match => {
      const linkedUpcoming = Array.isArray(match.upcoming_match)
        ? (match.upcoming_match[0] || null)
        : (match.upcoming_match || null);

      const transformedMatch = {
        id: match.id,
        shareCode: match.share_code || null,
        opponent: match.opponent || 'Internal Match',
        state: match.state,
        createdAt: match.created_at,
        startedAt: match.started_at,
        type: match.type,
        venueType: match.venue_type,
        difficulty: match.difficulty,
        ownedBy: match.owned_by,
        ownedByName: match.owned_by ? (profileMap.get(match.owned_by) ?? null) : null,
        takenOverAt: match.taken_over_at ?? null
      };

      transformedMatch.plannedStartTime = match.planned_start_time ?? null;

      // For planned and pending matches linked from provider schedules, expose provider date/time.
      if (linkedUpcoming?.match_date) {
        transformedMatch.matchDate = linkedUpcoming.match_date;
      }
      if (linkedUpcoming?.match_time) {
        transformedMatch.matchTime = linkedUpcoming.match_time;
      }
      if (linkedUpcoming?.id) {
        transformedMatch.upcomingMatchId = linkedUpcoming.id;
      }

      return transformedMatch;
    });

    // Hide planned matches whose date is before today; today (any time) and
    // future stay visible. pending/running and dateless plans are always kept.
    const today = getTodayLocalDateString();
    const visibleMatches = matches.filter(match => {
      if (match.state !== PLANNED_MATCH_STATE) {
        return true;
      }
      const effectiveDate = match.matchDate
        || (match.plannedStartTime ? getLocalDateFromISO(match.plannedStartTime) : null);
      if (!effectiveDate) {
        return true;
      }
      return effectiveDate >= today;
    });

    return {
      success: true,
      matches: visibleMatches
    };
  } catch (error) {
    console.error('Exception while getting active matches:', error);
    return {
      success: false,
      error: `Unexpected error: ${error.message}`
    };
  }
}

/**
 * Get matches by their IDs (for shared plan links).
 * Only returns planned/pending matches that are not soft-deleted.
 * RLS enforces team membership — the caller must be a team member.
 * @param {string[]} matchIds - Array of match UUIDs
 * @returns {Promise<{success: boolean, matches?: Array, error?: string}>}
 */
export async function getMatchesByIds(matchIds) {
  try {
    const MAX_MATCH_IDS = 10;
    if (!Array.isArray(matchIds) || matchIds.length === 0) {
      return {
        success: false,
        error: 'At least one match ID is required'
      };
    }
    if (matchIds.length > MAX_MATCH_IDS) {
      return {
        success: false,
        error: `Too many match IDs (max ${MAX_MATCH_IDS})`
      };
    }

    const { data, error } = await supabase
      .from('match')
      .select('id, share_code, opponent, state, created_at, started_at, planned_start_time, type, venue_type, difficulty, owned_by, taken_over_at, upcoming_match(id, match_date, match_time)')
      .in('id', matchIds)
      .in('state', ['planned', 'pending'])
      .is('deleted_at', null)
      .order('created_at', { ascending: false });

    if (error) {
      console.error('Failed to get matches by IDs:', error);
      return {
        success: false,
        error: `Database error: ${error.message}`
      };
    }

    // Preserve the order from the original matchIds array (URL order)
    const orderedData = matchIds
      .map(id => (data || []).find(m => m.id === id))
      .filter(Boolean);

    const profileMap = await fetchUserProfileNames(
      orderedData.map(match => match.owned_by)
    );

    // Transform to UI format (same shape as getActiveMatches)
    const matches = orderedData.map(match => {
      const linkedUpcoming = Array.isArray(match.upcoming_match)
        ? (match.upcoming_match[0] || null)
        : (match.upcoming_match || null);

      const transformedMatch = {
        id: match.id,
        shareCode: match.share_code || null,
        opponent: match.opponent || 'Internal Match',
        state: match.state,
        createdAt: match.created_at,
        startedAt: match.started_at,
        type: match.type,
        venueType: match.venue_type,
        difficulty: match.difficulty,
        ownedBy: match.owned_by,
        ownedByName: match.owned_by ? (profileMap.get(match.owned_by) ?? null) : null,
        takenOverAt: match.taken_over_at ?? null
      };

      transformedMatch.plannedStartTime = match.planned_start_time ?? null;

      if (linkedUpcoming?.match_date) {
        transformedMatch.matchDate = linkedUpcoming.match_date;
      }
      if (linkedUpcoming?.match_time) {
        transformedMatch.matchTime = linkedUpcoming.match_time;
      }
      if (linkedUpcoming?.id) {
        transformedMatch.upcomingMatchId = linkedUpcoming.id;
      }

      return transformedMatch;
    });

    return {
      success: true,
      matches
    };
  } catch (error) {
    console.error('Exception while getting matches by IDs:', error);
    return {
      success: false,
      error: `Unexpected error: ${error.message}`
    };
  }
}

/**
 * Get finished matches for a team (match history)
 * @param {string} teamId - Team ID
 * @param {Date} startDate - Optional start date filter
 * @param {Date} endDate - Optional end date filter
 * @returns {Promise<{success: boolean, matches?: Array, error?: string}>}
 */
export async function getFinishedMatches(teamId, startDate = null, endDate = null) {
  try {
    if (!teamId) {
      return {
        success: false,
        error: 'Team ID is required'
      };
    }

    let query = supabase
      .from('match')
      .select(`
        id,
        started_at,
        opponent,
        goals_scored,
        goals_conceded,
        venue_type,
        type,
        difficulty,
        outcome,
        format,
        formation,
        periods,
        period_duration_minutes,
        captain,
        owned_by,
        player_match_stats (
        player:player_id (
          id,
          display_name,
          first_name
        )
      )
      `)
      .eq('team_id', teamId)
      .eq('state', 'finished')
      .is('deleted_at', null)
      .order('started_at', { ascending: false });

    // Apply date filters if provided
    if (startDate) {
      query = query.gte('started_at', startDate.toISOString());
    }
    if (endDate) {
      // Add one day to include the entire end date
      const endDatePlusOne = new Date(endDate);
      endDatePlusOne.setDate(endDatePlusOne.getDate() + 1);
      query = query.lt('started_at', endDatePlusOne.toISOString());
    }

    const { data, error } = await query;

    if (error) {
      console.error('❌ Failed to get finished matches:', error);
      return {
        success: false,
        error: `Database error: ${error.message}`
      };
    }

    const profileMap = await fetchUserProfileNames(
      (data || []).map(match => match.owned_by)
    );

    // Transform data to match UI expectations
    const matches = (data || []).map(match => {
      // Extract unique player names from player_match_stats
      const playerNames = match.player_match_stats
        .filter(stat => stat.player)
        .map(stat => stat.player.display_name || stat.player.first_name || 'Unknown Player');

      return {
        id: match.id,
        date: match.started_at,
        opponent: match.opponent || 'Unknown',
        goalsScored: match.goals_scored,
        goalsConceded: match.goals_conceded,
        venueType: match.venue_type,
        type: match.type.charAt(0).toUpperCase() + match.type.slice(1),
        difficulty: match.difficulty,
        outcome: match.outcome === 'win' ? 'W' : match.outcome === 'draw' ? 'D' : 'L',
        format: match.format,
        ownedBy: match.owned_by || null,
        ownedByName: match.owned_by ? (profileMap.get(match.owned_by) ?? null) : null,
        players: playerNames
      };
    });

    return {
      success: true,
      matches
    };

  } catch (error) {
    console.error('❌ Exception while getting finished matches:', error);
    return {
      success: false,
      error: `Unexpected error: ${error.message}`
    };
  }
}

/**
 * Get match details with player statistics
 * @param {string} matchId - Match ID
 * @returns {Promise<{success: boolean, match?: Object, playerStats?: Array, error?: string}>}
 */
export async function getMatchDetails(matchId) {
  try {
    if (!matchId) {
      return {
        success: false,
        error: 'Match ID is required'
      };
    }

    const { data: match, error: matchError } = await supabase
      .from('match')
      .select(`
        id,
        started_at,
        opponent,
        goals_scored,
        goals_conceded,
        venue_type,
        type,
        difficulty,
        outcome,
        format,
        formation,
        periods,
        period_duration_minutes,
        match_duration_seconds,
        captain,
        owned_by
      `)
      .eq('id', matchId)
      .is('deleted_at', null)
      .single();

    if (matchError) {
      console.error('❌ Failed to get match details:', matchError);
      return {
        success: false,
        error: `Database error: ${matchError.message}`
      };
    }

    // Get player statistics for this match
    const { data: playerStats, error: statsError } = await supabase
      .from('player_match_stats')
      .select(`
        player:player_id (
          id,
          display_name,
          first_name
        ),
        goals_scored,
        goalie_time_seconds,
        defender_time_seconds,
        midfielder_time_seconds,
        attacker_time_seconds,
        substitute_time_seconds,
        total_field_time_seconds,
        started_as,
        was_captain,
        got_fair_play_award
      `)
      .eq('match_id', matchId);

    if (statsError) {
      console.error('❌ Failed to get player stats:', statsError);
      return {
        success: false,
        error: `Database error: ${statsError.message}`
      };
    }

    // Transform match data to UI format
    const matchDate = new Date(match.started_at);

    const normalizedType = typeof match.type === 'string'
      ? match.type.toLowerCase()
      : 'league';

    const profileMap = await fetchUserProfileNames([match.owned_by]);

    const transformedMatch = {
      id: match.id,
      date: matchDate.toISOString().split('T')[0],
      time: matchDate.toTimeString().slice(0, 5),
      type: normalizedType,
      opponent: match.opponent || 'Unknown',
      goalsScored: match.goals_scored,
      goalsConceded: match.goals_conceded,
      venueType: match.venue_type,
      outcome: match.outcome === 'win' ? 'W' : match.outcome === 'draw' ? 'D' : 'L',
      format: match.format,
      difficulty: match.difficulty,
      periods: match.periods,
      periodDuration: match.period_duration_minutes,
      matchDurationSeconds: match.match_duration_seconds,
      formation: match.formation,
      ownedBy: match.owned_by || null,
      ownedByName: match.owned_by ? (profileMap.get(match.owned_by) ?? null) : null
    };

    // Transform player stats to UI format (convert seconds to minutes)
    const transformedPlayerStats = playerStats
      .filter(stat => stat.player)
      .map((stat, index) => {
        const displayName = stat.player.display_name || stat.player.first_name || 'Unnamed Player';
        return {
          id: index + 1,
          playerId: stat.player.id,
          displayName,
          goalsScored: stat.goals_scored || 0,
          totalTimePlayed: (stat.total_field_time_seconds || 0) / 60,
          timeAsDefender: (stat.defender_time_seconds || 0) / 60,
          timeAsMidfielder: (stat.midfielder_time_seconds || 0) / 60,
          timeAsAttacker: (stat.attacker_time_seconds || 0) / 60,
          timeAsGoalkeeper: (stat.goalie_time_seconds || 0) / 60,
          startingRole: formatDatabaseRoleForDisplay(stat.started_as),
          wasCaptain: stat.was_captain || false,
          receivedFairPlayAward: stat.got_fair_play_award || false
        };
      });

    return {
      success: true,
      match: transformedMatch,
      playerStats: transformedPlayerStats
    };

  } catch (error) {
    console.error('❌ Exception while getting match details:', error);
    return {
      success: false,
      error: `Unexpected error: ${error.message}`
    };
  }
}

/**
 * Get aggregated player statistics for a team
 * @param {string} teamId - Team ID
 * @param {Date} startDate - Optional start date filter
 * @param {Date} endDate - Optional end date filter
 * @param {Object} filters - Additional match filters (type, outcome, venue, opponent, player, format)
 * @returns {Promise<{success: boolean, players?: Array, error?: string}>}
 */
export async function getPlayerStats(teamId, startDate = null, endDate = null, filters = {}) {
  try {
    if (!teamId) {
      return {
        success: false,
        error: 'Team ID is required'
      };
    }

    const toStartOfDay = (date) => {
      if (!(date instanceof Date) || Number.isNaN(date.getTime())) return null;
      return new Date(date.getFullYear(), date.getMonth(), date.getDate());
    };

    const toEndOfDay = (date) => {
      if (!(date instanceof Date) || Number.isNaN(date.getTime())) return null;
      return new Date(date.getFullYear(), date.getMonth(), date.getDate(), 23, 59, 59, 999);
    };

    const normalizeFilterArray = (value) => (Array.isArray(value) ? value : []);

    const normalizedFilters = {
      typeFilter: normalizeFilterArray(filters.typeFilter),
      outcomeFilter: normalizeFilterArray(filters.outcomeFilter),
      venueFilter: normalizeFilterArray(filters.venueFilter),
      opponentFilter: normalizeFilterArray(filters.opponentFilter),
      playerFilter: normalizeFilterArray(filters.playerFilter),
      formatFilter: normalizeFilterArray(filters.formatFilter),
      difficultyFilter: normalizeFilterArray(filters.difficultyFilter)
    };

    const normalizedStartDate = toStartOfDay(startDate);
    const normalizedEndDate = toEndOfDay(endDate);

    const formatMatchType = (type) => {
      if (!type || typeof type !== 'string') return null;
      return type.charAt(0).toUpperCase() + type.slice(1);
    };

    const mapOutcomeToDisplay = (outcome) => {
      if (!outcome) return null;
      if (outcome === 'win') return 'W';
      if (outcome === 'draw') return 'D';
      if (outcome === 'loss') return 'L';
      return outcome;
    };

    // Query to get all player match stats for the team's finished matches
    let query = supabase
      .from('player_match_stats')
      .select(`
        player_id,
        goals_scored,
        assists,
        goalie_time_seconds,
        defender_time_seconds,
        midfielder_time_seconds,
        attacker_time_seconds,
        total_field_time_seconds,
        started_as,
        was_captain,
        got_fair_play_award,
        match:match_id (
          id,
          team_id,
          state,
          deleted_at,
          started_at,
          type,
          outcome,
          venue_type,
          opponent,
          format,
          difficulty,
          weight
        ),
        player:player_id (
          id,
          display_name,
          first_name,
          team_id,
          match_id
        )
      `);

    // First fetch all data, then filter in memory
    // (Supabase doesn't support nested filters directly in the select)
    const { data: allStats, error: statsError } = await query;

    if (statsError) {
      console.error('❌ Failed to get player stats:', statsError);
      return {
        success: false,
        error: `Database error: ${statsError.message}`
      };
    }

    // Build helper maps for filtering
    const matchDetailsMap = new Map();

    (allStats || []).forEach((stat) => {
      if (!stat.match || stat.match.team_id !== teamId || stat.match.state !== 'finished' || stat.match.deleted_at !== null) {
        return;
      }

      const matchId = stat.match.id;
      if (!matchId) {
        return;
      }

      const existingDetails = matchDetailsMap.get(matchId);

      const matchDetails = existingDetails || {
        id: matchId,
        date: stat.match.started_at,
        type: formatMatchType(stat.match.type),
        outcome: mapOutcomeToDisplay(stat.match.outcome),
        venueType: stat.match.venue_type,
        opponent: stat.match.opponent || 'Unknown',
        format: stat.match.format,
        difficulty: stat.match.difficulty,
        players: new Set()
      };

      const playerDisplayName = stat.player?.display_name || stat.player?.first_name;
      if (playerDisplayName) {
        matchDetails.players.add(playerDisplayName);
      }

      matchDetailsMap.set(matchId, matchDetails);
    });

    // Filter for finished matches of this team only and apply match filters
    const filteredStats = (allStats || []).filter(stat => {
      if (!stat.match || !stat.player) return false;
      if (stat.match.team_id !== teamId) return false;
      if (stat.match.state !== 'finished') return false;
      if (stat.match.deleted_at !== null) return false;
      if (stat.player.match_id !== null && stat.player.match_id !== undefined) return false;

      // Apply date filters if provided
      if (normalizedStartDate || normalizedEndDate) {
        const matchDate = new Date(stat.match.started_at);
        if (normalizedStartDate && matchDate < normalizedStartDate) return false;
        if (normalizedEndDate && matchDate > normalizedEndDate) return false;
      }

      const matchDetails = matchDetailsMap.get(stat.match.id);
      if (!matchDetails) {
        return false;
      }

      const matchForFilters = {
        ...matchDetails,
        players: Array.from(matchDetails.players)
      };

      if (!matchPassesFilters(matchForFilters, {
        ...normalizedFilters,
        startDate: normalizedStartDate,
        endDate: normalizedEndDate
      })) {
        return false;
      }

      return true;
    });

    // Group stats by player
    const playerStatsMap = new Map();

    filteredStats.forEach(stat => {
      const playerId = stat.player_id;

      if (!playerStatsMap.has(playerId)) {
        const displayName = stat.player.display_name || stat.player.first_name || 'Unnamed Player';
        playerStatsMap.set(playerId, {
          playerId: playerId,
          displayName,
          weightedMatches: 0,
          actualMatches: 0,
          goalsScored: 0,
          assists: 0,
          totalDefenderSeconds: 0,
          totalMidfielderSeconds: 0,
          totalAttackerSeconds: 0,
          totalGoalieSeconds: 0,
          totalFieldTimeSeconds: 0,
          substituteStarts: 0,
          matchesAsCaptain: 0,
          fairPlayAwards: 0
        });
      }

      const playerData = playerStatsMap.get(playerId);
      playerData.weightedMatches += stat.match.weight ?? 1.0;
      playerData.actualMatches += 1;
      playerData.goalsScored += stat.goals_scored || 0;
      playerData.assists += stat.assists || 0;
      playerData.totalDefenderSeconds += stat.defender_time_seconds || 0;
      playerData.totalMidfielderSeconds += stat.midfielder_time_seconds || 0;
      playerData.totalAttackerSeconds += stat.attacker_time_seconds || 0;
      playerData.totalGoalieSeconds += stat.goalie_time_seconds || 0;
      playerData.totalFieldTimeSeconds += stat.total_field_time_seconds || 0;
      if (stat.started_as === 'substitute') playerData.substituteStarts += 1;
      if (stat.was_captain) playerData.matchesAsCaptain += 1;
      if (stat.got_fair_play_award) playerData.fairPlayAwards += 1;
    });

    // Transform to UI format with percentage calculations
    const players = Array.from(playerStatsMap.values()).map(player => {
      const totalOutfielderSeconds = player.totalDefenderSeconds +
                                      player.totalMidfielderSeconds +
                                      player.totalAttackerSeconds;

      // Calculate average time per match in minutes (weighted and actual).
      // Denominator is this team's matches only (not including loans), because
      // loan matches are played on other teams and don't contribute playing time here.
      const averageTimePerMatch = player.weightedMatches > 0
        ? player.totalFieldTimeSeconds / 60 / player.weightedMatches
        : 0;
      const averageTimePerMatchActual = player.actualMatches > 0
        ? player.totalFieldTimeSeconds / 60 / player.actualMatches
        : 0;

      // Calculate percentage started as substitute
      const percentStartedAsSubstitute = player.actualMatches > 0
        ? (player.substituteStarts / player.actualMatches) * 100
        : 0;

      // Calculate position percentages
      // For outfield positions, use outfielder time as denominator
      const percentTimeAsDefender = totalOutfielderSeconds > 0
        ? (player.totalDefenderSeconds / totalOutfielderSeconds) * 100
        : 0;

      const percentTimeAsMidfielder = totalOutfielderSeconds > 0
        ? (player.totalMidfielderSeconds / totalOutfielderSeconds) * 100
        : 0;

      const percentTimeAsAttacker = totalOutfielderSeconds > 0
        ? (player.totalAttackerSeconds / totalOutfielderSeconds) * 100
        : 0;

      // For goalie, use total playing time (goalie + outfield) as denominator
      const percentTimeAsGoalkeeper = (player.totalGoalieSeconds + player.totalFieldTimeSeconds) > 0
        ? (player.totalGoalieSeconds / (player.totalGoalieSeconds + player.totalFieldTimeSeconds)) * 100
        : 0;

      return {
        id: player.playerId,
        displayName: player.displayName,
        weightedMatches: player.weightedMatches,
        actualMatches: player.actualMatches,
        goalsScored: player.goalsScored,
        assists: player.assists,
        totalFieldTimeSeconds: player.totalFieldTimeSeconds,
        averageTimePerMatch: averageTimePerMatch,
        averageTimePerMatchActual: averageTimePerMatchActual,
        percentStartedAsSubstitute: Math.round(percentStartedAsSubstitute * 10) / 10, // 1 decimal
        percentTimeAsDefender: Math.round(percentTimeAsDefender * 10) / 10,
        percentTimeAsMidfielder: Math.round(percentTimeAsMidfielder * 10) / 10,
        percentTimeAsAttacker: Math.round(percentTimeAsAttacker * 10) / 10,
        percentTimeAsGoalkeeper: Math.round(percentTimeAsGoalkeeper * 10) / 10,
        matchesAsCaptain: player.matchesAsCaptain,
        fairPlayAwards: player.fairPlayAwards
      };
    });

    return {
      success: true,
      players
    };

  } catch (error) {
    console.error('❌ Exception while getting player stats:', error);
    return {
      success: false,
      error: `Unexpected error: ${error.message}`
    };
  }
}

/**
 * Get aggregated team statistics
 * @param {string} teamId - Team ID
 * @param {Date} startDate - Optional start date filter
 * @param {Date} endDate - Optional end date filter
 * @returns {Promise<{success: boolean, stats?: Object, error?: string}>}
 */
export async function getTeamStats(teamId, startDate = null, endDate = null) {
  try {
    if (!teamId) {
      return {
        success: false,
        error: 'Team ID is required'
      };
    }

    // Query all finished matches for the team
    let query = supabase
      .from('match')
      .select('*')
      .eq('team_id', teamId)
      .eq('state', 'finished')
      .is('deleted_at', null)
      .order('started_at', { ascending: false });

    const { data: matches, error: matchError } = await query;

    if (matchError) {
      console.error('❌ Failed to get team stats:', matchError);
      return {
        success: false,
        error: `Database error: ${matchError.message}`
      };
    }

    // Filter by date range if provided
    const filteredMatches = (matches || []).filter(match => {
      if (startDate || endDate) {
        const matchDate = new Date(match.started_at);
        if (startDate && matchDate < startDate) return false;
        if (endDate) {
          const endDatePlusOne = new Date(endDate);
          endDatePlusOne.setDate(endDatePlusOne.getDate() + 1);
          if (matchDate >= endDatePlusOne) return false;
        }
      }
      return true;
    });

    // Calculate overall statistics
    const totalMatches = filteredMatches.length;
    const wins = filteredMatches.filter(m => m.outcome === 'win').length;
    const draws = filteredMatches.filter(m => m.outcome === 'draw').length;
    const losses = filteredMatches.filter(m => m.outcome === 'loss').length;

    const goalsScored = filteredMatches.reduce((sum, m) => sum + (m.goals_scored || 0), 0);
    const goalsConceded = filteredMatches.reduce((sum, m) => sum + (m.goals_conceded || 0), 0);

    const cleanSheets = filteredMatches.filter(m => m.goals_conceded === 0).length;

    // Calculate home/away/neutral records
    const homeMatches = filteredMatches.filter(m => m.venue_type === 'home');
    const awayMatches = filteredMatches.filter(m => m.venue_type === 'away');
    const neutralMatches = filteredMatches.filter(m => m.venue_type === 'neutral');

    const homeRecord = {
      wins: homeMatches.filter(m => m.outcome === 'win').length,
      draws: homeMatches.filter(m => m.outcome === 'draw').length,
      losses: homeMatches.filter(m => m.outcome === 'loss').length,
      total: homeMatches.length
    };

    const awayRecord = {
      wins: awayMatches.filter(m => m.outcome === 'win').length,
      draws: awayMatches.filter(m => m.outcome === 'draw').length,
      losses: awayMatches.filter(m => m.outcome === 'loss').length,
      total: awayMatches.length
    };

    const neutralRecord = {
      wins: neutralMatches.filter(m => m.outcome === 'win').length,
      draws: neutralMatches.filter(m => m.outcome === 'draw').length,
      losses: neutralMatches.filter(m => m.outcome === 'loss').length,
      total: neutralMatches.length
    };

    // Format recent matches for display (top 5)
    const recentMatches = filteredMatches.slice(0, 5).map(match => {
      const matchDate = new Date(match.started_at);
      return {
        id: match.id,
        date: matchDate.toISOString().split('T')[0],
        opponent: match.opponent || 'Unknown',
        score: `${match.goals_scored}-${match.goals_conceded}`,
        result: match.outcome === 'win' ? 'W' : match.outcome === 'draw' ? 'D' : 'L'
      };
    });

    // Calculate derived statistics
    const averageGoalsScored = totalMatches > 0 ? goalsScored / totalMatches : 0;
    const averageGoalsConceded = totalMatches > 0 ? goalsConceded / totalMatches : 0;
    const cleanSheetPercentage = totalMatches > 0 ? (cleanSheets / totalMatches) * 100 : 0;

    return {
      success: true,
      stats: {
        totalMatches,
        wins,
        draws,
        losses,
        goalsScored,
        goalsConceded,
        averageGoalsScored: Math.round(averageGoalsScored * 10) / 10,
        averageGoalsConceded: Math.round(averageGoalsConceded * 10) / 10,
        cleanSheets,
        cleanSheetPercentage: Math.round(cleanSheetPercentage * 10) / 10,
        homeRecord,
        awayRecord,
        neutralRecord,
        recentMatches
      }
    };

  } catch (error) {
    console.error('❌ Exception while getting team stats:', error);
    return {
      success: false,
      error: `Unexpected error: ${error.message}`
    };
  }
}

/**
 * Calculate match outcome based on scores
 * @param {number} goalsScored - Goals scored by team
 * @param {number} goalsConceded - Goals conceded by team
 * @returns {string} Outcome: 'win', 'loss', or 'draw'
 */
export function calculateMatchOutcome(goalsScored, goalsConceded) {
  if (goalsScored > goalsConceded) return 'win';
  if (goalsScored < goalsConceded) return 'loss';
  return 'draw';
}

/**
 * Format match data from game state for database storage
 * @param {Object} gameState - Current game state
 * @param {string} teamId - Team ID
 * @returns {Object} Formatted match data
 */
export function formatMatchDataFromGameState(gameState, teamId) {
  const {
    teamConfig,
    selectedFormation,
    periods = DEFAULT_PERIODS,
    periodDurationMinutes = DEFAULT_PERIOD_DURATION_MINUTES,
    opponentTeam,
    captainId,
    matchType = DEFAULT_MATCH_TYPE,
    venueType = DEFAULT_VENUE_TYPE,
    difficulty = DEFAULT_MATCH_DIFFICULTY,
    teamName
  } = gameState;

  const formatKey = teamConfig?.format || FORMATS.FORMAT_5V5;
  const formatConfig = FORMAT_CONFIGS[formatKey] || FORMAT_CONFIGS[FORMATS.FORMAT_5V5];
  const defaultFormation = formatConfig?.defaultFormation || FORMATIONS.FORMATION_2_2;

  return {
    teamId,
    format: teamConfig?.format || FORMATS.FORMAT_5V5,
    formation: selectedFormation || teamConfig?.formation || defaultFormation,
    periods,
    periodDurationMinutes,
    type: matchType,
    opponent: opponentTeam || null,
    captainId: captainId || null,
    venueType: venueType || DEFAULT_VENUE_TYPE,
    difficulty: difficulty || DEFAULT_MATCH_DIFFICULTY,
    teamName: teamName || null
  };
}

/**
 * Format final stats from game state for match completion
 * @param {Object} gameState - Current game state
 * @param {number} matchDurationSeconds - Total match duration
 * @returns {Object} Formatted final stats
 */
export function formatFinalStatsFromGameState(gameState, matchDurationSeconds) {
  const { ownScore, opponentScore, allPlayers } = gameState;

  // Find fair play award winner (could be determined by user selection)
  const fairPlayWinner = allPlayers.find(p => p.hasFairPlayAward);

  return {
    matchDurationSeconds,
    goalsScored: ownScore || 0,
    goalsConceded: opponentScore || 0,
    outcome: calculateMatchOutcome(ownScore || 0, opponentScore || 0),
    fairPlayAwardId: fairPlayWinner?.id || null
  };
}

/**
 * Map formation position to database player_role enum
 * @param {string} position - Formation position (e.g., 'defender', 'left', 'attacker', 'goalie')
 * @param {string} currentRole - Player's current role (optional, for fallback)
 * @returns {string} Database player_role enum value
 */
export function mapFormationPositionToRole(position, currentRole = null) {
  if (!position) {
    console.warn('⚠️  No position provided to mapFormationPositionToRole');
    return roleToDatabase(PLAYER_ROLES.UNKNOWN);
  }

  switch (position) {
    // Goalie position
    case 'goalie':
      return roleToDatabase(PLAYER_ROLES.GOALIE);

    // Defender positions (2-2 and 1-2-1 formations)
    case 'leftDefender':
    case 'rightDefender':
    case 'defender':        // 1-2-1 center back
      return roleToDatabase(PLAYER_ROLES.DEFENDER);

    // Midfielder positions (1-2-1 formation)
    case 'left':            // Left midfielder in 1-2-1
    case 'right':           // Right midfielder in 1-2-1
    case 'leftMidfielder':
    case 'rightMidfielder':
    case 'centerMidfielder':
      return roleToDatabase(PLAYER_ROLES.MIDFIELDER);

    // Attacker positions (2-2 and 1-2-1 formations)
    case 'leftAttacker':
    case 'rightAttacker':
    case 'attacker':        // 1-2-1 center forward
      return roleToDatabase(PLAYER_ROLES.ATTACKER);

    // Substitute positions
    case 'substitute':
    case 'substitute_1':
    case 'substitute_2':
    case 'substitute_3':
    case 'substitute_4':
    case 'substitute_5':
      return roleToDatabase(PLAYER_ROLES.SUBSTITUTE);

    default:
      console.warn('⚠️  Unexpected position value:', position);
      return roleToDatabase(PLAYER_ROLES.UNKNOWN);
  }
}

/**
 * Map game state player role to database player_role enum (DEPRECATED - use mapFormationPositionToRole)
 * @param {string} gameStateRole - Role from game state (PLAYER_ROLES constants or any format)
 * @returns {string} Database player_role enum value
 */
export function mapStartingRoleToDBRole(gameStateRole) {
  if (!gameStateRole) {
    console.warn('⚠️  No starting role provided, defaulting to unknown');
    return roleToDatabase(PLAYER_ROLES.UNKNOWN);
  }

  // Normalize any role format to PLAYER_ROLES constant, then convert to database format
  const normalizedRole = normalizeRole(gameStateRole);

  // For 'FIELD_PLAYER', default to 'defender' since we track actual time in specific roles
  if (normalizedRole === PLAYER_ROLES.FIELD_PLAYER) {
    return roleToDatabase(PLAYER_ROLES.DEFENDER);
  }

  return roleToDatabase(normalizedRole);
}

/**
 * Count goals scored by a specific player using same logic as PlayerStatsTable
 * @param {Object} goalScorers - Goal scorers object { eventId: playerId }
 * @param {Array} matchEvents - Array of match events
 * @param {string} playerId - Player ID to count goals for
 * @returns {number} Number of goals scored by the player
 */
export function countPlayerGoals(goalScorers, matchEvents, playerId) {
  // Import EVENT_TYPES dynamically to avoid circular dependencies
  const EVENT_TYPES = {
    GOAL_SCORED: 'goal_scored',
    GOAL_CONCEDED: 'goal_conceded'
  };

  let goalCount = 0;
  // Count goals from match events (same logic as PlayerStatsTable)
  if (matchEvents && Array.isArray(matchEvents)) {
    matchEvents.forEach(event => {
      if ((event.type === EVENT_TYPES.GOAL_SCORED || event.type === EVENT_TYPES.GOAL_CONCEDED) && !event.undone) {
        // Check goalScorers mapping first, then fall back to event data
        const scorerId = goalScorers[event.id] || event.data?.scorerId;
        if (scorerId === playerId) {
          goalCount++;
        }
      }
    });
  }

  // Fallback to goalScorers object if no matchEvents (backward compatibility)
  if (goalCount === 0 && goalScorers && typeof goalScorers === 'object') {
    goalCount = Object.values(goalScorers).filter(scorerId => scorerId === playerId).length;
  }

  return goalCount;
}

/**
 * Count assists by a specific player — goal_scored events whose data.assistId matches.
 * @param {Array} matchEvents - Array of match events
 * @param {string} playerId - Player ID to count assists for
 * @returns {number} Number of assists by the player
 */
export function countPlayerAssists(matchEvents, playerId) {
  if (!Array.isArray(matchEvents)) return 0;

  return matchEvents.reduce((count, event) => {
    if (event.type === EVENT_TYPES.GOAL_SCORED && !event.undone && event.data?.assistId === playerId) {
      return count + 1;
    }
    return count;
  }, 0);
}

/**
 * Format initial player stats for database insertion when match starts
 * @param {Object} player - Player object from game state
 * @param {string} matchId - Match ID
 * @param {string} captainId - Captain player ID for this match
 * @returns {Object|null} Formatted initial player match stats for database, or null if player didn't participate
 */
export function formatInitialPlayerStats(player, matchId, captainId) {
  // Only process players who are participating in the match (have startedMatchAs or startedAtPosition)
  if (!player.stats?.startedMatchAs && !player.stats?.startedAtPosition) {
    return null;
  }

  let startingRole;
  if (player.stats?.startedAtRole) {
    startingRole = roleToDatabase(player.stats.startedAtRole);
  } else if (player.stats?.startedAtPosition) {
    startingRole = mapFormationPositionToRole(player.stats.startedAtPosition, player.stats.currentRole);
  } else {
    startingRole = roleToDatabase(PLAYER_ROLES.UNKNOWN);
  }

  return {
    player_id: player.id,
    match_id: matchId,
    // Match participation details - only data available at match start
    started_as: startingRole,
    was_captain: player.id === captainId || player.stats?.isCaptain || false,
    // Performance metrics default to 0/false - will be updated when match finishes
    goals_scored: 0,
    assists: 0,
    goalie_time_seconds: 0,
    defender_time_seconds: 0,
    midfielder_time_seconds: 0,
    attacker_time_seconds: 0,
    substitute_time_seconds: 0,
    total_field_time_seconds: 0,
    got_fair_play_award: false
  };
}

/**
 * Format individual player stats for database insertion
 * @param {Object} player - Player object from game state
 * @param {string} matchId - Match ID
 * @param {Object} goalScorers - Goal scorers data { eventId: playerId }
 * @param {Array} matchEvents - Array of match events for goal counting
 * @returns {Object} Formatted player match stats for database
 */
export function formatPlayerMatchStats(player, matchId, goalScorers = {}, matchEvents = []) {
  // Only process players who participated in the match
  if (!player.stats?.startedMatchAs) {
    return null;
  }

  // Calculate total field time using the outfield counter tracked in game state
  const totalFieldTime = Math.max(0, player.stats.timeOnFieldSeconds || 0);

  // Count goals scored by this player
  const goalsScored = countPlayerGoals(goalScorers, matchEvents, player.id);
  // Count assists by this player
  const assists = countPlayerAssists(matchEvents, player.id);


  let startingRole;
  if (player.stats?.startedAtRole) {
    startingRole = roleToDatabase(player.stats.startedAtRole);
  } else if (player.stats?.startedAtPosition) {
    startingRole = mapFormationPositionToRole(player.stats.startedAtPosition, player.stats.currentRole);
  } else {
    startingRole = roleToDatabase(PLAYER_ROLES.UNKNOWN);
  }

  return {
    player_id: player.id,
    match_id: matchId,
    // Performance metrics
    goals_scored: goalsScored,
    assists: assists,
    // Time tracking for all roles
    goalie_time_seconds: player.stats.timeAsGoalieSeconds || 0,
    defender_time_seconds: player.stats.timeAsDefenderSeconds || 0,
    midfielder_time_seconds: player.stats.timeAsMidfielderSeconds || 0,
    attacker_time_seconds: player.stats.timeAsAttackerSeconds || 0,
    substitute_time_seconds: player.stats.timeAsSubSeconds || 0,
    // Total outfield time (excluding goalie time)
    total_field_time_seconds: totalFieldTime,
    // Match participation details
    started_as: startingRole,
    was_captain: player.stats.isCaptain || false,
    got_fair_play_award: player.hasFairPlayAward || false
  };
}

/**
 * Insert initial player match statistics when match starts
 * @param {string} matchId - Match ID
 * @param {Array} allPlayers - Array of all players from game state
 * @param {string} captainId - Captain player ID for this match
 * @returns {Promise<{success: boolean, inserted: number, error?: string}>}
 */
export async function insertInitialPlayerMatchStats(matchId, allPlayers, captainId, selectedSquadIds = []) {
  try {
    const participatingPlayers = Array.isArray(selectedSquadIds) && selectedSquadIds.length > 0
      ? allPlayers.filter(player => selectedSquadIds.includes(player.id))
      : allPlayers;

    // Filter and format initial player stats for players who are participating
    const initialPlayerStatsData = participatingPlayers
      .map(player => formatInitialPlayerStats(player, matchId, captainId))
      .filter(stats => stats !== null); // Remove players who aren't participating

    if (initialPlayerStatsData.length === 0) {
      console.warn('⚠️  No initial player stats to insert - no players participating?');
      return {
        success: true,
        inserted: 0
      };
    }


    const { data, error } = await supabase
      .from('player_match_stats')
      .insert(initialPlayerStatsData)
      .select('id');

    if (error) {
      console.error('❌ Failed to insert initial player match stats:', error);
      return {
        success: false,
        error: `Database error: ${error.message}`
      };
    }

    return {
      success: true,
      inserted: data?.length || 0
    };

  } catch (error) {
    console.error('❌ Exception while inserting initial player match stats:', error);
    return {
      success: false,
      error: `Unexpected error: ${error.message}`
    };
  }
}

/**
 * Update existing match record with new configuration (for back-and-forth navigation)
 * @param {string} matchId - Match ID to update
 * @param {Object} matchData - Updated match configuration and team data
 * @param {string} matchData.teamId - Team ID (required)
 * @param {string} matchData.format - Match format (required, e.g., '5v5')
 * @param {string} matchData.formation - Formation configuration (required)
 * @param {number} matchData.periods - Number of periods (required)
 * @param {number} matchData.periodDurationMinutes - Duration per period (required)
 * @param {string} matchData.type - Match type (required, e.g., 'friendly')
 * @param {string} matchData.opponent - Opponent team name (optional)
 * @param {string} matchData.captainId - Captain player ID (optional)
 * @returns {Promise<{success: boolean, error?: string}>}
 */
export async function updateExistingMatch(matchId, matchData) {
  try {
    // Validate required fields
    const requiredFields = ['teamId', 'format', 'formation', 'periods', 'periodDurationMinutes', 'type', 'venueType'];
    const missingFields = requiredFields.filter(field => !matchData[field]);
    
    if (missingFields.length > 0) {
      return {
        success: false,
        error: `Missing required fields: ${missingFields.join(', ')}`
      };
    }

    if (!matchId) {
      return {
        success: false,
        error: 'Match ID is required'
      };
    }

    // Prepare update data (only updateable fields)
    const updateData = {
      format: matchData.format,
      formation: matchData.formation,
      periods: matchData.periods,
      period_duration_minutes: matchData.periodDurationMinutes,
      type: matchData.type,
      opponent: matchData.opponent || null,
      captain: matchData.captainId || null,
      venue_type: matchData.venueType,
      difficulty: matchData.difficulty || DEFAULT_MATCH_DIFFICULTY,
      state: 'pending',
      updated_at: new Date().toISOString()
    };


    const { data, error } = await supabase
      .from('match')
      .update(updateData)
      .eq('id', matchId)
      .is('deleted_at', null)
      .in('state', ['planned', 'pending']) // Only update planned/pending matches
      .select('share_code')
      .maybeSingle();

    if (error) {
      console.warn('⚠️  Failed to update existing match:', error);
      return {
        success: false,
        error: `Database error: ${error.message}`
      };
    }

    // A 0-row update (no error, no data) means the WHERE clause matched
    // nothing -- e.g. the match was concurrently discarded or moved out of
    // planned/pending. Report it as a failure instead of silently claiming
    // success for an update that never happened.
    if (!data) {
      return {
        success: false,
        error: 'Match not found or no longer editable'
      };
    }

    return { success: true, shareCode: data.share_code || null };

  } catch (error) {
    console.warn('⚠️  Exception while updating existing match:', error);
    return {
      success: false,
      error: `Unexpected error: ${error.message}`
    };
  }
}

/**
 * Persist the complete game+timer state snapshot to match.current_state.
 * Fire-and-forget — failures are logged but never thrown.
 */
const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

export async function persistCurrentMatchState(matchId, snapshot, userId) {
  if (!matchId || !snapshot || !userId) return;
  if (!UUID_REGEX.test(userId)) {
    console.warn('[persistCurrentMatchState] Invalid userId format, aborting write.');
    return;
  }
  try {
    const { error } = await supabase
      .from('match')
      .update({
        current_state: snapshot,
        current_state_updated_at: new Date().toISOString(),
      })
      .eq('id', matchId)
      .or(`owned_by.is.null,owned_by.eq.${userId}`)
      .is('deleted_at', null);

    if (error) {
      console.warn('[persistCurrentMatchState] DB write failed:', error.message);
    }
  } catch (err) {
    console.warn('[persistCurrentMatchState] Unexpected error:', err.message);
  }
}

/**
 * Fetch the current_state snapshot for a running match (for takeover).
 * Returns null if the match has no snapshot yet.
 */
export async function fetchMatchCurrentState(matchId) {
  const { data, error } = await supabase
    .from('match')
    .select('current_state, share_code')
    .eq('id', matchId)
    .is('deleted_at', null)
    .single();
  if (error) throw error;
  if (!data) return null;
  const snapshot = data.current_state ?? null;
  // Propagate share_code into the snapshot's gameState so takeover callers can
  // hydrate currentMatchShareCode alongside currentMatchId.
  if (snapshot?.gameState && data.share_code) {
    return {
      ...snapshot,
      gameState: { ...snapshot.gameState, currentMatchShareCode: data.share_code },
    };
  }
  return snapshot;
}

/**
 * Claim ownership of a running match (takeover).
 * Updates owned_by to the new user and records taken_over_at.
 */
export async function claimMatchOwnership(matchId, userId) {
  const { error } = await supabase
    .from('match')
    .update({
      owned_by: userId,
      taken_over_at: new Date().toISOString(),
    })
    .eq('id', matchId)
    .eq('state', 'running')
    .is('deleted_at', null);
  if (error) throw error;
}

/**
 * Release ownership of a match (best-effort rollback after a failed takeover).
 * Clears owned_by without updating taken_over_at.
 */
export async function releaseMatchOwnership(matchId) {
  const { error } = await supabase
    .from('match')
    .update({ owned_by: null })
    .eq('id', matchId)
    .eq('state', 'running')
    .is('deleted_at', null);
  if (error) throw error;
}

/**
 * Delete all player match statistics for a specific match (for squad changes)
 * @param {string} matchId - Match ID
 * @returns {Promise<{success: boolean, deleted: number, error?: string}>}
 */
export async function deletePlayerMatchStats(matchId) {
  try {
    if (!matchId) {
      return {
        success: false,
        error: 'Match ID is required'
      };
    }


    const { data, error } = await supabase
      .from('player_match_stats')
      .delete()
      .eq('match_id', matchId)
      .select('id'); // Return deleted record IDs for counting

    if (error) {
      console.warn('⚠️  Failed to delete existing player match stats:', error);
      return {
        success: false,
        error: `Database error: ${error.message}`
      };
    }

    const deletedCount = data?.length || 0;

    return {
      success: true,
      deleted: deletedCount
    };

  } catch (error) {
    console.warn('⚠️  Exception while deleting player match stats:', error);
    return {
      success: false,
      error: `Unexpected error: ${error.message}`
    };
  }
}

/**
 * Upsert player match statistics with updated squad/formation without destructive deletes
 * @param {string} matchId - Match ID
 * @param {Array} allPlayers - Array of all players from game state
 * @param {string} captainId - Captain player ID for this match
 * @param {Array} selectedSquadIds - Array of currently selected player IDs (optional, for filtering)
 * @returns {Promise<{success: boolean, inserted: number, deleted: number, error?: string}>}
 */
export async function upsertPlayerMatchStats(matchId, allPlayers, captainId, selectedSquadIds = null) {
  try {
    if (!matchId) {
      return {
        success: false,
        error: 'Match ID is required'
      };
    }

    // Filter to only currently selected players (defensive approach)
    let playersToProcess = allPlayers;
    if (selectedSquadIds && Array.isArray(selectedSquadIds) && selectedSquadIds.length > 0) {
      playersToProcess = allPlayers.filter(player => selectedSquadIds.includes(player.id));
    }

    const statsPayload = playersToProcess
      .map(player => formatInitialPlayerStats(player, matchId, captainId))
      .filter(stats => stats !== null);

    if (statsPayload.length === 0) {
      return {
        success: true,
        inserted: 0,
        updated: 0
      };
    }

    const { data, error } = await supabase
      .from('player_match_stats')
      .upsert(statsPayload, { onConflict: 'match_id,player_id' })
      .select('id');

    if (error) {
      console.error('❌ Failed to upsert player match stats:', error);
      return {
        success: false,
        error: `Database error: ${error.message}`
      };
    }

    return {
      success: true,
      inserted: data?.length || 0,
      updated: data?.length || 0
    };

  } catch (error) {
    console.warn('⚠️  Exception while upserting player match stats:', error);
    return {
      success: false,
      error: `Unexpected error: ${error.message}`
    };
  }
}

/**
 * Save initial match configuration when user clicks "Enter Game".
 *
 * When `expectedPlanVersion` is provided, the update uses optimistic
 * concurrency against the `plan_version` column: if the server's version
 * has moved on since the caller read it (e.g. another coach auto-saved a
 * new squad via PlanMatchesScreen), the update is retried after merging
 * the server's latest `squadSelection` on top of the caller's
 * `initial_config`. All other fields the caller set (captainId, matchType,
 * formation overrides, periodGoalies, etc.) win on the retry — only the
 * squad is taken from the server, because the planner is authoritative
 * for selection.
 *
 * @param {string} matchId - Match ID
 * @param {Object} initialConfig - Complete initial configuration
 * @param {Object} [options]
 * @param {number} [options.expectedPlanVersion] - OCC token from initial load
 * @returns {Promise<{success: boolean, error?: string}>}
 */
export async function saveInitialMatchConfig(matchId, initialConfig, options = {}) {
  const { expectedPlanVersion } = options;
  try {
    if (!matchId) {
      return {
        success: false,
        error: 'Match ID is required'
      };
    }

    if (!initialConfig || typeof initialConfig !== 'object') {
      return {
        success: false,
        error: 'errors.configRequired'
      };
    }

    const buildPayload = (sourceConfig) => {
      const cleanInitialConfig = { ...sourceConfig };
      if (sourceConfig.formation && sourceConfig.teamConfig && sourceConfig.squadSelection) {
        const runtimeTeamConfig = {
          format: sourceConfig.teamConfig?.format,
          formation: sourceConfig.teamConfig?.formation,
          squadSize: sourceConfig.teamConfig?.squadSize
        };
        cleanInitialConfig.formation = normalizeFormationStructure(
          sourceConfig.formation,
          runtimeTeamConfig,
          sourceConfig.squadSelection
        );
      }
      return cleanInitialConfig;
    };

    const performUpdate = async (payloadConfig, versionGuard) => {
      let query = supabase
        .from('match')
        .update({
          initial_config: payloadConfig,
          updated_at: new Date().toISOString()
        })
        .eq('id', matchId)
        .is('deleted_at', null)
        .in('state', ['planned', 'pending']);

      if (typeof versionGuard === 'number') {
        query = query.eq('plan_version', versionGuard);
      }

      return query.select('id, plan_version, initial_config');
    };

    const cleanInitialConfig = buildPayload(initialConfig);

    const { data: firstRows, error: firstError } = await performUpdate(
      cleanInitialConfig,
      typeof expectedPlanVersion === 'number' ? expectedPlanVersion : undefined
    );

    if (firstError) {
      console.error('❌ Failed to save initial match config:', firstError);
      return {
        success: false,
        error: `Database error: ${firstError.message}`
      };
    }

    if (firstRows && firstRows.length > 0) {
      return { success: true, planVersion: firstRows[0].plan_version };
    }

    // 0-row update: either stale version or the row moved out of planned/pending.
    if (typeof expectedPlanVersion !== 'number') {
      // No OCC guard — the row is genuinely not updatable.
      return {
        success: false,
        error: 'Match not found or not in planned/pending state.'
      };
    }

    const { data: latest, error: refetchError } = await supabase
      .from('match')
      .select('id, initial_config, plan_version, state')
      .eq('id', matchId)
      .is('deleted_at', null)
      .maybeSingle();

    if (refetchError || !latest) {
      return {
        success: false,
        error: refetchError ? `Database error: ${refetchError.message}` : 'Match not found.'
      };
    }

    if (latest.state !== 'planned' && latest.state !== 'pending') {
      return {
        success: false,
        error: 'Match is no longer in planned/pending state.'
      };
    }

    // Merge: take the server's squadSelection (planner is authoritative for squad),
    // but keep everything else the caller just set.
    const serverSelection = Array.isArray(latest.initial_config?.squadSelection)
      ? latest.initial_config.squadSelection
      : [];
    const mergedConfig = buildPayload({
      ...initialConfig,
      squadSelection: serverSelection
    });

    const { data: retryRows, error: retryError } = await performUpdate(
      mergedConfig,
      latest.plan_version
    );

    if (retryError) {
      console.error('❌ Retry save-initial-config failed:', retryError);
      return { success: false, error: `Database error: ${retryError.message}` };
    }
    if (!retryRows || retryRows.length === 0) {
      return {
        success: false,
        error: 'Concurrent edit detected; please reload and try again.'
      };
    }

    return { success: true, planVersion: retryRows[0].plan_version, rebased: true };

  } catch (error) {
    console.error('❌ Exception while saving initial match config:', error);
    return {
      success: false,
      error: `Unexpected error: ${error.message}`
    };
  }
}

/**
 * Get squad selections from initial_config for multiple pending matches
 * @param {Array<string>} matchIds - Array of match IDs to fetch
 * @returns {Promise<{success: boolean, selections?: Object, error?: string}>}
 *   selections is a map of { [matchId]: [playerId, ...] }
 */
export async function getSquadSelectionsForMatches(matchIds) {
  try {
    if (!Array.isArray(matchIds) || matchIds.length === 0) {
      return { success: true, selections: {} };
    }

    const { data, error } = await supabase
      .from('match')
      .select('id, initial_config, difficulty, type, venue_type, format')
      .in('id', matchIds)
      .in('state', ['planned', 'pending'])
      .is('deleted_at', null);

    if (error) {
      console.error('Failed to fetch squad selections:', error);
      return {
        success: false,
        error: `Database error: ${error.message}`
      };
    }

    const selections = {};
    const difficulties = {};
    const matchTypes = {};
    const venueTypes = {};
    const formats = {};
    (data || []).forEach(match => {
      const squadSelection = match.initial_config?.squadSelection;
      if (Array.isArray(squadSelection)) {
        // Auto-save writes the authoritative selection (including empty arrays).
        // Seed with whatever the DB says so local and remote stay in sync.
        selections[match.id] = squadSelection;
      }
      if (match.difficulty) {
        difficulties[match.id] = match.difficulty;
      }
      if (match.type) {
        matchTypes[match.id] = match.type;
      }
      if (match.venue_type) {
        venueTypes[match.id] = match.venue_type;
      }
      if (match.format) {
        formats[match.id] = match.format;
      }
    });

    return { success: true, selections, difficulties, matchTypes, venueTypes, formats };
  } catch (error) {
    console.error('Exception while fetching squad selections:', error);
    return {
      success: false,
      error: `Unexpected error: ${error.message}`
    };
  }
}

/**
 * Resolve the effective scheduled date for a planned/pending match row.
 * Prefers the linked upcoming_match.match_date (+match_time) when present,
 * otherwise falls back to planned_start_time. Returns an ISO timestamp string
 * or null when no schedule is available.
 */
export function resolvePlannedMatchEffectiveDate(match) {
  const linkedUpcoming = Array.isArray(match.upcoming_match)
    ? (match.upcoming_match[0] || null)
    : (match.upcoming_match || null);

  if (linkedUpcoming?.match_date) {
    const time = linkedUpcoming.match_time
      ? linkedUpcoming.match_time.slice(0, 8)
      : '00:00:00';
    const iso = `${linkedUpcoming.match_date}T${time}`;
    const parsed = new Date(iso);
    if (!Number.isNaN(parsed.getTime())) {
      return parsed.toISOString();
    }
  }

  if (match.planned_start_time) {
    const parsed = new Date(match.planned_start_time);
    if (!Number.isNaN(parsed.getTime())) {
      return parsed.toISOString();
    }
  }

  return null;
}

export async function getPlannedKickoffTime(matchId) {
  if (!matchId) {
    return null;
  }
  try {
    const { data, error } = await supabase
      .from('match')
      .select('planned_start_time, upcoming_match(match_date, match_time)')
      .eq('id', matchId)
      .single();
    if (error || !data) {
      return null;
    }
    return resolvePlannedMatchEffectiveDate(data);
  } catch (err) {
    console.error('Failed to resolve planned kickoff time:', err);
    return null;
  }
}

/**
 * Fetch planned/pending matches for a team scheduled strictly before a cutoff,
 * with their pre-saved squad selections.
 *
 * Used by the Plan Matches screen when the coach opts in to "count preceding
 * upcoming matches against P/M" — each returned match's squadSelection counts
 * as one virtual "matches played" unit for every selected player.
 *
 * Callers provide the cutoff (the earliest match date in the current planning
 * session) and an optional `excludeMatchIds` set so matches currently being
 * planned don't double count.
 *
 * @param {string} teamId - Team UUID
 * @param {string|Date} cutoff - Matches with effective date strictly less than
 *   this are included. Accepts ISO string or Date.
 * @param {{ excludeMatchIds?: Array<string> }} [options]
 * @returns {Promise<{success: boolean, matches?: Array<{id: string, effectiveDate: string, squadSelection: string[]}>, error?: string}>}
 */
export async function getPrecedingPlannedMatches(teamId, cutoff, options = {}) {
  try {
    if (!teamId) {
      return { success: false, error: 'Team ID is required' };
    }
    if (!cutoff) {
      return { success: true, matches: [] };
    }

    const cutoffDate = cutoff instanceof Date ? cutoff : new Date(cutoff);
    if (Number.isNaN(cutoffDate.getTime())) {
      return { success: false, error: 'Invalid cutoff date' };
    }

    const excludeSet = new Set((options.excludeMatchIds || []).map(String));

    const { data, error } = await supabase
      .from('match')
      .select('id, state, planned_start_time, initial_config, upcoming_match(id, match_date, match_time)')
      .eq('team_id', teamId)
      .in('state', ['planned', 'pending'])
      .is('deleted_at', null);

    if (error) {
      console.error('Failed to fetch preceding planned matches:', error);
      return { success: false, error: `Database error: ${error.message}` };
    }

    const matches = [];
    (data || []).forEach(match => {
      if (excludeSet.has(String(match.id))) return;

      const effectiveIso = resolvePlannedMatchEffectiveDate(match);
      if (!effectiveIso) return;

      const effectiveDate = new Date(effectiveIso);
      if (effectiveDate.getTime() >= cutoffDate.getTime()) return;

      const squadSelection = Array.isArray(match.initial_config?.squadSelection)
        ? match.initial_config.squadSelection
        : [];

      matches.push({
        id: match.id,
        effectiveDate: effectiveIso,
        squadSelection
      });
    });

    return { success: true, matches };
  } catch (error) {
    console.error('Exception while fetching preceding planned matches:', error);
    return { success: false, error: `Unexpected error: ${error.message}` };
  }
}

/**
 * Update squad selection and seed player stats for an existing planned match.
 * Keeps the match in planned state so ConfigurationScreen can still transition it to pending later.
 *
 * @param {string} matchId - Planned match ID
 * @param {Array<string>} selectedSquadIds - Selected player IDs for the planned match
 * @param {Array<Object>} rosterPlayers - Team roster players
 * @param {Object} defaults - Match planning defaults
 * @returns {Promise<{success: boolean, error?: string}>}
 */
export async function updatePlannedMatchSquad(matchId, selectedSquadIds, rosterPlayers, defaults) {
  try {
    if (!matchId) {
      return {
        success: false,
        error: 'Match ID is required'
      };
    }

    if (!Array.isArray(selectedSquadIds) || selectedSquadIds.length === 0) {
      return {
        success: false,
        error: 'Select at least one player for the match.'
      };
    }

    if (!defaults?.format || !defaults?.formation) {
      return {
        success: false,
        error: 'Match defaults are missing.'
      };
    }

    const { data: existingMatch, error: fetchError } = await supabase
      .from('match')
      .select('captain, initial_config')
      .eq('id', matchId)
      .eq('state', 'planned')
      .is('deleted_at', null)
      .maybeSingle();

    if (fetchError) {
      console.error('Failed to fetch planned match for squad update:', fetchError);
      return {
        success: false,
        error: `Database error: ${fetchError.message}`
      };
    }

    if (!existingMatch) {
      return {
        success: false,
        error: 'Planned match not found.'
      };
    }

    const deleteResult = await deletePlayerMatchStats(matchId);
    if (!deleteResult.success) {
      return {
        success: false,
        error: deleteResult.error
      };
    }

    const captainId = existingMatch.captain || existingMatch.initial_config?.matchConfig?.captainId || null;
    const plannedPlayers = selectedSquadIds.map((playerId) => {
      const player = (rosterPlayers || []).find((candidate) => candidate.id === playerId);

      return {
        id: playerId,
        displayName: player?.display_name || player?.displayName || player?.first_name || player?.firstName || 'Unknown Player',
        firstName: player?.first_name || player?.firstName || player?.display_name || player?.displayName || 'Unknown Player',
        lastName: player?.last_name || player?.lastName || null,
        stats: {
          startedMatchAs: PLAYER_ROLES.FIELD_PLAYER,
          startedAtRole: PLAYER_ROLES.UNKNOWN,
          isCaptain: playerId === captainId
        }
      };
    });

    const insertResult = await insertInitialPlayerMatchStats(matchId, plannedPlayers, captainId, selectedSquadIds);
    if (!insertResult.success) {
      return {
        success: false,
        error: insertResult.error
      };
    }

    const teamConfig = createTeamConfig(defaults.format, selectedSquadIds.length, defaults.formation);
    const formationTemplate = getInitialFormationTemplate(teamConfig);
    const existingConfig = existingMatch.initial_config || {};
    const updatedInitialConfig = {
      ...existingConfig,
      teamConfig,
      squadSelection: selectedSquadIds,
      formation: normalizeFormationStructure(
        formationTemplate,
        teamConfig,
        selectedSquadIds
      ),
      matchConfig: {
        ...(existingConfig.matchConfig || {}),
        ...(defaults.difficulty ? { difficulty: defaults.difficulty } : {})
      }
    };

    const matchUpdate = {
      initial_config: updatedInitialConfig,
      updated_at: new Date().toISOString()
    };
    if (defaults.difficulty) {
      matchUpdate.difficulty = defaults.difficulty;
    }

    const { error: updateError } = await supabase
      .from('match')
      .update(matchUpdate)
      .eq('id', matchId)
      .eq('state', 'planned')
      .is('deleted_at', null);

    if (updateError) {
      console.error('Failed to update planned match squad:', updateError);
      return {
        success: false,
        error: `Database error: ${updateError.message}`
      };
    }

    return { success: true };
  } catch (error) {
    console.error('Exception while updating planned match squad:', error);
    return {
      success: false,
      error: `Unexpected error: ${error.message}`
    };
  }
}

/**
 * Lightweight auto-save for PlanMatchesScreen edits.
 *
 * Updates only `match.initial_config.squadSelection`,
 * `match.initial_config.matchConfig.difficulty`, and `match.difficulty`. Does
 * NOT rebuild `player_match_stats` — that happens at the explicit "Set up
 * match" / ConfigurationScreen save path.
 *
 * Uses optimistic concurrency: the update only succeeds if the server's
 * current `plan_version` matches `expectedPlanVersion`. On mismatch the
 * function refetches the row and returns `{ success: false, conflict: true,
 * serverState }` so the caller can run a three-way rebase and retry.
 *
 * Accepts empty `selectedSquadIds` (user may want to clear a planned squad).
 *
 * @param {Object} params
 * @param {string} params.matchId
 * @param {Array<string>} params.selectedSquadIds
 * @param {string|null} [params.difficulty] - optional new difficulty
 * @param {string|null} [params.matchType] - optional new match type (e.g. 'league')
 * @param {string|null} [params.venueType] - optional new venue type (e.g. 'home')
 * @param {string|null} [params.format] - optional new format (e.g. '5v5')
 * @param {string|null} [params.formation] - optional new formation paired with format change
 * @param {number|null} [params.expectedPlanVersion]
 * @returns {Promise<{ success: boolean, newPlanVersion?: number, initialConfig?: Object, difficulty?: string, matchType?: string, venueType?: string, format?: string, formation?: string, lastUpdatedBy?: string, updatedAt?: string, conflict?: boolean, serverState?: Object, error?: string }>}
 */
export async function autoSaveMatchPlan({
  matchId,
  selectedSquadIds,
  difficulty,
  matchType,
  venueType,
  format,
  formation,
  expectedPlanVersion
} = {}) {
  try {
    if (!matchId) {
      return { success: false, error: 'Match ID is required' };
    }

    if (!Array.isArray(selectedSquadIds)) {
      return { success: false, error: 'Squad selection must be an array' };
    }

    const { data: existing, error: fetchError } = await supabase
      .from('match')
      .select('id, initial_config, difficulty, type, venue_type, format, formation, plan_version, state, last_updated_by, updated_at')
      .eq('id', matchId)
      .in('state', ['planned', 'pending'])
      .is('deleted_at', null)
      .maybeSingle();

    if (fetchError) {
      console.error('Failed to fetch match for auto-save:', fetchError);
      return { success: false, error: `Database error: ${fetchError.message}` };
    }

    if (!existing) {
      return { success: false, error: 'Match not found or not editable.' };
    }

    if (typeof expectedPlanVersion === 'number' && existing.plan_version !== expectedPlanVersion) {
      return {
        success: false,
        conflict: true,
        serverState: buildAutoSaveServerState(existing)
      };
    }

    const existingConfig = existing.initial_config || {};
    const existingMatchConfig = existingConfig.matchConfig || {};
    const existingTeamConfig = existingConfig.teamConfig || {};
    const nextMatchConfig = {
      ...existingMatchConfig,
      ...(difficulty ? { difficulty } : {}),
      ...(matchType ? { matchType } : {}),
      ...(venueType ? { venueType } : {}),
      ...(format ? { format } : {})
    };
    // When format changes, rebuild teamConfig AND the top-level formation
    // template so every formation-bearing field (match.format column,
    // match.formation column, teamConfig.format/formation, and
    // initial_config.formation) reflects the same pair. Leaving the
    // top-level template stale would mean a ConfigurationScreen resume
    // could pick up positions from the old format's template.
    const nextTeamConfig = format
      ? {
          ...existingTeamConfig,
          format,
          ...(formation ? { formation } : {}),
          squadSize: existingTeamConfig.squadSize || selectedSquadIds.length
        }
      : null;
    const nextInitialConfig = {
      ...existingConfig,
      squadSelection: [...selectedSquadIds],
      matchConfig: nextMatchConfig,
      ...(nextTeamConfig
        ? {
            teamConfig: nextTeamConfig,
            formation: getInitialFormationTemplate(nextTeamConfig)
          }
        : {})
    };

    const matchUpdate = {
      initial_config: nextInitialConfig,
      updated_at: new Date().toISOString()
    };
    if (difficulty) {
      matchUpdate.difficulty = difficulty;
    }
    if (matchType) {
      matchUpdate.type = matchType;
    }
    if (venueType) {
      matchUpdate.venue_type = venueType;
    }
    if (format) {
      matchUpdate.format = format;
    }
    // Keep the raw match.formation column in lock-step with match.format.
    // Downstream readers (e.g. getMostRecentFinishedMatch) look at the
    // column directly, not initial_config, so skipping this write pollutes
    // planning defaults for the next match.
    if (format && formation) {
      matchUpdate.formation = formation;
    }

    const versionGuard = typeof expectedPlanVersion === 'number'
      ? supabase
          .from('match')
          .update(matchUpdate)
          .eq('id', matchId)
          .eq('plan_version', expectedPlanVersion)
          .in('state', ['planned', 'pending'])
          .is('deleted_at', null)
      : supabase
          .from('match')
          .update(matchUpdate)
          .eq('id', matchId)
          .in('state', ['planned', 'pending'])
          .is('deleted_at', null);

    const { data: updatedRows, error: updateError } = await versionGuard
      .select('id, initial_config, difficulty, type, venue_type, format, formation, plan_version, last_updated_by, updated_at');

    if (updateError) {
      console.error('Auto-save update failed:', updateError);
      return { success: false, error: `Database error: ${updateError.message}` };
    }

    if (!updatedRows || updatedRows.length === 0) {
      // Row disappeared or another writer bumped plan_version between our fetch and update.
      const { data: refetched } = await supabase
        .from('match')
        .select('id, initial_config, difficulty, type, venue_type, format, formation, plan_version, state, last_updated_by, updated_at')
        .eq('id', matchId)
        .is('deleted_at', null)
        .maybeSingle();

      if (!refetched) {
        return { success: false, error: 'Match not found or no longer editable.' };
      }

      return {
        success: false,
        conflict: true,
        serverState: buildAutoSaveServerState(refetched)
      };
    }

    const row = updatedRows[0];
    return {
      success: true,
      newPlanVersion: row.plan_version,
      initialConfig: row.initial_config,
      difficulty: row.difficulty,
      matchType: row.type,
      venueType: row.venue_type,
      format: row.format,
      formation: row.formation,
      lastUpdatedBy: row.last_updated_by,
      updatedAt: row.updated_at
    };
  } catch (error) {
    console.error('Exception during auto-save:', error);
    return { success: false, error: `Unexpected error: ${error.message}` };
  }
}

function buildAutoSaveServerState(row) {
  const initialConfig = row.initial_config || {};
  const selection = Array.isArray(initialConfig.squadSelection)
    ? initialConfig.squadSelection
    : [];
  return {
    planVersion: row.plan_version,
    selection,
    difficulty: row.difficulty || null,
    matchType: row.type || null,
    venueType: row.venue_type || null,
    format: row.format || null,
    formation: row.formation || null,
    initialConfig,
    lastUpdatedBy: row.last_updated_by || null,
    updatedAt: row.updated_at || null,
    state: row.state || null
  };
}

/**
 * Fetch the plan-version fingerprint for a set of planned/pending matches.
 * Used to seed useAutoSavePlan with the current server `plan_version` so that
 * subsequent updates can include a proper OCC token.
 */
export async function getPlanFingerprintsForMatches(matchIds) {
  try {
    if (!Array.isArray(matchIds) || matchIds.length === 0) {
      return { success: true, fingerprints: {} };
    }

    const { data, error } = await supabase
      .from('match')
      .select('id, plan_version, last_updated_by, updated_at, initial_config, difficulty, type, venue_type, format, formation')
      .in('id', matchIds)
      .in('state', ['planned', 'pending'])
      .is('deleted_at', null);

    if (error) {
      console.error('Failed to fetch plan fingerprints:', error);
      return { success: false, error: `Database error: ${error.message}` };
    }

    const fingerprints = {};
    (data || []).forEach((row) => {
      fingerprints[row.id] = {
        planVersion: row.plan_version,
        lastUpdatedBy: row.last_updated_by || null,
        updatedAt: row.updated_at || null,
        selection: Array.isArray(row.initial_config?.squadSelection)
          ? row.initial_config.squadSelection
          : [],
        difficulty: row.difficulty || null,
        matchType: row.type || null,
        venueType: row.venue_type || null,
        format: row.format || null,
        formation: row.formation || null
      };
    });
    return { success: true, fingerprints };
  } catch (error) {
    console.error('Exception while fetching plan fingerprints:', error);
    return { success: false, error: `Unexpected error: ${error.message}` };
  }
}

/**
 * Resolve a user's display name by user_profile id.
 * Used by the remote-editor toast in PlanMatchesScreen to identify co-coaches.
 * @param {string} userId - user_profile.id
 * @returns {Promise<{success: boolean, name?: string|null, error?: string}>}
 */
export async function getUserDisplayName(userId) {
  try {
    if (!userId) {
      return { success: false, error: 'User ID is required' };
    }

    const { data, error } = await supabase
      .from('user_profile')
      .select('name')
      .eq('id', userId)
      .maybeSingle();

    if (error) {
      console.error('Failed to fetch user display name:', error);
      return { success: false, error: `Database error: ${error.message}` };
    }

    return { success: true, name: data?.name || null };
  } catch (error) {
    console.error('Exception while fetching user display name:', error);
    return { success: false, error: `Unexpected error: ${error.message}` };
  }
}

/**
 * Get the most relevant "resumable" match for a team.
 *
 * Considers two buckets:
 *   - state = 'pending' (any age — partial configuration awaiting completion)
 *   - state = 'planned' AND planned_start_time falls in [today 00:00, tomorrow 00:00)
 *     in the local timezone (planned-for-today; see issue #514)
 *
 * Returns the single best candidate: prefers the most recently created `pending`
 * match if one exists, otherwise the earliest planned-today match. Planned
 * matches without a `planned_start_time` are not considered (we don't know when
 * they're meant to happen — see #513).
 *
 * @param {string} teamId - Team ID
 * @returns {Promise<{success: boolean, match?: Object, error?: string}>}
 */
export async function getPendingMatchForTeam(teamId) {
  try {
    if (!teamId) {
      return {
        success: false,
        error: 'Team ID is required'
      };
    }

    const { startOfTodayISO, startOfTomorrowISO } = getLocalDayBoundsISO();

    const [pendingResult, plannedResult] = await Promise.all([
      supabase
        .from('match')
        .select('*')
        .eq('team_id', teamId)
        .is('deleted_at', null)
        .eq('state', 'pending')
        .order('created_at', { ascending: false })
        .limit(1)
        .maybeSingle(),
      supabase
        .from('match')
        .select('*')
        .eq('team_id', teamId)
        .is('deleted_at', null)
        .eq('state', 'planned')
        .gte('planned_start_time', startOfTodayISO)
        .lt('planned_start_time', startOfTomorrowISO)
        .order('planned_start_time', { ascending: true })
        .limit(1)
        .maybeSingle()
    ]);

    if (pendingResult.error) {
      console.error('❌ Failed to get pending match:', pendingResult.error);
      return {
        success: false,
        error: `Database error: ${pendingResult.error.message}`
      };
    }
    if (plannedResult.error) {
      // Don't fail the whole call if only the planned query errors —
      // we can still surface a pending match.
      console.warn('⚠️ Failed to get planned-today match:', plannedResult.error);
    }

    // Prefer pending (in-progress setup) over planned (pre-staged for today).
    const match = pendingResult.data || plannedResult.data || null;

    return {
      success: true,
      match
    };

  } catch (error) {
    console.error('❌ Exception while getting pending match:', error);
    return {
      success: false,
      error: `Unexpected error: ${error.message}`
    };
  }
}

/**
 * Delete pending match and clear local state
 * @param {string} matchId - Match ID
 * @returns {Promise<{success: boolean, error?: string}>}
 */
export async function discardPendingMatch(matchId) {
  try {
    if (!matchId) {
      return {
        success: false,
        error: 'Match ID is required'
      };
    }


    // First delete any associated player match stats
    await supabase
      .from('player_match_stats')
      .delete()
      .eq('match_id', matchId);

    // Then soft delete the match record
    const nowIso = new Date().toISOString();

    const { error } = await supabase
      .from('match')
      .update(
        {
          deleted_at: nowIso
        },
        { returning: 'minimal' }
      )
      .eq('id', matchId)
      .is('deleted_at', null)
      .in('state', ['planned', 'pending']); // Only update planned/pending matches

    if (error) {
      console.error('❌ Failed to discard pending match:', error);
      return {
        success: false,
        error: `Database error: ${error.message}`
      };
    }

    return { success: true };

  } catch (error) {
    console.error('❌ Exception while discarding pending match:', error);
    return {
      success: false,
      error: `Unexpected error: ${error.message}`
    };
  }
}

export async function deleteFinishedMatch(matchId) {
  try {
    if (!matchId) {
      return {
        success: false,
        error: 'Match ID is required'
      };
    }

    const nowIso = new Date().toISOString();

    const statsResult = await supabase
      .from('player_match_stats')
      .delete()
      .eq('match_id', matchId);

    if (statsResult.error) {
      console.error('❌ Failed to delete player match stats:', statsResult.error);
      return {
        success: false,
        error: `Database error: ${statsResult.error.message}`
      };
    }

    const matchResult = await supabase
      .from('match')
      .update(
        {
          deleted_at: nowIso
        },
        { returning: 'minimal' }
      )
      .eq('id', matchId)
      .is('deleted_at', null)
      .eq('state', 'finished');

    if (matchResult.error) {
      console.error('❌ Failed to delete finished match:', matchResult.error);
      return {
        success: false,
        error: `Database error: ${matchResult.error.message}`
      };
    }

    if (!matchResult.data || matchResult.data.length === 0) {
      return {
        success: false,
        error: 'errors.matchNotFoundOrDeleted'
      };
    }

    return { success: true };

  } catch (error) {
    console.error('❌ Exception while deleting finished match:', error);
    return {
      success: false,
      error: `Unexpected error: ${error.message}`
    };
  }
}

/**
 * Update match details from the edit view
 * @param {string} matchId - Match ID
 * @param {Object} matchUpdates - Updated match fields
 * @param {string} matchUpdates.opponent - Opponent team name (optional)
 * @param {number} matchUpdates.goalsScored - Goals scored by team
 * @param {number} matchUpdates.goalsConceded - Goals conceded by team
 * @param {string} matchUpdates.venueType - Venue type (home/away/neutral)
 * @param {string} matchUpdates.type - Match type
 * @param {string} matchUpdates.format - Match format
 * @param {string} matchUpdates.formation - Formation
 * @param {number} matchUpdates.periods - Number of periods
 * @param {number} matchUpdates.periodDuration - Period duration in minutes
 * @param {string} matchUpdates.date - Match date (YYYY-MM-DD)
 * @param {string} matchUpdates.time - Match time (HH:MM)
 * @returns {Promise<{success: boolean, error?: string}>}
 */
export async function updateMatchDetails(matchId, matchUpdates) {
  try {
    if (!matchId) {
      return {
        success: false,
        error: 'Match ID is required'
      };
    }

    // Recalculate outcome based on scores
    const outcome = calculateMatchOutcome(matchUpdates.goalsScored, matchUpdates.goalsConceded);

    // Combine date and time to create started_at timestamp
    const startedAt = new Date(`${matchUpdates.date}T${matchUpdates.time}:00`).toISOString();

    // Recalculate weight based on (possibly edited) periods/duration and current team preferences
    const { data: matchRecord, error: matchFetchError } = await supabase
      .from('match')
      .select('team_id')
      .eq('id', matchId)
      .single();

    if (matchFetchError) {
      console.warn('Could not fetch team_id for weight recalculation, defaulting to 1.0:', matchFetchError);
    }

    const weight = await calculateMatchWeightFromPreferences(
      matchRecord?.team_id,
      matchUpdates.periods,
      matchUpdates.periodDuration
    );

    // Prepare update data
    const updateData = {
      opponent: matchUpdates.opponent || null,
      goals_scored: matchUpdates.goalsScored,
      goals_conceded: matchUpdates.goalsConceded,
      outcome: outcome,
      venue_type: matchUpdates.venueType,
      type: matchUpdates.type.toLowerCase(),
      difficulty: matchUpdates.difficulty || DEFAULT_MATCH_DIFFICULTY,
      format: matchUpdates.format,
      formation: matchUpdates.formation,
      periods: matchUpdates.periods,
      period_duration_minutes: matchUpdates.periodDuration,
      match_duration_seconds: matchUpdates.matchDurationSeconds,
      started_at: startedAt,
      updated_at: new Date().toISOString(),
      weight
    };

    const { error } = await supabase
      .from('match')
      .update(updateData)
      .eq('id', matchId)
      .is('deleted_at', null);

    if (error) {
      console.error('❌ Failed to update match details:', error);
      return {
        success: false,
        error: `Database error: ${error.message}`
      };
    }

    return { success: true };

  } catch (error) {
    console.error('❌ Exception while updating match details:', error);
    return {
      success: false,
      error: `Unexpected error: ${error.message}`
    };
  }
}

/**
 * Update individual player match statistics from the edit view
 * @param {string} matchId - Match ID
 * @param {string} playerId - Player ID (from playerStats.playerId)
 * @param {Object} statUpdates - Updated stat fields
 * @param {number} statUpdates.goalsScored - Goals scored
 * @param {number} statUpdates.timeAsDefender - Time as defender (minutes)
 * @param {number} statUpdates.timeAsMidfielder - Time as midfielder (minutes)
 * @param {number} statUpdates.timeAsAttacker - Time as attacker (minutes)
 * @param {number} statUpdates.timeAsGoalkeeper - Time as goalkeeper (minutes)
 * @param {string} statUpdates.startingRole - Starting role
 * @param {boolean} statUpdates.wasCaptain - Was captain flag
 * @param {boolean} statUpdates.receivedFairPlayAward - Fair play award flag
 * @returns {Promise<{success: boolean, error?: string}>}
 */
function buildPlayerMatchStatUpdateRow(matchId, playerId, statUpdates) {
  const defenderSeconds = Math.round((statUpdates.timeAsDefender || 0) * 60);
  const midfielderSeconds = Math.round((statUpdates.timeAsMidfielder || 0) * 60);
  const attackerSeconds = Math.round((statUpdates.timeAsAttacker || 0) * 60);
  const goalieSeconds = Math.round((statUpdates.timeAsGoalkeeper || 0) * 60);

  const totalFieldTimeSeconds = defenderSeconds + midfielderSeconds + attackerSeconds;

  const startedAs = statUpdates.startingRole ? mapDisplayRoleToDatabaseRole(statUpdates.startingRole) : null;

  return {
    match_id: matchId,
    player_id: playerId,
    goals_scored: statUpdates.goalsScored,
    ...(statUpdates.assists !== undefined ? { assists: statUpdates.assists } : {}),
    defender_time_seconds: defenderSeconds,
    midfielder_time_seconds: midfielderSeconds,
    attacker_time_seconds: attackerSeconds,
    goalie_time_seconds: goalieSeconds,
    total_field_time_seconds: totalFieldTimeSeconds,
    started_as: startedAs,
    was_captain: statUpdates.wasCaptain,
    got_fair_play_award: statUpdates.receivedFairPlayAward,
    updated_at: new Date().toISOString()
  };
}

export async function updatePlayerMatchStat(matchId, playerId, statUpdates) {
  try {
    if (!matchId || !playerId) {
      return {
        success: false,
        error: 'Match ID and Player ID are required'
      };
    }

    const updateData = buildPlayerMatchStatUpdateRow(matchId, playerId, statUpdates);

    const { error } = await supabase
      .from('player_match_stats')
      .update(updateData)
      .eq('match_id', matchId)
      .eq('player_id', playerId);

    if (error) {
      console.error('❌ Failed to update player match stats:', error);
      return {
        success: false,
        error: `Database error: ${error.message}`
      };
    }

    return { success: true };

  } catch (error) {
    console.error('❌ Exception while updating player match stats:', error);
    return {
      success: false,
      error: `Unexpected error: ${error.message}`
    };
  }
}

export async function updatePlayerMatchStatsBatch(matchId, playerStats = []) {
  try {
    if (!matchId) {
      return {
        success: false,
        error: 'Match ID is required'
      };
    }

    if (!Array.isArray(playerStats)) {
      return {
        success: false,
        error: 'errors.invalidPlayerStats'
      };
    }

    if (playerStats.length === 0) {
      return {
        success: true,
        updated: 0
      };
    }

    const updateRows = playerStats
      .filter(player => player?.playerId)
      .map(player => buildPlayerMatchStatUpdateRow(matchId, player.playerId, player));

    if (updateRows.length === 0) {
      return {
        success: false,
        error: 'errors.noValidPlayerStats'
      };
    }

    const { error } = await supabase
      .from('player_match_stats')
      .upsert(updateRows, {
        onConflict: 'match_id,player_id'
      });

    if (error) {
      console.error('❌ Failed to batch update player match stats:', error);
      return {
        success: false,
        error: `Database error: ${error.message}`
      };
    }

    return {
      success: true,
      updated: updateRows.length
    };
  } catch (error) {
    console.error('❌ Exception while batch updating player match stats:', error);
    return {
      success: false,
      error: `Unexpected error: ${error.message}`
    };
  }
}

/**
 * Update player match statistics when match finishes
 * @param {string} matchId - Match ID
 * @param {Array} allPlayers - Array of all players from game state
 * @param {Object} goalScorers - Goal scorers data { eventId: playerId }
 * @param {Array} matchEvents - Array of match events for goal counting
 * @returns {Promise<{success: boolean, updated: number, total?: number, failures?: Array<{playerId: string, error: string}>, error?: string}>}
 */
export async function updatePlayerMatchStatsOnFinish(matchId, allPlayers, goalScorers = {}, matchEvents = []) {
  try {
    const participatingPlayers = allPlayers.filter(player =>
      player.stats?.startedMatchAs || player.stats?.startedAtPosition
    );

    if (participatingPlayers.length === 0) {
      console.warn('⚠️  No player stats to update - no players participated?');
      return {
        success: true,
        updated: 0,
        total: 0,
        failures: []
      };
    }

    const updatedAt = new Date().toISOString();
    const rows = [];
    const droppedPlayerIds = [];
    for (const player of participatingPlayers) {
      const playerStats = formatPlayerMatchStats(player, matchId, goalScorers, matchEvents);
      if (!playerStats) {
        // Player passed the participatingPlayers filter via startedAtPosition but
        // formatPlayerMatchStats requires startedMatchAs; log so incident debugging
        // doesn't have to puzzle out a silent count mismatch.
        droppedPlayerIds.push(player.id);
        continue;
      }

      // started_as must be included in the upsert payload. The .upsert() call
      // becomes INSERT ... ON CONFLICT (match_id, player_id) DO UPDATE, and
      // PostgreSQL evaluates NOT NULL constraints on the proposed INSERT row
      // before the unique-index conflict check fires the UPDATE path. Omitting
      // started_as (NOT NULL, no default) makes every call fail with
      // "null value in column started_as ..." even when the seeded row already
      // exists with started_as set. The value here matches what
      // insertInitialPlayerMatchStats seeded, so the UPDATE path is a no-op
      // overwrite for that column.
      rows.push({
        match_id: matchId,
        player_id: player.id,
        started_as: playerStats.started_as,
        goals_scored: playerStats.goals_scored,
        goalie_time_seconds: playerStats.goalie_time_seconds,
        defender_time_seconds: playerStats.defender_time_seconds,
        midfielder_time_seconds: playerStats.midfielder_time_seconds,
        attacker_time_seconds: playerStats.attacker_time_seconds,
        substitute_time_seconds: playerStats.substitute_time_seconds,
        total_field_time_seconds: playerStats.total_field_time_seconds,
        got_fair_play_award: playerStats.got_fair_play_award,
        updated_at: updatedAt
      });
    }

    if (droppedPlayerIds.length > 0) {
      console.warn(
        `⚠️  Skipped ${droppedPlayerIds.length} player(s) missing startedMatchAs in formatPlayerMatchStats:`,
        droppedPlayerIds
      );
    }

    if (rows.length === 0) {
      // All candidates were skipped above — nothing was actually sent to Supabase.
      // Report total: 0 so the caller's counters don't suggest rows were attempted.
      return {
        success: true,
        updated: 0,
        total: 0,
        failures: []
      };
    }

    // Batched upsert: a single round-trip replaces N sequential UPDATEs so a
    // transient drop on one player no longer aborts match finalisation (#455).
    const { error } = await supabase
      .from('player_match_stats')
      .upsert(rows, { onConflict: 'match_id,player_id' });

    if (error) {
      console.warn('⚠️  Failed batched player_match_stats upsert:', error.message);
      return {
        success: false,
        updated: 0,
        total: rows.length,
        failures: rows.map(r => ({ playerId: r.player_id, error: error.message })),
        error: `Database error: ${error.message}`
      };
    }

    return {
      success: true,
      updated: rows.length,
      total: rows.length,
      failures: []
    };

  } catch (error) {
    console.error('❌ Exception while updating player match stats:', error);
    return {
      success: false,
      error: `Unexpected error: ${error.message}`
    };
  }
}
