import { supabase } from '../lib/supabase';

/**
 * Fetch all player rankings and the configured level count for a team.
 *
 * Players with no row are implicitly at level 2, rank_order 0.
 *
 * @param {string} teamId
 * @returns {{ rankings: Array<{player_id: string, level: number, rank_order: number}>, levelCount: number } | null}
 */
export async function getPlayerRankings(teamId) {
  if (!teamId) return null;

  try {
    const [rankingsResult, teamResult] = await Promise.all([
      supabase
        .from('player_ranking')
        .select('player_id, level, rank_order')
        .eq('team_id', teamId)
        .order('level', { ascending: false })
        .order('rank_order', { ascending: true }),
      supabase
        .from('team')
        .select('ranking_level_count')
        .eq('id', teamId)
        .single(),
    ]);

    if (rankingsResult.error) {
      console.error('Failed to fetch player rankings:', rankingsResult.error);
      return null;
    }

    if (teamResult.error) {
      console.error('Failed to fetch team ranking level count:', teamResult.error);
      return null;
    }

    return {
      rankings: rankingsResult.data || [],
      levelCount: teamResult.data?.ranking_level_count ?? 3,
    };
  } catch (error) {
    console.error('Unexpected error fetching player rankings:', error);
    return null;
  }
}

/**
 * Batch upsert player ranking rows for a team.
 * Each row must include player_id, level, and rank_order.
 *
 * @param {string} teamId
 * @param {Array<{player_id: string, level: number, rank_order: number}>} rankingRows
 * @returns {boolean} success
 */
export async function upsertPlayerRankings(teamId, rankingRows) {
  if (!teamId || !rankingRows?.length) return true;

  try {
    const rows = rankingRows.map((r) => ({
      team_id: teamId,
      player_id: r.player_id,
      level: r.level,
      rank_order: r.rank_order,
    }));

    const { error } = await supabase
      .from('player_ranking')
      .upsert(rows, { onConflict: 'team_id,player_id' });

    if (error) {
      console.error('Failed to upsert player rankings:', error);
      return false;
    }

    return true;
  } catch (error) {
    console.error('Unexpected error upserting player rankings:', error);
    return false;
  }
}

/**
 * Update the number of ranking level groups for a team.
 *
 * @param {string} teamId
 * @param {number} levelCount
 * @returns {boolean} success
 */
export async function updateLevelCount(teamId, levelCount) {
  if (!teamId || levelCount < 1) return false;

  try {
    const { error } = await supabase
      .from('team')
      .update({ ranking_level_count: levelCount })
      .eq('id', teamId);

    if (error) {
      console.error('Failed to update ranking level count:', error);
      return false;
    }

    return true;
  } catch (error) {
    console.error('Unexpected error updating ranking level count:', error);
    return false;
  }
}
