import { useCallback } from 'react';
import { useTranslation } from 'react-i18next';
import { useTeam } from '../contexts/TeamContext';
import { useToast } from '../contexts/ToastContext';

// Wraps demo-team seeding so every entry point shows the same success/error banner.
export function useDemoTeamActions() {
  const { t } = useTranslation('team');
  const { acceptDemoPrompt, seedAndSwitchDemoTeam } = useTeam();
  const { showSuccess, showWarning } = useToast();

  const notify = useCallback((result) => {
    if (result?.success && result.target) {
      showSuccess(t('demo.generate.success'));
    } else {
      showWarning(t('demo.generate.error'));
    }
    return result;
  }, [t, showSuccess, showWarning]);

  const acceptDemoTeam = useCallback(async () => {
    try {
      return notify(await acceptDemoPrompt());
    } catch {
      notify(undefined);
    }
  }, [acceptDemoPrompt, notify]);

  const generateDemoTeam = useCallback(async () => {
    try {
      return notify(await seedAndSwitchDemoTeam());
    } catch {
      notify(undefined);
    }
  }, [seedAndSwitchDemoTeam, notify]);

  return { acceptDemoTeam, generateDemoTeam };
}
