import React, { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { Button } from '../shared/UI';
import { LoadingSpinner } from '../shared/LoadingSpinner';
import { Alert } from '../shared/Alert';
import { ModalShell } from '../shared/ModalShell';
import { Play, Trash2, Calendar, Users, Clock, Target, Plus, User } from 'lucide-react';

/**
 * Modal component for handling pending match resume actions
 * Shows when user signs in and has pending match configurations
 * Supports both single and multiple pending matches
 */
export function PendingMatchResumeModal({
  isOpen,
  onClose,
  onResume,
  onDiscard,
  pendingMatches = [], // Now expects array instead of single match
  isLoading = false,
  error = ''
}) {
  const { t } = useTranslation(['modals', 'configuration']);
  const [deletingMatchId, setDeletingMatchId] = useState(null);
  const [resumingMatchId, setResumingMatchId] = useState(null);


  if (!isOpen) return null;

  const handleResume = async (matchId) => {
    if (isLoading || resumingMatchId) return;

    setResumingMatchId(matchId);
    try {
      await onResume(matchId);
    } finally {
      setResumingMatchId(null);
    }
  };

  const handleDelete = async (matchId) => {
    if (isLoading || deletingMatchId) return;

    setDeletingMatchId(matchId);
    try {
      await onDiscard(matchId);
    } finally {
      setDeletingMatchId(null);
    }
  };

  const handleClose = () => {
    if (isLoading || deletingMatchId || resumingMatchId) return;
    onClose();
  };

  // Format creation date
  const formatMatchDate = (dateString) => {
    const date = new Date(dateString);
    const dateStr = date.toLocaleDateString();
    const timeStr = date.toLocaleTimeString([], {
      hour: '2-digit',
      minute: '2-digit'
    });
    return t('pendingMatchResume.dateAtTime', { date: dateStr, time: timeStr });
  };

  return (
    <ModalShell
      title={t('pendingMatchResume.title')}
      subtitle={pendingMatches.length === 0
        ? t('pendingMatchResume.noMatchesFound')
        : t('pendingMatchResume.matchesFound', { count: pendingMatches.length })
      }
      icon={Clock}
      iconColor="blue"
      onClose={handleClose}
      maxWidth="lg"
      className="max-h-[90vh] flex flex-col"
    >
        {/* Content */}
        <div className="flex-1 overflow-hidden flex flex-col -mb-6 -mx-6">
          {/* Error Display */}
          {error && (
            <Alert variant="error" className="mx-6 mt-6">{error}</Alert>
          )}

          {/* Empty State */}
          {pendingMatches.length === 0 && !error && (
            <div className="flex-1 flex flex-col items-center justify-center p-8 text-center">
              <div className="w-16 h-16 bg-slate-700 rounded-full flex items-center justify-center mb-4">
                <Clock className="w-8 h-8 text-slate-400" />
              </div>
              <h3 className="text-lg font-medium text-slate-300 mb-2">{t('pendingMatchResume.noPendingMatches')}</h3>
              <p className="text-sm text-slate-400 mb-6 max-w-sm">
                {t('pendingMatchResume.noPendingDescription')}
              </p>
              <Button
                onClick={handleClose}
                variant="accent"
                Icon={Plus}
                disabled={isLoading}
              >
                {t('pendingMatchResume.continueToConfigureNew')}
              </Button>
            </div>
          )}

          {/* Match List */}
          {pendingMatches.length > 0 && (
            <div className="flex-1 overflow-y-auto p-6 space-y-4">
              {pendingMatches.map((match) => {
                const { initial_config, opponent, created_at, id, creatorName, created_by_profile, state } = match;
                const matchConfig = initial_config?.matchConfig || {};
                const teamConfig = initial_config?.teamConfig || {};
                const createdByName = creatorName || created_by_profile?.name || null;

                // Extract key details for display
                const opponentName = opponent || matchConfig.opponentTeam || t('pendingMatchResume.unknownOpponent');
                const matchType = matchConfig.matchType || 'match';
                const periods = matchConfig.periods || 3;
                const duration = matchConfig.periodDurationMinutes || 15;
                const squadSize = teamConfig.squadSize || initial_config?.squadSelection?.length || 0;
                const formation = teamConfig.formation || t('pendingMatchResume.unknownFormation');

                // State badge — distinguishes a "planned for today" entry
                // (fully pre-staged) from a "pending setup" entry (partial config).
                const isPlannedForToday = state === 'planned';
                const stateBadgeLabel = isPlannedForToday
                  ? t('pendingMatchResume.stateBadgePlannedToday')
                  : t('pendingMatchResume.stateBadgePending');
                const stateBadgeClass = isPlannedForToday
                  ? 'bg-sky-900/60 text-sky-300 border border-sky-700'
                  : 'bg-amber-900/60 text-amber-300 border border-amber-700';

                return (
                  <div
                    key={id}
                    data-testid={`pending-match-card-${id}`}
                    className="bg-slate-700 rounded-lg border border-slate-600 p-4 hover:bg-slate-650 transition-colors"
                  >
                    {/* Match Header */}
                    <div className="flex items-center justify-between mb-3">
                      <div className="flex flex-col space-y-1">
                        <h3 className="text-base font-medium text-slate-200 flex items-center space-x-2">
                          <Target className="w-4 h-4 text-slate-400" />
                          <span>{t('pendingMatchResume.vsOpponent', { opponent: opponentName })}</span>
                        </h3>
                        <span
                          data-testid={`match-state-badge-${id}`}
                          className={`inline-block self-start px-2 py-0.5 rounded text-xs font-medium ${stateBadgeClass}`}
                        >
                          {stateBadgeLabel}
                        </span>
                      </div>
                      <div className="flex flex-col items-end space-y-1 text-xs text-slate-400">
                        <div className="flex items-center space-x-1">
                          <Calendar className="w-3 h-3" />
                          <span>{formatMatchDate(created_at)}</span>
                        </div>
                        {createdByName && (
                          <div className="flex items-center space-x-1">
                            <User className="w-3 h-3" />
                            <span>{t('pendingMatchResume.createdBy', { name: createdByName })}</span>
                          </div>
                        )}
                      </div>
                    </div>

                    {/* Match Details */}
                    <div className="bg-slate-600 rounded-lg p-3 mb-4 space-y-2 text-sm">
                      <div className="flex items-center justify-between">
                        <span className="text-slate-400">{t('pendingMatchResume.typeLabel')}</span>
                        <span className="font-medium text-slate-200">{t(`configuration:matchTypes.${matchType}.label`, matchType)}</span>
                      </div>

                      <div className="flex items-center justify-between">
                        <span className="text-slate-400">{t('pendingMatchResume.formatLabel')}</span>
                        <span className="font-medium text-slate-200">
                          {t('pendingMatchResume.periodsFormat', { periods, duration })}
                        </span>
                      </div>

                      <div className="flex items-center justify-between">
                        <span className="text-slate-400">{t('pendingMatchResume.squadLabel')}</span>
                        <div className="flex items-center space-x-1">
                          <Users className="w-4 h-4 text-slate-400" />
                          <span className="font-medium text-slate-200">
                            {t('pendingMatchResume.squadInfo', { size: squadSize, formation })}
                          </span>
                        </div>
                      </div>
                    </div>

                    {/* Action Buttons */}
                    <div className="flex space-x-2">
                      <Button
                        onClick={() => handleResume(id)}
                        variant="accent"
                        size="sm"
                        className="flex-1 bg-emerald-600 hover:bg-emerald-700"
                        disabled={isLoading || deletingMatchId || resumingMatchId}
                        Icon={resumingMatchId === id ? undefined : Play}
                      >
                        {resumingMatchId === id ? t('pendingMatchResume.resuming') : t('pendingMatchResume.resumeSetup')}
                      </Button>

                      <Button
                        onClick={() => handleDelete(id)}
                        variant="danger"
                        size="sm"
                        disabled={isLoading || deletingMatchId || resumingMatchId}
                        Icon={deletingMatchId === id ? undefined : Trash2}
                      >
                        {deletingMatchId === id ? t('pendingMatchResume.deleting') : t('pendingMatchResume.delete')}
                      </Button>
                    </div>
                  </div>
                );
              })}
            </div>
          )}

          {/* Bottom Actions */}
          {pendingMatches.length > 0 && (
            <div className="border-t border-slate-600 p-6 flex-shrink-0">
              <div className="flex space-x-3">
                <Button
                  onClick={handleClose}
                  variant="accent"
                  className="flex-1"
                  disabled={isLoading || deletingMatchId || resumingMatchId}
                  Icon={Plus}
                >
                  {t('pendingMatchResume.configureNewMatch')}
                </Button>

                <Button
                  onClick={handleClose}
                  variant="secondary"
                  className="px-6"
                  disabled={isLoading || deletingMatchId || resumingMatchId}
                >
                  {t('pendingMatchResume.cancel')}
                </Button>
              </div>

              {/* Info Tip */}
              <div className="mt-4 p-2 bg-slate-700/50 rounded-lg">
                <p className="text-xs text-slate-400 text-center">
                  <strong>{t('pendingMatchResume.tip')}</strong>
                </p>
              </div>
            </div>
          )}
        </div>

        {/* Loading State Overlay */}
        {isLoading && (
          <div className="absolute inset-0 bg-slate-800 bg-opacity-75 flex items-center justify-center">
            <LoadingSpinner size="md" message={t('pendingMatchResume.processing')} />
          </div>
        )}
    </ModalShell>
  );
}

export default PendingMatchResumeModal;
