export const STATS_TABS = {
  TEAM: 'team',
  PLAYER: 'player',
  ATTENDANCE: 'attendance',
  HISTORY: 'history'
};

export const STATISTICS_BASE_PATH = '/stats';

const TAB_TO_SLUG = {
  [STATS_TABS.TEAM]: 'team',
  [STATS_TABS.PLAYER]: 'players',
  [STATS_TABS.ATTENDANCE]: 'attendance',
  [STATS_TABS.HISTORY]: 'matches'
};

const SLUG_TO_TAB = {
  team: STATS_TABS.TEAM,
  players: STATS_TABS.PLAYER,
  player: STATS_TABS.PLAYER,
  attendance: STATS_TABS.ATTENDANCE,
  matches: STATS_TABS.HISTORY,
  history: STATS_TABS.HISTORY
};

const STATISTICS_TAB_VALUES = new Set(Object.values(STATS_TABS));

export const isValidStatisticsTab = (tab) => STATISTICS_TAB_VALUES.has(tab);

export const normalizeStatisticsPath = (path) => {
  const basePath = typeof path === 'string' ? path.split(/[?#]/, 1)[0] : '';
  return basePath.replace(/\/+$/, '') || '/';
};

export const isStatisticsPath = (path) => {
  const normalizedPath = normalizeStatisticsPath(path);

  return (
    normalizedPath === STATISTICS_BASE_PATH ||
    /^\/stats\/[^/]+$/i.test(normalizedPath)
  );
};

export const getStatisticsTabFromPath = (path) => {
  const normalizedPath = normalizeStatisticsPath(path);

  if (!normalizedPath.startsWith(`${STATISTICS_BASE_PATH}/`)) {
    return null;
  }

  const slug = normalizedPath.slice(STATISTICS_BASE_PATH.length + 1).toLowerCase();
  return SLUG_TO_TAB[slug] || null;
};

export const getStatisticsPath = (tab = STATS_TABS.TEAM) => {
  const safeTab = isValidStatisticsTab(tab) ? tab : STATS_TABS.TEAM;
  return `${STATISTICS_BASE_PATH}/${TAB_TO_SLUG[safeTab]}`;
};
