import { useState, useRef, useCallback } from 'react';
import { useTranslation } from 'react-i18next';
import { useTeam } from '../contexts/TeamContext';
import { useToast } from '../contexts/ToastContext';

// Shared switch-or-stay policy for both invite flows: switches the active team
// behind a double-submit guard, exposing `confirming` for UI and toasting on failure.
export function useTeamSwitchAction() {
  const { t } = useTranslation('team');
  const { showWarning } = useToast();
  const { switchCurrentTeam } = useTeam();
  const [confirming, setConfirming] = useState(false);
  const switchingRef = useRef(false);

  // Runs onSuccess only after the switch resolves; no-ops if one is already in flight.
  const runSwitch = useCallback(async (teamId, onSuccess) => {
    if (switchingRef.current) return;
    switchingRef.current = true;
    setConfirming(true);
    try {
      const result = await switchCurrentTeam(teamId);
      if (result?.blocked) {
        showWarning(t('teamSelection.matchRunningWarning'));
        return; // finally still resets switchingRef/confirming
      }
      onSuccess?.();
    } catch (e) {
      console.error('Error switching team:', e);
      showWarning(t('teamSelection.error'));
    } finally {
      switchingRef.current = false;
      setConfirming(false);
    }
  }, [switchCurrentTeam, showWarning, t]);

  return { confirming, runSwitch };
}
