import { ALL_FIXED_ROLE_GROUP_OPTIONS } from '../constants/teamConfiguration';
import { DEFAULT_MATCH_DIFFICULTY } from '../constants/matchDifficulties';

// Team preference keys
export const PREFERENCE_KEYS = {
  MATCH_FORMAT: 'matchFormat',
  FORMATION: 'formation',
  PERIOD_LENGTH: 'periodLength',
  NUM_PERIODS: 'numPeriods',
  SUBSTITUTION_LOGIC: 'substitutionLogic',
  FIXED_ROLE_GROUP: 'fixedRoleGroup',
  ALTERNATE_ROLES: 'alternateRoles',
  TRACK_GOAL_SCORER: 'trackGoalScorer',
  TRACK_ASSISTS: 'trackAssists',
  FAIR_PLAY_AWARD: 'fairPlayAward',
  TEAM_CAPTAIN: 'teamCaptain',
  LOAN_MATCH_WEIGHT: 'loanMatchWeight',
  USE_MATCH_WEIGHTS: 'useMatchWeights',
  SHOW_LIVE_DEFICIT: 'showLiveDeficit',
  MATCH_DIFFICULTY: 'matchDifficulty',
};

// Categories for grouping
export const PREFERENCE_CATEGORIES = {
  MATCH: 'match',
  TIME: 'time',
  SUBSTITUTION: 'substitution',
  FEATURES: 'features',
  STATISTICS: 'statistics',
};

const DEFAULT_LOAN_MATCH_WEIGHT = 0.5;

// Fair Play Award options
export const FAIR_PLAY_AWARD_OPTIONS = {
  NONE: 'none',
  LEAGUE_ONLY: 'league_only',
  COMPETITIVE: 'competitive',  // league, cup, tournament
  ALL_GAMES: 'all_games'
};

// Default values
export const DEFAULT_PREFERENCES = {
  [PREFERENCE_KEYS.MATCH_FORMAT]: '5v5',
  [PREFERENCE_KEYS.FORMATION]: '2-2',
  [PREFERENCE_KEYS.PERIOD_LENGTH]: 20,
  [PREFERENCE_KEYS.NUM_PERIODS]: 2,
  [PREFERENCE_KEYS.SUBSTITUTION_LOGIC]: 'rotate_roles',
  [PREFERENCE_KEYS.FIXED_ROLE_GROUP]: 'defender',
  [PREFERENCE_KEYS.ALTERNATE_ROLES]: true,
  [PREFERENCE_KEYS.TRACK_GOAL_SCORER]: true,
  [PREFERENCE_KEYS.TRACK_ASSISTS]: false,
  [PREFERENCE_KEYS.FAIR_PLAY_AWARD]: 'none',
  [PREFERENCE_KEYS.TEAM_CAPTAIN]: 'none',
  [PREFERENCE_KEYS.LOAN_MATCH_WEIGHT]: 0.5,
  [PREFERENCE_KEYS.USE_MATCH_WEIGHTS]: true,
  [PREFERENCE_KEYS.SHOW_LIVE_DEFICIT]: false,
  [PREFERENCE_KEYS.MATCH_DIFFICULTY]: DEFAULT_MATCH_DIFFICULTY,
};

// Value converters
export const parsePreferenceValue = (key, value) => {
  switch (key) {
    case PREFERENCE_KEYS.PERIOD_LENGTH:
    case PREFERENCE_KEYS.NUM_PERIODS:
      return parseInt(value, 10);
    case PREFERENCE_KEYS.TRACK_GOAL_SCORER:
    case PREFERENCE_KEYS.TRACK_ASSISTS:
    case PREFERENCE_KEYS.ALTERNATE_ROLES:
    case PREFERENCE_KEYS.USE_MATCH_WEIGHTS:
    case PREFERENCE_KEYS.SHOW_LIVE_DEFICIT:
      return value === 'true';
    case PREFERENCE_KEYS.LOAN_MATCH_WEIGHT:
      return Number.isNaN(parseFloat(value)) ? DEFAULT_LOAN_MATCH_WEIGHT : parseFloat(value);
    case PREFERENCE_KEYS.SUBSTITUTION_LOGIC:
      // Migrate legacy values
      if (value === 'same_role') return 'same_role_match';
      if (value === 'equal_time') return 'rotate_roles';
      return value;
    case PREFERENCE_KEYS.FIXED_ROLE_GROUP:
      if (ALL_FIXED_ROLE_GROUP_OPTIONS.includes(value)) {
        return value;
      }
      return DEFAULT_PREFERENCES[PREFERENCE_KEYS.FIXED_ROLE_GROUP];
    default:
      return value;
  }
};

export const serializePreferenceValue = (value) => {
  if (typeof value === 'boolean') return value ? 'true' : 'false';
  if (typeof value === 'number') return value.toString();
  return value;
};
