/**
 * Utility functions for handling team invitations via URL parameters
 */

import { createPersistenceManager } from './persistenceManager';
import { STORAGE_KEYS } from '../constants/storageKeys';

// Create persistence manager for pending invitations
const invitationPersistence = createPersistenceManager(STORAGE_KEYS.PENDING_INVITATION, { invitation: null });

// Flag persisted across an auth round-trip (incl. OAuth redirect) so we can show
// a "no invitation found" notice if the authenticated email matches no invitation.
const inviteGatewayPersistence = createPersistenceManager(STORAGE_KEYS.INVITE_GATEWAY_PENDING, { pending: false });

/**
 * Detect invitation parameters in the current URL
 * @returns {Object} Object containing invitation detection results
 */
export const detectInvitationParams = () => {
  if (typeof window === 'undefined') return { hasInvitation: false };

  // Invitations are carried entirely in query parameters of our own gateway link
  // (sent via Resend) — there is no Supabase magic-link token in the URL.
  const urlParams = new URLSearchParams(window.location.search);
  const invitation = urlParams.get('invitation');
  const teamId = urlParams.get('team');
  const role = urlParams.get('role');
  const invitationId = urlParams.get('invitation_id');
  // Display-only names carried in the link so we can show them without a DB read.
  const teamName = urlParams.get('team_name');
  const clubName = urlParams.get('club_name');

  const hasInvitation = !!(invitation === 'true' && teamId && role);

  return {
    hasInvitation,
    teamId,
    role,
    invitationId,
    teamName,
    clubName,
    isCustomInvitation: hasInvitation,
    params: {
      invitation,
      teamId,
      role,
      invitationId,
      teamName,
      clubName
    }
  };
};

/**
 * Clear invitation parameters from the URL
 * This helps clean up the URL after processing the invitation
 */
export const clearInvitationParamsFromUrl = () => {
  if (typeof window === 'undefined') return;

  const url = new URL(window.location);
  const params = url.searchParams;
  
  // Remove invitation-related query parameters
  params.delete('invitation');
  params.delete('team');
  params.delete('role');
  params.delete('invitation_id');
  params.delete('team_name');
  params.delete('club_name');
  
  const newUrl = params.toString() ? `${url.pathname}?${params.toString()}` : url.pathname;
  window.history.replaceState({}, '', newUrl);
};

/**
 * Check if the current user is in an invitation acceptance flow
 * @param {Object} user - Current authenticated user
 * @param {Object} invitationParams - Invitation parameters from URL
 * @returns {boolean} True if user should be guided through invitation acceptance
 */
export const shouldProcessInvitation = (user, invitationParams) => {
  // Must have valid invitation parameters and an authenticated user
  if (!invitationParams.hasInvitation || !user) {
    return false;
  }

  // We should process the invitation if we have full team context (incl. id)
  return !!(invitationParams.teamId && invitationParams.role && invitationParams.invitationId);
};

/**
 * Get user-friendly invitation status for display
 * @param {Object} user - Current authenticated user
 * @param {Object} invitationParams - Invitation parameters from URL
 * @returns {Object} Status information for UI
 */
export const getInvitationStatus = (user, invitationParams) => {
  if (!invitationParams.hasInvitation) {
    return { type: 'none' };
  }

  // Unauthenticated visitor on an invite link → show the join gateway.
  if (!user) {
    return {
      type: 'sign_in_required',
      messageKey: 'auth:invitation.statusMessages.signInRequired'
    };
  }

  if (shouldProcessInvitation(user, invitationParams)) {
    return {
      type: 'ready_to_process',
      messageKey: 'auth:invitation.statusMessages.processing'
    };
  }

  return { type: 'unknown' };
};

/**
 * Get invitation context for display purposes
 * @param {Object} invitationParams - Invitation parameters from URL
 * @returns {Object} Formatted invitation context
 */
export const getInvitationContext = (invitationParams) => {
  if (!invitationParams.hasInvitation) {
    return null;
  }
  
  return {
    teamId: invitationParams.teamId,
    role: invitationParams.role,
    invitationId: invitationParams.invitationId,
    teamName: invitationParams.teamName,
    clubName: invitationParams.clubName,
    displayRole: formatRoleForDisplay(invitationParams.role)
  };
};

/**
 * Format role string for display
 * @param {string} role - Raw role string
 * @returns {string} Formatted role string
 */
const formatRoleForDisplay = (role) => {
  switch (role?.toLowerCase()) {
    case 'admin':
      return 'Administrator';
    case 'coach':
      return 'Coach';
    case 'parent':
      return 'Parent';
    case 'player':
      return 'Player';
    default:
      return role || 'Member';
  }
};

/**
 * Store pending invitation details for processing after sign-in
 * @param {Object} invitationDetails - Invitation details to store
 */
export const storePendingInvitation = (invitationDetails) => {
  if (typeof window === 'undefined') return;

  invitationPersistence.saveState({ invitation: invitationDetails });
};

/**
 * Retrieve and clear pending invitation details
 * @returns {Object|null} Stored invitation details or null
 */
export const retrievePendingInvitation = () => {
  if (typeof window === 'undefined') return null;

  const stored = invitationPersistence.loadState();
  if (stored.invitation) {
    const invitation = stored.invitation;
    invitationPersistence.clearState(); // Clear after retrieval
    return invitation;
  }

  return null;
};

/**
 * Check if there's a pending invitation waiting to be processed
 * @returns {boolean} True if pending invitation exists
 */
export const hasPendingInvitation = () => {
  if (typeof window === 'undefined') return false;

  return invitationPersistence.hasStoredState();
};

/**
 * Mark that the visitor has started authenticating from the invitation gateway.
 * Survives an OAuth redirect so we can give feedback once they return.
 */
export const markInviteGatewayPending = () => {
  if (typeof window === 'undefined') return;
  inviteGatewayPersistence.saveState({ pending: true });
};

/**
 * Consume the invitation-gateway flag (returns true once, then clears it).
 * @returns {boolean} True if the visitor arrived via the invitation gateway
 */
export const consumeInviteGatewayPending = () => {
  if (typeof window === 'undefined') return false;
  const stored = inviteGatewayPersistence.loadState();
  if (stored.pending) {
    inviteGatewayPersistence.clearState();
    return true;
  }
  return false;
};

/**
 * Clear the invitation-gateway flag without consuming it as a signal.
 * Used when an auth attempt fails before any redirect, so a later unrelated
 * sign-in doesn't wrongly trigger the "no invitation found" notice.
 */
export const clearInviteGatewayPending = () => {
  if (typeof window === 'undefined') return;
  inviteGatewayPersistence.clearState();
};
