import React, { useCallback, useEffect, useLayoutEffect, useRef } from 'react';
import PropTypes from 'prop-types';

const VIDEO_SRC = `${process.env.PUBLIC_URL || ''}/media/SpinningWizard.mp4`;
// If playback never even begins (autoplay silently blocked), don't trap the user.
// Independent of the auth timeout in App.js — coincidentally the same value.
const STARTUP_GRACE_MS = 8000;
// Backstop for a missing `ended` event, anchored to actual playback start and
// sized to the real clip duration plus headroom so it never truncates the video.
const END_BACKSTOP_BUFFER_MS = 1500;
const FALLBACK_DURATION_MS = 10000;

// Full-screen native-only intro splash. Plays a muted 10s clip, then dismisses
// via onComplete on end/error/autoplay-failure — independent of data loading.
export function NativeIntroVideo({ onComplete, onPlaying }) {
  const videoRef = useRef(null);
  const doneRef = useRef(false);
  const startedRef = useRef(false);
  const startupTimerRef = useRef(null);
  const endTimerRef = useRef(null);
  const onCompleteRef = useRef(onComplete);
  const onPlayingRef = useRef(onPlaying);
  // Keep the latest callbacks in refs post-commit (concurrent-mode safe) so the
  // mount effect never needs them as deps.
  useLayoutEffect(() => {
    onCompleteRef.current = onComplete;
    onPlayingRef.current = onPlaying;
  });

  // Stable — only reads refs, so it never needs to re-run the mount effect.
  const finishOnce = useCallback(() => {
    if (doneRef.current) return;
    doneRef.current = true;
    clearTimeout(startupTimerRef.current);
    clearTimeout(endTimerRef.current);
    onCompleteRef.current?.();
  }, []);

  useEffect(() => {
    let unmounted = false;
    // Guards the uncancellable play() rejection handler from firing post-unmount.
    const safeFinish = () => { if (!unmounted) finishOnce(); };

    // Give up only if the clip never starts; the real dismissal is `onEnded`.
    startupTimerRef.current = setTimeout(() => {
      if (!startedRef.current) safeFinish();
    }, STARTUP_GRACE_MS);

    const play = videoRef.current?.play?.();
    if (play && typeof play.then === 'function') {
      play.then(null, safeFinish); // dismiss if autoplay is blocked
    }

    return () => {
      unmounted = true;
      clearTimeout(startupTimerRef.current);
      clearTimeout(endTimerRef.current);
    };
  }, [finishOnce]);

  const handlePlaying = useCallback(() => {
    if (startedRef.current) return;
    startedRef.current = true;
    clearTimeout(startupTimerRef.current);

    const duration = videoRef.current?.duration;
    const clipMs = Number.isFinite(duration) && duration > 0
      ? duration * 1000
      : FALLBACK_DURATION_MS;
    endTimerRef.current = setTimeout(finishOnce, clipMs + END_BACKSTOP_BUFFER_MS);

    onPlayingRef.current?.();
  }, [finishOnce]);

  return (
    <div
      className="fixed inset-0 z-[100] bg-slate-900"
      aria-hidden="true"
      data-testid="native-intro-video"
    >
      <video
        ref={videoRef}
        className="w-full h-full object-cover"
        src={VIDEO_SRC}
        autoPlay
        muted
        playsInline
        preload="auto"
        onPlaying={handlePlaying}
        onEnded={finishOnce}
        onError={finishOnce}
      />
    </div>
  );
}

NativeIntroVideo.propTypes = {
  onComplete: PropTypes.func.isRequired,
  onPlaying: PropTypes.func,
};
