import React from 'react';
import PropTypes from 'prop-types';
import { useTranslation } from 'react-i18next';
import './AppleAuthButton.css';

export function AppleAuthButton({ onClick, disabled = false, mode = 'signin' }) {
  const { t } = useTranslation('auth');
  const labelKey = mode === 'signup' ? 'providers.apple.signUp'
    : mode === 'continue' ? 'providers.apple.continue'
    : 'providers.apple.signIn';
  const label = t(labelKey);

  return (
    <div className="flex justify-center">
      <button
        type="button"
        className="apple-auth-button"
        onClick={onClick}
        disabled={disabled}
        aria-label={label}
      >
        <div className="apple-auth-button-state" />
        <div className="apple-auth-button-content-wrapper">
          <div className="apple-auth-button-icon">
            <svg
              xmlns="http://www.w3.org/2000/svg"
              viewBox="0 0 17 17"
              style={{ display: 'block' }}
              aria-hidden="true"
              focusable="false"
            >
              <path
                fill="#FFFFFF"
                d="M12.152 8.967c-.018-1.79 1.464-2.652 1.532-2.694-.836-1.221-2.137-1.388-2.6-1.407-1.107-.112-2.16.652-2.722.652-.562 0-1.428-.635-2.348-.617-1.209.018-2.323.703-2.945 1.785-1.256 2.177-.321 5.401.905 7.169.6.866 1.314 1.838 2.252 1.803.904-.036 1.246-.585 2.337-.585 1.091 0 1.4.585 2.357.567.973-.018 1.589-.881 2.183-1.751.689-1.005.972-1.978.99-2.027-.022-.011-1.897-.728-1.941-2.895zm-1.79-5.328c.502-.61.84-1.453.748-2.295-.723.03-1.601.482-2.12 1.085-.464.539-.871 1.4-.762 2.222.81.062 1.633-.41 2.134-1.012z"
              />
            </svg>
          </div>
          <span className="apple-auth-button-contents">{label}</span>
        </div>
      </button>
    </div>
  );
}

AppleAuthButton.propTypes = {
  onClick: PropTypes.func.isRequired,
  disabled: PropTypes.bool,
  mode: PropTypes.oneOf(['signin', 'signup', 'continue']),
};
